# R2: repeated QQ upstream 5xx responses must not serialize every fallback provider.
# The breaker only covers the QQ search endpoint; lyric fetch/QRC endpoints retain their
# mature fallback behavior.  This is transport-neutral and never touches frontend timing.
_R2_QQ_SEARCH_BREAKER = _core_CircuitBreaker(threshold=2, open_ms=45000) if callable(_core_CircuitBreaker) else None
_R2_QQ_SEARCH_BREAKER_LOG_MONO = 0.0

def _r2_qq_search_request(http, url, *, params=None, headers=None, timeout=8):
    global _R2_QQ_SEARCH_BREAKER_LOG_MONO
    breaker = _R2_QQ_SEARCH_BREAKER
    if breaker is not None:
        breaker.require('qq-search')
    response = http.get(url, params=params, headers=headers, timeout=timeout)
    try:
        status = int(getattr(response, 'status_code', 0) or 0)
    except Exception:
        status = 0
    if status == 429 or 500 <= status <= 599:
        opened = bool(breaker.failure('qq-search')) if breaker is not None else False
        if opened:
            now = time.monotonic()
            if now - float(_R2_QQ_SEARCH_BREAKER_LOG_MONO or 0.0) >= 5.0:
                _R2_QQ_SEARCH_BREAKER_LOG_MONO = now
                try:
                    snap = breaker.snapshot('qq-search') if breaker is not None else {}
                    write_error_log('R2 QQ搜索上游熔断', detail=(
                        f'status={status} | failures={int(snap.get("failures",0))} | '
                        f'retry_after={int(snap.get("retry_after_ms",0))}ms | '
                        'fallback=other-providers-immediate'))
                except Exception:
                    pass
        response.raise_for_status()
    elif breaker is not None:
        breaker.success('qq-search')
    return response

# Optional NetEase 3.x native-log adapter. It wraps the same public
# ``cloudmusic_detector.AsyncCloudMusic`` API used by LimbusLyricSimulator, but is
# intentionally isolated in a tiny module so detector failures can never break the
# existing Bridge/UIA/GSMTC fallback chain.
NETEASE_NATIVE_IMPORT_MODE = 'module'
try:
    from limbus_netease_native import NeteaseNativeClockAdapter, NATIVE_DETECTOR_IMPORT_ERROR
except Exception as _ncm_native_import_exc:
    # H36: source/debug launchers do not always keep the script directory on sys.path.
    # The release payload already ships limbus_netease_native.py beside this file, so retry
    # that exact sibling by path before declaring the native clock unavailable. This does
    # not download/import arbitrary code and it preserves the adapter's own soft dependency
    # handling for cloudmusic_detector.
    try:
        _ncm_native_path = Path(__file__).resolve().with_name('limbus_netease_native.py')
        if not _ncm_native_path.is_file():
            raise FileNotFoundError(str(_ncm_native_path))
        _ncm_native_spec = importlib.util.spec_from_file_location('limbus_netease_native', _ncm_native_path)
        if _ncm_native_spec is None or _ncm_native_spec.loader is None:
            raise ImportError(f'cannot create module spec for {_ncm_native_path}')
        _ncm_native_module = importlib.util.module_from_spec(_ncm_native_spec)
        sys.modules['limbus_netease_native'] = _ncm_native_module
        _ncm_native_spec.loader.exec_module(_ncm_native_module)
        NeteaseNativeClockAdapter = _ncm_native_module.NeteaseNativeClockAdapter
        NATIVE_DETECTOR_IMPORT_ERROR = getattr(_ncm_native_module, 'NATIVE_DETECTOR_IMPORT_ERROR', '')
        NETEASE_NATIVE_IMPORT_MODE = 'sibling-file'
    except Exception as _ncm_native_sibling_exc:
        NeteaseNativeClockAdapter = None
        NATIVE_DETECTOR_IMPORT_ERROR = (
            f"primary={type(_ncm_native_import_exc).__name__}: {_ncm_native_import_exc}; "
            f"sibling={type(_ncm_native_sibling_exc).__name__}: {_ncm_native_sibling_exc}"
        )
        NETEASE_NATIVE_IMPORT_MODE = 'unavailable'

