def _qq_range_v2_breaker_step(misses, found, max_misses=QQ_RANGE_V2_MAX_SESSION_MISSES):
    try:
        n=max(0,int(misses or 0)); limit=max(1,int(max_misses or 1))
    except Exception:
        n=0; limit=3
    if found:
        return 0, False
    n=min(limit,n+1)
    return n, bool(n>=limit)


def _qq_text_boundary_clock_step(state, raw_bucket_ms, now_ms, source_key,
                                 phase_ms=QQ_TEXT_BOUNDARY_PHASE_PRIOR_MS):
    """Build a continuous 1x QQ clock from bracketed whole-second Text edges.

    The function deliberately does not claim to discover absolute audio latency from Text
    alone. It removes poll-arrival jitter and, most importantly, keeps one phase convention
    across ordinary playback and seek. Large/non-unit jumps reset the local edge epoch.
    """
    try:
        raw=float(raw_bucket_ms); now=float(now_ms); phase=float(phase_ms)
    except Exception:
        return None, None, False, {'valid':False,'reason':'bad-input'}
    key=str(source_key or '')
    # QQ's public Text should be exact whole seconds. Reject preview/noise values rather
    # than silently quantizing a non-clock surface into authority.
    bucket=round(raw/1000.0)*1000.0
    if abs(raw-bucket)>80.0:
        return None, None, False, {'valid':False,'reason':'not-second-bucket'}
    prev=state if isinstance(state,dict) and str(state.get('source_key') or '')==key else None
    if prev is None:
        q={'source_key':key,'bucket':bucket,'last_sample_mono':now,'last_edge_mono':None,
           'last_edge_bucket':None,'offsets':[],'anchor_offset':None,'ready':False}
        return q, None, False, {'valid':False,'reason':'seed'}
    q=dict(prev)
    last_bucket=q.get('bucket'); last_sample=q.get('last_sample_mono')
    if last_bucket is None or last_sample is None:
        q.update({'bucket':bucket,'last_sample_mono':now,'offsets':[],'anchor_offset':None,'ready':False})
        return q, None, False, {'valid':False,'reason':'reseed'}
    step=bucket-float(last_bucket)
    if abs(step)<250.0:
        q['last_sample_mono']=now
        anchor=q.get('anchor_offset'); ready=bool(q.get('ready') and anchor is not None)
        candidate=(now-float(anchor)+phase) if ready else None
        return q,candidate,ready,{'valid':False,'repeat':True,'boundary_ready':ready,
                                  'anchor_offset':anchor,'edges':len(q.get('offsets') or [])}
    bracket=max(0.0,now-float(last_sample))
    edge_mono=(float(last_sample)+now)*0.5 if 0.0<bracket<=float(QQ_TEXT_BOUNDARY_MAX_BRACKET_MS) else now
    valid_step=bool(float(QQ_PHASE_EDGE_MIN_STEP_MS)<=step<=float(QQ_PHASE_EDGE_MAX_STEP_MS))
    last_edge=q.get('last_edge_mono'); last_edge_bucket=q.get('last_edge_bucket')
    cadence_error=0.0
    if last_edge is not None and last_edge_bucket is not None:
        cadence_error=abs((edge_mono-float(last_edge))-(bucket-float(last_edge_bucket)))
    cadence_ok=bool(last_edge is None or cadence_error<=float(QQ_TEXT_BOUNDARY_MAX_CADENCE_ERROR_MS))
    q['bucket']=bucket; q['last_sample_mono']=now
    if not valid_step or bracket>float(QQ_TEXT_BOUNDARY_MAX_BRACKET_MS) or not cadence_ok:
        # Large jump = seek/preview/new epoch. Do not let the old song-position intercept
        # survive it. The caller's seek FSM remains the immediate authority.
        q.update({'last_edge_mono':None,'last_edge_bucket':None,'offsets':[],
                  'anchor_offset':None,'ready':False})
        return q,None,False,{'valid':False,'reason':'epoch-reset','step':step,
                             'bracket':bracket,'cadence_error':cadence_error}
    offset=edge_mono-bucket
    offsets=list(q.get('offsets') or [])
    offsets.append(float(offset)); offsets=offsets[-int(QQ_TEXT_BOUNDARY_WINDOW):]
    ordered=sorted(offsets); n=len(ordered)
    median=ordered[n//2] if n%2 else (ordered[n//2-1]+ordered[n//2])*0.5
    spread=max((abs(v-median) for v in ordered),default=0.0)
    ready=bool(n>=int(QQ_TEXT_BOUNDARY_MIN_EDGES) and spread<=float(QQ_TEXT_BOUNDARY_MAX_SPREAD_MS))
    q.update({'last_edge_mono':edge_mono,'last_edge_bucket':bucket,'offsets':offsets,
              'anchor_offset':float(median) if ready else None,'ready':ready})
    candidate=(now-float(median)+phase) if ready else None
    return q,candidate,ready,{'valid':True,'step':step,'bracket':bracket,
                              'cadence_error':cadence_error,'spread':spread,'edges':n,
                              'anchor_offset':float(median),'boundary_ready':ready}


def _qq_range_progress_proof_step(pending, observed_ms, now_ms, status, source_key):
    """Prove a QQ RangeValue by playing-time motion; geometry alone never grants authority."""
    try:
        obs=float(observed_ms); now=float(now_ms)
    except Exception:
        return None, False
    st=str(status or 'unknown').lower(); key=str(source_key or '')
    if not key:
        return None, False
    p=pending if isinstance(pending,dict) and pending.get('source_key') == key else None
    if st != 'playing':
        if p is None:
            p={'source_key':key,'last':obs,'last_mono':now,'first_mono':now,'count':0}
        else:
            p=dict(p); p['last']=obs; p['last_mono']=now
        return p, False
    if p is None or int(p.get('count') or 0) <= 0:
        return {'source_key':key,'last':obs,'last_mono':now,'first_mono':now,'count':1}, False
    prev_mono=p.get('last_mono'); prev_obs=p.get('last')
    dt=max(1.0, now-float(now if prev_mono is None else prev_mono))
    dp=obs-float(obs if prev_obs is None else prev_obs)
    tol=max(420.0, dt*0.72)
    min_adv=max(45.0, min(170.0, dt*0.22))
    coherent=(dp >= min_adv and abs(dp-dt) <= tol)
    if not coherent:
        return {'source_key':key,'last':obs,'last_mono':now,'first_mono':now,'count':1}, False
    q=dict(p); q['last']=obs; q['last_mono']=now; q['count']=int(q.get('count') or 1)+1
    first_mono=q.get('first_mono')
    span=max(0.0, now-float(now if first_mono is None else first_mono))
    return q, bool(q['count'] >= 3 and span >= float(QQ_RANGE_V2_MIN_PROOF_SPAN_MS))
