def _qq_initial_anchor_stream_step(pending, observed_ms, now_ms, status, source_name, source_key, confidence):
    """Prove a real QQ current-time stream before cold-start clock authority.

    QQ exposes hover preview time through the same mm:ss Text surface as its live clock.
    Repetition and duration match are therefore insufficient; the stream must move forward
    at approximately wall-clock speed while playback is actually running. This grants only
    initial clock eligibility, never seek authority.
    """
    if (
        str(status or '') != 'playing' or observed_ms is None or
        str(source_name or '') not in ('qq-time-pair-candidate', 'qq-time-pair-validated') or
        int(confidence or 0) < 108
    ):
        return None, False
    try:
        raw = float(observed_ms); now = float(now_ms); key = str(source_key or source_name or '')
        p = pending if isinstance(pending, dict) else None
        if p is not None:
            gap = max(0.0, now - float(p.get('last_mono', now)))
            last_raw = float(p.get('last_raw', raw))
            same_key = not p.get('source_key') or not key or str(p.get('source_key')) == key
            expected = last_raw + gap
            coherent = (
                same_key and 0.0 <= gap <= float(QQ_HOVER_SAFE_CLOCK_MAX_GAP_MS) and
                raw >= last_raw - 80.0 and abs(raw - expected) <= 1120.0
            )
            if not coherent:
                p = None
        if p is None:
            p = {
                'source_key': key, 'first_raw': raw, 'first_mono': now,
                'last_raw': raw, 'last_mono': now, 'samples': 1,
                'validated': str(source_name or '') == 'qq-time-pair-validated',
                'advancing_proof': False,
            }
            return p, False
        p['samples'] = int(p.get('samples', 1)) + 1
        p['validated'] = bool(p.get('validated')) or str(source_name or '') == 'qq-time-pair-validated'
        p['last_raw'] = raw; p['last_mono'] = now
        span = max(0.0, now - float(p.get('first_mono', now)))
        raw_span = raw - float(p.get('first_raw', raw))
        progressed = raw_span >= float(QQ_INITIAL_ANCHOR_MIN_PROGRESS_MS)
        pace_ok = abs(raw_span - span) <= float(QQ_INITIAL_ANCHOR_MAX_PACE_ERROR_MS)
        proven = bool(
            str(source_name or '') == 'qq-time-pair-validated' and
            int(confidence or 0) >= int(QQ_INITIAL_ANCHOR_MIN_CONFIDENCE) and
            bool(p.get('validated')) and int(p.get('samples', 0)) >= int(QQ_INITIAL_ANCHOR_MIN_SAMPLES) and
            span >= float(QQ_INITIAL_ANCHOR_MIN_SPAN_MS) and progressed and pace_ok
        )
        p['advancing_proof'] = bool(p.get('advancing_proof')) or proven
        return p, bool(p.get('advancing_proof'))
    except Exception:
        return None, False



# v1.8.9.27: if a synced player stops advancing for a long time, do not leave a
# stale subtitle pinned to the desktop forever. Defaults are deliberately conservative:
# normal pause waits 45s, a 'playing' clock that is genuinely frozen waits about half
# that, and a clamped end-of-track frame gets a shorter 15s fallback. Normal long
# instrumental gaps are unaffected because the playback position is still advancing.
