def _audio_emphasis_cursor_offsets(advances, scales, spacing=0.0):
    """Centered cursor offsets with bounded room reserved around enlarged glyphs.

    This keeps a typographic accent from simply painting over its neighbours. It changes only
    local draw positions; lyric timing, reveal order, line placement selection and history
    capacity remain untouched.
    """
    adv = [max(0.0, float(x or 0.0)) for x in list(advances or [])]
    sc = list(scales or [])
    reserves = []
    for i, cw in enumerate(adv):
        try:
            scale = max(1.0, min(float(AUDIO_EMPHASIS_ABSOLUTE_MAX_SCALE), float(sc[i]) if i < len(sc) else 1.0))
        except Exception:
            scale = 1.0
        reserves.append(min(float(AUDIO_EMPHASIS_RESERVE_MAX_PX), max(0.0, cw * (scale - 1.0) * 0.92)))
    cursor = -sum(reserves) * 0.5
    out = []
    for i, cw in enumerate(adv):
        reserve = reserves[i]
        cursor += reserve * 0.5
        out.append(cursor)
        cursor += cw + float(spacing or 0.0) + reserve * 0.5
    return out

