# WinRT 媒体同步延迟加载：同步依赖异常不应阻止主界面启动。
GlobalSystemMediaTransportControlsSessionManager = None
GSMTC_BACKEND = None
GSMTC_BACKEND_ERROR = ""

def _load_gsmtc_backend():
    global GlobalSystemMediaTransportControlsSessionManager, GSMTC_BACKEND, GSMTC_BACKEND_ERROR
    if GlobalSystemMediaTransportControlsSessionManager is not None:
        return True
    errors = []
    try:
        # PyWinRT 3.x 将 Windows SDK 命名空间拆成独立发行包。
        # Media.Control 在 request_async()/返回集合时会用到 Foundation/Collections，
        # 所以这里先显式导入，避免“导入 Media.Control 成功、线程启动后才崩”。
        import winrt.windows.foundation  # noqa: F401
        import winrt.windows.foundation.collections  # noqa: F401
        from winrt.windows.media.control import GlobalSystemMediaTransportControlsSessionManager as Manager
        GlobalSystemMediaTransportControlsSessionManager = Manager
        GSMTC_BACKEND = "winrt"
        GSMTC_BACKEND_ERROR = ""
        return True
    except Exception as exc:
        errors.append(f"winrt={type(exc).__name__}: {exc}")
    try:
        from winsdk.windows.media.control import GlobalSystemMediaTransportControlsSessionManager as Manager
        GlobalSystemMediaTransportControlsSessionManager = Manager
        GSMTC_BACKEND = "winsdk"
        GSMTC_BACKEND_ERROR = ""
        return True
    except Exception as exc:
        errors.append(f"winsdk={type(exc).__name__}: {exc}")
    GSMTC_BACKEND_ERROR = " | ".join(errors)
    return False

