LIVING_SHAKE_FRAME_MS = 16

def _advance_living_shake(states, intensity, cadence_ms, last_target_mono, last_motion_mono, now_mono=None):
    """Keep target cadence, but interpolate the old 30% response continuously."""
    if not states or int(intensity or 0) <= 0:
        return False, float(last_target_mono or 0.0), float(last_motion_mono or 0.0)
    now = float(now_mono if now_mono is not None else time.monotonic() * 1000.0)
    cadence = max(10.0, float(cadence_ms or 143))
    last_target = float(last_target_mono or now); last_motion = float(last_motion_mono or now)
    target_changed = False
    if now - last_target >= cadence:
        for st in states:
            st['target_x'] = random.randint(-int(intensity), int(intensity)); st['target_y'] = random.randint(-int(intensity), int(intensity))
        last_target = now; target_changed = True
    dt = max(0.0, min(120.0, now - last_motion)); last_motion = now
    if dt <= 0.0:
        return target_changed, last_target, last_motion
    alpha = 1.0 - math.pow(0.70, dt / cadence)
    moved = False
    for st in states:
        ox=float(st.get('x',0.0) or 0.0); oy=float(st.get('y',0.0) or 0.0)
        tx=float(st.get('target_x',0.0) or 0.0); ty=float(st.get('target_y',0.0) or 0.0)
        nx=ox+(tx-ox)*alpha; ny=oy+(ty-oy)*alpha
        moved = moved or abs(nx-ox)>0.0005 or abs(ny-oy)>0.0005
        st['x']=nx; st['y']=ny
    return bool(target_changed or moved), last_target, last_motion

# v76: raster cache is restricted to the intentionally-soft glow. Shadow/outline/fill stay vector.
# Glow is generated at 2x and scaled to logical size, reducing transformed 1x softness.
GLYPH_RASTER_CACHE_ENABLED = str(os.environ.get('LIMBUSLYRIC_GLYPH_RASTER_CACHE', '0')).strip().lower() not in {'0','false','off','no','disabled'}
_GLYPH_RASTER_CACHE = OrderedDict(); _GLYPH_RASTER_CACHE_PIXELS = 0
_GLYPH_RASTER_CACHE_MAX_PIXELS = 8_000_000; _GLYPH_RASTER_CACHE_MAX_ENTRIES = 2048
_GLYPH_RASTER_CACHE_HITS = 0; _GLYPH_RASTER_CACHE_MISSES = 0; _GLYPH_GLOW_SUPERSAMPLE = 2

def _qcolor_rgba_key(color):
    try:
        c=QColor(color); return (int(c.red()),int(c.green()),int(c.blue()),int(c.alpha()))
    except Exception:
        return (0,0,0,255)

def _soft_glow_pad(glow_size):
    """Logical padding needed by the V26 airbrush-style halo."""
    try:
        return max(0.0, float(glow_size or 0.0)) * 1.18 + 2.5
    except Exception:
        return 2.5

def _draw_soft_glow_path(painter, path, glow_color, glow_size, glow_alpha, opacity_scale=1.0):
    """Draw a soft, airbrush-like halo instead of one hard duplicate outline.

    Qt has no thread-safe public Gaussian blur for QImage workers.  All expensive lyric
    paths are already rasterized into the sprite/song atlases, so several low-alpha
    concentric strokes give a smooth falloff while keeping the worker path deterministic.
    Vector fallbacks use the exact same helper, so global and per-song DIY stay identical.
    """
    try:
        radius=max(0.0,float(glow_size or 0.0))
        alpha=max(0,min(255,int(round(float(glow_alpha or 0)*max(0.0,float(opacity_scale or 0.0))))))
        if radius<=0.0 or alpha<=0 or path is None or path.isEmpty():
            return False
        base=QColor(glow_color)
        # Outer -> inner.  No single high-alpha hard edge; the filled glyph/outline is drawn
        # afterwards and hides the centre, leaving only the feathered falloff outside.
        layers=((2.30,0.075),(1.92,0.105),(1.58,0.145),(1.28,0.185),(1.02,0.235),(0.78,0.285))
        painter.setBrush(Qt.NoBrush)
        for width_mul, alpha_mul in layers:
            c=QColor(base); c.setAlpha(max(1,min(255,int(round(alpha*alpha_mul)))))
            painter.setPen(QPen(c,max(0.75,radius*width_mul),Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            painter.drawPath(path)
        return True
    except Exception:
        return False

def _glyph_glow_raster(font, ch, glow_enabled, glow_color, glow_size, glow_alpha):
    global _GLYPH_RASTER_CACHE_PIXELS, _GLYPH_RASTER_CACHE_HITS, _GLYPH_RASTER_CACHE_MISSES
    if not GLYPH_RASTER_CACHE_ENABLED or not bool(glow_enabled) or float(glow_size or 0.0) <= 0.0:
        return None
    try:
        font=QFont(font); gc=QColor(glow_color)
        key=(font.toString(),str(ch),_qcolor_rgba_key(gc),round(float(glow_size or 0.0),3),int(glow_alpha or 0),_GLYPH_GLOW_SUPERSAMPLE)
        hit=_GLYPH_RASTER_CACHE.get(key)
        if hit is not None:
            _GLYPH_RASTER_CACHE.move_to_end(key); _GLYPH_RASTER_CACHE_HITS += 1; return hit
        _GLYPH_RASTER_CACHE_MISSES += 1
        fm=QFontMetrics(font); th=float(fm.height()); path=QPainterPath(); path.addText(0.0,th/3.0,font,str(ch)); br=QRectF(path.boundingRect())
        if path.isEmpty() or br.width()<=0.0 or br.height()<=0.0: return None
        pad=max(2.0,_soft_glow_pad(glow_size))
        left=math.floor(br.left()-pad); top=math.floor(br.top()-pad); right=math.ceil(br.right()+pad); bottom=math.ceil(br.bottom()+pad)
        lw=max(1,int(right-left+1)); lh=max(1,int(bottom-top+1)); ss=int(_GLYPH_GLOW_SUPERSAMPLE); w=lw*ss; h=lh*ss
        if w>2048 or h>2048 or w*h>1_048_576: return None
        image=QImage(w,h,QImage.Format_ARGB32_Premultiplied)
        if image.isNull(): return None
        image.fill(Qt.transparent); qp=QPainter(image); qp.setRenderHint(QPainter.Antialiasing,True); qp.scale(float(ss),float(ss)); qp.translate(-float(left),-float(top))
        _draw_soft_glow_path(qp, path, gc, glow_size, glow_alpha); qp.end()
        pixels=w*h; result=(image,float(left),float(top),float(lw),float(lh),pixels)
        _GLYPH_RASTER_CACHE[key]=result; _GLYPH_RASTER_CACHE_PIXELS += pixels; _GLYPH_RASTER_CACHE.move_to_end(key)
        while _GLYPH_RASTER_CACHE and (len(_GLYPH_RASTER_CACHE)>_GLYPH_RASTER_CACHE_MAX_ENTRIES or _GLYPH_RASTER_CACHE_PIXELS>_GLYPH_RASTER_CACHE_MAX_PIXELS):
            _,old=_GLYPH_RASTER_CACHE.popitem(last=False)
            try: _GLYPH_RASTER_CACHE_PIXELS=max(0,_GLYPH_RASTER_CACHE_PIXELS-int(old[5] or 0))
            except Exception: pass
        return result
    except Exception:
        return None

def _glyph_raster_cache_stats():
    try:
        return (
            len(_GLYPH_RASTER_CACHE), int(_GLYPH_RASTER_CACHE_PIXELS),
            int(_GLYPH_RASTER_CACHE_HITS), int(_GLYPH_RASTER_CACHE_MISSES)
        )
    except Exception:
        return (0, 0, 0, 0)

# v80 high-resolution glyph sprite cache. QPixmap is kept only for the active process and
# is LRU-bounded; it changes CPU work from "rasterize complex vector every frame" to
# "blit a cached high-DPI glyph and change only position/opacity". The cache key includes
# every visible style component so it can never reuse a stale color/effect.
_HIRES_GLYPH_SPRITE_CACHE = OrderedDict()
_HIRES_GLYPH_SPRITE_CACHE_PIXELS = 0
_HIRES_GLYPH_SPRITE_HITS = 0
_HIRES_GLYPH_SPRITE_MISSES = 0
_HIRES_GLYPH_SPRITE_PREWARMS = 0

def _hires_sprite_complex_enough(elements, char_count, font=None):
    # v98: complexity is no longer a routing decision. A pile of individually "simple"
    # glyphs can cost more than one decorative glyph, so every visible row uses cached
    # raster sprites. Path rendering survives only as a per-glyph allocation/failure fallback.
    return bool(HIRES_GLYPH_SPRITE_ENABLED and int(char_count or 0) > 0)

def _hires_glyph_sprite(font, ch, text_color, stroke_color, stroke_width,
                        outline_enabled, shadow_enabled, shadow_color,
                        glow_enabled, glow_color, glow_size, glow_alpha,
                        base_path=None, text_height=None):
    global _HIRES_GLYPH_SPRITE_CACHE_PIXELS, _HIRES_GLYPH_SPRITE_HITS, _HIRES_GLYPH_SPRITE_MISSES
    if not HIRES_GLYPH_SPRITE_ENABLED or not ch or ch.isspace():
        return None
    try:
        font = QFont(font)
        ss = int(HIRES_GLYPH_SPRITE_SUPERSAMPLE)
        key = (
            font.toString(), str(ch), _qcolor_rgba_key(text_color),
            _qcolor_rgba_key(stroke_color), round(float(stroke_width or 0.0), 3), bool(outline_enabled),
            bool(shadow_enabled), _qcolor_rgba_key(shadow_color), bool(glow_enabled),
            _qcolor_rgba_key(glow_color), round(float(glow_size or 0.0), 3), int(glow_alpha or 0), ss,
        )
        hit = _HIRES_GLYPH_SPRITE_CACHE.get(key)
        if hit is not None:
            _HIRES_GLYPH_SPRITE_CACHE.move_to_end(key)
            _HIRES_GLYPH_SPRITE_HITS += 1
            return hit
        _HIRES_GLYPH_SPRITE_MISSES += 1
        fm = QFontMetrics(font)
        th = float(text_height or fm.height())
        path = base_path
        if path is None:
            path = QPainterPath(); path.addText(0.0, th / 3.0, font, str(ch))
        if path is None or path.isEmpty():
            return None
        br = QRectF(path.boundingRect())
        outline_pad = float(stroke_width or 0.0) if bool(outline_enabled) else 0.0
        glow_pad = _soft_glow_pad(glow_size) if bool(glow_enabled) else 0.0
        shadow_pad = 3.0 if bool(shadow_enabled) else 0.0
        pad = max(3.0, outline_pad + 2.0, glow_pad + 2.0, shadow_pad + 2.0)
        left = float(math.floor(br.left() - pad))
        top = float(math.floor(br.top() - pad))
        right = float(math.ceil(br.right() + pad))
        bottom = float(math.ceil(br.bottom() + pad))
        lw = max(1, int(right - left + 1.0)); lh = max(1, int(bottom - top + 1.0))
        w = int(lw * ss); h = int(lh * ss)
        # A pathological font/glyph must never allocate an unbounded texture. Vector is
        # the safe fallback for that one glyph.
        if w > 3072 or h > 3072 or w * h > 2_500_000:
            return None
        image = QImage(w, h, QImage.Format_ARGB32_Premultiplied)
        if image.isNull():
            return None
        image.fill(Qt.transparent)
        qp = QPainter(image)
        qp.setRenderHint(QPainter.Antialiasing, True)
        qp.setRenderHint(QPainter.TextAntialiasing, True)
        qp.scale(float(ss), float(ss))
        qp.translate(-left, -top)
        if bool(glow_enabled) and float(glow_size or 0.0) > 0.0:
            gc = QColor(glow_color)
            _draw_soft_glow_path(qp, path, gc, glow_size, glow_alpha)
        if bool(shadow_enabled):
            qp.save(); qp.translate(3.0, 3.0); qp.setPen(Qt.NoPen); qp.setBrush(QColor(shadow_color)); qp.drawPath(path); qp.restore()
        if bool(outline_enabled) and float(stroke_width or 0.0) > 0.0:
            qp.setPen(QPen(QColor(stroke_color), float(stroke_width) * 2.0, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        else:
            qp.setPen(Qt.NoPen)
        qp.setBrush(QColor(text_color)); qp.drawPath(path)
        qp.end()
        pixmap = QPixmap.fromImage(image)
        if pixmap.isNull():
            return None
        pixmap.setDevicePixelRatio(float(ss))
        pixels = int(w * h)
        result = (pixmap, left, top, float(lw), float(lh), pixels)
        _HIRES_GLYPH_SPRITE_CACHE[key] = result
        _HIRES_GLYPH_SPRITE_CACHE_PIXELS += pixels
        _HIRES_GLYPH_SPRITE_CACHE.move_to_end(key)
        while _HIRES_GLYPH_SPRITE_CACHE and (
            len(_HIRES_GLYPH_SPRITE_CACHE) > HIRES_GLYPH_SPRITE_CACHE_MAX_ENTRIES or
            _HIRES_GLYPH_SPRITE_CACHE_PIXELS > HIRES_GLYPH_SPRITE_CACHE_MAX_PIXELS
        ):
            _, old = _HIRES_GLYPH_SPRITE_CACHE.popitem(last=False)
            try:
                _HIRES_GLYPH_SPRITE_CACHE_PIXELS = max(0, _HIRES_GLYPH_SPRITE_CACHE_PIXELS - int(old[5] or 0))
            except Exception:
                pass
        return result
    except Exception:
        return None

def _prime_hires_glyph_sprite_from_song_image(style_sig, ch, image, left, top, lw, lh):
    """Install one worker-rendered 2x glyph into the existing active QPixmap cache.

    QImage rendering stays on the atlas worker. QPixmap creation remains on the GUI thread,
    but v104 converts only ONE queued glyph per idle tick instead of forcing an entire new
    lyric line to rasterize many uncached glyphs inside paintEvent. Visual pixels are the
    same style/supersample as _hires_glyph_sprite().
    """
    global _HIRES_GLYPH_SPRITE_CACHE_PIXELS, _HIRES_GLYPH_SPRITE_PREWARMS
    try:
        if not style_sig or not ch or ch.isspace() or image is None or image.isNull():
            return False
        key = (
            str(style_sig[0]), str(ch), tuple(style_sig[1]), tuple(style_sig[2]),
            round(float(style_sig[3] or 0.0), 3), bool(style_sig[4]), bool(style_sig[5]),
            tuple(style_sig[6]), bool(style_sig[7]), tuple(style_sig[8]),
            round(float(style_sig[9] or 0.0), 3), int(style_sig[10] or 0), int(style_sig[11] or 2),
        )
        if key in _HIRES_GLYPH_SPRITE_CACHE:
            _HIRES_GLYPH_SPRITE_CACHE.move_to_end(key)
            return False
        pixmap = QPixmap.fromImage(image)
        if pixmap.isNull():
            return False
        ss = max(1, int(style_sig[11] or 2))
        pixmap.setDevicePixelRatio(float(ss))
        pixels = int(image.width() * image.height())
        result = (pixmap, float(left), float(top), float(lw), float(lh), pixels)
        _HIRES_GLYPH_SPRITE_CACHE[key] = result
        _HIRES_GLYPH_SPRITE_CACHE_PIXELS += pixels
        _HIRES_GLYPH_SPRITE_CACHE.move_to_end(key)
        _HIRES_GLYPH_SPRITE_PREWARMS += 1
        while _HIRES_GLYPH_SPRITE_CACHE and (
            len(_HIRES_GLYPH_SPRITE_CACHE) > HIRES_GLYPH_SPRITE_CACHE_MAX_ENTRIES or
            _HIRES_GLYPH_SPRITE_CACHE_PIXELS > HIRES_GLYPH_SPRITE_CACHE_MAX_PIXELS
        ):
            _, old = _HIRES_GLYPH_SPRITE_CACHE.popitem(last=False)
            try:
                _HIRES_GLYPH_SPRITE_CACHE_PIXELS = max(0, _HIRES_GLYPH_SPRITE_CACHE_PIXELS - int(old[5] or 0))
            except Exception:
                pass
        return True
    except Exception:
        return False

def _hires_sprite_cache_stats():
    try:
        return (len(_HIRES_GLYPH_SPRITE_CACHE), int(_HIRES_GLYPH_SPRITE_CACHE_PIXELS),
                int(_HIRES_GLYPH_SPRITE_HITS), int(_HIRES_GLYPH_SPRITE_MISSES))
    except Exception:
        return (0, 0, 0, 0)

def _clear_hires_sprite_cache():
    global _HIRES_GLYPH_SPRITE_CACHE_PIXELS
    try:
        _HIRES_GLYPH_SPRITE_CACHE.clear(); _HIRES_GLYPH_SPRITE_CACHE_PIXELS = 0
    except Exception:
        pass

# v79: do not pre-expand decorative glyph strokes into giant QPainterPaths.
# The v78 cache had a high hit rate but made each cached object much more expensive to
# rasterize. Base glyph outlines remain cached per visible row; stroke/glow use QPen at
# final device geometry so sharpness stays vector-native without retaining huge hidden paths.

def _bundled_resource_path(name):
    """Resolve a bundled/source asset without depending on the current working directory."""
    try:
        root = getattr(sys, '_MEIPASS', None) or os.path.dirname(os.path.abspath(__file__))
    except Exception:
        root = os.getcwd()
    return os.path.join(root, str(name or ''))

def _bundled_support_asset(name):
    return _bundled_resource_path(os.path.join(SUPPORT_ASSET_DIR, str(name or '')))

def _application_icon():
    try:
        path = _bundled_resource_path(APP_ICON_FILENAME)
        if os.path.isfile(path):
            icon = QIcon(path)
            if not icon.isNull():
                return icon
    except Exception:
        pass
    return QIcon()

