_CUSTOM_APPLICATION_FONT_IDS = []

def _load_custom_application_fonts():
    """Load user-imported fonts for this process only; never install them into Windows."""
    families = []
    try:
        for path in sorted(Path(CUSTOM_FONT_ROOT).iterdir()):
            if not path.is_file() or path.suffix.lower() not in ('.ttf', '.otf', '.ttc'):
                continue
            font_id = QFontDatabase.addApplicationFont(str(path))
            if font_id < 0:
                write_error_log('自定义字体加载失败', detail=str(path))
                continue
            _CUSTOM_APPLICATION_FONT_IDS.append(font_id)
            try:
                if '_h51_invalidate_font_support_cache' in globals(): _h51_invalidate_font_support_cache('custom-font-load')
            except Exception: pass
            for family in QFontDatabase.applicationFontFamilies(font_id):
                family = str(family or '').strip()
                if family and family not in families:
                    families.append(family)
        if families:
            write_error_log('自定义字体已加载', detail=f'files={len(_CUSTOM_APPLICATION_FONT_IDS)} | families={len(families)}')
    except Exception as exc:
        write_error_log('扫描自定义字体目录失败', exc, detail=CUSTOM_FONT_ROOT)
    return families

def _reload_custom_application_fonts():
    """Reload the app-private font folder after user removal without touching system fonts."""
    global _CUSTOM_APPLICATION_FONT_IDS
    old_ids = list(_CUSTOM_APPLICATION_FONT_IDS)
    _CUSTOM_APPLICATION_FONT_IDS = []
    for font_id in old_ids:
        try:
            QFontDatabase.removeApplicationFont(int(font_id))
        except Exception:
            pass
    try:
        if '_h51_invalidate_font_support_cache' in globals(): _h51_invalidate_font_support_cache('custom-font-reload')
    except Exception: pass
    return _load_custom_application_fonts()

