AUTOSTART_VALUE_NAME = "LimbusLyric"
AUTOSTART_RUN_KEY = r"Software\Microsoft\Windows\CurrentVersion\Run"

_INSTANCE_MUTEX_HANDLE = None
ERROR_ALREADY_EXISTS = 183

def _acquire_single_instance():
    """Prevent a hidden tray instance and a newly launched copy from both drawing lyrics."""
    global _INSTANCE_MUTEX_HANDLE
    if os.name != 'nt':
        return True
    try:
        kernel32 = ctypes.windll.kernel32
        kernel32.CreateMutexW.restype = ctypes.c_void_p
        handle = kernel32.CreateMutexW(
            None, False, "Local\\TPRLimbusLyric_SingleInstance_v1"
        )
        if not handle:
            return True
        err = int(kernel32.GetLastError())
        if err == ERROR_ALREADY_EXISTS:
            try:
                kernel32.CloseHandle(ctypes.c_void_p(handle))
            except Exception:
                pass
            return False
        _INSTANCE_MUTEX_HANDLE = handle
        return True
    except Exception:
        # Single-instance is a UX guard, not a reason to prevent startup.
        return True

def _legacy_config_candidates():
    candidates = []
    script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
    parent_dir = os.path.dirname(script_dir)
    direct = [
        os.path.abspath(LEGACY_CONFIG_FILE),
        os.path.join(script_dir, LEGACY_CONFIG_FILE),
    ]
    # 新旧测试包通常并排解压。额外扫描父目录下一层的 LimbusLyric* 文件夹，
    # 按修改时间优先迁移最近使用的旧配置。
    sibling_configs = []
    try:
        for name in os.listdir(parent_dir):
            if not name.lower().startswith('limbuslyric'):
                continue
            candidate = os.path.join(parent_dir, name, LEGACY_CONFIG_FILE)
            if os.path.isfile(candidate):
                sibling_configs.append(candidate)
        sibling_configs.sort(key=lambda x: os.path.getmtime(x), reverse=True)
    except Exception:
        sibling_configs = []
    for path in direct + sibling_configs:
        if path not in candidates and os.path.abspath(path) != os.path.abspath(CONFIG_FILE):
            candidates.append(path)
    return candidates

def _migrate_legacy_config_once():
    if os.path.exists(CONFIG_FILE):
        return
    for old_path in _legacy_config_candidates():
        try:
            if not os.path.isfile(old_path):
                continue
            with open(old_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            tmp = CONFIG_FILE + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            os.replace(tmp, CONFIG_FILE)
            write_error_log('配置迁移完成', detail=f'{old_path} -> {CONFIG_FILE}')
            return
        except Exception:
            continue

def _autostart_command():
    if getattr(sys, 'frozen', False):
        args = [os.path.abspath(sys.executable), '--autostart']
    else:
        script = os.path.abspath(sys.argv[0])
        py = os.path.abspath(sys.executable)
        pyw = os.path.join(os.path.dirname(py), 'pythonw.exe')
        if os.name == 'nt' and os.path.exists(pyw):
            py = pyw
        args = [py, script, '--autostart']
    return subprocess.list2cmdline(args)

def is_autostart_enabled():
    if os.name != 'nt':
        return False
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, AUTOSTART_RUN_KEY, 0, winreg.KEY_READ) as key:
            winreg.QueryValueEx(key, AUTOSTART_VALUE_NAME)
        return True
    except Exception:
        return False

def _refresh_autostart_target_if_enabled():
    if is_autostart_enabled():
        set_autostart_enabled(True)

def set_autostart_enabled(enabled):
    if os.name != 'nt':
        return False
    try:
        import winreg
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, AUTOSTART_RUN_KEY) as key:
            if enabled:
                winreg.SetValueEx(key, AUTOSTART_VALUE_NAME, 0, winreg.REG_SZ, _autostart_command())
            else:
                try:
                    winreg.DeleteValue(key, AUTOSTART_VALUE_NAME)
                except FileNotFoundError:
                    pass
        return True
    except Exception as exc:
        write_error_log('切换开机自启动失败', exc)
        return False

