# ==================== 日志 ====================
# Production/session logging policy:
#   * every launch gets an independent session log;
#   * prefer LOCALAPPDATA\LimbusLyric\logs so upgrades/portable folders share one bounded pool;
#   * fall back to the application folder, then TEMP if LOCALAPPDATA is unavailable;
#   * keep at most five session logs and bound a long-running single session too;
#   * cleanup stays on the logging path and never participates in player/render timing.
_LOG_WRITE_LOCK = threading.RLock()
_LOG_ASYNC_QUEUE = queue.Queue(maxsize=4096)
_LOG_ASYNC_THREAD = None
_LOG_ASYNC_START_LOCK = threading.Lock()
_LOG_ASYNC_DROPPED = 0
_LOG_SESSION_LOCK = threading.RLock()
_LOG_SESSION_PATH = None
_LOG_SESSION_FINALIZED = False
_LOG_SESSION_STARTED_MONO = time.monotonic()
_LOG_RETENTION_DAYS = 0  # count/size based; keep the newest sessions regardless of age
_LOG_KEEP_RECENT = 5
_LOG_MAX_SESSIONS = 5
_LOG_MAX_TOTAL_BYTES = 64 * 1024 * 1024
_LOG_MAX_SESSION_BYTES = 12 * 1024 * 1024
_LOG_SESSION_TRIM_TO_BYTES = 8 * 1024 * 1024


def _log_directory_candidates():
    candidates = []
    local = str(os.environ.get('LOCALAPPDATA') or '').strip()
    if local:
        candidates.append(os.path.join(local, 'LimbusLyric', 'logs'))
    try:
        if bool(getattr(sys, 'frozen', False)):
            app_dir = os.path.dirname(os.path.abspath(sys.executable))
        else:
            app_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
        if app_dir:
            candidates.append(os.path.join(app_dir, 'logs'))
    except Exception:
        pass
    temp = str(os.environ.get('TEMP') or os.environ.get('TMP') or '').strip()
    if temp:
        candidates.append(os.path.join(temp, 'LimbusLyric', 'logs'))
    out = []
    seen = set()
    for path in candidates:
        key = os.path.normcase(os.path.abspath(path))
        if key not in seen:
            seen.add(key); out.append(path)
    return out


def _choose_log_directory():
    for path in _log_directory_candidates():
        try:
            os.makedirs(path, exist_ok=True)
            probe = os.path.join(path, '.limbus_write_probe')
            with open(probe, 'w', encoding='ascii') as f:
                f.write('ok')
            try: os.remove(probe)
            except Exception: pass
            return path
        except Exception:
            continue
    return os.getcwd()


def _cleanup_old_log_sessions(log_dir, now=None):
    """Prune only *previous* sessions. Recent evidence always wins over disk tidiness."""
    try:
        now = float(time.time() if now is None else now)
        rows = []
        for name in os.listdir(log_dir):
            if not (name.startswith('LimbusLyric_') and name.lower().endswith('.log')):
                continue
            path = os.path.join(log_dir, name)
            try:
                st = os.stat(path)
                if not os.path.isfile(path):
                    continue
                rows.append({'path': path, 'mtime': float(st.st_mtime), 'size': int(st.st_size)})
            except Exception:
                continue
        rows.sort(key=lambda r: (r['mtime'], r['path']), reverse=True)
        protected = {r['path'] for r in rows[:_LOG_KEEP_RECENT]}
        # Count-based retention is easier to reason about for support: keep the newest
        # sessions even if the user only reproduces an issue occasionally. Disk usage is
        # bounded independently by the per-session and total-size ceilings below.
        survivors = list(rows)

        # Session-count ceiling.
        survivors.sort(key=lambda r: (r['mtime'], r['path']), reverse=True)
        if len(survivors) > _LOG_MAX_SESSIONS:
            for row in survivors[_LOG_MAX_SESSIONS:]:
                if row['path'] in protected:
                    continue
                try: os.remove(row['path'])
                except Exception: pass

        # Total-size ceiling. Keep newest _LOG_KEEP_RECENT even if they alone exceed it.
        survivors = []
        for name in os.listdir(log_dir):
            if name.startswith('LimbusLyric_') and name.lower().endswith('.log'):
                path = os.path.join(log_dir, name)
                try:
                    st = os.stat(path)
                    survivors.append({'path': path, 'mtime': float(st.st_mtime), 'size': int(st.st_size)})
                except Exception:
                    pass
        survivors.sort(key=lambda r: (r['mtime'], r['path']), reverse=True)
        protected = {r['path'] for r in survivors[:_LOG_KEEP_RECENT]}
        total = sum(r['size'] for r in survivors)
        for row in reversed(survivors):
            if total <= _LOG_MAX_TOTAL_BYTES:
                break
            if row['path'] in protected:
                continue
            try:
                os.remove(row['path']); total -= row['size']
            except Exception:
                pass
    except Exception:
        pass


def _ensure_log_session():
    global _LOG_SESSION_PATH
    if _LOG_SESSION_PATH:
        return _LOG_SESSION_PATH
    with _LOG_SESSION_LOCK:
        if _LOG_SESSION_PATH:
            return _LOG_SESSION_PATH
        log_dir = _choose_log_directory()
        stamp = time.strftime('%Y%m%d-%H%M%S')
        path = os.path.join(log_dir, f'LimbusLyric_{stamp}_pid{os.getpid()}.log')
        # Collision is very unlikely, but tests/rapid relaunches should still be lossless.
        if os.path.exists(path):
            path = os.path.join(log_dir, f'LimbusLyric_{stamp}_pid{os.getpid()}_{int(time.time()*1000)%100000}.log')
        try:
            with open(path, 'a', encoding='utf-8'):
                pass
        except Exception:
            path = os.path.join(os.getcwd(), f'LimbusLyric_{stamp}_pid{os.getpid()}.log')
        _LOG_SESSION_PATH = path
        # Count the just-created current log so the on-disk pool really ends at <=5 files.
        _cleanup_old_log_sessions(os.path.dirname(os.path.abspath(path)))
        return path


def _trim_log_file_if_needed(path):
    """Bound one long-running session while preserving the recent troubleshooting tail."""
    try:
        size = int(os.path.getsize(path))
        if size <= _LOG_MAX_SESSION_BYTES:
            return
        keep = min(int(_LOG_SESSION_TRIM_TO_BYTES), size)
        with open(path, 'rb') as f:
            f.seek(max(0, size - keep))
            tail = f.read()
        if size > keep:
            nl = tail.find(b'\n')
            if nl >= 0:
                tail = tail[nl + 1:]
        marker = (f'[log-maintenance] older diagnostics trimmed; retained_recent_bytes={len(tail)}\n').encode('utf-8')
        with open(path, 'wb') as f:
            f.write(marker)
            f.write(tail)
    except Exception:
        pass


def _runtime_environment_detail(app):
    """Support-only OS/display fingerprint; no device identifiers or personal paths."""
    parts = []
    try:
        if hasattr(sys, 'getwindowsversion'):
            w = sys.getwindowsversion()
            parts.append(f'windows={w.major}.{w.minor}.{w.build}')
        else:
            parts.append(f'platform={sys.platform}')
    except Exception:
        pass
    try:
        parts.append(f'python={sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}')
        parts.append(f'frozen={int(bool(getattr(sys, "frozen", False)))}')
        parts.append(f'config_schema={globals().get("CONFIG_SCHEMA_VERSION", "?")}')
        parts.append(f'log_policy=keep{int(globals().get("_LOG_KEEP_RECENT", 0) or 0)}/session{int(globals().get("_LOG_MAX_SESSION_BYTES", 0) or 0)//(1024*1024)}MB')
    except Exception:
        pass
    try:
        screens = list(app.screens())
        parts.append(f'screens={len(screens)}')
        for idx, screen in enumerate(screens[:4]):
            geo = screen.geometry()
            parts.append(
                f'screen{idx}={geo.width()}x{geo.height()}@{float(screen.refreshRate() or 0.0):.2f}Hz/'
                f'dpi{float(screen.logicalDotsPerInch() or 0.0):.1f}/dpr{float(screen.devicePixelRatio() or 1.0):.2f}'
            )
    except Exception:
        pass
    return ' | '.join(parts)


def _write_log_records(records):
    if not records:
        return
    try:
        by_path = {}
        for path, message, trace_text in records:
            by_path.setdefault(path, []).append((message, trace_text))
        with _LOG_WRITE_LOCK:
            for path, items in by_path.items():
                os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
                _trim_log_file_if_needed(path)
                with open(path, 'a', encoding='utf-8', buffering=1) as f:
                    for message, trace_text in items:
                        f.write(message + '\n')
                        if trace_text:
                            f.write(trace_text + '\n')
    except Exception:
        pass


def _async_log_worker():
    while True:
        batch = []
        try:
            first = _LOG_ASYNC_QUEUE.get()
            if first is None:
                try: _LOG_ASYNC_QUEUE.task_done()
                except Exception: pass
                return
            batch = [first]
            for _ in range(63):
                try:
                    item = _LOG_ASYNC_QUEUE.get_nowait()
                except queue.Empty:
                    break
                if item is None:
                    try: _LOG_ASYNC_QUEUE.task_done()
                    except Exception: pass
                    break
                batch.append(item)
            _write_log_records(batch)
        except Exception:
            time.sleep(0.01)
        finally:
            for _ in batch:
                try: _LOG_ASYNC_QUEUE.task_done()
                except Exception: pass


def _ensure_async_log_thread():
    global _LOG_ASYNC_THREAD
    th = _LOG_ASYNC_THREAD
    if th is not None and th.is_alive():
        return True
    with _LOG_ASYNC_START_LOCK:
        th = _LOG_ASYNC_THREAD
        if th is not None and th.is_alive():
            return True
        try:
            th = threading.Thread(target=_async_log_worker, name='LimbusLyric-LogWriter', daemon=True)
            th.start(); _LOG_ASYNC_THREAD = th
            return True
        except Exception:
            return False


def _flush_async_log(timeout=2.0):
    deadline = time.monotonic() + max(0.1, float(timeout))
    try:
        # Queue.empty() is insufficient: the worker may already have dequeued a batch but not
        # written it yet. unfinished_tasks stays non-zero until task_done(), so normal exit can
        # never race the daemon writer and silently lose the final diagnostics.
        while int(getattr(_LOG_ASYNC_QUEUE, 'unfinished_tasks', 0) or 0) > 0 and time.monotonic() < deadline:
            time.sleep(0.01)
        with _LOG_WRITE_LOCK:
            pass
    except Exception:
        pass


def _finalize_log_session(reason='process-exit'):
    global _LOG_SESSION_FINALIZED
    with _LOG_SESSION_LOCK:
        if _LOG_SESSION_FINALIZED:
            return
        _LOG_SESSION_FINALIZED = True
        # Imported helper/child processes may register this atexit handler without ever
        # starting a LimbusLyric log session. Do not manufacture an end-only junk file.
        if not _LOG_SESSION_PATH:
            return
    try:
        _flush_async_log(2.0)
        path = _LOG_SESSION_PATH
        stamp = time.strftime('%Y-%m-%d %H:%M:%S')
        uptime_ms = int(max(0.0, time.monotonic() - float(_LOG_SESSION_STARTED_MONO)) * 1000.0)
        _write_log_records([(path, f'[{stamp}] 日志会话结束 | reason={reason} | uptime={uptime_ms}ms | async_drop={int(_LOG_ASYNC_DROPPED)}', '')])
    except Exception:
        pass


atexit.register(_finalize_log_session)


def write_error_log(context, exc=None, detail='', force_sync=False):
    global _LOG_ASYNC_DROPPED
    try:
        path = _ensure_log_session()
        stamp = time.strftime('%Y-%m-%d %H:%M:%S')
        message = f'[{stamp}] {context}'
        if detail:
            message += f' | {detail}'
        if exc is not None:
            message += f' | {type(exc).__name__}: {exc}'
        trace_text = traceback.format_exc() if exc is not None else ''
        record = (path, message, trace_text)
        if force_sync or exc is not None or not ASYNC_DIAGNOSTIC_LOG_ENABLED:
            _write_log_records([record]); return
        if _ensure_async_log_thread():
            try:
                _LOG_ASYNC_QUEUE.put_nowait(record); return
            except queue.Full:
                _LOG_ASYNC_DROPPED += 1
                return
        _write_log_records([record])
    except Exception:
        pass


def _clean_name(value):
    value = (value or "").lower().strip()
    value = re.sub(r'[\s\-–—－_·•\.\(\)（）\[\]【】]+', '', value)
    return value


def _artist_text(song):
    artists = song.get('artists') or song.get('ar') or song.get('singer') or []
    if isinstance(artists, str):
        return artists
    names = []
    for item in artists:
        if isinstance(item, dict):
            names.append(str(item.get('name') or item.get('title') or ''))
        else:
            names.append(str(item))
    return '/'.join(x for x in names if x)


def _artist_alias_keys(value):
    """Normalize a provider/user artist string into conservative alias tokens.

    This is deliberately generic: slash-separated collaborators and bracketed aliases are
    separate evidence units. It does not transliterate or fuzzy-match unrelated names.
    """
    raw = html.unescape(str(value or '')).lower().strip()
    if not raw:
        return set()
    bracket_parts = re.findall(r'[\(（\[【]([^\)）\]】]{1,80})[\)）\]】]', raw)
    base = re.sub(r'[\(（\[【][^\)）\]】]{1,80}[\)）\]】]', '/', raw)
    pieces = [base] + bracket_parts
    out = set()
    for piece in pieces:
        piece = re.sub(r'(?i)\b(?:feat(?:uring)?|ft)\.?\b', '/', piece)
        for part in re.split(r'[/／、,&，;；|+＋×]', piece):
            part = re.sub(r'^(?:cv|vocal|vocals|歌手|演唱)\s*[:：]?\s*', '', part.strip(), flags=re.I)
            key = _clean_name(part)
            if len(key) >= 2:
                out.add(key)
    whole = _clean_name(raw)
    if whole:
        out.add(whole)
    return out


def _artist_alias_match(query_artist, candidate_artist):
    if not str(query_artist or '').strip():
        return True, ''
    q = _artist_alias_keys(query_artist)
    c = _artist_alias_keys(candidate_artist)
    if not q or not c:
        return False, ''
    for qa in sorted(q, key=len, reverse=True):
        for ca in sorted(c, key=len, reverse=True):
            if qa == ca:
                return True, qa
            # Containment is useful for provider suffixes, but only for meaningful names.
            if min(len(qa), len(ca)) >= 3 and (qa in ca or ca in qa):
                return True, qa if len(qa) <= len(ca) else ca
    return False, ''


def _candidate_score(song_name, artist, candidate_song, candidate_artist):
    q_song = _clean_name(song_name)
    q_artist = _clean_name(artist)
    c_song = _clean_name(candidate_song)
    c_artist = _clean_name(candidate_artist)
    score = 0
    if q_song and c_song:
        if q_song == c_song:
            score += 100
        elif q_song in c_song or c_song in q_song:
            score += 60
    if q_artist and c_artist:
        artist_ok, artist_alias = _artist_alias_match(artist, candidate_artist) if EVIDENCE_CLOCK_ENABLED else (q_artist == c_artist or q_artist in c_artist or c_artist in q_artist, '')
        if q_artist == c_artist:
            score += 80
        elif artist_ok:
            score += 62 if artist_alias else 45
    return score


def _staggered_edge_wrap_adjust(abs_left, glyph_width, screen_width, base_y, screen_height, line_height):
    """Return (dx, dy, cycle) only after a glyph is fully beyond a horizontal edge.

    The old modulo wrap moved a glyph as soon as its baseline crossed the width, so a
    still-visible fragment could appear on the opposite side early.  This helper waits
    until the whole glyph has left the viewport, then continues it from the other edge on
    a neighboring vertical lane.  The lane shift keeps a long wrapped sentence from
    drawing directly on top of its own unwrapped tail.
    """
    try:
        left = float(abs_left)
        width = max(1.0, float(glyph_width or 1.0))
        sw = float(screen_width or 0.0)
        if sw <= 1.0:
            return 0.0, 0.0, 0
        right = left + width
        cycle = 0
        if left >= sw:
            cycle = max(1, int(math.floor(left / sw)))
        elif right <= 0.0:
            cycle = -max(1, int(math.floor(max(0.0, -right) / sw)) + 1)
        if not cycle:
            return 0.0, 0.0, 0
        sh = max(1.0, float(screen_height or 1.0))
        lane = max(float(line_height or 1.0) * 1.15, float(line_height or 1.0) + 8.0)
        lane_dir = 1.0 if float(base_y) < sh * 0.5 else -1.0
        return -float(cycle) * sw, lane_dir * abs(cycle) * lane, int(cycle)
    except Exception:
        return 0.0, 0.0, 0


def _device_space_staggered_wrap_adjust(painter, local_rect, screen_width, screen_height, line_height):
    """Perspective-aware wrap.  Decide edge exit in device/screen coordinates.

    v1.8.9.21 tested the pre-perspective x coordinate. Under a projective QTransform a
    glyph could therefore still be visibly around the middle-right of the monitor while
    its untransformed x had already crossed ``screen_width``.  We now map the glyph's
    actual local bounding box through the painter transform first.  Only a fully off-screen
    device-space rectangle wraps. The requested one-screen horizontal shift and staggered
    vertical lane are then mapped back into local coordinates via the inverse transform.
    """
    try:
        sw = float(screen_width or 0.0)
        sh = max(1.0, float(screen_height or 1.0))
        if sw <= 1.0 or painter is None:
            return 0.0, 0.0, 0
        tr = painter.transform()
        mapped = tr.mapRect(QRectF(local_rect))
        left = float(mapped.left()); right = float(mapped.right())
        cycle = 0
        if left >= sw:
            cycle = max(1, int(math.floor(left / sw)))
        elif right <= 0.0:
            cycle = -max(1, int(math.floor(max(0.0, -right) / sw)) + 1)
        if not cycle:
            return 0.0, 0.0, 0

        lane = max(float(line_height or 1.0) * 1.15, float(line_height or 1.0) + 8.0)
        lane_dir = 1.0 if float(mapped.center().y()) < sh * 0.5 else -1.0
        device_dx = -float(cycle) * sw
        device_dy = lane_dir * abs(cycle) * lane

        inv, ok = tr.inverted()
        if not ok:
            return 0.0, 0.0, 0
        anchor_local = QRectF(local_rect).center()
        anchor_device = tr.map(anchor_local)
        target_local = inv.map(QPointF(anchor_device.x() + device_dx, anchor_device.y() + device_dy))
        return (float(target_local.x() - anchor_local.x()),
                float(target_local.y() - anchor_local.y()), int(cycle))
    except Exception:
        return 0.0, 0.0, 0


# ==================== LRC 输入安全层 ====================
# 支持：
#   [mm:ss]
#   [mm:ss.xx] / [mm:ss.xxx]
#   [mm:ss:cc] / [mm:ss:mmm]
# 同一行可有多个前置时间标签。
_LRC_TIME_TOKEN_RE = re.compile(
    r'\[\s*(\d{1,3})\s*:\s*(\d{1,2})'
    r'(?:(?:\.(\d{1,3}))|(?::(\d{1,3})))?\s*\]'
)
_LRC_INLINE_TIME_RE = re.compile(
    r'<\s*\d{1,3}\s*:\s*\d{1,2}(?:(?:\.\d{1,3})|(?::\d{1,3}))?\s*>'
)
_YRC_LINE_RE = re.compile(r'^\s*\[(\d+)\s*,\s*(\d+)\s*\](.*)$')
_YRC_WORD_RE = re.compile(r'\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)(.*?)(?=\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*\)|$)')
_KLYRIC_WORD_RE = _YRC_WORD_RE


def _inline_lrc_match_to_ms(match):
    token = str(match.group(0) or '').strip()[1:-1]
    m = re.match(r'^\s*(\d{1,3})\s*:\s*(\d{1,2})(?:(?:\.(\d{1,3}))|(?::(\d{1,3})))?\s*$', token)
    if not m:
        return None
    minute = int(m.group(1)); second = int(m.group(2))
    if second >= 60:
        return None
    fraction = m.group(3) if m.group(3) is not None else m.group(4)
    return (minute * 60 + second) * 1000 + _lrc_fraction_ms(fraction)


def _format_lrc_ms(ms):
    ms = max(0, int(ms or 0))
    minute, rem = divmod(ms, 60000)
    second, milli = divmod(rem, 1000)
    return f"{minute:02d}:{second:02d}.{milli:03d}"


def _yrc_to_enhanced_lrc(yrc_text):
    """Convert NetEase YRC into Enhanced-LRC while preserving absolute word clocks.

    Each YRC token becomes <absolute-start>text<absolute-end>. The renderer consumes
    the start clock as a reveal event; the end tag is retained for compatibility with
    common Enhanced-LRC tooling. Invalid lines are ignored rather than shown raw.
    """
    if not yrc_text:
        return ''
    out = []
    for raw in str(yrc_text).replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        line = raw.strip('\ufeff').strip()
        if not line:
            continue
        lm = _YRC_LINE_RE.match(line)
        if not lm:
            # Preserve only ordinary metadata tags, never unknown YRC control text.
            if _LRC_METADATA_ONLY_RE.match(line) or _LRC_OFFSET_RE.match(line):
                out.append(line)
            continue
        line_start = int(lm.group(1))
        body = lm.group(3) or ''
        parts = []
        for wm in _YRC_WORD_RE.finditer(body):
            start_ms = int(wm.group(1)); duration_ms = max(0, int(wm.group(2)))
            word = _LRC_CONTROL_RE.sub('', wm.group(4) or '')
            if not word:
                continue
            parts.append(
                f"<{_format_lrc_ms(start_ms)}>{word}"
                f"<{_format_lrc_ms(start_ms + duration_ms)}>"
            )
        if parts:
            out.append(f"[{_format_lrc_ms(line_start)}]" + ''.join(parts))
    return '\n'.join(out).strip()


def _klyric_to_enhanced_lrc(klyric_text):
    """Convert legacy NetEase KLYRIC karaoke timing to Enhanced-LRC.

    KLYRIC has existed alongside ordinary LRC for years. In the wild its token start
    field appears in three variants: absolute playback ms, offset-from-line-start, and
    older delta-like exports. Detect the shape per line and normalize all of them to
    absolute reveal clocks. Duration is retained as an end tag exactly like YRC.
    """
    if not klyric_text:
        return ''
    out = []
    for raw in str(klyric_text).replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        line = raw.strip('\ufeff').strip()
        if not line:
            continue
        lm = _YRC_LINE_RE.match(line)
        if not lm:
            if _LRC_METADATA_ONLY_RE.match(line) or _LRC_OFFSET_RE.match(line):
                out.append(line)
            continue
        line_start = int(lm.group(1)); line_duration = max(0, int(lm.group(2)))
        body = lm.group(3) or ''
        toks = []
        for wm in _KLYRIC_WORD_RE.finditer(body):
            a = int(wm.group(1)); dur = max(0, int(wm.group(2)))
            word = _LRC_CONTROL_RE.sub('', wm.group(4) or '')
            if word:
                toks.append((a, dur, word))
        if not toks:
            continue

        starts = [x[0] for x in toks]
        nondecreasing = all(starts[i] >= starts[i-1] for i in range(1, len(starts)))
        # Modern KLYRIC/YRC-like exports commonly use absolute clocks (first token near
        # line_start). Some older KLYRIC uses offsets within the line. A rare delta form
        # is handled last by accumulating gaps.
        if abs(starts[0] - line_start) <= max(1800, line_duration):
            mode = 'absolute'
        elif nondecreasing and max(starts) <= max(3000, line_duration + 1200):
            mode = 'line-relative'
        else:
            mode = 'delta'

        parts = []
        cumulative = line_start
        for a, dur, word in toks:
            if mode == 'absolute':
                start_ms = a
            elif mode == 'line-relative':
                start_ms = line_start + a
            else:
                cumulative += max(0, a)
                start_ms = cumulative
            start_ms = max(0, int(start_ms))
            parts.append(
                f"<{_format_lrc_ms(start_ms)}>{word}"
                f"<{_format_lrc_ms(start_ms + dur)}>"
            )
        if parts:
            out.append(f"[{_format_lrc_ms(line_start)}]" + ''.join(parts))
    return '\n'.join(out).strip()



_KRC_LINE_RE = re.compile(r'^\[(\d+)\s*,\s*(\d+)\](.*)$')
_KRC_WORD_RE = re.compile(r'<(\d+)\s*,\s*(\d+)\s*,\s*[^>]*>([^<]*)')

def _krc_plain_to_enhanced_lrc(krc_text):
    """Convert decompressed Kugou KRC into the same Enhanced-LRC clock used by YRC.

    KRC line clocks are absolute milliseconds. Token clocks are line-relative offsets
    with explicit durations. No inferred token boundaries are introduced.
    """
    if not krc_text:
        return ''
    out = []
    for raw in str(krc_text).replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        line = raw.strip('\ufeff').strip()
        if not line or line.startswith('[id:') or line.startswith('[ar:') or line.startswith('[ti:'):
            continue
        lm = _KRC_LINE_RE.match(line)
        if not lm:
            continue
        line_start = int(lm.group(1))
        body = lm.group(3) or ''
        parts = []
        for wm in _KRC_WORD_RE.finditer(body):
            rel = max(0, int(wm.group(1)))
            dur = max(0, int(wm.group(2)))
            word = _LRC_CONTROL_RE.sub('', html.unescape(wm.group(3) or ''))
            if not word:
                continue
            start_ms = line_start + rel
            parts.append(
                f"<{_format_lrc_ms(start_ms)}>{word}"
                f"<{_format_lrc_ms(start_ms + dur)}>"
            )
        if parts:
            out.append(f"[{_format_lrc_ms(line_start)}]" + ''.join(parts))
    return '\n'.join(out).strip()


def _krc_plain_translation_to_line_lrc(krc_text):
    """Extract KuGou KRC's embedded translated rows as line-timed LRC.

    KRC may carry a Base64 JSON ``[language:...]`` tag.  Translation rows have
    no independent clock; their row indexes correspond to the native KRC rows,
    so reuse only those provider line starts and never invent word timing.
    """
    raw_text = str(krc_text or '').replace('\r\n', '\n').replace('\r', '\n')
    if not raw_text:
        return ''
    starts = []
    language_blob = ''
    for raw in raw_text.split('\n'):
        line = raw.strip('\ufeff').strip()
        lm = _KRC_LINE_RE.match(line)
        if lm:
            starts.append(max(0, int(lm.group(1))))
            continue
        if line.startswith('[language:') and line.endswith(']'):
            language_blob = line[len('[language:'):-1].strip()
    if not starts or not language_blob:
        return ''
    try:
        pad = '=' * ((4 - len(language_blob) % 4) % 4)
        payload = base64.b64decode(language_blob + pad)
        obj = json.loads(payload.decode('utf-8', errors='strict'))
    except Exception:
        return ''
    entries = obj.get('content') if isinstance(obj, dict) else None
    if not isinstance(entries, list):
        return ''
    translated_rows = None
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        try:
            kind = int(entry.get('type', -1))
        except Exception:
            kind = -1
        rows = entry.get('lyricContent')
        if kind == 1 and isinstance(rows, list):
            translated_rows = rows
            break
    if not translated_rows:
        return ''
    out = []
    for idx, row in enumerate(translated_rows[:len(starts)]):
        if isinstance(row, (list, tuple)):
            text = ''.join(str(x or '') for x in row)
        else:
            text = str(row or '')
        text = _LRC_CONTROL_RE.sub('', html.unescape(text)).strip()
        if text:
            out.append(f"[{_format_lrc_ms(starts[idx])}]{text}")
    return '\n'.join(out).strip()

_QRC_WORD_MARK_RE = re.compile(r'\(\s*(\d+)\s*,\s*(\d+)\s*\)')
_QQ_QRC_KEY = b"!@#)(*$%123ZXC!@!@#)(NHL"


def _extract_qq_qrc_lyric_content(qrc_plain):
    """Extract LyricContent from a decrypted QQ QRC XML document."""
    raw = str(qrc_plain or '').lstrip('\ufeff').strip()
    if not raw:
        return ''
    if '<Lyric_1' not in raw and 'LyricContent=' not in raw:
        return raw
    m = re.search(r'<Lyric_1\b[^>]*\bLyricContent\s*=\s*([\"\'])(.*?)\1', raw, re.S | re.I)
    if not m:
        return ''
    return html.unescape(m.group(2) or '').replace('&#xA;', '\n').replace('&#10;', '\n').strip()


def _qrc_plain_to_enhanced_lrc(qrc_text):
    """Convert QQ QRC to Enhanced-LRC without inventing any timing.

    QQ QRC stores each token as ``text(start_ms,duration_ms)``. Both line and
    token start clocks are absolute playback milliseconds. The generated inline
    clock keeps the provider's exact start/end so the existing precise renderer
    can consume QRC alongside YRC/KLYRIC/KRC.
    """
    raw = _extract_qq_qrc_lyric_content(qrc_text)
    if not raw:
        return ''
    out = []
    for row in raw.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        line = row.strip('\ufeff')
        stripped = line.strip()
        if not stripped:
            continue
        lm = _YRC_LINE_RE.match(stripped)
        if not lm:
            if _LRC_METADATA_ONLY_RE.match(stripped) or _LRC_OFFSET_RE.match(stripped):
                out.append(stripped)
            continue
        line_start = max(0, int(lm.group(1)))
        body = lm.group(3) or ''
        parts = []
        cursor = 0
        for wm in _QRC_WORD_MARK_RE.finditer(body):
            word = _LRC_CONTROL_RE.sub('', html.unescape(body[cursor:wm.start()] or ''))
            cursor = wm.end()
            if not word:
                continue
            start_ms = max(0, int(wm.group(1)))
            duration_ms = max(0, int(wm.group(2)))
            parts.append(
                f"<{_format_lrc_ms(start_ms)}>{word}"
                f"<{_format_lrc_ms(start_ms + duration_ms)}>"
            )
        if parts:
            out.append(f"[{_format_lrc_ms(line_start)}]" + ''.join(parts))
    return '\n'.join(out).strip()


# QQ QRC DES port notes:
# The network QRC decoder below follows the bit-level DES/3DES layout used by
# fred913/goqrcdec (Apache-2.0). v22/v23 incorrectly assumed that layout was
# equivalent to word-swapping around a conventional DES3 implementation.
_QQ_QRC_SBOXES = (
    (14,4,13,1,2,15,11,8,3,10,6,12,5,9,0,7,0,15,7,4,14,2,13,1,10,6,12,11,9,5,3,8,4,1,14,8,13,6,2,11,15,12,9,7,3,10,5,0,15,12,8,2,4,9,1,7,5,11,3,14,10,0,6,13),
    (15,1,8,14,6,11,3,4,9,7,2,13,12,0,5,10,3,13,4,7,15,2,8,15,12,0,1,10,6,9,11,5,0,14,7,11,10,4,13,1,5,8,12,6,9,3,2,15,13,8,10,1,3,15,4,2,11,6,7,12,0,5,14,9),
    (10,0,9,14,6,3,15,5,1,13,12,7,11,4,2,8,13,7,0,9,3,4,6,10,2,8,5,14,12,11,15,1,13,6,4,9,8,15,3,0,11,1,2,12,5,10,14,7,1,10,13,0,6,9,8,7,4,15,14,3,11,5,2,12),
    (7,13,14,3,0,6,9,10,1,2,8,5,11,12,4,15,13,8,11,5,6,15,0,3,4,7,2,12,1,10,14,9,10,6,9,0,12,11,7,13,15,1,3,14,5,2,8,4,3,15,0,6,10,10,13,8,9,4,5,11,12,7,2,14),
    (2,12,4,1,7,10,11,6,8,5,3,15,13,0,14,9,14,11,2,12,4,7,13,1,5,0,15,10,3,9,8,6,4,2,1,11,10,13,7,8,15,9,12,5,6,3,0,14,11,8,12,7,1,14,2,13,6,15,0,9,10,4,5,3),
    (12,1,10,15,9,2,6,8,0,13,3,4,14,7,5,11,10,15,4,2,7,12,9,5,6,1,13,14,0,11,3,8,9,14,15,5,2,8,12,3,7,0,4,10,1,13,11,6,4,3,2,12,9,5,15,10,11,14,1,7,6,0,8,13),
    (4,11,2,14,15,0,8,13,3,12,9,7,5,10,6,1,13,0,11,7,4,9,1,10,14,3,5,12,2,15,8,6,1,4,11,13,12,3,7,14,10,15,6,8,0,5,9,2,6,11,13,8,1,4,10,7,9,5,0,15,14,2,3,12),
    (13,2,8,4,6,15,11,1,10,9,3,14,5,0,12,7,1,15,13,8,10,3,7,4,12,5,6,11,0,14,9,2,7,11,4,1,9,12,14,2,0,6,10,13,15,3,5,8,2,1,14,7,4,10,8,13,15,12,9,0,3,5,6,11),
)
_QQ_QRC_KEY_SHIFTS = (1,1,2,2,2,2,2,2,1,2,2,2,2,2,2,1)
_QQ_QRC_KEY_PERM_C = (56,48,40,32,24,16,8,0,57,49,41,33,25,17,9,1,58,50,42,34,26,18,10,2,59,51,43,35)
_QQ_QRC_KEY_PERM_D = (62,54,46,38,30,22,14,6,61,53,45,37,29,21,13,5,60,52,44,36,28,20,12,4,27,19,11,3)
_QQ_QRC_KEY_COMP = (13,16,10,23,0,4,2,27,14,5,20,9,22,18,11,3,25,7,15,6,26,19,12,1,40,51,30,36,46,54,29,39,50,44,32,47,43,48,38,55,33,52,45,41,49,35,28,31)
_QQ_QRC_PBOX = (15,6,19,20,28,11,27,16,0,14,22,25,4,17,30,9,1,7,23,13,31,26,2,8,18,12,29,5,21,10,3,24)

def _qq_qrc_bit_key_byte(a, b, c):
    i = (b // 32) * 4 + 3 - (b % 32) // 8
    return (((a[i] >> (7 - (b % 8))) & 1) << c)

def _qq_qrc_bit_key(a, b, c):
    i = (b // 32) * 4 + 3 - (b % 32) // 8
    return (((a[i] >> (7 - (b % 8))) & 1) << c)

def _qq_qrc_bit_intr(a, b, c):
    return (((a >> (31 - b)) & 1) << c)

def _qq_qrc_bit_intl(a, b, c):
    return (((a << b) & 0x80000000) >> c)

def _qq_qrc_sbox_bit(a):
    return (a & 0x20) | ((a & 0x1f) >> 1) | ((a & 1) << 4)

def _qq_qrc_des_key_setup(key, mode):
    C = D = 0
    for i, v in enumerate(_QQ_QRC_KEY_PERM_C): C |= _qq_qrc_bit_key(key, v, 31-i)
    for i, v in enumerate(_QQ_QRC_KEY_PERM_D): D |= _qq_qrc_bit_key(key, v, 31-i)
    schedule = [[0]*6 for _ in range(16)]
    for i, shift in enumerate(_QQ_QRC_KEY_SHIFTS):
        C = ((C << shift) | (C >> (28-shift))) & 0xfffffff0
        D = ((D << shift) | (D >> (28-shift))) & 0xfffffff0
        si = 15-i if mode == 'decrypt' else i
        for j in range(24):
            schedule[si][j//8] |= _qq_qrc_bit_intr(C, _QQ_QRC_KEY_COMP[j], 7-(j%8))
        for j in range(24, 48):
            schedule[si][j//8] |= _qq_qrc_bit_intr(D, _QQ_QRC_KEY_COMP[j]-27, 7-(j%8))
    return schedule

def _qq_qrc_ip(block):
    left_bits = (57,49,41,33,25,17,9,1,59,51,43,35,27,19,11,3,61,53,45,37,29,21,13,5,63,55,47,39,31,23,15,7)
    right_bits = (56,48,40,32,24,16,8,0,58,50,42,34,26,18,10,2,60,52,44,36,28,20,12,4,62,54,46,38,30,22,14,6)
    a = sum(_qq_qrc_bit_key_byte(block, b, 31-i) for i,b in enumerate(left_bits))
    c = sum(_qq_qrc_bit_key_byte(block, b, 31-i) for i,b in enumerate(right_bits))
    return [a, c]

def _qq_qrc_inv_ip(state):
    d = [0]*8
    specs = {
        3:(7,15,23,31), 2:(6,14,22,30), 1:(5,13,21,29), 0:(4,12,20,28),
        7:(3,11,19,27), 6:(2,10,18,26), 5:(1,9,17,25), 4:(0,8,16,24),
    }
    for out_idx, bits in specs.items():
        v = 0
        c = 7
        for b in bits:
            v |= _qq_qrc_bit_intr(state[1], b, c); c -= 1
            v |= _qq_qrc_bit_intr(state[0], b, c); c -= 1
        d[out_idx] = v & 0xff
    return bytes(d)

def _qq_qrc_f(state, key):
    t1 = (_qq_qrc_bit_intl(state,31,0) | ((state & 0xf0000000)>>1) | _qq_qrc_bit_intl(state,4,5) | _qq_qrc_bit_intl(state,3,6) | ((state & 0x0f000000)>>3) | _qq_qrc_bit_intl(state,8,11) | _qq_qrc_bit_intl(state,7,12) | ((state & 0x00f00000)>>5) | _qq_qrc_bit_intl(state,12,17) | _qq_qrc_bit_intl(state,11,18) | ((state & 0x000f0000)>>7) | _qq_qrc_bit_intl(state,16,23))
    t2 = (_qq_qrc_bit_intl(state,15,0) | ((state & 0x0000f000)<<15) | _qq_qrc_bit_intl(state,20,5) | _qq_qrc_bit_intl(state,19,6) | ((state & 0x00000f00)<<13) | _qq_qrc_bit_intl(state,24,11) | _qq_qrc_bit_intl(state,23,12) | ((state & 0x000000f0)<<11) | _qq_qrc_bit_intl(state,28,17) | _qq_qrc_bit_intl(state,27,18) | ((state & 0x0000000f)<<9) | _qq_qrc_bit_intl(state,0,23))
    l = [(t1>>24)&255,(t1>>16)&255,(t1>>8)&255,(t2>>24)&255,(t2>>16)&255,(t2>>8)&255]
    l = [x ^ y for x,y in zip(l,key)]
    six = (l[0]>>2, ((l[0]&3)<<4)|(l[1]>>4), ((l[1]&15)<<2)|(l[2]>>6), l[2]&0x3f,
           l[3]>>2, ((l[3]&3)<<4)|(l[4]>>4), ((l[4]&15)<<2)|(l[5]>>6), l[5]&0x3f)
    out = 0
    for i, value in enumerate(six):
        out |= _QQ_QRC_SBOXES[i][_qq_qrc_sbox_bit(value)] << (28 - 4*i)
    p = 0
    for i, b in enumerate(_QQ_QRC_PBOX): p |= _qq_qrc_bit_intl(out, b, i)
    return p & 0xffffffff

def _qq_qrc_des_crypt(block, schedule):
    state = _qq_qrc_ip(block)
    for idx in range(15):
        t = state[1]
        state[1] = (_qq_qrc_f(state[1], schedule[idx]) ^ state[0]) & 0xffffffff
        state[0] = t
    state[0] = (_qq_qrc_f(state[1], schedule[15]) ^ state[0]) & 0xffffffff
    return _qq_qrc_inv_ip(state)

def _qq_qrc_3des_schedules(mode='decrypt'):
    key = [int(b) for b in _QQ_QRC_KEY]
    if mode == 'encrypt':
        return (_qq_qrc_des_key_setup(key, 'encrypt'), _qq_qrc_des_key_setup(key[8:], 'decrypt'), _qq_qrc_des_key_setup(key[16:], 'encrypt'))
    return (_qq_qrc_des_key_setup(key[16:], 'decrypt'), _qq_qrc_des_key_setup(key[8:], 'encrypt'), _qq_qrc_des_key_setup(key, 'decrypt'))

def _qq_qrc_3des_crypt_block(block, mode='decrypt'):
    raw = bytes(block or b'')
    if len(raw) != 8: raise ValueError(f'QRC DES block must be 8 bytes, got {len(raw)}')
    out = raw
    for schedule in _qq_qrc_3des_schedules(mode): out = _qq_qrc_des_crypt(out, schedule)
    return out

def _qq_qrc_crypt_bytes(data, mode='decrypt'):
    raw = bytes(data or b'')
    if not raw or len(raw) % 8: raise ValueError(f'invalid QRC block length: {len(raw)}')
    schedules = _qq_qrc_3des_schedules(mode)
    out = bytearray()
    for i in range(0, len(raw), 8):
        block = raw[i:i+8]
        for schedule in schedules: block = _qq_qrc_des_crypt(block, schedule)
        out.extend(block)
    return bytes(out)

def _decode_qq_qrc_hex(content_hex):
    """Decode QQ encrypted QRC using the provider's actual bit-level 3DES layout."""
    clean = re.sub(r'\s+', '', html.unescape(str(content_hex or '')))
    if not clean or len(clean) % 2 or not re.fullmatch(r'[0-9A-Fa-f]+', clean):
        raise ValueError('invalid QRC hex payload')
    encrypted = bytes.fromhex(clean)
    if encrypted.startswith(b'[offset:0]\n'): encrypted = encrypted[11:]
    decrypted = _qq_qrc_crypt_bytes(encrypted, 'decrypt')
    plain = zlib.decompress(decrypted)
    if plain.startswith(b'\xef\xbb\xbf'): plain = plain[3:]
    return plain.decode('utf-8', errors='replace')

def _qrc_plain_to_line_lrc(qrc_text):
    """Turn decrypted QRC translation text into ordinary line-LRC, without word alignment."""
    raw = _extract_qq_qrc_lyric_content(qrc_text)
    if not raw: return ''
    out = []
    for row in raw.replace('\r\n','\n').replace('\r','\n').split('\n'):
        line = row.strip('\ufeff').strip()
        if not line: continue
        m = _YRC_LINE_RE.match(line)
        if m:
            start_ms = max(0, int(m.group(1)))
            body = m.group(3) or ''
            body = _QRC_WORD_MARK_RE.sub('', body)
            body = _LRC_CONTROL_RE.sub('', html.unescape(body)).strip()
            if body: out.append(f'[{_format_lrc_ms(start_ms)}]{body}')
        elif _LRC_TIME_TOKEN_RE.search(line):
            out.append(line)
    return '\n'.join(out).strip()


def _translation_to_line_lrc(translation_text, reference_lrc=''):
    """Normalize translation into line-level LRC only; never keep per-word clocks.

    Timed translation keeps only each row's leading line timestamp. If a provider returns
    plain translation lines, align them to the original lyric only when the line counts
    match exactly; refusing an uncertain alignment is safer than drifting later verses.
    """
    raw = html.unescape(str(translation_text or '')).replace('\r\n', '\n').replace('\r', '\n').strip()
    if not raw:
        return ''

    # Some QQ translation payloads are decrypted QRC/YRC-shaped text. Collapse those to
    # one timestamp per row first, discarding all word markers.
    if _YRC_LINE_RE.search(raw):
        qrc_line = _qrc_plain_to_line_lrc(raw)
        if qrc_line:
            raw = qrc_line

    timed = []
    for row in raw.split('\n'):
        line = row.strip('\ufeff').strip()
        if not line:
            continue
        times, body_raw = _split_lrc_leading_timestamps(line)
        if not times:
            continue
        body = _sanitize_lrc_body(html.unescape(body_raw))
        if not body:
            continue
        for ms in times:
            timed.append(f'[{_format_lrc_ms(ms)}]{body}')
    if timed:
        return '\n'.join(timed).strip()

    # Last-resort plain-text translation: only index-align when the provider returned the
    # same number of visible rows as the reference. This creates segment timing without
    # fabricating per-word timestamps.
    refs = []
    for row in str(reference_lrc or '').replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        times, body_raw = _split_lrc_leading_timestamps(row.strip('\ufeff').strip())
        if not times:
            continue
        body = _sanitize_lrc_body(html.unescape(body_raw))
        if body:
            refs.append((times[0], body))

    plain = []
    metadata_re = re.compile(r'^\[(?:ti|ar|al|by|kana|re|ve|length|id|hash|sign|language|tool|encoding|offset)\s*:', re.I)
    for row in raw.split('\n'):
        line = row.strip('\ufeff').strip()
        if not line or metadata_re.match(line):
            continue
        body = _sanitize_lrc_body(html.unescape(line))
        if body:
            plain.append(body)

    if refs and plain and len(refs) == len(plain):
        return '\n'.join(f'[{_format_lrc_ms(ms)}]{body}' for (ms, _), body in zip(refs, plain)).strip()
    return ''


def _is_native_han_lyric_line(body):
    """Conservative detector for original Chinese lyric rows missing from translation tracks."""
    text = _sanitize_lrc_body(html.unescape(str(body or ''))).strip()
    if not text or _LRC_CREDIT_BODY_RE.match(text) or _LRC_EXTRA_CREDIT_RE.match(text):
        return False
    if re.search(r'[\u3040-\u30ff\uac00-\ud7af]', text):
        return False
    han = re.findall(r'[\u3400-\u4dbf\u4e00-\u9fff]', text)
    if len(han) < 2:
        return False
    visible_letters = [ch for ch in text if ch.isalpha() or ch.isdigit()]
    return (len(han) / max(1, len(visible_letters))) >= 0.42


def _extract_native_chinese_lrc(original_lrc):
    """Return only confidently Chinese original lyric rows, preserving line timestamps."""
    rows = []
    for raw in str(original_lrc or '').replace('\r\n','\n').replace('\r','\n').split('\n'):
        line = raw.strip('\ufeff').strip()
        times, body_raw = _split_lrc_leading_timestamps(line)
        body = _sanitize_lrc_body(html.unescape(body_raw)) if times else ''
        if not times or not _is_native_han_lyric_line(body):
            continue
        for ms in times:
            rows.append((int(ms), body))
    rows.sort(key=lambda item: item[0])
    return '\n'.join(f'[{_format_lrc_ms(ms)}]{body}' for ms, body in rows).strip()


def _merge_translation_native_chinese(translation_lrc, original_lrc, tolerance_ms=420):
    """Fill untranslated original-Chinese rows without turning translation-only into bilingual mode.

    A row is added only when the original row is confidently Chinese and the translation
    track has no row at roughly the same timestamp. This keeps translated foreign-language
    rows translation-only while preserving Chinese phrases that never needed translation.
    """
    translated = []
    translated_times = []
    for raw in str(translation_lrc or '').replace('\r\n','\n').replace('\r','\n').split('\n'):
        line = raw.strip('\ufeff').strip()
        times, body_raw = _split_lrc_leading_timestamps(line)
        body = _sanitize_lrc_body(html.unescape(body_raw)) if times else ''
        if not times or not body:
            continue
        for ms in times:
            translated.append((int(ms), body, 0))
            translated_times.append(int(ms))
    if not translated:
        return str(translation_lrc or '').strip()

    added = 0
    for raw in str(original_lrc or '').replace('\r\n','\n').replace('\r','\n').split('\n'):
        line = raw.strip('\ufeff').strip()
        times, body_raw = _split_lrc_leading_timestamps(line)
        body = _sanitize_lrc_body(html.unescape(body_raw)) if times else ''
        if not times or not _is_native_han_lyric_line(body):
            continue
        for ms in times:
            ms = int(ms)
            if any(abs(ms - t) <= int(tolerance_ms) for t in translated_times):
                continue
            translated.append((ms, body, 1))
            translated_times.append(ms)
            added += 1
    translated.sort(key=lambda item: (item[0], item[2]))
    if added:
        try:
            write_error_log('仅翻译补回原曲中文行', detail=f'rows={added}')
        except Exception:
            pass
    return '\n'.join(f'[{_format_lrc_ms(ms)}]{body}' for ms, body, _kind in translated).strip()


def _lyric_script_profile(text):
    """Return a conservative primary script family for styling decisions."""
    value = str(text or '')
    if re.search(r'[\u3040-\u30ff]', value):
        return 'ja'
    if re.search(r'[\uac00-\ud7af]', value):
        return 'ko'
    if re.search(r'[\u3400-\u9fff]', value):
        return 'han'
    if re.search(r'[\u0590-\u08ff]', value):
        return 'rtl'
    if re.search(r'[A-Za-z\u00c0-\u024f\u0370-\u052f]', value):
        return 'western'
    return 'other'


def _netease_bridge_script_visual_phase(text, bridge_phase_ms):
    """Use one small precise-Bridge phase; script is diagnostic only."""
    try: phase = int(round(float(bridge_phase_ms or 0)))
    except Exception: phase = 0
    script = _lyric_script_profile(text)
    if phase <= 0: return phase, script
    return min(phase, int(NETEASE_INTERNAL_BRIDGE_VISUAL_LEAD_MS)), script

def _netease_bridge_timeline_visual_phase(timeline, raw_position_ms, bridge_phase_ms):
    """Resolve Bridge look-ahead from the row containing the *raw* player timestamp.

    v74 first added 120ms, used that future position to choose a script, and only then changed
    the phase to 20/120ms. Mixed-script rows could therefore make the phase decision depend on
    the phase itself. v76 keeps script classification only for diagnostics/presentation and uses
    one small uniform phase from authoritative raw currentTime; seek and steady playback match.
    """
    try:
        base = int(round(float(bridge_phase_ms or 0)))
        raw = int(round(float(raw_position_ms or 0)))
        if not timeline:
            return base, 'n/a'
        starts = [int(item[0]) for item in timeline]
        idx = max(0, min(len(starts) - 1, bisect.bisect_right(starts, raw) - 1))
        text = str(timeline[idx][1] or '')
        return _netease_bridge_script_visual_phase(text, base)
    except Exception:
        return int(round(float(bridge_phase_ms or 0))), 'unknown'


def _cjk_cross_provider_clock_should_fallback(reference_lrc, anchor_stats):
    """Reject only weak *and* heavily shifted CJK foreign clocks.

    A large native-LRC/KRC phase disagreement by itself is ambiguous, and low text coverage by
    itself can simply be segmentation. Requiring both keeps high-confidence KRC rhythm while
    routing suspicious CJK cases back to the v1.8.8-style native LRC flow.
    """
    if not CJK_KRC_COMFORT_FALLBACK_ENABLED:
        return False
    if _lyric_script_profile(reference_lrc) not in ('ja', 'ko', 'han'):
        return False
    try:
        coverage = float((anchor_stats or {}).get('coverage') or 0.0)
        phase = abs(float((anchor_stats or {}).get('median_delta') or 0.0))
    except Exception:
        return False
    return bool(coverage < float(CJK_KRC_COMFORT_MIN_COVERAGE) and phase > float(CJK_KRC_COMFORT_MAX_PHASE_MS))


def _cross_provider_clock_anchor_trusted(anchor_stats):
    """Require native-LRC evidence before a foreign precise clock owns timing."""
    stats = anchor_stats or {}
    try:
        matches = int(stats.get('matches') or 0)
        coverage = float(stats.get('coverage') or 0.0)
        spread = abs(float(stats.get('spread') or 0.0))
    except Exception:
        return False
    # Reanchoring itself already rejects incoherent phases. The trust gate is intentionally
    # a little stricter because a foreign clock that merely passes parser/search checks can
    # still be the right song but the wrong edit/master. Require at least six coherent rows
    # at >=45% coverage, or ten rows at >=35% for longer/segmented lyrics.
    evidence_ok = bool((matches >= 6 and coverage >= 0.45) or (matches >= 10 and coverage >= 0.35))
    try:
        drift_ms = abs(float(stats.get('drift_ms') or 0.0))
        trend_spread = abs(float(stats.get('trend_spread') or 0.0))
    except Exception:
        return False
    if not evidence_ok or spread > 130.0 or drift_ms > float(CROSS_PROVIDER_ANCHOR_DRIFT_MAX_MS) or trend_spread > float(CROSS_PROVIDER_ANCHOR_TREND_SPREAD_MAX_MS):
        return False
    if bool(stats.get('applied')):
        return True
    return str(stats.get('reason') or '') == 'below-noise-floor'


def _token_cascade_candidate(text, effect='smart'):
    """Whether a provider token may receive presentation-only visual subdivision.

    No synthetic lyric timestamps are created here: the cascade always stays inside the
    provider's real token span. Latin/Greek/Cyrillic and precomposed Hangul syllables are
    safe to reveal codepoint-by-codepoint. Arabic/Hebrew, Indic/Thai-like shaping, combining
    sequences, Jamo composition and emoji ZWJ sequences intentionally stay provider-atomic.
    """
    effect = str(effect or 'smart').strip().lower()
    token = str(text or '')
    core = [ch for ch in token if not ch.isspace()]
    if effect == 'token' or len(core) < 2:
        return False
    unsafe_shape = bool(re.search(
        r'[\u0590-\u08ff\u0900-\u0dff\u0e00-\u0fff\u1100-\u11ff\u3130-\u318f'
        r'\ua960-\ua97f\ud7b0-\ud7ff\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff'
        r'\u20d0-\u20ff\ufe20-\ufe2f\u200d\ufe0e\ufe0f]', token
    ))
    if effect == 'typewriter':
        return not unsafe_shape
    if effect != 'smart' or unsafe_shape:
        return False

    letters = [ch for ch in token if ch.isalpha()]
    if HANGUL_VISUAL_CASCADE_ENABLED:
        hangul = [ch for ch in letters if '\uac00' <= ch <= '\ud7a3']
        if len(hangul) >= 2 and len(hangul) >= max(2, int(len(letters) * 0.75)):
            return True

    if not LATIN_VISUAL_CASCADE_ENABLED:
        return False
    # Existing safe alphabetic path: Latin, Greek and Cyrillic.
    western = [ch for ch in letters if re.match(r'[A-Za-z\u00c0-\u024f\u0370-\u03ff\u0400-\u052f]', ch)]
    return len(western) >= 2 and len(western) >= max(2, int(len(letters) * 0.75))


_INSTRUMENTAL_BOILERPLATE_RE = re.compile(
    r'^(?:'
    r'(?:此|该|本)?(?:歌曲|曲目)?(?:为|是)?(?:一首)?(?:没有填词的|无歌词的)?纯音乐(?:作品)?'
    r'(?:[，,、 ]*(?:请您?|敬请)?欣赏)?|'
    r'(?:此|该|本)?(?:歌曲|曲目)?(?:暂(?:无|没有)|没有|无)(?:可用)?歌词'
    r'(?:[，,、 ]*(?:请您?|敬请)?欣赏)?|'
    r'(?:暂无|没有|无)(?:可用)?歌词(?:[，,、 ]*(?:请您?|敬请)?欣赏)?|'
    r'(?:instrumental(?:\s+music)?|pure\s+music)'
    r')[。.!！]?$'
    , re.I
)

def _instrumental_boilerplate_bodies(text):
    """Return visible provider rows for presentation-only instrumental detection."""
    bodies = []
    for raw in str(text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        stripped = raw.strip('\ufeff').strip()
        if not stripped or _LRC_OFFSET_RE.match(stripped) or _LRC_METADATA_ONLY_RE.match(stripped):
            continue
        times, body_raw = _split_lrc_leading_timestamps(stripped)
        body = _sanitize_lrc_body(body_raw if times else stripped)
        if not body:
            continue
        # Presentation normalization only. Provider clocks/text in text_input remain untouched.
        body = html.unescape(body)
        body = re.sub(r'[\u200b-\u200f\u202a-\u202e\u2060\ufeff]', '', body)
        body = re.sub(r'\s+', ' ', body).strip()
        if not body:
            continue
        # Intro production credits are not evidence that a song has lyrics. Ignore them when
        # deciding whether the remaining payload is only a provider instrumental notice.
        if _LRC_CREDIT_BODY_RE.match(body) or _LRC_EXTRA_CREDIT_RE.match(body):
            continue
        bodies.append(body)
    return bodies


def _instrumental_notice_compact(value):
    """Normalize punctuation/formatting without changing the provider payload itself."""
    value = html.unescape(str(value or '')).lower()
    value = re.sub(r'[\u200b-\u200f\u202a-\u202e\u2060\ufeff]', '', value)
    return re.sub(r'[\W_]+', '', value, flags=re.UNICODE)


def _instrumental_notice_text_variants(value):
    """Return presentation-only text variants for conservative mojibake recovery.

    Some ordinary KuGou LRC responses are UTF-8 bytes presented through a legacy text
    encoding by the HTTP stack.  Do not mutate the provider payload or click timeline;
    only try reversible round-trips here so a known pure-music notice can still be hidden.
    """
    base = html.unescape(str(value or ''))
    variants = [base]
    for legacy in ('latin1', 'cp1252', 'gb18030'):
        try:
            repaired = base.encode(legacy, errors='strict').decode('utf-8', errors='strict')
        except Exception:
            continue
        if repaired and repaired not in variants:
            variants.append(repaired)
    return variants


def _kugou_payload_text_repair(value):
    """Repair reversible KuGou HTTP mojibake before normal lyric cleanup/rendering.

    KuGou's ordinary-LRC endpoint is UTF-8 in practice, but some responses arrive through
    requests with a legacy guessed text encoding.  V11-V17 repaired this only inside pure-
    music *classification*, leaving normal timed rows/intro credits visibly garbled.

    This is conservative: only a strict legacy-bytes -> UTF-8 round-trip is considered,
    timestamp count must be preserved, and the candidate must materially reduce common
    mojibake bytes.  Provider timing tokens are never synthesized or shifted.
    """
    base = html.unescape(str(value or ''))
    if not base:
        return base, False, ''

    def penalty(text):
        text = str(text or '')
        # UTF-8-as-Latin1/CP1252 fingerprints, including the mojibake BOM seen in KuGou LRC.
        bad_sequences = ('ï»¿', 'Ã', 'Â', 'â€', 'â€™', 'â€œ', 'â€', 'å', 'æ', 'ç', 'ä', 'é', 'è', 'ð')
        score = sum(text.count(tok) * (8 if len(tok) > 1 else 1) for tok in bad_sequences)
        score += text.count('�') * 20
        return score

    base_times = len(_LRC_TIME_TOKEN_RE.findall(base))
    best = base
    best_codec = ''
    best_score = penalty(base)
    for legacy in ('latin1', 'cp1252'):
        try:
            repaired = base.encode(legacy, errors='strict').decode('utf-8', errors='strict')
        except Exception:
            continue
        if not repaired or repaired == base:
            continue
        if len(_LRC_TIME_TOKEN_RE.findall(repaired)) != base_times:
            continue
        score = penalty(repaired)
        # Require a real improvement. ASCII-only payloads round-trip to themselves and never land here.
        if score + 2 < best_score:
            best, best_codec, best_score = repaired, legacy, score
    return best, bool(best_codec), best_codec


def _instrumental_notice_strip_provider_meta(compact):
    """Strip bounded KuGou/QQ LRC bookkeeping that can survive mojibake cleanup.

    Runtime KuGou ordinary-LRC can arrive with a mojibake BOM in front of metadata such as
    ``[id:00000000]`` and ``[qq:total=320317]``.  The generic LRC metadata cleaner cannot
    recognize those tags until after reversible UTF-8 repair, so presentation detection sees
    ``id00000000qqtotal320317纯音乐请欣赏``.  Remove only known leading bookkeeping tokens
    here; provider text, click timeline, clocks and seek data remain untouched.
    """
    value = str(compact or '')
    if not value:
        return ''
    # Bounded numeric metadata prefixes only.  Deliberately do not strip arbitrary words so
    # a legitimate lyric ending in “纯音乐” cannot become a provider notice by accident.
    prefix = re.compile(r'^(?:(?:id|qqtotal|total|offset|length|duration|timelength)\d{1,16})', re.I)
    for _ in range(8):
        newer = prefix.sub('', value, count=1)
        if newer == value:
            break
        value = newer
    return value


def _is_instrumental_boilerplate_payload(text):
    """Conservatively detect provider boilerplate that should never become desktop lyrics.

    NetEase commonly returns one short line, while Kugou can split the same notice into
    several three-character KRC rows. Detection is renderer-only and never changes source
    text, timestamps, seek, clock authority, or provider selection.
    """
    bodies = _instrumental_boilerplate_bodies(text)
    if not bodies:
        return False

    # Exact provider phrases first. KuGou may repeat the same short notice on several
    # KRC rows (observed as 5 x "纯音乐"), so allow the full bounded provider payload here.
    if len(bodies) <= 8 and all(
        any(bool(_INSTRUMENTAL_BOILERPLATE_RE.match(candidate.strip()))
            for candidate in _instrumental_notice_text_variants(body))
        for body in bodies
    ):
        return True

    if len(bodies) > 8 or any(not (0 < len(body) <= 24) for body in bodies):
        return False

    joined = ''.join(bodies)
    # Runtime providers sometimes inject unusual punctuation/zero-width formatting.  A
    # KuGou ordinary-LRC response can also arrive as reversible UTF-8 mojibake.  Detection
    # may repair that *only for presentation classification*; source text stays untouched.
    for candidate in _instrumental_notice_text_variants(joined):
        candidate = candidate.strip()
        if _INSTRUMENTAL_BOILERPLATE_RE.match(candidate):
            return True

        # KuGou's KRC may segment the sentence differently from its ordinary-LRC equivalent.
        # After stripping presentation-only punctuation, require a *short* payload plus a
        # provider-specific pure-music phrase. This intentionally does not classify a lyric
        # merely because it mentions “纯音乐”.
        compact = _instrumental_notice_strip_provider_meta(_instrumental_notice_compact(candidate))
        if len(compact) <= 40:
            if re.fullmatch(
                r'(?:(?:此|该|本)?(?:歌曲|曲目)?(?:为|是)?(?:一首)?(?:没有填词的|无歌词的)?'
                r'纯音乐(?:作品)?(?:(?:请您?|敬请)?欣赏)?)', compact
            ):
                return True
            if re.fullmatch(
                r'(?:(?:此|该|本)?(?:歌曲|曲目)?(?:暂无|暂没有|没有|无)(?:可用)?歌词'
                r'(?:(?:请您?|敬请)?欣赏)?)', compact
            ):
                return True
            if compact in ('instrumental', 'instrumentalmusic', 'puremusic'):
                return True
    return False

def _is_netease_sparse_instrumental_placeholder(text, duration_ms=0):
    """Recognize the NetEase one-line/5-second pure-music placeholder seen in runtime logs.

    This is deliberately presentation-only and source-specific.  It requires a long track,
    exactly one short visible timed row, no word clock, and the provider's characteristic
    ~5s placement.  It does not alter the source payload, clock, seek timeline, or provider
    selection.
    """
    try:
        if int(duration_ms or 0) < 60000:
            return False
        raw = str(text or '')
        if _LRC_INLINE_TIME_RE.search(raw):
            return False
        rows = []
        for raw_line in raw.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
            stripped = raw_line.strip('\ufeff').strip()
            if not stripped or _LRC_OFFSET_RE.match(stripped) or _LRC_METADATA_ONLY_RE.match(stripped):
                continue
            times, body_raw = _split_lrc_leading_timestamps(stripped)
            if not times:
                continue
            body = _sanitize_lrc_body(body_raw)
            if not body:
                continue
            # Ignore timed production credits; they are not the placeholder row itself.
            if _LRC_CREDIT_BODY_RE.match(body) or _LRC_EXTRA_CREDIT_RE.match(body):
                continue
            body = html.unescape(body)
            body = re.sub(r'[\u200b-\u200f\u202a-\u202e\u2060\ufeff]', '', body)
            body = re.sub(r'\s+', ' ', body).strip()
            if body:
                rows.append((min(times), body))
        if len(rows) != 1:
            return False
        start_ms, body = rows[0]
        compact = _instrumental_notice_compact(body)
        if not (3500 <= int(start_ms) <= 6500):
            return False
        if not (1 <= len(compact) <= 8):
            return False
        # Provider placeholders observed here are CJK-only after punctuation stripping.
        # Reject Latin/digit-bearing one-line songs so this cannot become a generic sparse-song rule.
        if re.search(r'[A-Za-z0-9]', compact):
            return False
        return True
    except Exception:
        return False


def _provider_pure_music_flag(payload):
    """Return True/False for a provider pure-music field, or None when not declared.

    Providers are inconsistent about bool/int/string encodings.  This helper is deliberately
    narrow and presentation-only; unknown values never become instrumental evidence.
    """
    if not isinstance(payload, dict) or 'pureMusic' not in payload:
        return None
    value = payload.get('pureMusic')
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if value in (0, 1):
            return bool(value)
        return None
    if isinstance(value, str):
        token = value.strip().lower()
        if token in ('1', 'true', 'yes', 'y', 'on'):
            return True
        if token in ('0', 'false', 'no', 'n', 'off', ''):
            return False
    return None


def _lyric_payload_profile(text):
    """Describe cleaned visible timed content without assigning clock authority."""
    rows = []
    for raw in str(text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        stripped = raw.strip('\ufeff').strip()
        if not stripped or _LRC_OFFSET_RE.match(stripped) or _LRC_METADATA_ONLY_RE.match(stripped):
            continue
        times, body_raw = _split_lrc_leading_timestamps(stripped)
        if not times:
            continue
        body = _sanitize_lrc_body(body_raw)
        if not body or _LRC_CREDIT_BODY_RE.match(body) or _LRC_EXTRA_CREDIT_RE.match(body):
            continue
        body = html.unescape(body)
        body = re.sub(r'[\u200b-\u200f\u202a-\u202e\u2060\ufeff]', '', body)
        body = re.sub(r'\s+', ' ', body).strip()
        if body:
            rows.append((min(times), body))
    return {
        'rows': len(rows),
        'visible_chars': sum(len(_instrumental_notice_compact(body)) for _ts, body in rows),
        'first_ms': min((ts for ts, _body in rows), default=None),
    }


def _provider_payload_instrumental(source, text, duration_ms=0, provider_meta=None):
    """Classify lyric *payload* independently from the selected playback provider.

    This is the missing provenance layer for cross-provider borrowing: a QQ session may carry
    NetEase lyric text, and that text must retain NetEase's sparse-placeholder semantics.
    """
    meta = dict(provider_meta or {})
    if meta.get('pure_music_hint') is True:
        return True
    if _is_instrumental_boilerplate_payload(text):
        return True
    if str(source or '') == '网易云':
        return _is_netease_sparse_instrumental_placeholder(text, duration_ms)
    return False


def _build_lyric_payload_meta(base_meta, payload_source, text, duration_ms=0, provider_meta=None):
    """Preserve transport identity while attaching safe lyric-payload provenance."""
    out = dict(base_meta or {})
    pmeta = dict(provider_meta or {})
    source = str(payload_source or out.get('source') or '')
    flag = pmeta.get('pure_music_hint', None)
    profile = _lyric_payload_profile(text)
    out['lyric_payload_source'] = source
    if flag is True or flag is False:
        out['lyric_payload_pure_music'] = bool(flag)
    else:
        out.pop('lyric_payload_pure_music', None)
    out['lyric_payload_instrumental'] = bool(
        _provider_payload_instrumental(source, text, duration_ms, pmeta)
    )
    out['lyric_payload_rows'] = int(profile.get('rows') or 0)
    out['lyric_payload_visible_chars'] = int(profile.get('visible_chars') or 0)
    first_ms = profile.get('first_ms')
    out['lyric_payload_first_ms'] = int(first_ms) if first_ms is not None else None
    return out


def _is_primary_instrumental_payload(source, text, duration_ms=0):
    """Classify a selected provider's own lyric payload before cross-provider enhancement.

    This is a lyric-retrieval fast path only.  It never changes transport identity, clock
    authority, seek state or provider selection.  A confirmed provider notice should not pay
    several extra seconds asking the other two services for a higher-quality lyric clock.
    """
    try:
        return _provider_payload_instrumental(source, text, duration_ms, None)
    except Exception:
        return False


def _instrumental_track_card_lrc(song, artist=''):
    song = re.sub(r'\s+', ' ', str(song or '')).strip()
    artist = re.sub(r'\s+', ' ', str(artist or '')).strip()
    if not song:
        return ''
    card = f'♫ {song}'
    if artist:
        card += f' — {artist}'
    return f'[00:00.00]{card[:180]}'


def _decode_kugou_krc_content(content_b64):
    """Decode Kugou /download fmt=krc Base64 payload to plain KRC text."""
    if not content_b64:
        return ''
    blob = base64.b64decode(content_b64)
    if len(blob) < 5 or blob[:4] != b'krc1':
        return ''
    key = bytes([
        0x40, 0x47, 0x61, 0x77, 0x5e, 0x32, 0x74, 0x47,
        0x51, 0x36, 0x31, 0x2d, 0xce, 0xd2, 0x6e, 0x69
    ])
    enc = blob[4:]
    dec = bytes(b ^ key[i % len(key)] for i, b in enumerate(enc))
    return zlib.decompress(dec).decode('utf-8', errors='replace')

def _lyric_clock_quality(text):
    """0=no timed lyric, 1=line LRC, 3=provider word clock."""
    raw = str(text or '')
    if WORD_TIMING_ENABLED and _LRC_INLINE_TIME_RE.search(raw):
        return 3
    if _LRC_TIME_TOKEN_RE.search(raw):
        return 1
    return 0

def _parse_enhanced_body(body_raw, offset_ms=0):
    """Return (plain_text, reveal_events) for Enhanced-LRC inline clocks.

    v1.8.9.7 keeps richer provider timing without changing the public timeline shape.
    Each reveal event is:
        (start_ms, visible_end, end_ms, visible_start)

    Older consumers only read [0]/[1], so the first two fields remain backward-compatible.
    The end/start-visible fields let the renderer animate *inside* a provider token rather
    than snapping the whole token on one 40ms line-timer tick.

    Generated YRC/KLYRIC is shaped as:
        <token-start>text<token-end><next-start>text...
    Generic Enhanced-LRC without explicit end clocks still works; its next inline clock
    becomes a conservative visual end.
    """
    raw = _LRC_CONTROL_RE.sub('', str(body_raw or ''))
    matches = list(_LRC_INLINE_TIME_RE.finditer(raw))
    if not matches:
        return _sanitize_lrc_body(raw), None

    plain_parts = []
    events = []
    visible = 0

    prefix = _LRC_TIME_TOKEN_RE.sub('', raw[:matches[0].start()])
    prefix = re.sub(r'[ \t]+', ' ', prefix)
    if prefix:
        plain_parts.append(prefix)
        visible += len(prefix)

    for i, m in enumerate(matches):
        seg_start = m.end()
        seg_end = matches[i + 1].start() if i + 1 < len(matches) else len(raw)
        segment = _LRC_TIME_TOKEN_RE.sub('', raw[seg_start:seg_end])
        segment = re.sub(r'[ \t]+', ' ', segment)
        if not segment:
            continue

        at_ms = _inline_lrc_match_to_ms(m)
        if at_ms is None:
            continue
        at_ms = max(0, int(at_ms + offset_ms))

        visible_start = visible
        plain_parts.append(segment)
        visible += len(segment)

        end_ms = at_ms
        if i + 1 < len(matches):
            maybe_end = _inline_lrc_match_to_ms(matches[i + 1])
            if maybe_end is not None:
                end_ms = max(at_ms, int(maybe_end + offset_ms))

        events.append((at_ms, visible, end_ms, visible_start))

    plain = ''.join(plain_parts).strip()
    if not plain:
        return '', None

    # Boundary strip can shift indices. Rebuild conservatively while preserving segment
    # widths as much as possible. YRC/KLYRIC normally has no leading/trailing whitespace.
    raw_visible = visible
    shift = max(0, raw_visible - len(plain))
    cleaned = []
    last_t = -1
    last_n = -1
    for ev in events:
        t, n, end_t, start_n = ev
        n = max(0, min(len(plain), int(n - shift)))
        start_n = max(0, min(n, int(start_n - shift)))
        if n <= last_n:
            continue
        if t < last_t:
            t = last_t
        end_t = max(int(t), int(end_t))
        cleaned.append((int(t), n, end_t, start_n))
        last_t, last_n = int(t), n
    return plain, (cleaned or None)

_LRC_OFFSET_RE = re.compile(r'^\s*\[\s*offset\s*:\s*([+-]?\d+)\s*\]\s*$', re.I)
_LRC_METADATA_ONLY_RE = re.compile(
    r'^\s*\[\s*(?:ti|ar|al|by|kana|re|ve|length|id|hash|sign|language|tool|encoding)\s*:',
    re.I
)
_LRC_CREDIT_BODY_RE = re.compile(
    r'^(?:'
    r'词|曲|编曲|作词|作曲|編曲|歌詞|歌词|'
    r'演唱|歌手|制作|制作人|监制|監製|統籌|统筹|'
    r'混音|母带|母帶|录音|錄音|和声|和聲|'
    r'吉他|貝斯|贝斯|鼓|键盘|鍵盤|弦乐|弦樂|'
    r'lyrics?|lyricist|composer|arranger|producer|'
    r'vocal|vocals|music|words|op|sp|发行|發行|出品'
    r')\s*[:：]',
    re.I
)
_LRC_SECTION_LABEL_RE = re.compile(
    r'^\s*[（(]\s*(?:唱|演唱|戏腔|戲腔|念白|对白|對白|合|合唱|旁白)[^）)]*[）)]\s*(?:[^:：]{0,40}[:：].*)?\s*$',
    re.I
)
_LRC_EXTRA_CREDIT_RE = re.compile(
    r'^(?:戏词念白|戲詞念白|混音\s*/\s*录音|混音\s*/\s*錄音|录音\s*/\s*混音|錄音\s*/\s*混音|老生|青衣)\s*[:：]',
    re.I
)

# Presentation-only credit detector used by the user-selectable intro policy. It is
# intentionally broader than lyric cleaning so English credits such as
# "Composed & Arranged by ..." can be hidden without changing source parsing.
_INTRO_DISPLAY_CREDIT_RE = re.compile(
    r'^(?:'
    r'(?:composed|arranged|written|produced|performed|mixed|mastered|recorded|illustrated|animation|movie|video)'
    r'(?:\s*(?:&|and|/|,|\+)\s*(?:composed|arranged|written|produced|performed|mixed|mastered|recorded|illustrated|animation|movie|video))*'
    r'\s*(?:by|[:：])|'
    r'(?:作词|作詞|作曲|编曲|編曲|制作|製作|混音|母带|母帶|录音|錄音|演唱|歌手|和声|和聲|吉他|贝斯|貝斯|鼓|键盘|鍵盤|弦乐|弦樂)'
    r'\s*(?:[:：]|by\b)'
    r')',
    re.I
)
# Compact title-card mode keeps only authorship credits that are useful at a glance.
# It intentionally excludes arranger/producer/mix/etc. so the compact card cannot recreate
# the very first-second credit flood this presentation option is meant to avoid.
_INTRO_DISPLAY_PRIMARY_CREDIT_RE = re.compile(
    r'^(?:词|詞|歌词|歌詞|作词|作詞|作曲|曲|lyrics?|lyricist|words|composer|composed|written)'
    r'(?:\s*(?:&|and|/|,|\+)\s*(?:词|詞|作词|作詞|作曲|曲|lyrics?|lyricist|words|composer|composed|written|arranged))*'
    r'\s*(?:[:：]|by\b)',
    re.I
)
_LRC_SPEAKER_LABEL_RE = re.compile(
    r'^\s*[^，。！？!?]{1,32}[:：]\s*$'
)

_LRC_ANY_METADATA_RE = re.compile(
    r'\[\s*(?:ti|ar|al|by|offset|kana|re|ve|length|id|hash|sign|language|tool|encoding)\s*:',
    re.I
)
_LRC_QRC_HINT_RE = re.compile(r'\[\s*\d+\s*,\s*\d+\s*\].*?\(\s*\d+\s*,\s*\d+\s*\)', re.S)
_LRC_SRT_HINT_RE = re.compile(
    r'\d{1,2}:\d{2}:\d{2}[,.]\d{1,3}\s*-->\s*'
    r'\d{1,2}:\d{2}:\d{2}[,.]\d{1,3}'
)
_LRC_CONTROL_RE = re.compile(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]')


def _lrc_fraction_ms(value):
    if value is None or value == '':
        return 0
    digits = str(value)
    if len(digits) == 1:
        return int(digits) * 100
    if len(digits) == 2:
        return int(digits) * 10
    return int(digits[:3])


def _lrc_match_to_ms(match):
    minute = int(match.group(1))
    second = int(match.group(2))
    fraction = match.group(3) if match.group(3) is not None else match.group(4)
    if second >= 60:
        return None
    return (minute * 60 + second) * 1000 + _lrc_fraction_ms(fraction)


def _split_lrc_leading_timestamps(line):
    """Return (timestamps_ms, body) for consecutive leading LRC time tags."""
    raw = str(line or '').lstrip()
    pos = 0
    times = []
    while pos < len(raw):
        while pos < len(raw) and raw[pos].isspace():
            pos += 1
        m = _LRC_TIME_TOKEN_RE.match(raw, pos)
        if not m:
            break
        ms = _lrc_match_to_ms(m)
        if ms is None:
            break
        times.append(ms)
        pos = m.end()
    return times, raw[pos:].strip()


def _sanitize_lrc_body(body):
    body = _LRC_CONTROL_RE.sub('', str(body or ''))
    # Enhanced-LRC per-word clocks are control data, never visible lyric text here.
    body = _LRC_INLINE_TIME_RE.sub('', body)
    # Defensive second pass: valid [] timestamps remaining inside the body are also
    # control data. This prevents "[01:23.45]" from ever reaching the renderer.
    body = _LRC_TIME_TOKEN_RE.sub('', body)
    return re.sub(r'[ \t]+', ' ', body).strip()


def _looks_like_timed_lyric(text):
    raw = str(text or '')
    return bool(
        _LRC_TIME_TOKEN_RE.search(raw) or
        _LRC_INLINE_TIME_RE.search(raw) or
        _LRC_ANY_METADATA_RE.search(raw) or
        _LRC_QRC_HINT_RE.search(raw) or
        _LRC_SRT_HINT_RE.search(raw)
    )


def _sync_text_key(value):
    """Normalize a lyric body for conservative cross-provider line alignment."""
    body = html.unescape(_sanitize_lrc_body(value or '')).lower()
    return re.sub(r'[\W_]+', '', body, flags=re.UNICODE)


def _lrc_alignment_events(lrc_text):
    """Return (absolute_line_ms, normalized_text) without invoking the renderer parser."""
    raw_lines = str(lrc_text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n')
    offset_ms = 0
    for raw in raw_lines:
        m = _LRC_OFFSET_RE.match(raw.strip('\ufeff').strip())
        if m:
            try:
                offset_ms = max(-3600000, min(3600000, int(m.group(1))))
            except Exception:
                offset_ms = 0
    events = []
    for raw in raw_lines:
        stripped = raw.strip('\ufeff').strip()
        if not stripped or _LRC_OFFSET_RE.match(stripped) or _LRC_METADATA_ONLY_RE.match(stripped):
            continue
        times, body_raw = _split_lrc_leading_timestamps(stripped)
        if not times:
            continue
        key = _sync_text_key(body_raw)
        if len(key) < 2:
            continue
        for at in times:
            events.append((max(0, int(at + offset_ms)), key))
    events.sort(key=lambda item: item[0])
    return events


def _median_number(values):
    vals = sorted(float(v) for v in values)
    if not vals:
        return 0.0
    n = len(vals)
    if n % 2:
        return vals[n // 2]
    return (vals[n // 2 - 1] + vals[n // 2]) / 2.0


def _estimate_cross_source_lrc_offset(reference_lrc, precise_lrc):
    """Estimate a constant precise-clock shift using QQ's own line starts as reference.

    The cross-source bridge already requires title/artist/duration agreement. This second
    gate refuses to shift YRC unless several *identical lyric lines* also agree on one
    small offset. Repeated choruses are paired by nearest absolute time, not just text.
    """
    ref_events = _lrc_alignment_events(reference_lrc)
    precise_events = _lrc_alignment_events(precise_lrc)
    if len(ref_events) < 2 or len(precise_events) < 2:
        return 0, 0, None

    by_key = {}
    for at, key in precise_events:
        by_key.setdefault(key, []).append(at)

    deltas = []
    for ref_at, key in ref_events:
        candidates = by_key.get(key) or []
        if not candidates:
            continue
        nearest = min(candidates, key=lambda at: abs(float(ref_at) - float(at)))
        delta = float(ref_at) - float(nearest)
        # Strict match means the tracks should already be nearly phase-aligned. Larger
        # differences are more likely duplicated/variant lines than encoder delay.
        if abs(delta) <= 2200.0:
            deltas.append(delta)

    if len(deltas) < 2:
        return 0, len(deltas), None

    median = _median_number(deltas)
    residuals = [abs(d - median) for d in deltas]
    mad = _median_number(residuals)
    inliers = [d for d in deltas if abs(d - median) <= 360.0]
    min_inliers = 3 if len(deltas) >= 3 else 2
    if len(inliers) < min_inliers:
        return 0, len(inliers), int(round(mad))

    aligned = _median_number(inliers)
    spread = _median_number([abs(d - aligned) for d in inliers])
    if abs(aligned) > 1200.0 or spread > 220.0:
        return 0, len(inliers), int(round(spread))
    # Tiny estimates are below the timestamp/source noise floor and create more churn
    # than value, so leave them at zero.
    if abs(aligned) < 60.0:
        aligned = 0.0
    return int(round(aligned)), len(inliers), int(round(spread))




def _anchor_drift_diagnostics(anchor_pairs):
    """Measure time-base drift without changing the provider clock.

    A single global offset can hide a small speed/edit mismatch: the first half of a song may
    look correct while the last half is steadily early/late. Use a robust pairwise-slope median
    over well-separated native-LRC/precise-clock anchors. This is a *rejection* diagnostic only;
    v77 deliberately does not time-stretch provider tokens from coarse ordinary-LRC evidence.
    """
    pairs = sorted((float(t), float(d)) for t, d in (anchor_pairs or []))
    if len(pairs) < 4:
        return {'available': False, 'anchors': len(pairs), 'drift_ms': 0, 'drift_ppm': 0, 'trend_spread': 0}
    slopes = []
    for i in range(len(pairs)):
        t1, d1 = pairs[i]
        for j in range(i + 1, len(pairs)):
            t2, d2 = pairs[j]
            dt = t2 - t1
            if dt >= 30000.0:
                slopes.append((d2 - d1) / dt)
    if len(slopes) < 3:
        return {'available': False, 'anchors': len(pairs), 'drift_ms': 0, 'drift_ppm': 0, 'trend_spread': 0}
    slope = float(_median_number(slopes))
    center_t = float(_median_number([t for t, _ in pairs]))
    intercept = float(_median_number([d - slope * (t - center_t) for t, d in pairs]))
    residuals = [abs(d - (intercept + slope * (t - center_t))) for t, d in pairs]
    span = max(t for t, _ in pairs) - min(t for t, _ in pairs)
    drift_ms = slope * span
    return {
        'available': True, 'anchors': len(pairs), 'drift_ms': int(round(drift_ms)),
        'drift_ppm': int(round(slope * 1000000.0)),
        'trend_spread': int(round(_median_number(residuals))), 'span_ms': int(round(span)),
    }


def _reanchor_precise_lines_to_reference(reference_lrc, precise_lrc, provider_duration_delta_ms=None):
    """Conservatively align a cross-provider precise clock to the native provider.

    v59/v60 shifted *each matched line* to the NetEase ordinary-LRC timestamp. That preserved
    token spacing inside a line but could warp the inter-line clock by hundreds of milliseconds
    (and occasionally >1s) when the two providers segmented a phrase differently. Ordinary LRC
    is strong evidence for a song-level phase, but not precise enough to own every word-line onset.

    v61 therefore estimates one robust global phase from many identical lyric lines and applies
    that same shift to the whole KRC clock. The KRC provider keeps all relative token and line
    spacing. A very large phase with nearly identical total duration is accepted only when many
    matched rows agree tightly; weak large-phase evidence is still left untouched.
    """
    original = str(precise_lrc or '')
    ref_events = _lrc_alignment_events(reference_lrc)
    if len(ref_events) < 3 or not original:
        return original, {'applied': False, 'mode': 'global', 'matches': 0, 'shifted': 0, 'coverage': 0.0, 'median_delta': 0, 'spread': 0, 'reason': 'insufficient-reference'}

    rows = original.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    precise_rows = []
    for idx, raw in enumerate(rows):
        stripped = raw.strip('\ufeff').strip()
        if not stripped or _LRC_METADATA_ONLY_RE.match(stripped) or _LRC_OFFSET_RE.match(stripped):
            continue
        times, body_raw = _split_lrc_leading_timestamps(stripped)
        if len(times) != 1:
            continue
        key = _sync_text_key(body_raw)
        if len(key) < 2:
            continue
        precise_rows.append({'row': idx, 'start': int(times[0]), 'key': key, 'raw': stripped})
    if len(precise_rows) < 3:
        return original, {'applied': False, 'mode': 'global', 'matches': 0, 'shifted': 0, 'coverage': 0.0, 'median_delta': 0, 'spread': 0, 'reason': 'insufficient-precise'}

    ref_by_key = {}
    for ri, (at, key) in enumerate(ref_events):
        ref_by_key.setdefault(key, []).append((ri, int(at)))
    used_ref = set()
    deltas = []
    anchors = []
    exact_matches = 0

    # First estimate a coarse global offset using strict same-text evidence. It is only a
    # pairing aid here; no line is shifted independently anymore.
    coarse_offset, _, _ = _estimate_cross_source_lrc_offset(reference_lrc, precise_lrc)
    for item in precise_rows:
        p_start = int(item['start'])
        key = item['key']
        candidates = list(ref_by_key.get(key) or [])
        exact = bool(candidates)
        if not candidates and len(key) >= 4:
            for rkey, vals in ref_by_key.items():
                if len(rkey) >= 4 and (key in rkey or rkey in key):
                    candidates.extend(vals)
        if not candidates:
            continue
        center = float(p_start + int(coarse_offset or 0))
        candidates.sort(key=lambda it: ((it[0] in used_ref), abs(float(it[1]) - center)))
        ri, r_start = candidates[0]
        delta = int(r_start - p_start)
        limit = 1600 if exact else 900
        if abs(delta) > limit:
            continue
        if ri in used_ref and len(candidates) > 1:
            alt = next((c for c in candidates if c[0] not in used_ref and abs(int(c[1]) - center) <= limit), None)
            if alt is not None:
                ri, r_start = alt
                delta = int(r_start - p_start)
        used_ref.add(ri)
        deltas.append(delta)
        anchors.append((p_start, delta))
        exact_matches += int(exact)

    coverage = float(len(deltas)) / float(max(1, len(precise_rows)))
    if len(deltas) < 3 or coverage < 0.28:
        return original, {'applied': False, 'mode': 'global', 'matches': len(deltas), 'shifted': 0, 'coverage': coverage,
                          'median_delta': int(round(_median_number(deltas))) if deltas else 0, 'spread': 0, 'reason': 'low-coverage'}

    median_delta = float(_median_number(deltas))
    inlier_anchors = [(t, d) for t, d in anchors if abs(float(d) - median_delta) <= 260.0]
    inliers = [d for _, d in inlier_anchors]
    if len(inliers) < 3:
        return original, {'applied': False, 'mode': 'global', 'matches': len(deltas), 'shifted': 0, 'coverage': coverage,
                          'median_delta': int(round(median_delta)), 'spread': 0, 'reason': 'no-coherent-phase'}
    global_shift = float(_median_number(inliers))
    spread = float(_median_number([abs(float(d) - global_shift) for d in inliers]))
    inlier_coverage = float(len(inliers)) / float(max(1, len(precise_rows)))
    drift_stats = _anchor_drift_diagnostics(inlier_anchors)
    if drift_stats.get('available') and (
        abs(float(drift_stats.get('drift_ms') or 0.0)) > float(CROSS_PROVIDER_ANCHOR_DRIFT_MAX_MS) or
        float(drift_stats.get('trend_spread') or 0.0) > float(CROSS_PROVIDER_ANCHOR_TREND_SPREAD_MAX_MS)
    ):
        return original, {
            'applied': False, 'mode': 'global', 'matches': len(deltas), 'shifted': 0, 'coverage': coverage,
            'median_delta': int(round(global_shift)), 'spread': int(round(spread)),
            'drift_ms': int(drift_stats.get('drift_ms') or 0), 'drift_ppm': int(drift_stats.get('drift_ppm') or 0),
            'trend_spread': int(drift_stats.get('trend_spread') or 0), 'reason': 'timebase-drift',
        }
    if inlier_coverage < 0.25 or spread > 180.0 or abs(global_shift) > 1200.0:
        return original, {'applied': False, 'mode': 'global', 'matches': len(deltas), 'shifted': 0, 'coverage': coverage,
                          'median_delta': int(round(global_shift)), 'spread': int(round(spread)), 'reason': 'unstable-global-phase'}

    try:
        duration_delta = abs(float(provider_duration_delta_ms)) if provider_duration_delta_ms is not None else None
    except Exception:
        duration_delta = None
    if duration_delta is not None and duration_delta <= 300.0 and abs(global_shift) > 420.0:
        # A close total duration does not disprove a constant encoder/edit offset. When many
        # same-text rows independently agree on one large phase with a tight residual spread,
        # that is stronger evidence than duration equality and should be corrected. The old
        # unconditional guard left fully coherent clocks (e.g. 50+ lines, ~55ms spread) about
        # half a second late/early for the whole song. Keep the guard only for weak evidence.
        strong_coherent_phase = bool(
            len(inliers) >= 8 and coverage >= 0.72 and inlier_coverage >= 0.68 and spread <= 120.0
        )
        if not strong_coherent_phase:
            return original, {'applied': False, 'mode': 'global', 'matches': len(deltas), 'shifted': 0, 'coverage': coverage,
                              'median_delta': int(round(global_shift)), 'spread': int(round(spread)),
                              'reason': 'close-duration-large-phase', 'duration_delta': int(round(duration_delta))}

    shift = int(round(global_shift))
    if abs(shift) < 35:
        return original, {'applied': False, 'mode': 'global', 'matches': len(deltas), 'shifted': 0, 'coverage': coverage,
                          'median_delta': shift, 'spread': int(round(spread)), 'reason': 'below-noise-floor'}

    out = list(rows)
    shifted = 0
    for idx, raw in enumerate(rows):
        stripped = raw.strip('\ufeff').strip()
        if not stripped or _LRC_METADATA_ONLY_RE.match(stripped) or _LRC_OFFSET_RE.match(stripped):
            continue
        times, body_raw = _split_lrc_leading_timestamps(stripped)
        if len(times) != 1:
            continue
        def _shift_inline(m):
            at = _inline_lrc_match_to_ms(m)
            if at is None:
                return m.group(0)
            return f"<{_format_lrc_ms(max(0, int(at) + shift))}>"
        shifted_body = _LRC_INLINE_TIME_RE.sub(_shift_inline, body_raw)
        out[idx] = f"[{_format_lrc_ms(max(0, int(times[0]) + shift))}]" + shifted_body
        shifted += 1

    return '\n'.join(out).strip(), {
        'applied': bool(shifted), 'mode': 'global', 'matches': len(deltas), 'exact_matches': exact_matches,
        'shifted': shifted, 'coverage': coverage, 'median_delta': shift, 'spread': int(round(spread)),
        'max_shift': abs(shift), 'drift_ms': int(drift_stats.get('drift_ms') or 0),
        'drift_ppm': int(drift_stats.get('drift_ppm') or 0), 'trend_spread': int(drift_stats.get('trend_spread') or 0),
        'reason': 'global-phase',
    }



def _self_align_netease_native_precise(reference_lrc, precise_lrc):
    """Audit current NetEase YRC/KLYRIC against the same song_id's ordinary LRC.

    v82 proved that a same-provider LRC/YRC phase delta is useful evidence, but not a safe
    correction target: ordinary LRC is a coarse *line* annotation while YRC is a word clock.
    Fully shifting a native YRC by a large LRC delta can turn one uniform problem into a mix
    of early/on-time/late tokens.  v83 therefore keeps this comparison diagnostic-only.

    A very large, tightly coherent self-delta is instead a *trust alarm*.  The native precise
    clock is then allowed to yield to a separately verified same-platform/foreign enhancement;
    if none passes the existing native-LRC verification gates, ordinary NetEase LRC wins.
    No per-song constants, per-line warping, or time stretching are used.
    """
    original = str(precise_lrc or '')
    if not reference_lrc or not original:
        return original, {
            'applied': False, 'reason': 'missing-native-self-reference', 'matches': 0,
            'coverage': 0.0, 'median_delta': 0, 'spread': 0, 'drift_ms': 0,
            'trend_spread': 0, 'self_phase_suspect': False,
        }
    _aligned_preview, stats = _reanchor_precise_lines_to_reference(
        reference_lrc, original, provider_duration_delta_ms=0
    )
    stats = dict(stats or {})
    shift = int(stats.get('median_delta') or 0)
    matches = int(stats.get('matches') or 0)
    coverage = float(stats.get('coverage') or 0.0)
    spread = int(stats.get('spread') or 0)
    drift = abs(int(stats.get('drift_ms') or 0))
    trend_spread = abs(int(stats.get('trend_spread') or 0))

    coherent = bool(
        stats.get('applied') and
        matches >= 10 and coverage >= 0.50 and spread <= 110 and
        drift <= 120 and trend_spread <= 110
    )
    # v96: ordinary LRC is a coarse line annotation, while YRC/KLYRIC is the provider's
    # actual word clock. A stable fixed delta therefore cannot, by itself, revoke the
    # current same-platform word clock. Preserve a strongly coherent native clock up to
    # 900ms of fixed line-vs-word phase; only weak/dirty large-phase evidence (or an
    # extreme >=1.2s disagreement) opens foreign/cached-clock arbitration.
    stable_native = bool(
        stats.get('applied') and matches >= 12 and coverage >= 0.80 and
        spread <= 100 and drift <= 100 and trend_spread <= 100 and abs(shift) <= 900
    )
    suspect = bool(
        coherent and abs(shift) >= 480 and
        (not stable_native or abs(shift) >= 1200)
    )
    stats['self_phase_strong'] = bool(coherent)
    stats['self_phase_stable_native'] = bool(stable_native)
    stats['self_phase_suspect'] = bool(suspect)
    stats['applied_preview'] = bool(stats.get('applied'))
    stats['applied'] = False
    if suspect:
        stats['reason'] = 'native-self-large-phase-suspect'
    elif abs(shift) < 80:
        stats['reason'] = 'native-self-within-noise'
    elif stable_native and abs(shift) >= 480:
        stats['reason'] = 'native-self-stable-fixed-phase-diagnostic-only'
    elif coherent:
        stats['reason'] = 'native-self-coherent-diagnostic-only'
    else:
        stats['reason'] = 'native-self-evidence-insufficient'
    return original, stats

def _verify_precise_enhancement_against_native(reference_lrc, precise_lrc, provider_duration_delta_ms=None, preserve_provider_phase=False):
    """Return (verified_clock, stats, reason) for any non-current precise clock.

    Native ordinary-LRC remains strong evidence for song identity, global coherence and drift,
    but it is still a coarse *line* annotation. v84 therefore lets callers preserve a foreign
    provider's raw word-clock phase after validation. A raw clock that disagrees too much with
    the native line clock is rejected rather than shifted. Same-platform alternate YRC keeps
    the older aligned policy for now.
    """
    if not reference_lrc or not precise_lrc:
        return '', {'applied': False, 'reason': 'missing-native-reference', 'matches': 0, 'coverage': 0.0, 'spread': 0}, 'missing-native-reference'
    ref_ok, ref_stats, ref_reason = _precise_clock_reference_evidence(reference_lrc, precise_lrc)
    if not ref_ok:
        stats = {'applied': False, 'reason': ref_reason, 'matches': int(ref_stats.get('matches') or 0),
                 'coverage': 0.0, 'spread': 0, 'text_ratio': float(ref_stats.get('ratio') or 0.0)}
        return '', stats, ref_reason
    aligned, stats = _reanchor_precise_lines_to_reference(
        reference_lrc, precise_lrc, provider_duration_delta_ms=provider_duration_delta_ms
    )
    stats = dict(stats or {})
    stats['text_matches'] = int(ref_stats.get('matches') or 0)
    stats['text_ratio'] = float(ref_stats.get('ratio') or 0.0)
    trusted = _cross_provider_clock_anchor_trusted(stats)
    if trusted and _cjk_cross_provider_clock_should_fallback(reference_lrc, stats):
        trusted = False
        stats['reason'] = 'cjk-weak-large-phase'

    if trusted and preserve_provider_phase:
        try:
            raw_phase = int(round(float(stats.get('median_delta') or 0)))
        except Exception:
            raw_phase = 0
        stats['alignment_preview_applied'] = bool(stats.get('applied'))
        stats['alignment_preview_shift_ms'] = raw_phase if bool(stats.get('applied')) else 0
        if abs(raw_phase) <= int(NETEASE_KRC_RAW_PHASE_MAX_MS):
            stats['phase_policy'] = 'raw-krc-v84'
            stats['applied'] = False
            stats['reason'] = 'trusted-raw-provider-phase'
            return str(precise_lrc or ''), stats, 'trusted-raw-provider-phase'

        # v94 rescue: v84 correctly stopped blindly dragging every KRC to ordinary-LRC, but
        # its 420ms hard cutoff also discarded clocks where dozens of matching lines prove a
        # single fixed encoder/edit offset. Reuse the already-computed one-shot global alignment
        # only under substantially stricter evidence than the ordinary cross-provider gate.
        try:
            duration_delta = abs(float(provider_duration_delta_ms)) if provider_duration_delta_ms is not None else None
        except Exception:
            duration_delta = None
        matches = int(stats.get('matches') or 0)
        coverage = float(stats.get('coverage') or 0.0)
        spread = abs(int(stats.get('spread') or 0))
        drift = abs(int(stats.get('drift_ms') or 0))
        trend_spread = abs(int(stats.get('trend_spread') or 0))
        rescue = bool(
            aligned and bool(stats.get('applied')) and
            abs(raw_phase) <= int(NETEASE_KRC_ALIGNED_RESCUE_PHASE_MAX_MS) and
            matches >= 20 and coverage >= 0.70 and spread <= 110 and
            drift <= 160 and trend_spread <= 120 and
            (duration_delta is None or duration_delta <= float(NETEASE_KRC_ALIGNED_RESCUE_DURATION_DELTA_MAX_MS))
        )
        if rescue:
            stats['phase_policy'] = 'aligned-large-phase-rescue-v94'
            stats['reason'] = 'trusted-aligned-large-phase-rescue'
            return str(aligned or ''), stats, 'trusted-aligned-large-phase-rescue'

        stats['phase_policy'] = 'raw-krc-v84'
        stats['reason'] = 'raw-provider-phase-too-far'
        return '', stats, 'raw-provider-phase-too-far'

    reason = 'trusted' if trusted else str(stats.get('reason') or 'anchor-untrusted')
    if trusted:
        stats['phase_policy'] = 'aligned-reference'
    return (aligned if trusted else ''), stats, reason


def _precise_clock_basic_stats(precise_lrc):
    """Summarize a provider clock without trusting provider metadata."""
    line_events = _lrc_alignment_events(precise_lrc)
    inline_matches = list(_LRC_INLINE_TIME_RE.finditer(str(precise_lrc or '')))
    inline_times = []
    for m in inline_matches:
        t = _inline_lrc_match_to_ms(m)
        if t is not None:
            inline_times.append(int(t))
    visible_chars = sum(len(key) for _, key in line_events)
    span_ms = 0
    if inline_times:
        span_ms = max(inline_times) - min(inline_times)
    return {
        'lines': len(line_events),
        'inline_tags': len(inline_matches),
        'visible_chars': visible_chars,
        'span_ms': max(0, int(span_ms)),
        'raw_chars': len(str(precise_lrc or '')),
    }


def _precise_clock_basic_sanity(precise_lrc, duration_ms=0):
    """Reject obviously placeholder/empty provider clocks before they enter cache."""
    stats = _precise_clock_basic_stats(precise_lrc)
    duration_ms = max(0, int(duration_ms or 0))
    if not _LRC_INLINE_TIME_RE.search(str(precise_lrc or '')):
        return False, stats, 'no-inline-clock'
    # Long tracks with only a tiny one-line payload are commonly generic/placeholder
    # KRC candidates. Falling back to line-LRC is safer than calling that "precise".
    if duration_ms >= 60000:
        if stats['raw_chars'] < 260 or stats['lines'] < 2 or stats['visible_chars'] < 8:
            return False, stats, 'tiny-long-track-clock'
    return True, stats, 'ok'


def _precise_clock_reference_evidence(reference_lrc, precise_lrc):
    """Check that a cross-provider clock actually contains the same lyric text.

    Search metadata can identify the right audio row while the lyric-download endpoint
    still returns a generic candidate. Compare normalized lyric bodies as a second,
    provider-independent evidence gate.
    """
    ref = _lrc_alignment_events(reference_lrc)
    precise = _lrc_alignment_events(precise_lrc)
    if not ref:
        return True, {'ref_lines': 0, 'precise_lines': len(precise), 'matches': 0, 'ratio': 1.0}, 'no-reference'
    if not precise:
        return False, {'ref_lines': len(ref), 'precise_lines': 0, 'matches': 0, 'ratio': 0.0}, 'no-precise-lines'

    ref_keys = []
    seen = set()
    for _, key in ref:
        if key and key not in seen:
            ref_keys.append(key); seen.add(key)
    precise_keys = []
    seen = set()
    for _, key in precise:
        if key and key not in seen:
            precise_keys.append(key); seen.add(key)

    matches = 0
    for rk in ref_keys:
        if len(rk) < 2:
            continue
        if any(
            rk == pk or
            (len(rk) >= 4 and len(pk) >= 4 and (rk in pk or pk in rk))
            for pk in precise_keys
        ):
            matches += 1

    ref_concat = ''.join(ref_keys)[:16000]
    precise_concat = ''.join(precise_keys)[:16000]
    ratio = difflib.SequenceMatcher(None, ref_concat, precise_concat, autojunk=False).ratio() if ref_concat and precise_concat else 0.0

    if len(ref_keys) <= 1:
        ok = bool(matches >= 1 or ratio >= 0.60)
    else:
        ok = bool(matches >= 2 or ratio >= 0.46)

    stats = {
        'ref_lines': len(ref_keys),
        'precise_lines': len(precise_keys),
        'matches': matches,
        'ratio': float(ratio),
    }
    return ok, stats, ('ok' if ok else 'text-evidence-mismatch')


def _precise_clock_granularity(precise_lrc):
    """Measure CJK token granularity; smaller average span is finer evidence."""
    cjk_re = re.compile(r'[\u3400-\u4dbf\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]')
    spans = []
    tokens = 0
    for raw in str(precise_lrc or '').replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        stripped = raw.strip('\ufeff').strip()
        if not stripped:
            continue
        times, body = _split_lrc_leading_timestamps(stripped)
        if not times:
            continue
        plain, events = _parse_enhanced_body(body, 0)
        if not events:
            continue
        tokens += len(events)
        for ev in events:
            end_idx = int(ev[1])
            start_idx = int(ev[3]) if len(ev) >= 4 else 0
            seg = plain[max(0, start_idx):max(0, end_idx)]
            n = sum(1 for ch in seg if cjk_re.match(ch))
            if n:
                spans.append(n)
    if not spans:
        return {'tokens': tokens, 'cjk_tokens': 0, 'avg_cjk_span': 0.0, 'multi_ratio': 0.0}
    return {
        'tokens': tokens,
        'cjk_tokens': len(spans),
        'avg_cjk_span': float(sum(spans)) / len(spans),
        'multi_ratio': float(sum(1 for n in spans if n > 1)) / len(spans),
    }


def _precise_clock_needs_finer_candidate(precise_lrc):
    stats = _precise_clock_granularity(precise_lrc)
    return bool(
        FLOW_STACK_ENABLED and
        stats['cjk_tokens'] >= 6 and
        (stats['avg_cjk_span'] >= 1.45 or stats['multi_ratio'] >= 0.35)
    )


def _precise_clock_is_finer(candidate_lrc, baseline_lrc):
    cand = _precise_clock_granularity(candidate_lrc)
    base = _precise_clock_granularity(baseline_lrc)
    if cand['cjk_tokens'] < 6 or base['cjk_tokens'] < 6:
        return False, cand, base
    finer = bool(
        cand['avg_cjk_span'] + 0.18 <= base['avg_cjk_span'] or
        cand['cjk_tokens'] >= max(8, int(base['cjk_tokens'] * 1.25))
    )
    return finer, cand, base


def _add_lrc_offset(lrc_text, delta_ms):
    """Combine a new global offset with any existing Enhanced-LRC offset tag."""
    delta_ms = int(delta_ms or 0)
    if not delta_ms:
        return str(lrc_text or '')
    raw_lines = str(lrc_text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n')
    existing = 0
    kept = []
    for raw in raw_lines:
        m = _LRC_OFFSET_RE.match(raw.strip('\ufeff').strip())
        if m:
            try:
                existing = int(m.group(1))
            except Exception:
                existing = 0
            continue
        kept.append(raw)
    combined = max(-3600000, min(3600000, existing + delta_ms))
    return f'[offset:{combined}]\n' + '\n'.join(kept).strip()


# ==================== 歌词搜索引擎 ====================
class LyricSearchEngine:
    HEADERS = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        'Accept': 'application/json,text/plain,*/*'
    }
    last_error = ""
    _provider_meta_local = threading.local()
    _cancel_local = threading.local()
    _precise_clock_cache = []
    _precise_clock_cache_loaded = False
    # H95F10: transient exact-pair handoff from main bilingual search to the display
    # translation lane.  This avoids immediately re-querying the same provider and ensures
    # the sidecar consumes the translation that was validated together with the main lyric.
    _bilingual_pair_cache = OrderedDict()
    _bilingual_pair_cache_lock = threading.Lock()
    _bilingual_pair_cache_limit = 24


    @classmethod
    def _bilingual_pair_key(cls, song_name, artist, source):
        return (_clean_name(song_name), _clean_name(artist), str(source or '').strip())

    @classmethod
    def _remember_bilingual_pair(cls, song_name, artist, source, duration_ms, main_lrc, translation_lrc):
        main_lrc = str(main_lrc or '').strip(); translation_lrc = str(translation_lrc or '').strip()
        if not main_lrc or not translation_lrc or str(source or '') not in ('网易云','QQ音乐','酷狗'):
            return False
        key = cls._bilingual_pair_key(song_name, artist, source)
        row = {
            'duration': int(duration_ms or 0),
            'main_sha256': hashlib.sha256(main_lrc.encode('utf-8')).hexdigest(),
            'translation': translation_lrc,
            'saved_mono': time.monotonic(),
        }
        try:
            with cls._bilingual_pair_cache_lock:
                cls._bilingual_pair_cache[key] = row
                cls._bilingual_pair_cache.move_to_end(key)
                while len(cls._bilingual_pair_cache) > int(cls._bilingual_pair_cache_limit):
                    cls._bilingual_pair_cache.popitem(last=False)
            return True
        except Exception:
            return False

    @classmethod
    def _cached_bilingual_pair_translation(cls, song_name, artist, source, duration_ms=0, main_lrc=''):
        key = cls._bilingual_pair_key(song_name, artist, source)
        try:
            with cls._bilingual_pair_cache_lock:
                row = dict(cls._bilingual_pair_cache.get(key) or {})
                if row:
                    cls._bilingual_pair_cache.move_to_end(key)
        except Exception:
            row = {}
        if not row:
            return ''
        expected = int(duration_ms or 0); cached = int(row.get('duration') or 0)
        if expected and cached and abs(expected-cached) > max(3500, int(max(expected,cached)*0.025)):
            return ''
        main_lrc = str(main_lrc or '').strip()
        if main_lrc and str(row.get('main_sha256') or '') != hashlib.sha256(main_lrc.encode('utf-8')).hexdigest():
            return ''
        return str(row.get('translation') or '')


    @classmethod
    def _set_provider_meta(cls, **meta):
        try:
            cls._provider_meta_local.value = dict(meta or {})
        except Exception:
            pass

    @classmethod
    def last_provider_meta(cls):
        try:
            value = getattr(cls._provider_meta_local, 'value', None)
            return dict(value) if isinstance(value, dict) else {}
        except Exception:
            return {}

    @classmethod
    def _set_cancel_check(cls, fn=None):
        try:
            cls._cancel_local.fn = fn if callable(fn) else None
        except Exception:
            pass

    @classmethod
    def _is_cancelled(cls):
        try:
            fn = getattr(cls._cancel_local, 'fn', None)
            return bool(callable(fn) and fn())
        except Exception:
            return False

    @classmethod
    def _load_precise_clock_cache(cls):
        if cls._precise_clock_cache_loaded:
            return
        cls._precise_clock_cache_loaded = True
        if not EVIDENCE_CLOCK_ENABLED:
            return
        try:
            with open(PRECISE_CLOCK_CACHE_FILE, 'r', encoding='utf-8') as f:
                obj = json.load(f)
            rows = obj.get('entries', []) if isinstance(obj, dict) else obj
            now_epoch = time.time()
            keep = []
            for row in rows if isinstance(rows, list) else []:
                if not isinstance(row, dict):
                    continue
                lyric = str(row.get('lyric') or '')
                if not lyric or not _LRC_INLINE_TIME_RE.search(lyric):
                    continue
                provider_name = str(row.get('provider') or '').lower()
                if FLOW_STACK_ENABLED and provider_name in ('kugou-krc', 'netease-alt-yrc-klyric'):
                    if not bool(row.get('verified_native_lrc')):
                        try:
                            write_error_log('逐字时钟缓存旧未验证增强已丢弃', detail=f'song={row.get("song","")} | provider={provider_name}')
                        except Exception:
                            pass
                        continue
                    sane, _stats, _why = _precise_clock_basic_sanity(lyric, row.get('duration') or 0)
                    if not sane:
                        try:
                            write_error_log(
                                '逐字时钟缓存坏增强已丢弃',
                                detail=f'song={row.get("song","")} | provider={provider_name} | reason={_why} | stats={_stats}'
                            )
                        except Exception:
                            pass
                        continue
                saved = float(row.get('saved_at') or 0.0)
                if saved and now_epoch - saved > 120 * 86400:
                    continue
                keep.append(row)
            cls._precise_clock_cache = keep[-24:]
        except FileNotFoundError:
            cls._precise_clock_cache = []
        except Exception as exc:
            cls._precise_clock_cache = []
            write_error_log('逐字时钟缓存读取失败', exc, detail=PRECISE_CLOCK_CACHE_FILE)

    @classmethod
    def _save_precise_clock_cache(cls):
        if not EVIDENCE_CLOCK_ENABLED:
            return
        try:
            os.makedirs(os.path.dirname(PRECISE_CLOCK_CACHE_FILE), exist_ok=True)
            tmp = PRECISE_CLOCK_CACHE_FILE + '.tmp'
            rows = []
            for row in cls._precise_clock_cache[-24:]:
                clean = dict(row)
                clean.pop('mono', None)
                rows.append(clean)
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump({'version': 2, 'entries': rows}, f, ensure_ascii=False)
            os.replace(tmp, PRECISE_CLOCK_CACHE_FILE)
        except Exception as exc:
            write_error_log('逐字时钟缓存保存失败', exc, detail=PRECISE_CLOCK_CACHE_FILE)

    @classmethod
    def _remember_precise_clock(cls, song_name, artist, duration_ms, lyric, provider, provider_id=None, verification=None):
        if not lyric or not _LRC_INLINE_TIME_RE.search(str(lyric)):
            return
        if FLOW_STACK_ENABLED and str(provider or '').lower() == 'kugou-krc':
            sane, stats, reason = _precise_clock_basic_sanity(lyric, duration_ms)
            if not sane:
                write_error_log(
                    '拒绝缓存低证据KRC',
                    detail=f'song={song_name} | reason={reason} | stats={stats}'
                )
                return
        cls._load_precise_clock_cache()
        entry = {
            'song': str(song_name or ''),
            'artist': str(artist or ''),
            'duration': int(duration_ms or 0),
            'lyric': str(lyric),
            'provider': str(provider or ''),
            'provider_id': provider_id,
            'mono': time.monotonic(),
            'saved_at': time.time(),
        }
        if verification:
            entry['verified_native_lrc'] = True
            entry['verification'] = {
                'matches': int((verification or {}).get('matches') or 0),
                'coverage': float((verification or {}).get('coverage') or 0.0),
                'spread': int((verification or {}).get('spread') or 0),
                'drift_ms': int((verification or {}).get('drift_ms') or 0),
                'median_delta': int((verification or {}).get('median_delta') or 0),
                'native_song_id': str((verification or {}).get('native_song_id') or ''),
                'phase_policy': str((verification or {}).get('phase_policy') or ''),
                'alignment_preview_shift_ms': int((verification or {}).get('alignment_preview_shift_ms') or 0),
            }
        key = (_clean_name(entry['song']), int(entry['duration'] or 0))
        cls._precise_clock_cache = [
            x for x in cls._precise_clock_cache
            if (_clean_name(x.get('song','')), int(x.get('duration') or 0)) != key
            or not _artist_alias_match(entry.get('artist',''), x.get('artist',''))[0]
        ]
        cls._precise_clock_cache.append(entry)
        cls._precise_clock_cache = cls._precise_clock_cache[-24:]
        cls._save_precise_clock_cache()

    @classmethod
    def _forget_precise_clock(cls, song_name, artist, duration_ms, provider=None):
        cls._load_precise_clock_cache()
        q_song = _clean_name(song_name)
        q_duration = int(duration_ms or 0)
        kept = []
        removed = 0
        for entry in cls._precise_clock_cache:
            same_song = _clean_name(entry.get('song','')) == q_song
            d = abs(q_duration - int(entry.get('duration') or 0)) if q_duration and entry.get('duration') else 0
            same_duration = d <= max(2200, int(max(q_duration, int(entry.get('duration') or 0)) * 0.015))
            artist_ok = (not str(artist or '').strip()) or _artist_alias_match(artist, entry.get('artist',''))[0]
            provider_ok = (not provider) or str(entry.get('provider') or '') == str(provider)
            if same_song and same_duration and artist_ok and provider_ok:
                removed += 1
                continue
            kept.append(entry)
        if removed:
            cls._precise_clock_cache = kept
            cls._save_precise_clock_cache()
        return removed

    @classmethod
    def _cached_precise_clock(cls, song_name, artist, duration_ms):
        if not CLOCK_SOURCE_FIRST_ENABLED:
            return '', None
        cls._load_precise_clock_cache()
        q_song = _clean_name(song_name)
        q_duration = int(duration_ms or 0)
        best = None
        for entry in reversed(cls._precise_clock_cache):
            if _clean_name(entry.get('song','')) != q_song:
                continue
            d = abs(q_duration - int(entry.get('duration') or 0)) if q_duration and entry.get('duration') else 0
            limit = max(1800, int(max(q_duration, int(entry.get('duration') or 0)) * 0.012))
            artist_ok = True
            if EVIDENCE_CLOCK_ENABLED and str(artist or '').strip():
                artist_ok = bool(str(entry.get('artist') or '').strip()) and _artist_alias_match(artist, entry.get('artist',''))[0]
            if d <= limit and artist_ok:
                best = entry
                break
        if best and FLOW_STACK_ENABLED and str(best.get('provider') or '').lower() in ('kugou-krc', 'netease-alt-yrc-klyric'):
            provider_name = str(best.get('provider') or '').lower()
            if not bool(best.get('verified_native_lrc')):
                cls._forget_precise_clock(song_name, artist, duration_ms, provider=provider_name)
                write_error_log('跨源逐字时钟缓存拒绝', detail=f'song={song_name} | provider={provider_name} | reason=unverified-native-lrc')
                best = None
            else:
                sane, stats, reason = _precise_clock_basic_sanity(best.get('lyric',''), best.get('duration') or q_duration)
                if not sane:
                    cls._forget_precise_clock(song_name, artist, duration_ms, provider=provider_name)
                    write_error_log(
                        '跨源逐字时钟缓存拒绝',
                        detail=f'song={song_name} | provider={provider_name} | reason={reason} | stats={stats}'
                    )
                    best = None
        if best:
            write_error_log(
                '跨源逐字时钟缓存命中',
                detail=(
                    f'song={song_name} | provider={best.get("provider")} | '
                    f'duration_delta={abs(q_duration-int(best.get("duration") or 0))}ms'
                )
            )
            return best.get('lyric',''), best
        return '', None

    @classmethod
    def _cached_verified_enhancement(cls, song_name, artist, duration_ms, native_song_id=None):
        """Return only clocks previously verified against the native song's LRC."""
        if not CLOCK_SOURCE_FIRST_ENABLED:
            return '', None
        cls._load_precise_clock_cache()
        q_song = _clean_name(song_name)
        q_duration = int(duration_ms or 0)
        for entry in reversed(cls._precise_clock_cache):
            provider = str(entry.get('provider') or '').lower()
            if provider not in ('netease-alt-yrc-klyric', 'kugou-krc') or not bool(entry.get('verified_native_lrc')):
                continue
            if _clean_name(entry.get('song','')) != q_song:
                continue
            e_duration = int(entry.get('duration') or 0)
            d = abs(q_duration - e_duration) if q_duration and e_duration else 0
            limit = max(1000, int(max(q_duration, e_duration) * 0.005))
            if d > limit:
                continue
            if str(artist or '').strip() and not _artist_alias_match(artist, entry.get('artist',''))[0]:
                continue
            verification = dict(entry.get('verification') or {})
            verified_id = str(verification.get('native_song_id') or '')
            if provider == 'kugou-krc' and str(verification.get('phase_policy') or '') not in {
                'raw-krc-v84', 'aligned-large-phase-rescue-v94'
            }:
                try:
                    legacy_shift = abs(int(verification.get('median_delta') or 0))
                except Exception:
                    legacy_shift = 999999
                if legacy_shift >= 35:
                    cls._forget_precise_clock(song_name, artist, duration_ms, provider=provider)
                    write_error_log(
                        '已验证逐字增强缓存失效',
                        detail=(
                            f'song={song_name} | provider={provider} | reason=legacy-aligned-krc-cache | '
                            f'legacy_shift={legacy_shift}ms'
                        )
                    )
                    continue
            if native_song_id is not None and verified_id and verified_id != str(native_song_id):
                continue
            if native_song_id is not None and not verified_id:
                continue
            sane, stats, reason = _precise_clock_basic_sanity(entry.get('lyric',''), e_duration or q_duration)
            if not sane:
                cls._forget_precise_clock(song_name, artist, duration_ms, provider=provider)
                write_error_log('已验证逐字增强缓存失效', detail=f'song={song_name} | provider={provider} | reason={reason} | stats={stats}')
                continue
            write_error_log('已验证逐字增强缓存命中', detail=f'song={song_name} | provider={provider} | duration_delta={d}ms')
            return str(entry.get('lyric') or ''), entry
        return '', None

    @staticmethod
    def _r2_line_only_payload(payload):
        """Downgrade a precise payload to ordinary line timing without inventing clocks."""
        text = str(payload or '')
        if not text.strip():
            return ''
        try:
            events = parse_lrc(text, diagnostics=False)
            out = []
            for row in list(events or []):
                if not row or len(row) < 2:
                    continue
                at = max(0, int(row[0] or 0))
                body = str(row[1] or '').strip()
                if not body:
                    continue
                minute = at // 60000
                sec_ms = at % 60000
                second = sec_ms // 1000
                centi = (sec_ms % 1000) // 10
                out.append(f'[{minute:02d}:{second:02d}.{centi:02d}]{body}')
            if out:
                return '\n'.join(out)
        except Exception:
            pass
        try:
            return _LRC_INLINE_TIME_RE.sub('', text)
        except Exception:
            return text

    @classmethod
    def _fail(cls, source, exc=None, detail=""):
        if exc is not None:
            cls.last_error = f"{source}：{type(exc).__name__}: {exc}"
        else:
            cls.last_error = f"{source}：{detail or '没有匹配结果'}"
        # Provider HTTP timeouts are an expected degraded-network outcome, not a program
        # crash. Keep the useful endpoint/error summary but do not dump requests/urllib3's
        # multi-page traceback into the runtime log. Unexpected exceptions still retain the
        # full traceback through the historical write_error_log(exc) path.
        is_timeout = False
        is_expected_upstream = False
        upstream_status = 0
        if exc is not None:
            try:
                is_timeout = isinstance(exc, (TimeoutError, requests.exceptions.Timeout))
            except Exception:
                is_timeout = isinstance(exc, TimeoutError)
            try:
                is_expected_upstream = isinstance(exc, _core_CircuitOpen)
            except Exception:
                is_expected_upstream = False
            try:
                if isinstance(exc, requests.exceptions.HTTPError):
                    upstream_status = int(getattr(getattr(exc, 'response', None), 'status_code', 0) or 0)
                    is_expected_upstream = is_expected_upstream or upstream_status == 429 or upstream_status >= 500
            except Exception:
                pass
        if is_timeout:
            extra = f' | {detail}' if str(detail or '').strip() else ''
            write_error_log(
                f"歌词搜索网络超时/{source}",
                detail=f'{type(exc).__name__}: {exc}{extra} | traceback=suppressed-expected-network-timeout'
            )
        elif is_expected_upstream:
            extra = f' | {detail}' if str(detail or '').strip() else ''
            write_error_log(
                f"歌词搜索上游暂不可用/{source}",
                detail=(f'{type(exc).__name__}: {exc}{extra} | status={upstream_status or "circuit"} | '
                        'traceback=suppressed-expected-upstream-failure')
            )
        else:
            write_error_log(f"歌词搜索失败/{source}", exc, detail)
        return None, None, 0

    @staticmethod
    def _netease_eapi_payload(api_path, payload):
        if not PYCRYPTODOME_AVAILABLE or AES is None or _crypto_pad is None:
            raise RuntimeError(f"PyCryptodome unavailable: {PYCRYPTODOME_ERROR or 'unknown error'}")
        text = json.dumps(payload, ensure_ascii=False, separators=(',', ':'))
        message = f"nobody{api_path}use{text}md5forencrypt"
        digest = hashlib.md5(message.encode('utf-8')).hexdigest()
        blob = f"{api_path}-36cd479b6b5-{text}-36cd479b6b5-{digest}".encode('utf-8')
        cipher = AES.new(b'e82ckenh8dichen8', AES.MODE_ECB)
        encrypted = cipher.encrypt(_crypto_pad(blob, 16))
        return {'params': encrypted.hex().upper()}

    @staticmethod
    def _netease_client_context():
        """Build the client-shaped header/cookie context used by modern EAPI.

        The word-lyric endpoint is unusually sensitive to request context: a bare EAPI
        request can still return ordinary LRC while omitting YRC. Keep the identity
        anonymous and process-local; no login cookie or stable machine identifier is used.
        """
        now = int(time.time())
        request_id = f"{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        header = {
            'osver': '14',
            'deviceId': _NETEASE_PROBE_DEVICE_ID,
            'os': 'android',
            'appver': '9.1.40',
            'versioncode': '9014000',
            'mobilename': 'LimbusLyric',
            'buildver': str(now),
            'resolution': '1920x1080',
            '__csrf': '',
            'channel': 'netease',
            'requestId': request_id,
        }
        cookies = dict(header)
        cookies['NMTID'] = '00E' + hashlib.md5(
            f'{_NETEASE_PROBE_DEVICE_ID}-{time.time_ns()}'.encode('utf-8')
        ).hexdigest()[:29]
        cookies['__remember_me'] = 'true'
        return header, cookies

    @staticmethod
    def _fetch_netease_word_lyric(song_id, allow_recovery=True):
        """Best-effort NetEase word timing without turning no-YRC songs into slow fetches.

        The proven v1.8.9 bare EAPI request stays first. Recovery profiles are attempted
        only when that response *omits the yrc field entirely*. If yrc is present but empty,
        treat it as provider-declared no-word-timing and immediately use ordinary LRC.
        """
        if not WORD_TIMING_ENABLED:
            return '', None

        api_path = '/api/song/lyric/v1'
        base_payload = {
            'id': int(song_id), 'cp': False,
            'tv': 0, 'lv': 0, 'rv': 0, 'kv': 0,
            'yv': 0, 'ytv': 0, 'yrv': 0,
        }

        def request_eapi(use_client_ctx):
            payload = dict(base_payload)
            cookies = {}
            headers = {
                **LyricSearchEngine.HEADERS,
                'Content-Type': 'application/x-www-form-urlencoded',
                'Origin': 'https://music.163.com',
                'Referer': 'https://music.163.com/',
            }
            if use_client_ctx:
                client_header, cookies = LyricSearchEngine._netease_client_context()
                payload['header'] = client_header
                headers['User-Agent'] = (
                    'NeteaseMusic/9.1.40.9014000; '
                    'Dalvik/2.1.0 (Linux; U; Android 14; LimbusLyric)'
                )
            else:
                headers['User-Agent'] = (
                    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
                    'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36'
                )
            data = LyricSearchEngine._netease_eapi_payload(api_path, payload)
            resp = requests.post(
                'https://interface3.music.163.com/eapi/song/lyric/v1',
                data=data, headers=headers, cookies=cookies, timeout=(2.8, 4.0)
            )
            resp.raise_for_status()
            return resp.json()

        def extract_provider_clock(obj, profile_name):
            if not isinstance(obj, dict):
                return ''
            yrc = str((obj.get('yrc') or {}).get('lyric') or '')
            if yrc.strip():
                enhanced = _yrc_to_enhanced_lrc(yrc)
                if enhanced.strip():
                    write_error_log(
                        '网易云逐字歌词命中',
                        detail=(
                            f'song_id={song_id} | yrc_chars={len(yrc)} | '
                            f'enhanced_chars={len(enhanced)} | profile={profile_name}'
                        )
                    )
                    return enhanced
            # Legacy karaoke timing is still exposed for a subset of songs that have no
            # YRC. It is a real provider clock, not a heuristic fallback.
            klyric = str((obj.get('klyric') or {}).get('lyric') or '') if RHYTHM_GROUPS_ENABLED else ''
            if klyric.strip():
                enhanced = _klyric_to_enhanced_lrc(klyric)
                if enhanced.strip():
                    write_error_log(
                        '网易云KLYRIC逐词歌词命中',
                        detail=(
                            f'song_id={song_id} | klyric_chars={len(klyric)} | '
                            f'enhanced_chars={len(enhanced)} | profile={profile_name}'
                        )
                    )
                    return enhanced
            return ''

        best_obj = None
        last_exc = None
        try:
            best_obj = request_eapi(False)
            enhanced = extract_provider_clock(best_obj, 'bare-v189')
            if enhanced:
                return enhanced, best_obj
        except Exception as exc:
            last_exc = exc
            write_error_log(
                '网易云逐字EAPI配置探针失败', exc,
                detail=f'song_id={song_id} | profile=bare-v189'
            )

        yrc_field_present = isinstance(best_obj, dict) and 'yrc' in best_obj

        # Only a missing field suggests request-context suppression. An explicitly empty
        # yrc field is treated as a genuine coverage gap and does not pay extra network
        # latency on every track.
        if allow_recovery and WORD_CLOCK_RECOVERY_ENABLED and not yrc_field_present:
            try:
                ctx_obj = request_eapi(True)
                enhanced = extract_provider_clock(ctx_obj, 'client-context')
                if enhanced:
                    return enhanced, ctx_obj
                if isinstance(ctx_obj, dict) and str((ctx_obj.get('lrc') or {}).get('lyric') or ''):
                    best_obj = ctx_obj
            except Exception as exc:
                last_exc = exc
                write_error_log(
                    '网易云逐字EAPI配置探针失败', exc,
                    detail=f'song_id={song_id} | profile=client-context'
                )

            # Last bounded recovery path. Current API wrappers document yrc on lyric
            # responses, so inspect the public route too if EAPI omitted the field.
            try:
                public_resp = requests.get(
                    'https://music.163.com/api/song/lyric',
                    params={
                        'id': int(song_id), 'lv': 1, 'kv': (-1 if RHYTHM_GROUPS_ENABLED else 1), 'tv': -1,
                        'yv': 0, 'ytv': 0, 'rv': 0, 'yrv': 0,
                    },
                    headers=LyricSearchEngine.HEADERS, timeout=(2.8, 4.0)
                )
                public_resp.raise_for_status()
                public_obj = public_resp.json()
                enhanced = extract_provider_clock(public_obj, 'public-yrc-recovery')
                if enhanced:
                    return enhanced, public_obj
                if isinstance(public_obj, dict) and str((public_obj.get('lrc') or {}).get('lyric') or ''):
                    best_obj = public_obj
            except Exception as exc:
                last_exc = exc
                write_error_log('网易云公开逐字恢复探针失败', exc, detail=f'song_id={song_id}')

        if isinstance(best_obj, dict):
            try:
                yrc_obj = best_obj.get('yrc') or {}
                klyric_obj = best_obj.get('klyric') or {}
                lrc_chars = len(str((best_obj.get('lrc') or {}).get('lyric') or ''))
                klyric_chars = len(str(klyric_obj.get('lyric') or ''))
                write_error_log(
                    '网易云逐字歌词未返回，使用普通LRC',
                    detail=(
                        f'song_id={song_id} | code={best_obj.get("code")} | '
                        f'keys={sorted(best_obj.keys())} | yrc_present={int("yrc" in best_obj)} | '
                        f'yrc_version={yrc_obj.get("version")} | klyric_chars={klyric_chars} | lrc_chars={lrc_chars} | '
                        f'recovery={int(bool(allow_recovery and WORD_CLOCK_RECOVERY_ENABLED))}'
                    )
                )
            except Exception:
                pass
            return '', best_obj

        if last_exc is not None:
            write_error_log('网易云逐字歌词探针失败，回退普通LRC', last_exc, detail=f'song_id={song_id}')
        return '', None

    @staticmethod
    def _strict_timing_match(song_name, artist, duration_ms, candidate):
        """Return (ok, score, duration_delta) for conservative cross-provider timing reuse."""
        q_song = _clean_name(song_name)
        c_song = _clean_name(candidate.get('name', ''))
        q_artist = _clean_name(artist)
        c_artist = _clean_name(_artist_text(candidate))
        c_duration = int(candidate.get('duration', 0) or candidate.get('dt', 0) or 0)
        d = abs(int(duration_ms or 0) - c_duration) if duration_ms and c_duration else 10**9

        song_exact = bool(q_song and c_song and q_song == c_song)
        song_contained = bool(q_song and c_song and (q_song in c_song or c_song in q_song))
        if EVIDENCE_CLOCK_ENABLED:
            artist_ok, artist_alias = _artist_alias_match(artist, _artist_text(candidate))
        else:
            artist_ok = (not q_artist) or bool(c_artist and (q_artist == c_artist or q_artist in c_artist or c_artist in q_artist))
            artist_alias = ''
        duration_limit = max(1800, int(max(int(duration_ms or 0), c_duration) * 0.012))
        duration_ok = d <= duration_limit
        score = (100 if song_exact else 65 if song_contained else 0) + (80 if artist_ok and q_artist else 20 if not q_artist else 0)
        if EVIDENCE_CLOCK_ENABLED and artist_alias:
            score += min(20, len(artist_alias) * 2)
        return bool((song_exact or song_contained) and artist_ok and duration_ok), score, d

    @staticmethod
    def _fetch_strict_netease_word_match(song_name, artist, duration_ms):
        """Borrow only a very strongly matched NetEase YRC clock for QQ fallback."""
        if not (WORD_TIMING_ENABLED and WORD_CLOCK_RECOVERY_ENABLED and CROSS_SOURCE_TIMING_ENABLED):
            return '', None
        try:
            keyword = f"{song_name} {artist}".strip()
            def _search_kw(kw):
                url = f"https://music.163.com/api/search/get?s={urllib.parse.quote(kw)}&type=1&limit=12"
                resp = requests.get(url, headers=LyricSearchEngine.HEADERS, timeout=(3.0, 5.5))
                resp.raise_for_status()
                return resp.json().get('result', {}).get('songs', [])
            songs = _search_kw(keyword)
            best = None
            best_score = -1
            best_delta = None
            for candidate in songs:
                ok, score, delta = LyricSearchEngine._strict_timing_match(
                    song_name, artist, duration_ms, candidate
                )
                if ok and (score > best_score or (score == best_score and (best_delta is None or delta < best_delta))):
                    best = candidate; best_score = score; best_delta = delta
            if not best and artist:
                # Long multi-alias artist strings can make the provider search return no
                # useful row even when the exact title/duration exists. Retry title-only;
                # strict title+duration+artist validation still runs on every candidate.
                for candidate in _search_kw(str(song_name or '').strip()):
                    ok, score, delta = LyricSearchEngine._strict_timing_match(
                        song_name, artist, duration_ms, candidate
                    )
                    if ok and (score > best_score or (score == best_score and (best_delta is None or delta < best_delta))):
                        best = candidate; best_score = score; best_delta = delta
            if not best:
                write_error_log(
                    'QQ跨源逐字时钟未匹配',
                    detail=f'song={song_name} | artist={artist} | duration={duration_ms} | title_retry={int(bool(artist))}'
                )
                return '', None
            enhanced, _obj = LyricSearchEngine._fetch_netease_word_lyric(best.get('id'))
            if enhanced:
                write_error_log(
                    'QQ跨源逐字时钟命中',
                    detail=(
                        f'netease_song_id={best.get("id")} | title={best.get("name", "")} | '
                        f'artist={_artist_text(best)} | duration_delta={best_delta}ms'
                    )
                )
                return enhanced, best
            write_error_log(
                'QQ跨源匹配歌曲无逐字时钟',
                detail=f'netease_song_id={best.get("id")} | duration_delta={best_delta}ms'
            )
            return '', best
        except Exception as exc:
            write_error_log('QQ跨源逐字时钟探针失败', exc, detail=f'song={song_name} | artist={artist}')
            return '', None

    @staticmethod
    def _fetch_netease_alternate_word_match(search_rows, current_song_id, song_name, artist, duration_ms):
        """Try at most two already-returned NetEase versions before crossing providers.

        This does not perform another catalog search. Candidates must pass strict title/artist
        identity and a tighter 0.5% / 1000ms duration window, then only the inexpensive bare
        current-ID word endpoint is tried. The caller still must verify timing against the
        current song's ordinary LRC before accepting or caching the clock.
        """
        if not (NETEASE_ALT_NATIVE_PRECISE_ENABLED and WORD_TIMING_ENABLED and WORD_CLOCK_RECOVERY_ENABLED):
            return '', None
        ranked = []
        for row in list(search_rows or []):
            try:
                if str(row.get('id')) == str(current_song_id):
                    continue
                ok, score, delta = LyricSearchEngine._strict_timing_match(song_name, artist, duration_ms, row)
                c_duration = int(row.get('duration', 0) or row.get('dt', 0) or 0)
                tight_limit = max(1000, int(max(int(duration_ms or 0), c_duration) * 0.005))
                if ok and delta <= tight_limit:
                    ranked.append((int(score), -int(delta), row))
            except Exception:
                continue
        ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
        attempts = 0
        for _score, _neg_delta, row in ranked[:2]:
            if LyricSearchEngine._is_cancelled():
                return '', None
            attempts += 1
            try:
                enhanced, _obj = LyricSearchEngine._fetch_netease_word_lyric(row.get('id'), allow_recovery=False)
                if enhanced and _LRC_INLINE_TIME_RE.search(enhanced):
                    out = dict(row)
                    out['_clock_provider'] = 'netease-alt-yrc-klyric'
                    out['_duration_delta_ms'] = abs(int(duration_ms or 0) - int(row.get('duration',0) or row.get('dt',0) or 0))
                    write_error_log('网易云同平台候选逐字命中', detail=(
                        f'current_id={current_song_id} | alternate_id={row.get("id")} | '
                        f'duration_delta={out["_duration_delta_ms"]}ms | attempts={attempts}'
                    ))
                    return enhanced, out
            except Exception as exc:
                write_error_log('网易云同平台候选逐字探针失败', exc, detail=f'current_id={current_song_id} | alternate_id={row.get("id")}')
        if ranked:
            write_error_log('网易云同平台候选无可用逐字', detail=f'current_id={current_song_id} | candidates={len(ranked)} | attempted={min(2,len(ranked))}')
        return '', None

    @staticmethod
    def _fetch_strict_kugou_word_match(song_name, artist, duration_ms, reference_lrc='', conservative_duration=False):
        """Best-effort strict Kugou KRC bridge for songs missing YRC/KLYRIC.

        v1.8.9.9 never disables TLS verification. It tries current HTTPS search hosts in
        order and validates title + artist alias + duration before trusting a FileHash.
        """
        if not (CLOCK_SOURCE_FIRST_ENABLED and WORD_TIMING_ENABLED and CROSS_SOURCE_TIMING_ENABLED):
            return '', None
        if LyricSearchEngine._is_cancelled():
            return '', None

        def clean_markup(v):
            return html.unescape(re.sub(r'<[^>]+>', '', str(v or ''))).strip()

        def norm_row(c):
            name = clean_markup(c.get('SongName') or c.get('songname') or c.get('filename','').split(' - ')[-1])
            singer = clean_markup(c.get('SingerName') or c.get('singername') or c.get('filename','').split(' - ')[0])
            raw_dur = c.get('Duration') if c.get('Duration') not in (None, '') else c.get('duration')
            try:
                raw_dur = float(raw_dur or 0)
                dur = int(raw_dur if raw_dur > 10000 else raw_dur * 1000)
            except Exception:
                dur = 0
            return {
                'songname': name,
                'singername': singer,
                'duration_ms': dur,
                'hash': c.get('FileHash') or c.get('filehash') or c.get('hash') or c.get('320hash') or c.get('sqhash'),
                'raw': c,
            }

        def search_rows(keyword):
            endpoints = [
                ('songsearch-v2', 'https://songsearch.kugou.com/song_search_v2', {
                    'keyword': keyword, 'page': 1, 'pagesize': 12, 'platform': 'WebFilter',
                    'format': 'json', 'filter': 2, 'iscorrection': 1, 'privilege_filter': 0,
                }, 'v2'),
                ('msearch-v3', 'https://msearch.kugou.com/api/v3/search/song', {
                    'format': 'json', 'keyword': keyword, 'page': 1, 'pagesize': 12,
                }, 'v3'),
                ('mobilecdn-v3', 'https://mobilecdn.kugou.com/api/v3/search/song', {
                    'format': 'json', 'keyword': keyword, 'page': 1, 'pagesize': 12,
                }, 'v3'),
            ] if EVIDENCE_CLOCK_ENABLED else [
                ('mobilecdn-v3', 'https://mobilecdn.kugou.com/api/v3/search/song', {
                    'format': 'json', 'keyword': keyword, 'page': 1, 'pagesize': 10,
                }, 'v3')
            ]
            for label, url, params, shape in endpoints:
                if LyricSearchEngine._is_cancelled():
                    return []
                try:
                    r = requests.get(
                        url, params=params,
                        headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                        timeout=(2.4, 4.2)
                    )
                    r.raise_for_status()
                    obj = r.json()
                    data = obj.get('data') or {}
                    rows = (data.get('lists') if shape == 'v2' else data.get('info')) or []
                    if rows:
                        if EVIDENCE_CLOCK_ENABLED:
                            write_error_log('酷狗KRC搜索入口命中', detail=f'endpoint={label} | rows={len(rows)}')
                        return [norm_row(x) for x in rows if isinstance(x, dict)]
                except requests.exceptions.SSLError as exc:
                    if EVIDENCE_CLOCK_ENABLED:
                        write_error_log('酷狗KRC搜索入口TLS不可用', detail=f'endpoint={label} | {type(exc).__name__}: {exc}')
                    else:
                        raise
                except Exception as exc:
                    if EVIDENCE_CLOCK_ENABLED:
                        write_error_log('酷狗KRC搜索入口失败', detail=f'endpoint={label} | {type(exc).__name__}: {exc}')
                    else:
                        raise
            return []

        try:
            queries = [f"{song_name} {artist}".strip()]
            if EVIDENCE_CLOCK_ENABLED and artist:
                queries.append(str(song_name or '').strip())
            q_song = _clean_name(song_name)
            q_artist = _clean_name(artist)
            best = None; best_score = -1; best_delta = None
            for keyword in queries:
                if LyricSearchEngine._is_cancelled():
                    return '', None
                for row in search_rows(keyword):
                    c_song = _clean_name(row.get('songname'))
                    c_artist = _clean_name(row.get('singername'))
                    c_dur = int(row.get('duration_ms') or 0)
                    d = abs(int(duration_ms or 0)-c_dur) if duration_ms and c_dur else 10**9
                    title_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                    if EVIDENCE_CLOCK_ENABLED:
                        artist_ok, alias = _artist_alias_match(artist, row.get('singername',''))
                    else:
                        artist_ok = (not q_artist) or bool(c_artist and (q_artist == c_artist or q_artist in c_artist or c_artist in q_artist))
                        alias = ''
                    if conservative_duration:
                        duration_limit = max(
                            int(KUGOU_CROSS_SOURCE_DURATION_FLOOR_MS),
                            int(max(int(duration_ms or 0), c_dur) * float(KUGOU_CROSS_SOURCE_DURATION_RATIO))
                        )
                    else:
                        # Preserve the established optional QQ/cross-provider A/B tolerance.
                        duration_limit = max(2200, int(max(int(duration_ms or 0), c_dur) * 0.015))
                    dur_ok = d <= duration_limit
                    if not (title_ok and artist_ok and dur_ok):
                        continue
                    score = (100 if q_song == c_song else 65) + (80 if artist_ok and q_artist else 20) - min(30, int(d/100))
                    if alias:
                        score += min(20, len(alias) * 2)
                    if score > best_score:
                        best=row; best_score=score; best_delta=d
                if best:
                    break
            if not best:
                write_error_log('酷狗KRC逐字时钟未匹配', detail=f'song={song_name} | artist={artist} | duration={duration_ms}')
                return '', None
            song_hash = best.get('hash')
            if not song_hash:
                return '', None
            if LyricSearchEngine._is_cancelled():
                return '', None
            lyric_keyword = f"{song_name} {artist}".strip()
            lyr_search = requests.get(
                'https://lyrics.kugou.com/search',
                params={'ver':'1','man':'yes','client':'pc','keyword':lyric_keyword,'hash':song_hash},
                headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                timeout=(2.8, 5.0)
            )
            lyr_search.raise_for_status()
            candidates = lyr_search.json().get('candidates') or []
            candidate = next((x for x in candidates if x.get('id') is not None and x.get('accesskey')), None)
            if not candidate:
                return '', None
            if LyricSearchEngine._is_cancelled():
                return '', None
            dl = requests.get(
                'https://lyrics.kugou.com/download',
                params={
                    'ver':'1','client':'pc','id':candidate.get('id'),'fmt':'krc',
                    'charset':'utf8','accesskey':candidate.get('accesskey')
                },
                headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                timeout=(2.8, 5.0)
            )
            dl.raise_for_status()
            obj = dl.json()
            plain = _decode_kugou_krc_content(obj.get('content') or '')
            enhanced = _krc_plain_to_enhanced_lrc(plain)
            if enhanced and _LRC_INLINE_TIME_RE.search(enhanced):
                if FLOW_STACK_ENABLED:
                    sane, clock_stats, clock_reason = _precise_clock_basic_sanity(enhanced, duration_ms)
                    if not sane:
                        write_error_log(
                            '酷狗KRC逐字时钟证据不足已拒绝',
                            detail=(
                                f'song={song_name} | lyric_id={candidate.get("id")} | '
                                f'reason={clock_reason} | stats={clock_stats}'
                            )
                        )
                        return '', None
                    if reference_lrc:
                        ref_ok, ref_stats, ref_reason = _precise_clock_reference_evidence(reference_lrc, enhanced)
                        if not ref_ok:
                            write_error_log(
                                '酷狗KRC正文证据不符已拒绝',
                                detail=(
                                    f'song={song_name} | lyric_id={candidate.get("id")} | '
                                    f'reason={ref_reason} | matches={ref_stats.get("matches")} | '
                                    f'ratio={ref_stats.get("ratio",0.0):.3f}'
                                )
                            )
                            return '', None
                # v77: a foreign KRC is not cached here. The NetEase/QQ caller must first
                # prove it against the current provider's ordinary LRC and only then persist it.
                write_error_log(
                    '酷狗KRC逐字时钟命中',
                    detail=(
                        f'song={song_name} | hash={song_hash} | lyric_id={candidate.get("id")} | '
                        f'duration_delta={best_delta}ms | enhanced_chars={len(enhanced)}'
                    )
                )
                best_out = dict(best or {})
                best_out['_clock_provider'] = 'kugou-krc'
                return enhanced, best_out
        except Exception as exc:
            write_error_log('酷狗KRC逐字时钟探针失败', exc, detail=f'song={song_name} | artist={artist}')
        return '', None

    @staticmethod
    def _fetch_best_cross_provider_word_match(song_name, artist, duration_ms, use_cache=True):
        cached, entry = LyricSearchEngine._cached_precise_clock(song_name, artist, duration_ms) if use_cache else ('', None)
        if cached:
            if (
                FLOW_STACK_ENABLED and
                str((entry or {}).get('provider') or '').lower() != 'kugou-krc' and
                _precise_clock_needs_finer_candidate(cached)
            ):
                krc, kg = LyricSearchEngine._fetch_strict_kugou_word_match(song_name, artist, duration_ms)
                if krc:
                    finer, cand_stats, base_stats = _precise_clock_is_finer(krc, cached)
                    if finer:
                        write_error_log(
                            '跨源逐字时钟粒度升级',
                            detail=f'song={song_name} | from=cache-{(entry or {}).get("provider")} | to=kugou-krc | base={base_stats} | candidate={cand_stats}'
                        )
                        return krc, kg
            return cached, entry
        enhanced, matched = LyricSearchEngine._fetch_strict_netease_word_match(song_name, artist, duration_ms)
        if enhanced:
            if FLOW_STACK_ENABLED and _precise_clock_needs_finer_candidate(enhanced):
                krc, kg = LyricSearchEngine._fetch_strict_kugou_word_match(song_name, artist, duration_ms)
                if krc:
                    finer, cand_stats, base_stats = _precise_clock_is_finer(krc, enhanced)
                    if finer:
                        write_error_log(
                            '跨源逐字时钟粒度升级',
                            detail=f'song={song_name} | from=netease | to=kugou-krc | base={base_stats} | candidate={cand_stats}'
                        )
                        return krc, kg
            if isinstance(matched, dict):
                matched = dict(matched)
                matched['_clock_provider'] = 'netease-yrc-klyric'
            return enhanced, matched
        return LyricSearchEngine._fetch_strict_kugou_word_match(song_name, artist, duration_ms)

    @staticmethod
    def _best(items, song_name, artist, name_getter, artist_getter):
        if not items:
            return None
        return max(items, key=lambda x: _candidate_score(
            song_name, artist, name_getter(x), artist_getter(x)))

    @staticmethod
    def search_netease(song_name, artist="", trans_only=False, strict_identity=False, expected_duration_ms=0, preferred_song_id=None, preferred_duration_ms=0):
        try:
            keyword = f"{song_name} {artist}".strip()
            url = f"https://music.163.com/api/search/get?s={urllib.parse.quote(keyword)}&type=1&limit=8"
            resp = requests.get(url, headers=LyricSearchEngine.HEADERS, timeout=8)
            resp.raise_for_status()
            data = resp.json()
            songs = data.get('result', {}).get('songs', [])
            if strict_identity:
                # Cross-provider translation borrowing must not accept a same-title song
                # by another artist (or a clearly different version). Keep the matching
                # deliberately conservative because a false positive is worse than no
                # translation: translated row timestamps would be attached to the wrong audio.
                strict_rows = []
                q_song = _clean_name(song_name)
                for row in songs:
                    c_song = _clean_name(row.get('name', ''))
                    song_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                    artist_ok, _artist_alias = _artist_alias_match(artist, _artist_text(row)) if str(artist or '').strip() else (True, '')
                    c_duration = int(row.get('duration', 0) or row.get('dt', 0) or 0)
                    duration_ok = True
                    duration_delta = 0
                    if expected_duration_ms and c_duration:
                        duration_delta = abs(int(expected_duration_ms) - c_duration)
                        duration_ok = duration_delta <= max(3500, int(max(int(expected_duration_ms), c_duration) * 0.025))
                    if song_ok and artist_ok and duration_ok:
                        strict_rows.append((
                            _candidate_score(song_name, artist, row.get('name', ''), _artist_text(row)),
                            -duration_delta, row
                        ))
                song = max(strict_rows, key=lambda x: (x[0], x[1]))[2] if strict_rows else None
                if songs and not song:
                    LyricSearchEngine.last_error = '网易云：没有找到歌名、歌手和版本时长都足够一致的安全匹配'
                    write_error_log(
                        '网易云跨源翻译严格匹配拒绝',
                        detail=f'song={song_name} | artist={artist} | expected_duration={int(expected_duration_ms or 0)} | candidates={len(songs)}'
                    )
            else:
                song = None
                preferred_id = str(preferred_song_id or '').strip().split('_')[0]
                if preferred_id:
                    for row in songs:
                        if str(row.get('id') or '') != preferred_id:
                            continue
                        q_song = _clean_name(song_name); c_song = _clean_name(row.get('name',''))
                        song_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                        artist_ok, _alias = _artist_alias_match(artist, _artist_text(row)) if str(artist or '').strip() else (True, '')
                        c_duration = int(row.get('duration',0) or row.get('dt',0) or 0)
                        duration_ok = True
                        if preferred_duration_ms and c_duration:
                            duration_ok = abs(int(preferred_duration_ms) - c_duration) <= max(1200, int(max(int(preferred_duration_ms), c_duration) * 0.008))
                        if song_ok and artist_ok and duration_ok:
                            song = row
                            write_error_log('网易云Bridge song_id搜索命中', detail=(
                                f'song={song_name} | track_id={preferred_id} | duration={c_duration} | '
                                f'bridge_duration={int(preferred_duration_ms or 0)}'
                            ))
                            break
                if song is None:
                    song = LyricSearchEngine._best(
                        songs, song_name, artist,
                        lambda x: x.get('name', ''), _artist_text)
                    if preferred_id:
                        write_error_log('网易云Bridge song_id搜索未确认', detail=(
                            f'song={song_name} | track_id={preferred_id} | candidates={len(songs)} | fallback=text-rank'
                        ))
            if song:
                song_id = song['id']
                duration = song.get('duration', 0) or song.get('dt', 0) or 0
                LyricSearchEngine._set_provider_meta(
                    source='网易云', netease_song_id=str(song_id), duration_ms=int(duration or 0),
                    matched_song=str(song.get('name') or ''), matched_artist=_artist_text(song)
                )

                # A stale zero-touch generation no longer needs provider lyric work. The
                # in-flight search request itself cannot be cancelled safely, but stopping here
                # avoids the much heavier EAPI/KRC chain after rapid next/previous.
                if LyricSearchEngine._is_cancelled():
                    return None, None, duration

                # Translation-only is deliberately a separate line-level fast path.
                # Do not probe YRC/KLYRIC/KRC or any cross-provider word clock here.
                if trans_only:
                    lyric_resp = requests.get(
                        'https://music.163.com/api/song/lyric',
                        params={'id': int(song_id), 'lv': 1, 'kv': -1, 'tv': -1},
                        headers=LyricSearchEngine.HEADERS, timeout=(2.8, 5.0)
                    )
                    lyric_resp.raise_for_status()
                    lyric_obj = lyric_resp.json()
                    ordinary_lrc = str((lyric_obj.get('lrc') or {}).get('lyric') or '')
                    translated = str((lyric_obj.get('tlyric') or {}).get('lyric') or '')
                    line_translation = _translation_to_line_lrc(translated, ordinary_lrc)
                    if line_translation:
                        LyricSearchEngine.last_error = ''
                        write_error_log(
                            '网易云翻译行歌词命中',
                            detail=f'song_id={song_id} | chars={len(line_translation)} | word_probe=0'
                        )
                        return ordinary_lrc, line_translation, duration
                    LyricSearchEngine.last_error = '网易云：搜索到歌曲，但当前曲目没有可用翻译歌词'
                    write_error_log('歌词搜索失败/网易云', detail='搜索到歌曲，但当前曲目没有可用翻译歌词')
                    return ordinary_lrc or None, None, duration

                # Try the word-timing EAPI first. A successful EAPI response already
                # contains the ordinary LRC/translation fields as well, so reuse that same
                # response instead of serially issuing a second lyric request. This keeps
                # next-track auto-fetch latency close to the v1.8.8 path.
                enhanced_yrc, yrc_obj = LyricSearchEngine._fetch_netease_word_lyric(song_id)
                ordinary_ref = str((yrc_obj.get('lrc') or {}).get('lyric') or '') if isinstance(yrc_obj, dict) else ''
                native_self_stats = {}
                if enhanced_yrc and ordinary_ref:
                    enhanced_yrc, native_self_stats = _self_align_netease_native_precise(ordinary_ref, enhanced_yrc)
                    write_error_log('网易云原生逐字自相位审计', detail=(
                        f'song={song_name} | song_id={song_id} | applied={int(bool(native_self_stats.get("applied")))} | '
                        f'reason={native_self_stats.get("reason","n/a")} | matches={native_self_stats.get("matches",0)} | '
                        f'coverage={native_self_stats.get("coverage",0.0):.3f} | phase={native_self_stats.get("median_delta",0)}ms | '
                        f'spread={native_self_stats.get("spread",0)}ms | drift={native_self_stats.get("drift_ms",0)}ms | '
                        f'trend_spread={native_self_stats.get("trend_spread",0)}ms | '
                        f'suspect={int(bool(native_self_stats.get("self_phase_suspect")))} | behavior=diagnostic-arbitration'
                    ))
                if enhanced_yrc and not bool(native_self_stats.get('self_phase_suspect')):
                    LyricSearchEngine._remember_precise_clock(
                        song_name, artist, duration, enhanced_yrc, 'netease-yrc-klyric', song_id
                    )
                elif enhanced_yrc and native_self_stats.get('self_phase_suspect'):
                    write_error_log('网易云可疑原生逐字不写缓存', detail=(
                        f'song={song_name} | song_id={song_id} | phase={native_self_stats.get("median_delta",0)}ms | '
                        'preserve_verified_enhancement_cache=1'
                    ))
                if LyricSearchEngine._is_cancelled():
                    if isinstance(yrc_obj, dict):
                        ordinary_cancel = ordinary_ref
                        trans_cancel = str((yrc_obj.get('tlyric') or {}).get('lyric') or '')
                        return enhanced_yrc or ordinary_cancel or None, trans_cancel or None, duration
                    return enhanced_yrc or None, None, duration
                # v77 source hierarchy: current NetEase precise -> verified alternate NetEase
                # precise -> verified Kugou KRC -> current NetEase ordinary LRC. Any non-current
                # clock is merely an enhancement and must be proven against this song_id's own LRC.
                # v83 keeps the current native YRC/LRC comparison diagnostic. A very large,
                # coherent self-delta revokes automatic native-precise authority and opens the
                # existing verified-enhancement arbitration; it never shifts native YRC wholesale.
                native_self_suspect = bool(enhanced_yrc and native_self_stats.get('self_phase_suspect'))
                selected_precise = '' if native_self_suspect else (enhanced_yrc or '')
                selected_provider = 'netease-current-yrc-klyric' if selected_precise else ''
                selected_stats = dict(native_self_stats or {})
                selection_reason = (
                    'native-current-precise-self-suspect-arbitration'
                    if native_self_suspect
                    else ('native-current-precise' if enhanced_yrc else 'native-word-clock-missing')
                )

                can_verify_enhancement = bool(
                    (not selected_precise) and ordinary_ref and
                    len(_lrc_alignment_events(ordinary_ref)) >= 4 and
                    CLOCK_SOURCE_FIRST_ENABLED and WORD_TIMING_ENABLED and CROSS_SOURCE_TIMING_ENABLED
                )
                if can_verify_enhancement:
                    cached_enhanced, cached_entry = LyricSearchEngine._cached_verified_enhancement(
                        song_name, artist, duration, native_song_id=song_id
                    )
                    if cached_enhanced:
                        selected_precise = cached_enhanced
                        selected_provider = str((cached_entry or {}).get('provider') or 'verified-cache')
                        selected_stats = dict((cached_entry or {}).get('verification') or {})
                        selection_reason = 'verified-cache'

                # v85 latency-only optimization: KRC discovery can overlap the same-platform
                # alternate probe. Selection priority remains current-native > alternate-NetEase > KRC.
                krc_prefetch = None
                krc_prefetch_done = None
                krc_prefetch_cancel = None
                krc_prefetch_thread = None
                if (
                    can_verify_enhancement and not selected_precise and
                    NETEASE_PARALLEL_ENHANCEMENT_ENABLED and
                    NETEASE_ALT_NATIVE_PRECISE_ENABLED and NETEASE_VERIFIED_KRC_ENHANCEMENT_ENABLED
                ):
                    krc_prefetch = {'value': ('', None)}
                    krc_prefetch_done = threading.Event()
                    krc_prefetch_cancel = threading.Event()
                    parent_cancel = getattr(LyricSearchEngine._cancel_local, 'fn', None)
                    def _krc_prefetch_worker():
                        def _prefetch_cancel_check():
                            return bool(krc_prefetch_cancel.is_set() or (callable(parent_cancel) and parent_cancel()))
                        LyricSearchEngine._set_cancel_check(_prefetch_cancel_check)
                        try:
                            krc_prefetch['value'] = LyricSearchEngine._fetch_strict_kugou_word_match(
                                song_name, artist, duration, reference_lrc=ordinary_ref, conservative_duration=True
                            )
                        except Exception as exc:
                            write_error_log('网易云KRC并行预取失败', exc, detail=f'song={song_name}')
                            krc_prefetch['value'] = ('', None)
                        finally:
                            LyricSearchEngine._set_cancel_check(None)
                            krc_prefetch_done.set()
                    try:
                        krc_prefetch_thread = threading.Thread(
                            target=_krc_prefetch_worker, name='LimbusLyric-NetEaseKRCPreload', daemon=True
                        )
                        krc_prefetch_thread.start()
                        write_error_log('网易云逐字增强并行预取', detail=f'song={song_name} | alt=1 | krc=1 | priority=alt-first')
                    except Exception:
                        krc_prefetch = None; krc_prefetch_done = None; krc_prefetch_cancel = None; krc_prefetch_thread = None

                if can_verify_enhancement and not selected_precise and NETEASE_ALT_NATIVE_PRECISE_ENABLED:
                    alt_precise, alt_row = LyricSearchEngine._fetch_netease_alternate_word_match(
                        songs, song_id, song_name, artist, duration
                    )
                    if alt_precise:
                        alt_delta = int((alt_row or {}).get('_duration_delta_ms') or 0)
                        verified_alt, alt_stats, alt_reason = _verify_precise_enhancement_against_native(
                            ordinary_ref, alt_precise, provider_duration_delta_ms=alt_delta
                        )
                        write_error_log('网易云同平台逐字锚定诊断', detail=(
                            f'song={song_name} | current_id={song_id} | alternate_id={(alt_row or {}).get("id")} | '
                            f'trusted={int(bool(verified_alt))} | reason={alt_reason} | matches={alt_stats.get("matches",0)} | '
                            f'coverage={alt_stats.get("coverage",0.0):.3f} | phase={alt_stats.get("median_delta",0)}ms | '
                            f'spread={alt_stats.get("spread",0)}ms | drift={alt_stats.get("drift_ms",0)}ms'
                        ))
                        if verified_alt:
                            alt_stats = dict(alt_stats); alt_stats['native_song_id'] = str(song_id)
                            LyricSearchEngine._remember_precise_clock(
                                song_name, artist, duration, verified_alt, 'netease-alt-yrc-klyric',
                                (alt_row or {}).get('id'), verification=alt_stats
                            )
                            selected_precise = verified_alt
                            selected_provider = 'netease-alt-yrc-klyric'
                            selected_stats = alt_stats
                            selection_reason = 'verified-same-platform-alternate'
                            if krc_prefetch_cancel is not None:
                                krc_prefetch_cancel.set()

                if (
                    can_verify_enhancement and not selected_precise and
                    NETEASE_VERIFIED_KRC_ENHANCEMENT_ENABLED
                ):
                    if krc_prefetch is not None and krc_prefetch_done is not None:
                        # Old code would start this network probe only now. Waiting here cannot be
                        # slower than that path; normally most/all of the request already ran in parallel.
                        krc_prefetch_done.wait()
                        recovered_krc, _kg = krc_prefetch.get('value', ('', None))
                    else:
                        recovered_krc, _kg = LyricSearchEngine._fetch_strict_kugou_word_match(
                            song_name, artist, duration, reference_lrc=ordinary_ref, conservative_duration=True
                        )
                    if recovered_krc:
                        kg_duration = int((_kg or {}).get('duration_ms') or 0)
                        kg_delta = abs(int(duration or 0) - kg_duration) if kg_duration else None
                        verified_krc, krc_stats, krc_reason = _verify_precise_enhancement_against_native(
                            ordinary_ref, recovered_krc, provider_duration_delta_ms=kg_delta,
                            preserve_provider_phase=True
                        )
                        write_error_log('网易云KRC锚定诊断', detail=(
                            f'song={song_name} | trusted={int(bool(verified_krc))} | reason={krc_reason} | '
                            f'matched={krc_stats.get("matches",0)} | coverage={krc_stats.get("coverage",0.0):.3f} | '
                            f'phase={krc_stats.get("median_delta",0)}ms | spread={krc_stats.get("spread",0)}ms | '
                            f'drift={krc_stats.get("drift_ms",0)}ms | drift_ppm={krc_stats.get("drift_ppm",0)} | '
                            f'phase_policy={krc_stats.get("phase_policy","n/a")}'
                        ))
                        if verified_krc:
                            krc_stats = dict(krc_stats); krc_stats['native_song_id'] = str(song_id)
                            LyricSearchEngine._remember_precise_clock(
                                song_name, artist, duration, verified_krc, 'kugou-krc',
                                (_kg or {}).get('hash') or (_kg or {}).get('provider_id'), verification=krc_stats
                            )
                            selected_precise = verified_krc
                            selected_provider = 'kugou-krc'
                            selected_stats = krc_stats
                            selection_reason = 'verified-foreign-enhancement'
                        else:
                            selection_reason = f'foreign-rejected:{krc_reason}'

                if isinstance(yrc_obj, dict):
                    ordinary_lrc = str((yrc_obj.get('lrc') or {}).get('lyric') or '')
                    lrc = selected_precise or ordinary_lrc
                    if selected_precise and ordinary_lrc:
                        lrc = LyricSearchEngine._merge_intro_credits(lrc, ordinary_lrc)
                    tlyric = str((yrc_obj.get('tlyric') or {}).get('lyric') or '')
                    if lrc or tlyric:
                        final_mode = 'native-lrc' if not selected_precise else selected_provider
                        write_error_log('网易云歌词时钟决策', detail=(
                            f'song={song_name} | mode={final_mode} | reason={selection_reason} | '
                            f'native_song_id={song_id} | matches={selected_stats.get("matches",0)} | '
                            f'coverage={selected_stats.get("coverage",0.0):.3f} | spread={selected_stats.get("spread",0)}ms | '
                            f'drift={selected_stats.get("drift_ms",0)}ms'
                        ))
                        LyricSearchEngine.last_error = ""
                        return lrc, tlyric, duration

                # Strict fallback: this is the historical v1.8.8 ordinary-LRC endpoint.
                # It remains intact for missing Crypto, EAPI failure, songs without usable
                # response data, or any future provider-side change.
                lyric_url = f"https://music.163.com/api/song/lyric?id={song_id}&lv=1&kv={-1 if RHYTHM_GROUPS_ENABLED else 1}&tv=-1"
                lrc_resp = requests.get(lyric_url, headers=LyricSearchEngine.HEADERS, timeout=8)
                lrc_resp.raise_for_status()
                lrc_data = lrc_resp.json()
                ordinary_fallback_lrc = str(lrc_data.get('lrc', {}).get('lyric', '') or '')
                tlyric = lrc_data.get('tlyric', {}).get('lyric', '')
                if ordinary_fallback_lrc or tlyric:
                    # If EAPI did not even give us a native reference, do not start foreign
                    # clock probing after another failure path. The native line clock is the
                    # deterministic v1.8.8-compatible safety baseline.
                    write_error_log('网易云歌词时钟决策', detail=(
                        f'song={song_name} | mode=native-lrc | reason=eapi-reference-unavailable | '
                        f'native_song_id={song_id} | foreign_probe=0'
                    ))
                    LyricSearchEngine.last_error = ""
                    return ordinary_fallback_lrc or None, tlyric or None, duration
                return LyricSearchEngine._fail("网易云", detail="搜索到歌曲，但接口没有返回 LRC")
            return LyricSearchEngine._fail("网易云", detail="没有搜索到匹配歌曲")
        except Exception as exc:
            return LyricSearchEngine._fail("网易云", exc)

    @staticmethod
    def _decode_qq_lyric(value):
        if not value:
            return ""
        value = html.unescape(str(value)).replace('\\n', '\n')
        # nobase64=1 时通常已经是明文；只有看起来不像 LRC 时才尝试 Base64。
        if re.search(r'\[\d{1,3}:\d{1,2}(?:\.\d+)?\]', value):
            return value
        try:
            decoded = base64.b64decode(value, validate=True).decode('utf-8')
            return html.unescape(decoded)
        except Exception:
            return value


    @staticmethod
    def _decode_qq_translation(value, allow_plain=False):
        """Decode QQ translation from web-LRC when present; accept encrypted QRC as fallback."""
        raw = html.unescape(str(value or '')).strip()
        if not raw:
            return ''
        decoded = LyricSearchEngine._decode_qq_lyric(raw)
        if _LRC_TIME_TOKEN_RE.search(decoded):
            return decoded
        compact = re.sub(r'\s+', '', raw)
        if len(compact) >= 16 and len(compact) % 16 == 0 and re.fullmatch(r'[0-9A-Fa-f]+', compact):
            try:
                return _qrc_plain_to_line_lrc(_decode_qq_qrc_hex(compact))
            except Exception:
                pass
        return decoded.strip() if allow_plain else ''


    @staticmethod
    def _normalize_credit_text(value):
        return re.sub(r'[\s\-–—－·・:：()（）\[\]【】/\\,_]+', '', str(value or '')).lower()

    @classmethod
    def _merge_intro_credits(cls, primary_lrc, reference_lrc):
        """Merge provider-supplied intro credits without changing the chosen lyric clock."""
        primary = str(primary_lrc or '')
        reference = str(reference_lrc or '')
        if not (PRESERVE_INTRO_CREDITS_ENABLED and primary and reference):
            return primary

        existing = set()
        for raw in primary.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
            times, body_raw = _split_lrc_leading_timestamps(raw.strip())
            if not times:
                continue
            body = _sanitize_lrc_body(body_raw)
            if body:
                existing.add(cls._normalize_credit_text(body))

        extras = []
        for raw in reference.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
            stripped = raw.strip('\ufeff').strip()
            times, body_raw = _split_lrc_leading_timestamps(stripped)
            if not times or min(times) > 45000:
                continue
            body = _sanitize_lrc_body(body_raw)
            if not body or not (_LRC_CREDIT_BODY_RE.match(body) or _LRC_EXTRA_CREDIT_RE.match(body)):
                continue
            key = cls._normalize_credit_text(body)
            if not key or key in existing:
                continue
            existing.add(key)
            extras.append(stripped)
        if not extras:
            return primary
        try:
            write_error_log('开场制作信息已补回', detail=f'credits={len(extras)}')
        except Exception:
            pass
        return (primary.rstrip() + '\n' + '\n'.join(extras)).strip()

    @classmethod
    def _clean_lrc(cls, lyric, song_name='', artist=''):
        """Remove provider control metadata without destroying LRC timing semantics.

        Timed intro production credits are preserved in v1.8.9.16. offset remains intact
        for parse_lrc(); multiple leading timestamps and colon-fraction timestamps are
        understood here so actual control metadata cannot bypass cleanup.
        """
        if not lyric:
            return ""

        metadata_re = re.compile(
            r'^\[(?:ti|ar|al|by|kana|re|ve|length|id|hash|sign|language|tool|encoding)\s*:',
            re.I
        )
        song_norm = cls._normalize_credit_text(song_name)
        artist_norm = cls._normalize_credit_text(artist)
        kept = []
        removed = 0

        for raw in str(lyric).replace('\r\n', '\n').replace('\r', '\n').split('\n'):
            line = raw.strip('\ufeff')
            stripped = line.strip()
            if not stripped:
                continue

            # Preserve offset so the parser can actually apply it.
            if _LRC_OFFSET_RE.match(stripped):
                kept.append(stripped)
                continue

            if metadata_re.match(stripped):
                removed += 1
                continue

            times, body_raw = _split_lrc_leading_timestamps(stripped)
            if times:
                body = _sanitize_lrc_body(body_raw)
                if not body:
                    removed += 1
                    continue

                # v1.8.9.16: production credits are user-visible lyric content when the
                # provider timestamps them near the beginning. Keep those rows; continue
                # filtering section/speaker control labels. We never invent missing credits.
                is_credit = bool(_LRC_CREDIT_BODY_RE.match(body) or _LRC_EXTRA_CREDIT_RE.match(body))
                if CLOCK_SOURCE_FIRST_ENABLED and _LRC_SECTION_LABEL_RE.match(body):
                    removed += 1
                    continue
                if CLOCK_SOURCE_FIRST_ENABLED and is_credit:
                    if PRESERVE_INTRO_CREDITS_ENABLED and min(times) <= 45000:
                        kept.append(stripped)
                        continue
                    removed += 1
                    continue
                if (
                    CLOCK_SOURCE_FIRST_ENABLED and min(times) <= 30000 and
                    _LRC_SPEAKER_LABEL_RE.match(body) and
                    (re.search(r'[A-Za-z0-9]', body) or '王朝' in body or '朱旭' in body)
                ):
                    removed += 1
                    continue

                # Provider title banner: only remove when it matches the requested song.
                if min(times) <= 12000:
                    body_norm = cls._normalize_credit_text(body)
                    song_match = bool(song_norm and song_norm in body_norm)
                    artist_match = bool(artist_norm and artist_norm in body_norm)
                    if song_match and (artist_match or not artist_norm):
                        removed += 1
                        continue

            kept.append(stripped)

        cleaned = '\n'.join(kept).strip()
        if removed:
            try:
                write_error_log(
                    'LRC元数据已清理',
                    detail=f'removed={removed} | song={song_name} | artist={artist}'
                )
            except Exception:
                pass
        return cleaned

    @staticmethod
    def search_qq(song_name, artist="", trans_only=False, expected_duration_ms=0):
        """QQ lyrics: native QRC first, QQ ordinary LRC fallback.

        v1.8.9.18 never needs another provider for normal operation. When QQ's
        encrypted QRC is available it becomes a real precise word clock. The
        historical cross-provider bridge is still available only behind the
        explicit LIMBUSLYRIC_QQ_CROSS_SOURCE_TIMING=1 A/B switch.
        """
        try:
            keyword = f"{song_name} {artist}".strip()
            expected_duration_ms = int(expected_duration_ms or 0)
            # When the QQ player already exposes the total duration, search deeper than the
            # historical top-8 list. Same-title international songs can rank a wrong edit
            # above the currently playing version; duration is a stronger version identity.
            search_limit = 30 if expected_duration_ms > 0 else 8
            search_url = (
                f"https://c.y.qq.com/soso/fcgi-bin/client_search_cp"
                f"?p=1&n={search_limit}&w={urllib.parse.quote(keyword)}&format=json"
            )
            headers = {**LyricSearchEngine.HEADERS, 'Referer': 'https://y.qq.com/'}
            _r2_req = globals().get('_r2_qq_search_request')
            resp = (_r2_req(requests, search_url, headers=headers, timeout=8)
                    if callable(_r2_req) else requests.get(search_url, headers=headers, timeout=8))
            resp.raise_for_status()
            data = resp.json()
            songs = data.get('data', {}).get('song', {}).get('list', [])
            if expected_duration_ms > 0:
                safe_rows = []
                q_song = _clean_name(song_name)
                for row in songs:
                    c_song_text = row.get('songname') or row.get('name') or ''
                    c_song = _clean_name(c_song_text)
                    song_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                    c_artist = _artist_text({'singer': row.get('singer', [])})
                    artist_ok, _artist_alias = _artist_alias_match(artist, c_artist) if str(artist or '').strip() else (True, '')
                    c_duration = int((row.get('interval', 0) or 0) * 1000)
                    duration_delta = abs(expected_duration_ms - c_duration) if c_duration > 0 else 10**9
                    duration_ok = bool(
                        c_duration > 0 and
                        duration_delta <= max(3500, int(max(expected_duration_ms, c_duration) * 0.025))
                    )
                    if song_ok and artist_ok and duration_ok:
                        safe_rows.append((
                            _candidate_score(song_name, artist, c_song_text, c_artist),
                            -duration_delta,
                            row,
                        ))
                song = max(safe_rows, key=lambda x: (x[0], x[1]))[2] if safe_rows else None
                if song is None:
                    write_error_log(
                        'QQ歌词版本时长拒绝',
                        detail=(
                            f'song={song_name} | artist={artist} | expected_duration={expected_duration_ms} | '
                            f'candidates={len(songs)} | action=no-unsafe-fallback'
                        )
                    )
                    return LyricSearchEngine._fail(
                        "QQ音乐", detail="没有找到歌名、歌手和播放器时长都足够一致的安全歌词版本"
                    )
                try:
                    write_error_log(
                        'QQ歌词版本时长严格匹配',
                        detail=(
                            f'song={song_name} | artist={artist} | expected_duration={expected_duration_ms} | '
                            f'candidate_duration={int((song.get("interval", 0) or 0) * 1000)} | '
                            f'songmid={song.get("songmid") or ""}'
                        )
                    )
                except Exception:
                    pass
            else:
                song = LyricSearchEngine._best(
                    songs, song_name, artist,
                    lambda x: x.get('songname') or x.get('name') or '',
                    lambda x: _artist_text({'singer': x.get('singer', [])})
                )
            if not song:
                return LyricSearchEngine._fail("QQ音乐", detail="没有搜索到匹配歌曲")

            songmid = song.get('songmid')
            if not songmid:
                return LyricSearchEngine._fail("QQ音乐", detail="搜索结果缺少 songmid")
            duration = (song.get('interval', 0) or 0) * 1000
            songid = song.get('songid') or song.get('id')

            def resolve_songid():
                nonlocal songid
                if songid:
                    return str(songid)
                try:
                    detail_url = 'https://c.y.qq.com/v8/fcg-bin/fcg_play_single_song.fcg'
                    detail_resp = requests.get(
                        detail_url,
                        params={'songmid': songmid, 'format': 'json'},
                        headers=headers,
                        timeout=4.2,
                    )
                    detail_resp.raise_for_status()
                    detail = detail_resp.json()
                    rows = detail.get('data') or []
                    if rows and isinstance(rows[0], dict):
                        songid = rows[0].get('id') or rows[0].get('songid')
                except Exception as exc:
                    write_error_log('QQ QRC songid解析失败', exc, detail=f'songmid={songmid}')
                return str(songid) if songid else ''

            qq_translation = ''

            def fetch_qq_lrc():
                nonlocal qq_translation
                lyric_url = (
                    f"https://c.y.qq.com/lyric/fcgi-bin/fcg_query_lyric_new.fcg"
                    f"?songmid={songmid}&format=json&nobase64=1"
                )
                lrc_resp = requests.get(lyric_url, headers=headers, timeout=8)
                lrc_resp.raise_for_status()
                lrc_data = lrc_resp.json()
                lyric = LyricSearchEngine._decode_qq_lyric(lrc_data.get('lyric', ''))
                qq_translation = LyricSearchEngine._decode_qq_translation(lrc_data.get('trans', ''), allow_plain=trans_only)
                try:
                    write_error_log(
                        'QQ普通LRC已读取',
                        detail=(
                            f'songmid={songmid} | '
                            f'keys={sorted(lrc_data.keys()) if isinstance(lrc_data, dict) else []} | trans_raw_len={len(str(lrc_data.get("trans", "") or "")) if isinstance(lrc_data, dict) else 0} | trans_decoded_len={len(qq_translation)}'
                        )
                    )
                    if qq_translation.strip():
                        write_error_log(
                            'QQ翻译LRC已读取',
                            detail=f'songmid={songmid} | chars={len(qq_translation)}'
                        )
                except Exception:
                    pass
                return lyric

            qrc_translation = ''

            def fetch_qq_qrc():
                nonlocal qrc_translation
                if not QQ_NATIVE_QRC_ENABLED:
                    return ''
                if (not trans_only) and not (WORD_TIMING_ENABLED and WORD_CLOCK_RECOVERY_ENABLED):
                    return '' 
                qrc_headers = {**headers, 'Referer': 'https://c.y.qq.com/'}
                qrc_pc_headers = {
                    **qrc_headers,
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/63.0.3239.132 Safari/537.36',
                    'Cookie': 'os=pc;osver=Microsoft-Windows-10-Professional-build-16299.125-64bit;appver=2.0.3.131777;channel=qqmusic;__remember_me=true',
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'Accept': '*/*',
                }

                def resolve_pc_lyric_id():
                    """Resolve the ID emitted by QQ's PC lyric search, not the song music ID."""
                    try:
                        pc_resp = requests.get(
                            'https://c.y.qq.com/lyric/fcgi-bin/fcg_search_pc_lrc.fcg',
                            params={
                                'SONGNAME': song_name, 'SINGERNAME': artist, 'TYPE': '2',
                                'RANGE_MIN': '1', 'RANGE_MAX': '20'
                            },
                            headers=qrc_pc_headers, timeout=3.2
                        )
                        pc_resp.raise_for_status()
                        xmlish = str(pc_resp.text or '').replace('<!--', '').replace('-->', '')
                        rows = []
                        for m in re.finditer(r'<songinfo\b([^>]*)>(.*?)</songinfo\s*>', xmlish, re.S | re.I):
                            attrs, body = m.group(1), m.group(2)
                            im = re.search(r'\bid=["\']([^"\']+)["\']', attrs, re.I)
                            if not im:
                                continue
                            def fld(tag):
                                fm = re.search(r'<%s\b[^>]*>(.*?)</%s\s*>' % (tag, tag), body, re.S | re.I)
                                value = re.sub(r'<[^>]+>', '', fm.group(1) if fm else '')
                                return urllib.parse.unquote(html.unescape(value or '')).strip()
                            name = fld('name'); singer = fld('singername')
                            score = _candidate_score(song_name, artist, name, singer)
                            rows.append((score, str(im.group(1)), name, singer))
                        if rows:
                            rows.sort(key=lambda x: x[0], reverse=True)
                            best = rows[0]
                            if best[0] >= 100 or not artist:
                                write_error_log('QQ PC歌词ID命中', detail=(
                                    f'songmid={songmid} | lyric_id={best[1]} | score={best[0]} | '
                                    f'name={best[2]} | singer={best[3]}'
                                ))
                                return best[1]
                            write_error_log('QQ PC歌词ID证据不足', detail=f'songmid={songmid} | best_score={best[0]} | rows={len(rows)}')
                        else:
                            write_error_log('QQ PC歌词搜索无候选', detail=f'songmid={songmid} | chars={len(xmlish)} | ctype={pc_resp.headers.get("Content-Type","")}')
                    except Exception as exc:
                        write_error_log('QQ PC歌词ID解析失败', exc, detail=f'songmid={songmid}')
                    return ''

                # Translation-only prefers QQ's PC lyric-search ID because that is the
                # identifier used by the PC lyric downloader for contentts (translated QRC).
                # Normal precise mode keeps the existing song-id-first behavior.
                pc_lyric_id = ''
                if trans_only:
                    pc_lyric_id = resolve_pc_lyric_id()
                    sid = pc_lyric_id or resolve_songid()
                else:
                    sid = resolve_songid()
                    if not sid:
                        pc_lyric_id = resolve_pc_lyric_id()
                        sid = pc_lyric_id
                if not sid:
                    write_error_log('QQ原生QRC不可用', detail=f'songmid={songmid} | reason=no lyric/song id')
                    return ''
                qrc_url = 'https://c.y.qq.com/qqmusic/fcgi-bin/lyric_download.fcg'
                params={'version':'15','miniversion':'82','lrctype':'4','musicid':sid}

                def extract_hex_fields(text):
                    xmlish = str(text or '').replace('<!--','').replace('-->','')
                    fields = {}
                    for tag in ('content', 'contentts', 'contentroma'):
                        cm = re.search(r'<%s\b[^>]*>(.*?)</%s\s*>' % (tag, tag), xmlish, re.S|re.I)
                        if not cm:
                            continue
                        inner = html.unescape(cm.group(1) or '')
                        inner = re.sub(r'^\s*<!\[CDATA\[', '', inner, flags=re.I)
                        inner = re.sub(r'\]\]>\s*$', '', inner, flags=re.I)
                        compact = re.sub(r'\s+', '', inner)
                        # Do not manufacture ciphertext by filtering arbitrary HTML down to hex letters.
                        if compact and len(compact) % 2 == 0 and re.fullmatch(r'[0-9A-Fa-f]+', compact):
                            fields[tag] = compact
                    return fields, xmlish

                attempts=[]
                profiles = (
                    ('POST-PC', 'POST', qrc_pc_headers),
                    ('GET-PC', 'GET', qrc_pc_headers),
                    ('POST-WEB', 'POST', qrc_headers),
                    ('GET-WEB', 'GET', qrc_headers),
                )
                html_hint = ''

                def request_qrc_profile(item):
                    profile, method, req_headers = item
                    try:
                        if method == 'GET':
                            resp=requests.get(qrc_url,params=params,headers=req_headers,timeout=2.8)
                        else:
                            resp=requests.post(qrc_url,data=params,headers=req_headers,timeout=2.8)
                        resp.raise_for_status()
                        payloads, xmlish = extract_hex_fields(resp.text)
                        ctype = str(resp.headers.get('Content-Type') or '')
                        return profile, payloads, xmlish, ctype, None
                    except Exception as exc:
                        return profile, {}, '', '', exc

                # QQ's endpoint is inconsistent per song/network: some tracks answer POST-PC
                # immediately while others only answer GET-PC. Serial 2.8s attempts made the
                # latter look like a multi-second startup hang. Race equivalent PC methods
                # first; only if both fail/no-content do the equivalent WEB methods race.
                for wave in (profiles[:2], profiles[2:]):
                    ex_qrc = concurrent.futures.ThreadPoolExecutor(max_workers=2)
                    pending_qrc = {ex_qrc.submit(request_qrc_profile, item) for item in wave}
                    try:
                        while pending_qrc:
                            done_qrc, pending_qrc = concurrent.futures.wait(
                                pending_qrc, timeout=3.05,
                                return_when=concurrent.futures.FIRST_COMPLETED,
                            )
                            if not done_qrc:
                                break
                            for fut in done_qrc:
                                try:
                                    profile, payloads, xmlish, ctype, req_exc = fut.result()
                                except Exception as exc:
                                    profile, payloads, xmlish, ctype, req_exc = '<worker>', {}, '', '', exc
                                if req_exc is not None:
                                    attempts.append((profile,'error',f'{type(req_exc).__name__}:{str(req_exc)[:120]}'))
                                    continue
                                attempts.append((profile, len(xmlish), ctype, sorted(payloads.keys())))
                                if not payloads:
                                    if not html_hint and 'html' in ctype.lower():
                                        tm = re.search(r'<title[^>]*>(.*?)</title>', xmlish, re.S|re.I)
                                        if tm:
                                            html_hint = re.sub(r'\s+',' ',html.unescape(tm.group(1) or '')).strip()[:80]
                                    continue
                                if payloads.get('contentts') and not qrc_translation:
                                    try:
                                        trans_plain = _decode_qq_qrc_hex(payloads['contentts'])
                                        qrc_translation = _qrc_plain_to_line_lrc(trans_plain)
                                        if qrc_translation:
                                            write_error_log('QQ QRC翻译命中', detail=(
                                                f'songmid={songmid} | profile={profile} | chars={len(qrc_translation)}'
                                            ))
                                    except Exception as texc:
                                        attempts.append((profile, 'trans-error', f'{type(texc).__name__}:{str(texc)[:120]}'))
                                if trans_only:
                                    if qrc_translation:
                                        for pf in pending_qrc: pf.cancel()
                                        return ''
                                    continue
                                payload = payloads.get('content')
                                if not payload:
                                    continue
                                decoded = _decode_qq_qrc_hex(payload)
                                enhanced = _qrc_plain_to_enhanced_lrc(decoded)
                                if enhanced and _LRC_INLINE_TIME_RE.search(enhanced):
                                    write_error_log('QQ原生QRC逐字时钟命中', detail=(
                                        f'songmid={songmid} | songid={sid} | profile={profile} | '
                                        f'decoded_chars={len(decoded)} | enhanced_chars={len(enhanced)} | race=1'
                                    ))
                                    for pf in pending_qrc: pf.cancel()
                                    return enhanced
                                attempts.append((profile,'decoded-no-events',len(decoded)))
                    finally:
                        for pf in pending_qrc:
                            pf.cancel()
                        ex_qrc.shutdown(wait=False, cancel_futures=True)
                write_error_log('QQ原生QRC未返回正文',detail=(
                    f'songmid={songmid} | songid={sid} | attempts={attempts} | html_title={html_hint or "<none>"}'
                ))
                return ''

            qq_lyric = ''
            native_qrc = ''

            # Run the source-faithful ordinary and QRC probes together. If ordinary LRC
            # finishes first, give native QRC a short grace window rather than making
            # startup wait for a full network timeout.
            if (not trans_only) and WORD_TIMING_ENABLED and WORD_CLOCK_RECOVERY_ENABLED and QQ_NATIVE_QRC_ENABLED:
                ex = concurrent.futures.ThreadPoolExecutor(max_workers=2)
                qq_future = ex.submit(fetch_qq_lrc)
                qrc_future = ex.submit(fetch_qq_qrc)
                qq_done_at = None
                pending = {qq_future, qrc_future}
                deadline = time.monotonic() + 5.6
                try:
                    while pending and time.monotonic() < deadline:
                        done, pending = concurrent.futures.wait(
                            pending,
                            timeout=min(0.65, max(0.0, deadline - time.monotonic())),
                            return_when=concurrent.futures.FIRST_COMPLETED,
                        )
                        if not done:
                            if qq_done_at is not None and time.monotonic() - qq_done_at >= 2.8:
                                break
                            continue
                        for fut in done:
                            if fut is qq_future:
                                try:
                                    qq_lyric = fut.result()
                                except Exception as exc:
                                    write_error_log('QQ普通LRC并行抓取失败', exc, detail=f'songmid={songmid}')
                                qq_done_at = time.monotonic()
                            else:
                                try:
                                    native_qrc = fut.result()
                                except Exception as exc:
                                    write_error_log('QQ原生QRC抓取失败', exc, detail=f'songmid={songmid}')
                        if native_qrc:
                            break
                        if qq_done_at is not None and time.monotonic() - qq_done_at >= 2.8:
                            break
                finally:
                    if native_qrc and not qq_lyric and qq_future.done():
                        try:
                            qq_lyric = qq_future.result()
                        except Exception:
                            pass
                    for fut in pending:
                        fut.cancel()
                    ex.shutdown(wait=False, cancel_futures=True)
            else:
                qq_lyric = fetch_qq_lrc()
                if trans_only and not qq_translation and QQ_NATIVE_QRC_ENABLED:
                    try:
                        fetch_qq_qrc()
                    except Exception as exc:
                        write_error_log('QQ翻译QRC抓取失败', exc, detail=f'songmid={songmid}')
                if qrc_translation and not qq_translation:
                    qq_translation = qrc_translation

            if qrc_translation and not qq_translation:
                qq_translation = qrc_translation

            if trans_only:
                line_translation = _translation_to_line_lrc(qq_translation, qq_lyric)
                if line_translation:
                    LyricSearchEngine.last_error = ''
                    write_error_log(
                        'QQ翻译行歌词命中',
                        detail=(
                            f'songmid={songmid} | chars={len(line_translation)} | '
                            f'ordinary_trans={int(bool(qq_translation and not qrc_translation))} | '
                            f'qrc_trans={int(bool(qrc_translation))} | word_probe=0'
                        )
                    )
                    return qq_lyric, line_translation, duration
                LyricSearchEngine.last_error = 'QQ音乐：搜索到歌曲，但当前曲目没有可用翻译歌词'
                write_error_log('歌词搜索失败/QQ音乐', detail='搜索到歌曲，但当前曲目没有可用翻译歌词')
                return qq_lyric or None, None, duration

            if native_qrc and _LRC_INLINE_TIME_RE.search(native_qrc):
                if qq_lyric:
                    _qq_audit_clock, _qq_audit_stats = _reanchor_precise_lines_to_reference(
                        qq_lyric, native_qrc, provider_duration_delta_ms=0
                    )
                    write_error_log('QQ原生QRC自相位审计', detail=(
                        f'songmid={songmid} | applied_preview={int(bool(_qq_audit_stats.get("applied")))} | '
                        f'reason={_qq_audit_stats.get("reason","n/a")} | matches={_qq_audit_stats.get("matches",0)} | '
                        f'coverage={_qq_audit_stats.get("coverage",0.0):.3f} | phase={_qq_audit_stats.get("median_delta",0)}ms | '
                        f'spread={_qq_audit_stats.get("spread",0)}ms | drift={_qq_audit_stats.get("drift_ms",0)}ms | '
                        f'behavior=diagnostic-only'
                    ))
                    native_qrc = LyricSearchEngine._merge_intro_credits(native_qrc, qq_lyric)
                LyricSearchEngine.last_error = ''
                write_error_log(
                    'QQ原生QRC逐字时钟命中',
                    detail=f'songmid={songmid} | songid={songid} | enhanced_chars={len(native_qrc)}'
                )
                write_error_log(
                    'QQ逐字时钟启用',
                    detail=f'songmid={songmid} | mode=native-qrc | duration={duration} | source_faithful=1'
                )
                return native_qrc, qq_translation or None, duration

            # Explicit A/B compatibility only. Native QRC is always preferred and this
            # branch remains off by default so QQ never silently inherits another app's clock.
            precise_lyric = ''
            _matched = None
            if (
                (not trans_only) and WORD_TIMING_ENABLED and WORD_CLOCK_RECOVERY_ENABLED and
                CROSS_SOURCE_TIMING_ENABLED and QQ_CROSS_SOURCE_TIMING_ENABLED
            ):
                try:
                    precise_lyric, _matched = LyricSearchEngine._fetch_best_cross_provider_word_match(
                        song_name, artist, duration, use_cache=False
                    )
                except Exception as exc:
                    write_error_log('QQ跨源逐字抓取失败', exc, detail=f'songmid={songmid}')

            if precise_lyric and _LRC_INLINE_TIME_RE.search(precise_lyric):
                provider = str((_matched or {}).get('_clock_provider') or (_matched or {}).get('provider') or 'cross-provider')
                duration_delta = None
                try:
                    matched_duration = int((_matched or {}).get('duration_ms') or (_matched or {}).get('duration') or (_matched or {}).get('dt') or 0)
                    if matched_duration:
                        duration_delta = abs(int(duration or 0) - matched_duration)
                except Exception:
                    duration_delta = None
                if qq_lyric:
                    verified_cross, cross_stats, cross_reason = _verify_precise_enhancement_against_native(
                        qq_lyric, precise_lyric, provider_duration_delta_ms=duration_delta
                    )
                else:
                    verified_cross, cross_stats, cross_reason = '', {}, 'missing-qq-native-reference'
                write_error_log('QQ跨源逐字锚定诊断', detail=(
                    f'songmid={songmid} | provider={provider} | trusted={int(bool(verified_cross))} | '
                    f'reason={cross_reason} | matches={cross_stats.get("matches",0)} | '
                    f'coverage={cross_stats.get("coverage",0.0):.3f} | phase={cross_stats.get("median_delta",0)}ms | '
                    f'spread={cross_stats.get("spread",0)}ms | drift={cross_stats.get("drift_ms",0)}ms'
                ))
                if verified_cross:
                    precise_lyric = LyricSearchEngine._merge_intro_credits(verified_cross, qq_lyric) if qq_lyric else verified_cross
                    LyricSearchEngine.last_error = ''
                    write_error_log(
                        'QQ逐字时钟启用',
                        detail=(
                            f'songmid={songmid} | mode=verified-cross-provider-word-clock | duration={duration} | '
                            f'provider={provider} | source_faithful=0'
                        )
                    )
                    return precise_lyric, qq_translation or None, duration

            if not qq_lyric:
                # A QRC request can fail while the ordinary future was cancelled after the
                # grace window; give the authoritative fallback one direct final attempt.
                try:
                    qq_lyric = fetch_qq_lrc()
                except Exception as exc:
                    write_error_log('QQ普通LRC最终回退失败', exc, detail=f'songmid={songmid}')

            if qq_lyric and re.search(r'\[\d{1,3}:\d{1,2}', qq_lyric):
                LyricSearchEngine.last_error = ''
                if WORD_TIMING_ENABLED:
                    write_error_log(
                        'QQ逐字时钟降级普通LRC',
                        detail=(
                            f'songmid={songmid} | native_qrc={int(QQ_NATIVE_QRC_ENABLED)} | '
                            f'cross_source={int(CROSS_SOURCE_TIMING_ENABLED)} | '
                            f'qq_cross_source={int(QQ_CROSS_SOURCE_TIMING_ENABLED)} | source_faithful=1'
                        )
                    )
                return qq_lyric, qq_translation or None, duration
            return LyricSearchEngine._fail("QQ音乐", detail="搜索到歌曲，但歌词不是可识别的LRC/QRC")
        except Exception as exc:
            return LyricSearchEngine._fail("QQ音乐", exc)

    @staticmethod
    def search_kugou(song_name, artist="", expected_duration_ms=0, trans_only=False):
        """Direct Kugou source with TLS-safe search rotation and native KRC preference.

        v132 also treats the desktop client's own track identity/duration as version evidence.
        Kugou search can return several same-title edits; title+partial-artist alone is not
        sufficient (field case: ``少女A`` selected an 81s edit while the player was on 03:41).
        Never disables certificate verification.
        """
        original_artist = str(artist or '').strip()
        artist_enriched = False
        kugou_pids = []
        try:
            kugou_pids = LyricFetcher.get_player_pids('酷狗音乐', DEFAULT_PLAYERS)
            if kugou_pids:
                wsong, wart = LyricFetcher.get_song_from_title(kugou_pids, '酷狗音乐', DEFAULT_PLAYERS)
                if wsong and wart and _clean_name(wsong) == _clean_name(song_name):
                    artist_ok, _alias = _artist_alias_match(original_artist, wart) if original_artist else (True, '')
                    old_keys = _artist_alias_keys(original_artist)
                    new_keys = _artist_alias_keys(wart)
                    if artist_ok and (not original_artist or len(new_keys) > len(old_keys) or len(str(wart)) > len(original_artist) + 2):
                        artist = str(wart).strip()
                        if _clean_name(artist) != _clean_name(original_artist):
                            artist_enriched = True
                            write_error_log('酷狗歌词搜索身份补全', detail=(
                                f'song={song_name} | artist={original_artist or "<empty>"} -> {artist} | source=window-title'))
        except Exception as exc:
            write_error_log('酷狗歌词搜索身份补全失败', exc, detail=f'song={song_name}')

        keyword = f"{song_name} {artist}".strip()

        def clean_markup(v):
            return html.unescape(re.sub(r'<[^>]+>', '', str(v or ''))).strip()

        def normalize_row(c):
            if not isinstance(c, dict):
                return None
            name = clean_markup(c.get('SongName') or c.get('songname') or c.get('filename','').split(' - ')[-1])
            singer = clean_markup(c.get('SingerName') or c.get('singername') or c.get('filename','').split(' - ')[0])
            raw_dur = c.get('Duration') if c.get('Duration') not in (None, '') else c.get('duration')
            try:
                raw_dur = float(raw_dur or 0)
                duration_ms = int(raw_dur if raw_dur > 10000 else raw_dur * 1000)
            except Exception:
                duration_ms = 0
            return {
                'songname': name, 'singername': singer, 'duration_ms': duration_ms,
                'hash': c.get('FileHash') or c.get('filehash') or c.get('hash') or c.get('320hash') or c.get('sqhash'),
                'raw': c,
            }

        endpoints = [
            ('songsearch-v2', 'https://songsearch.kugou.com/song_search_v2', {
                'keyword':keyword, 'page':1, 'pagesize':12, 'platform':'WebFilter',
                'format':'json', 'filter':2, 'iscorrection':1, 'privilege_filter':0
            }, 'v2'),
            ('msearch-v3', 'https://msearch.kugou.com/api/v3/search/song', {
                'format':'json', 'keyword':keyword, 'page':1, 'pagesize':12
            }, 'v3'),
            ('mobilecdn-v3', 'https://mobilecdn.kugou.com/api/v3/search/song', {
                'format':'json', 'keyword':keyword, 'page':1, 'pagesize':12
            }, 'v3'),
            # Some networks currently see a certificate-hostname mismatch here. Keep it only
            # as the final compatibility fallback so normal searches do not pay that TLS failure.
            ('msearchcdn-v3', 'https://msearchcdn.kugou.com/api/v3/search/song', {
                'format':'json', 'keyword':keyword, 'page':1, 'pagesize':12
            }, 'v3'),
        ]

        songs = []
        endpoint_errors = []
        for label, url, params, shape in endpoints:
            if LyricSearchEngine._is_cancelled():
                return None, None, 0
            try:
                resp = requests.get(
                    url, params=params,
                    headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                    timeout=(2.8, 5.5)
                )
                resp.raise_for_status()
                obj = resp.json()
                data = obj.get('data') or {}
                rows = (data.get('lists') if shape == 'v2' else data.get('info')) or []
                songs = [x for x in (normalize_row(row) for row in rows) if x]
                if songs:
                    write_error_log('酷狗歌词搜索入口命中', detail=f'endpoint={label} | rows={len(songs)} | tls_verify=1')
                    break
            except requests.exceptions.SSLError as exc:
                endpoint_errors.append(f'{label}:TLS')
                write_error_log('酷狗歌词搜索入口TLS不可用', detail=f'endpoint={label} | tls_verify=1 | {type(exc).__name__}: {exc}')
            except Exception as exc:
                endpoint_errors.append(f'{label}:{type(exc).__name__}')
                write_error_log('酷狗歌词搜索入口失败', detail=f'endpoint={label} | {type(exc).__name__}: {exc}')

        if not songs:
            return LyricSearchEngine._fail(
                '酷狗', detail='搜索入口均未返回歌曲（保持TLS校验）' +
                (f"；尝试={','.join(endpoint_errors)}" if endpoint_errors else '')
            )

        # Same-title Kugou rows can be different edits/versions. First collect identity-plausible
        # rows, then (when ambiguous) ask the desktop accessibility tree for the playlist's own
        # ``歌名，时长:mm:ss`` evidence. This is only an ambiguity probe, so ordinary songs keep
        # the fast network-only path.
        q_song = _clean_name(song_name)
        identity_rows = []
        for row in songs:
            c_song = _clean_name(row.get('songname') or '')
            if not q_song or not c_song or not (q_song == c_song or q_song in c_song or c_song in q_song):
                continue
            artist_ok, _alias = _artist_alias_match(artist, row.get('singername') or '') if str(artist or '').strip() else (True, '')
            if artist_ok:
                identity_rows.append(row)

        duration_hint = int(expected_duration_ms or 0)
        identity_durations = sorted({int(x.get('duration_ms') or 0) for x in identity_rows if int(x.get('duration_ms') or 0) > 0})
        duration_ambiguous = (
            len(identity_durations) >= 2 and
            (identity_durations[-1] - identity_durations[0]) >= max(8000, int(identity_durations[-1] * 0.06))
        )
        if duration_hint <= 0 and (duration_ambiguous or artist_enriched) and kugou_pids:
            try:
                duration_hint = int(LyricFetcher.get_kugou_ui_duration_hint(kugou_pids, song_name) or 0)
            except Exception as exc:
                write_error_log('酷狗播放器版本时长探测失败', exc, detail=f'song={song_name}')

        song = None
        if duration_hint > 0 and identity_rows:
            duration_limit = max(2500, int(duration_hint * 0.018))
            version_rows = []
            for row in identity_rows:
                c_dur = int(row.get('duration_ms') or 0)
                if c_dur <= 0:
                    continue
                delta = abs(c_dur - duration_hint)
                if delta <= duration_limit:
                    version_rows.append((
                        _candidate_score(song_name, artist, row.get('songname') or '', row.get('singername') or ''),
                        -delta, row
                    ))
            if not version_rows:
                # The artist-qualified endpoint can still rank a short edit above the actual
                # desktop item. One title-only retry is allowed *only* after the player has
                # supplied an exact duration witness; the same identity+duration guard remains.
                try:
                    retry = requests.get(
                        'https://songsearch.kugou.com/song_search_v2',
                        params={
                            'keyword':str(song_name or '').strip(), 'page':1, 'pagesize':30,
                            'platform':'WebFilter', 'format':'json', 'filter':2,
                            'iscorrection':1, 'privilege_filter':0
                        },
                        headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                        timeout=(2.8, 5.5)
                    )
                    retry.raise_for_status()
                    retry_rows = ((retry.json().get('data') or {}).get('lists') or [])
                    seen_hashes = {str(x.get('hash') or '') for x in songs}
                    added = 0
                    for raw_row in retry_rows:
                        row = normalize_row(raw_row)
                        if not row:
                            continue
                        h = str(row.get('hash') or '')
                        if h and h in seen_hashes:
                            continue
                        c_song = _clean_name(row.get('songname') or '')
                        artist_ok, _alias = _artist_alias_match(artist, row.get('singername') or '') if str(artist or '').strip() else (True, '')
                        if not c_song or not (q_song == c_song or q_song in c_song or c_song in q_song) or not artist_ok:
                            continue
                        c_dur = int(row.get('duration_ms') or 0)
                        delta = abs(c_dur - duration_hint) if c_dur else 10**9
                        if c_dur > 0 and delta <= duration_limit:
                            version_rows.append((
                                _candidate_score(song_name, artist, row.get('songname') or '', row.get('singername') or ''),
                                -delta, row
                            ))
                            added += 1
                    if added:
                        write_error_log('酷狗同名版本标题重试命中', detail=(
                            f'song={song_name} | ui_duration={duration_hint} | rows={len(retry_rows)} | matched={added}'))
                except Exception as exc:
                    write_error_log('酷狗同名版本标题重试失败', exc, detail=f'song={song_name} | ui_duration={duration_hint}')

            if version_rows:
                song = max(version_rows, key=lambda x: (x[0], x[1]))[2]
                write_error_log('酷狗同名版本按播放器时长锁定', detail=(
                    f'song={song_name} | artist={artist} | ui_duration={duration_hint} | '
                    f'selected_duration={int(song.get("duration_ms") or 0)} | identity_rows={len(identity_rows)}'))
            elif duration_ambiguous or artist_enriched:
                write_error_log('酷狗播放器时长未匹配搜索候选', detail=(
                    f'song={song_name} | artist={artist} | ui_duration={duration_hint} | '
                    f'candidate_durations={identity_durations}'))

        if song is None:
            song = LyricSearchEngine._best(
                identity_rows or songs, song_name, artist,
                lambda x: x.get('songname') or '',
                lambda x: x.get('singername') or ''
            )
        if not song:
            return LyricSearchEngine._fail('酷狗', detail='没有搜索到匹配歌曲')

        song_hash = song.get('hash')
        duration = int(song.get('duration_ms') or 0)
        if not song_hash:
            return LyricSearchEngine._fail('酷狗', detail='匹配歌曲缺少可用 FileHash')

        # Native precise KRC first.  This is the same source-faithful decoder already used
        # by cross-provider enhancement, but here we can reuse the selected Kugou hash.
        try:
            lyr_search = requests.get(
                'https://lyrics.kugou.com/search',
                params={'ver':'1','man':'yes','client':'pc','keyword':keyword,'hash':song_hash},
                headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                timeout=(2.8, 5.0)
            )
            lyr_search.raise_for_status()
            candidates = lyr_search.json().get('candidates') or []
            candidate = next((x for x in candidates if x.get('id') is not None and x.get('accesskey')), None)
            if candidate is not None:
                dl = requests.get(
                    'https://lyrics.kugou.com/download',
                    params={
                        'ver':'1','client':'pc','id':candidate.get('id'),'fmt':'krc',
                        'charset':'utf8','accesskey':candidate.get('accesskey')
                    },
                    headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                    timeout=(2.8, 5.0)
                )
                dl.raise_for_status()
                plain = _decode_kugou_krc_content((dl.json() or {}).get('content') or '')
                krc_translation = _krc_plain_translation_to_line_lrc(plain)
                enhanced = _krc_plain_to_enhanced_lrc(plain)
                if krc_translation:
                    write_error_log('酷狗KRC内嵌翻译命中', detail=(
                        f'hash={str(song_hash)[:12]}... | lyric_id={candidate.get("id")} | '
                        f'rows={len(krc_translation.splitlines())} | chars={len(krc_translation)}'
                    ))
                if enhanced and _LRC_INLINE_TIME_RE.search(enhanced):
                    sane, stats, reason = _precise_clock_basic_sanity(enhanced, duration)
                    if sane:
                        LyricSearchEngine.last_error = ''
                        write_error_log('酷狗原生KRC逐字时钟命中', detail=(
                            f'hash={str(song_hash)[:12]}... | lyric_id={candidate.get("id")} | '
                            f'duration={duration} | stats={stats}'
                        ))
                        return enhanced, krc_translation or None, duration
                    write_error_log('酷狗原生KRC逐字时钟证据不足', detail=f'reason={reason} | stats={stats}')
        except Exception as exc:
            write_error_log('酷狗原生KRC获取失败，回退普通LRC', detail=f'{type(exc).__name__}: {exc}')

        # Ordinary provider LRC remains a safe fallback if native KRC is unavailable.
        try:
            lrc_resp = requests.get(
                'https://m.kugou.com/app/i/krc.php',
                params={'cmd':100, 'hash':song_hash, 'timelength':999999},
                headers={**LyricSearchEngine.HEADERS, 'Referer':'https://www.kugou.com/'},
                timeout=(2.8, 5.5)
            )
            lrc_resp.raise_for_status()
            lyric = lrc_resp.text
            if lyric and lyric.strip() and re.search(r'\[\d{1,3}:\d{1,2}', lyric):
                LyricSearchEngine.last_error = ''
                write_error_log('酷狗普通LRC回退命中', detail=f'hash={str(song_hash)[:12]}... | duration={duration}')
                return lyric, None, duration
            return LyricSearchEngine._fail('酷狗', detail='搜索到歌曲，但歌词不是可识别的 KRC/LRC')
        except Exception as exc:
            return LyricSearchEngine._fail('酷狗', exc)

    @staticmethod
    def _search_netease_ordinary(song_name, artist="", trans_only=False, strict_identity=False, expected_duration_ms=0, preferred_song_id=None, preferred_duration_ms=0):
        """Fetch NetEase line-LRC only. Classic mode must not probe YRC/KLYRIC/KRC."""
        try:
            keyword = f"{song_name} {artist}".strip()
            resp = requests.get(
                f"https://music.163.com/api/search/get?s={urllib.parse.quote(keyword)}&type=1&limit=8",
                headers=LyricSearchEngine.HEADERS, timeout=8
            )
            resp.raise_for_status()
            songs = (resp.json().get('result') or {}).get('songs') or []
            song = None
            q_song = _clean_name(song_name)
            if strict_identity:
                rows = []
                for row in songs:
                    c_song = _clean_name(row.get('name', ''))
                    song_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                    c_artist = _artist_text(row)
                    artist_ok, _alias = _artist_alias_match(artist, c_artist) if str(artist or '').strip() else (True, '')
                    c_duration = int(row.get('duration', 0) or row.get('dt', 0) or 0)
                    delta = abs(int(expected_duration_ms or 0) - c_duration) if expected_duration_ms and c_duration else 0
                    duration_ok = not expected_duration_ms or bool(
                        c_duration > 0 and delta <= max(3500, int(max(int(expected_duration_ms), c_duration) * 0.025))
                    )
                    if song_ok and artist_ok and duration_ok:
                        rows.append((_candidate_score(song_name, artist, row.get('name', ''), c_artist), -delta, row))
                song = max(rows, key=lambda x: (x[0], x[1]))[2] if rows else None
                if songs and song is None:
                    return LyricSearchEngine._fail('网易云', detail='没有找到歌名、歌手和版本时长都足够一致的安全普通歌词版本')
            else:
                preferred_id = str(preferred_song_id or '').strip().split('_')[0]
                if preferred_id:
                    for row in songs:
                        if str(row.get('id') or '') != preferred_id:
                            continue
                        c_song = _clean_name(row.get('name', ''))
                        song_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                        artist_ok, _alias = _artist_alias_match(artist, _artist_text(row)) if str(artist or '').strip() else (True, '')
                        c_duration = int(row.get('duration', 0) or row.get('dt', 0) or 0)
                        duration_ok = True
                        if preferred_duration_ms and c_duration:
                            duration_ok = abs(int(preferred_duration_ms) - c_duration) <= max(1200, int(max(int(preferred_duration_ms), c_duration) * 0.008))
                        if song_ok and artist_ok and duration_ok:
                            song = row
                            break
                if song is None:
                    song = LyricSearchEngine._best(songs, song_name, artist, lambda x: x.get('name', ''), _artist_text)
            if not song:
                return LyricSearchEngine._fail('网易云', detail='没有搜索到匹配歌曲')
            song_id = song.get('id')
            duration = int(song.get('duration', 0) or song.get('dt', 0) or 0)
            LyricSearchEngine._set_provider_meta(
                source='网易云', netease_song_id=str(song_id or ''), duration_ms=duration,
                matched_song=str(song.get('name') or ''), matched_artist=_artist_text(song)
            )
            if LyricSearchEngine._is_cancelled():
                return None, None, duration
            lyric_resp = requests.get(
                'https://music.163.com/api/song/lyric',
                params={'id': int(song_id), 'lv': 1, 'kv': -1, 'tv': -1},
                headers=LyricSearchEngine.HEADERS, timeout=(2.8, 5.0)
            )
            lyric_resp.raise_for_status()
            obj = lyric_resp.json()
            ordinary = _LRC_INLINE_TIME_RE.sub('', str((obj.get('lrc') or {}).get('lyric') or ''))
            translated = str((obj.get('tlyric') or {}).get('lyric') or '')
            tlyric = _translation_to_line_lrc(translated, ordinary)
            if ordinary and _is_instrumental_boilerplate_payload(ordinary):
                LyricSearchEngine.last_error = ''
                write_error_log('网易云经典模式纯音乐占位命中', detail=(
                    f'song_id={song_id} | duration={duration} | timed={int(bool(_LRC_TIME_TOKEN_RE.search(ordinary)))} | word_probe=0'))
                return ordinary, None, duration
            if ordinary and re.search(r'\[\d{1,3}:\d{1,2}', ordinary):
                LyricSearchEngine.last_error = ''
                write_error_log('网易云经典模式普通LRC命中', detail=f'song_id={song_id} | duration={duration} | word_probe=0')
                return ordinary, tlyric or None, duration
            if trans_only and tlyric:
                LyricSearchEngine.last_error = ''
                return ordinary or None, tlyric, duration
            return LyricSearchEngine._fail('网易云', detail='搜索到歌曲，但没有可识别的普通LRC')
        except Exception as exc:
            return LyricSearchEngine._fail('网易云', exc)

    @staticmethod
    def _search_qq_ordinary(song_name, artist="", trans_only=False, expected_duration_ms=0):
        """Fetch QQ ordinary line-LRC only; never call QRC endpoints."""
        try:
            keyword = f"{song_name} {artist}".strip()
            expected_duration_ms = int(expected_duration_ms or 0)
            search_limit = 30 if expected_duration_ms > 0 else 8
            headers = {**LyricSearchEngine.HEADERS, 'Referer': 'https://y.qq.com/'}
            resp = _r2_qq_search_request(
                requests,
                f"https://c.y.qq.com/soso/fcgi-bin/client_search_cp?p=1&n={search_limit}&w={urllib.parse.quote(keyword)}&format=json",
                headers=headers, timeout=8
            )
            resp.raise_for_status()
            songs = ((resp.json().get('data') or {}).get('song') or {}).get('list') or []
            if expected_duration_ms > 0:
                rows = []
                q_song = _clean_name(song_name)
                for row in songs:
                    c_song_text = row.get('songname') or row.get('name') or ''
                    c_song = _clean_name(c_song_text)
                    song_ok = bool(q_song and c_song and (q_song == c_song or q_song in c_song or c_song in q_song))
                    c_artist = _artist_text({'singer': row.get('singer', [])})
                    artist_ok, _alias = _artist_alias_match(artist, c_artist) if str(artist or '').strip() else (True, '')
                    c_duration = int((row.get('interval', 0) or 0) * 1000)
                    delta = abs(expected_duration_ms - c_duration) if c_duration > 0 else 10**9
                    duration_ok = bool(c_duration > 0 and delta <= max(3500, int(max(expected_duration_ms, c_duration) * 0.025)))
                    if song_ok and artist_ok and duration_ok:
                        rows.append((_candidate_score(song_name, artist, c_song_text, c_artist), -delta, row))
                song = max(rows, key=lambda x: (x[0], x[1]))[2] if rows else None
                if song is None:
                    return LyricSearchEngine._fail('QQ音乐', detail='没有找到歌名、歌手和播放器时长都足够一致的安全普通歌词版本')
            else:
                song = LyricSearchEngine._best(
                    songs, song_name, artist,
                    lambda x: x.get('songname') or x.get('name') or '',
                    lambda x: _artist_text({'singer': x.get('singer', [])})
                )
            if not song:
                return LyricSearchEngine._fail('QQ音乐', detail='没有搜索到匹配歌曲')
            songmid = song.get('songmid')
            if not songmid:
                return LyricSearchEngine._fail('QQ音乐', detail='搜索结果缺少 songmid')
            duration = int((song.get('interval', 0) or 0) * 1000)
            lrc_resp = requests.get(
                f"https://c.y.qq.com/lyric/fcgi-bin/fcg_query_lyric_new.fcg?songmid={songmid}&format=json&nobase64=1",
                headers=headers, timeout=8
            )
            lrc_resp.raise_for_status()
            obj = lrc_resp.json()
            ordinary = _LRC_INLINE_TIME_RE.sub('', LyricSearchEngine._decode_qq_lyric(obj.get('lyric', '')))
            tlyric = LyricSearchEngine._decode_qq_translation(obj.get('trans', ''), allow_plain=trans_only)
            if ordinary and _is_instrumental_boilerplate_payload(ordinary):
                LyricSearchEngine.last_error = ''
                write_error_log('QQ经典模式纯音乐占位命中', detail=(
                    f'songmid={songmid} | duration={duration} | timed={int(bool(_LRC_TIME_TOKEN_RE.search(ordinary)))} | qrc_probe=0'))
                return ordinary, None, duration
            if ordinary and re.search(r'\[\d{1,3}:\d{1,2}', ordinary):
                LyricSearchEngine.last_error = ''
                write_error_log('QQ经典模式普通LRC命中', detail=f'songmid={songmid} | duration={duration} | qrc_probe=0')
                return ordinary, tlyric or None, duration
            if trans_only and tlyric:
                LyricSearchEngine.last_error = ''
                return ordinary or None, tlyric, duration
            return LyricSearchEngine._fail('QQ音乐', detail='搜索到歌曲，但没有可识别的普通LRC')
        except Exception as exc:
            return LyricSearchEngine._fail('QQ音乐', exc)

    @staticmethod
    def _search_kugou_ordinary(song_name, artist="", expected_duration_ms=0, trans_only=False):
        """Fetch Kugou line-LRC only; skip lyrics.kugou.com KRC search/download entirely."""
        keyword = f"{song_name} {artist}".strip()

        def clean_markup(value):
            return html.unescape(re.sub(r'<[^>]+>', '', str(value or ''))).strip()

        def normalize(row):
            if not isinstance(row, dict):
                return None
            name = clean_markup(row.get('SongName') or row.get('songname') or row.get('filename', '').split(' - ')[-1])
            singer = clean_markup(row.get('SingerName') or row.get('singername') or row.get('filename', '').split(' - ')[0])
            seconds = row.get('Duration') or row.get('duration') or row.get('duration_s') or 0
            try:
                duration_ms = int(float(seconds) * 1000) if float(seconds or 0) < 10000 else int(float(seconds))
            except Exception:
                duration_ms = 0
            return {
                'songname': name, 'singername': singer, 'duration_ms': duration_ms,
                'hash': row.get('FileHash') or row.get('filehash') or row.get('hash') or row.get('320hash') or row.get('sqhash')
            }

        try:
            resp = requests.get(
                'https://songsearch.kugou.com/song_search_v2',
                params={
                    'keyword': keyword, 'page': 1, 'pagesize': 30 if int(expected_duration_ms or 0) > 0 else 12,
                    'platform': 'WebFilter', 'format': 'json', 'filter': 2, 'iscorrection': 1, 'privilege_filter': 0
                },
                headers={**LyricSearchEngine.HEADERS, 'Referer': 'https://www.kugou.com/'},
                timeout=(2.8, 5.5)
            )
            resp.raise_for_status()
            rows = ((resp.json().get('data') or {}).get('lists') or [])
            songs = [x for x in (normalize(row) for row in rows) if x]
            if not songs:
                return LyricSearchEngine._fail('酷狗', detail='普通歌词搜索入口没有返回歌曲')
            q_song = _clean_name(song_name)
            identity_rows = []
            for row in songs:
                c_song = _clean_name(row.get('songname') or '')
                if not q_song or not c_song or not (q_song == c_song or q_song in c_song or c_song in q_song):
                    continue
                artist_ok, _alias = _artist_alias_match(artist, row.get('singername') or '') if str(artist or '').strip() else (True, '')
                if artist_ok:
                    identity_rows.append(row)
            expected = int(expected_duration_ms or 0)
            song = None
            if expected > 0 and identity_rows:
                limit = max(2500, int(expected * 0.018))
                matches = []
                for row in identity_rows:
                    c_duration = int(row.get('duration_ms') or 0)
                    delta = abs(expected - c_duration) if c_duration > 0 else 10**9
                    if c_duration > 0 and delta <= limit:
                        matches.append((_candidate_score(song_name, artist, row.get('songname') or '', row.get('singername') or ''), -delta, row))
                song = max(matches, key=lambda x: (x[0], x[1]))[2] if matches else None
                if song is None:
                    return LyricSearchEngine._fail('酷狗', detail='没有找到歌名、歌手和播放器时长都足够一致的安全普通歌词版本')
            if song is None:
                song = LyricSearchEngine._best(identity_rows or songs, song_name, artist, lambda x: x.get('songname') or '', lambda x: x.get('singername') or '')
            if not song:
                return LyricSearchEngine._fail('酷狗', detail='没有搜索到匹配歌曲')
            song_hash = song.get('hash')
            duration = int(song.get('duration_ms') or 0)
            if not song_hash:
                return LyricSearchEngine._fail('酷狗', detail='匹配歌曲缺少可用 FileHash')
            lrc_resp = requests.get(
                'https://m.kugou.com/app/i/krc.php',
                params={'cmd': 100, 'hash': song_hash, 'timelength': 999999},
                headers={**LyricSearchEngine.HEADERS, 'Referer': 'https://www.kugou.com/'},
                timeout=(2.8, 5.5)
            )
            lrc_resp.raise_for_status()
            ordinary = _LRC_INLINE_TIME_RE.sub('', str(lrc_resp.text or ''))
            if ordinary and _is_instrumental_boilerplate_payload(ordinary):
                LyricSearchEngine.last_error = ''
                write_error_log('酷狗经典模式纯音乐占位命中', detail=(
                    f'hash={str(song_hash)[:12]}... | duration={duration} | timed={int(bool(_LRC_TIME_TOKEN_RE.search(ordinary)))} | krc_probe=0'))
                return ordinary, None, duration
            if ordinary and re.search(r'\[\d{1,3}:\d{1,2}', ordinary):
                LyricSearchEngine.last_error = ''
                write_error_log('酷狗经典模式普通LRC命中', detail=f'hash={str(song_hash)[:12]}... | duration={duration} | krc_probe=0')
                return ordinary, None, duration
            return LyricSearchEngine._fail('酷狗', detail='搜索到歌曲，但没有可识别的普通LRC')
        except Exception as exc:
            return LyricSearchEngine._fail('酷狗', exc)

    @staticmethod
    def search(song_name, artist="", source="网易云", trans_only=False, provider_track_id=None, provider_duration_ms=0, prefer_precise=True, provider_locked=False, require_translation_pair=False):
        LyricSearchEngine._set_provider_meta()

        # Keep timing-reference and credit-reference separate. Translation-only is now
        # provider-agnostic: use the selected source first, then borrow safely from the
        # other two providers when the native translation is absent.
        translation_reference_lrc = ''
        credit_reference_lrc = ''
        fallback_note = ''
        primary_meta = {}

        def duration_compatible(expected_ms, candidate_ms):
            _core_duration = globals().get('_core_duration_compatible')
            if callable(_core_duration):
                try:
                    return bool(_core_duration(expected_ms, candidate_ms))
                except Exception as exc:
                    _faults = globals().get('_LIMBUS_S2_FAULTS')
                    if _faults is not None:
                        _faults.record('lyric-search.duration-policy', exc)
            expected_ms = int(expected_ms or 0)
            candidate_ms = int(candidate_ms or 0)
            if not expected_ms or not candidate_ms:
                return True
            return abs(expected_ms - candidate_ms) <= max(3500, int(max(expected_ms, candidate_ms) * 0.025))

        def repair_kugou_payload(value):
            import re as _repair_re
            # Keep this local to search() as well as the module helper: replay/audit harnesses
            # intentionally execute LyricSearchEngine.search in isolation.
            base = str(value or '')
            if not base:
                return base, False, ''
            def penalty(text):
                bad_sequences = ('ï»¿', 'Ã', 'Â', 'â€', 'â€™', 'â€œ', 'â€\x9d', 'å', 'æ', 'ç', 'ä', 'é', 'è', 'ð')
                score = sum(str(text or '').count(tok) * (8 if len(tok) > 1 else 1) for tok in bad_sequences)
                return score + str(text or '').count('\ufffd') * 20
            base_times = len(_repair_re.findall(r'\[\d{1,3}:\d{1,2}', base))
            best, best_codec, best_score = base, '', penalty(base)
            for legacy in ('latin1', 'cp1252'):
                try:
                    repaired = base.encode(legacy, errors='strict').decode('utf-8', errors='strict')
                except Exception:
                    continue
                if not repaired or repaired == base or len(_repair_re.findall(r'\[\d{1,3}:\d{1,2}', repaired)) != base_times:
                    continue
                score = penalty(repaired)
                if score + 2 < best_score:
                    best, best_codec, best_score = repaired, legacy, score
            return best, bool(best_codec), best_codec

        # S2 provider boundary.  The registry contains no HTTP/player logic; it only translates
        # one stable query into the mature provider methods.  Dynamic method lookup preserves
        # every later provider safety wrapper while removing provider-specific branching here.
        provider_registry = None
        _provider_registry_cls = globals().get('_core_ProviderRegistry')
        _lyric_query_cls = globals().get('_core_LyricQuery')
        _provider_unavailable_cls = globals().get('_core_ProviderUnavailable', LookupError)
        if callable(_provider_registry_cls) and callable(_lyric_query_cls):
            try:
                provider_registry = _provider_registry_cls.from_legacy_engine(LyricSearchEngine)
            except Exception as exc:
                _faults = globals().get('_LIMBUS_S2_FAULTS')
                if _faults is not None:
                    _faults.record('lyric-search.provider-registry-init', exc)

        def fetch_provider(provider, *, borrow=False, expected_ms=0):
            if provider_registry is not None:
                try:
                    query = _lyric_query_cls(
                        song=song_name, artist=artist, provider=str(provider or ''),
                        trans_only=bool(trans_only), expected_duration_ms=int(expected_ms or 0),
                        provider_track_id=provider_track_id, provider_duration_ms=int(provider_duration_ms or 0),
                        prefer_precise=bool(prefer_precise), borrow=bool(borrow),
                    )
                    result = provider_registry.fetch(query)
                    return result.legacy_tuple()
                except _provider_unavailable_cls:
                    LyricSearchEngine.last_error = f"未知歌词源：{provider}"
                    return None, None, 0
                except Exception as exc:
                    # A registry/glue defect must not take down the mature acquisition path.
                    _faults = globals().get('_LIMBUS_S2_FAULTS')
                    if _faults is not None:
                        _faults.record(
                            'lyric-search.provider-registry-fetch', exc,
                            detail=f'provider={provider} borrow={int(bool(borrow))}'
                        )
                    try:
                        write_error_log('S2歌词Provider契约回退', exc, detail=(
                            f'provider={provider} | borrow={int(bool(borrow))} | action=legacy-direct'))
                    except Exception:
                        pass

            # Fail-safe legacy direct dispatch.  This is intentionally kept until the S2
            # contract has survived Windows field testing.
            LyricSearchEngine._set_provider_meta(source=str(provider or ''), lyric_payload_source=str(provider or ''))
            ordinary_only = not bool(prefer_precise)
            if provider == '网易云':
                fn = LyricSearchEngine._search_netease_ordinary if ordinary_only else LyricSearchEngine.search_netease
                return fn(
                    song_name, artist, trans_only=trans_only,
                    strict_identity=bool(borrow), expected_duration_ms=int(expected_ms or 0),
                    preferred_song_id=(provider_track_id if not borrow else None),
                    preferred_duration_ms=(provider_duration_ms if not borrow else 0)
                )
            if provider == 'QQ音乐':
                fn = LyricSearchEngine._search_qq_ordinary if ordinary_only else LyricSearchEngine.search_qq
                return fn(
                    song_name, artist, trans_only=trans_only,
                    expected_duration_ms=int(expected_ms or (provider_duration_ms if not borrow else 0) or 0)
                )
            if provider == '酷狗':
                fn = LyricSearchEngine._search_kugou_ordinary if ordinary_only else LyricSearchEngine.search_kugou
                return fn(
                    song_name, artist,
                    expected_duration_ms=int(expected_ms or (provider_duration_ms if not borrow else 0) or 0),
                    trans_only=trans_only
                )
            LyricSearchEngine.last_error = f"未知歌词源：{provider}"
            return None, None, 0

        lrc, tlyric, duration = fetch_provider(source, borrow=False, expected_ms=provider_duration_ms)
        primary_meta = LyricSearchEngine.last_provider_meta()
        payload_source = str(source or '')
        payload_provider_meta = dict(primary_meta or {})
        translation_reference_lrc = lrc or ''
        credit_reference_lrc = lrc or ''

        # H95F10 bilingual-source lock: in bilingual mode, choose one provider that can
        # supply BOTH the displayed main lyric and its translation.  Do not compose a row
        # from provider A with translation text from provider B.  The selected lyric-source
        # metadata remains the transport/identity authority; only payload provenance may
        # move to another provider after strict title/artist/duration matching.
        bilingual_pair_locked = False
        if bool(require_translation_pair) and not trans_only and not provider_locked:
            expected_ms = int(provider_duration_ms or duration or 0)
            pair_order = [source] + [p for p in ('网易云', 'QQ音乐', '酷狗') if p != source]
            pair_candidates = []

            def pair_stats(provider, main_payload, trans_payload, candidate_duration, candidate_meta):
                main_payload = str(main_payload or '')
                line_trans = _translation_to_line_lrc(trans_payload, main_payload) if trans_payload else ''
                if not main_payload.strip() or not line_trans.strip():
                    return None
                try:
                    main_rows = len(parse_lrc(main_payload, diagnostics=False))
                except Exception:
                    main_rows = 0
                try:
                    trans_rows = len(parse_lrc(line_trans, diagnostics=False))
                except Exception:
                    trans_rows = 0
                if main_rows <= 0 or trans_rows <= 0:
                    return None
                coverage = min(1.0, float(trans_rows) / float(max(1, main_rows)))
                quality = int(_lyric_clock_quality(main_payload))
                return {
                    'provider': str(provider), 'lrc': main_payload, 'tlyric': line_trans,
                    'duration': int(candidate_duration or 0), 'meta': dict(candidate_meta or {}),
                    'main_rows': int(main_rows), 'trans_rows': int(trans_rows),
                    'coverage': float(coverage), 'quality': int(quality),
                }

            # Reuse the already-fetched preferred source first.
            native_pair = pair_stats(source, lrc, tlyric, duration, primary_meta)
            if native_pair is not None and duration_compatible(expected_ms, duration):
                pair_candidates.append(native_pair)
            # Do not turn every normal bilingual lookup into a three-provider serial request.
            # If the preferred provider already has a substantially complete pair, keep it.
            # Foreign probing is reserved for a missing or materially incomplete translation.
            native_pair_coverage = float((native_pair or {}).get('coverage', 0.0))
            probe_foreign_pair = bool(native_pair is None or native_pair_coverage < 0.90)

            # Probe the remaining providers with strict cross-provider identity/duration proof.
            for provider in (pair_order[1:] if probe_foreign_pair else ()):
                if LyricSearchEngine._is_cancelled():
                    break
                try:
                    alt_lrc, alt_tlyric, alt_duration = fetch_provider(
                        provider, borrow=True, expected_ms=expected_ms
                    )
                    alt_meta = LyricSearchEngine.last_provider_meta()
                except Exception as exc:
                    write_error_log('H95F10双语同源候选失败', exc, detail=(
                        f'from={source} | to={provider} | song={song_name}'))
                    continue
                if expected_ms > 0 and int(alt_duration or 0) <= 0:
                    write_error_log('H95F10双语同源候选时长缺失拒绝', detail=(
                        f'from={source} | to={provider} | song={song_name} | expected={expected_ms}'))
                    continue
                if not duration_compatible(expected_ms, alt_duration):
                    write_error_log('H95F10双语同源候选版本时长拒绝', detail=(
                        f'from={source} | to={provider} | song={song_name} | '
                        f'expected={expected_ms} | candidate={int(alt_duration or 0)}'))
                    continue
                candidate = pair_stats(provider, alt_lrc, alt_tlyric, alt_duration, alt_meta)
                if candidate is not None:
                    pair_candidates.append(candidate)

            if pair_candidates:
                # Completeness first, then precise timing quality.  Keep the user's preferred
                # provider when candidates are effectively tied; otherwise use the provider
                # that actually gives the more complete bilingual pair.
                best = max(pair_candidates, key=lambda row: (
                    round(float(row.get('coverage', 0.0)), 3),
                    int(row.get('quality', 0)),
                    1 if str(row.get('provider')) == str(source) else 0,
                    int(row.get('trans_rows', 0)),
                ))
                chosen = str(best.get('provider') or source)
                lrc = str(best.get('lrc') or '')
                tlyric = str(best.get('tlyric') or '')
                payload_source = chosen
                payload_provider_meta = dict(best.get('meta') or {})
                translation_reference_lrc = lrc
                credit_reference_lrc = lrc
                # Keep the selected/player-owned duration whenever available; foreign duration
                # proves version compatibility but does not gain transport-clock authority.
                duration = int(provider_duration_ms or duration or best.get('duration') or 0)
                bilingual_pair_locked = True
                fallback_note = '' if chosen == source else f'{source}->{chosen}:bilingual-pair'
                LyricSearchEngine.last_error = ''
                write_error_log('H95F10双语同源命中', detail=(
                    f'preferred={source} | payload={chosen} | song={song_name} | artist={artist} | '
                    f'coverage={float(best.get("coverage",0.0)):.3f} | '
                    f'rows={int(best.get("trans_rows",0))}/{int(best.get("main_rows",0))} | '
                    f'quality={int(best.get("quality",0))} | provider-mix=0'))
            else:
                # Preserve main-lyric availability when no provider has a safe bilingual pair.
                # The sidecar fetch is provider-locked below, so the UI will show missing
                # translation instead of silently mixing sources.
                try:
                    write_error_log('H95F10双语同源未命中', detail=(
                        f'preferred={source} | song={song_name} | artist={artist} | '
                        'action=keep-main-lyric-without-cross-source-translation'))
                except Exception:
                    pass

        if not trans_only and not bilingual_pair_locked:
            expected_ms = int(provider_duration_ms or duration or 0)
            legacy_borrow_order = {
                '网易云': ('QQ音乐', '酷狗'), 'QQ音乐': ('网易云', '酷狗'),
                '酷狗': ('网易云', 'QQ音乐'),
            }.get(source, ())
            # Keep the H95F10 source-lock shape explicit for replay/audit readability.
            borrow_order = () if provider_locked else legacy_borrow_order
            if not provider_locked and callable(globals().get('_core_provider_order')):
                try:
                    borrow_order = tuple(p for p in globals().get('_core_provider_order')(source) if p != source)
                except Exception:
                    borrow_order = legacy_borrow_order
            primary_lrc = lrc or ''
            primary_quality = _lyric_clock_quality(primary_lrc)
            primary_duration_safe = duration_compatible(provider_duration_ms, duration)
            primary_instrumental = bool(
                primary_duration_safe and
                _provider_payload_instrumental(source, primary_lrc, expected_ms, primary_meta)
            )
            if primary_instrumental:
                try:
                    write_error_log(
                        '纯音乐主源快速收口',
                        detail=(f'source={source} | song={song_name} | artist={artist} | '
                                f'duration={expected_ms} | quality={primary_quality} | '
                                'cross_provider_enhancement=skip | presentation-only=1')
                    )
                except Exception:
                    pass
            foreign_rows = []

            # Precise mode quality ladder:
            # native precise > verified foreign precise > native ordinary > safe foreign ordinary.
            # Classic mode never asks any provider for word timing; it stays ordinary-only.
            need_foreign = bool(((prefer_precise and primary_quality < 3) or not primary_lrc) and not primary_instrumental)
            if need_foreign:
                for provider in borrow_order:
                    if LyricSearchEngine._is_cancelled():
                        break
                    try:
                        alt_lrc, alt_tlyric, alt_duration = fetch_provider(
                            provider, borrow=True, expected_ms=expected_ms
                        )
                    except Exception as exc:
                        write_error_log('跨平台歌词质量候选失败', exc, detail=f'from={source} | to={provider} | song={song_name}')
                        continue
                    alt_meta = LyricSearchEngine.last_provider_meta()
                    if not alt_lrc:
                        continue
                    if expected_ms > 0 and int(alt_duration or 0) <= 0:
                        write_error_log('跨平台歌词质量候选时长缺失拒绝', detail=(
                            f'from={source} | to={provider} | song={song_name} | expected={expected_ms}'
                        ))
                        continue
                    if not duration_compatible(expected_ms, alt_duration):
                        write_error_log('跨平台歌词质量候选版本时长拒绝', detail=(
                            f'from={source} | to={provider} | song={song_name} | expected={expected_ms} | candidate={int(alt_duration or 0)}'
                        ))
                        continue
                    alt_instrumental = bool(
                        _provider_payload_instrumental(provider, alt_lrc, int(alt_duration or expected_ms or 0), alt_meta)
                    )
                    foreign_rows.append((
                        provider, alt_lrc, alt_tlyric, int(alt_duration or 0),
                        _lyric_clock_quality(alt_lrc), dict(alt_meta or {}), alt_instrumental
                    ))
                    if alt_instrumental and not primary_lrc:
                        write_error_log('跨平台纯音乐证据提前收口', detail=(
                            f'from={source} | to={provider} | song={song_name} | artist={artist} | '
                            f'expected_duration={expected_ms} | candidate_duration={int(alt_duration or 0)} | '
                            'remaining_providers=skip | presentation-only=1'))
                        break

            if not primary_lrc:
                instrumental_row = next((row for row in foreign_rows if row[6]), None)
                if instrumental_row:
                    provider, alt_lrc, alt_tlyric, alt_duration, _q, alt_meta, _inst = instrumental_row
                    lrc = alt_lrc
                    tlyric = alt_tlyric
                    duration = int(alt_duration or expected_ms or 0)
                    payload_source = provider
                    payload_provider_meta = dict(alt_meta or {})
                    credit_reference_lrc = alt_lrc or credit_reference_lrc
                    translation_reference_lrc = alt_lrc or translation_reference_lrc
                    fallback_note = f'{source}->{provider}:instrumental'
                    LyricSearchEngine.last_error = ''

            if bool(prefer_precise) and primary_quality < 3:
                for provider, alt_lrc, alt_tlyric, alt_duration, alt_quality, alt_meta, _alt_instrumental in foreign_rows:
                    if alt_quality < 3:
                        continue
                    verified = alt_lrc
                    verify_stats = {}
                    verify_reason = 'strict-identity-duration-no-native-reference'
                    if primary_lrc and _lyric_clock_quality(primary_lrc) >= 1:
                        delta = abs(int(expected_ms or duration or 0) - int(alt_duration or 0)) if alt_duration else None
                        verified, verify_stats, verify_reason = _verify_precise_enhancement_against_native(
                            primary_lrc, alt_lrc, provider_duration_delta_ms=delta,
                            preserve_provider_phase=(provider == '酷狗')
                        )
                    write_error_log('跨平台逐字质量阶梯诊断', detail=(
                        f'from={source} | to={provider} | song={song_name} | trusted={int(bool(verified))} | '
                        f'reason={verify_reason} | primary_quality={primary_quality} | candidate_quality={alt_quality} | '
                        f'matches={verify_stats.get("matches",0)} | coverage={verify_stats.get("coverage",0.0):.3f} | '
                        f'duration={expected_ms}->{alt_duration}'
                    ))
                    if verified:
                        # R2: without a player-owned duration, a cross-provider precise clock is
                        # only provisional evidence. Same title/artist can still be a different
                        # edit (the field log showed 221.5s precise lyrics temporarily owning a
                        # 242s QQ track). Keep searching/fallback as line timing until the player
                        # proves its duration; never cache/promote this as quality-3 authority.
                        if int(expected_ms or 0) <= 0:
                            write_error_log('R2跨平台逐字候选等待播放器版本证明', detail=(
                                f'from={source} | to={provider} | song={song_name} | '
                                f'foreign_duration={int(alt_duration or 0)} | player_duration=0 | '
                                'authority=provisional-line-only'))
                            continue
                        lrc = LyricSearchEngine._merge_intro_credits(verified, primary_lrc) if primary_lrc else verified
                        tlyric = tlyric or alt_tlyric
                        # Keep the selected player's/native provider duration and identity metadata.
                        duration = int(duration or provider_duration_ms or alt_duration or 0)
                        fallback_note = f'{source}->{provider}:precise'
                        payload_source = provider
                        payload_provider_meta = dict(alt_meta or {})
                        LyricSearchEngine.last_error = ''
                        write_error_log('跨平台逐字质量阶梯命中', detail=(
                            f'from={source} | to={provider} | song={song_name} | artist={artist} | '
                            f'player_duration={expected_ms} | foreign_duration={alt_duration} | quality=precise'
                        ))
                        break

            # Only after every precise candidate has failed may ordinary lyrics win.
            if not lrc:
                ordinary_row = next((row for row in foreign_rows if row[4] >= 1), None)
                if ordinary_row:
                    provider, alt_lrc, alt_tlyric, alt_duration, _q, alt_meta, _alt_instrumental = ordinary_row
                    provisional_version = bool(int(expected_ms or 0) <= 0 and int(_q or 0) >= 3)
                    lrc = LyricSearchEngine._r2_line_only_payload(alt_lrc) if provisional_version else alt_lrc
                    tlyric = alt_tlyric
                    # A foreign duration is not player transport evidence. Keep it out of the
                    # public duration while version identity is still unproved.
                    duration = 0 if provisional_version else int(alt_duration or expected_ms or 0)
                    credit_reference_lrc = alt_lrc or credit_reference_lrc
                    translation_reference_lrc = alt_lrc or translation_reference_lrc
                    fallback_note = (
                        f'{source}->{provider}:provisional-line' if provisional_version
                        else f'{source}->{provider}:ordinary'
                    )
                    payload_source = provider
                    payload_provider_meta = dict(alt_meta or {})
                    LyricSearchEngine.last_error = ''
                    write_error_log('跨平台普通歌词借用命中', detail=(
                        f'from={source} | to={provider} | song={song_name} | artist={artist} | '
                        f'expected_duration={expected_ms} | borrowed_duration={alt_duration} | '
                        f'provisional_line_only={int(provisional_version)}'
                    ))
                    # Retain the established diagnostic label for downstream release/replay tools.
                    write_error_log('跨平台完整歌词借用命中', detail=(
                        f'from={source} | to={provider} | song={song_name} | artist={artist} | '
                        f'expected_duration={expected_ms} | borrowed_duration={alt_duration} | chars={len(alt_lrc or "")}'
                    ))

            # Foreign provider IDs must never replace the selected player's transport identity.
            # Payload provenance is re-attached after final LRC cleanup using safe scalar fields only.
            LyricSearchEngine._set_provider_meta(**primary_meta) if primary_meta else LyricSearchEngine._set_provider_meta()
            if not lrc and borrow_order:
                LyricSearchEngine.last_error = f'{source}及其余歌词平台当前曲目均没有安全匹配歌词'
                write_error_log('三平台完整歌词均未命中', detail=(
                    f'source={source} | song={song_name} | artist={artist} | expected_duration={expected_ms}'
                ))

        if trans_only and not tlyric:
            expected_ms = int(duration or provider_duration_ms or 0)
            legacy_borrow_order = {
                '网易云': ('QQ音乐', '酷狗'), 'QQ音乐': ('网易云', '酷狗'),
                '酷狗': ('网易云', 'QQ音乐'),
            }.get(source, ())
            # Keep the H95F10 source-lock shape explicit for replay/audit readability.
            borrow_order = () if provider_locked else legacy_borrow_order
            if not provider_locked and callable(globals().get('_core_provider_order')):
                try:
                    borrow_order = tuple(p for p in globals().get('_core_provider_order')(source) if p != source)
                except Exception:
                    borrow_order = legacy_borrow_order
            attempts = []
            for provider in borrow_order:
                if LyricSearchEngine._is_cancelled():
                    break
                try:
                    alt_lrc, alt_tlyric, alt_duration = fetch_provider(
                        provider, borrow=True, expected_ms=expected_ms
                    )
                except Exception as exc:
                    attempts.append(f'{provider}:error')
                    write_error_log('跨平台翻译借用失败', exc, detail=f'from={source} | to={provider} | song={song_name}')
                    continue
                if not duration_compatible(expected_ms, alt_duration):
                    attempts.append(f'{provider}:duration-mismatch')
                    write_error_log('跨平台翻译版本时长拒绝', detail=(
                        f'from={source} | to={provider} | song={song_name} | '
                        f'expected={expected_ms} | candidate={int(alt_duration or 0)}'
                    ))
                    continue
                line_alt = _translation_to_line_lrc(alt_tlyric, alt_lrc) if alt_tlyric else ''
                if not line_alt:
                    attempts.append(f'{provider}:no-translation')
                    continue
                lrc = alt_lrc or lrc
                tlyric = line_alt
                duration = int(duration or alt_duration or 0)
                translation_reference_lrc = alt_lrc or translation_reference_lrc
                fallback_note = f'{source}->{provider}'
                LyricSearchEngine.last_error = ''
                write_error_log('跨平台仅翻译借用命中', detail=(
                    f'from={source} | to={provider} | song={song_name} | artist={artist} | '
                    f'expected_duration={expected_ms} | borrowed_duration={int(alt_duration or 0)} | '
                    f'chars={len(line_alt)}'
                ))
                break
            if not tlyric and attempts:
                LyricSearchEngine.last_error = '网易云、QQ音乐、酷狗：当前曲目均没有可用翻译歌词'
                write_error_log('三平台仅翻译均未命中', detail=(
                    f'source={source} | song={song_name} | artist={artist} | attempts={attempts}'
                ))
            # Borrowing must not replace the selected provider's identity metadata used by
            # MediaSync (especially NetEase bridge song_id).
            if primary_meta:
                LyricSearchEngine._set_provider_meta(**primary_meta)

        # KuGou ordinary-LRC can be UTF-8 bytes decoded as a legacy charset.  Repair the
        # actual lyric payload here (not merely the pure-music detector) so normal lyrics and
        # intro credits cannot spray mojibake onto the desktop.  Clock tokens remain byte-for-
        # byte equivalent and the transport/player source is untouched.
        if lrc and str(payload_source or '') == '酷狗':
            _repaired_lrc, _repaired_changed, _repaired_codec = repair_kugou_payload(lrc)
            if _repaired_changed:
                try:
                    _before_preview = re.sub(r'\s+', ' ', str(lrc or ''))[:72]
                    _after_preview = re.sub(r'\s+', ' ', str(_repaired_lrc or ''))[:72]
                    write_error_log('酷狗歌词正文可逆乱码修复', detail=(
                        f'codec={_repaired_codec}->utf8 | song={song_name} | '
                        f'before={_before_preview} | after={_after_preview} | timing=preserved'))
                except Exception:
                    pass
                lrc = _repaired_lrc
                if credit_reference_lrc:
                    _credit_fixed, _credit_changed, _ = repair_kugou_payload(credit_reference_lrc)
                    if _credit_changed:
                        credit_reference_lrc = _credit_fixed
                if translation_reference_lrc:
                    _trans_fixed, _trans_changed, _ = repair_kugou_payload(translation_reference_lrc)
                    if _trans_changed:
                        translation_reference_lrc = _trans_fixed

        clean_lrc = LyricSearchEngine._clean_lrc(lrc, song_name, artist) if lrc else ''

        def _finalize_payload_meta(payload_text):
            try:
                final_meta = _build_lyric_payload_meta(
                    primary_meta, payload_source, payload_text, duration or provider_duration_ms or 0,
                    payload_provider_meta
                )
                LyricSearchEngine._set_provider_meta(**final_meta)
            except Exception:
                LyricSearchEngine._set_provider_meta(**primary_meta) if primary_meta else LyricSearchEngine._set_provider_meta()

        if trans_only:
            line_tlyric = _translation_to_line_lrc(
                tlyric, translation_reference_lrc or lrc
            ) if tlyric else ''
            native_reference_lrc = credit_reference_lrc or translation_reference_lrc or lrc
            if not line_tlyric:
                # A Chinese original needs no translation field. In translation-only mode,
                # returning its native Chinese rows is more faithful than reporting "no translation".
                line_tlyric = _extract_native_chinese_lrc(native_reference_lrc)
                if line_tlyric:
                    try:
                        write_error_log('仅翻译使用原曲中文歌词', detail=f'rows={len(line_tlyric.splitlines())}')
                    except Exception:
                        pass
            if line_tlyric:
                line_tlyric = _merge_translation_native_chinese(
                    line_tlyric, native_reference_lrc
                )
                line_tlyric = LyricSearchEngine._merge_intro_credits(
                    line_tlyric, credit_reference_lrc or lrc
                )
                if fallback_note and translation_reference_lrc and translation_reference_lrc != credit_reference_lrc:
                    line_tlyric = LyricSearchEngine._merge_intro_credits(
                        line_tlyric, translation_reference_lrc
                    )
            clean_tlyric = LyricSearchEngine._clean_lrc(line_tlyric, song_name, artist) if line_tlyric else ''
            if clean_tlyric.strip():
                _finalize_payload_meta(clean_tlyric)
                return clean_tlyric, duration
            if not LyricSearchEngine.last_error:
                LyricSearchEngine.last_error = f"{source}及其余歌词平台当前曲目没有可用翻译歌词"
            _finalize_payload_meta('')
            return None, duration
        clean_tlyric = LyricSearchEngine._clean_lrc(tlyric, song_name, artist) if tlyric else ''
        if clean_lrc.strip():
            if bool(require_translation_pair) and bool(bilingual_pair_locked) and clean_tlyric.strip():
                try:
                    LyricSearchEngine._remember_bilingual_pair(
                        song_name, artist, payload_source, duration or provider_duration_ms or 0,
                        clean_lrc, clean_tlyric
                    )
                except Exception:
                    pass
            _finalize_payload_meta(clean_lrc)
            return clean_lrc, duration
        if clean_tlyric.strip():
            _finalize_payload_meta(clean_tlyric)
            return clean_tlyric, duration
        _finalize_payload_meta('')
        return None, duration


# ==================== 网易云内部播放器时钟 Bridge ====================
class NeteaseInternalClockBridge:
    """Receive NetEase's own audioplayer.onPlayProgress clock over localhost only.

    The companion plugin runs inside NetEase Chromium and POSTs currentTime to this
    tiny server. It never controls playback and never accepts commands from LimbusLyric.
    Binding to 127.0.0.1 keeps the bridge local to this PC; UIA remains the fallback
    when the plugin is absent.
    """
    def __init__(self):
        self.enabled = bool(NETEASE_INTERNAL_BRIDGE_ENABLED)
        self._lock = threading.Lock()
        self._server = None
        self._thread = None
        self._port = None
        self._sample = None
        self._meta = {
            'track_id': '', 'duration_ms': None, 'play_state': 'unknown',
            'load_received_mono': 0.0, 'state_received_mono': 0.0, 'explicit_state_received_mono': 0.0,
            'progress_received_mono': 0.0, 'last_received_mono': 0.0,
            'cached_position_ms': None, 'cached_position_age_ms': None, 'cached_position_received_mono': 0.0,
            'load_page_seq': 0, 'state_page_seq': 0,
            'plugin_loaded': False, 'channel_ready': False, 'bridge_version': '',
            'host_ua': '', 'hello_received_mono': 0.0, 'diagnostic': '',
        }
        self._local_seq = 0
        self._started = False

    @property
    def port(self):
        with self._lock:
            return self._port

    def start(self):
        if not self.enabled:
            return False
        with self._lock:
            if self._server is not None and self._thread is not None and self._thread.is_alive():
                return True

        bridge = self

        class Handler(http.server.BaseHTTPRequestHandler):
            server_version = 'LimbusLyricNCMBridge/1'
            protocol_version = 'HTTP/1.1'

            def log_message(self, fmt, *args):
                return

            def _headers(self, code=200, content_type='application/json; charset=utf-8', length=0, cors=True):
                self.send_response(code)
                self.send_header('Content-Type', content_type)
                if cors:
                    self.send_header('Access-Control-Allow-Origin', '*')
                    self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
                    self.send_header('Access-Control-Allow-Headers', 'Content-Type')
                    self.send_header('Access-Control-Allow-Private-Network', 'true')
                self.send_header('Cache-Control', 'no-store')
                self.send_header('Connection', 'close')
                self.send_header('Content-Length', str(int(length)))
                self.end_headers()

            def _json(self, obj, code=200, cors=True):
                raw = json.dumps(obj, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
                self._headers(code=code, length=len(raw), cors=cors)
                try:
                    self.wfile.write(raw)
                except Exception:
                    pass

            def do_OPTIONS(self):
                self._headers(code=204, length=0)

            def do_GET(self):
                if self.path.startswith('/v1/ping'):
                    self._json({'ok': True, 'service': 'LimbusLyric-NCM-Bridge', 'protocol': 1, 'port': bridge.port})
                    return
                if self.path.startswith('/v1/plugin-heartbeat'):
                    try:
                        parsed = urllib.parse.urlparse(self.path)
                        q = urllib.parse.parse_qs(parsed.query or '')
                        bridge._accept({
                            'protocol': 1, 'event': 'hello',
                            'bridge_version': str((q.get('v') or [''])[0]),
                            'channel_ready': str((q.get('channel') or ['0'])[0]).lower() in ('1','true','yes'),
                            'diagnostic': str((q.get('diag') or ['image-heartbeat'])[0]),
                            'source': 'plugin-image-heartbeat',
                        })
                    except Exception:
                        pass
                    self._headers(code=204, length=0)
                    return
                if self.path.startswith('/v1/status'):
                    snap = bridge.snapshot(max_age_ms=86400000.0)
                    # Diagnostic tools are native Python/PowerShell and do not need browser CORS.
                    # Avoid exposing current track/position/host metadata to arbitrary web pages.
                    self._json({
                        'ok': True,
                        'service': 'LimbusLyric-NCM-Bridge',
                        'protocol': 1,
                        'port': bridge.port,
                        'sample': snap,
                        'meta': bridge.meta_snapshot(),
                    }, cors=False)
                    return
                self._json({'ok': False, 'error': 'not-found'}, 404)

            def do_POST(self):
                if not self.path.startswith('/v1/ncm-clock'):
                    self._json({'ok': False, 'error': 'not-found'}, 404)
                    return
                try:
                    length = int(self.headers.get('Content-Length') or 0)
                except Exception:
                    length = 0
                if length <= 0 or length > 8192:
                    self._json({'ok': False, 'error': 'bad-length'}, 400)
                    return
                try:
                    raw = self.rfile.read(length)
                    payload = json.loads(raw.decode('utf-8', errors='strict'))
                except Exception:
                    self._json({'ok': False, 'error': 'bad-json'}, 400)
                    return
                if not isinstance(payload, dict) or not bridge._accept(payload):
                    self._json({'ok': False, 'error': 'bad-payload'}, 400)
                    return
                self._json({'ok': True, 'service': 'LimbusLyric-NCM-Bridge', 'protocol': 1})

        server = None
        chosen = None
        first = int(NETEASE_INTERNAL_BRIDGE_PORT_FIRST)
        for port in range(first, first + max(1, int(NETEASE_INTERNAL_BRIDGE_PORT_COUNT))):
            try:
                server_cls = http.server.ThreadingHTTPServer if NETEASE_INTERNAL_BRIDGE_THREADED_SERVER else http.server.HTTPServer
                server = server_cls(('127.0.0.1', int(port)), Handler)
                server.daemon_threads = True
                server.allow_reuse_address = True
                chosen = int(port)
                break
            except OSError:
                server = None
                continue
            except Exception:
                server = None
                continue
        if server is None:
            if SOURCE_GUARD_ENABLED:
                try:
                    write_error_log(
                        '网易云内部时钟Bridge监听失败',
                        detail=f'ports={first}-{first + max(1, int(NETEASE_INTERNAL_BRIDGE_PORT_COUNT)) - 1} | fallback=UIA'
                    )
                except Exception:
                    pass
            return False

        with self._lock:
            self._server = server
            self._port = chosen
            self._started = True

        def run():
            try:
                server.serve_forever(poll_interval=0.25)
            except Exception as exc:
                if SOURCE_GUARD_ENABLED:
                    try:
                        write_error_log('网易云内部时钟Bridge线程结束', exc)
                    except Exception:
                        pass
            finally:
                try:
                    server.server_close()
                except Exception:
                    pass

        thread = threading.Thread(target=run, name='LimbusLyric-NCMBridge', daemon=True)
        with self._lock:
            self._thread = thread
        thread.start()
        if SOURCE_GUARD_ENABLED:
            try:
                write_error_log(
                    '网易云内部时钟Bridge监听启动',
                    detail=f'addr=127.0.0.1:{chosen} | protocol=1 | server={"thread-per-request" if NETEASE_INTERNAL_BRIDGE_THREADED_SERVER else "single-thread"} | host_diag=1 | mouse_hover_default=off | fallback=UIA'
                )
            except Exception:
                pass
        return True

    def stop(self):
        with self._lock:
            server = self._server
            self._server = None
            self._thread = None
            self._port = None
            self._started = False
            self._sample = None
            self._meta = {
                'track_id': '', 'duration_ms': None, 'play_state': 'unknown',
                'load_received_mono': 0.0, 'state_received_mono': 0.0, 'explicit_state_received_mono': 0.0,
                'progress_received_mono': 0.0, 'last_received_mono': 0.0,
                'cached_position_ms': None, 'cached_position_age_ms': None, 'cached_position_received_mono': 0.0,
                'load_page_seq': 0, 'state_page_seq': 0,
            }
        if server is not None:
            try:
                server.shutdown()
            except Exception:
                pass
            try:
                server.server_close()
            except Exception:
                pass

    def _accept(self, payload):
        try:
            protocol = int(payload.get('protocol', 1) or 1)
            if protocol != 1:
                return False
            event = str(payload.get('event') or 'progress')[:32].lower()
            now = time.monotonic() * 1000.0
            track_id = str(payload.get('track_id') or '')[:160].split('_')[0]
            page_seq = int(payload.get('seq') or 0)
            duration_ms = payload.get('duration_ms')
            try:
                duration_ms = None if duration_ms is None else float(duration_ms)
                if duration_ms is not None and (not math.isfinite(duration_ms) or duration_ms <= 0.0 or duration_ms > 24.0 * 3600.0 * 1000.0):
                    duration_ms = None
            except Exception:
                duration_ms = None

            raw_state = str(payload.get('play_state') or '').strip().lower()
            play_state = raw_state if raw_state in ('playing', 'paused', 'stopped') else 'unknown'
            bridge_version = str(payload.get('bridge_version') or '')[:48]
            host_ua = str(payload.get('host_ua') or '')[:240]
            diagnostic = str(payload.get('diagnostic') or '')[:240]
            channel_ready_raw = payload.get('channel_ready')
            channel_ready = None if channel_ready_raw is None else bool(channel_ready_raw)
            cached_position_ms = payload.get('cached_position_ms')
            cached_position_age_ms = payload.get('cached_position_age_ms')
            try:
                cached_position_ms = None if cached_position_ms is None else float(cached_position_ms)
                if cached_position_ms is not None and (not math.isfinite(cached_position_ms) or cached_position_ms < 0.0 or cached_position_ms > 24.0 * 3600.0 * 1000.0):
                    cached_position_ms = None
            except Exception:
                cached_position_ms = None
            try:
                cached_position_age_ms = None if cached_position_age_ms is None else max(0.0, float(cached_position_age_ms))
                if cached_position_age_ms is not None and (not math.isfinite(cached_position_age_ms) or cached_position_age_ms > 7.0 * 24.0 * 3600.0 * 1000.0):
                    cached_position_age_ms = None
            except Exception:
                cached_position_age_ms = None

            with self._lock:
                previous_track = str(self._meta.get('track_id') or '')
                if track_id and previous_track and track_id != previous_track and event in ('load', 'progress', 'state', 'hello', 'ready', 'diagnostic'):
                    # Never let the previous song's last progress/cached sample survive a real internal track change.
                    self._sample = None
                    self._meta['cached_position_ms'] = None
                    self._meta['cached_position_age_ms'] = None
                    self._meta['cached_position_received_mono'] = 0.0
                if track_id:
                    self._meta['track_id'] = track_id
                if duration_ms is not None:
                    self._meta['duration_ms'] = float(duration_ms)
                if play_state != 'unknown':
                    self._meta['play_state'] = play_state
                    # Progress packets carry the last internal play state too. Treat that as a
                    # fresh state heartbeat so starting LimbusLyric mid-song does not have to wait
                    # for the next explicit pause/resume transition.
                    self._meta['state_received_mono'] = float(now)
                self._meta['last_received_mono'] = float(now)
                if bridge_version:
                    self._meta['bridge_version'] = bridge_version
                if host_ua:
                    self._meta['host_ua'] = host_ua
                if diagnostic:
                    self._meta['diagnostic'] = diagnostic
                if channel_ready is not None:
                    self._meta['channel_ready'] = bool(channel_ready)
                if cached_position_ms is not None:
                    self._meta['cached_position_ms'] = float(cached_position_ms)
                    self._meta['cached_position_age_ms'] = cached_position_age_ms
                    self._meta['cached_position_received_mono'] = float(now)

                if event in ('hello', 'ready', 'diagnostic'):
                    self._meta['plugin_loaded'] = True
                    self._meta['hello_received_mono'] = float(now)
                    if event == 'ready':
                        self._meta['channel_ready'] = True
                    return True

                if event == 'load':
                    self._meta['load_received_mono'] = float(now)
                    self._meta['load_page_seq'] = int(page_seq)
                    return True

                if event == 'state':
                    self._meta['state_received_mono'] = float(now)
                    self._meta['explicit_state_received_mono'] = float(now)
                    self._meta['state_page_seq'] = int(page_seq)
                    return True

                if event != 'progress':
                    return False

                pos = payload.get('position_ms')
                if pos is None and payload.get('position') is not None:
                    pos = float(payload.get('position')) * 1000.0
                pos = float(pos)
                if not math.isfinite(pos) or pos < 0.0 or pos > 24.0 * 3600.0 * 1000.0:
                    return False
                self._local_seq += 1
                self._meta['progress_received_mono'] = float(now)
                # A real progress callback is also the newest cached native position.
                self._meta['cached_position_ms'] = float(pos)
                self._meta['cached_position_age_ms'] = 0.0
                self._meta['cached_position_received_mono'] = float(now)
                self._sample = {
                    'local_seq': int(self._local_seq), 'page_seq': page_seq,
                    'event': 'progress', 'track_id': str(self._meta.get('track_id') or track_id),
                    'position_ms': float(pos),
                    'duration_ms': self._meta.get('duration_ms'),
                    'play_state': str(self._meta.get('play_state') or 'unknown'),
                    'received_mono': now,
                    'load_received_mono': float(self._meta.get('load_received_mono') or 0.0),
                    'state_received_mono': float(self._meta.get('state_received_mono') or 0.0),
                    'source': str(payload.get('source') or 'audioplayer.onPlayProgress')[:96],
                }
                return True
        except Exception:
            return False

    def meta_snapshot(self):
        with self._lock:
            meta = dict(self._meta)
        now = time.monotonic() * 1000.0
        for key in ('last_received_mono', 'load_received_mono', 'state_received_mono', 'explicit_state_received_mono', 'progress_received_mono', 'cached_position_received_mono'):
            try:
                mono = float(meta.get(key) or 0.0)
                meta[key.replace('_mono', '_age_ms')] = (max(0.0, now - mono) if mono > 0.0 else None)
            except Exception:
                meta[key.replace('_mono', '_age_ms')] = None
        return meta

    def snapshot(self, max_age_ms=None, paused_hint=False):
        if max_age_ms is None:
            max_age_ms = NETEASE_INTERNAL_BRIDGE_MAX_AGE_MS
        with self._lock:
            sample = dict(self._sample) if isinstance(self._sample, dict) else None
            meta = dict(self._meta)
        now = time.monotonic() * 1000.0
        def cached_paused_sample():
            # BetterNCM may stop onPlayProgress while paused. Bridge heartbeats carry
            # the last native currentTime, so a listener started mid-song can still bind the
            # exact paused position without waking Chromium/UIA. Never synthesize this while
            # playing: a frozen cached position must not masquerade as a running clock.
            internal_paused = str(meta.get('play_state') or '') == 'paused'
            if not (internal_paused or bool(paused_hint)):
                return None
            cached = meta.get('cached_position_ms')
            received = float(meta.get('last_received_mono') or meta.get('cached_position_received_mono') or 0.0)
            if cached is None or received <= 0.0:
                return None
            heartbeat_age = max(0.0, now - received)
            if heartbeat_age > float(NETEASE_INTERNAL_BRIDGE_PAUSED_HEARTBEAT_GRACE_MS):
                return None
            return {
                'local_seq': int(self._local_seq), 'page_seq': int(meta.get('state_page_seq') or 0),
                'event': 'cached-paused', 'track_id': str(meta.get('track_id') or ''),
                'position_ms': float(cached), 'duration_ms': meta.get('duration_ms'),
                'play_state': 'paused', 'received_mono': float(received), 'age_ms': float(heartbeat_age),
                'paused_hint': int(bool(paused_hint and not internal_paused)),
                'load_received_mono': float(meta.get('load_received_mono') or 0.0),
                'state_received_mono': float(meta.get('state_received_mono') or 0.0),
                'source': 'bridge.cached-paused',
            }
        if not sample:
            return cached_paused_sample()
        try:
            age = max(0.0, now - float(sample.get('received_mono') or now))
        except Exception:
            return cached_paused_sample()
        sample['age_ms'] = age
        if age > float(max_age_ms):
            return cached_paused_sample()
        if sample.get('position_ms') is None:
            return cached_paused_sample()
        sample['track_id'] = str(meta.get('track_id') or sample.get('track_id') or '')
        sample['duration_ms'] = meta.get('duration_ms') or sample.get('duration_ms')
        sample['play_state'] = str(meta.get('play_state') or sample.get('play_state') or 'unknown')
        sample['load_received_mono'] = float(meta.get('load_received_mono') or sample.get('load_received_mono') or 0.0)
        sample['state_received_mono'] = float(meta.get('state_received_mono') or sample.get('state_received_mono') or 0.0)
        return sample
def _kugou_host_candidate_score(class_name, title, rect, visible=True, iconic=False):
    """Score a top-level window as the official KuGou desktop host.

    This intentionally does not require a process-list lookup. Field logs repeatedly show
    the stable KuGou top-level class ``kugou_ui`` even when tasklist/PID resolution races.
    ``kugou_mv_win`` is explicitly excluded so an open MV window cannot become the rail host.
    """
    if not visible or iconic or not rect or len(rect) != 4:
        return -100000
    try:
        l, t, r, b = [int(v) for v in rect]
    except Exception:
        return -100000
    w, h = max(0, r-l), max(0, b-t)
    if w < 360 or h < 220:
        return -100000
    cls = str(class_name or '').strip().lower()
    text = str(title or '').strip()
    low = text.lower()
    if cls == 'kugou_mv_win' or '酷狗mv' in low:
        return -100000
    explicit_kugou = bool(
        cls == 'kugou_ui' or 'kugou' in cls or 'kgmusic' in cls or '酷狗音乐' in text
    )
    if not explicit_kugou:
        return -100000
    score = 0
    if cls == 'kugou_ui':
        score += 1200
    elif 'kugou' in cls or 'kgmusic' in cls:
        score += 260
    if '酷狗音乐' in text:
        score += 720
    if text.endswith(' - 酷狗音乐'):
        score += 220
    if cls == 'kugou_ui' and text:
        score += 140
    # Prefer the content-bearing player over oversized shells while still accepting the
    # blank kugou_ui frame observed on some builds.
    area = w*h
    score += min(180, int(area / 18000))
    if w >= 700 and h >= 420:
        score += 90
    return int(score)


def _kugou_range_clock_candidate(control_type, value, minimum, maximum, known_duration_ms=0):
    """Interpret a KuGou RangeValue without assuming lyric duration is already loaded.

    The official desktop progress Slider observed in host logs uses centiseconds.  When a
    verified lyric duration exists, keep the historical ratio-based interpretation unless
    the native maximum clearly changed to another track.  Without a known duration, only
    a plausible centisecond Slider range is accepted; percent/volume ranges stay rejected.
    """
    try:
        val=float(value); mn=float(minimum); mx=float(maximum); known=float(known_duration_ms or 0.0)
    except Exception:
        return None
    span=mx-mn
    if span <= 0.0:
        return None
    ratio=max(0.0,min(1.0,(val-mn)/span))
    native_duration=None
    if str(control_type or '') == 'Slider' and 3000.0 <= span <= 360000.0:
        nd=span*10.0
        if 30000.0 <= nd <= 3600000.0:
            native_duration=nd
    if known > 1000.0:
        native_mismatch=False
        if native_duration is not None:
            tol=max(2500.0,max(native_duration,known)*0.018)
            native_mismatch=abs(native_duration-known) > tol
        observed=((val-mn)*10.0) if (native_duration is not None and native_mismatch) else ratio*known
        return {
            'observed_ms':float(observed), 'duration_ms':float(known), 'ratio':float(ratio),
            'native_duration_ms':native_duration, 'native_mismatch':bool(native_mismatch),
        }
    if native_duration is None:
        return None
    return {
        'observed_ms':float((val-mn)*10.0), 'duration_ms':float(native_duration), 'ratio':float(ratio),
        'native_duration_ms':float(native_duration), 'native_mismatch':False,
    }


def _kugou_progress_proof_step(pending, observed_ms, now_ms, status, source_key):
    """Transport-aware proof for a candidate UIA progress control.

    A volume slider can have a perfectly valid RangeValue, so range geometry alone is not
    authority. The candidate must stay frozen while paused or advance at roughly wall-clock
    pace while playing. Returns (new_pending, proven).
    """
    try:
        obs = float(observed_ms); now = float(now_ms)
    except Exception:
        return None, False
    st = str(status or 'unknown')
    key = str(source_key or '')
    if st not in ('playing', 'paused') or not key:
        return None, False
    p = pending if isinstance(pending, dict) and pending.get('source_key') == key else None
    if not p:
        return {'source_key': key, 'last': obs, 'last_mono': now, 'first_mono': now, 'count': 1}, False
    dt = max(1.0, now - float(p.get('last_mono') or now))
    dp = obs - float(p.get('last') or obs)
    if st == 'playing':
        tol = max(520.0, dt * 0.80)
        min_adv = max(60.0, min(180.0, dt * 0.25))
        coherent = (dp >= min_adv and abs(dp - dt) <= tol)
    else:
        coherent = abs(dp) <= max(220.0, dt * 0.18)
    if not coherent:
        return {'source_key': key, 'last': obs, 'last_mono': now, 'first_mono': now, 'count': 1}, False
    q = dict(p)
    q['last'] = obs; q['last_mono'] = now; q['count'] = int(q.get('count') or 1) + 1
    span = max(0.0, now - float(q.get('first_mono') or now))
    return q, bool(q['count'] >= 3 and span >= float(KUGOU_HOST_V2_PROGRESS_MIN_SPAN_MS))


def _qq_duration_replays_prebind(candidate_ms, prebind_ui_ms=0, prebind_transport_ms=0, prebind_source=''):
    """True when a post-bind QQ duration is still indistinguishable from the old epoch.

    QQ can publish MediaProperties for the next song before its TimelineProperties/current-total
    controls leave the previous song.  A bind boundary therefore cannot itself make an unchanged
    duration fresh.  The dedicated track-switch hint is the only pre-bind duration already proven
    to belong to the new transport; otherwise a value matching either pre-bind UIA or direct
    GSMTC remains quarantined until the player publishes a different duration.  Same-duration
    consecutive songs safely fall back to title/artist-only retrieval rather than risking a hard
    version filter from ambiguous evidence.
    """
    try:
        cand = int(candidate_ms or 0)
    except Exception:
        return False
    if cand <= 0 or str(prebind_source or '') == 'qq-track-switch-hint':
        return False
    for raw in (prebind_ui_ms, prebind_transport_ms):
        try:
            ref = int(raw or 0)
        except Exception:
            ref = 0
        if ref <= 0:
            continue
        tol = max(1800, int(max(cand, ref) * 0.018))
        if abs(cand - ref) <= tol:
            return True
    return False


def _kugou_same_identity_end_continuation_step(
    pending, position_ms, duration_ms, status, now_ms, host_clock_fresh=False, visual_clock_fresh=False
):
    """Prove a hidden KuGou same-identity play-instance rollover at the end boundary.

    Title/artist are intentionally *not* evidence here: a playlist can contain several
    indistinguishable copies of the same song, while repeated MediaProperties polling is
    not a new publication. When Host-V2/visual rail is available it remains authoritative.
    Only while both are unavailable may a duration-clamped local rail that has genuinely
    reached the end and is still reported as ``playing`` accumulate a short continuation
    proof. Normal mid-song pause/resume therefore cannot create a new play instance.
    """
    try:
        pos = float(position_ms or 0.0)
        dur = float(duration_ms or 0.0)
        now = float(now_ms or 0.0)
    except Exception:
        return None, False, 'invalid'
    if dur < 10000.0 or str(status or '') != 'playing':
        return None, False, 'inactive'
    if bool(host_clock_fresh) or bool(visual_clock_fresh):
        return None, False, 'real-clock-present'
    margin = max(30.0, min(220.0, dur * 0.0015))
    if pos < max(0.0, dur - margin):
        return None, False, 'not-at-end'
    if not isinstance(pending, dict) or abs(float(pending.get('duration_ms') or 0.0) - dur) > max(500.0, dur * 0.01):
        return {
            'first_mono': now, 'last_mono': now, 'duration_ms': dur,
            'hits': 1, 'position_ms': pos,
        }, False, 'arming'
    first = float(pending.get('first_mono') or now)
    hits = int(pending.get('hits') or 1) + 1
    next_pending = dict(pending)
    next_pending.update(last_mono=now, hits=hits, position_ms=pos)
    dwell = max(0.0, now - first)
    # Longer than ordinary provider-duration tail mismatch, but short enough that an
    # identical next playlist item does not appear permanently stuck at the old end.
    if hits >= 3 and dwell >= 1250.0:
        return None, True, f'end-playing-dwell:{int(round(dwell))}ms'
    return next_pending, False, f'waiting:{int(round(dwell))}ms/{hits}'


class MediaSessionSync:
    """后台读取 Windows GSMTC 媒体会话。不可用时保持静默并让歌词回退到本地计时。"""
    def __init__(self):
        # 真正延迟到用户点击“获取歌词/开始”时才加载 WinRT。
        # 避免某些机器的 WinRT DLL/ABI 问题在程序启动阶段直接终止进程。
        self.available = False
        self._lock = threading.Lock()
        self._state = {
            'connected': False, 'position_ms': None, 'raw_position_ms': None,
            'status': 'unknown', 'playback_rate': 1.0,
            'timeline_last_updated_ms': None,
            'title': '', 'artist': '', 'source': '', 'updated_at': 0,
            # `title/artist` may also be populated by bind_track(). Keep the externally
            # detected media identity separate so auto-track can never mistake a bound
            # lyric title (or another player's stale GSMTC title) for fresh player metadata.
            'media_title': '', 'media_artist': '', 'media_source': '', 'media_metadata_mono': 0.0,
            'sync_requested': False, 'sync_waiting': False,
            'position_anchor_mono': None, 'duration_ms': None, 'seek_serial': 0,
            'kugou_transport_generation': 0, 'qq_transport_generation': 0,
            'player_alive': None, 'player_liveness': 'unknown',
            'player_liveness_process': '', 'player_liveness_serial': 0,
        }
        self._process_hint = ''
        self._snapshot_slow_log_mono = 0.0
        # H8: process-image lookup (OpenProcess/GetModuleFileNameEx) can take hundreds of
        # milliseconds on some Windows/security configurations. Never execute it from
        # snapshot(), which is called by the lyric GUI clock. Click edges enqueue a tiny
        # verifier and snapshot only consumes completed results.
        self._click_target_probe_lock = threading.Lock()
        self._click_target_probe_serial = 0
        self._click_target_probe_inflight = {}
        self._click_target_probe_results = {}
        self._click_target_probe_last_request = {}
        self._stop_event = threading.Event()
        self._thread = None
        # 状态化时间轴估算器：不要在暂停/恢复时反复用旧 LastUpdatedTime 从头外推。
        self._est_position_ms = None
        self._est_anchor_mono = None
        self._est_status = 'unknown'
        self._timeline_signature = None
        self._est_source = ''
        self._last_sync_diag = None
        self._uia_reader = AsyncPlayerUiPositionReader()
        self._netease_bridge = NeteaseInternalClockBridge()
        self._netease_bridge_primary = False
        self._netease_bridge_last_local_seq = -1
        self._netease_bridge_last_position_ms = None
        self._netease_bridge_last_mono = None
        self._netease_bridge_bind_mono = 0.0
        self._netease_bridge_last_diag_mono = 0.0
        self._netease_bridge_expected_track_id = ''
        self._netease_bridge_bound_track_id = ''
        self._netease_bridge_identity_reject_last_mono = 0.0
        self._netease_bridge_duration_warn_last_mono = 0.0
        self._netease_bridge_duration_warn_key = ''
        # Full content duration (lyrics/catalog) and currently playable duration are different
        # concepts. A 30s member-preview of a 328s song is valid, not stale metadata.
        self._netease_bridge_content_duration_ms = None
        self._netease_bridge_playable_duration_ms = None
        self._netease_bridge_limited_playback = False
        # Transport health is independent of track identity. A fresh packet with a temporarily
        # mismatched ID during next/previous is a transition, not a Bridge outage.
        self._netease_bridge_transition_waiting = False
        self._netease_bridge_allow_unknown_autobind = True
        self._netease_bridge_transport_last_seen_mono = 0.0
        self._netease_bridge_bootstrap_until_mono = 0.0

        # NetEase native log clock (cloudmusic_detector). It is started lazily on the
        # MediaSessionSync asyncio worker and never touches the Qt GUI thread. Bridge
        # remains first choice; this becomes the normal no-plugin clock before UIA.
        self._netease_native = (NeteaseNativeClockAdapter() if (NETEASE_NATIVE_LOG_ENABLED and NeteaseNativeClockAdapter is not None) else None)
        self._netease_native_primary = False
        self._netease_native_last_position_ms = None
        self._netease_native_last_mono = 0.0
        self._netease_native_last_track_key = ''
        self._netease_native_last_track_serial = -1
        self._netease_native_last_seek_serial = -1
        self._netease_native_transition_pending = False
        self._netease_native_transition_old_position_ms = None
        self._netease_native_transition_started_mono = 0.0
        self._netease_native_seek_guard_until_mono = 0.0
        self._netease_native_last_diag_mono = 0.0
        self._netease_native_import_logged = False

        self._netease_uia_fallback_active = False
        self._uia_position_ms = None
        self._uia_anchor_mono = None
        self._uia_observed_ms = None
        self._uia_duration_ms = None
        self._uia_status = 'unknown'
        self._uia_has_lock = False
        self._uia_last_seen_mono = None
        self._uia_last_observed_ms = None
        self._uia_reacquire_count = 0
        self._uia_pending_far = None
        # 暂停拖动采用 settle/debounce，而不是要求用户再跳一次。
        # value 为最后一次看到的位置；last_change_mono 只在目标真正变化时刷新。
        self._paused_seek_pending = None
        self._paused_seek_settle_ms = 300.0
        self._uia_initial_pending = None
        self._uia_last_sample_seq = -1
        self._uia_locked_source_key = None
        self._uia_locked_source_name = None
        # 首次只有 Document 时间对时先做“临时锁定”：立即给歌词一个可用位置，
        # 后续由第二个同源样本或更强的小型时间控件确认/纠正。
        self._uia_provisional = False
        self._uia_provisional_started_mono = None
        self._track_key = ''
        # 自动切歌在歌词搜索完成前先重置新曲目 worker，但此时还不知道官方歌曲时长。
        # duration pending 时只允许高可信小型控件锁定，Document 时间对先等歌词搜索返回。
        self._track_duration_pending = False
        # Keep the newest position/total-duration sample seen while auto-track lyric
        # search is still resolving the official duration. Once the duration arrives, a
        # matching sample can pre-calibrate the provisional clock before normal UIA lock.
        self._duration_pending_ui_sample = None

        # 播放中 doc-point seek 使用短 settle，而不是再次等第二个 UIA 样本。
        self._playing_seek_pending = None
        self._playing_seek_settle_ms = 260.0

        self._uia_last_strong_seen_mono = None
        # A recently coherent NetEase Document clock remains trustworthy for a few seconds
        # even if a compact Button temporarily becomes the preferred source. This matters
        # because Chromium often emits only one doc sample for the next lyric-page seek.
        self._uia_last_good_doc_mono = None
        self._uia_last_observed_source_name = ''
        self._uia_last_observed_source_key = ''

        # 所有播放/暂停 seek 共用一个短 burst。
        self._seek_burst_until_mono = 0.0
        self._seek_burst_target_ms = None
        self._seek_burst_source = ''
        self._seek_serial = 0

        # seek 提交后的主动复核窗口。不是再延迟 seek，而是先立即跳，
        # 然后约 3.2 秒内高频检查“刚才接受的位置是否站得住”。
        self._seek_verify_until_mono = 0.0
        self._seek_verify_anchor_ms = None
        self._seek_verify_anchor_mono = None
        self._seek_verify_pending = None

        # QQ 连续拖/点进度条时会输出多个中间位置。只提交最终目标。
        self._qq_seek_pending = None
        self._qq_seek_settle_playing_ms = 180.0 if STABILITY_FIXES_ENABLED else 1100.0
        self._qq_seek_settle_paused_ms = 140.0 if STABILITY_FIXES_ENABLED else 450.0
        self._qq_seek_required_samples = 2
        self._qq_seek_last_commit_mono = 0.0
        self._qq_seek_last_commit_target = None
        self._qq_last_rail_commit_mono = 0.0
        self._qq_last_rail_commit_target = None
        self._qq_post_seek_hard_rephase_done_mono = 0.0
        self._qq_seek_revision = 0
        self._qq_mouse_is_down = False
        self._qq_gesture_id = 0
        self._qq_gesture_press_mono = 0.0
        self._qq_gesture_release_mono = 0.0
        self._qq_gesture_recent_until_mono = 0.0
        self._qq_gesture_expected_ms = None
        self._qq_gesture_expected_id = 0
        # QQ can keep returning the pre-seek live Text wrapper for several seconds after
        # a real rail seek. Track repeated outliers per gesture so the UIA worker can
        # reacquire the time controls without ever promoting geometry to clock authority.
        self._qq_gesture_outlier_id = 0
        self._qq_gesture_outlier_count = 0
        self._qq_gesture_outlier_last_observed = None
        self._qq_gesture_reacquire_requested_id = 0
        self._qq_gesture_reacquire_mono = 0.0
        self._qq_progress_rect = None
        self._qq_track_switch_hold_until_mono = 0.0
        # Lyric-page / keyboard seeks do not touch QQ's bottom progress rail. Keep a separate
        # evidence streak so a sustained new mm:ss stream can be accepted without weakening
        # the hover-preview quarantine.
        self._qq_unarmed_far_pending = None
        # v82: an actual click inside QQ but outside the progress rail is evidence for
        # lyric-page seek.  It grants faster *confirmation* only; cursor geometry never
        # supplies a target and hover over the rail remains quarantined.
        self._qq_nonrail_click_until_mono = 0.0
        self._qq_nonrail_click_mono = 0.0
        self._qq_nonrail_mouse_down = False
        self._qq_lyric_click_result_serial = -1
        self._qq_lyric_click_target_ms = None
        self._qq_lyric_click_target_until_mono = 0.0

        # v1.8.9.3 QQ clock authority: validated means "this is the pair of time
        # labels", not "every value currently shown by that label is truthful".
        # During ordinary playback, only a short coherent streak close to the local
        # monotonic clock is allowed to calibrate it. Far samples remain diagnostics.
        self._qq_clock_good_streak = 0
        self._qq_clock_last_good_ms = None
        self._qq_clock_last_good_mono = None
        self._qq_clock_last_good_key = ''
        self._qq_clock_trusted = False
        self._qq_clock_last_calibrate_mono = 0.0
        self._qq_phase_edge_last_bucket_ms = None
        self._qq_phase_edge_last_mono = None
        self._qq_phase_edge_last_key = ''
        self._qq_phase_edge_errors = []
        self._qq_phase_edge_baseline_ms = None
        self._qq_phase_edge_baseline_samples = []
        self._session_affinity_diag_key = ''
        self._session_affinity_diag_mono = 0.0
        # v1.8.9.46: preserve a small rolling window of *ordinary playback*
        # local-vs-QQ phases. A whole-second accessibility label naturally jitters by
        # hundreds of ms, so a single sample is not safe to carry across a seek.
        # Gesture / hover samples never enter this window because they are excluded
        # before _qq_note_clock_sample() is called.
        self._qq_seek_phase_samples = []
        self._qq_last_trusted_phase_ms = None  # median snapshot, kept for diagnostics
        self._qq_last_trusted_phase_mono = 0.0
        # v1.8.9.47: resting the mouse over QQ's progress rail must not permanently
        # disable clock calibration. A separate advancing-stream proof distinguishes
        # the actual clock from static/dragged hover preview text.
        self._qq_hover_clock_pending = None

        # v1.8.9.43 QQ public clock authority. A validated UIA pair identifies the song
        # clock, but its whole-second text is not a suitable animation clock on every PC.
        # Prefer a coherent GSMTC timeline when Windows exposes one with a real timestamp.
        self._qq_gsmtc_good_streak = 0
        self._qq_gsmtc_primary = False
        self._qq_gsmtc_last_delta_ms = None
        self._qq_gsmtc_last_diag_mono = 0.0
        self._qq_gsmtc_last_position_ms = None
        self._qq_gsmtc_last_mono = None
        # Environment-independent QQ identity witness. Unlike _qq_gsmtc_primary this does
        # not require UIA agreement: its purpose is precisely to quarantine a UIA duration
        # that belongs to another/stale Chromium surface. Position jumps still need a second
        # GSMTC sample before they can become seek authority.
        self._qq_gsmtc_identity_guard_active = False
        self._qq_gsmtc_identity_duration_ms = None
        self._qq_gsmtc_identity_last_position_ms = None
        self._qq_gsmtc_identity_last_mono = None
        self._qq_gsmtc_identity_seek_pending = None
        self._qq_gsmtc_identity_seek_confirmed_mono = 0.0
        self._qq_gsmtc_identity_seek_confirmed_position_ms = None
        self._qq_direct_gsmtc_state = None
        self._qq_direct_gsmtc_authority_until_mono = 0.0
        self._qq_direct_gsmtc_authority_position_ms = None
        self._qq_gsmtc_identity_last_diag_mono = 0.0

        # v117 Kugou public clock authority.  GSMTC is only promoted when the selected
        # kgmusic session exposes a real timeline timestamp and motion remains plausible.
        # UIA is used as a coherence witness/fallback, never as a QQ-style phase PLL.
        self._kugou_gsmtc_good_streak = 0
        self._kugou_gsmtc_primary = False
        self._kugou_gsmtc_last_delta_ms = None
