    def set_lyric_click_timeline(self, lrc_text):
        """Publish the currently rendered lyric rows to the isolated NetEase click matcher.

        The click matcher never infers time from cursor geometry. It only maps UIA text from
        the row the user actually clicked back to this exact overlay timeline.
        """
        entries = []
        try:
            for idx, item in enumerate(parse_lrc(lrc_text, diagnostics=False)):
                if len(item) < 2:
                    continue
                at_ms, body = int(item[0]), str(item[1] or '').strip()
                norm = PlayerUiPositionReader._normalize_lyric_match_text(body)
                if len(norm) < 2:
                    continue
                entries.append({'index': int(idx), 'time_ms': at_ms, 'text': body, 'norm': norm})
        except Exception as exc:
            write_error_log('网易云歌词点击索引构建失败', exc)
            entries = []
        try:
            self._uia_reader.set_lyric_click_timeline(entries)
        except Exception:
            pass
        if SOURCE_GUARD_ENABLED:
            try:
                write_error_log('网易云歌词点击文本索引就绪', detail=f'rows={len(entries)}')
            except Exception:
                pass

    def _live_public_position_hint(self):
        """Return a lock-safe best-effort live public position for duplicate-line disambiguation."""
        try:
            with self._lock:
                st = dict(self._state)
            pos = st.get('position_ms')
            if pos is None:
                return None
            pos = float(pos)
            if st.get('status') == 'playing' and st.get('position_anchor_mono') is not None:
                pos += max(0.0, time.monotonic() * 1000.0 - float(st.get('position_anchor_mono'))) * max(0.01, float(st.get('playback_rate') or 1.0))
            duration = st.get('duration_ms')
            if duration:
                pos = min(pos, float(duration))
            return max(0, int(pos))
        except Exception:
            return None

    @staticmethod
    def _process_stem(process_name):
        value = os.path.basename((process_name or '').replace('\\', '/')).lower()
        return os.path.splitext(value)[0]

    @classmethod
    def _source_matches_process_hint(cls, source, process_name):
        """Whether a GSMTC source belongs to the explicitly selected player."""
        stem = cls._process_stem(process_name)
        raw = str(source or '').replace('\\', '/').lower()
        if not stem or not raw:
            return False
        aliases = {
            'cloudmusic': ('cloudmusic', 'netease', 'orpheus'),
            'qqmusic': ('qqmusic', 'tencent.qqmusic'),
            'kgmusic': ('kgmusic', 'kugou'),
        }
        return any(alias in raw for alias in aliases.get(stem, (stem,)))

    @classmethod
    def _strict_builtin_process(cls, process_name):
        return cls._process_stem(process_name) in {'cloudmusic', 'qqmusic', 'kgmusic'}

    @staticmethod
    def _ms(value):
        if value is None:
            return None
        if hasattr(value, 'total_seconds'):
            return int(value.total_seconds() * 1000)
        try:
            return int(value / 10000)  # WinRT TimeSpan ticks (100ns), for backends returning ints
        except Exception:
            return None

    @staticmethod
    def _status_name(value):
        raw = str(value).lower()
        if 'playing' in raw:
            return 'playing'
        if 'paused' in raw:
            return 'paused'
        if 'stopped' in raw:
            return 'stopped'
        try:
            numeric = int(value)
            return {3: 'stopped', 4: 'playing', 5: 'paused'}.get(numeric, 'unknown')
        except Exception:
            return 'unknown'

    @staticmethod
    def _datetime_ms(value):
        # PyWinRT projects Windows.Foundation.DateTime as timezone-aware datetime.
        if value is None:
            return None
        try:
            return int(value.timestamp() * 1000)
        except Exception:
            return None

    @staticmethod
    def _playback_rate(playback):
        try:
            value = getattr(playback, 'playback_rate', None)
            if value is None:
                return 1.0
            rate = float(value)
            return rate if rate > 0 else 1.0
        except Exception:
            return 1.0

    @staticmethod
    def _timeline_end_ms(timeline):
        return MediaSessionSync._ms(getattr(timeline, 'end_time', None))

