        def make_tab_page():
            page = QWidget()
            page_layout = QVBoxLayout(page)
            page_layout.setSpacing(12)
            page_layout.setContentsMargins(0, 10, 8, 16)
            area = QScrollArea()
            area.setWidgetResizable(True)
            area.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            area.setFrameShape(QFrame.NoFrame)
            area.setWidget(page)
            return area, page_layout

        def polish_page_cards(page_layout, sections, drop_section_titles=False):
            """Re-home existing rows into visual cards without recreating controls."""
            if not CLASSIC_FRONTEND_POLISH_ENABLED:
                return

            def polish_row_layout(row_layout):
                # Consistent field-label rhythm is one of the quiet details that makes dense
                # settings feel intentional. Only colon-terminated leading labels are aligned.
                try:
                    if isinstance(row_layout, QHBoxLayout):
                        row_layout.setSpacing(8)
                    first = row_layout.itemAt(0).widget() if row_layout is not None and row_layout.count() else None
                    if isinstance(first, QLabel) and str(first.text() or '').strip().endswith('：'):
                        first.setObjectName('fieldLabel')
                        first.setMinimumWidth(94)
                except Exception:
                    pass

            raw_items = []
            while page_layout.count():
                item = page_layout.takeAt(0)
                widget = item.widget()
                if drop_section_titles and widget is not None and widget.objectName() == 'sectionTitle':
                    widget.setVisible(False)
                    continue
                if item.spacerItem() is not None:
                    continue
                raw_items.append(item)

            cursor = 0
            for title, hint, count in sections:
                if cursor >= len(raw_items):
                    break
                card = QFrame()
                card.setObjectName('settingsCard')
                card_layout = QVBoxLayout(card)
                card_layout.setContentsMargins(16, 15, 16, 16)
                card_layout.setSpacing(10)
                title_label = QLabel(title)
                title_label.setObjectName('cardTitle')
                card_layout.addWidget(title_label)
                if hint:
                    # Keep guidance available without the AI-dashboard pattern of a visible
                    # explanatory subtitle under every section heading.
                    title_label.setToolTip(hint)
                for _ in range(int(count)):
                    if cursor >= len(raw_items):
                        break
                    item = raw_items[cursor]; cursor += 1
                    if item.widget() is not None:
                        card_layout.addWidget(item.widget())
                    elif item.layout() is not None:
                        polish_row_layout(item.layout())
                        card_layout.addLayout(item.layout())
                    elif item.spacerItem() is not None:
                        card_layout.addItem(item.spacerItem())
                page_layout.addWidget(card)

            # Future/compat rows that were not covered remain usable in one final card.
            if cursor < len(raw_items):
                card = QFrame(); card.setObjectName('settingsCard')
                card_layout = QVBoxLayout(card)
                card_layout.setContentsMargins(16, 15, 16, 16)
                card_layout.setSpacing(10)
                for item in raw_items[cursor:]:
                    if item.widget() is not None: card_layout.addWidget(item.widget())
                    elif item.layout() is not None:
                        polish_row_layout(item.layout()); card_layout.addLayout(item.layout())
                page_layout.addWidget(card)
            page_layout.addStretch()

