LyricWindow._make_history_line=_h12_make_history

def _h12_fading_update(self):
    effect=str(getattr(self,'exit_effect','fade'))
    if effect=='instant': self.release_render_resources(); return False
    if effect=='shrink': self._fade_expedite_factor=max(float(getattr(self,'_fade_expedite_factor',1.0)),2.6)
    return _LIMBUS_FADING_UPDATE_PRE_H12(self)
FadingLine.update=_h12_fading_update

def _h12_fading_draw(self,painter):
    effect=str(getattr(self,'exit_effect','fade')); progress=max(0.0,min(1.0,1.0-float(self.alpha)/255.0))
    if effect=='instant': return
    painter.save()
    try:
        advances=list(getattr(self,'_glyph_cache_advances',[]) or [])
        if len(advances)!=len(self.text):
            fm=QFontMetrics(QFont(self.font)); advances=[float(fm.horizontalAdvance(ch)) for ch in self.text]; self._glyph_cache_advances=list(advances)
        width=max(1.0,sum(advances)+max(0,len(advances)-1)*float(self.spacing)); h=max(20.0,float(getattr(self,'_glyph_cache_height',0) or QFontMetrics(QFont(self.font)).height()))
        if effect in ('wipe_ltr','wipe_rtl','per_char'):
            if effect=='per_char':
                n=len(self.text); visible=max(0,n-int(math.floor(progress*n))); frac=(sum(advances[:visible])+max(0,visible-1)*float(self.spacing))/width if n else 0
            else: frac=1.0-progress
            if effect=='wipe_ltr': painter.setClipRect(QRectF(self.x+width*(1-frac)-30,self.y-h*2,width*frac+60,h*4),Qt.IntersectClip)
            else: painter.setClipRect(QRectF(self.x-30,self.y-h*2,width*frac+60,h*4),Qt.IntersectClip)
        elif effect=='shrink':
            sc=max(.65,1.0-progress*.35); painter.translate(self.x,self.y); painter.scale(sc,sc); painter.translate(-self.x,-self.y)
        _LIMBUS_FADING_DRAW_PRE_H12(self,painter)
    finally: painter.restore()
FadingLine.draw=_h12_fading_draw

def _h12_set_capture(panel,enabled,quiet=False):
    enabled=bool(enabled); ok=False
    if enabled and os.name=='nt':
        try:
            build=int(sys.getwindowsversion().build)
            if build<19041: raise RuntimeError('Windows build < 19041')
            ok=bool(ctypes.windll.user32.SetWindowDisplayAffinity(int(panel.lyric_window.winId()),0x11))
        except Exception as exc:
            if not quiet: QMessageBox.warning(panel,'捕获排除不可用',f'当前系统/捕获链不支持安全的歌词排除模式。\n{exc}')
    elif not enabled and os.name=='nt':
        try: ctypes.windll.user32.SetWindowDisplayAffinity(int(panel.lyric_window.winId()),0); ok=True
        except Exception: ok=False
    panel._h12_capture_exclusion=bool(enabled and ok)
    if hasattr(panel,'h12_capture_combo'):
        panel.h12_capture_combo.blockSignals(True); panel.h12_capture_combo.setCurrentIndex(1 if panel._h12_capture_exclusion else 0); panel.h12_capture_combo.blockSignals(False)
    panel._schedule_config_save()

def _h12_apply_scale(panel,pct):
    pct=int(pct); panel._h12_ui_scale_pct=pct; factor=pct/100.0
    scaled_css = ''
    try:
        base_css=str(getattr(panel,'_default_stylesheet','') or getattr(panel,'_h12_stylesheet_base','') or '')
        if base_css:
            props=r'(font-size|padding(?:-(?:left|right|top|bottom))?|margin(?:-(?:left|right|top|bottom))?|min-width|max-width|min-height|max-height|border-radius)'
            def repl(m): return f'{m.group(1)}: {max(1,round(float(m.group(2))*factor))}px'
            scaled_css = re.sub(props+r'\s*:\s*([0-9]+(?:\.[0-9]+)?)px',repl,base_css)
    except Exception: pass
    for w,base in getattr(panel,'_h12_widget_baseline',[]):
        try:
            f=QFont(w.font()); ps=base[0]
            if ps>0: f.setPointSizeF(max(6.0,ps*factor)); w.setFont(f)
            mnw,mnh,mxw,mxh=base[1:]
            if 0<mnw<16777215: w.setMinimumWidth(round(mnw*factor))
            if 0<mnh<16777215: w.setMinimumHeight(round(mnh*factor))
            if 0<mxw<16777215: w.setMaximumWidth(round(mxw*factor))
            if 0<mxh<16777215: w.setMaximumHeight(round(mxh*factor))
        except Exception: pass
    for lay,base in getattr(panel,'_h12_layout_baseline',[]):
        try:
            l,t,r,b,sp=base; lay.setContentsMargins(round(l*factor),round(t*factor),round(r*factor),round(b*factor));
            if sp>=0: lay.setSpacing(round(sp*factor))
        except Exception: pass
    if scaled_css:
        # Apply after font/layout baselines: setFont can invalidate Qt's stylesheet cache.
        panel.setStyleSheet('')
        panel.setStyleSheet(scaled_css)
    panel._schedule_config_save()

def _h12_poll_async(panel):
    cover=getattr(panel,'_h12_cover_result',None)
    if cover:
        panel._h12_cover_result=None; key,color=cover
        cur=panel._track_identity(getattr(panel,'_loaded_song',''),getattr(panel,'_loaded_artist',''))
        if key==cur and getattr(panel,'_h12_cover_follow',False):
            _active=(getattr(panel,'_active_song_style',{}) or {}); _random=(getattr(panel,'_random_song_style',{}) or {})
            panel._h12_cover_applied=(key,color)
            if not _active.get('text_color') and not _random.get('text_color'):
                try: panel.lyric_window.text_color=QColor(color); panel.lyric_window.update()
                except Exception: pass
    upd=getattr(panel,'_h12_update_result',None)
    if upd:
        panel._h12_update_result=None; panel._h12_update_busy=False; panel.h12_check_btn.setEnabled(True); ok,msg,url=upd; panel.h12_update_status.setPlainText(msg); panel._h12_update_download_url=url or ''; panel.h12_download_btn.setEnabled(bool(ok and url))

def _h12_cover_tick(panel):
    if not getattr(panel,'_h12_cover_follow',False): return
    song=str(getattr(panel,'_loaded_song','') or '').strip(); artist=str(getattr(panel,'_loaded_artist','') or '').strip(); key=panel._track_identity(song,artist)
    if not song or not key or key==getattr(panel,'_h12_cover_requested_key',''): return
    panel._h12_cover_requested_key=key
    def work():
        try:
            r=requests.post('https://music.163.com/api/search/get/web',data={'s':f'{song} {artist}','type':1,'limit':5},headers={'User-Agent':'Mozilla/5.0'},timeout=4); rows=((r.json().get('result') or {}).get('songs') or [])
            def norm(x): return re.sub(r'\W+','',str(x or '').lower())
            hit=next((x for x in rows if norm(x.get('name'))==norm(song) and (not artist or any(norm(a.get('name'))==norm(artist) for a in x.get('artists',[])))),None)
            url=((hit or {}).get('album') or {}).get('picUrl') if hit else ''
            if not str(url).startswith('https://'): return
            im=requests.get(url,timeout=4).content; q=QImage.fromData(im)
            if q.isNull(): return
            q=q.scaled(28,28,Qt.IgnoreAspectRatio,Qt.SmoothTransformation); rs=gs=bs=n=0
            for y in range(q.height()):
                for x in range(q.width()):
                    c=QColor(q.pixel(x,y)); mx=max(c.red(),c.green(),c.blue()); mn=min(c.red(),c.green(),c.blue())
                    if mx<35 or mx>245 or mx-mn<18: continue
                    rs+=c.red(); gs+=c.green(); bs+=c.blue(); n+=1
            if n:
                c=QColor(rs//n,gs//n,bs//n); h,sat,val,_=c.getHsv(); c.setHsv(h,max(120,sat),max(175,min(235,val))); panel._h12_cover_result=(key,c.name())
        except Exception: pass
    threading.Thread(target=work,name='LimbusLyric-H12Cover',daemon=True).start()

def _h12_check_update(panel):
    if bool(getattr(panel,'_h12_update_busy',False)): return
    url=str(panel.h12_update_url_edit.text() or '').strip(); panel._h12_update_url=url
    if not url.startswith('https://'): QMessageBox.information(panel,'检查更新','请先填写 HTTPS 更新接口。'); return
    panel.h12_update_status.setPlainText('正在检查更新…'); panel.h12_check_btn.setEnabled(False); panel._h12_update_busy=True
    def work():
        try:
            r=requests.get(url,headers={'User-Agent':'LimbusLyric-H12'},timeout=6); r.raise_for_status(); d=r.json(); tag=str(d.get('tag_name') or d.get('version') or '').strip(); body=str(d.get('body') or d.get('notes') or d.get('changelog') or '').strip(); dl=str(d.get('html_url') or d.get('download_url') or '').strip(); dl=dl if dl.startswith('https://') else ''
            cur='1.8.9.135 H13'; nums=lambda z: tuple(int(x) for x in re.findall(r'\d+',z)[:5])
            newer=bool(tag and nums(tag)>nums(cur)); state=('发现新版本。' if newer else ('当前已是最新版。' if tag else '未能识别远端版本。')); msg=f'当前版本：{cur}\n最新版本：{tag or "未知"}\n'+state+(f'\n\n更新内容：\n{body}' if body else '')
            panel._h12_update_result=(newer,msg,dl)
        except Exception as exc: panel._h12_update_result=(False,f'检查更新失败：{exc}','')
    threading.Thread(target=work,name='LimbusLyric-H12Update',daemon=True).start()

