def _global_exception_hook(exc_type, exc_value, exc_tb):
    try:
        text = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
        write_error_log("未捕获异常", detail=text, force_sync=True)
    except Exception:
        pass
    try:
        sys.__excepthook__(exc_type, exc_value, exc_tb)
    except Exception:
        pass


# H13 output / lyric-slot / Spotify extensions --------------------------------
# H13 remains outside the frozen QQ / NetEase / KuGou authority methods.  It adds
# presentation output, per-song user lyric payload ownership, and a strict local-GSMTC
# Spotify lane.  No Spotify Web API/OAuth token is used.
H13_LYRIC_SLOT_NAMES = {
    'precise': '精准',
    'classic': '经典',
    'translation': '仅翻译',
}


def _h13_mode_slot_from_flags(trans_only=False, prefer_precise=True):
    if bool(trans_only):
        return 'translation'
    return 'precise' if bool(prefer_precise) else 'classic'


def _h13_current_mode_slot(panel):
    try:
        return _h13_mode_slot_from_flags(
            bool(panel.trans_check.isChecked()),
            bool(panel.precise_tracking_check.isChecked()) if hasattr(panel, 'precise_tracking_check') else True,
        )
    except Exception:
        return 'precise'


def _h13_song_row_for_track(panel, song, artist='', create=False):
    song = str(song or '').strip(); artist = str(artist or '').strip()
    if not song:
        return '', None
    try:
        identity = panel._song_style_identity_for_track(song, artist)
    except Exception:
        identity = panel._track_identity(song, artist)
    row = (getattr(panel, 'song_styles', {}) or {}).get(identity)
    if not isinstance(row, dict) and create:
        identity = panel._track_identity(song, artist)
        row = {'song': song, 'artist': artist, 'rules': {}, 'mode': 'per_player', 'lyric_slots': {}}
        panel.song_styles[identity] = row
    if isinstance(row, dict):
        row.setdefault('song', song); row.setdefault('artist', artist)
        slots = row.get('lyric_slots')
        if not isinstance(slots, dict):
            slots = {}; row['lyric_slots'] = slots
    return identity, row if isinstance(row, dict) else None


def _h13_custom_lyric_for_track(panel, song, artist, slot):
    # User-authored lyric *content* must bind more strictly than presentation style.
    # The legacy style matcher intentionally treats a missing artist as same-song; doing that
    # for lyric payloads could put one artist's words onto another same-title track. H13 slots
    # therefore require the exact normalized song+artist identity that was saved by the user.
    song = str(song or '').strip(); artist = str(artist or '').strip()
    if not song or not artist:
        return ''
    try:
        identity = panel._track_identity(song, artist)
    except Exception:
        return ''
    row = (getattr(panel, 'song_styles', {}) or {}).get(identity)
    if not isinstance(row, dict):
        return ''
    slots = row.get('lyric_slots') if isinstance(row.get('lyric_slots'), dict) else {}
    payload = slots.get(str(slot or ''))
    if isinstance(payload, dict):
        text = str(payload.get('text') or '').strip()
    else:
        text = str(payload or '').strip()
    return text


def _h13_slot_target(panel):
    try:
        identity = panel._diy_selected_identity()
    except Exception:
        identity = ''
    if identity:
        row = (getattr(panel, 'song_styles', {}) or {}).get(identity, {})
        if isinstance(row, dict):
            return str(identity), str(row.get('song') or '').strip(), str(row.get('artist') or '').strip()
    song = str(getattr(panel, '_loaded_song', '') or '').strip()
    artist = str(getattr(panel, '_loaded_artist', '') or '').strip()
    identity = panel._track_identity(song, artist) if song else ''
    return identity, song, artist


def _h13_refresh_slot_ui(panel):
    if not hasattr(panel, 'h13_slot_state'):
        return
    identity, song, artist = _h13_slot_target(panel)
    slot = str(panel.h13_slot_combo.currentData() or 'precise')
    _identity, row = _h13_song_row_for_track(panel, song, artist, create=False) if song else ('', None)
    slots = row.get('lyric_slots') if isinstance(row, dict) and isinstance(row.get('lyric_slots'), dict) else {}
    custom = slots.get(slot)
    custom_text = str(custom.get('text') or '').strip() if isinstance(custom, dict) else str(custom or '').strip()
    if not song:
        panel.h13_slot_state.setText('未选择歌曲')
        panel.h13_slot_save_btn.setEnabled(False)
        panel.h13_slot_auto_btn.setEnabled(False)
        panel.h13_slot_delete_btn.setEnabled(False)
        return
    state = '已自定义 · 运行时优先使用' if custom_text else '未自定义 · 运行时自动抓词'
    panel.h13_slot_state.setText(f'{song}' + (f' - {artist}' if artist else '') + f' · {H13_LYRIC_SLOT_NAMES.get(slot,slot)}：{state}')
    panel.h13_slot_save_btn.setEnabled(True)
    panel.h13_slot_auto_btn.setEnabled(True)
    panel.h13_slot_delete_btn.setEnabled(bool(custom_text))


def _h13_load_slot_editor(panel, prefer_custom=True):
    identity, song, artist = _h13_slot_target(panel)
    if not song:
        panel.status.setText('状态：请先选择单曲DIY歌曲或读取当前歌曲')
        return False
    slot = str(panel.h13_slot_combo.currentData() or 'precise')
    custom = _h13_custom_lyric_for_track(panel, song, artist, slot)
    if prefer_custom and custom:
        panel.h13_slot_editor.setPlainText(custom)
        panel.status.setText(f'状态：已载入「{song}」的{H13_LYRIC_SLOT_NAMES.get(slot,slot)}自定义歌词')
        return True
    try:
        loaded_song=str(getattr(panel,'_loaded_song','') or '').strip(); loaded_artist=str(getattr(panel,'_loaded_artist','') or '').strip()
        exact_current=bool(song and artist and loaded_song and loaded_artist and panel._track_identity(song,artist)==panel._track_identity(loaded_song,loaded_artist))
        if exact_current:
            current = str(panel.text_input.toPlainText() or '').strip()
            if current and _h13_current_mode_slot(panel) == slot:
                panel.h13_slot_editor.setPlainText(current)
                panel.status.setText(f'状态：已从当前正在使用的歌词复制到{H13_LYRIC_SLOT_NAMES.get(slot,slot)}编辑器')
                return True
    except Exception:
        pass
    if not custom:
        panel.h13_slot_editor.clear()
    return False


def _h13_save_slot(panel):
    _identity, song, artist = _h13_slot_target(panel)
    if not song or not artist:
        panel.status.setText('状态：歌词DIY需要明确的歌名和歌手，避免同名歌曲误绑定')
        return False
    text = str(panel.h13_slot_editor.toPlainText() or '').strip()
    if not text:
        panel.status.setText('状态：当前歌词槽编辑器为空，不会保存空白覆盖')
        return False
    slot = str(panel.h13_slot_combo.currentData() or 'precise')
    # Saving lyric content always creates/updates the exact song+artist row. Do not attach
    # words to a legacy artist-less style row merely because the style matcher considers it
    # visually compatible.
    identity = panel._track_identity(song, artist)
    row = (getattr(panel, 'song_styles', {}) or {}).get(identity)
    if not isinstance(row, dict):
        row = {'song': song, 'artist': artist, 'rules': {}, 'mode': 'per_player', 'lyric_slots': {}}
        panel.song_styles[identity] = row
    else:
        row.setdefault('song', song); row.setdefault('artist', artist)
    slots = row.setdefault('lyric_slots', {})
    slots[slot] = {
        'text': text,
        'updated_at': int(time.time()),
        'source_hint': str(panel.source_combo.currentText() or ''),
    }
    panel._schedule_config_save()
    try: panel._refresh_song_style_list(); panel._select_song_style_item(identity, load=False)
    except Exception: pass
    _h13_refresh_slot_ui(panel)
    # If this is exactly the active track/mode, user save is presentation-authoritative now.
    try:
        if _h13_current_mode_slot(panel) == slot and panel._same_track(song, artist, panel._loaded_song, panel._loaded_artist):
            # A user-owned payload satisfies a persistent mode that may previously have
            # been blank because the provider had no matching translation/precision data.
            panel._limbus_mode_payload_blocked = False
            panel._limbus_mode_payload_block_reason = ''
            panel.text_input.setPlainText(text)
            panel._active_lyric_provider_meta = {'h13_custom_lyric_slot': slot, 'user_owned': True}
            if getattr(panel, '_is_started', False):
                panel._launch_current_lyrics(start_delay=0)
    except Exception as exc:
        write_error_log('H13单曲歌词槽即时应用失败', exc, detail=f'song={song} | slot={slot}')
    panel.status.setText(f'状态：已保存「{song}」的{H13_LYRIC_SLOT_NAMES.get(slot,slot)}歌词DIY')
    return True


def _h13_delete_slot(panel, refetch=True):
    identity, song, artist = _h13_slot_target(panel)
    if not song:
        return False
    slot = str(panel.h13_slot_combo.currentData() or 'precise')
    _identity, row = _h13_song_row_for_track(panel, song, artist, create=False)
    if not isinstance(row, dict) or not isinstance(row.get('lyric_slots'), dict) or slot not in row['lyric_slots']:
        _h13_refresh_slot_ui(panel); return False
    row['lyric_slots'].pop(slot, None)
    if not row['lyric_slots']:
        row.pop('lyric_slots', None)
    # If this row existed only to own lyric content, deleting the last slot should not leave
    # a ghost song in the legacy style list. Rows with any visual rules are preserved.
    rules=row.get('rules') if isinstance(row.get('rules'),dict) else {}
    if not row.get('lyric_slots') and not any(isinstance(v,dict) and bool(v) for v in rules.values()):
        panel.song_styles.pop(_identity or identity,None)
        try: panel._refresh_song_style_list()
        except Exception: pass
    panel._schedule_config_save(); _h13_refresh_slot_ui(panel)
    panel.status.setText(f'状态：已删除「{song}」的{H13_LYRIC_SLOT_NAMES.get(slot,slot)}歌词DIY；该模式恢复自动抓词')
    if refetch:
        try:
            if _h13_current_mode_slot(panel) == slot and panel._same_track(song, artist, panel._loaded_song, panel._loaded_artist):
                # Restore this semantic slot from the automatic provider path, not from
                # the manual-fetch UI transaction (which may prompt for identity).
                QTimer.singleShot(0, lambda: panel._refetch_loaded_track_for_mode_switch('h13-slot-delete'))
        except Exception:
            pass
    return True


def _h13_fetch_slot_preview(panel):
    _identity, song, artist = _h13_slot_target(panel)
    if not song:
        panel.status.setText('状态：请先选择歌曲')
        return False
    if bool(getattr(panel, '_h13_slot_preview_busy', False)):
        panel.status.setText('状态：当前歌词槽正在读取自动歌词')
        return False
    source = str(panel.source_combo.currentText() or '')
    slot = str(panel.h13_slot_combo.currentData() or 'precise')
    trans_only = slot == 'translation'; prefer_precise = slot == 'precise'
    panel._h13_slot_preview_busy = True
    panel._h13_slot_preview_started_mono = time.monotonic()
    panel.h13_slot_auto_btn.setEnabled(False)
    panel.status.setText(f'状态：正在从{source}读取「{song}」的{H13_LYRIC_SLOT_NAMES.get(slot,slot)}自动歌词预览…')
    generation = int(getattr(panel, '_h13_slot_preview_generation', 0) or 0) + 1
    panel._h13_slot_preview_generation = generation
    def worker():
        lyric=''; duration=0; err=''
        cancel_check=lambda: int(generation)!=int(getattr(panel,'_h13_slot_preview_generation',-1))
        LyricSearchEngine._set_cancel_check(cancel_check)
        try:
            lyric, duration = LyricSearchEngine.search(song, artist, source, trans_only, prefer_precise=prefer_precise)
            err = str(LyricSearchEngine.last_error or '')
        except Exception as exc:
            err = f'{type(exc).__name__}: {exc}'
        finally:
            LyricSearchEngine._set_cancel_check(None)
        if not cancel_check():
            panel._h13_slot_preview_result=(generation, song, artist, slot, str(lyric or ''), int(duration or 0), err)
    threading.Thread(target=worker, name=f'LimbusLyric-H13SlotPreview-g{generation}', daemon=True).start()
    return True


def _h13_poll_slot_preview(panel):
    row = getattr(panel, '_h13_slot_preview_result', None)
    if not row:
        if bool(getattr(panel, '_h13_slot_preview_busy', False)):
            started=float(getattr(panel, '_h13_slot_preview_started_mono',0.0) or 0.0)
            if started>0.0 and time.monotonic()-started>=18.0:
                panel._h13_slot_preview_generation=int(getattr(panel,'_h13_slot_preview_generation',0) or 0)+1
                panel._h13_slot_preview_busy=False
                panel._h13_slot_preview_started_mono=0.0
                if hasattr(panel,'h13_slot_auto_btn'): panel.h13_slot_auto_btn.setEnabled(True)
                panel.status.setText('状态：自动歌词预览超时；编辑器已恢复，可稍后重试')
                try: write_error_log('H13歌词DIY自动预览超时',detail='budget=18s | late-result=stale-drop | gui-block=0')
                except Exception: pass
        return
    panel._h13_slot_preview_result=None
    generation,song,artist,slot,lyric,duration,err=row
    if int(generation)!=int(getattr(panel,'_h13_slot_preview_generation',-1)): return
    panel._h13_slot_preview_busy=False
    panel._h13_slot_preview_started_mono=0.0
    if hasattr(panel,'h13_slot_auto_btn'): panel.h13_slot_auto_btn.setEnabled(True)
    cur_identity,cur_song,cur_artist=_h13_slot_target(panel)
    if not panel._same_track(song,artist,cur_song,cur_artist) or str(panel.h13_slot_combo.currentData() or '')!=str(slot):
        return
    if lyric.strip():
        panel.h13_slot_editor.setPlainText(lyric)
        panel.status.setText(f'状态：已载入「{song}」的自动{H13_LYRIC_SLOT_NAMES.get(slot,slot)}歌词到编辑器；未保存，不影响当前播放')
    else:
        panel.status.setText(f'状态：未找到「{song}」的{H13_LYRIC_SLOT_NAMES.get(slot,slot)}歌词预览' + (f'：{err}' if err else ''))


def _h13_spotify_duration_witness(panel, song='', artist=''):
    """Return only the selected Spotify GSMTC duration for lyric-version identity."""
    try:
        if str(panel.player_combo.currentText() or '') != 'Spotify':
            return 0
        state = panel.media_sync.snapshot() or {}
        source = str(state.get('media_source') or '')
        if not panel.media_sync._source_matches_process_hint(source, 'spotify.exe'):
            return 0
        media_song = str(state.get('media_title') or '').strip()
        media_artist = str(state.get('media_artist') or '').strip()
        if song:
            if not artist or not media_song or not media_artist:
                return 0
            if panel._track_identity(song,artist) != panel._track_identity(media_song,media_artist):
                return 0
        return max(0, int(state.get('duration_ms') or 0))
    except Exception:
        return 0


# Custom lyric slots bypass provider IO completely when they exist.
_LIMBUS_H13_START_AUTO_SEARCH_PRE = ControlPanel._start_auto_search_job

def _h13_start_auto_search_job(self, job):
    job = dict(job or {})
    # Spotify owns playback while QQ/NetEase/KuGou may only be lyric sources. Feed the
    # source-affine player duration into version selection so auto fetch never waits on or
    # borrows another player's UIA clock merely because that provider supplies the words.
    spotify_duration = _h13_spotify_duration_witness(self, job.get('song',''), job.get('artist',''))
    if spotify_duration > 0:
        job['provider_duration_ms'] = spotify_duration
    slot = _h13_mode_slot_from_flags(job.get('trans_only'), job.get('prefer_precise', True))
    custom = _h13_custom_lyric_for_track(self, job.get('song',''), job.get('artist',''), slot)
    if not custom:
        return _LIMBUS_H13_START_AUTO_SEARCH_PRE(self, job)
    self._auto_fetch_in_progress = True
    duration = int(job.get('provider_duration_ms') or 0)
    if duration <= 0:
        try: duration = int((self.media_sync.snapshot() or {}).get('duration_ms') or 0)
        except Exception: duration = 0
    result = dict(job)
    result.update({
        'lyric': custom, 'duration': duration,
        'provider_meta': {'h13_custom_lyric_slot': slot, 'user_owned': True},
        'error': '', 'search_elapsed_ms': 0, 'cancelled': False,
        'progressive_stage': 'custom', 'precision_upgrade_pending': False,
        'progressive_keep_fast': False, 'precision_upgrade': False,
    })
    try:
        write_error_log('H13单曲歌词槽命中', detail=f'song={job.get("song","")} | slot={slot} | path=auto | provider-network=skip')
    except Exception: pass
    QTimer.singleShot(0, lambda r=result: self.auto_lyric_result.emit(dict(r)))
    return True

ControlPanel._start_auto_search_job = _h13_start_auto_search_job

_LIMBUS_H13_START_MANUAL_SEARCH_PRE = ControlPanel._start_manual_fetch_search

def _h13_start_manual_fetch_search(self, request):
    request = dict(request or {})
    slot = _h13_mode_slot_from_flags(request.get('trans_only'), request.get('prefer_precise', True))
    custom = _h13_custom_lyric_for_track(self, request.get('song',''), request.get('artist',''), slot)
    if not custom:
        return _LIMBUS_H13_START_MANUAL_SEARCH_PRE(self, request)
    duration = int(request.get('provider_duration_ms') or 0)
    if duration <= 0:
        try: duration=int((self.media_sync.snapshot() or {}).get('duration_ms') or 0)
        except Exception: duration=0
    payload=dict(request)
    payload.update({'event':'search-result','stage':'single','lyric':custom,'duration':duration,
                    'provider_meta':{'h13_custom_lyric_slot':slot,'user_owned':True},
                    'error':'','keep_fast':False,'final':True,'elapsed_ms':0})
    try: write_error_log('H13单曲歌词槽命中', detail=f'song={request.get("song","")} | slot={slot} | path=manual | provider-network=skip')
    except Exception: pass
    QTimer.singleShot(0, lambda p=payload: self._manual_fetch_emit(dict(p)))
    return True

ControlPanel._start_manual_fetch_search = _h13_start_manual_fetch_search


# Semantic mode switches have a separate reload path, so they must honor the same
# three user-owned lyric slots as automatic/manual fetch.
_LIMBUS_H13_MODE_REFETCH_PRE = ControlPanel._refetch_loaded_track_for_mode_switch

def _h13_refetch_loaded_track_for_mode_switch(self, reason='mode-switch', rollback_trans_only=None, rollback_precise=None):
    song=str(getattr(self,'_loaded_song','') or '').strip()
    artist=str(getattr(self,'_loaded_artist','') or '').strip()
    if not song:
        return _LIMBUS_H13_MODE_REFETCH_PRE(
            self, reason=reason, rollback_trans_only=rollback_trans_only, rollback_precise=rollback_precise
        )
    slot=_h13_current_mode_slot(self)
    custom=_h13_custom_lyric_for_track(self,song,artist,slot)
    source=str(self.source_combo.currentText() or '') if hasattr(self,'source_combo') else ''
    if not custom and str(self.player_combo.currentText() or '') == 'Spotify':
        # Mode switches are another lyric-provider transaction. Keep the duration witness
        # player-owned just like automatic/manual fetch; do not call QQ UIA because QQ may be
        # only the selected lyric source while Spotify owns playback.
        trans_only=bool(self.trans_check.isChecked()) if hasattr(self,'trans_check') else False
        prefer_precise=bool(self.precise_tracking_check.isChecked()) if hasattr(self,'precise_tracking_check') else True
        provider_duration_ms=_h13_spotify_duration_witness(self,song,artist)
        self._mode_refetch_generation=int(getattr(self,'_mode_refetch_generation',0) or 0)+1
        generation=int(self._mode_refetch_generation)
        self.status.setText(f'状态：模式已切换，正在重新获取「{song}」歌词…')
        def worker():
            lyric=None; duration=0; error=''; provider_meta={}
            try:
                lyric,duration=LyricSearchEngine.search(
                    song,artist,source,trans_only,provider_duration_ms=provider_duration_ms,prefer_precise=prefer_precise,
                    require_translation_pair=bool((not trans_only) and str(getattr(self,'_h95f5_bilingual_mode','original') or 'original')=='bilingual')
                )
                provider_meta=LyricSearchEngine.last_provider_meta(); error=LyricSearchEngine.last_error or ''
            except Exception as exc:
                error=f'{type(exc).__name__}: {exc}'
            try:
                self.mode_lyric_result.emit({
                    'generation':generation,'reason':reason,'song':song,'artist':artist,'source':source,
                    'trans_only':trans_only,'lyric':lyric,'duration':duration or provider_duration_ms or 0,
                    'provider_meta':provider_meta,'error':error,
                    'rollback_trans_only':rollback_trans_only,'rollback_precise':rollback_precise,
                })
            except Exception:
                pass
        threading.Thread(target=worker,name=f'LimbusLyric-H13SpotifyModeRefetch-g{generation}',daemon=True).start()
        return True
    if not custom:
        return _LIMBUS_H13_MODE_REFETCH_PRE(
            self, reason=reason, rollback_trans_only=rollback_trans_only, rollback_precise=rollback_precise
        )
    trans_only=bool(self.trans_check.isChecked()) if hasattr(self,'trans_check') else False
    self._mode_refetch_generation=int(getattr(self,'_mode_refetch_generation',0) or 0)+1
    generation=int(self._mode_refetch_generation)
    duration=0
    try: duration=int((self.media_sync.snapshot() or {}).get('duration_ms') or 0)
    except Exception: duration=0
    if duration<=0:
        try: duration=int(getattr(self.lyric_window,'song_duration',0) or 0)
        except Exception: duration=0
    result={
        'generation':generation, 'reason':reason, 'song':song, 'artist':artist, 'source':source,
        'trans_only':trans_only, 'lyric':custom, 'duration':duration,
        'provider_meta':{'h13_custom_lyric_slot':slot,'user_owned':True}, 'error':'',
        'rollback_trans_only':rollback_trans_only, 'rollback_precise':rollback_precise,
    }
    self.status.setText(f'状态：模式已切换，正在载入「{song}」的{H13_LYRIC_SLOT_NAMES.get(slot,slot)}自定义歌词…')
    try:
        write_error_log('H13单曲歌词槽命中',detail=f'song={song} | slot={slot} | path=mode-refetch | provider-network=skip')
    except Exception: pass
    QTimer.singleShot(0,lambda r=result:self.mode_lyric_result.emit(dict(r)))
    return True

ControlPanel._refetch_loaded_track_for_mode_switch = _h13_refetch_loaded_track_for_mode_switch


class H13ObsLyricMirror(QWidget):
    """Dedicated capturable mirror. Shares presentation pixels, never MediaSync/timeline state."""
    def __init__(self, source_window):
        flags = Qt.Tool | Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.WindowTransparentForInput
        super().__init__(None, flags)
        self.source_window = source_window
        self.setWindowTitle('LimbusLyric OBS Lyrics')
        self.setObjectName('limbusObsLyricsOutput')
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_ShowWithoutActivating, True)
        self._frame = QPixmap()
        self._frame_rect = QRect()
        self._active = False
        self._capture_busy = False
        self._timer = QTimer(self); self._timer.timeout.connect(self._tick); self._timer.setInterval(50)

    def set_active(self, active):
        self._active = bool(active)
        if self._active:
            self._timer.start(); self._tick(); self.show()
        else:
            self._timer.stop(); self.hide(); self._frame = QPixmap(); self._frame_rect = QRect()

    def _tick(self):
        if not self._active or self._capture_busy:
            return
        src = self.source_window
        try:
            if src is None or not src.isVisible():
                self.hide(); return
            self._capture_busy = True
            g = src.geometry()
            if self.geometry() != g: self.setGeometry(g)
            old_rect = QRect(self._frame_rect)
            try:
                visual = src._current_visual_region().boundingRect()
                rect = visual.adjusted(-48,-48,48,48).intersected(src.rect()) if not visual.isEmpty() else QRect()
            except Exception:
                rect = src.rect()
            if rect.isEmpty():
                self._frame = QPixmap(); self._frame_rect = QRect()
                if not old_rect.isEmpty(): self.update(old_rect)
            else:
                self._frame = src.grab(rect); self._frame_rect = QRect(rect)
                dirty = old_rect.united(rect) if not old_rect.isEmpty() else rect
                if not self.isVisible(): self.show()
                self.update(dirty)
        except Exception:
            pass
        finally:
            self._capture_busy = False

    def paintEvent(self, event):
        p=QPainter(self); p.setRenderHint(QPainter.SmoothPixmapTransform, True)
        try:
            p.setCompositionMode(QPainter.CompositionMode_Source)
            p.fillRect(event.rect(), QColor(0,0,0,0))
            p.setCompositionMode(QPainter.CompositionMode_SourceOver)
        except Exception:
            pass
        if self._frame.isNull() or self._frame_rect.isEmpty(): return
        try: p.setOpacity(max(0.0,min(1.0,float(self.source_window.windowOpacity()))))
        except Exception: pass
        p.drawPixmap(self._frame_rect, self._frame)


def _h13_set_window_mode(panel, mode, quiet=False):
    mode=str(mode or 'normal')
    if mode not in ('normal','obs','exclude'): mode='normal'
    mirror=getattr(panel,'_h13_obs_mirror',None)
    if mirror is None:
        mirror=H13ObsLyricMirror(panel.lyric_window); panel._h13_obs_mirror=mirror
    if mode=='exclude':
        if mirror: mirror.set_active(False)
        _h12_set_capture(panel, True, quiet=quiet)
        if not bool(getattr(panel,'_h12_capture_exclusion',False)):
            mode='normal'
    else:
        _h12_set_capture(panel, False, quiet=True)
        if mirror: mirror.set_active(mode=='obs')
    panel._h13_window_mode=mode
    if hasattr(panel,'h12_capture_combo'):
        idx=panel.h12_capture_combo.findData(mode)
        if idx>=0 and panel.h12_capture_combo.currentIndex()!=idx:
            panel.h12_capture_combo.blockSignals(True); panel.h12_capture_combo.setCurrentIndex(idx); panel.h12_capture_combo.blockSignals(False)
    if not quiet: panel._schedule_config_save()


