_LIMBUS_H13_NATIVE_PROBE_PRE = _LIMBUS_PROBE_BUILTIN_PROCESS_ALIVE_LOCKED

def _h13_probe_spotify_or_legacy(process_stem):
    stem=MediaSessionSync._process_stem(process_stem)
    if stem!='spotify': return _LIMBUS_H13_NATIVE_PROBE_PRE(process_stem)
    if os.name!='nt': return None
    try:
        from ctypes import wintypes as _wt
        class _PE(ctypes.Structure):
            _fields_=[('dwSize',_wt.DWORD),('cntUsage',_wt.DWORD),('th32ProcessID',_wt.DWORD),('th32DefaultHeapID',ctypes.c_void_p),('th32ModuleID',_wt.DWORD),('cntThreads',_wt.DWORD),('th32ParentProcessID',_wt.DWORD),('pcPriClassBase',_wt.LONG),('dwFlags',_wt.DWORD),('szExeFile',_wt.WCHAR*260)]
        k32=ctypes.windll.kernel32
        k32.CreateToolhelp32Snapshot.argtypes=[_wt.DWORD,_wt.DWORD]
        k32.CreateToolhelp32Snapshot.restype=_wt.HANDLE
        k32.Process32FirstW.argtypes=[_wt.HANDLE,ctypes.POINTER(_PE)]
        k32.Process32FirstW.restype=_wt.BOOL
        k32.Process32NextW.argtypes=[_wt.HANDLE,ctypes.POINTER(_PE)]
        k32.Process32NextW.restype=_wt.BOOL
        k32.CloseHandle.argtypes=[_wt.HANDLE]
        k32.CloseHandle.restype=_wt.BOOL
        snap=k32.CreateToolhelp32Snapshot(0x2,0)
        invalid=ctypes.c_void_p(-1).value
        if not snap or int(ctypes.cast(snap,ctypes.c_void_p).value or 0)==int(invalid): return None
        try:
            pe=_PE(); pe.dwSize=ctypes.sizeof(pe); ok=bool(k32.Process32FirstW(snap,ctypes.byref(pe)))
            while ok:
                if str(pe.szExeFile or '').strip().lower()=='spotify.exe': return True
                ok=bool(k32.Process32NextW(snap,ctypes.byref(pe)))
            return False
        finally: k32.CloseHandle(snap)
    except Exception: return None

_LIMBUS_PROBE_BUILTIN_PROCESS_ALIVE_LOCKED = _h13_probe_spotify_or_legacy
_LIMBUS_H13_TASKLIST_PRE = _limbus_liveness_tasklist_probe

def _h13_liveness_tasklist_probe(stem):
    stem=MediaSessionSync._process_stem(stem)
    if stem!='spotify': return _LIMBUS_H13_TASKLIST_PRE(stem)
    if os.name!='nt': return None
    try:
        r=subprocess.run(['tasklist','/fo','csv','/nh'],capture_output=True,text=True,encoding='utf-8',errors='ignore',timeout=float(_LIMBUS_LIVENESS_TASKLIST_TIMEOUT_S),creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        if int(getattr(r,'returncode',-1))!=0 or not str(r.stdout or '').strip(): return None
        names={line.split(',',1)[0].strip().strip('"').lower() for line in str(r.stdout or '').splitlines() if line.strip() and not line.startswith('INFO:')}
        return 'spotify.exe' in names
    except Exception: return None

_limbus_liveness_tasklist_probe = _h13_liveness_tasklist_probe


def _h13_player_liveness_worker(self):
    supported=('cloudmusic','qqmusic','kgmusic','spotify')
    while not self._player_liveness_stop_event.is_set():
        stem=self._process_stem(self._process_hint)
        try:
            with self._lock: sync_requested=bool(self._state.get('sync_requested',False))
        except Exception: sync_requested=False
        if (not sync_requested) or stem not in supported:
            self._player_liveness_wake_event.wait(.25); self._player_liveness_wake_event.clear(); continue
        started=time.perf_counter(); alive,probe_source=_limbus_bounded_player_liveness_probe(self,stem); elapsed_ms=(time.perf_counter()-started)*1000.0; now_ms=time.monotonic()*1000.0; changed=False
        with self._player_liveness_lock:
            if stem!=self._player_liveness_stem:
                self._player_liveness_stem=stem; self._player_liveness_confirmed=None; self._player_liveness_dead_streak=0; self._player_liveness_serial+=1; changed=True
            previous=self._player_liveness_confirmed
            if alive is True: self._player_liveness_dead_streak=0; self._player_liveness_confirmed=True
            elif alive is False:
                self._player_liveness_dead_streak+=1
                if self._player_liveness_dead_streak>=int(PLAYER_LIVENESS_DEAD_CONFIRMATIONS): self._player_liveness_confirmed=False
            self._player_liveness_last_probe_mono=now_ms; self._player_liveness_last_probe_ms=float(elapsed_ms)
            if self._player_liveness_confirmed is not previous: self._player_liveness_serial+=1; changed=True
            serial=int(self._player_liveness_serial); confirmed=self._player_liveness_confirmed; dead_streak=int(self._player_liveness_dead_streak)
        if stem=='kgmusic' and confirmed is not None: self._kugou_mouse_hook_capture_enabled=bool(confirmed)
        if elapsed_ms>=float(PLAYER_LIVENESS_SLOW_PROBE_MS) and now_ms-float(self._player_liveness_slow_log_mono or 0.0)>=3000.0:
            self._player_liveness_slow_log_mono=now_ms
            try: write_error_log('播放器存活异步慢查询',detail=f'process={stem} | elapsed={elapsed_ms:.1f}ms | gui-block=0 | confirmed={confirmed} | dead_streak={dead_streak} | source={probe_source}')
            except Exception: pass
        if changed:
            try: write_error_log('播放器存活状态变化',detail=f'process={stem} | alive={confirmed} | dead_streak={dead_streak} | serial={serial} | source={probe_source}')
            except Exception: pass
        self._player_liveness_wake_event.wait(float(PLAYER_LIVENESS_POLL_MS)/1000.0); self._player_liveness_wake_event.clear()
MediaSessionSync._player_liveness_worker = _h13_player_liveness_worker

# Spotify uses a single source-affine GSMTC clock. Keep the shared UIA worker dormant for
# this provider so it cannot become an accidental fourth-player authority or waste Chromium
# discovery work on Spotify's desktop shell. Switching to any older provider delegates to the
# frozen start() implementation, which resumes UIA exactly as before.
_LIMBUS_H13_MEDIA_START_PRE = MediaSessionSync.start

def _h13_media_start(self, process_name):
    out=_LIMBUS_H13_MEDIA_START_PRE(self, process_name)
    if self._process_stem(process_name)=='spotify':
        try: self._uia_reader.set_suspended(True, reason='spotify-gsmtc-primary')
        except Exception: pass
    return out

MediaSessionSync.start = _h13_media_start

_LIMBUS_H13_MERGE_UIA_PRE = MediaSessionSync._merge_uia_position

def _h13_merge_uia_position(self, process_name, status, fallback_position, fallback_trusted=False):
    if self._process_stem(process_name)!='spotify':
        return _LIMBUS_H13_MERGE_UIA_PRE(self, process_name, status, fallback_position, fallback_trusted)
    duration=int(getattr(self,'_uia_duration_ms',0) or (getattr(self,'_state',{}) or {}).get('duration_ms') or 0)
    if bool(fallback_trusted) and fallback_position is not None:
        pos=max(0,int(round(float(fallback_position))))
        return pos,{
            'position_ms':pos,'duration_ms':duration or None,'confidence':1000,
            'source':'gsmtc-spotify-local','source_key':'gsmtc:spotify.exe',
            'detail':'source-affine local GSMTC; UIA disabled',
        }
    return None,{
        'position_ms':None,'duration_ms':duration or None,'confidence':0,
        'source':'spotify-gsmtc-wait','source_key':'gsmtc:spotify.exe',
        'detail':'waiting for trustworthy Spotify GSMTC timeline',
    }

MediaSessionSync._merge_uia_position = _h13_merge_uia_position

