_LIMBUS_H13_MANUAL_IDENTITY_PRE = ControlPanel._manual_fetch_identity_worker

def _h13_manual_fetch_identity_worker(self,request):
    request=dict(request or {})
    if str(request.get('player_name') or '')!='Spotify':
        return _LIMBUS_H13_MANUAL_IDENTITY_PRE(self,request)
    # Spotify identity is local-GSMTC-only.  Do not fall through to the generic window
    # title parser: Spotify shell titles (Premium/Free) are presentation chrome, not tracks.
    request['builtin_player']=True
    generation=int(request.get('generation',-1))
    state={}
    try:
        presence=False
        deadline=time.monotonic()+float(PLAYER_LIVENESS_MANUAL_WAIT_MS)/1000.0
        while time.monotonic()<deadline and generation==int(getattr(self,'_manual_fetch_generation',-2)):
            state=self.media_sync.snapshot() or {}
            live=str(state.get('player_liveness') or 'unknown')
            if live=='alive': presence=True; break
            if live=='dead': break
            time.sleep(.05)
        request['player_presence_ok']=bool(presence)
        request['player_liveness']=str((state or {}).get('player_liveness') or 'unknown')
        if generation!=int(getattr(self,'_manual_fetch_generation',-2)): return
        song=artist=''
        if presence:
            deadline=time.monotonic()+1.2
            while time.monotonic()<deadline and generation==int(getattr(self,'_manual_fetch_generation',-2)):
                state=self.media_sync.snapshot() or {}
                media_source=str(state.get('media_source') or '')
                title=str(state.get('media_title') or '').strip()
                if title and self.media_sync._source_matches_process_hint(media_source,'spotify.exe'):
                    if _clean_name(title).casefold() not in {'spotify','spotify music','spotify premium','spotify free'}:
                        song=title; artist=str(state.get('media_artist') or '').strip(); break
                time.sleep(.05)
        request['song']=song; request['artist']=artist
        if not song:
            self._manual_fetch_emit({'event':'needs-input','request':request}); return
        # The lyric provider never owns Spotify playback. Use Spotify's current source-affine
        # GSMTC duration as the version witness for every provider, not just QQ.
        request['provider_duration_ms']=_h13_spotify_duration_witness(self,song,artist)
        self._manual_fetch_emit({'event':'identity-ready','request':request})
    except Exception as exc:
        self._manual_fetch_emit({'event':'fatal','request':request,'error':f'{type(exc).__name__}: {exc}'})
ControlPanel._manual_fetch_identity_worker = _h13_manual_fetch_identity_worker

_LIMBUS_H13_DETECTED_PRE = ControlPanel._detected_player_track

def _h13_detected_player_track(self):
    if str(self.player_combo.currentText() or '')!='Spotify':
        return _LIMBUS_H13_DETECTED_PRE(self)
    # Avoid even queuing the generic title/window discovery lane for Spotify. The selected
    # spotify.exe GSMTC session is the sole canonical identity witness in H13.
    try:
        state=self.media_sync.snapshot() or {}
        song=str(state.get('media_title') or '').strip()
        artist=str(state.get('media_artist') or '').strip()
        source=str(state.get('media_source') or '')
        process_name=str((self.players.get('Spotify',{}) or {}).get('process') or 'spotify.exe')
        shell={'spotify','spotify music','spotify premium','spotify free'}
        if (song and len(song)<180 and _clean_name(song).casefold() not in shell and
                self.media_sync._source_matches_process_hint(source,process_name)):
            return song,artist
    except Exception:
        pass
    return None,None
ControlPanel._detected_player_track = _h13_detected_player_track


def _h13_copy_current_lyric_to_slot_editor(panel):
    _identity, song, artist = _h13_slot_target(panel)
    loaded_song = str(getattr(panel, '_loaded_song', '') or '').strip()
    loaded_artist = str(getattr(panel, '_loaded_artist', '') or '').strip()
    exact_current=False
    try:
        exact_current=bool(song and artist and loaded_song and loaded_artist and panel._track_identity(song,artist)==panel._track_identity(loaded_song,loaded_artist))
    except Exception:
        exact_current=False
    if not exact_current:
        panel.status.setText('状态：当前选中的历史歌曲不是正在播放的精确歌曲身份，已阻止跨歌曲复制歌词')
        return False
    text = str(panel.text_input.toPlainText() or '')
    if not text.strip():
        panel.status.setText('状态：当前正在使用的歌词为空')
        return False
    panel.h13_slot_editor.setPlainText(text)
    panel.status.setText(f'状态：已从当前播放「{loaded_song}」复制歌词到编辑器；尚未保存')
    return True


def _h13_register_scale_baseline(panel, root):
    """Register controls created after H12's baseline capture, then apply current scale once."""
    try:
        known={id(w) for w,_base in getattr(panel,'_h12_widget_baseline',[])}
        widgets=[root]+list(root.findChildren(QWidget))
        for w in widgets:
            if id(w) in known:
                continue
            f=w.font(); panel._h12_widget_baseline.append((w,(float(f.pointSizeF()),w.minimumWidth(),w.minimumHeight(),w.maximumWidth(),w.maximumHeight())))
            known.add(id(w))
        known_layouts={id(lo) for lo,_base in getattr(panel,'_h12_layout_baseline',[])}
        for w in widgets:
            lo=w.layout()
            if lo is None or id(lo) in known_layouts:
                continue
            m=lo.contentsMargins(); panel._h12_layout_baseline.append((lo,(m.left(),m.top(),m.right(),m.bottom(),lo.spacing())))
            known_layouts.add(id(lo))
        _h12_apply_scale(panel,int(getattr(panel,'_h12_ui_scale_pct',100) or 100))
    except Exception as exc:
        write_error_log('H13界面缩放基准注册失败',exc)


