def _h13_close_event(self,event):
    try:
        m=getattr(self,'_h13_obs_mirror',None)
        if m is not None: m.set_active(False); m.close()
    except Exception: pass
    return _LIMBUS_H13_CLOSE_PRE(self,event)
ControlPanel.closeEvent = _h13_close_event


# H15 frontend integration / verified installer update ------------------------
# This closure keeps the R4 presentation shell while completing the last part of
# the user-requested update flow.  It does not touch player/lyric clock authority.
H15_UPDATE_MAX_BYTES = 512 * 1024 * 1024
H15_UPDATE_CHUNK_BYTES = 1024 * 1024
H15_AUTO_CHECK_INTERVAL_SEC = 24 * 60 * 60
H15_AUTO_CHECK_DELAY_MS = 5500
_LIMBUS_H15_H12_POLL_PRE = _h12_poll_async
_LIMBUS_H15_CONTROL_INIT_PRE = ControlPanel.__init__


def _h15_version_key(value):
    """Stable release ordering: dotted app version first, then the latest H/F stage."""
    s = str(value or '').strip()
    m = re.search(r'(?i)\bv?(\d+)\.(\d+)\.(\d+)\.(\d+)\b', s)
    base = tuple(int(x) for x in m.groups()) if m else (0, 0, 0, 0)
    stages = [(int(a), int(b or 0)) for a, b in re.findall(r'(?i)\bH(\d+)(?:F(\d+))?\b', s)]
    stage = max(stages) if stages else (0, 0)
    return base + stage


def _h15_current_version_label():
    tag = str(globals().get('LIMBUSLYRIC_BUILD_TAG') or '').strip()
    m = re.search(r'(?i)\bv?(\d+\.\d+\.\d+\.\d+)\b', tag)
    base = m.group(1) if m else '1.8.9.135'
    stages = [(int(a), int(b or 0)) for a, b in re.findall(r'(?i)\bH(\d+)(?:F(\d+))?\b', tag)]
    if not stages:
        return base
    h, f = max(stages)
    return f'{base} H{h}' + (f'F{f}' if f else '')


def _h15_https(value):
    s = str(value or '').strip()
    try:
        parsed = urllib.parse.urlparse(s)
        return s if parsed.scheme.lower() == 'https' and bool(parsed.netloc) else ''
    except Exception:
        return ''


def _h15_digest(value):
    s = str(value or '').strip().lower()
    if s.startswith('sha256:'):
        s = s.split(':', 1)[1].strip()
    return s if re.fullmatch(r'[0-9a-f]{64}', s) else ''


def _h15_safe_installer_name(value, fallback='LimbusLyric_Update.exe'):
    name = os.path.basename(str(value or '').strip().replace('\\', '/'))
    name = re.sub(r'[^A-Za-z0-9._+() -]+', '_', name).strip(' .')
    if not name.lower().endswith('.exe'):
        name = fallback
    return name[:160] or fallback


def _h15_release_candidate(payload):
    """Normalize GitHub Release JSON or a small compatible manifest.

    Auto-install is allowed only when an HTTPS .exe installer and SHA-256 digest
    are both present.  A page URL without a digest remains a manual-download path.
    """
    d = payload if isinstance(payload, dict) else {}
    tag = str(d.get('tag_name') or d.get('version') or d.get('name') or '').strip()
    notes = str(d.get('body') or d.get('notes') or d.get('changelog') or '').strip()
    page = _h15_https(d.get('html_url') or d.get('page_url') or d.get('release_url') or '')
    chosen = None

    direct_url = _h15_https(d.get('installer_url') or d.get('download_url') or '')
    direct_sha = _h15_digest(d.get('installer_sha256') or d.get('sha256') or d.get('digest') or '')
    if direct_url and direct_url.lower().split('?', 1)[0].endswith('.exe'):
        chosen = {
            'url': direct_url,
            'sha256': direct_sha,
            'name': _h15_safe_installer_name(d.get('installer_name') or urllib.parse.urlparse(direct_url).path),
            'size': int(d.get('installer_size') or d.get('size') or 0),
        }

    if chosen is None:
        assets = d.get('assets') if isinstance(d.get('assets'), list) else []
        scored = []
        for asset in assets:
            if not isinstance(asset, dict):
                continue
            name = str(asset.get('name') or '').strip()
            low = name.lower()
            url = _h15_https(asset.get('browser_download_url') or asset.get('download_url') or '')
            if not url or not low.endswith('.exe'):
                continue
            if 'limbuslyric' not in low:
                continue
            score = 0
            if 'setup' in low: score += 4
            if 'installer' in low: score += 3
            if 'update' in low: score += 1
            scored.append((score, asset, url, name))
        if scored:
            _score, asset, url, name = sorted(scored, key=lambda x: (x[0], x[3].lower()), reverse=True)[0]
            chosen = {
                'url': url,
                'sha256': _h15_digest(asset.get('digest') or asset.get('sha256') or ''),
                'name': _h15_safe_installer_name(name),
                'size': int(asset.get('size') or 0),
            }

    candidate = {
        'version': tag,
        'notes': notes,
        'page_url': page,
        'installer_url': str((chosen or {}).get('url') or ''),
        'installer_sha256': str((chosen or {}).get('sha256') or ''),
        'installer_name': str((chosen or {}).get('name') or ''),
        'installer_size': int((chosen or {}).get('size') or 0),
    }
    candidate['verified_installer'] = bool(
        candidate['installer_url'] and candidate['installer_sha256'] and
        candidate['installer_name'].lower().endswith('.exe')
    )
    candidate['newer'] = bool(tag and _h15_version_key(tag) > _h15_version_key(_h15_current_version_label()))
    return candidate


def _h15_update_status(candidate):
    c = candidate if isinstance(candidate, dict) else {}
    current = _h15_current_version_label()
    remote = str(c.get('version') or '未知')
    if not c.get('version'):
        state = '未能识别远端版本。'
    elif bool(c.get('newer')):
        state = '发现新版本。'
    else:
        state = '当前已是最新版。'
    lines = [f'当前版本：{current}', f'最新版本：{remote}', state]
    if bool(c.get('newer')):
        if bool(c.get('verified_installer')):
            lines.append('安装器：HTTPS + SHA-256 已验证，可下载后交给安装程序更新。')
        elif c.get('page_url'):
            lines.append('安装器缺少可验证 SHA-256；仅允许打开下载页，不会自动执行。')
        else:
            lines.append('没有找到可安全使用的安装器或下载页。')
    notes = str(c.get('notes') or '').strip()
    if notes:
        lines.extend(['', '更新内容：', notes])
    return '\n'.join(lines)


def _h15_check_update(panel):
    if bool(getattr(panel, '_h15_update_check_busy', False)) or bool(getattr(panel, '_h15_update_download_busy', False)):
        return
    url = _h15_https(panel.h12_update_url_edit.text() if hasattr(panel, 'h12_update_url_edit') else '')
    panel._h12_update_url = url
    if not url:
        QMessageBox.information(panel, '检查更新', '请先填写 HTTPS 更新接口。')
        return
    panel._h15_update_check_busy = True
    panel.h12_check_btn.setEnabled(False)
    panel.h12_download_btn.setEnabled(False)
    panel.h12_download_btn.setText('下载更新')
    panel.h12_update_status.setPlainText(f'正在检查更新…\n当前版本：{_h15_current_version_label()}')

    def work():
        try:
            response = requests.get(
                url,
                headers={'User-Agent': f'LimbusLyric-{_h15_current_version_label()}'},
                timeout=(5, 8),
            )
            response.raise_for_status()
            if not _h15_https(getattr(response, 'url', url)):
                raise RuntimeError('更新接口发生了非 HTTPS 重定向')
            candidate = _h15_release_candidate(response.json())
            panel._h15_update_check_result = (True, candidate, '')
        except Exception as exc:
            panel._h15_update_check_result = (False, {}, f'检查更新失败：{exc}')

    threading.Thread(target=work, name='LimbusLyric-H15UpdateCheck', daemon=True).start()


def _h15_download_installer_file(candidate, updates_dir, request_get=None):
    """Download one verified installer to *updates_dir* and atomically publish it.

    This helper is UI-free so the verified download byte/hash path can be tested independently.
    """
    c = dict(candidate or {})
    url = _h15_https(c.get('installer_url'))
    digest = _h15_digest(c.get('installer_sha256'))
    if not url or not digest:
        raise RuntimeError('缺少可验证的 HTTPS 安装器或 SHA-256')
    expected_size = max(0, int(c.get('installer_size') or 0))
    if expected_size > H15_UPDATE_MAX_BYTES:
        raise RuntimeError('安装器超过安全大小上限')
    updates_dir = os.path.abspath(str(updates_dir or '').strip())
    if not updates_dir:
        raise RuntimeError('更新目录无效')
    os.makedirs(updates_dir, exist_ok=True)
    name = _h15_safe_installer_name(c.get('installer_name') or urllib.parse.urlparse(url).path)
    final_path = os.path.abspath(os.path.join(updates_dir, name))
    if os.path.commonpath((updates_dir, final_path)) != updates_dir:
        raise RuntimeError('安装器文件名越界')
    part_path = final_path + '.part'
    try:
        os.remove(part_path)
    except FileNotFoundError:
        pass
    hasher = hashlib.sha256()
    received = 0
    getter = request_get or requests.get
    try:
        with getter(
            url,
            headers={'User-Agent': f'LimbusLyric-{_h15_current_version_label()}'},
            stream=True,
            timeout=(5, 20),
        ) as response:
            response.raise_for_status()
            if not _h15_https(getattr(response, 'url', url)):
                raise RuntimeError('安装器发生了非 HTTPS 重定向')
            header_size = int(response.headers.get('Content-Length') or 0)
            if header_size > H15_UPDATE_MAX_BYTES:
                raise RuntimeError('安装器响应超过安全大小上限')
            with open(part_path, 'wb') as output:
                for chunk in response.iter_content(chunk_size=H15_UPDATE_CHUNK_BYTES):
                    if not chunk:
                        continue
                    received += len(chunk)
                    if received > H15_UPDATE_MAX_BYTES:
                        raise RuntimeError('安装器下载超过安全大小上限')
                    hasher.update(chunk)
                    output.write(chunk)
                output.flush()
                try:
                    os.fsync(output.fileno())
                except Exception:
                    pass
        if expected_size and received != expected_size:
            raise RuntimeError(f'安装器大小不匹配：expected={expected_size} actual={received}')
        actual = hasher.hexdigest().lower()
        if actual != digest:
            raise RuntimeError(f'SHA-256 校验失败：expected={digest} actual={actual}')
        os.replace(part_path, final_path)
        return final_path, received, actual
    except Exception:
        try:
            os.remove(part_path)
        except Exception:
            pass
        raise


def _h15_download_verified_installer(panel, candidate):
    if bool(getattr(panel, '_h15_update_download_busy', False)):
        return
    c = dict(candidate or {})
    url = _h15_https(c.get('installer_url'))
    digest = _h15_digest(c.get('installer_sha256'))
    if not bool(c.get('newer')):
        return
    if not url or not digest:
        page = _h15_https(c.get('page_url'))
        if page:
            QDesktopServices.openUrl(QUrl(page))
        return
    if os.name != 'nt':
        page = _h15_https(c.get('page_url'))
        QMessageBox.information(panel, '下载更新', '自动安装仅在 Windows 正式版中启用。')
        if page:
            QDesktopServices.openUrl(QUrl(page))
        return

    answer = QMessageBox.question(
        panel,
        '下载并安装更新',
        f'将下载并校验 {c.get("version") or "新版本"} 的安装器。\n\n'
        'SHA-256 校验成功后会启动安装程序，并退出当前 LimbusLyric。\n'
        '安装过程仍由现有安装向导完成，不会由主程序直接覆盖自身文件。\n\n继续吗？',
        QMessageBox.Yes | QMessageBox.No,
        QMessageBox.No,
    )
    if answer != QMessageBox.Yes:
        return

    panel._h15_update_download_busy = True
    panel.h12_check_btn.setEnabled(False)
    panel.h12_download_btn.setEnabled(False)
    panel.h12_download_btn.setText('正在下载…')
    panel.h12_update_status.setPlainText(
        _h15_update_status(c) + '\n\n正在下载并校验安装器…'
    )

    def work():
        try:
            updates_dir = os.path.join(_CONFIG_ROOT, 'updates')
            final_path, _received, _actual = _h15_download_installer_file(c, updates_dir)
            panel._h15_update_download_result = (True, final_path, c, '')
        except Exception as exc:
            panel._h15_update_download_result = (False, '', c, f'更新下载失败：{exc}')

    threading.Thread(target=work, name='LimbusLyric-H15UpdateDownload', daemon=True).start()


def _h15_launch_installer(panel, installer_path, candidate):
    path = os.path.abspath(str(installer_path or ''))
    if os.name != 'nt' or not path.lower().endswith('.exe') or not os.path.isfile(path):
        raise RuntimeError('安装器路径无效')
    subprocess.Popen([path], cwd=os.path.dirname(path), close_fds=True)
    try:
        write_error_log('H15更新安装器已启动', detail=(
            f'version={candidate.get("version") or ""} | path={path} | '
            f'sha256={candidate.get("installer_sha256") or ""} | action=bounded-exit'))
    except Exception:
        pass
    panel.h12_update_status.setPlainText(
        _h15_update_status(candidate) + '\n\n安装程序已启动，LimbusLyric 正在退出…'
    )
    QTimer.singleShot(250, panel._exit_app)


def _h15_maybe_auto_check(panel):
    """Check the built-in release feed at most once per day without blocking startup."""
    try:
        enabled = str(os.environ.get('LIMBUSLYRIC_AUTO_UPDATE_CHECK', '1')).strip().lower() not in {'0', 'false', 'no', 'off'}
        if not enabled or not hasattr(panel, 'h12_check_btn'):
            return
        data = load_all_config(); settings = data.setdefault('settings', {})
        now = float(time.time())
        last = float(settings.get('h15_last_auto_check_epoch', 0.0) or 0.0)
        if now - last < float(H15_AUTO_CHECK_INTERVAL_SEC):
            return
        # Record the attempt before networking so repeated launches cannot hammer GitHub when offline.
        settings['h15_last_auto_check_epoch'] = now
        _write_config_dict_atomic(data)
        _h15_check_update(panel)
    except Exception as exc:
        try: write_error_log('H15自动更新检查调度失败', exc)
        except Exception: pass


def _h15_poll_async(panel):
    _LIMBUS_H15_H12_POLL_PRE(panel)
    checked = getattr(panel, '_h15_update_check_result', None)
    if checked is not None:
        panel._h15_update_check_result = None
        panel._h15_update_check_busy = False
        ok, candidate, error = checked
        panel.h12_check_btn.setEnabled(not bool(getattr(panel, '_h15_update_download_busy', False)))
        if ok:
            panel._h15_update_candidate = dict(candidate or {})
            panel._h12_update_download_url = _h15_https(candidate.get('page_url') or candidate.get('installer_url'))
            panel.h12_update_status.setPlainText(_h15_update_status(candidate))
            if bool(candidate.get('newer')):
                try:
                    version = str(candidate.get('version') or '新版本')
                    if version != str(getattr(panel, '_h15_notified_version', '') or ''):
                        panel._h15_notified_version = version
                        tray = getattr(panel, 'tray_icon', None)
                        if tray is not None:
                            tray.showMessage('LimbusLyric 有新版本', f'发现 {version}，可在“显示与更新”中下载。', QSystemTrayIcon.Information, 7000)
                except Exception:
                    pass
            if bool(candidate.get('newer')) and bool(candidate.get('verified_installer')):
                panel.h12_download_btn.setText('下载并安装')
                panel.h12_download_btn.setEnabled(True)
            elif bool(candidate.get('newer')) and _h15_https(candidate.get('page_url')):
                panel.h12_download_btn.setText('打开下载页')
                panel.h12_download_btn.setEnabled(True)
            else:
                panel.h12_download_btn.setText('下载更新')
                panel.h12_download_btn.setEnabled(False)
        else:
            panel._h15_update_candidate = {}
            panel.h12_update_status.setPlainText(str(error or '检查更新失败'))
            panel.h12_download_btn.setText('下载更新')
            panel.h12_download_btn.setEnabled(False)

    downloaded = getattr(panel, '_h15_update_download_result', None)
    if downloaded is not None:
        panel._h15_update_download_result = None
        panel._h15_update_download_busy = False
        ok, path, candidate, error = downloaded
        panel.h12_check_btn.setEnabled(True)
        if not ok:
            panel.h12_update_status.setPlainText(_h15_update_status(candidate) + f'\n\n{error}')
            panel.h12_download_btn.setText('重试下载并安装')
            panel.h12_download_btn.setEnabled(bool(candidate.get('verified_installer')))
        else:
            panel.h12_update_status.setPlainText(_h15_update_status(candidate) + '\n\n安装器 SHA-256 校验通过，正在启动安装程序…')
            panel.h12_download_btn.setText('校验通过')
            panel.h12_download_btn.setEnabled(False)
            try:
                _h15_launch_installer(panel, path, candidate)
            except Exception as exc:
                panel.h12_update_status.setPlainText(_h15_update_status(candidate) + f'\n\n启动安装器失败：{exc}')
                panel.h12_download_btn.setText('重试下载并安装')
                panel.h12_download_btn.setEnabled(True)


globals()['_h12_poll_async'] = _h15_poll_async
globals()['_h12_check_update'] = _h15_check_update


def _h15_update_button_clicked(panel):
    candidate = dict(getattr(panel, '_h15_update_candidate', {}) or {})
    if bool(candidate.get('verified_installer')):
        _h15_download_verified_installer(panel, candidate)
        return
    page = _h15_https(candidate.get('page_url') or getattr(panel, '_h12_update_download_url', ''))
    if page:
        QDesktopServices.openUrl(QUrl(page))


def _h15_harmonize_frontend_cards(panel):
    """Apply the R4 card rhythm to H12/H13 cards created after base UI construction."""
    try:
        baseline = list(getattr(panel, '_h12_layout_baseline', []) or [])
        for card in panel.findChildren(QFrame, 'settingsCard'):
            layout = card.layout()
            if layout is not None:
                layout.setContentsMargins(16, 15, 16, 16)
                layout.setSpacing(10)
                for idx, (known_layout, _base) in enumerate(baseline):
                    if known_layout is layout:
                        baseline[idx] = (known_layout, (16, 15, 16, 16, 10))
                        break
            # Runtime extension cards still carry the old sectionTitle object name.
            for label in card.findChildren(QLabel, 'sectionTitle', Qt.FindDirectChildrenOnly):
                if str(label.text() or '').strip().startswith(('H12 ·', 'H13 ·')):
                    label.setObjectName('cardTitle')
                    label.style().unpolish(label); label.style().polish(label)
        panel._h12_layout_baseline = baseline
        try:
            _h12_apply_scale(panel, int(getattr(panel, '_h12_ui_scale_pct', 100) or 100))
        except Exception:
            pass
        if hasattr(panel, '_filter_settings_cards'):
            panel._filter_settings_cards(panel.settings_filter.text() if hasattr(panel, 'settings_filter') else '')
    except Exception as exc:
        try:
            write_error_log('H15前端动态卡片整合失败', exc)
        except Exception:
            pass


def _h15_control_init(self, *args, **kwargs):
    _LIMBUS_H15_CONTROL_INIT_PRE(self, *args, **kwargs)
    self._h15_update_candidate = {}
    self._h15_update_check_busy = False
    self._h15_update_download_busy = False
    self._h15_update_check_result = None
    self._h15_update_download_result = None
    self._h15_notified_version = ''
    try:
        self.h12_update_status.setPlaceholderText(
            '支持 GitHub Release 或兼容 JSON manifest。只有 HTTPS 安装器同时带 SHA-256 时才允许自动执行。'
        )
        self.h12_check_btn.setText('检查更新')
        try:
            self.h12_download_btn.clicked.disconnect()
        except Exception:
            pass
        self.h12_download_btn.clicked.connect(lambda: _h15_update_button_clicked(self))
        self.h12_download_btn.setText('下载更新')
        self.h12_download_btn.setEnabled(False)
        _h15_harmonize_frontend_cards(self)
        QTimer.singleShot(H15_AUTO_CHECK_DELAY_MS, lambda p=self: _h15_maybe_auto_check(p))
    except Exception as exc:
        write_error_log('H15更新界面初始化失败', exc)


ControlPanel.__init__ = _h15_control_init



# H24 Win10 runtime safety / KuGou marquee identity closure ---------------------
# Field replay on Windows 10 19045 exposed two independent compatibility hazards:
# (1) NetEase/Chromium can become unresponsive after an in-process accessibility wake or
#     targeted UIA scan even though lyric/network work is healthy; and
# (2) KuGou's top-level title may be a rotating marquee.  Slices of that marquee can look
#     like valid ``artist - song`` text and repeatedly reset the same track.
# Fail closed only for the exact Win10 frozen NetEase accessibility profile, keep QQ's
# proven UIA path unchanged, and treat a changing same-HWND KuGou title as discovery-only
# until it is stable.  Also keep a session-scoped verified KuGou duration so a shorter
# same-title cache cannot downgrade a duration already proved in this session.
H24_NETEASE_WIN10_FROZEN_SAFE_MODE = str(os.environ.get(
    'LIMBUSLYRIC_H24_NETEASE_WIN10_NO_UIA_INIT', '1'
)).strip().lower() not in {'0','false','no','off'}
H24_NETEASE_WIN10_UIA_OPTIN = str(os.environ.get(
    'LIMBUSLYRIC_NETEASE_UIA_WIN10', '0'
)).strip().lower() in {'1','true','yes','on'}
H24_KUGOU_HOST_STABLE_MS = 1100.0
H24_KUGOU_MARQUEE_FUSE_MS = 6500.0
H24_KUGOU_DURATION_TOLERANCE_RATIO = 0.025
H24_KUGOU_DURATION_TOLERANCE_MIN_MS = 3500

_LIMBUS_H24_ASYNC_START_PRE = AsyncPlayerUiPositionReader.start
_LIMBUS_H24_ASYNC_SET_SUSPENDED_PRE = AsyncPlayerUiPositionReader.set_suspended
_LIMBUS_H24_ASYNC_WAKE_PRE = AsyncPlayerUiPositionReader._start_accessibility_wake
_LIMBUS_H24_ASYNC_KICK_PRE = AsyncPlayerUiPositionReader._kick_accessibility
_LIMBUS_H24_ASYNC_URGENT_PRE = AsyncPlayerUiPositionReader.request_urgent_scan
_LIMBUS_H24_ASYNC_INTERACTION_PRE = AsyncPlayerUiPositionReader.request_interaction_point_scan
_LIMBUS_H24_ASYNC_LYRIC_TEXT_PRE = AsyncPlayerUiPositionReader.request_lyric_text_probe
_LIMBUS_H24_NETEASE_SUSPEND_PRE = MediaSessionSync._set_netease_uia_suspended
_LIMBUS_H24_DETECTED_TRACK_PRE = ControlPanel._detected_player_track
_LIMBUS_H24_KUGOU_PROMOTE_PRE = ControlPanel._promote_kugou_background_identity_hint
_LIMBUS_H24_KUGOU_CREDIBLE_PRE = ControlPanel._kugou_window_probe_identity_credible
