def _h24_netease_uia_suspend_guard(self, suspended, reason='bridge-primary'):
    if str(getattr(self, '_process_hint', '') or '').lower() == 'cloudmusic' and _h24_netease_win10_frozen_no_accessibility('cloudmusic.exe'):
        suspended = True
        reason = 'win10-frozen-safe-mode'
    out = _LIMBUS_H24_NETEASE_SUSPEND_PRE(self, suspended, reason=reason)
    if bool(suspended):
        try:
            self._netease_uia_fallback_active = False
        except Exception:
            pass
    return out


