def _h24_kugou_title_compact(raw):
    return re.sub(r'\s+', '', str(raw or '').strip())


def _h24_kugou_title_is_rotation(previous, current):
    a = _h24_kugou_title_compact(previous)
    b = _h24_kugou_title_compact(current)
    if not a or not b or a == b or len(a) < 8 or len(a) != len(b):
        return False
    doubled = a + a
    return b in doubled[1:-1]


def _h24_kugou_split_shell_fragment(song, artist=''):
    # A rotating KuGou marquee can split the literal shell across the parsed fields, e.g.
    # artist='酷' + song='狗音乐 ...'.  Existing per-field checks miss that exact case.
    s = _h24_kugou_title_compact(song)
    a = _h24_kugou_title_compact(artist)
    return bool('酷狗音乐' in (a + s) or '酷狗音乐' in (s + a))


def _h24_kugou_window_probe_credible(song, artist=''):
    if _h24_kugou_split_shell_fragment(song, artist):
        return False
    return bool(_LIMBUS_H24_KUGOU_CREDIBLE_PRE(song, artist))


ControlPanel._kugou_window_probe_identity_credible = staticmethod(_h24_kugou_window_probe_credible)


def _h24_kugou_host_title_trusted(self, host):
    try:
        raw = str((host or {}).get('title') or '').strip()
        hwnd = int((host or {}).get('hwnd') or 0)
        if not raw or not hwnd:
            return False
        now = time.monotonic() * 1000.0
        state = dict(getattr(self, '_h24_kugou_host_title_state', {}) or {})
        if int(state.get('hwnd') or 0) != hwnd or not state.get('title'):
            state = {
                'hwnd': hwnd, 'title': raw, 'stable_since': now,
                'marquee_until': 0.0, 'last_log': 0.0,
            }
            self._h24_kugou_host_title_state = state
            return False
        previous = str(state.get('title') or '')
        if raw != previous:
            if _h24_kugou_title_is_rotation(previous, raw):
                state['marquee_until'] = max(float(state.get('marquee_until') or 0.0), now + float(H24_KUGOU_MARQUEE_FUSE_MS))
                if now - float(state.get('last_log') or 0.0) >= 1800.0:
                    state['last_log'] = now
                    try:
                        write_error_log('H24酷狗跑马灯Host身份熔断', detail=(
                            f'hwnd={hwnd} | previous={previous[:90]} | current={raw[:90]} | '
                            f'fuse={int(H24_KUGOU_MARQUEE_FUSE_MS)}ms | identity-authority=gsmtc/corroborated-only'))
                    except Exception:
                        pass
            state['title'] = raw
            state['stable_since'] = now
        self._h24_kugou_host_title_state = state
        if now < float(state.get('marquee_until') or 0.0):
            return False
        return bool(now - float(state.get('stable_since') or now) >= float(H24_KUGOU_HOST_STABLE_MS))
    except Exception:
        return False


def _h24_detected_player_track(self):
    try:
        if str(self.player_combo.currentText() or '') == '酷狗音乐':
            host = dict(getattr(self.media_sync, '_kugou_host_v2_cache', None) or {})
            host_mono = float(getattr(self.media_sync, '_kugou_host_v2_cache_mono', 0.0) or 0.0)
            host_age = time.monotonic() * 1000.0 - host_mono if host_mono > 0.0 else 10**9
            if host_age <= 2200.0 and str(host.get('class') or '').lower() == 'kugou_ui':
                trusted = _h24_kugou_host_title_trusted(self, host)
                raw = str(host.get('title') or '')
                hsong, hartist = LyricFetcher._split_title(
                    raw, '酷狗音乐', (self.players.get('酷狗音乐', {}) or {}).get('pattern')
                )
                if _h24_kugou_split_shell_fragment(hsong, hartist or ''):
                    trusted = False
                if not trusted:
                    state = dict(getattr(self, '_h24_kugou_host_title_state', {}) or {})
                    if time.monotonic() * 1000.0 < float(state.get('marquee_until') or 0.0):
                        self._h21_kugou_host_switch = None
                    saved = getattr(self.media_sync, '_kugou_host_v2_cache', None)
                    try:
                        self.media_sync._kugou_host_v2_cache = None
                        return _LIMBUS_H24_DETECTED_TRACK_PRE(self)
                    finally:
                        self.media_sync._kugou_host_v2_cache = saved
    except Exception:
        pass
    return _LIMBUS_H24_DETECTED_TRACK_PRE(self)


def _h24_kugou_promote(self, song, artist='', source='kugou-background-title', evidence_mono_ms=None):
    try:
        if str(source or '') == 'kugou-gsmtc-title-change':
            state = dict(getattr(self, '_h24_kugou_host_title_state', {}) or {})
            now_ms = time.monotonic() * 1000.0
            if now_ms < float(state.get('marquee_until') or 0.0):
                # A marquee-derived Host guard is not allowed to veto process-affine GSMTC.
                # H25: keep the authority behavior unchanged, but coalesce the diagnostic;
                # the H24 field log emitted this line hundreds of times per song.
                self._h21_kugou_host_switch = None
                try:
                    log_key = f'{_clean_name(song)}|{_clean_name(artist)}'
                    prev_key = str(getattr(self, '_h25_kugou_gsmtc_restore_log_key', '') or '')
                    prev_mono = float(getattr(self, '_h25_kugou_gsmtc_restore_log_mono', 0.0) or 0.0)
                    if log_key != prev_key or (now_ms - prev_mono) >= 6000.0:
                        self._h25_kugou_gsmtc_restore_log_key = log_key
                        self._h25_kugou_gsmtc_restore_log_mono = now_ms
                        write_error_log('H24酷狗跑马灯期间GSMTC恢复身份权威', detail=(
                            f'gsmtc={song}|{artist or "<empty>"} | host-veto=cleared | network-restart=normal | H25-log=coalesced'))
                except Exception:
                    pass
    except Exception:
        pass
    return _LIMBUS_H24_KUGOU_PROMOTE_PRE(
        self, song, artist, source=source, evidence_mono_ms=evidence_mono_ms
    )


ControlPanel._detected_player_track = _h24_detected_player_track
ControlPanel._promote_kugou_background_identity_hint = _h24_kugou_promote


def _h24_artist_alias_ok(a, b):
    a = str(a or '').strip(); b = str(b or '').strip()
    if not a or not b:
        return True
    try:
        ok, _why = _artist_alias_match(a, b)
        return bool(ok)
    except Exception:
        return _clean_name(a) == _clean_name(b)


def _h24_kugou_duration_row(self, song, artist=''):
    try:
        key = _clean_name(song)
        if not key:
            return None
        row = dict((getattr(self, '_h24_kugou_verified_durations', {}) or {}).get(key) or {})
        if not row:
            return None
        if not _h24_artist_alias_ok(artist, row.get('artist', '')):
            return None
        return row
    except Exception:
        return None


def _h24_kugou_duration_tol(a, b):
    return max(
        int(H24_KUGOU_DURATION_TOLERANCE_MIN_MS),
        int(max(int(a or 0), int(b or 0), 1) * float(H24_KUGOU_DURATION_TOLERANCE_RATIO))
    )


def _h24_remember_kugou_duration(self, song, artist, duration, *, player_duration=0, source='auto-result'):
    """Remember only independently corroborated KuGou duration evidence.

    H24 originally treated an accepted lyric-provider result as its own proof. Field replay
    showed that this creates a circular 81s -> accepted -> verified loop. A provider/cache
    duration may be a candidate, but it becomes session-verified only when an independent
    player-side duration corroborates the same version.
    """
    try:
        duration = int(duration or 0)
        player_duration = int(player_duration or 0)
        if duration < 5000 or player_duration < 5000:
            return False
        if abs(player_duration - duration) > _h24_kugou_duration_tol(player_duration, duration):
            return False
        key = _clean_name(song)
        if not key:
            return False
        rows = getattr(self, '_h24_kugou_verified_durations', None)
        if not isinstance(rows, dict):
            rows = {}
            self._h24_kugou_verified_durations = rows
        old = dict(rows.get(key) or {})
        if old and not _h24_artist_alias_ok(artist, old.get('artist', '')):
            return False
        old_duration = int(old.get('duration') or 0)
        if old_duration >= 5000 and abs(old_duration - duration) > _h24_kugou_duration_tol(old_duration, duration):
            # A genuinely different version is allowed only because the new candidate already
            # passed independent player-duration corroboration above.
            pass
        keep_artist = str(artist or old.get('artist') or '')
        try:
            if old.get('artist') and len(_artist_alias_keys(old.get('artist'))) > len(_artist_alias_keys(keep_artist)):
                keep_artist = str(old.get('artist') or keep_artist)
        except Exception:
            pass
        rows[key] = {
            'song': str(song or ''), 'artist': keep_artist, 'duration': duration,
            'player_duration': player_duration, 'source': str(source or ''), 'mono': time.monotonic(),
            'independent': True,
        }
        return True
    except Exception:
        return False


def _h24_start_auto_search_job(self, job):
    patched = dict(job or {})
    try:
        if str(patched.get('source') or '') == '酷狗' and int(patched.get('provider_duration_ms') or 0) <= 0:
            row = _h24_kugou_duration_row(self, patched.get('song', ''), patched.get('artist', ''))
            if row and int(row.get('duration') or 0) >= 5000:
                patched['provider_duration_ms'] = int(row.get('duration') or 0)
                patched['h24_session_duration_seed'] = True
                try:
                    write_error_log('H24酷狗会话已验证时长注入新事务', detail=(
                        f'song={patched.get("song","")} | artist={patched.get("artist","")} | '
                        f'duration={int(row.get("duration") or 0)}ms | source={row.get("source") or "session"} | '
                        'cache-downgrade=guarded'))
                except Exception:
                    pass
    except Exception:
        pass
    return _LIMBUS_H24_AUTO_START_PRE(self, patched)


def _h24_auto_lyric_result(self, result):
    patched = dict(result or {})
    remember = None
    try:
        if str(patched.get('source') or '') == '酷狗' and patched.get('lyric'):
            song = str(patched.get('song') or '')
            artist = str(patched.get('artist') or '')
            incoming = int(patched.get('duration') or 0)
            player_duration = int(patched.get('provider_duration_ms') or 0)
            row = _h24_kugou_duration_row(self, song, artist)
            known = int((row or {}).get('duration') or 0)
            if incoming >= 5000 and known >= 5000:
                tol = _h24_kugou_duration_tol(known, incoming)
                player_supports_new = bool(
                    player_duration >= 5000 and
                    abs(player_duration - incoming) <= _h24_kugou_duration_tol(player_duration, incoming)
                )
                if abs(known - incoming) > tol and not player_supports_new:
                    patched['lyric'] = None
                    patched['duration'] = 0
                    patched['precision_upgrade_pending'] = False
                    patched['progressive_keep_fast'] = True
                    patched['error'] = 'KuGou same-title cached version conflicts with session-verified duration'
                    try:
                        write_error_log('H24酷狗同名缓存时长降级拒绝', detail=(
                            f'song={song} | artist={artist or "<empty>"} | verified={known}ms | '
                            f'candidate={incoming}ms | player_duration={player_duration}ms | '
                            'action=keep-session-verified-payload'))
                    except Exception:
                        pass
                else:
                    remember = (song, artist, incoming, player_duration)
            elif incoming >= 5000:
                remember = (song, artist, incoming, player_duration)
    except Exception:
        pass
    out = _LIMBUS_H24_AUTO_RESULT_PRE(self, patched)
    if remember and patched.get('lyric'):
        _h24_remember_kugou_duration(
            self, remember[0], remember[1], remember[2],
            player_duration=remember[3], source='player-duration-corroborated-auto-result'
        )
    return out


ControlPanel._start_auto_search_job = _h24_start_auto_search_job
ControlPanel._on_auto_lyric_result = _h24_auto_lyric_result


def _h24_auto_cache_load(self):
    try:
        if os.path.exists(AUTO_LYRIC_CACHE_FILE):
            bad = False
            try:
                with open(AUTO_LYRIC_CACHE_FILE, 'r', encoding='utf-8') as f:
                    payload = json.load(f)
                bad = not isinstance(payload, dict) or not isinstance(payload.get('rows', []), list)
            except Exception:
                bad = True
            if bad:
                stamp = time.strftime('%Y%m%d-%H%M%S')
                backup = AUTO_LYRIC_CACHE_FILE + '.corrupt-' + stamp
                try:
                    os.replace(AUTO_LYRIC_CACHE_FILE, backup)
                except Exception:
                    backup = '<replace-failed>'
                try:
                    os.makedirs(os.path.dirname(AUTO_LYRIC_CACHE_FILE), exist_ok=True)
                    tmp = AUTO_LYRIC_CACHE_FILE + '.tmp'
                    with open(tmp, 'w', encoding='utf-8') as f:
                        json.dump({'version': 1, 'rows': []}, f, ensure_ascii=False, separators=(',', ':'))
                        f.flush()
                    os.replace(tmp, AUTO_LYRIC_CACHE_FILE)
                    write_error_log('H24自动歌词损坏缓存自愈', detail=(
                        f'file={AUTO_LYRIC_CACHE_FILE} | backup={backup} | reset=empty-valid-json'))
                except Exception as exc:
                    write_error_log('H24自动歌词损坏缓存自愈失败', exc, detail=AUTO_LYRIC_CACHE_FILE)
    except Exception:
        pass
    return _LIMBUS_H24_CACHE_LOAD_PRE(self)


ControlPanel._load_auto_lyric_cache_from_disk = _h24_auto_cache_load


