# H25 clock / seek / evidence closure -------------------------------------------
# Full H24 field-log replay exposed three remaining correctness gaps:
# (1) an accepted KuGou lyric duration could certify itself as "verified";
# (2) manual/auto KuGou artist enrichment bypassed the marquee/shell credibility gate; and
# (3) H24's Win10 frozen NetEase no-UIA profile removed the only surviving absolute
#     position observer when strict GSMTC/native-log were unavailable.  H25 keeps the
#     accessibility fail-closed policy, but adds a screen-pixel-only Win32/GDI rail clock.
# The rail runs on MediaSessionSync's worker, never traverses Chromium accessibility trees,
# requires multi-sample wall-clock coherence, and treats transport clicks as intent only
# unless they land on an already learned physical rail.
H25_NETEASE_VISUAL_SAMPLE_MS = 420.0
H25_NETEASE_VISUAL_MIN_HITS = 3
H25_NETEASE_VISUAL_MIN_SPAN_MS = 720.0
H25_NETEASE_VISUAL_CAPTURE_Y_MIN = 0.775
H25_NETEASE_VISUAL_CAPTURE_Y_MAX = 0.968
H25_NETEASE_VISUAL_RECT_TTL_MS = 7000.0
H25_NETEASE_VISUAL_LOCAL_HOLD_MS = 2200.0
H25_NETEASE_VISUAL_STATIC_PAUSE_MS = 1250.0
H25_NETEASE_SEEK_INTENT_MS = 3200.0
H25_NETEASE_SEEK_SEED_MS = 1500.0

_LIMBUS_H25_NETEASE_INTERACTION_PRE = MediaSessionSync._netease_apply_verified_page_interaction
_LIMBUS_H25_KUGOU_TRANSPORT_REQUEST_PRE = MediaSessionSync.request_kugou_transport_instance_from_edge
_LIMBUS_H25_MANUAL_APPLY_PRE = ControlPanel._apply_manual_lyric_payload
_LIMBUS_H25_AUTO_RESULT_PRE = ControlPanel._on_auto_lyric_result


def _h25_kugou_recent_committed_seek(self, now_ms=None):
    """True only for a *committed* rail seek, never for a broad mouse-down candidate.

    KuGou may emit Media/Playback callbacks as a side effect of seeking.  Those callbacks are
    evidence-only and must not turn an already committed absolute user gesture into a synthetic
    same-song restart at 0ms.  The guard is deliberately short and requires the rail-local master
    to still be the exact committed gesture for the current track/player/identity epochs, so a
    real duplicate-playlist Next remains unchanged when there was no seek commit.
    """
    try:
        now = float(now_ms if now_ms is not None else time.monotonic() * 1000.0)
        gesture_mono = float(getattr(self, '_kugou_last_gesture_mono', 0.0) or 0.0)
        if gesture_mono <= 0.0 or not (0.0 <= now - gesture_mono <= 1500.0):
            return False
        return bool(
            getattr(self, '_kugou_rail_master_active', False) and
            getattr(self, '_kugou_rail_master_absolute', False) and
            str(getattr(self, '_kugou_rail_master_reason', '') or '') == 'user-rail-gesture' and
            str(getattr(self, '_kugou_rail_master_track_key', '') or '') == str(getattr(self, '_track_key', '') or '') and
            int(getattr(self, '_kugou_rail_master_player_epoch', -1)) == int(getattr(self, '_media_player_epoch', 0) or 0) and
            int(getattr(self, '_kugou_rail_master_identity_epoch', -1)) == int(getattr(self, '_track_identity_epoch', 0) or 0)
        )
    except Exception:
        return False


def _h25_request_kugou_transport_instance_from_edge(self, edge_serial, reason='gsmtc-transport-edge'):
    # A proven user seek outranks ambiguous same-identity GSMTC Media/Playback callbacks.  Do not
    # use raw mouse-down/candidate state here: the field log shows KuGou transport buttons can sit
    # inside the broad first-discovery band.  Only _kugou_commit_gesture_seek() may arm this veto.
    try:
        serial = int(edge_serial or 0)
    except Exception:
        return False
    if serial > 0 and _h25_kugou_recent_committed_seek(self):
        self._kugou_transport_edge_consumed_serial = max(
            serial, int(getattr(self, '_kugou_transport_edge_consumed_serial', 0) or 0)
        )
        try:
            write_error_log('H25酷狗Seek期间同曲Transport零点接管否决', detail=(
                f'edge_serial={serial} | reason={reason} | '
                f'gesture_position={int(round(float(getattr(self, "_kugou_rail_master_position_ms", 0.0) or 0.0)))}ms | '
                'authority=user-rail-gesture | local-zero=skip'))
        except Exception:
            pass
        return False
    return _LIMBUS_H25_KUGOU_TRANSPORT_REQUEST_PRE(self, edge_serial, reason=reason)


MediaSessionSync._h25_kugou_recent_committed_seek = _h25_kugou_recent_committed_seek
MediaSessionSync.request_kugou_transport_instance_from_edge = _h25_request_kugou_transport_instance_from_edge


def _h25_netease_safe_profile(self=None):
    try:
        return bool(
            globals().get('_h24_netease_win10_frozen_no_accessibility') and
            _h24_netease_win10_frozen_no_accessibility('cloudmusic.exe')
        )
    except Exception:
        return False


def _h25_netease_visual_proof_step(pending, observed, now_ms, x0, x1, y, duration_ms):
    """Pure replayable proof: the visible rail boundary must advance at wall-clock pace."""
    try:
        observed = float(observed); now_ms = float(now_ms); duration_ms = float(duration_ms)
        x0 = float(x0); x1 = float(x1); y = float(y)
        rail_w = max(1.0, x1 - x0)
    except Exception:
        return None, False
    if not isinstance(pending, dict):
        return ({'hits': 1, 'first_mono': now_ms, 'last_mono': now_ms,
                 'last_position': observed, 'x0': x0, 'x1': x1, 'y': y,
                 'rail_w': rail_w}, False)
    try:
        dt = max(1.0, now_ms - float(pending.get('last_mono') or now_ms))
        dp = observed - float(pending.get('last_position') or observed)
        same_geom = bool(
            abs(y - float(pending.get('y') or y)) <= 9.0 and
            abs(x0 - float(pending.get('x0') or x0)) <= 48.0 and
            abs(x1 - float(pending.get('x1') or x1)) <= 48.0
        )
        # Pixel quantization on a ~200s song can be hundreds of ms per pixel.  Keep the
        # corridor wide enough for that quantization but narrow enough to reject animations.
        tol = max(520.0, dt * 0.86, duration_ms / max(90.0, rail_w) * 2.2)
        coherent = bool(same_geom and dp >= -tol * 0.18 and abs(dp - dt) <= tol)
    except Exception:
        coherent = False
    if not coherent:
        return ({'hits': 1, 'first_mono': now_ms, 'last_mono': now_ms,
                 'last_position': observed, 'x0': x0, 'x1': x1, 'y': y,
                 'rail_w': rail_w}, False)
    row = dict(pending)
    row['hits'] = int(row.get('hits') or 1) + 1
    row['last_mono'] = now_ms
    row['last_position'] = observed
    row['x0'] = x0; row['x1'] = x1; row['y'] = y; row['rail_w'] = rail_w
    span = now_ms - float(row.get('first_mono') or now_ms)
    proven = bool(int(row['hits']) >= int(H25_NETEASE_VISUAL_MIN_HITS) and span >= float(H25_NETEASE_VISUAL_MIN_SPAN_MS))
    return row, proven


def _h25_netease_window_rect(self):
    now = time.monotonic() * 1000.0
    cached = getattr(self, '_h25_netease_window_rect_cache', None)
    cached_mono = float(getattr(self, '_h25_netease_window_rect_mono', 0.0) or 0.0)
    if isinstance(cached, (tuple, list)) and len(cached) == 4 and now - cached_mono <= float(H25_NETEASE_VISUAL_RECT_TTL_MS):
        return tuple(int(v) for v in cached)
    # This helper is Win32-only. It may enumerate processes, so it is called only from the
    # MediaSessionSync worker and is strongly cached; never call it on Qt hot paths.
    try:
        reader = getattr(getattr(self, '_uia_reader', None), '_reader', None)
        rect = reader._clock_wake_window_rect('cloudmusic.exe') if reader is not None else None
    except Exception:
        rect = None
    if isinstance(rect, (tuple, list)) and len(rect) == 4:
        rect = tuple(int(v) for v in rect)
        self._h25_netease_window_rect_cache = rect
        self._h25_netease_window_rect_mono = now
        return rect
    return tuple(int(v) for v in cached) if isinstance(cached, (tuple, list)) and len(cached) == 4 else None


def _h25_netease_capture_visual_strip(self, rect):
    """Read only desktop pixels around NetEase's lower transport rail; no UIA/MSAA/COM."""
    if os.name != 'nt' or not rect:
        return None
    try:
        l, t, r, b = [int(round(float(v))) for v in rect]
        ww, wh = max(1, r-l), max(1, b-t)
        sx = l + int(round(ww * 0.025)); ex = l + int(round(ww * 0.975))
        sy = t + int(round(wh * float(H25_NETEASE_VISUAL_CAPTURE_Y_MIN)))
        ey = t + int(round(wh * float(H25_NETEASE_VISUAL_CAPTURE_Y_MAX)))
        cw, ch = max(8, ex-sx), max(8, ey-sy)
        if cw > 4096 or ch > 700:
            return None
        from ctypes import wintypes as _wt
        user32 = ctypes.windll.user32; gdi32 = ctypes.windll.gdi32
        user32.GetDC.argtypes = [_wt.HWND]; user32.GetDC.restype = _wt.HDC
        user32.ReleaseDC.argtypes = [_wt.HWND, _wt.HDC]; user32.ReleaseDC.restype = ctypes.c_int
        gdi32.CreateCompatibleDC.argtypes = [_wt.HDC]; gdi32.CreateCompatibleDC.restype = _wt.HDC
        gdi32.CreateCompatibleBitmap.argtypes = [_wt.HDC, ctypes.c_int, ctypes.c_int]; gdi32.CreateCompatibleBitmap.restype = _wt.HBITMAP
        gdi32.SelectObject.argtypes = [_wt.HDC, ctypes.c_void_p]; gdi32.SelectObject.restype = ctypes.c_void_p
        gdi32.DeleteObject.argtypes = [ctypes.c_void_p]; gdi32.DeleteObject.restype = ctypes.c_int
        gdi32.DeleteDC.argtypes = [_wt.HDC]; gdi32.DeleteDC.restype = ctypes.c_int
        gdi32.BitBlt.argtypes = [_wt.HDC, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, _wt.HDC, ctypes.c_int, ctypes.c_int, _wt.DWORD]
        gdi32.BitBlt.restype = ctypes.c_int
        gdi32.GetDIBits.argtypes = [_wt.HDC, _wt.HBITMAP, _wt.UINT, _wt.UINT, ctypes.c_void_p, ctypes.c_void_p, _wt.UINT]
        gdi32.GetDIBits.restype = ctypes.c_int
        class _BMIH(ctypes.Structure):
            _fields_ = [('biSize', _wt.DWORD), ('biWidth', ctypes.c_long), ('biHeight', ctypes.c_long),
                        ('biPlanes', _wt.WORD), ('biBitCount', _wt.WORD), ('biCompression', _wt.DWORD),
                        ('biSizeImage', _wt.DWORD), ('biXPelsPerMeter', ctypes.c_long), ('biYPelsPerMeter', ctypes.c_long),
                        ('biClrUsed', _wt.DWORD), ('biClrImportant', _wt.DWORD)]
        class _RGBQ(ctypes.Structure):
            _fields_ = [('rgbBlue', ctypes.c_ubyte), ('rgbGreen', ctypes.c_ubyte),
                        ('rgbRed', ctypes.c_ubyte), ('rgbReserved', ctypes.c_ubyte)]
        class _BMI(ctypes.Structure):
            _fields_ = [('bmiHeader', _BMIH), ('bmiColors', _RGBQ * 1)]
        hdc = user32.GetDC(None)
        if not hdc:
            return None
        mem = gdi32.CreateCompatibleDC(hdc)
        bmp = gdi32.CreateCompatibleBitmap(hdc, cw, ch) if mem else None
        old = gdi32.SelectObject(mem, bmp) if bmp else None
        try:
            if not mem or not bmp:
                return None
            if not gdi32.BitBlt(mem, 0, 0, cw, ch, hdc, sx, sy, 0x00CC0020 | 0x40000000):
                return None
            bmi = _BMI(); bmi.bmiHeader.biSize = ctypes.sizeof(_BMIH)
            bmi.bmiHeader.biWidth = cw; bmi.bmiHeader.biHeight = -ch
            bmi.bmiHeader.biPlanes = 1; bmi.bmiHeader.biBitCount = 32; bmi.bmiHeader.biCompression = 0
            buf = ctypes.create_string_buffer(cw * ch * 4)
            got = gdi32.GetDIBits(mem, bmp, 0, ch, buf, ctypes.byref(bmi), 0)
            if int(got or 0) != ch:
                return None
            return {'x': sx, 'y': sy, 'w': cw, 'h': ch, 'data': bytes(buf.raw)}
        finally:
            try:
                if old: gdi32.SelectObject(mem, old)
            except Exception: pass
            try:
                if bmp: gdi32.DeleteObject(bmp)
            except Exception: pass
            try:
                if mem: gdi32.DeleteDC(mem)
            except Exception: pass
            try: user32.ReleaseDC(None, hdc)
            except Exception: pass
    except Exception:
        return None


def _h25_netease_visual_row(self, position, duration, status, source, confidence=236, detail=''):
    try:
        position = max(0, min(int(round(float(duration))), int(round(float(position)))))
    except Exception:
        return None
    return {
        'ready': True, 'clock_ok': True, 'position_ms': position,
        'duration_ms': int(round(float(duration))), 'status': str(status or 'unknown'),
        'source': str(source or 'ncm-win32-visual-rail'), 'source_key': 'ncm:win32-visual-rail',
        'confidence': int(confidence), 'title': '', 'artist': '',
        'detail': str(detail or 'screen-pixel rail; no accessibility traversal'),
    }


def _h25_poll_netease_safe_visual_clock(self, status_hint='unknown'):
    if self._process_stem(self._process_hint) != 'cloudmusic' or not _h25_netease_safe_profile(self):
        return None
    try:
        duration = float(self._uia_duration_ms or self._state.get('duration_ms') or 0.0)
    except Exception:
        duration = 0.0
    if duration <= 5000.0:
        return None
    now = time.monotonic() * 1000.0
    track = str(self._track_key or '')
    if track != str(getattr(self, '_h25_netease_visual_track_key', '') or ''):
        self._h25_netease_visual_track_key = track
        self._h25_netease_visual_prev_frame = None
        self._h25_netease_visual_prev_mono = 0.0
        self._h25_netease_visual_pending = None
        self._h25_netease_visual_locked = False
        self._h25_netease_visual_anchor_position = None
        self._h25_netease_visual_anchor_mono = 0.0
        self._h25_netease_visual_static_since = 0.0
        self._h25_netease_seek_seed = None

    # A click can seed an already learned physical rail immediately. It remains provisional
    # and expires quickly unless the screen rail reconfirms it.
    seed = getattr(self, '_h25_netease_seek_seed', None)
    if isinstance(seed, dict) and now <= float(seed.get('until') or 0.0):
        seed_row = _h25_netease_visual_row(
            seed.get('position'), duration, seed.get('status') or 'playing',
            'ncm-win32-seek-intent-local', confidence=218,
            detail='explicit transport click on learned physical rail; awaiting pixel reconfirmation'
        )
    else:
        seed_row = None
        if isinstance(seed, dict):
            self._h25_netease_seek_seed = None

    # Honor an explicit paused state immediately. The most recent physical anchor is safer
    # than inventing forward progress while the player says paused.
    if str(status_hint or '').lower() == 'paused':
        anchor = getattr(self, '_h25_netease_visual_anchor_position', None)
        if anchor is not None:
            return _h25_netease_visual_row(anchor, duration, 'paused', 'ncm-win32-visual-rail', 240, 'paused; freeze last physical rail anchor')
        return seed_row

    last_sample = float(getattr(self, '_h25_netease_visual_prev_mono', 0.0) or 0.0)
    if now - last_sample < float(H25_NETEASE_VISUAL_SAMPLE_MS):
        if seed_row is not None:
            return seed_row
        anchor = getattr(self, '_h25_netease_visual_anchor_position', None)
        anchor_mono = float(getattr(self, '_h25_netease_visual_anchor_mono', 0.0) or 0.0)
        if anchor is not None and bool(getattr(self, '_h25_netease_visual_locked', False)) and now - anchor_mono <= float(H25_NETEASE_VISUAL_LOCAL_HOLD_MS):
            predicted = float(anchor) + max(0.0, now - anchor_mono)
            return _h25_netease_visual_row(predicted, duration, 'playing', 'ncm-win32-visual-local', 226, 'short monotonic hold from verified physical rail')
        return None

    rect = _h25_netease_window_rect(self)
    frame = _h25_netease_capture_visual_strip(self, rect)
    self._h25_netease_visual_prev_mono = now
    if not frame:
        return seed_row
    prev = getattr(self, '_h25_netease_visual_prev_frame', None)
    self._h25_netease_visual_prev_frame = frame
    if not prev:
        return seed_row

    motion = self._kugou_visual_motion_candidate(prev, frame)
    if not motion:
        if bool(getattr(self, '_h25_netease_visual_locked', False)):
            if float(getattr(self, '_h25_netease_visual_static_since', 0.0) or 0.0) <= 0.0:
                self._h25_netease_visual_static_since = now
            static_age = now - float(self._h25_netease_visual_static_since or now)
            anchor = getattr(self, '_h25_netease_visual_anchor_position', None)
            if anchor is not None and static_age >= float(H25_NETEASE_VISUAL_STATIC_PAUSE_MS) and str(status_hint or '').lower() != 'playing':
                return _h25_netease_visual_row(anchor, duration, 'paused', 'ncm-win32-visual-rail', 224, 'physical rail static; conservative pause freeze')
        return seed_row
    self._h25_netease_visual_static_since = 0.0
    _score, lx, ly, changed = motion
    try:
        ww = max(1.0, float(rect[2]) - float(rect[0]))
    except Exception:
        ww = float(frame.get('w') or 1)
    bounds = self._kugou_visual_infer_bounds(frame, lx, ly, ww)
    if not bounds:
        self._h25_netease_visual_pending = None
        return seed_row
    gx0, gx1, gy, rail_w, color_sep = bounds
    gx = float(frame['x']) + float(lx)
    ratio = max(0.0, min(1.0, (gx - float(gx0)) / max(1.0, float(gx1-gx0))))
    observed = ratio * duration
    pending, proven = _h25_netease_visual_proof_step(
        getattr(self, '_h25_netease_visual_pending', None), observed, now,
        gx0, gx1, gy, duration
    )
    self._h25_netease_visual_pending = pending
    if not proven:
        return seed_row

    previous_anchor = getattr(self, '_h25_netease_visual_anchor_position', None)
    previous_mono = float(getattr(self, '_h25_netease_visual_anchor_mono', 0.0) or 0.0)
    predicted = None
    if previous_anchor is not None and previous_mono > 0.0:
        predicted = float(previous_anchor) + max(0.0, now - previous_mono)
    self._h25_netease_visual_locked = True
    self._h25_netease_visual_anchor_position = float(observed)
    self._h25_netease_visual_anchor_mono = now
    self._h25_netease_visual_bounds = (float(gx0), float(gx1))
    self._h25_netease_visual_y = float(gy)
    self._h25_netease_seek_seed = None
    seek_recent = now <= float(getattr(self, '_h25_netease_seek_intent_until_mono', 0.0) or 0.0)
    if predicted is not None and abs(float(observed) - float(predicted)) >= 1800.0 and seek_recent:
        try:
            self._mark_seek_burst(observed, 'ncm-win32-visual-rail', now)
            write_error_log('H25网易云Win32视觉Seek确认', detail=(
                f'predicted={int(round(predicted))}ms | observed={int(round(observed))}ms | '
                f'delta={int(round(observed-predicted))}ms | rail=({int(gx0)},{int(gy)})->({int(gx1)},{int(gy)}) | '
                'accessibility=0'))
        except Exception:
            pass
    last_diag = float(getattr(self, '_h25_netease_visual_diag_mono', 0.0) or 0.0)
    if now - last_diag >= 8000.0:
        self._h25_netease_visual_diag_mono = now
        try:
            write_error_log('H25网易云Win32视觉时钟已锁定', detail=(
                f'position={int(round(observed))}ms | duration={int(round(duration))}ms | ratio={ratio:.5f} | '
                f'rail=({int(gx0)},{int(gy)})->({int(gx1)},{int(gy)}) | '
                f'hits={int((pending or {}).get("hits") or 0)} | color_sep={int(color_sep)} | screen-readonly=1 | accessibility=0'))
        except Exception:
            pass
    return _h25_netease_visual_row(observed, duration, 'playing', 'ncm-win32-visual-rail', 242, 'multi-sample physical rail proof')


MediaSessionSync._h25_poll_netease_safe_visual_clock = _h25_poll_netease_safe_visual_clock


def _h25_netease_apply_verified_page_interaction(self, hit):
    if not _h25_netease_safe_profile(self):
        return _LIMBUS_H25_NETEASE_INTERACTION_PRE(self, hit)
    if not isinstance(hit, dict) or self._process_stem(self._process_hint) != 'cloudmusic':
        return False
    try:
        cx, cy = int(hit.get('cx')), int(hit.get('cy'))
    except Exception:
        return False
    zone = self._netease_click_zone(cx, cy)
    if zone is None:
        return False
    now = time.monotonic() * 1000.0
    self._netease_page_interaction_until_mono = now + float(NETEASE_CLICK_EVIDENCE_MS)
    rect = None
    try:
        if win32gui is not None:
            hwnd = win32gui.WindowFromPoint((cx, cy))
            if hwnd:
                try: hwnd = win32gui.GetAncestor(hwnd, getattr(win32con, 'GA_ROOT', 2)) or hwnd
                except Exception: pass
                rect = tuple(int(v) for v in win32gui.GetWindowRect(hwnd))
    except Exception:
        rect = None
    if isinstance(rect, tuple) and len(rect) == 4:
        self._h25_netease_window_rect_cache = rect
        self._h25_netease_window_rect_mono = now
    seeded = False
    target = None
    if zone == 'transport':
        self._h25_netease_seek_intent_until_mono = now + float(H25_NETEASE_SEEK_INTENT_MS)
        self._h25_netease_visual_pending = None
        bounds = getattr(self, '_h25_netease_visual_bounds', None)
        rail_y = getattr(self, '_h25_netease_visual_y', None)
        try:
            duration = float(self._uia_duration_ms or self._state.get('duration_ms') or 0.0)
            if (isinstance(bounds, (tuple, list)) and len(bounds) == 2 and rail_y is not None and duration > 5000.0):
                x0, x1 = float(bounds[0]), float(bounds[1])
                if x0 <= float(cx) <= x1 and abs(float(cy) - float(rail_y)) <= 24.0:
                    ratio = max(0.0, min(1.0, (float(cx)-x0) / max(1.0, x1-x0)))
                    target = ratio * duration
                    current_status = str(self._state.get('status') or 'unknown').lower()
                    seed_status = 'paused' if current_status == 'paused' else 'playing'
                    self._h25_netease_seek_seed = {
                        'position': float(target), 'status': seed_status,
                        'mono': now, 'until': now + float(H25_NETEASE_SEEK_SEED_MS),
                    }
                    seeded = True
                    try: self._mark_seek_burst(target, 'ncm-win32-seek-intent-local', now)
                    except Exception: pass
        except Exception:
            target = None
    if SOURCE_GUARD_ENABLED and now - float(getattr(self, '_h25_netease_interaction_log_mono', 0.0) or 0.0) >= 300.0:
        self._h25_netease_interaction_log_mono = now
        try:
            write_error_log('H25网易云Win10安全交互取证', detail=(
                f'cursor=({cx},{cy}) | zone={zone} | seek-intent={int(zone=="transport")} | '
                f'learned-rail-seed={int(seeded)} | target={None if target is None else int(round(target))}ms | '
                f'seed-status={str((getattr(self, "_h25_netease_seek_seed", {}) or {}).get("status") or "none")} | '
                'uia-request=0 | chromium-tree=0 | visual-reconfirm=1'))
        except Exception:
            pass
    return True


MediaSessionSync._netease_apply_verified_page_interaction = _h25_netease_apply_verified_page_interaction


def _h25_manual_apply(self, result):
    result = dict(result or {})
    out = _LIMBUS_H25_MANUAL_APPLY_PRE(self, result)
    try:
        if out and str(result.get('source') or '') == '酷狗' and result.get('lyric') and int(result.get('duration') or 0) >= 5000:
            song = str(result.get('song') or '')
            artist = str(result.get('artist') or '')
            # Manual payload is user-selected session preference, NOT independent player proof.
            # Keep it only for this bound track/identity epoch so automatic cache cannot instantly
            # downgrade it, while a real new track/version remains free to replace it.
            self._h25_kugou_manual_payload = {
                'song': song, 'artist': artist, 'duration': int(result.get('duration') or 0),
                'track_key': str(getattr(self.media_sync, '_track_key', '') or ''),
                'identity_epoch': int(getattr(self.media_sync, '_track_identity_epoch', 0) or 0),
                'player_epoch': int(getattr(self.media_sync, '_media_player_epoch', 0) or 0),
                'mono': time.monotonic(),
            }
            write_error_log('H25酷狗手动歌词会话偏好已记录', detail=(
                f'song={song} | artist={artist or "<empty>"} | duration={int(result.get("duration") or 0)}ms | '
                'authority=manual-payload-preference | verified-duration=0'))
    except Exception:
        pass
    return out


ControlPanel._apply_manual_lyric_payload = _h25_manual_apply


def _h25_auto_result(self, result):
    patched = dict(result or {})
    try:
        if str(patched.get('source') or '') == '酷狗' and patched.get('lyric') and int(patched.get('duration') or 0) >= 5000:
            pref = dict(getattr(self, '_h25_kugou_manual_payload', {}) or {})
            if pref:
                current_track = str(getattr(self.media_sync, '_track_key', '') or '')
                current_identity_epoch = int(getattr(self.media_sync, '_track_identity_epoch', 0) or 0)
                current_player_epoch = int(getattr(self.media_sync, '_media_player_epoch', 0) or 0)
                same_instance = bool(
                    current_track and current_track == str(pref.get('track_key') or '') and
                    current_identity_epoch == int(pref.get('identity_epoch') or -1) and
                    current_player_epoch == int(pref.get('player_epoch') or -1)
                )
                same_song = _clean_name(patched.get('song') or '') == _clean_name(pref.get('song') or '')
                alias_ok = _h24_artist_alias_ok(patched.get('artist') or '', pref.get('artist') or '')
                incoming = int(patched.get('duration') or 0); preferred = int(pref.get('duration') or 0)
                player_duration = int(patched.get('provider_duration_ms') or 0)
                player_supports_incoming = bool(
                    player_duration >= 5000 and abs(player_duration-incoming) <= _h24_kugou_duration_tol(player_duration, incoming)
                )
                if (same_instance and same_song and alias_ok and preferred >= 5000 and
                        abs(preferred-incoming) > _h24_kugou_duration_tol(preferred, incoming) and
                        not player_supports_incoming):
                    patched['lyric'] = None
                    patched['duration'] = 0
                    patched['precision_upgrade_pending'] = False
                    patched['progressive_keep_fast'] = True
                    patched['error'] = 'KuGou automatic candidate conflicts with current manual session payload'
                    write_error_log('H25酷狗自动歌词覆盖手动会话偏好已拒绝', detail=(
                        f'song={patched.get("song","")} | manual={preferred}ms | auto={incoming}ms | '
                        f'player_duration={player_duration}ms | action=keep-manual-session-payload'))
    except Exception:
        pass
    return _LIMBUS_H25_AUTO_RESULT_PRE(self, patched)


ControlPanel._on_auto_lyric_result = _h25_auto_result


# H26 transport ownership / Win10 evidence closure -------------------------------
# H25 field replay exposed two independent contract holes:
# 1) Win10 CloudMusic could still publish the generic auto-local lane after every
#    safe clock failed, turning UNKNOWN into a convincing 0ms position.
# 2) lyric-provider choice could invoke another open player's desktop clock/identity
#    probes. Transport belongs to the selected player; providers own network lyrics only.
#
# H26 is deliberately layered *after* H25. Historical class methods remain unchanged;
# Win10-only behavior is capability-gated, while cross-player ownership is enforced at
# shared desktop-probe boundaries. Win11 therefore keeps its established transport path.
H26_NETEASE_VISUAL_MIN_HITS = 3
H26_NETEASE_VISUAL_MIN_SPAN_MS = 900.0
H26_NETEASE_VISUAL_STALE_PROOF_MS = 2600.0
H26_NETEASE_VISUAL_MAX_CANDIDATES = 10
H26_NETEASE_UNKNOWN_SOURCES = {
    'auto-track-local-provisional', 'auto-track-local-guarded',
    'ncm-bridge-bootstrap-local', 'ncm-bridge-track-transition-local',
}
H26_TRANSITION_STRONG_POSITION_SOURCES = {
    'ncm-native-log', 'ncm-internal-bridge', 'ncm-win32-visual-rail',
    'gsmtc-qq-precise', 'gsmtc-kugou-precise', 'kugou-rail-local-master',
    'qq-startup-rail-validated', 'uia-lyric-row-text', 'qq-time-pair-validated',
}
_LIMBUS_H26_ACTIVE_PLAYER = ''
_LIMBUS_H26_OWNERSHIP_LOG_MONO = {}
_LIMBUS_H26_PANEL_INIT_PRE = ControlPanel.__init__
_LIMBUS_H26_GET_PLAYER_PIDS_PRE = LyricFetcher.get_player_pids
_LIMBUS_H26_QQ_DURATION_HINT_PRE = LyricFetcher.get_qq_ui_duration_hint
_LIMBUS_H26_UIA_POLL_PRE = AsyncPlayerUiPositionReader.poll
_LIMBUS_H26_BIND_TRACK_PRE = MediaSessionSync.bind_track
_LIMBUS_H26_AUTO_LOCAL_START_PRE = MediaSessionSync._start_auto_local_clock
_LIMBUS_H26_SNAPSHOT_PRE = MediaSessionSync.snapshot
_LIMBUS_H26_H25_VISUAL_PRE = MediaSessionSync._h25_poll_netease_safe_visual_clock
_LIMBUS_H26_NETEASE_INTERACTION_PRE = MediaSessionSync._netease_apply_verified_page_interaction


def _h26_set_active_player(name):
    global _LIMBUS_H26_ACTIVE_PLAYER
    _LIMBUS_H26_ACTIVE_PLAYER = str(name or '')
    return _LIMBUS_H26_ACTIVE_PLAYER


def _h26_active_player():
    return str(globals().get('_LIMBUS_H26_ACTIVE_PLAYER', '') or '')


def _h26_player_process_stems(player_name):
    name = str(player_name or '')
    return {
        'QQ音乐': {'qqmusic'},
        '网易云音乐': {'cloudmusic'},
        '酷狗音乐': {'kgmusic', 'kugou'},
        'Spotify': {'spotify'},
    }.get(name, set())


def _h26_process_stem(value):
    try:
        return os.path.splitext(os.path.basename(str(value or '').replace('\\', '/').lower()))[0]
    except Exception:
        return ''


def _h26_log_ownership_once(key, message, detail, interval_ms=5000.0):
    now = time.monotonic() * 1000.0
    last = float(_LIMBUS_H26_OWNERSHIP_LOG_MONO.get(str(key), 0.0) or 0.0)
    if now - last < float(interval_ms):
        return
    _LIMBUS_H26_OWNERSHIP_LOG_MONO[str(key)] = now
    try:
        write_error_log(message, detail=detail)
    except Exception:
        pass


def _h26_panel_init(self, *args, **kwargs):
    result = _LIMBUS_H26_PANEL_INIT_PRE(self, *args, **kwargs)
    try:
        _h26_set_active_player(self.player_combo.currentText())
        self.player_combo.currentTextChanged.connect(_h26_set_active_player)
    except Exception:
        pass
    return result


ControlPanel.__init__ = _h26_panel_init


def _h26_get_player_pids_player_owned(player_name=None, players=None):
    requested = str(player_name or '')
    active = _h26_active_player()
    if active and requested and _h26_player_process_stems(requested) and active != requested:
        _h26_log_ownership_once(
            f'pids:{active}:{requested}', 'H26跨播放器桌面进程探测已拒绝',
            f'selected_player={active} | requested_desktop={requested} | provider-search=network-only | win11-transport=unchanged')
        return []
    return _LIMBUS_H26_GET_PLAYER_PIDS_PRE(player_name, players)


LyricFetcher.get_player_pids = staticmethod(_h26_get_player_pids_player_owned)


def _h26_qq_duration_hint_player_owned(panel, purpose='manual-fetch'):
    try:
        selected = str(panel.player_combo.currentText() or '')
    except Exception:
        selected = _h26_active_player()
    if selected and selected != 'QQ音乐':
        _h26_log_ownership_once(
            f'qq-duration:{selected}:{purpose}', 'H26跨播放器QQ时长探测已拒绝',
            f'purpose={purpose} | selected_player={selected} | lyric-provider=QQ音乐 | qqmusic-ui-read=0 | ownership=player')
        return 0
    return _LIMBUS_H26_QQ_DURATION_HINT_PRE(panel, purpose)


LyricFetcher.get_qq_ui_duration_hint = staticmethod(_h26_qq_duration_hint_player_owned)


def _h26_uia_poll_player_owned(self, process_name, force=False):
    active = _h26_active_player()
    requested_stem = _h26_process_stem(process_name)
    expected = _h26_player_process_stems(active)
    builtins = {'qqmusic', 'cloudmusic', 'kgmusic', 'kugou'}
    if active and requested_stem in builtins and expected and requested_stem not in expected:
        _h26_log_ownership_once(
            f'uia:{active}:{requested_stem}', 'H26跨播放器UIA时钟探测已拒绝',
            f'selected_player={active} | requested_process={process_name} | desktop-read=0 | ownership=player')
        return {
            'position_ms': None, 'duration_ms': None, 'confidence': 0,
            'source': 'h26-cross-player-uia-blocked', 'detail': 'transport belongs to selected player',
            '_sample_seq': -1,
        }
    return _LIMBUS_H26_UIA_POLL_PRE(self, process_name, force=force)


AsyncPlayerUiPositionReader.poll = _h26_uia_poll_player_owned


def _h26_netease_win10_safe_profile(self=None):
    try:
        return bool(_h25_netease_safe_profile(self))
    except Exception:
        return False


def _h26_same_track_identity(song, artist, media_title, media_artist):
    try:
        if _clean_name(song) != _clean_name(media_title):
            return False
        if not str(artist or '').strip() or not str(media_artist or '').strip():
            return True
        ok, _alias = _artist_alias_match(artist, media_artist)
        return bool(ok)
    except Exception:
        return False


def _h26_refine_provisional_origin(sync, song, artist, legacy_position_ms):
    try:
        legacy = max(0, int(legacy_position_ms or 0))
    except Exception:
        legacy = 0
    try:
        state = _LIMBUS_H26_SNAPSHOT_PRE(sync) or {}
        process_name = str(getattr(sync, '_process_hint', '') or '')
        if not sync._source_matches_process_hint(str(state.get('media_source') or ''), process_name):
            return legacy
        if not _h26_same_track_identity(song, artist, state.get('media_title'), state.get('media_artist')):
            return legacy
        position_source = str(state.get('position_source') or '')
        if position_source not in H26_TRANSITION_STRONG_POSITION_SOURCES:
            return legacy
        if not bool(state.get('connected')) or str(state.get('status') or '').lower() not in ('playing', 'paused'):
            return legacy
        pos = state.get('position_ms')
        if pos is None:
            return legacy
        pos = float(pos)
        if not math.isfinite(pos) or pos < 0.0:
            return legacy
        duration = float(state.get('duration_ms') or 0.0)
        if duration > 0.0 and pos > duration + 1800.0:
            return legacy
        actual = max(0, int(round(pos)))
        if abs(actual - legacy) >= 350:
            _h26_log_ownership_once(
                f'transition:{_clean_name(song)}', 'H26自动切歌采用播放器真实位置',
                f'process={process_name} | song={song} | legacy_detection={legacy}ms | player_position={actual}ms | '
                f'source={position_source} | ownership=player | lyric-provider=non-authoritative', interval_ms=800.0)
        return actual
    except Exception:
        return legacy


def _h26_bind_track_player_owned(self, song, artist='', duration_ms=0, auto_provisional=False,
                                  initial_position_ms=0, netease_track_id=None, startup_existing=False):
    process_stem = self._process_stem(getattr(self, '_process_hint', ''))
    requested_ncm = netease_track_id
    if process_stem != 'cloudmusic' and requested_ncm not in (None, ''):
        _h26_log_ownership_once(
            f'ncm-id:{process_stem}', 'H26跨播放器网易云曲目ID已拒绝',
            f'process={getattr(self, "_process_hint", "")} | ncm_id={str(requested_ncm)[:32]} | ownership=player')
        requested_ncm = None
    refined_initial = initial_position_ms
    if bool(auto_provisional):
        if process_stem == 'cloudmusic' and _h26_netease_win10_safe_profile(self):
            refined_initial = 0
        else:
            refined_initial = _h26_refine_provisional_origin(self, song, artist, initial_position_ms)
    return _LIMBUS_H26_BIND_TRACK_PRE(
        self, song, artist, duration_ms,
        auto_provisional=auto_provisional,
        initial_position_ms=refined_initial,
        netease_track_id=requested_ncm,
        startup_existing=startup_existing,
    )


MediaSessionSync.bind_track = _h26_bind_track_player_owned


def _h26_start_auto_local_clock(self, initial_position_ms=0):
    # Win11 and every non-NetEase player delegate exactly to the accumulated H25 path.
    if self._process_stem(self._process_hint) == 'cloudmusic' and _h26_netease_win10_safe_profile(self):
        self._reset_auto_local_clock()
        now = time.monotonic() * 1000.0
        if now - float(getattr(self, '_h26_netease_unknown_log_mono', 0.0) or 0.0) >= 3000.0:
            self._h26_netease_unknown_log_mono = now
            try:
                write_error_log('H26网易云Win10临时时钟无证据禁用', detail=(
                    f'initial_hint={int(initial_position_ms or 0)}ms | position=none | '
                    'reason=no-player-owned-clock | win11-path=unchanged'))
            except Exception:
                pass
        return False
    return _LIMBUS_H26_AUTO_LOCAL_START_PRE(self, initial_position_ms)


MediaSessionSync._start_auto_local_clock = _h26_start_auto_local_clock


def _h26_snapshot(self):
    state = _LIMBUS_H26_SNAPSHOT_PRE(self) or {}
    if self._process_stem(self._process_hint) != 'cloudmusic' or not _h26_netease_win10_safe_profile(self):
        return state
    source = str(state.get('position_source') or '')
    if source not in H26_NETEASE_UNKNOWN_SOURCES:
        return state
    patched = dict(state)
    patched['position_ms'] = None
    patched['connected'] = False
    patched['sync_waiting'] = True
    patched['position_source'] = 'h26-ncm-unknown-no-player-evidence'
    patched.pop('visual_seek', None)
    now = time.monotonic() * 1000.0
    if now - float(getattr(self, '_h26_snapshot_unknown_log_mono', 0.0) or 0.0) >= 5000.0:
        self._h26_snapshot_unknown_log_mono = now
        try:
            write_error_log('H26网易云UNKNOWN端到端保持', detail=(
                f'blocked_source={source} | position=none | connected=0 | '
                'snapshot-to-renderer=fail-closed | win11-path=unchanged'))
        except Exception:
            pass
    return patched


MediaSessionSync.snapshot = _h26_snapshot


def _h26_netease_apply_verified_page_interaction(self, hit):
    if _h26_netease_win10_safe_profile(self) and isinstance(hit, dict):
        try:
            zone = self._netease_click_zone(int(hit.get('cx')), int(hit.get('cy')))
        except Exception:
            zone = None
        if zone == 'transport':
            self._h26_netease_visual_pending_map = {}
    return _LIMBUS_H26_NETEASE_INTERACTION_PRE(self, hit)


MediaSessionSync._netease_apply_verified_page_interaction = _h26_netease_apply_verified_page_interaction

def _h26_rgb_distance(a, b):
    return abs(int(a[0])-int(b[0])) + abs(int(a[1])-int(b[1])) + abs(int(a[2])-int(b[2]))


def _h26_netease_static_rail_candidates(self, frame, window_width):
    """Find long two-tone horizontal rails without requiring a large frame-to-frame motion.

    Candidate discovery alone has zero time authority.  Text separators and other long lines are
    allowed into this shortlist; only multi-sample wall-clock boundary motion can certify one.
    """
    if not isinstance(frame, dict) or not frame.get('data'):
        return []
    try:
        w, h = int(frame['w']), int(frame['h'])
        window_width = max(1.0, float(window_width or w))
    except Exception:
        return []
    if w < 160 or h < 8:
        return []
    rows = []
    for y in range(2, h-2, 2):
        edges = []
        for x in range(28, w-28, 4):
            try:
                left = self._kugou_visual_rgb(frame, x-14, y)
                right = self._kugou_visual_rgb(frame, x+14, y)
                sep = _h26_rgb_distance(left, right)
            except Exception:
                continue
            if sep >= 28:
                edges.append((sep, x))
        if not edges:
            continue
        edges.sort(reverse=True)
        for sep, x in edges[:4]:
            try:
                bounds = self._kugou_visual_infer_bounds(frame, x, y, window_width)
            except Exception:
                bounds = None
            if not bounds:
                continue
            gx0, gx1, gy, rail_w, color_sep = bounds
            if rail_w < max(180, int(window_width * 0.30)):
                continue
            ratio = (float(frame['x']) + float(x) - float(gx0)) / max(1.0, float(gx1-gx0))
            if ratio < 0.005 or ratio > 0.995:
                continue
            # Prefer wide, clearly two-tone, thin lower-transport structures. Proof later
            # decides time authority, so ranking is intentionally permissive.
            score = float(rail_w) + float(color_sep) * 1.6 + float(sep) * 0.5
            rows.append({
                'score': score, 'x0': float(gx0), 'x1': float(gx1), 'y': float(gy),
                'rail_w': float(rail_w), 'color_sep': int(color_sep),
                'boundary_x': float(frame['x']) + float(x),
            })
    # De-duplicate the same rail discovered on adjacent rows / neighboring edge samples.
    rows.sort(key=lambda r: float(r.get('score') or 0.0), reverse=True)
    out = []
    for row in rows:
        duplicate = False
        for prior in out:
            if (abs(row['y']-prior['y']) <= 5.0 and abs(row['x0']-prior['x0']) <= 28.0 and
                    abs(row['x1']-prior['x1']) <= 28.0):
                duplicate = True
                break
        if not duplicate:
            out.append(row)
        if len(out) >= int(H26_NETEASE_VISUAL_MAX_CANDIDATES):
            break
    return out


def _h26_netease_visual_proof_step(pending, observed, now_ms, x0, x1, y, duration_ms):
    """Certify a rail only after real forward motion; a perfectly static line cannot lock."""
    try:
        observed = float(observed); now_ms = float(now_ms); duration_ms = float(duration_ms)
        x0 = float(x0); x1 = float(x1); y = float(y); rail_w = max(1.0, x1-x0)
    except Exception:
        return None, False
    px_ms = duration_ms / max(1.0, rail_w)
    if isinstance(pending, dict):
        try:
            if now_ms - float(pending.get('last_mono') or now_ms) > float(H26_NETEASE_VISUAL_STALE_PROOF_MS):
                pending = None
        except Exception:
            pending = None
    if not isinstance(pending, dict):
        return ({'hits': 1, 'first_mono': now_ms, 'last_mono': now_ms,
                 'first_position': observed, 'last_position': observed,
                 'x0': x0, 'x1': x1, 'y': y, 'rail_w': rail_w}, False)
    try:
        same_geom = bool(
            abs(y-float(pending.get('y') or y)) <= 8.0 and
            abs(x0-float(pending.get('x0') or x0)) <= 42.0 and
            abs(x1-float(pending.get('x1') or x1)) <= 42.0
        )
        dt = max(1.0, now_ms-float(pending.get('last_mono') or now_ms))
        dp = observed-float(pending.get('last_position') or observed)
        step_tol = max(620.0, dt*0.95, px_ms*3.2)
        coherent = bool(same_geom and dp >= -max(180.0, px_ms*1.3) and dp <= dt+step_tol)
    except Exception:
        coherent = False
    if not coherent:
        return ({'hits': 1, 'first_mono': now_ms, 'last_mono': now_ms,
                 'first_position': observed, 'last_position': observed,
                 'x0': x0, 'x1': x1, 'y': y, 'rail_w': rail_w}, False)
    row = dict(pending)
    row['hits'] = int(row.get('hits') or 1) + 1
    row['last_mono'] = now_ms; row['last_position'] = observed
    row['x0'] = x0; row['x1'] = x1; row['y'] = y; row['rail_w'] = rail_w
    span = max(0.0, now_ms-float(row.get('first_mono') or now_ms))
    advance = observed-float(row.get('first_position') or observed)
    min_advance = max(140.0, min(950.0, px_ms*1.15))
    pace_tol = max(900.0, span*0.72, px_ms*4.2)
    proven = bool(
        int(row['hits']) >= int(H26_NETEASE_VISUAL_MIN_HITS) and
        span >= float(H26_NETEASE_VISUAL_MIN_SPAN_MS) and
        advance >= min_advance and abs(advance-span) <= pace_tol
    )
    return row, proven


def _h26_netease_visual_diag(self, phase, detail=''):
    now = time.monotonic() * 1000.0
    if now - float(getattr(self, '_h26_netease_visual_diag_mono', 0.0) or 0.0) < 5000.0:
        return
    self._h26_netease_visual_diag_mono = now
    try:
        write_error_log('H26网易云Win32视觉时钟等待', detail=(
            f'phase={phase} | {detail} | accessibility=0 | win10-safe=1'))
    except Exception:
        pass


def _h26_poll_netease_safe_visual_clock(self, status_hint='unknown'):
    if self._process_stem(self._process_hint) != 'cloudmusic' or not _h26_netease_win10_safe_profile(self):
        return _LIMBUS_H26_H25_VISUAL_PRE(self, status_hint)
    try:
        duration = float(self._uia_duration_ms or self._state.get('duration_ms') or 0.0)
    except Exception:
        duration = 0.0
    if duration <= 5000.0:
        _h26_netease_visual_diag(self, 'duration-unavailable', f'duration={int(duration)}')
        return None
    now = time.monotonic() * 1000.0
    track = str(self._track_key or '')
    if track != str(getattr(self, '_h26_netease_visual_track_key', '') or ''):
        self._h26_netease_visual_track_key = track
        self._h26_netease_visual_pending_map = {}
        self._h26_netease_visual_locked = False
        self._h26_netease_visual_anchor_position = None
        self._h26_netease_visual_anchor_mono = 0.0
        self._h25_netease_visual_bounds = None
        self._h25_netease_visual_y = None
        self._h25_netease_seek_seed = None

    seed = getattr(self, '_h25_netease_seek_seed', None)
    if isinstance(seed, dict) and now <= float(seed.get('until') or 0.0):
        seed_row = _h25_netease_visual_row(
            seed.get('position'), duration, seed.get('status') or 'playing',
            'ncm-win32-seek-intent-local', confidence=218,
            detail='H26 explicit click on learned physical rail; awaiting visual reconfirmation')
    else:
        seed_row = None
        if isinstance(seed, dict):
            self._h25_netease_seek_seed = None

    if str(status_hint or '').lower() == 'paused':
        anchor = getattr(self, '_h26_netease_visual_anchor_position', None)
        if anchor is not None and bool(getattr(self, '_h26_netease_visual_locked', False)):
            return _h25_netease_visual_row(anchor, duration, 'paused', 'ncm-win32-visual-rail', 242, 'H26 verified physical rail paused freeze')
        return seed_row

    last_sample = float(getattr(self, '_h26_netease_visual_last_sample_mono', 0.0) or 0.0)
    if now-last_sample < float(H25_NETEASE_VISUAL_SAMPLE_MS):
        if seed_row is not None:
            return seed_row
        anchor = getattr(self, '_h26_netease_visual_anchor_position', None)
        anchor_mono = float(getattr(self, '_h26_netease_visual_anchor_mono', 0.0) or 0.0)
        if anchor is not None and bool(getattr(self, '_h26_netease_visual_locked', False)) and now-anchor_mono <= float(H25_NETEASE_VISUAL_LOCAL_HOLD_MS):
            predicted = float(anchor)+max(0.0, now-anchor_mono)
            return _h25_netease_visual_row(predicted, duration, 'playing', 'ncm-win32-visual-local', 228, 'H26 short hold from verified physical rail')
        return None

    rect = _h25_netease_window_rect(self)
    if not rect:
        self._h26_netease_visual_last_sample_mono = now
        _h26_netease_visual_diag(self, 'no-window-rect')
        return seed_row
    frame = _h25_netease_capture_visual_strip(self, rect)
    self._h26_netease_visual_last_sample_mono = now
    if not frame:
        _h26_netease_visual_diag(self, 'capture-failed', f'rect={rect}')
        return seed_row
    try:
        ww = max(1.0, float(rect[2])-float(rect[0]))
    except Exception:
        ww = float(frame.get('w') or 1)
    candidates = _h26_netease_static_rail_candidates(self, frame, ww)
    if not candidates:
        self._h26_netease_visual_pending_map = {}
        _h26_netease_visual_diag(self, 'no-horizontal-rail', f'frame={int(frame.get("w") or 0)}x{int(frame.get("h") or 0)}')
        return seed_row

    pending_map = dict(getattr(self, '_h26_netease_visual_pending_map', {}) or {})
    next_map = {}
    locked = None
    for cand in candidates:
        x0, x1, y = float(cand['x0']), float(cand['x1']), float(cand['y'])
        boundary = float(cand['boundary_x'])
        ratio = max(0.0, min(1.0, (boundary-x0)/max(1.0, x1-x0)))
        observed = ratio*duration
        key = (int(round(y/4.0)), int(round(x0/24.0)), int(round(x1/24.0)))
        previous = pending_map.get(key)
        p, proven = _h26_netease_visual_proof_step(previous, observed, now, x0, x1, y, duration)
        if p is not None:
            p['score'] = float(cand.get('score') or 0.0)
            p['ratio'] = ratio
            p['color_sep'] = int(cand.get('color_sep') or 0)
            next_map[key] = p
        if proven and (locked is None or float(cand.get('score') or 0.0) > float(locked[0])):
            locked = (float(cand.get('score') or 0.0), observed, cand, p)
    self._h26_netease_visual_pending_map = next_map
    if locked is None:
        _h26_netease_visual_diag(self, 'proof-pending', f'candidates={len(candidates)} | proofs={len(next_map)}')
        return seed_row

    _score, observed, cand, proof = locked
    previous_anchor = getattr(self, '_h26_netease_visual_anchor_position', None)
    previous_mono = float(getattr(self, '_h26_netease_visual_anchor_mono', 0.0) or 0.0)
    predicted = None
    if previous_anchor is not None and previous_mono > 0.0:
        predicted = float(previous_anchor)+max(0.0, now-previous_mono)
    self._h26_netease_visual_locked = True
    self._h26_netease_visual_anchor_position = float(observed)
    self._h26_netease_visual_anchor_mono = now
    self._h25_netease_visual_locked = True
    self._h25_netease_visual_anchor_position = float(observed)
    self._h25_netease_visual_anchor_mono = now
    self._h25_netease_visual_bounds = (float(cand['x0']), float(cand['x1']))
    self._h25_netease_visual_y = float(cand['y'])
    self._h25_netease_seek_seed = None
    seek_recent = now <= float(getattr(self, '_h25_netease_seek_intent_until_mono', 0.0) or 0.0)
    if predicted is not None and abs(float(observed)-float(predicted)) >= 1800.0 and seek_recent:
        try:
            self._mark_seek_burst(observed, 'ncm-win32-visual-rail', now)
            write_error_log('H26网易云Win32视觉Seek确认', detail=(
                f'predicted={int(round(predicted))}ms | observed={int(round(observed))}ms | '
                f'delta={int(round(observed-predicted))}ms | rail=({int(cand["x0"])},{int(cand["y"])})->({int(cand["x1"])},{int(cand["y"])}) | '
                'hard-reanchor=1 | accessibility=0'))
        except Exception:
            pass
    try:
        write_error_log('H26网易云Win32视觉时钟已锁定', detail=(
            f'position={int(round(observed))}ms | duration={int(round(duration))}ms | ratio={float(proof.get("ratio") or 0.0):.5f} | '
            f'rail=({int(cand["x0"])},{int(cand["y"])})->({int(cand["x1"])},{int(cand["y"])}) | '
            f'hits={int(proof.get("hits") or 0)} | span={int(now-float(proof.get("first_mono") or now))}ms | '
            'static-line-lock=forbidden | screen-readonly=1 | accessibility=0'))
    except Exception:
        pass
    return _h25_netease_visual_row(observed, duration, 'playing', 'ncm-win32-visual-rail', 244, 'H26 static-rail geometry + real forward-motion proof')


MediaSessionSync._h25_poll_netease_safe_visual_clock = _h26_poll_netease_safe_visual_clock


# H16 UX runtime wiring / real-machine closure ---------------------------------
# Presentation-only closure over H12/H15.  H15 real-machine testing showed that
# several controls existed in the panel but did not own the full runtime lifecycle:
# cover-follow could be overwritten by the next style resolve, continuous weight
# could collapse back to the legacy bold checkbox on lyric restart, and exit effects
# inherited a fade lifetime that could be too short to perceive.  Keep all player
# clocks / provider identity / seek authority untouched.
H16_FONT_SIZE_MIN_PT = 6
H16_FONT_SIZE_MAX_PT = 300
H16_EXIT_VISIBLE_MIN_MS = 520.0
H16_EXIT_PRESSURE_MIN_MS = 380.0
H16_EXIT_MAX_MS = 6000.0
H16_COVER_RETRY_SEC = (2.0, 6.0, 18.0)

_LIMBUS_H16_CONTROL_INIT_PRE = ControlPanel.__init__
_LIMBUS_H16_RESOLVE_STYLE_PRE = ControlPanel._resolved_active_visual_style
_LIMBUS_H16_FADING_BEGIN_PRE = FadingLine.begin_fade
_LIMBUS_H16_FADING_DRAW_PRE = FadingLine.draw


def _h16_exit_duration_ms(row):
    try:
        speed=max(1.0,float(getattr(row,'fade_speed',12) or 12))
    except Exception:
        speed=12.0
    cutoff=max(0.0,min(254.0,float(FADE_VISUAL_ALPHA_CUTOFF)))
    nominal=max(30.0,((255.0-cutoff)/speed)*30.0)
    effect=str(getattr(row,'exit_effect','fade') or 'fade')
    # Shrink should feel brisk but still be a real animation, never an instant pop.
    if effect=='shrink':
        nominal*=0.88
    base=max(float(H16_EXIT_VISIBLE_MIN_MS),nominal)
    try:
        expedite=max(1.0,float(getattr(row,'_fade_expedite_factor',1.0) or 1.0))
    except Exception:
        expedite=1.0
    duration=base/min(expedite,4.0)
    return max(float(H16_EXIT_PRESSURE_MIN_MS),min(float(H16_EXIT_MAX_MS),duration))


def _h16_begin_fade(self):
    out=_LIMBUS_H16_FADING_BEGIN_PRE(self)
    now=time.monotonic()*1000.0
    self._h16_exit_started_mono=now
    self._h16_exit_last_mono=now
    self._h16_exit_progress=0.0
    return out
FadingLine.begin_fade=_h16_begin_fade


def _h16_fading_update(self):
    effect=str(getattr(self,'exit_effect','fade') or 'fade')
    if effect=='instant':
        self.release_render_resources(); self._h16_exit_progress=1.0; return False
    now=time.monotonic()*1000.0
    started=float(getattr(self,'_h16_exit_started_mono',0.0) or 0.0)
    if started<=0.0:
        started=now; self._h16_exit_started_mono=now; self._h16_exit_last_mono=now
    last=float(getattr(self,'_h16_exit_last_mono',now) or now)
    step=max(0.0,min(120.0,now-last)); self._h16_exit_last_mono=now
    duration=_h16_exit_duration_ms(self)
    progress=max(0.0,min(1.0,(now-started)/max(1.0,duration)))
    self._h16_exit_progress=progress
    # Keep the established alpha-based draw backend, but drive it from a bounded
    # presentation lifetime instead of timer-tick debt.  A busy GUI can skip frames,
    # yet any frames that do render still show a deterministic effect progression.
    self._fade_alpha_float=max(0.0,255.0*(1.0-progress))
    self.alpha=int(max(0,min(255,round(self._fade_alpha_float))))
    if step>0.0:
        self.y-=float(getattr(self,'rise_speed',0.0) or 0.0)*(step/30.0)
    if self.alpha>int(FADE_SHAKE_FREEZE_ALPHA):
        try: self._update_shake_motion()
        except Exception: pass
    if progress>=1.0 or self.alpha<=int(FADE_VISUAL_ALPHA_CUTOFF):
        self.release_render_resources(); return False
    return True
FadingLine.update=_h16_fading_update


def _h16_cover_artist_ok(wanted, row_artists):
    wanted=str(wanted or '').strip()
    if not wanted: return True
    names=[]
    for item in list(row_artists or []):
        if isinstance(item,dict): names.append(str(item.get('name') or '').strip())
        else: names.append(str(item or '').strip())
    joined=', '.join(x for x in names if x)
    if not joined: return False
    try:
        return bool(_artist_alias_match(wanted,joined)[0])
    except Exception:
        def norm(x): return re.sub(r'\W+','',str(x or '').casefold())
        w=norm(wanted)
        return any(bool(n) and (n in w or w in n) for n in map(norm,names))


def _h16_choose_cover_row(rows,song,artist='',preferred_id=''):
    rows=[x for x in list(rows or []) if isinstance(x,dict)]
    pid=str(preferred_id or '').strip()
    if pid:
        for row in rows:
            if str(row.get('id') or '').strip()==pid:
                return row
    def norm(x): return re.sub(r'\W+','',str(x or '').casefold())
    target=norm(song)
    exact=[]
    for row in rows:
        if target and norm(row.get('name'))==target:
            exact.append(row)
    for row in exact:
        artists=row.get('artists') if isinstance(row.get('artists'),list) else row.get('ar')
        if _h16_cover_artist_ok(artist,artists): return row
    return exact[0] if exact and not artist else None


def _h16_cover_pic_url(row):
    if not isinstance(row,dict): return ''
    album=row.get('album') if isinstance(row.get('album'),dict) else row.get('al')
    url=str((album or {}).get('picUrl') or '').strip()
    if url.startswith('http://'):
        url='https://'+url[len('http://'):]
    return url if url.startswith('https://') else ''


def _h16_cover_color_from_image(image):
    if image is None or image.isNull(): return ''
    q=image.scaled(32,32,Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
    rs=gs=bs=n=0
    for y in range(q.height()):
        for x in range(q.width()):
            c=QColor(q.pixel(x,y)); mx=max(c.red(),c.green(),c.blue()); mn=min(c.red(),c.green(),c.blue())
            if mx<35 or mx>245 or mx-mn<18: continue
            rs+=c.red(); gs+=c.green(); bs+=c.blue(); n+=1
    if not n: return ''
    c=QColor(rs//n,gs//n,bs//n); h,sat,val,_=c.getHsv(); c.setHsv(h,max(120,sat),max(175,min(235,val)))
    return c.name()


def _h16_cover_tick(panel):
    if not bool(getattr(panel,'_h12_cover_follow',False)): return
    song=str(getattr(panel,'_loaded_song','') or '').strip(); artist=str(getattr(panel,'_loaded_artist','') or '').strip()
    key=panel._track_identity(song,artist)
    if not song or not key: return
    cache=getattr(panel,'_h16_cover_cache',{}) or {}
    if key in cache:
        applied=getattr(panel,'_h12_cover_applied',None)
        if not applied or applied[0]!=key or str(applied[1])!=str(cache[key]):
            panel._h12_cover_result=(key,str(cache[key]))
        return
    now=time.monotonic()
    retry=dict(getattr(panel,'_h16_cover_retry',{}) or {})
    state=retry.get(key) or (0,0.0)
    if now<float(state[1] or 0.0): return
    active=dict(getattr(panel,'_h17_cover_active_requests',{}) or {})
    if key in active: return
    serial=int(getattr(panel,'_h17_cover_request_serial',0) or 0)+1
    panel._h17_cover_request_serial=serial
    active[key]=serial; panel._h17_cover_active_requests=active
    meta=dict(getattr(panel,'_active_lyric_provider_meta',{}) or {})
    preferred_id=str(meta.get('netease_song_id') or '').strip()
    def work():
        color=''; err=''
        try:
            headers={'User-Agent':'Mozilla/5.0'}
            queries=[f'{song} {artist}'.strip(),song]
            seen=set(); rows=[]
            for query in queries:
                if query in seen: continue
                seen.add(query)
                r=requests.post('https://music.163.com/api/search/get/web',data={'s':query,'type':1,'limit':8},headers=headers,timeout=4)
                r.raise_for_status(); rows=((r.json().get('result') or {}).get('songs') or [])
                if _h16_choose_cover_row(rows,song,artist,preferred_id): break
            hit=_h16_choose_cover_row(rows,song,artist,preferred_id)
            url=_h16_cover_pic_url(hit)
            if not url: raise RuntimeError('cover-not-found')
            image_response=requests.get(url,headers=headers,timeout=4); image_response.raise_for_status()
            q=QImage.fromData(image_response.content); color=_h16_cover_color_from_image(q)
            if not color: raise RuntimeError('cover-color-empty')
        except Exception as exc:
            err=f'{type(exc).__name__}: {exc}'
        # Multiple tracks may have cover workers alive at once after a fast switch.  Publish
        # every result into a queue and tag it with the exact per-key request serial so an
        # older worker can never overwrite/retire a newer request.
        try:
            panel._h17_cover_results.put((str(key),int(serial),str(color),str(err)))
        except Exception:
            pass
    threading.Thread(target=work,name='LimbusLyric-H16Cover',daemon=True).start()

def _h16_resolve_style(self):
    font,text_color,glow_color=_LIMBUS_H16_RESOLVE_STYLE_PRE(self)
    style=dict(getattr(self,'_active_song_style',{}) or {})
    if 'font_bold' not in style:
        try: font.setWeight(max(1,min(99,int(getattr(self,'_h12_font_weight',75)))))
        except Exception: pass
    try:
        key=self._track_identity(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist',''))
        cached=getattr(self,'_h12_cover_applied',None)
        if bool(getattr(self,'_h12_cover_follow',False)) and cached and cached[0]==key and not style.get('text_color'):
            c=QColor(str(cached[1] or ''))
            if c.isValid(): text_color=c
    except Exception: pass
    return font,text_color,glow_color
ControlPanel._resolved_active_visual_style=_h16_resolve_style


def _h16_poll_runtime(panel):
    ready_for_live=[]
    q=getattr(panel,'_h17_cover_results',None)
    if q is not None:
        while True:
            try: result=q.get_nowait()
            except queue.Empty: break
            except Exception: break
            try: key,serial,color,err=result
            except Exception: continue
            key=str(key); serial=int(serial or 0); color=str(color or ''); err=str(err or '')
            active=dict(getattr(panel,'_h17_cover_active_requests',{}) or {})
            # A result is authoritative only for the request serial still registered for
            # this track. Stale completions are harmlessly discarded.
            if int(active.get(key,0) or 0)!=serial:
                continue
            active.pop(key,None); panel._h17_cover_active_requests=active
            if color:
                cache=dict(getattr(panel,'_h16_cover_cache',{}) or {}); cache[key]=color; panel._h16_cover_cache=cache
                retry=dict(getattr(panel,'_h16_cover_retry',{}) or {}); retry.pop(key,None); panel._h16_cover_retry=retry
                current=panel._track_identity(getattr(panel,'_loaded_song',''),getattr(panel,'_loaded_artist',''))
                if str(current)==key:
                    panel._h12_cover_result=(str(key),str(color)); ready_for_live.append((key,color))
                try: write_error_log('H17封面跟色就绪',detail=f'key={key} | serial={serial} | color={color} | ownership=style-resolver')
                except Exception: pass
            else:
                retry=dict(getattr(panel,'_h16_cover_retry',{}) or {}); count=int((retry.get(key) or (0,0))[0])+1
                delay=float(H16_COVER_RETRY_SEC[min(count-1,len(H16_COVER_RETRY_SEC)-1)])
                retry[key]=(count,time.monotonic()+delay); panel._h16_cover_retry=retry
                try: write_error_log('H17封面跟色重试',detail=f'key={key} | serial={serial} | attempt={count} | retry={delay:.0f}s | error={err}')
                except Exception: pass
    # H12/H15 poll applies immutable async presentation results on the UI thread.
    _h12_poll_async(panel)
    try:
        current=panel._track_identity(getattr(panel,'_loaded_song',''),getattr(panel,'_loaded_artist',''))
        if any(str(key)==str(current) and color for key,color in ready_for_live):
            panel._apply_active_visual_style_live(reason='h17-cover-ready')
    except Exception: pass

def _h16_control_init(self,*args,**kwargs):
    _LIMBUS_H16_CONTROL_INIT_PRE(self,*args,**kwargs)
    self._h16_cover_cache={}; self._h16_cover_retry={}; self._h17_cover_active_requests={}; self._h17_cover_request_serial=0; self._h17_cover_results=queue.SimpleQueue()
    # QSpinBox remains keyboard-editable; enlarge the safe typographic range and restore the
    # raw persisted value after the legacy 100pt maximum had a chance to clamp it on startup.
    try:
        saved=int((load_all_config().get('settings') or {}).get('font_size',self.font_size.value()) or self.font_size.value())
        self.font_size.blockSignals(True); self.font_size.setRange(H16_FONT_SIZE_MIN_PT,H16_FONT_SIZE_MAX_PT); self.font_size.setKeyboardTracking(False); self.font_size.setValue(max(H16_FONT_SIZE_MIN_PT,min(H16_FONT_SIZE_MAX_PT,saved))); self.font_size.blockSignals(False)
        self.font_size.setSuffix(' pt'); self.font_size.setToolTip('可直接键盘输入 6～300 pt；按 Enter 或离开输入框后应用。')
        def font_size_changed(_value):
            try:
                if getattr(self,'_is_started',False) and getattr(self,'_loaded_track_key',''): self._apply_active_visual_style_live(reason='h16-font-size')
                if hasattr(self,'font_inline_preview'):
                    f=QFont(self.font_inline_preview.font()); f.setPointSize(max(6,min(72,int(self.font_size.value())))); self.font_inline_preview.setFont(f)
                if getattr(self,'_settings_loaded',False): self._schedule_config_save()
            except Exception as exc: write_error_log('H16字体大小实时应用失败',exc)
        self.font_size.valueChanged.connect(font_size_changed)
    except Exception as exc: write_error_log('H16字体大小输入初始化失败',exc)
    try:
        for label in self.findChildren(QLabel):
            if str(label.text() or '').strip()=='桌面同时字幕：':
                label.setText('清晰保留字幕：'); label.setToolTip('限制当前字幕 + 仍完整清晰的历史字幕数量；退场动画是独立过渡层，可短暂额外存在。')
        self.visible_subtitle_slider.setToolTip('1～6 条清晰字幕容量。增加后从后续换行逐步填满；正在退场的旧句不占清晰容量。')
        self.visible_subtitle_slider.valueChanged.connect(lambda _v: self._schedule_config_save() if getattr(self,'_settings_loaded',False) else None)
    except Exception: pass
    try:
        self.h12_exit_combo.setToolTip('除“直接消失”外，退场效果拥有独立可感知生命周期；不会通过改变播放器时间来制造动画。')
        def exit_changed(_i):
            effect=str(self.h12_exit_combo.currentData() or 'fade')
            for item in list(getattr(self.lyric_window,'history_lines',[]) or [])+list(getattr(self.lyric_window,'fading_lines',[]) or []):
                try: item.exit_effect=effect
                except Exception: pass
        self.h12_exit_combo.currentIndexChanged.connect(exit_changed)
    except Exception: pass
    try:
        def cover_mutual(on):
            if not on: return
            if hasattr(self,'random_color_check') and self.random_color_check.isChecked(): self.random_color_check.setChecked(False)
            self._h16_cover_retry.pop(self._track_identity(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist','')),None)
            self._h17_cover_active_requests.pop(self._track_identity(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist','')),None)
            self._apply_song_style_for_track(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist',''),getattr(self,'_loaded_player',''))
            try: self._apply_active_visual_style_live(reason='h16-cover-on')
            except Exception: pass
        self.h12_cover_check.toggled.connect(cover_mutual)
        if hasattr(self,'random_color_check'):
            self.random_color_check.toggled.connect(lambda on: self.h12_cover_check.setChecked(False) if on and self.h12_cover_check.isChecked() else None)
            if self.h12_cover_check.isChecked() and self.random_color_check.isChecked():
                self.random_color_check.setChecked(False)
        self.h12_cover_check.setToolTip('从当前歌曲封面提取高辨识度主色作为歌词文字色；与“每首歌安全随机颜色”互斥，单曲DIY颜色优先。')
    except Exception as exc: write_error_log('H16封面跟色互斥初始化失败',exc)
    # Replace the H12 timer callbacks after construction. Timers themselves are retained;
    # only presentation polling/cover lookup changes.
    try:
        self._h12_async_timer.timeout.disconnect(); self._h12_async_timer.timeout.connect(lambda:_h16_poll_runtime(self))
        self._h12_cover_timer.timeout.disconnect(); self._h12_cover_timer.timeout.connect(lambda:_h16_cover_tick(self))
    except Exception as exc: write_error_log('H16显示扩展定时器接线失败',exc)
    try:
        self._apply_song_style_for_track(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist',''),getattr(self,'_loaded_player',''))
        if getattr(self,'_is_started',False): self._apply_active_visual_style_live(reason='h16-init')
    except Exception: pass
ControlPanel.__init__=_h16_control_init


# H18 liveness corroboration / false-dead closure ------------------------------
# H10F4 user logs from 2026-08-28 showed a second failure mode beyond H11's hung
# Toolhelp32 calls: Toolhelp can also return a *fast false negative* for a player
# that becomes positively visible a few seconds later.  A single OS enumeration
# mechanism must therefore never create immediate player-dead authority.
#
# H18 keeps death conservative without weakening stale-data guards:
#   * a fast Toolhelp=False must be corroborated by the independent bounded tasklist path;
#   * a newly selected/started player gets a short negative-only grace period;
#   * corroborated negative evidence must persist for a minimum dwell before False is
#     published to H11's existing multi-confirmation state machine;
#   * a fresh, strict source-affine GSMTC session in playing/paused state may veto death
#     and may rescue UNKNOWN -> ALIVE for consumers, but it can never turn a confirmed
#     process death into ALIVE by itself.
H18_LIVENESS_EPOCH_NEGATIVE_GRACE_MS = 9000.0
H18_LIVENESS_NEGATIVE_DWELL_MS = 1800.0
H18_GSMTC_PRESENCE_TTL_MS = 1800.0
_LIMBUS_H18_RESET_LIVENESS_PRE = MediaSessionSync._reset_player_liveness_epoch
_LIMBUS_H18_CHOOSE_SESSION_PRE = MediaSessionSync._choose_session
_LIMBUS_H18_BOUNDED_PROBE_PRE = _limbus_bounded_player_liveness_probe
_LIMBUS_H18_LIVENESS_SNAPSHOT_PRE = MediaSessionSync._player_liveness_snapshot


def _limbus_h18_reset_liveness_epoch(self, process_stem):
    out = _LIMBUS_H18_RESET_LIVENESS_PRE(self, process_stem)
    try:
        self._h18_liveness_epoch_mono = time.monotonic() * 1000.0
        self._h18_liveness_negative_since_mono = 0.0
        self._h18_liveness_negative_stem = self._process_stem(process_stem)
        self._h18_gsmtc_presence = None
    except Exception:
        pass
    return out


MediaSessionSync._reset_player_liveness_epoch = _limbus_h18_reset_liveness_epoch


def _limbus_h18_note_gsmtc_presence(self, session):
    """Record only strict, process-affine, currently active GSMTC presence.

    This is intentionally *not* media identity.  It is a short-lived existence witness used
    only to veto false-dead and rescue UNKNOWN.  A stale/stopped/global-current session is
    never accepted.
    """
    try:
        stem = self._process_stem(self._process_hint)
        if stem not in ('cloudmusic', 'qqmusic', 'kgmusic') or session is None:
            return False
        source = str(getattr(session, 'source_app_user_model_id', '') or '')
        if not self._source_matches_process_hint(source, self._process_hint):
            return False
        # Do not issue a second GSMTC COM playback query here: _poll_loop already reads
        # playback info immediately after _choose_session().  Presence uses the already-public
        # transport state plus strict session affinity, avoiding extra provider-thread latency.
        try:
            with self._lock:
                status = str(self._state.get('status', 'unknown') or 'unknown').lower()
        except Exception:
            status = str(getattr(self, '_state', {}).get('status', 'unknown') or 'unknown').lower()
        if status not in ('playing', 'paused'):
            return False
        row = {
            'stem': stem,
            'source': source,
            'status': status,
            'mono': time.monotonic() * 1000.0,
        }
        try:
            with self._player_liveness_lock:
                self._h18_gsmtc_presence = row
        except Exception:
            self._h18_gsmtc_presence = row
        return True
    except Exception:
        return False


def _limbus_h18_gsmtc_presence_snapshot(self, process_stem):
    stem = self._process_stem(process_stem)
    try:
        with self._player_liveness_lock:
            row = dict(getattr(self, '_h18_gsmtc_presence', None) or {})
    except Exception:
        row = dict(getattr(self, '_h18_gsmtc_presence', None) or {})
    now = time.monotonic() * 1000.0
    age = now - float(row.get('mono') or 0.0) if row else 10**9
    fresh = bool(
        row and str(row.get('stem') or '') == stem and
        str(row.get('status') or '') in ('playing', 'paused') and
        0.0 <= age <= float(H18_GSMTC_PRESENCE_TTL_MS)
    )
    return {
        'fresh': fresh,
        'age_ms': age,
        'stem': str(row.get('stem') or ''),
        'status': str(row.get('status') or ''),
        'source': str(row.get('source') or ''),
    }


def _limbus_h18_choose_session(self, manager):
    session = _LIMBUS_H18_CHOOSE_SESSION_PRE(self, manager)
    if session is not None:
        _limbus_h18_note_gsmtc_presence(self, session)
    return session


MediaSessionSync._choose_session = _limbus_h18_choose_session


def _limbus_h18_negative_gate(self, stem, probe_source):
    """Return True only when a corroborated negative is old enough to count as death."""
    now = time.monotonic() * 1000.0
    presence = _limbus_h18_gsmtc_presence_snapshot(self, stem)
    if bool(presence.get('fresh')):
        self._h18_liveness_negative_since_mono = 0.0
        self._h18_liveness_negative_stem = stem
        try:
            write_error_log('播放器存活假死否决', detail=(
                f'process={stem} | source={probe_source} | gsm_source={presence.get("source","")} | '
                f'gsm_status={presence.get("status","")} | age={float(presence.get("age_ms") or 0.0):.1f}ms | '
                'action=keep-unknown/no-dead-streak'))
        except Exception:
            pass
        return False

    epoch = float(getattr(self, '_h18_liveness_epoch_mono', 0.0) or 0.0)
    if epoch <= 0.0:
        self._h18_liveness_epoch_mono = now
        epoch = now
    if now - epoch < float(H18_LIVENESS_EPOCH_NEGATIVE_GRACE_MS):
        self._h18_liveness_negative_since_mono = 0.0
        self._h18_liveness_negative_stem = stem
        return False

    neg_stem = str(getattr(self, '_h18_liveness_negative_stem', '') or '')
    neg_since = float(getattr(self, '_h18_liveness_negative_since_mono', 0.0) or 0.0)
    if neg_stem != stem or neg_since <= 0.0:
        self._h18_liveness_negative_stem = stem
        self._h18_liveness_negative_since_mono = now
        return False
    return bool(now - neg_since >= float(H18_LIVENESS_NEGATIVE_DWELL_MS))


def _limbus_h18_bounded_player_liveness_probe(self, stem):
    stem = self._process_stem(stem)
    result, source = _LIMBUS_H18_BOUNDED_PROBE_PRE(self, stem)
    if result is True:
        self._h18_liveness_negative_since_mono = 0.0
        self._h18_liveness_negative_stem = stem
        return True, source
    if result is None:
        return None, source

    # H11's bounded helper intentionally trusted a fast Toolhelp=False.  H18 requires an
    # independent bounded observation before such a result is even eligible to count toward
    # the existing dead-streak state machine.
    if str(source) == 'toolhelp':
        corroborated = _limbus_liveness_tasklist_probe(stem)
        if corroborated is True:
            self._h18_liveness_negative_since_mono = 0.0
            self._h18_liveness_negative_stem = stem
            try:
                write_error_log('播放器存活假阴性纠正', detail=(
                    f'process={stem} | toolhelp=0 | tasklist=1 | action=alive | gui-block=0'))
            except Exception:
                pass
            return True, 'tasklist-corroborates-alive'
        if corroborated is None:
            # One negative mechanism plus one unavailable mechanism is inconclusive.
            return None, 'unknown-after-toolhelp-false'
        source = 'toolhelp+tasklist-negative'

    if not _limbus_h18_negative_gate(self, stem, source):
        return None, f'{source}+negative-grace'
    return False, f'{source}+corroborated-dwell'


_limbus_bounded_player_liveness_probe = _limbus_h18_bounded_player_liveness_probe


def _limbus_h18_player_liveness_snapshot(self, process_stem=None):
    snap = dict(_LIMBUS_H18_LIVENESS_SNAPSHOT_PRE(self, process_stem) or {})
    # Positive-only rescue. Never rewrite an explicit confirmed False here; the probe-side
    # veto is responsible for preventing fresh active-session evidence from becoming False.
    if snap.get('alive') is None:
        stem = self._process_stem(process_stem or self._process_hint)
        presence = _limbus_h18_gsmtc_presence_snapshot(self, stem)
        if bool(presence.get('fresh')):
            snap['alive'] = True
            snap['presence_rescue'] = 'strict-active-gsmtc'
            snap['presence_age_ms'] = float(presence.get('age_ms') or 0.0)
    return snap


MediaSessionSync._player_liveness_snapshot = _limbus_h18_player_liveness_snapshot

# H19 cover-follow + mirrored exit closure -------------------------------------
# Real-machine H18 logs proved two presentation defects:
#   * the legacy NetEase search payload normally exposes album.picId but not album.picUrl,
#     so the H16/H17 cover worker could match a song and still retry cover-not-found forever;
#   * H12 exit effects were unrelated wipe/shrink tricks rather than time-reversed versions
#     of the selected entrance motion.  H19 fixes both without touching player clocks/seek.
H19_EXIT_EFFECT_VALUES = (
    'mirror', 'reverse_soft', 'reverse_typewriter', 'reverse_rise',
    'reverse_slide', 'reverse_bounce', 'fade', 'instant'
)
H19_EXIT_MIN_MS = 620.0
H19_EXIT_MAX_MS = 1200.0
# Cover metadata outages should not hammer the provider forever. H16/H17 stopped at an
# 18-second repeating retry; H19 keeps the fast first retries, then backs off to 2 minutes.
H16_COVER_RETRY_SEC = (2.0, 6.0, 18.0, 30.0, 60.0, 120.0)

_LIMBUS_H19_CONTROL_INIT_PRE = ControlPanel.__init__
_LIMBUS_H19_MAKE_HISTORY_PRE = LyricWindow._make_history_line
_LIMBUS_H19_FADING_UPDATE_PRE = FadingLine.update
_LIMBUS_H19_FADING_DRAW_PRE = FadingLine.draw
_LIMBUS_H19_COVER_PIC_PRE = _h16_cover_pic_url
_LIMBUS_H19_COVER_ARTIST_PRE = _h16_cover_artist_ok


def _h19_https_url(url):
    url=str(url or '').strip()
    if url.startswith('http://'):
        url='https://'+url[len('http://'):]
    return url if url.startswith('https://') else ''


def _h19_cover_artist_ok(wanted, row_artists):
    """Prefer the primary requested artist while tolerating provider feature-list differences."""
    wanted=str(wanted or '').strip()
    if not wanted:
        return True
    names=[]
    for item in list(row_artists or []):
        if isinstance(item,dict): names.append(str(item.get('name') or '').strip())
        else: names.append(str(item or '').strip())
    names=[x for x in names if x]
    if not names:
        return False
    try:
        if bool(_artist_alias_match(wanted,', '.join(names))[0]):
            return True
    except Exception:
        pass
    def norm(x): return re.sub(r'[^0-9a-z\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]+','',str(x or '').casefold())
    # UI metadata often contains featured/vocal artists that the NetEase search row omits.
    # The first artist is the stable primary identity; require that one rather than requiring
    # every comma-separated contributor to be present in the search result.
    wanted_parts=[x.strip() for x in re.split(r'[,，/&、;；|]+',wanted) if x.strip()]
    primary=norm(wanted_parts[0] if wanted_parts else wanted)
    actual=[norm(x) for x in names]
    if primary and any(n and (n==primary or n in primary or primary in n) for n in actual):
        return True
    return bool(_LIMBUS_H19_COVER_ARTIST_PRE(wanted,row_artists))


# _h16_choose_cover_row resolves this global at call time, so the safer multi-artist matcher
# automatically applies to the existing H17 per-track request/queue machinery.
_h16_cover_artist_ok = _h19_cover_artist_ok


def _h19_cover_pic_url(row):
    """Resolve a cover URL from a search row, enriching the old search payload when needed."""
    direct=_h19_https_url(_LIMBUS_H19_COVER_PIC_PRE(row))
    if direct:
        return direct
    if not isinstance(row,dict):
        return ''
    headers={
        'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/142 Safari/537.36',
        'Referer':'https://music.163.com/'
    }
    sid=str(row.get('id') or '').strip()
    if sid:
        try:
            r=requests.get(
                'https://music.163.com/api/song/detail/',
                params={'id':sid,'ids':f'[{sid}]'}, headers=headers, timeout=4
            )
            r.raise_for_status(); payload=r.json() if hasattr(r,'json') else {}
            songs=(payload or {}).get('songs') or ((payload or {}).get('result') or {}).get('songs') or []
            if songs and isinstance(songs[0],dict):
                album=songs[0].get('album') if isinstance(songs[0].get('album'),dict) else songs[0].get('al')
                url=_h19_https_url((album or {}).get('picUrl') if isinstance(album,dict) else '')
                if url:
                    try: write_error_log('H19封面地址补全',detail=f'song_id={sid} | source=song-detail')
                    except Exception: pass
                    return url
        except Exception as exc:
            try: write_error_log('H19封面歌曲详情补全失败',exc,detail=f'song_id={sid}')
            except Exception: pass
    album=row.get('album') if isinstance(row.get('album'),dict) else row.get('al')
    aid=str((album or {}).get('id') or '').strip() if isinstance(album,dict) else ''
    if aid:
        try:
            r=requests.get(f'https://music.163.com/api/album/{aid}/',headers=headers,timeout=4)
            r.raise_for_status(); payload=r.json() if hasattr(r,'json') else {}
            full=(payload or {}).get('album') or payload or {}
            url=_h19_https_url(full.get('picUrl') if isinstance(full,dict) else '')
            if url:
                try: write_error_log('H19封面地址补全',detail=f'album_id={aid} | source=album-detail')
                except Exception: pass
                return url
        except Exception as exc:
            try: write_error_log('H19封面专辑详情补全失败',exc,detail=f'album_id={aid}')
            except Exception: pass
    return ''


# The H16 worker calls this global inside its daemon thread.  Detail enrichment therefore never
# adds network work to the UI thread, while H17's request serial/queue race protection is retained.
_h16_cover_pic_url = _h19_cover_pic_url


def _h19_cover_color_from_image(image):
    """Pick a visible dominant accent instead of averaging every saturated cover pixel together."""
    if image is None or image.isNull():
        return ''
    q=image.scaled(40,40,Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
    buckets={}
    fallback=[]
    for y in range(q.height()):
        for x in range(q.width()):
            c=QColor(q.pixel(x,y)); r,g,b=c.red(),c.green(),c.blue()
            h,s,v,_=c.getHsv()
            if v<28 or v>248:
                continue
            fallback.append((r,g,b))
            if h<0 or s<35:
                continue
            # Hue clusters keep one strong cover accent from being muddied by unrelated colors.
            band=int(h//15) % 24
            weight=(0.35+float(s)/255.0)*(0.45+float(v)/255.0)
            acc=buckets.setdefault(band,[0.0,0.0,0.0,0.0])
            acc[0]+=r*weight; acc[1]+=g*weight; acc[2]+=b*weight; acc[3]+=weight
    if buckets:
        _band,acc=max(buckets.items(),key=lambda kv:kv[1][3])
        w=max(1e-6,float(acc[3])); c=QColor(int(acc[0]/w),int(acc[1]/w),int(acc[2]/w))
        h,s,v,_=c.getHsv(); c.setHsv(h,max(115,s),max(178,min(232,v)))
        return c.name()
    if fallback:
        n=len(fallback); c=QColor(sum(x[0] for x in fallback)//n,sum(x[1] for x in fallback)//n,sum(x[2] for x in fallback)//n)
        h,s,v,_=c.getHsv()
        if h>=0: c.setHsv(h,max(45,s),max(182,min(225,v)))
        return c.name()
    return ''


_h16_cover_color_from_image = _h19_cover_color_from_image


def _h19_smoothstep(p):
    p=max(0.0,min(1.0,float(p)))
    return p*p*(3.0-2.0*p)


def _h19_exit_effect_for_row(row):
    raw=str(getattr(row,'exit_effect','fade') or 'fade').strip().lower()
    legacy={
        'per_char':'reverse_typewriter', 'wipe_ltr':'reverse_slide',
        'wipe_rtl':'reverse_slide', 'shrink':'reverse_bounce'
    }
    raw=legacy.get(raw,raw)
    if raw=='mirror':
        entrance=str(getattr(row,'_h19_entrance_effect','smart') or 'smart').strip().lower()
        return {
            'soft':'reverse_soft', 'typewriter':'reverse_typewriter', 'rise':'reverse_rise',
            'slide':'reverse_slide', 'bounce':'reverse_bounce', 'smart':'reverse_smart',
            'token':'reverse_soft'
        }.get(entrance,'reverse_smart')
    return raw if raw in H19_EXIT_EFFECT_VALUES or raw=='reverse_smart' else 'fade'


def _h19_exit_motion(effect, progress):
    """Exact time reversal of LyricWindow._entrance_motion for motion entrances."""
    effect=str(effect or '').strip().lower(); q=max(0.0,min(1.0,float(progress)))
    p=1.0-q
    eased=1.0-(1.0-p)*(1.0-p)
    remain=1.0-eased
    if effect=='reverse_rise':
        return 0.0,13.0*remain
    if effect=='reverse_slide':
        return -15.0*remain,0.0
    if effect=='reverse_bounce':
        dy=11.0*((1.0-p)**2)-5.0*math.sin(math.pi*p)*(1.0-p)
        return 0.0,dy
    return 0.0,0.0


def _h19_exit_alpha(effect, progress):
    effect=str(effect or '').strip().lower(); p=max(0.0,min(1.0,float(progress)))
    if effect in ('reverse_typewriter','reverse_smart'):
        return 255
    if effect=='reverse_soft':
        return int(round(255.0*(1.0-_h19_smoothstep(p))))
    if effect in ('reverse_rise','reverse_slide','reverse_bounce'):
        fade_p=max(0.0,min(1.0,(p-0.12)/0.88))
        return int(round(255.0*(1.0-_h19_smoothstep(fade_p))))
    return int(round(255.0*(1.0-p)))


def _h19_exit_duration_ms(row,effect):
    base=max(float(H19_EXIT_MIN_MS),float(_h16_exit_duration_ms(row)))
    n=max(1,len(str(getattr(row,'text','') or '')))
    if effect in ('reverse_typewriter','reverse_smart'):
        base=max(base,min(float(H19_EXIT_MAX_MS),520.0+18.0*n))
    elif effect in ('reverse_rise','reverse_slide','reverse_bounce'):
        base=max(base,680.0)
    return min(float(H19_EXIT_MAX_MS),base)


def _h19_fading_update(self):
    raw=str(getattr(self,'exit_effect','fade') or 'fade').strip().lower()
    if raw in ('fade','instant'):
        return _LIMBUS_H19_FADING_UPDATE_PRE(self)
    effect=_h19_exit_effect_for_row(self)
    now=time.monotonic()*1000.0
    started=float(getattr(self,'_h16_exit_started_mono',0.0) or 0.0)
    if started<=0.0:
        started=now; self._h16_exit_started_mono=now; self._h16_exit_last_mono=now
    self._h16_exit_last_mono=now
    duration=_h19_exit_duration_ms(self,effect)
    progress=max(0.0,min(1.0,(now-started)/max(1.0,duration)))
    self._h16_exit_progress=progress
    self._fade_alpha_float=float(_h19_exit_alpha(effect,progress))
    self.alpha=int(max(0,min(255,round(self._fade_alpha_float))))
    if self.alpha>int(FADE_SHAKE_FREEZE_ALPHA):
        try: self._update_shake_motion()
        except Exception: pass
    if progress>=1.0:
        self.release_render_resources(); return False
    if effect not in ('reverse_typewriter','reverse_smart') and self.alpha<=int(FADE_VISUAL_ALPHA_CUTOFF):
        self.release_render_resources(); return False
    return True


FadingLine.update=_h19_fading_update


def _h19_row_width_metrics(row):
    advances=list(getattr(row,'_glyph_cache_advances',[]) or [])
    if len(advances)!=len(str(getattr(row,'text','') or '')):
        fm=QFontMetrics(QFont(row.font)); advances=[float(fm.horizontalAdvance(ch)) for ch in row.text]
        row._glyph_cache_advances=list(advances)
    spacing=float(getattr(row,'spacing',0.0) or 0.0)
    width=max(1.0,sum(advances)+max(0,len(advances)-1)*spacing)
    height=max(20.0,float(getattr(row,'_glyph_cache_height',0) or QFontMetrics(QFont(row.font)).height()))
    return advances,spacing,width,height


def _h19_fading_draw(self,painter):
    raw=str(getattr(self,'exit_effect','fade') or 'fade').strip().lower()
    if raw in ('fade','instant'):
        return _LIMBUS_H19_FADING_DRAW_PRE(self,painter)
    effect=_h19_exit_effect_for_row(self)
    progress=max(0.0,min(1.0,float(getattr(self,'_h16_exit_progress',0.0) or 0.0)))
    painter.save()
    try:
        dx,dy=_h19_exit_motion(effect,progress)
        if abs(dx)>=0.01 or abs(dy)>=0.01:
            painter.translate(float(dx),float(dy))
        if effect in ('reverse_typewriter','reverse_smart'):
            advances,spacing,width,height=_h19_row_width_metrics(self)
            n=len(advances)
            if n<=0:
                return
            # Time-reversed typewriter: the last glyph is the first to leave. Smart mode
            # uses an eased cursor, while explicit typewriter keeps a linear cadence.
            p=_h19_smoothstep(progress) if effect=='reverse_smart' else progress
            visible=max(0.0,float(n)*(1.0-p))
            whole=max(0,min(n,int(math.floor(visible))))
            frac=max(0.0,min(1.0,visible-float(whole)))
            clip_w=sum(advances[:whole])+max(0,whole-1)*spacing
            if whole<n and frac>0.0:
                if whole>0: clip_w+=spacing
                clip_w+=advances[whole]*frac
            painter.setClipRect(QRectF(float(self.x)-36.0,float(self.y)-height*2.2,max(0.0,float(clip_w))+72.0,height*4.4),Qt.IntersectClip)
        # Bypass H12's old wipe/shrink wrapper: draw through the original historical-row
        # renderer with only the H19 reverse transform/clip applied.
        return _LIMBUS_FADING_DRAW_PRE_H12(self,painter)
    finally:
        painter.restore()


FadingLine.draw=_h19_fading_draw


def _h19_make_history_line(self,text):
    item=_LIMBUS_H19_MAKE_HISTORY_PRE(self,text)
    if item is not None:
        try: item._h19_entrance_effect=str(self._entrance_effect_for_text(str(text or '')) or 'smart')
        except Exception: item._h19_entrance_effect=str(getattr(self,'entrance_effect','smart') or 'smart')
    return item


LyricWindow._make_history_line=_h19_make_history_line


def _h19_control_init(self,*args,**kwargs):
    _LIMBUS_H19_CONTROL_INIT_PRE(self,*args,**kwargs)
    try:
        old=str(getattr(self.lyric_window,'exit_effect','fade') or 'fade').strip().lower()
        old_map={'per_char':'reverse_typewriter','wipe_ltr':'reverse_slide','wipe_rtl':'reverse_slide','shrink':'reverse_bounce'}
        selected=old_map.get(old,old)
        if selected not in H19_EXIT_EFFECT_VALUES:
            selected='mirror'
        self.h12_exit_combo.blockSignals(True)
        self.h12_exit_combo.clear()
        for label,key in [
            ('跟随进场反向（推荐）','mirror'),
            ('柔和淡退（淡入反向）','reverse_soft'),
            ('打字机倒放','reverse_typewriter'),
            ('下沉退场（上浮反向）','reverse_rise'),
            ('向左滑出（侧滑反向）','reverse_slide'),
            ('轻弹退场（弹入反向）','reverse_bounce'),
            ('整行淡出','fade'),
            ('直接消失','instant'),
        ]:
            self.h12_exit_combo.addItem(label,key)
        idx=self.h12_exit_combo.findData(selected)
        self.h12_exit_combo.setCurrentIndex(max(0,idx))
        self.lyric_window.exit_effect=str(self.h12_exit_combo.currentData() or 'mirror')
        self.h12_exit_combo.blockSignals(False)
        self.h12_exit_combo.setToolTip('“跟随进场反向”会为每一行记住它实际使用的进场方式，并在退场时按时间反向播放；不改变歌词时间轴。')
    except Exception as exc:
        try: write_error_log('H19镜像退场初始化失败',exc)
        except Exception: pass
    try:
        self.h12_cover_check.setToolTip('从当前歌曲封面提取主色作为歌词文字色。H19会在搜索结果只有picId时后台补查歌曲/专辑详情；与随机颜色互斥，单曲DIY颜色优先。')
    except Exception:
        pass


ControlPanel.__init__=_h19_control_init


# H20 classic-exit / palette / KuGou presentation / packaging closure ----------
# H19 proved cover acquisition but also exposed three real-machine presentation defects:
# (1) replacing the established H12 classic exits with whole-row "reverse entrance" effects
#     changed user-visible behavior and did not actually mirror per-token entrances;
# (2) cover-follow changed only text color while leaving an unrelated legacy glow color;
# (3) KuGou Host-V2 could already know the exact current duration while H14's separate
#     MSAA version probe exceeded 1.25s and threw away a KRC that arrived milliseconds later.
# This layer is presentation/evidence-only. Player clocks, seek authority and provider
# timestamps remain owned by the earlier transport chain.
H20_EXIT_CLASSIC_VALUES = ('fade','per_char','wipe_ltr','wipe_rtl','shrink','soft_drift','instant')
H20_KUGOU_DURATION_HINT_TTL_SEC = 8.0
H20_MANUAL_PRECISE_PENDING_MAX_SEC = 20.0
_LIMBUS_H20_CONTROL_INIT_PRE = ControlPanel.__init__
_LIMBUS_H20_RESOLVE_STYLE_PRE = ControlPanel._resolved_active_visual_style
_LIMBUS_H20_FADING_UPDATE_CLASSIC = globals().get('_LIMBUS_H19_FADING_UPDATE_PRE', FadingLine.update)
_LIMBUS_H20_FADING_DRAW_CLASSIC = globals().get('_LIMBUS_H19_FADING_DRAW_PRE', FadingLine.draw)
_LIMBUS_H20_PROVIDER_IDLE_PRE = LyricWindow._release_provider_idle_visual
_LIMBUS_H20_KUGOU_PROGRESS_PRE = MediaSessionSync._kugou_poll_uia_progress_v2
_LIMBUS_H20_KUGOU_UI_HINT_PRE = LyricFetcher.get_kugou_ui_duration_hint
_LIMBUS_H20_MANUAL_APPLY_PRE = ControlPanel._apply_manual_lyric_payload
_LIMBUS_H20_MANUAL_RESULT_PRE = ControlPanel._on_manual_lyric_result
_LIMBUS_H20_MANUAL_FETCH_PRE = ControlPanel.fetch_lyric
_LIMBUS_H20_KUGOU_DURATION_HINTS = {}
_LIMBUS_H20_KUGOU_DURATION_LOCK = threading.Lock()


def _h20_cover_accent_from_rgb_rows(rows,total_valid=None):
    """Return one readable representative accent from (r,g,b,count) buckets.

    Population is primary; chroma and mid-tone readability break ties.  ``total_valid`` lets
    the caller distinguish a genuinely colorful cover from a nearly monochrome cover with a
    handful of tinted JPEG/lighting pixels.  The latter should stay neutral instead of being
    artificially promoted into a bright blue/red lyric color.
    """
    import colorsys
    best=None; chromatic_total=0.0
    prepared=[]
    for row in list(rows or []):
        try:
            r,g,b,count=[float(x) for x in row[:4]]
        except Exception:
            continue
        if count <= 0:
            continue
        rr,gg,bb=max(0.0,min(255.0,r))/255.0,max(0.0,min(255.0,g))/255.0,max(0.0,min(255.0,b))/255.0
        h,s,v=colorsys.rgb_to_hsv(rr,gg,bb)
        if v < 0.10 or (v > 0.96 and s < 0.16) or s < 0.11:
            continue
        prepared.append((r,g,b,count,h,s,v)); chromatic_total+=count
    try:
        total=max(float(total_valid or 0.0),chromatic_total)
    except Exception:
        total=chromatic_total
    if total>0 and chromatic_total/total < 0.085:
        return None
    for _r,_g,_b,count,h,s,v in prepared:
        # A representative region still needs meaningful population.  This avoids tiny UI-like
        # accents, compression speckles or edge lighting owning a mostly neutral album cover.
        coverage=(count/total) if total>0 else 1.0
        if total>0 and coverage < 0.012:
            continue
        mid=1.0-min(1.0,abs(v-0.64)/0.64)
        score=(count ** 0.90) * (0.62 + s * 0.92) * (0.84 + mid * 0.22)
        if best is None or score > best[0]:
            best=(score,h,s,v)
    if best is None:
        return None
    _,h,s,v=best
    # Album tint should support the lyric rather than turn it into a neon UI element.  Keep
    # the hue, reduce extreme saturation, and bias toward a light foreground suitable for an
    # arbitrary desktop background.  This follows the same design principle as dynamic music
    # themes that tint readable text instead of replacing white text with a dark raw swatch.
    s=max(0.20,min(0.56,s*0.62+0.10))
    v=max(0.84,min(0.95,v*0.60+0.38))
    r,g,b=colorsys.hsv_to_rgb(h,s,v)
    return tuple(int(round(x*255.0)) for x in (r,g,b))


def _h20_cover_color_from_image(image):
    if image is None or image.isNull():
        return ''
    q=image.scaled(48,48,Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
    bins={}; neutral=[]; valid_total=0
    for y in range(q.height()):
        for x in range(q.width()):
            c=QColor(q.pixel(x,y)); r,g,b=c.red(),c.green(),c.blue()
            mx=max(r,g,b); mn=min(r,g,b); chroma=mx-mn
            if mx < 24 or (mn > 238 and chroma < 24):
                continue
            valid_total+=1
            if chroma < 24:
                if 45 <= mx <= 235:
                    neutral.append((r,g,b))
                continue
            key=(r//32,g//32,b//32)
            acc=bins.setdefault(key,[0,0,0,0])
            acc[0]+=r; acc[1]+=g; acc[2]+=b; acc[3]+=1
    rows=[]
    for acc in bins.values():
        n=max(1,int(acc[3])); rows.append((acc[0]/n,acc[1]/n,acc[2]/n,n))
    rgb=_h20_cover_accent_from_rgb_rows(rows,total_valid=valid_total)
    if rgb is None and neutral:
        # Predominantly monochrome artwork should produce a clean neutral lyric rather than
        # magnifying a tiny colored artifact into a saturated accent.  Keep it softly off-white
        # so it still feels derived from the artwork without sacrificing readability.
        n=len(neutral); lum=sum((px[0]+px[1]+px[2])/3.0 for px in neutral)/max(1,n)
        v=max(205,min(236,int(round(lum*0.22+190))))
        rgb=(v,v,v)
    if rgb is None:
        return ''
    return QColor(int(rgb[0]),int(rgb[1]),int(rgb[2])).name()

def _h20_glow_from_text(color):
    c=QColor(color)
    if not c.isValid():
        return QColor('#777777')
    h,s,v,_=c.getHsv()
    if h < 0:
        g=max(72,min(145,int(v*0.52)))
        return QColor(g,g,g)
    out=QColor()
    out.setHsv(h,max(110,min(225,int(s)+34)),max(72,min(148,int(v)-72)))
    return out


# The existing H16 daemon worker calls this global after decoding the artwork.
_h16_cover_color_from_image = _h20_cover_color_from_image


def _h20_resolve_style(self):
    font,text_color,glow_color=_LIMBUS_H20_RESOLVE_STYLE_PRE(self)
    try:
        style=dict(getattr(self,'_active_song_style',{}) or {})
        key=self._track_identity(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist',''))
        cached=getattr(self,'_h12_cover_applied',None)
        if bool(getattr(self,'_h12_cover_follow',False)) and cached and cached[0]==key and not style.get('text_color'):
            c=QColor(str(cached[1] or ''))
            if c.isValid():
                text_color=c
                # A per-song DIY glow remains authoritative. Otherwise cover-follow owns a
                # coherent text+glow palette instead of mixing the cover accent with the old
                # global yellow/other glow.
                if not style.get('glow_color'):
                    glow_color=_h20_glow_from_text(c)
    except Exception:
        pass
    return font,text_color,glow_color


ControlPanel._resolved_active_visual_style=_h20_resolve_style


def _h20_fading_update(self):
    effect=str(getattr(self,'exit_effect','fade') or 'fade').strip().lower()
    # Exact H18/H16 behavior for the six established classic exits. This intentionally
    # bypasses H19's reverse-effect remapping.
    if effect != 'soft_drift':
        if effect not in H20_EXIT_CLASSIC_VALUES:
            self.exit_effect='fade'
        return _LIMBUS_H20_FADING_UPDATE_CLASSIC(self)
    now=time.monotonic()*1000.0
    started=float(getattr(self,'_h16_exit_started_mono',0.0) or 0.0)
    if started<=0.0:
        started=now; self._h16_exit_started_mono=now
    duration=max(620.0,min(1050.0,float(_h16_exit_duration_ms(self))))
    p=max(0.0,min(1.0,(now-started)/max(1.0,duration)))
    self._h16_exit_progress=p
    eased=p*p*(3.0-2.0*p)
    self._fade_alpha_float=255.0*(1.0-eased)
    self.alpha=int(max(0,min(255,round(self._fade_alpha_float))))
    if self.alpha>int(FADE_SHAKE_FREEZE_ALPHA):
        try: self._update_shake_motion()
        except Exception: pass
    if p>=1.0 or self.alpha<=int(FADE_VISUAL_ALPHA_CUTOFF):
        self.release_render_resources(); return False
    return True


def _h20_fading_draw(self,painter):
    effect=str(getattr(self,'exit_effect','fade') or 'fade').strip().lower()
    if effect!='soft_drift':
        return _LIMBUS_H20_FADING_DRAW_CLASSIC(self,painter)
    p=max(0.0,min(1.0,float(getattr(self,'_h16_exit_progress',0.0) or 0.0)))
    eased=p*p*(3.0-2.0*p)
    painter.save()
    try:
        # Deliberately subtle. Mature lyric renderers use fluid, interruptible movement;
        # the row should leave without becoming a second focal animation.
        painter.translate(0.0,7.0*eased)
        sc=1.0-0.018*eased
        painter.translate(float(self.x),float(self.y)); painter.scale(sc,sc); painter.translate(-float(self.x),-float(self.y))
        return _LIMBUS_FADING_DRAW_PRE_H12(self,painter)
    finally:
        painter.restore()


FadingLine.update=_h20_fading_update
FadingLine.draw=_h20_fading_draw


