def _h20_provider_idle_release(self,line_index,position_ms,deadline_info):
    source=str(getattr(self,'_last_sync_source','') or '').strip().lower()
    is_kugou=source in ('kugou','kgmusic','kgmusic.exe')
    keep_limit=max(0,int(getattr(self,'max_visible_subtitles',1) or 1)-1)
    if not is_kugou or keep_limit<=0 or not getattr(self,'history_lines',None):
        return _LIMBUS_H20_PROVIDER_IDLE_PRE(self,line_index,position_ms,deadline_info)
    held=list(self.history_lines)[-keep_limit:]
    self.history_lines=[]
    ok=False
    try:
        ok=bool(_LIMBUS_H20_PROVIDER_IDLE_PRE(self,line_index,position_ms,deadline_info))
        current_extra=list(getattr(self,'history_lines',[]) or [])
        self.history_lines=(held+current_extra)[-keep_limit:]
        try: self._enforce_visual_stack_limit()
        except Exception: pass
        try: self.update()
        except Exception: pass
        if ok:
            try: write_error_log('H20酷狗空白段保留清晰历史',detail=f'line={int(line_index)} | held={len(self.history_lines)} | live_limit={int(getattr(self,"max_visible_subtitles",1) or 1)} | current=fade-only')
            except Exception: pass
        return ok
    finally:
        if not ok and not getattr(self,'history_lines',None):
            self.history_lines=held


LyricWindow._release_provider_idle_visual=_h20_provider_idle_release



def _h20_manual_apply(self,result):
    result=dict(result or {})
    try:
        stage=str(result.get('stage') or '')
        if stage=='fast' and bool(getattr(self,'_is_started',False)) and result.get('lyric'):
            song=str(result.get('song') or ''); artist=str(result.get('artist') or '')
            same_loaded=bool(self._same_track(song,artist,getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist','')))
            if same_loaded:
                current=str(self.text_input.toPlainText() or '')
                incoming=str(result.get('lyric') or '')
                old_q=_lyric_clock_quality(current); new_q=_lyric_clock_quality(incoming)
                if current.strip() and (current.strip()==incoming.strip() or old_q>=new_q):
                    self.status.setText(f'状态：当前「{song}」歌词已在显示；精准歌词后台升级中')
                    try: write_error_log('H20同曲手动快速歌词免重启',detail=f'song={song} | old_quality={old_q} | new_quality={new_q} | renderer-reset=skip | precise=continue')
                    except Exception: pass
                    return True
    except Exception:
        pass
    return _LIMBUS_H20_MANUAL_APPLY_PRE(self,result)


ControlPanel._apply_manual_lyric_payload=_h20_manual_apply


def _h20_manual_result(self,result):
    result=dict(result or {})
    event=str(result.get('event') or '')
    stage=str(result.get('stage') or '')
    generation=int(result.get('generation',-1) or -1)
    out=_LIMBUS_H20_MANUAL_RESULT_PRE(self,result)
    try:
        if event=='search-result' and result.get('lyric') and stage=='fast' and bool(result.get('prefer_precise')):
            key=self._track_identity(result.get('song',''),result.get('artist',''))
            self._h20_manual_precise_pending=(generation,str(key),str(result.get('source') or ''),time.monotonic())
        if event=='search-result' and (stage=='precise' or bool(result.get('final')) or bool(result.get('keep_fast'))):
            pending=getattr(self,'_h20_manual_precise_pending',None)
            if pending and int(pending[0])==generation:
                self._h20_manual_precise_pending=None
    except Exception:
        pass
    return out


ControlPanel._on_manual_lyric_result=_h20_manual_result


def _h20_manual_fetch(self):
    try:
        pending=getattr(self,'_h20_manual_precise_pending',None)
        if pending:
            generation,key,source,stamp=pending
            age=max(0.0,time.monotonic()-float(stamp))
            current=self._track_identity(getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist',''))
            if age<=float(H20_MANUAL_PRECISE_PENDING_MAX_SEC) and str(current)==str(key) and str(self.source_combo.currentText() or '')==str(source):
                self.status.setText('状态：当前歌曲精准歌词正在后台升级；重复请求已忽略')
                try: write_error_log('H20重复手动抓词合并精准任务',detail=f'generation={generation} | key={key} | age={int(age*1000)}ms | duplicate-render-reset=skip')
                except Exception: pass
                return False
            if age>float(H20_MANUAL_PRECISE_PENDING_MAX_SEC) or str(current)!=str(key):
                self._h20_manual_precise_pending=None
    except Exception:
        pass
    return _LIMBUS_H20_MANUAL_FETCH_PRE(self)


ControlPanel.fetch_lyric=_h20_manual_fetch


def _h20_control_init(self,*args,**kwargs):
    _LIMBUS_H20_CONTROL_INIT_PRE(self,*args,**kwargs)
    try:
        old=str(getattr(self.lyric_window,'exit_effect','fade') or 'fade').strip().lower()
        migration={
            'mirror':'fade','reverse_soft':'fade','reverse_typewriter':'per_char',
            'reverse_rise':'soft_drift','reverse_slide':'wipe_ltr','reverse_bounce':'shrink',
            'reverse_smart':'fade'
        }
        selected=migration.get(old,old)
        if selected not in H20_EXIT_CLASSIC_VALUES:
            selected='fade'
        self.h12_exit_combo.blockSignals(True)
        self.h12_exit_combo.clear()
        for label,key in [
            ('整行淡出（经典）','fade'),
            ('逐字消失（经典）','per_char'),
            ('从左到右消失（经典）','wipe_ltr'),
            ('从右到左消失（经典）','wipe_rtl'),
            ('快速收缩/淡出（经典）','shrink'),
            ('柔和下沉淡出','soft_drift'),
            ('直接消失','instant'),
        ]:
            self.h12_exit_combo.addItem(label,key)
        idx=self.h12_exit_combo.findData(selected)
        self.h12_exit_combo.setCurrentIndex(max(0,idx))
        self.lyric_window.exit_effect=str(self.h12_exit_combo.currentData() or 'fade')
        self.h12_exit_combo.blockSignals(False)
        self.h12_exit_combo.setToolTip('H20已恢复H18的经典退场。柔和下沉淡出仅做轻微位移+缩放+平滑透明度，不改变歌词时间轴。')
        if old!=selected:
            QTimer.singleShot(0,self._schedule_config_save)
    except Exception as exc:
        try: write_error_log('H20经典退场恢复初始化失败',exc)
        except Exception: pass
    try:
        self.h12_cover_check.setToolTip('从封面排除黑/白/灰后选代表色，并生成同色系文字+辉光；单曲DIY文字/辉光仍优先。')
    except Exception:
        pass
    self._h20_manual_precise_pending=None


ControlPanel.__init__=_h20_control_init


# H23 Win10 frozen KuGou: complete in-process accessibility fail-closed profile.
# H22 removed the deep pywinauto UIA surface, but the legacy KuGou reader could still
# immediately fall through to native MSAA/comtypes tree traversal. The field failure ended
# around that fallback lane as well, so this exact Win10 frozen profile must avoid both
# accessibility stacks in-process. Win32/GSMTC/KRC/numeric/gesture lanes remain available.
_LIMBUS_H23_KUGOU_MSAA_PRE = PlayerUiPositionReader._try_kugou_msaa_probe
_LIMBUS_H23_KUGOU_DURATION_HINT_PRE = LyricFetcher.get_kugou_ui_duration_hint


def _h23_windows_build_number():
    try:
        return int(sys.getwindowsversion().build or 0) if hasattr(sys, 'getwindowsversion') else 0
    except Exception:
        return 0


def _h23_kugou_win10_frozen_no_accessibility():
    try:
        enabled = str(os.environ.get('LIMBUSLYRIC_H23_KUGOU_WIN10_NO_UIA_INIT', '1')).strip().lower() not in {'0','false','no','off'}
        legacy_enabled = str(os.environ.get('LIMBUSLYRIC_H22_KUGOU_WIN10_FROZEN_SAFE_MODE', '1')).strip().lower() not in {'0','false','no','off'}
        optin = str(os.environ.get('LIMBUSLYRIC_KUGOU_HOST_V2_UIA_WIN10', '0')).strip().lower() in {'1','true','yes','on'}
        build = _h23_windows_build_number()
        return bool(enabled and legacy_enabled and not optin and sys.platform.startswith('win') and getattr(sys, 'frozen', False) and 0 < build < 22000)
    except Exception:
        return False


def _h23_kugou_msaa_guard(self, process_name, pids):
    if _h23_kugou_win10_frozen_no_accessibility():
        now = time.monotonic()
        last = float(getattr(self, '_h23_kugou_msaa_skip_log_mono', 0.0) or 0.0)
        if now - last >= 30.0:
            self._h23_kugou_msaa_skip_log_mono = now
            try:
                write_error_log('H23酷狗Win10 MSAA安全跳过', detail=(
                    f'process={process_name} | build={_h23_windows_build_number()} | frozen=1 | '
                    'action=skip-inprocess-comtypes-msaa | kept=win32+numeric+gsmtc+krc'))
            except Exception:
                pass
        return None
    return _LIMBUS_H23_KUGOU_MSAA_PRE(self, process_name, pids)


def _h23_kugou_duration_hint_guard(pids, song_name, max_nodes=640):
    if _h23_kugou_win10_frozen_no_accessibility():
        try:
            write_error_log('H23酷狗Win10版本时长MSAA安全跳过', detail=(
                f'song={song_name} | build={_h23_windows_build_number()} | frozen=1 | '
                'action=skip-comtypes-tree-version-hint | version-evidence=other-lanes-only'))
        except Exception:
            pass
        return 0
    return _LIMBUS_H23_KUGOU_DURATION_HINT_PRE(pids, song_name, max_nodes=max_nodes)


PlayerUiPositionReader._try_kugou_msaa_probe = _h23_kugou_msaa_guard
LyricFetcher.get_kugou_ui_duration_hint = staticmethod(_h23_kugou_duration_hint_guard)


# H21 KuGou identity corroboration / cover-control placement --------------------
# H20 real-machine replay exposed a KuGou identity race: Host-V2 had already
# observed the new window title while a fresh GSMTC notification still carried
# the previous media title.  The stale notification could reset the just-bound
# track, blank/relaunch presentation, and leave later KRC duration evidence
# attached to the wrong media identity.  H21 gives a *recent, conflicting,
# just-switched Host-V2 title* a short veto over GSMTC title-change promotion.
# It also closes H20's KuGou duration reuse timing gap and relocates the existing
# cover-follow checkbox beside the random font/color controls.  Clock/seek and
# provider timestamps remain unchanged.
H21_KUGOU_HOST_IDENTITY_VETO_SEC = 3.0
H21_KUGOU_HOST_HINT_WAIT_SEC = 0.55
H21_KUGOU_DURATION_MATCH_MIN_MS = 1200
H21_KUGOU_DURATION_MATCH_RATIO = 0.012
_LIMBUS_H21_DETECTED_TRACK_PRE = ControlPanel._detected_player_track
_LIMBUS_H21_KUGOU_PROMOTE_PRE = ControlPanel._promote_kugou_background_identity_hint
_LIMBUS_H21_KUGOU_PROGRESS_PRE = MediaSessionSync._kugou_poll_uia_progress_v2
_LIMBUS_H21_KUGOU_UI_HINT_PRE = LyricFetcher.get_kugou_ui_duration_hint
_LIMBUS_H21_CONTROL_INIT_PRE = ControlPanel.__init__


def _h21_recent_kugou_duration_hint(song_name, max_age=H20_KUGOU_DURATION_HINT_TTL_SEC):
    try:
        key=_clean_name(song_name)
        if not key:
            return 0
        with _LIMBUS_H20_KUGOU_DURATION_LOCK:
            row=_LIMBUS_H20_KUGOU_DURATION_HINTS.get(key)
        if not row:
            return 0
        duration,stamp=int(row[0]),float(row[1])
        if duration < 5000 or max(0.0,time.monotonic()-stamp) > float(max_age):
            return 0
        return duration
    except Exception:
        return 0


def _h21_kugou_progress_v2(self,*args,**kwargs):
    out=_LIMBUS_H21_KUGOU_PROGRESS_PRE(self,*args,**kwargs)
    try:
        duration=int(getattr(self,'_uia_duration_ms',0) or (getattr(self,'_state',{}) or {}).get('duration_ms') or 0)
        host=dict(getattr(self,'_kugou_host_v2_cache',None) or {})
        host_mono=float(getattr(self,'_kugou_host_v2_cache_mono',0.0) or 0.0)
        host_age=time.monotonic()*1000.0-host_mono if host_mono>0.0 else 10**9
        if duration>=5000 and host_age<=2500.0 and str(host.get('class') or '').lower()=='kugou_ui':
            hsong,_hartist=LyricFetcher._split_title(
                str(host.get('title') or ''),'酷狗音乐',
                (DEFAULT_PLAYERS.get('酷狗音乐',{}) or {}).get('pattern')
            )
            hkey=_clean_name(hsong)
            if hkey:
                with _LIMBUS_H20_KUGOU_DURATION_LOCK:
                    _LIMBUS_H20_KUGOU_DURATION_HINTS[hkey]=(duration,time.monotonic())
    except Exception:
        pass
    return out


MediaSessionSync._kugou_poll_uia_progress_v2=_h21_kugou_progress_v2


def _h21_kugou_ui_duration_hint(pids,song_name,max_nodes=640):
    # H14 executes the expensive legacy/MSAA probe in its own named daemon thread.
    # Give Host-V2 a brief opportunity to publish the duration already being discovered
    # by the live transport path before falling into the old accessibility tree scan.
    if str(threading.current_thread().name or '')=='LimbusLyric-H14-KuGouDurationHint':
        deadline=time.monotonic()+float(H21_KUGOU_HOST_HINT_WAIT_SEC)
        while True:
            hint=_h21_recent_kugou_duration_hint(song_name)
            if hint:
                try: write_error_log('H21酷狗HostV2时长等待命中',detail=f'song={song_name} | duration={hint}ms | legacy-msaa=skip')
                except Exception: pass
                return hint
            if time.monotonic()>=deadline:
                break
            time.sleep(0.035)
    hint=_h21_recent_kugou_duration_hint(song_name)
    if hint:
        return hint
    return _LIMBUS_H21_KUGOU_UI_HINT_PRE(pids,song_name,max_nodes=max_nodes)


LyricFetcher.get_kugou_ui_duration_hint=staticmethod(_h21_kugou_ui_duration_hint)


def _h21_detected_player_track(self):
    out=_LIMBUS_H21_DETECTED_TRACK_PRE(self)
    try:
        if str(self.player_combo.currentText() or '')!='酷狗音乐':
            return out
        host=dict(getattr(self.media_sync,'_kugou_host_v2_cache',None) or {})
        host_mono=float(getattr(self.media_sync,'_kugou_host_v2_cache_mono',0.0) or 0.0)
        age=time.monotonic()*1000.0-host_mono if host_mono>0.0 else 10**9
        if age>2200.0 or str(host.get('class') or '').lower()!='kugou_ui':
            return out
        hsong,hartist=LyricFetcher._split_title(
            str(host.get('title') or ''),'酷狗音乐',
            (self.players.get('酷狗音乐',{}) or {}).get('pattern')
        )
        if not hsong or not out or not out[0]:
            return out
        # Record only a real Host-V2 switch away from the currently loaded track, and only
        # when the detector actually chose that same Host-V2 identity.  A stable old host
        # title is therefore never allowed to veto a genuinely newer GSMTC track.
        if (
            self._same_track(out[0],out[1] or '',hsong,hartist or '') and
            not self._same_track(hsong,hartist or '',getattr(self,'_loaded_song',''),getattr(self,'_loaded_artist',''))
        ):
            self._h21_kugou_host_switch=(str(hsong),str(hartist or ''),time.monotonic())
    except Exception:
        pass
    return out


ControlPanel._detected_player_track=_h21_detected_player_track


def _h21_kugou_promote(self,song,artist='',source='kugou-background-title',evidence_mono_ms=None):
    try:
        if str(source or '')=='kugou-gsmtc-title-change':
            # H24: a rotating same-HWND Host title is discovery-only and must never
            # let H21 veto the process-affine GSMTC identity.  The state attribute is
            # absent on older builds/replays, so H21's historical behavior is unchanged.
            try:
                h24_state=dict(getattr(self,'_h24_kugou_host_title_state',{}) or {})
                if time.monotonic()*1000.0 < float(h24_state.get('marquee_until') or 0.0):
                    self._h21_kugou_host_switch=None
            except Exception:
                pass
            guard=getattr(self,'_h21_kugou_host_switch',None)
            if guard:
                hsong,hartist,stamp=guard
                age=max(0.0,time.monotonic()-float(stamp))
                if age<=float(H21_KUGOU_HOST_IDENTITY_VETO_SEC) and not self._same_track(song,artist,hsong,hartist):
                    # The guard remains valid only while the cached KuGou host title still
                    # agrees with it.  This prevents a stale guard from delaying a rapid
                    # second real track switch.
                    host=dict(getattr(self.media_sync,'_kugou_host_v2_cache',None) or {})
                    host_mono=float(getattr(self.media_sync,'_kugou_host_v2_cache_mono',0.0) or 0.0)
                    host_age=time.monotonic()*1000.0-host_mono if host_mono>0.0 else 10**9
                    csong,cartist=LyricFetcher._split_title(
                        str(host.get('title') or ''),'酷狗音乐',
                        (self.players.get('酷狗音乐',{}) or {}).get('pattern')
                    )
                    if (
                        host_age<=2200.0 and csong and
                        self._same_track(csong,cartist or '',hsong,hartist or '')
                    ):
                        try:
                            write_error_log('H21酷狗陈旧GSMTC身份否决',detail=(
                                f'gsmtc={song}|{artist or "<empty>"} | host={hsong}|{hartist or "<empty>"} | '
                                f'host_switch_age={int(age*1000)}ms | identity-reset=skip | network-restart=skip'))
                        except Exception:
                            pass
                        try: self._queue_track_probe('酷狗音乐',urgent=True)
                        except Exception: pass
                        return False
                elif age>float(H21_KUGOU_HOST_IDENTITY_VETO_SEC):
                    self._h21_kugou_host_switch=None
    except Exception:
        pass
    return _LIMBUS_H21_KUGOU_PROMOTE_PRE(self,song,artist,source=source,evidence_mono_ms=evidence_mono_ms)


ControlPanel._promote_kugou_background_identity_hint=_h21_kugou_promote


def _h21_find_widget_layout(layout,widget):
    if layout is None or widget is None:
        return None,-1
    try:
        for i in range(layout.count()):
            item=layout.itemAt(i)
            if item.widget() is widget:
                return layout,i
            child=item.layout()
            if child is not None:
                found,idx=_h21_find_widget_layout(child,widget)
                if found is not None:
                    return found,idx
    except Exception:
        pass
    return None,-1


def _h21_control_init(self,*args,**kwargs):
    _LIMBUS_H21_CONTROL_INIT_PRE(self,*args,**kwargs)
    self._h21_kugou_host_switch=None
    # Cover-follow is a song text-style choice, not an updater/display-infrastructure
    # setting. Move the *existing* checkbox (same signal/config ownership) beside the
    # random-font/random-color controls instead of creating a second control.
    try:
        root=self.layout()
        old_layout,_old_idx=_h21_find_widget_layout(root,getattr(self,'h12_cover_check',None))
        target_layout,target_idx=_h21_find_widget_layout(root,getattr(self,'random_color_check',None))
        if target_layout is not None and target_idx>=0:
            if old_layout is not None:
                old_layout.removeWidget(self.h12_cover_check)
            try: self.h12_cover_check.setParent(self.random_color_check.parentWidget())
            except Exception: pass
            target_layout.insertWidget(target_idx+1,self.h12_cover_check)
            self.h12_cover_check.setText('歌词颜色跟随封面')
            self.h12_cover_check.setToolTip('按当前歌曲封面生成可读文字+同色系辉光；与每首歌随机颜色互斥，单曲DIY仍优先。')
            try: write_error_log('H21封面跟色控件归位',detail='section=subtitle-style | beside=random-color | config-key=h12_cover_follow')
            except Exception: pass
    except Exception as exc:
        try: write_error_log('H21封面跟色控件归位失败',exc)
        except Exception: pass


ControlPanel.__init__=_h21_control_init

# ==================== H22 KuGou Win10 crash hardening ====================
# Field evidence from a Windows 10 19045 frozen build showed KuGou's custom UIA provider
# repeatedly taking ~20-26 seconds to answer a RangeValue descendants query, followed by an
# ungraceful process disappearance with no Python traceback or normal log-session footer.
# Keep the proven Win32/GSMTC/KRC/numeric lanes, but do not repeatedly enter the same in-process
# pywinauto deep Range scan on that platform. Other platforms retain HostV2 Range with a slow-call
# circuit breaker so one pathological provider cannot be queried over and over.
H22_KUGOU_HOST_UIA_SLOW_MS = max(750.0, min(8000.0, float(__import__('os').environ.get('LIMBUSLYRIC_H22_KUGOU_HOST_UIA_SLOW_MS', '1500'))))
H22_KUGOU_HOST_UIA_SLOW_FUSE_SEC = max(30.0, min(900.0, float(__import__('os').environ.get('LIMBUSLYRIC_H22_KUGOU_HOST_UIA_SLOW_FUSE_SEC', '300'))))
H22_KUGOU_HOST_UIA_MISS_FUSE_SEC = max(15.0, min(300.0, float(__import__('os').environ.get('LIMBUSLYRIC_H22_KUGOU_HOST_UIA_MISS_FUSE_SEC', '90'))))
H22_KUGOU_HOST_UIA_MISS_LIMIT = max(2, min(8, int(__import__('os').environ.get('LIMBUSLYRIC_H22_KUGOU_HOST_UIA_MISS_LIMIT', '3'))))
H22_KUGOU_WIN10_FROZEN_SAFE_MODE = str(__import__('os').environ.get('LIMBUSLYRIC_H22_KUGOU_WIN10_FROZEN_SAFE_MODE', '1')).strip().lower() not in {'0','false','no','off'}
H22_KUGOU_WIN10_HOST_UIA_OPTIN = str(__import__('os').environ.get('LIMBUSLYRIC_KUGOU_HOST_V2_UIA_WIN10', '0')).strip().lower() in {'1','true','yes','on'}

_LIMBUS_H22_KUGOU_PROGRESS_PRE = MediaSessionSync._kugou_poll_uia_progress_v2
_H22_PLAYER_UI_READER_CLASS = globals().get('PlayerUiPositionReader')
_H22_ASYNC_UI_READER_CLASS = globals().get('AsyncPlayerUiPositionReader')
_LIMBUS_H22_KUGOU_POINT_PRE = getattr(_H22_PLAYER_UI_READER_CLASS, '_try_kugou_point_probe', None)
_LIMBUS_H22_KUGOU_HIDDEN_RANGE_PRE = getattr(_H22_PLAYER_UI_READER_CLASS, '_kugou_hidden_startup_range', None)
_LIMBUS_H22_KUGOU_WAKE_PRE = getattr(_H22_ASYNC_UI_READER_CLASS, '_kick_accessibility', None)
_H22_FAULT_HANDLE = None


def _h22_windows_build_number():
    try:
        _sys = __import__('sys')
        if hasattr(_sys, 'getwindowsversion'):
            return int(_sys.getwindowsversion().build or 0)
    except Exception:
        pass
    return 0


def _h22_kugou_win10_frozen_safe_mode():
    if not bool(H22_KUGOU_WIN10_FROZEN_SAFE_MODE) or bool(H22_KUGOU_WIN10_HOST_UIA_OPTIN):
        return False
    try:
        build = _h22_windows_build_number()
        _sys = __import__('sys')
        return bool(_sys.platform.startswith('win') and getattr(_sys, 'frozen', False) and 0 < build < 22000)
    except Exception:
        return False


def _h22_kugou_progress_guard(self, status='unknown', local_position_hint=None):
    now_ms = time.monotonic() * 1000.0

    # Windows 10 + frozen is the exact field environment that produced repeated 20s+ provider
    # stalls and then vanished without a Python-level exception. The async compatibility reader
    # remains available; only this second synchronous deep pywinauto Range walk is suppressed.
    if _h22_kugou_win10_frozen_safe_mode():
        last = float(getattr(self, '_h22_kugou_win10_uia_safe_log_mono', 0.0) or 0.0)
        if now_ms - last >= 30000.0:
            self._h22_kugou_win10_uia_safe_log_mono = now_ms
            try:
                write_error_log('H22酷狗HostV2 UIA安全模式', detail=(
                    f'windows_build={_h22_windows_build_number()} | frozen=1 | '
                    'action=skip-inprocess-pywinauto-range | '
                    'kept=win32-host+gsmtc+krc+numeric'))
            except Exception:
                pass
        return None

    # A changed top-level HWND is a new provider instance and gets one fresh capability attempt.
    hwnd = 0
    try:
        host = self._kugou_resolve_host_v2()
        hwnd = int((host or {}).get('hwnd') or 0)
    except Exception:
        hwnd = 0
    prev_hwnd = int(getattr(self, '_h22_kugou_host_uia_hwnd', 0) or 0)
    if hwnd and prev_hwnd and hwnd != prev_hwnd:
        self._h22_kugou_host_uia_fused_until_mono = 0.0
        self._h22_kugou_host_uia_miss_streak = 0
        self._h22_kugou_host_uia_mandatory_skip = 0
    if hwnd:
        self._h22_kugou_host_uia_hwnd = hwnd

    # H33F1: a completed slow/no-range provider call must suppress at least the next
    # logical re-entry once, independent of wall-clock scheduling.  The release suite runs
    # gates concurrently and real Windows/VM machines can be descheduled or suspended long
    # enough for a short test fuse (or even a production fuse) to expire before the caller
    # gets CPU again.  Without this one-shot barrier the first resumed call can immediately
    # re-enter the same risky UIA provider.  A changed HWND above clears the barrier because
    # that is a genuinely new provider instance.
    mandatory_skip = int(getattr(self, '_h22_kugou_host_uia_mandatory_skip', 0) or 0)
    if mandatory_skip > 0:
        self._h22_kugou_host_uia_mandatory_skip = max(0, mandatory_skip - 1)
        return None

    now = time.monotonic()
    fused_until = float(getattr(self, '_h22_kugou_host_uia_fused_until_mono', 0.0) or 0.0)
    if now < fused_until:
        last = float(getattr(self, '_h22_kugou_host_uia_fuse_log_mono', 0.0) or 0.0)
        if now - last >= 20.0:
            self._h22_kugou_host_uia_fuse_log_mono = now
            try:
                write_error_log('H22酷狗HostV2 UIA熔断保持', detail=(
                    f'hwnd={hwnd or prev_hwnd} | remaining={max(0.0, fused_until-now):.1f}s | '
                    f'reason={getattr(self, "_h22_kugou_host_uia_fuse_reason", "slow-provider")}'))
            except Exception:
                pass
        return None

    started = time.monotonic()
    out = _LIMBUS_H22_KUGOU_PROGRESS_PRE(self, status, local_position_hint=local_position_hint)
    elapsed_ms = (time.monotonic() - started) * 1000.0

    if out is not None:
        self._h22_kugou_host_uia_miss_streak = 0
    else:
        self._h22_kugou_host_uia_miss_streak = min(99, int(getattr(self, '_h22_kugou_host_uia_miss_streak', 0) or 0) + 1)

    fuse_sec = 0.0
    reason = ''
    if elapsed_ms >= float(H22_KUGOU_HOST_UIA_SLOW_MS):
        fuse_sec = float(H22_KUGOU_HOST_UIA_SLOW_FUSE_SEC)
        reason = f'slow-provider-{int(elapsed_ms)}ms'
    elif out is None and int(getattr(self, '_h22_kugou_host_uia_miss_streak', 0) or 0) >= int(H22_KUGOU_HOST_UIA_MISS_LIMIT):
        fuse_sec = float(H22_KUGOU_HOST_UIA_MISS_FUSE_SEC)
        reason = f'no-range-x{int(getattr(self, "_h22_kugou_host_uia_miss_streak", 0) or 0)}'

    if fuse_sec > 0.0:
        self._h22_kugou_host_uia_fused_until_mono = time.monotonic() + fuse_sec
        self._h22_kugou_host_uia_mandatory_skip = 1
        self._h22_kugou_host_uia_fuse_reason = reason
        self._h22_kugou_host_uia_fuse_log_mono = time.monotonic()
        try:
            write_error_log('H22酷狗HostV2 UIA熔断', detail=(
                f'hwnd={hwnd or prev_hwnd} | elapsed={elapsed_ms:.1f}ms | hit={int(out is not None)} | '
                f'miss_streak={int(getattr(self, "_h22_kugou_host_uia_miss_streak", 0) or 0)} | '
                f'fuse={int(fuse_sec)}s | reason={reason}'))
        except Exception:
            pass
    return out


MediaSessionSync._kugou_poll_uia_progress_v2 = _h22_kugou_progress_guard


