def _h22_enable_native_fault_trace():
    """Append Python thread stacks to the normal session log on fatal native/runtime faults."""
    global _H22_FAULT_HANDLE
    if _H22_FAULT_HANDLE is not None:
        return True
    try:
        import faulthandler
        path = _ensure_log_session()
        handle = open(path, 'a', encoding='utf-8', buffering=1)
        faulthandler.enable(file=handle, all_threads=True)
        _H22_FAULT_HANDLE = handle
        return True
    except Exception:
        return False


# H14 auto-precision deadline / bounded enhancement -----------------------------
# Real-world H10F4 logs showed a KuGou automatic precision upgrade surviving for
# ~205 seconds after the fast ordinary LRC was already visible.  The enhancement
# must never own transport authority and must not accumulate unbounded provider
# work.  Keep the original provider search intact and install a narrow outer
# budget only for KuGou precise searches launched by the automatic-lyrics worker.
H14_AUTO_KUGOU_PRECISE_BUDGET_SEC = 22.0
H14_AUTO_KUGOU_PRECISE_MAX_INFLIGHT = 2
H14_AUTO_KUGOU_UI_HINT_BUDGET_SEC = 1.25
_LIMBUS_H14_AUTO_PRECISE_SLOTS = threading.BoundedSemaphore(H14_AUTO_KUGOU_PRECISE_MAX_INFLIGHT)
_LIMBUS_H14_UI_HINT_SLOT = threading.BoundedSemaphore(1)
_LIMBUS_H14_LOCAL = threading.local()
_LIMBUS_H14_KUGOU_UI_HINT_PRE = LyricFetcher.get_kugou_ui_duration_hint


def _limbus_h14_kugou_ui_duration_hint(pids, song_name, max_nodes=640):
    if not bool(getattr(_LIMBUS_H14_LOCAL, 'auto_precise_active', False)):
        return _LIMBUS_H14_KUGOU_UI_HINT_PRE(pids, song_name, max_nodes=max_nodes)
    if not _LIMBUS_H14_UI_HINT_SLOT.acquire(blocking=False):
        _LIMBUS_H14_LOCAL.ui_hint_timeout = True
        try:
            write_error_log('自动歌词酷狗版本时长证据限流跳过', detail=(
                f'song={song_name} | max_inflight=1 | precise-upgrade=abort | fast-display=keep'))
        except Exception:
            pass
        return 0

    done = threading.Event()
    box = {}

    def probe():
        try:
            box['value'] = int(_LIMBUS_H14_KUGOU_UI_HINT_PRE(pids, song_name, max_nodes=max_nodes) or 0)
        except Exception as exc:
            box['error'] = exc
        finally:
            done.set()
            try:
                _LIMBUS_H14_UI_HINT_SLOT.release()
            except Exception:
                pass

    threading.Thread(
        target=probe, name='LimbusLyric-H14-KuGouDurationHint', daemon=True
    ).start()
    if not done.wait(float(H14_AUTO_KUGOU_UI_HINT_BUDGET_SEC)):
        _LIMBUS_H14_LOCAL.ui_hint_timeout = True
        try:
            write_error_log('自动歌词酷狗版本时长证据超时', detail=(
                f'song={song_name} | budget={int(H14_AUTO_KUGOU_UI_HINT_BUDGET_SEC*1000)}ms | '
                'precise-upgrade=abort | late-result=drop | fast-display=keep'))
        except Exception:
            pass
        return 0
    if box.get('error') is not None:
        return 0
    return int(box.get('value') or 0)


LyricFetcher.get_kugou_ui_duration_hint = staticmethod(_limbus_h14_kugou_ui_duration_hint)
_LIMBUS_H14_SEARCH_PRE = LyricSearchEngine.search


def _limbus_h14_auto_precise_search(
    song_name, artist="", source="网易云", trans_only=False,
    provider_track_id=None, provider_duration_ms=0, prefer_precise=True,
    provider_locked=False, require_translation_pair=False
):
    def call_previous_search():
        kwargs = {
            'provider_track_id': provider_track_id,
            'provider_duration_ms': provider_duration_ms,
            'prefer_precise': prefer_precise,
        }
        # Preserve the legacy call shape unless a new bilingual source-lock policy is
        # actually active. This keeps older provider/search adapters callable in single
        # language mode while still forwarding the policy when requested.
        if bool(provider_locked):
            kwargs['provider_locked'] = True
        if bool(require_translation_pair):
            kwargs['require_translation_pair'] = True
        return _LIMBUS_H14_SEARCH_PRE(song_name, artist, source, trans_only, **kwargs)

    thread_name = str(threading.current_thread().name or '')
    h14_auto_kugou_precise = bool(
        thread_name.startswith('LimbusLyric-AutoLyrics-g') and
        str(source or '') == '酷狗' and bool(prefer_precise) and not bool(trans_only)
    )
    if not h14_auto_kugou_precise:
        return call_previous_search()

    if not _LIMBUS_H14_AUTO_PRECISE_SLOTS.acquire(blocking=False):
        LyricSearchEngine.last_error = '酷狗：自动精准升级队列已满，已保留快速歌词'
        LyricSearchEngine._set_provider_meta(
            source='酷狗', lyric_payload_source='酷狗',
            h14_auto_precision_saturated=True,
            h14_auto_precision_budget_sec=float(H14_AUTO_KUGOU_PRECISE_BUDGET_SEC)
        )
        try:
            write_error_log('自动歌词精确升级限流保留快速歌词', detail=(
                f'song={song_name} | source=酷狗 | max_inflight={H14_AUTO_KUGOU_PRECISE_MAX_INFLIGHT} | '
                'provider-network=skip | fast-display=keep'))
        except Exception:
            pass
        return None, 0

    parent_cancel = getattr(LyricSearchEngine._cancel_local, 'fn', None)
    started = time.monotonic()
    deadline = started + float(H14_AUTO_KUGOU_PRECISE_BUDGET_SEC)
    _LIMBUS_H14_LOCAL.auto_precise_active = True
    _LIMBUS_H14_LOCAL.ui_hint_timeout = False

    def deadline_cancel():
        if time.monotonic() >= deadline:
            return True
        try:
            return bool(callable(parent_cancel) and parent_cancel())
        except Exception:
            return False

    try:
        LyricSearchEngine._set_cancel_check(deadline_cancel)
        lyric, duration = call_previous_search()
        parent_cancelled = False
        try:
            parent_cancelled = bool(callable(parent_cancel) and parent_cancel())
        except Exception:
            parent_cancelled = False
        elapsed = max(0.0, time.monotonic() - started)
        ui_hint_timeout = bool(getattr(_LIMBUS_H14_LOCAL, 'ui_hint_timeout', False))
        if ui_hint_timeout and not parent_cancelled:
            # H21: the bounded legacy UI proof may time out a few milliseconds before the
            # already-running Host-V2 rail publishes its current duration.  If the KRC has
            # now returned and a fresh Host-V2 duration for this exact title agrees within a
            # narrow tolerance, that is stronger evidence than blindly discarding the KRC.
            # With no such independent evidence the historical H14 drop remains unchanged.
            _h21_rescued = False
            try:
                _recent_fn = globals().get('_h21_recent_kugou_duration_hint')
                _host_duration = int(_recent_fn(song_name) or 0) if callable(_recent_fn) else 0
                _krc_duration = int(duration or 0)
                _tol = max(int(H21_KUGOU_DURATION_MATCH_MIN_MS) if 'H21_KUGOU_DURATION_MATCH_MIN_MS' in globals() else 1200,
                           int(max(_host_duration,_krc_duration) * (float(H21_KUGOU_DURATION_MATCH_RATIO) if 'H21_KUGOU_DURATION_MATCH_RATIO' in globals() else 0.012)))
                if lyric and _host_duration >= 5000 and _krc_duration >= 5000 and abs(_host_duration-_krc_duration) <= _tol:
                    _h21_rescued = True
                    ui_hint_timeout = False
                    try:
                        _meta = LyricSearchEngine.last_provider_meta()
                        _meta.update({
                            'h21_host_v2_duration_rescue': True,
                            'h21_host_v2_duration_ms': _host_duration,
                            'h21_krc_duration_ms': _krc_duration,
                        })
                        LyricSearchEngine._set_provider_meta(**_meta)
                    except Exception:
                        pass
                    try:
                        write_error_log('H21酷狗精准版本证据晚到救援', detail=(
                            f'song={song_name} | host={_host_duration}ms | krc={_krc_duration}ms | '
                            f'delta={abs(_host_duration-_krc_duration)}ms | ui-timeout=vetoed | apply=precise'))
                    except Exception:
                        pass
            except Exception:
                _h21_rescued = False
        if ui_hint_timeout and not parent_cancelled:
            LyricSearchEngine.last_error = '酷狗：自动精准升级的播放器版本时长证据读取超时，已保留快速歌词'
            LyricSearchEngine._set_provider_meta(
                source='酷狗', lyric_payload_source='酷狗',
                h14_auto_precision_ui_hint_timeout=True,
                h14_auto_precision_elapsed_ms=int(elapsed * 1000.0),
                h14_auto_precision_ui_hint_budget_sec=float(H14_AUTO_KUGOU_UI_HINT_BUDGET_SEC)
            )
            try:
                write_error_log('自动歌词精确升级版本证据超时保留快速歌词', detail=(
                    f'song={song_name} | source=酷狗 | elapsed={int(elapsed*1000.0)}ms | '
                    f'ui_hint_budget={int(H14_AUTO_KUGOU_UI_HINT_BUDGET_SEC*1000)}ms | '
                    'apply=drop | auto-cache=skip | fast-display=keep'))
            except Exception:
                pass
            return None, 0
        timed_out = bool(elapsed >= float(H14_AUTO_KUGOU_PRECISE_BUDGET_SEC) and not parent_cancelled)
        if timed_out:
            LyricSearchEngine.last_error = (
                f'酷狗：自动精准升级超过{int(H14_AUTO_KUGOU_PRECISE_BUDGET_SEC)}秒预算，已保留快速歌词'
            )
            LyricSearchEngine._set_provider_meta(
                source='酷狗', lyric_payload_source='酷狗',
                h14_auto_precision_timeout=True,
                h14_auto_precision_elapsed_ms=int(elapsed * 1000.0),
                h14_auto_precision_budget_sec=float(H14_AUTO_KUGOU_PRECISE_BUDGET_SEC)
            )
            try:
                write_error_log('自动歌词精确升级超时保留快速歌词', detail=(
                    f'song={song_name} | source=酷狗 | elapsed={int(elapsed*1000.0)}ms | '
                    f'budget={int(H14_AUTO_KUGOU_PRECISE_BUDGET_SEC*1000)}ms | '
                    'apply=drop | auto-cache=skip | fast-display=keep'))
            except Exception:
                pass
            return None, 0
        return lyric, duration
    finally:
        _LIMBUS_H14_LOCAL.auto_precise_active = False
        _LIMBUS_H14_LOCAL.ui_hint_timeout = False
        LyricSearchEngine._set_cancel_check(parent_cancel)
        try:
            _LIMBUS_H14_AUTO_PRECISE_SLOTS.release()
        except Exception:
            pass


LyricSearchEngine.search = staticmethod(_limbus_h14_auto_precise_search)


# Progressive keep-fast is valid only if the fast stage actually became the
# presentation owner.  A duration-rejected fast candidate may still exist in the
# worker local variable; treating that as "already on screen" would silently close
# a timed-out precise transaction with no lyric for the new track.
_LIMBUS_H14_AUTO_RESULT_PRE = ControlPanel._on_auto_lyric_result


def _limbus_h14_on_auto_lyric_result(self, result):
    patched = result
    try:
        if bool(result.get('progressive_keep_fast')):
            song = str(result.get('song') or '')
            artist = str(result.get('artist') or '')
            fast_is_owner = bool(
                song and self._same_track(
                    song, artist,
                    str(getattr(self, '_loaded_song', '') or ''),
                    str(getattr(self, '_loaded_artist', '') or '')
                )
            )
            if not fast_is_owner:
                patched = dict(result)
                patched['progressive_keep_fast'] = False
                if not str(patched.get('error') or '').strip():
                    patched['error'] = '精确增强结束，但快速歌词未通过当前曲目验证'
                try:
                    write_error_log('自动歌词保留快速歌词所有权拒绝', detail=(
                        f'song={song} | loaded={getattr(self,"_loaded_song","")} | '
                        'fast-display-owner=0 | action=normal-failure-close'))
                except Exception:
                    pass
    except Exception as exc:
        try:
            write_error_log('H14自动歌词快速所有权检查失败', exc)
        except Exception:
            pass
    return _LIMBUS_H14_AUTO_RESULT_PRE(self, patched)


ControlPanel._on_auto_lyric_result = _limbus_h14_on_auto_lyric_result







# H27 player-clock epoch / Win10 visual / KuGou Win11 closure --------------------
# Field evidence from H26 showed two distinct failures:
# - Win10 NetEase: zero-operation window discovery depended on process enumeration and
#   the permissive edge shortlist never promoted a stable physical rail.
# - Win11 KuGou: a previous track's local rail was accepted as the next track's
#   provisional origin, while H22 counted a legitimate HostV2 proof-pending None as a
#   capability miss and fused the provider for 90 seconds.
# Keep historical implementations byte-stable and install this final outer closure last.
# H14/H16 historical replay extractors execute this tail with minimal fake classes.
# Install H27 only in the real runtime where its owning classes already exist.
if 'MediaSessionSync' in globals() and 'ControlPanel' in globals():
    H27_KUGOU_NEW_TRACK_HOLD_MS = 2800.0
    H27_NETEASE_RECT_TTL_MS = 2200.0
    _LIMBUS_H27_BIND_TRACK_PRE = MediaSessionSync.bind_track
    _LIMBUS_H27_KUGOU_PROGRESS_PRE = MediaSessionSync._kugou_poll_uia_progress_v2
    _LIMBUS_H27_RESTORE_PRE = ControlPanel._restore_qq_suspended_loaded_track
    _LIMBUS_H27_NETEASE_RECT_PRE = _h25_netease_window_rect


    def _h27_windows_build_number():
        try:
            _sys = __import__('sys')
            return int(_sys.getwindowsversion().build or 0) if hasattr(_sys, 'getwindowsversion') else 0
        except Exception:
            return 0


    def _h27_is_win11_kugou(sync=None):
        try:
            _sys = __import__('sys')
            if not _sys.platform.startswith('win') or _h27_windows_build_number() < 22000:
                return False
            if sync is None:
                return True
            return str(sync._process_stem(getattr(sync, '_process_hint', ''))) in ('kgmusic','kugou')
        except Exception:
            return False


    def _h27_new_track_key(song, artist=''):
        return f"{_clean_name(song)}|{_clean_name(artist)}"


    def _h27_bind_track_epoch_barrier(self, song, artist='', duration_ms=0, auto_provisional=False,
                                        initial_position_ms=0, netease_track_id=None, startup_existing=False):
        process_stem = str(self._process_stem(getattr(self, '_process_hint', '')) or '')
        new_key = _h27_new_track_key(song, artist)
        old_key = str(getattr(self, '_track_key', '') or '')
        different = bool(new_key and new_key != old_key)
        if process_stem in ('kgmusic','kugou') and different:
            # New identity is a hard evidence epoch. A previous song's rail/local/UIA proof may
            # remain useful for geometry discovery, but it must never provide the next song's time.
            try: self._reset_kugou_rail_local_master()
            except Exception: pass
            for attr in ('_kugou_host_v2_progress_pending','_kugou_host_v2_progress_trusted_key',
                         '_kugou_range_track_switch_pending','_kugou_visual_rail_pending',
                         '_kugou_seek_candidate','_kugou_numeric_pending'):
                try: setattr(self, attr, None if attr != '_kugou_host_v2_progress_trusted_key' else '')
                except Exception: pass
            if bool(auto_provisional):
                # Never convert an old-track rail estimate into the new track's initial position.
                initial_position_ms = min(max(0, int(initial_position_ms or 0)), 2500)
            try:
                write_error_log('H27酷狗新曲时钟证据代际隔离', detail=(
                    f'old={old_key or "<none>"} | new={new_key} | provisional={int(bool(auto_provisional))} | '
                    f'initial={int(initial_position_ms or 0)}ms | old-rail-authority=revoked'))
            except Exception: pass
        return _LIMBUS_H27_BIND_TRACK_PRE(
            self, song, artist, duration_ms, auto_provisional=auto_provisional,
            initial_position_ms=initial_position_ms, netease_track_id=netease_track_id,
            startup_existing=startup_existing)


    MediaSessionSync.bind_track = _h27_bind_track_epoch_barrier

    # H26's source set was intentionally broad, but KuGou field logs proved that local-master
    # can still describe the previous track at the instant a new GSMTC identity arrives.
    try:
        H26_TRANSITION_STRONG_POSITION_SOURCES.discard('kugou-rail-local-master')
    except Exception:
        pass


    def _h27_kugou_progress_guard(self, status='unknown', local_position_hint=None):
        if _h27_is_win11_kugou(self):
            # On Win11 use the accumulated pre-H22 provider implementation directly. Its None can
            # mean "proof pending"; do not reinterpret it as a capability miss and start a 90s fuse.
            try:
                out = _LIMBUS_H22_KUGOU_PROGRESS_PRE(self, status, local_position_hint=local_position_hint)
                if out is None and isinstance(getattr(self, '_kugou_host_v2_progress_pending', None), dict):
                    self._h22_kugou_host_uia_miss_streak = 0
                    self._h22_kugou_host_uia_fused_until_mono = 0.0
                return out
            except Exception:
                return None
        return _LIMBUS_H27_KUGOU_PROGRESS_PRE(self, status, local_position_hint=local_position_hint)


    MediaSessionSync._kugou_poll_uia_progress_v2 = _h27_kugou_progress_guard


    def _h27_restore_suspended_track(self, song, artist=''):
        try:
            if str(self.player_combo.currentText() or '') == '酷狗音乐':
                sync = self.media_sync
                now = time.monotonic() * 1000.0
                hint_mono = float(getattr(sync, '_kugou_identity_transport_hint_mono', 0.0) or 0.0)
                target = str(getattr(self, '_auto_target_key', '') or '')
                loaded = str(getattr(self, '_loaded_track_key', '') or '')
                requested = _h27_new_track_key(song, artist)
                if (0.0 <= now-hint_mono <= H27_KUGOU_NEW_TRACK_HOLD_MS and target and
                        target != loaded and requested == loaded):
                    try:
                        write_error_log('H27酷狗新曲事务阻止旧歌词恢复', detail=(
                            f'loaded={loaded} | target={target} | hint_age={int(now-hint_mono)}ms | '
                            'host-lag=hold | presentation-owner=new-track'))
                    except Exception: pass
                    return False
        except Exception:
            pass
        return _LIMBUS_H27_RESTORE_PRE(self, song, artist)


    ControlPanel._restore_qq_suspended_loaded_track = _h27_restore_suspended_track


    def _h27_win32_process_window_rect(exe_name):
        if os.name != 'nt':
            return None
        try:
            from ctypes import wintypes as _wt
            user32 = ctypes.windll.user32; kernel32 = ctypes.windll.kernel32
            target = str(exe_name or '').lower()
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            GW_OWNER = 4
            rows=[]
            EnumProc = ctypes.WINFUNCTYPE(ctypes.c_bool, _wt.HWND, _wt.LPARAM)
            def cb(hwnd, lparam):
                try:
                    if not user32.IsWindowVisible(hwnd) or user32.GetWindow(hwnd, GW_OWNER): return True
                    pid=_wt.DWORD(); user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                    if not pid.value: return True
                    h=kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid.value)
                    if not h: return True
                    try:
                        n=_wt.DWORD(32768); buf=ctypes.create_unicode_buffer(32768)
                        if not kernel32.QueryFullProcessImageNameW(h,0,buf,ctypes.byref(n)): return True
                        if os.path.basename(buf.value).lower()!=target: return True
                    finally: kernel32.CloseHandle(h)
                    rc=_wt.RECT()
                    if not user32.GetWindowRect(hwnd,ctypes.byref(rc)): return True
                    w=rc.right-rc.left; hh=rc.bottom-rc.top
                    if w>=360 and hh>=220: rows.append((w*hh,(rc.left,rc.top,rc.right,rc.bottom)))
                except Exception: pass
                return True
            user32.EnumWindows(EnumProc(cb),0)
            return max(rows,key=lambda x:x[0])[1] if rows else None
        except Exception:
            return None


    def _h27_netease_window_rect(self):
        try:
            if _h26_netease_win10_safe_profile(self):
                now=time.monotonic()*1000.0
                cached=getattr(self,'_h25_netease_window_rect_cache',None)
                stamp=float(getattr(self,'_h25_netease_window_rect_mono',0.0) or 0.0)
                if isinstance(cached,(tuple,list)) and len(cached)==4 and now-stamp<=H27_NETEASE_RECT_TTL_MS:
                    return tuple(int(v) for v in cached)
                rect=_h27_win32_process_window_rect('cloudmusic.exe')
                if rect:
                    self._h25_netease_window_rect_cache=tuple(rect); self._h25_netease_window_rect_mono=now
                    return tuple(rect)
        except Exception: pass
        return _LIMBUS_H27_NETEASE_RECT_PRE(self)


    _h25_netease_window_rect = _h27_netease_window_rect


    def _h27_quant_rgb(rgb):
        return tuple(int(v)//24 for v in rgb[:3])


    def _h27_netease_static_rail_candidates(self, frame, window_width):
        # A real playback rail is a long, thin, mostly two-colour run with one dominant fill
        # boundary. Reject text/separators that merely contain many unrelated high-contrast edges.
        if not isinstance(frame,dict) or not frame.get('data'): return []
        try: w,h=int(frame['w']),int(frame['h']); fw=float(window_width or w)
        except Exception: return []
        if w<220 or h<8: return []
        out=[]
        for y in range(2,h-2,2):
            samples=[]
            for x in range(10,w-10,2):
                try: samples.append((x,self._kugou_visual_rgb(frame,x,y)))
                except Exception: pass
            if len(samples)<80: continue
            # Sliding continuous run: adjacent pixels should usually be similar; allow one major jump.
            run=[]; best=[]
            for item in samples:
                if not run:
                    run=[item]; continue
                d=_h26_rgb_distance(run[-1][1],item[1])
                if d<=34 or len(run)<8:
                    run.append(item)
                else:
                    if len(run)>len(best): best=run
                    run=[item]
            if len(run)>len(best): best=run
            if len(best)*2 < max(180,int(fw*0.30)): continue
            # Instead of one uniform run, inspect a wide row interval for exactly one persistent colour transition.
            xs=[x for x,_ in samples]; rgbs=[c for _,c in samples]
            q=[_h27_quant_rgb(c) for c in rgbs]
            from collections import Counter
            common=Counter(q).most_common(4)
            if len(common)<2: continue
            c1,c2=common[0][0],common[1][0]
            valid=[i for i,v in enumerate(q) if v==c1 or v==c2]
            if len(valid)<int(len(q)*0.55): continue
            lo,hi=min(valid),max(valid)
            if (hi-lo)*2 < max(180,int(fw*0.30)): continue
            seq=[q[i] for i in range(lo,hi+1) if q[i] in (c1,c2)]
            if len(seq)<60: continue
            transitions=sum(1 for a,b in zip(seq,seq[1:]) if a!=b)
            if transitions<1 or transitions>5: continue
            # Find the dominant split minimizing misclassified colours on both sides.
            best_split=None; best_err=10**9
            for k in range(8,len(seq)-8):
                left=seq[:k]; right=seq[k:]
                lc=Counter(left).most_common(1)[0][0]; rc=Counter(right).most_common(1)[0][0]
                if lc==rc: continue
                err=sum(v!=lc for v in left)+sum(v!=rc for v in right)
                if err<best_err: best_err=err; best_split=k
            if best_split is None or best_err>len(seq)*0.18: continue
            x0=float(frame['x'])+float(xs[lo]); x1=float(frame['x'])+float(xs[hi])
            boundary=float(frame['x'])+float(xs[min(hi,lo+best_split)])
            ratio=(boundary-x0)/max(1.0,x1-x0)
            if not 0.004<ratio<0.996: continue
            score=(x1-x0)-best_err*4.0
            out.append({'score':score,'x0':x0,'x1':x1,'y':float(frame['y'])+float(y),
                        'rail_w':x1-x0,'color_sep':48,'boundary_x':boundary})
        out.sort(key=lambda r:r['score'],reverse=True)
        ded=[]
        for r in out:
            if any(abs(r['y']-p['y'])<=6 and abs(r['x0']-p['x0'])<=30 and abs(r['x1']-p['x1'])<=30 for p in ded):
                continue
            ded.append(r)
            if len(ded)>=4: break
        return ded


    _h26_netease_static_rail_candidates = _h27_netease_static_rail_candidates


# H28 unified evidence epoch / seek observer / Win10 clock closure ----------------
# H27 field replay exposed that transport epoch isolation alone was insufficient:
# KuGou's lyric renderer could still retain the previous track position, duration-unknown
# cache entries could select a wrong same-name version, the Win10 safe path could lose the
# player rectangle and therefore never consume real WH_MOUSE_LL rail events, and NetEase
# could remain proof-pending while liveness repeatedly fell through to slow tasklist probes.
# H28 is a final outer layer: historical H1-H27 methods remain source-locked.
if 'MediaSessionSync' in globals() and 'ControlPanel' in globals() and 'LyricWindow' in globals():
    H28_KUGOU_EPOCH_FRESH_MS = 4200.0
    H28_KUGOU_SAFE_RAIL_Y_RATIO = 0.895
    H28_KUGOU_SAFE_RAIL_X0_RATIO = 0.035
    H28_KUGOU_SAFE_RAIL_X1_RATIO = 0.965
    H28_NETEASE_H26_PENDING_FALLBACK_MS = 2600.0

    _LIMBUS_H28_RECORD_LOADED_PRE = ControlPanel._record_loaded_track
    _LIMBUS_H28_PRECISE_UPGRADE_PRE = LyricWindow.upgrade_lyric_timeline_preserve_visual
    _LIMBUS_H28_CACHE_LOAD_PRE = ControlPanel._load_auto_lyric_cache_from_disk
    _LIMBUS_H28_AUTO_SEARCH_PRE = ControlPanel._start_auto_search_job
    _LIMBUS_H28_KUGOU_RECT_PRE = MediaSessionSync._kugou_window_rect
    _LIMBUS_H28_KUGOU_COMMIT_PRE = MediaSessionSync._kugou_commit_gesture_seek
    _LIMBUS_H28_NCM_VISUAL_PRE = MediaSessionSync._h25_poll_netease_safe_visual_clock
    _LIMBUS_H28_LIVENESS_PRE = _limbus_bounded_player_liveness_probe

    def _h28_kugou_selected(panel):
        try:
            return str(panel.player_combo.currentText() or '') == '酷狗音乐'
        except Exception:
            return False

    def _h28_reset_lyric_epoch(panel, song, artist='', reason='new-track'):
        """Retire every renderer-side position witness before a new KuGou payload can hand off."""
        try:
            lw = panel.lyric_window
        except Exception:
            return False
        now = time.monotonic() * 1000.0
        try:
            sync = panel.media_sync
            snap = sync.snapshot() or {}
            media_key = str(getattr(sync, '_track_key', '') or '')
            expected = panel._track_identity(song, artist)
            pos = snap.get('position_ms') if media_key and expected == media_key else None
            if pos is not None:
                pos = max(0, int(pos))
        except Exception:
            sync = None; pos = None; expected = ''
        # Position/handoff/history are one evidence epoch. Geometry/style caches are not.
        for attr, value in (
            ('_last_position_ms', pos), ('_last_sync_seek_serial', None),
            ('_precision_handoff_pending', None), ('_precision_handoff_visible_floor', None),
            ('_precision_handoff_last_reason', ''), ('displayed_line_index', -1),
            ('current_line', 0), ('full_text', ''), ('char_index', 0),
            ('fading_lines', []), ('history_lines', []), ('_placement_recent', []),
            ('_stale_progress_position_ms', None), ('_last_visual_seek_mono', 0.0),
        ):
            try: setattr(lw, attr, value)
            except Exception: pass
        lw._h28_media_sync_ref = sync
        lw._h28_track_key = expected
        lw._h28_epoch_started_mono = now
        lw._h28_epoch_serial = int(getattr(lw, '_h28_epoch_serial', 0) or 0) + 1
        try:
            write_error_log('H28酷狗歌词显示时钟代际隔离', detail=(
                f'track={expected or "<none>"} | fresh_position={"none" if pos is None else int(pos)}ms | '
                f'reason={reason} | handoff=cleared | history=cleared'))
        except Exception: pass
        return True

    def _h28_record_loaded_track(self, song, artist='', source=None):
        old_song = str(getattr(self, '_loaded_song', '') or '')
        old_artist = str(getattr(self, '_loaded_artist', '') or '')
        different = bool(song and (not old_song or not self._same_track(song, artist, old_song, old_artist)))
        if _h28_kugou_selected(self) and different:
            _h28_reset_lyric_epoch(self, song, artist, reason='record-loaded-track')
        return _LIMBUS_H28_RECORD_LOADED_PRE(self, song, artist, source)

    ControlPanel._record_loaded_track = _h28_record_loaded_track

    def _h28_precision_upgrade(self, text):
        # During the first seconds of a newly bound KuGou epoch, refresh the renderer position
        # from MediaSync immediately before precision handoff. This closes the observed
        # 202ms transport / 9152ms renderer split without disabling seamless upgrades later.
        try:
            now = time.monotonic() * 1000.0
            started = float(getattr(self, '_h28_epoch_started_mono', 0.0) or 0.0)
            sync = getattr(self, '_h28_media_sync_ref', None)
            if sync is not None and 0.0 <= now-started <= H28_KUGOU_EPOCH_FRESH_MS:
                snap = sync.snapshot() or {}
                pos = snap.get('position_ms')
                self._last_position_ms = None if pos is None else max(0, int(pos))
                self._precision_handoff_pending = None
                self._precision_handoff_visible_floor = None
                self._precision_handoff_last_reason = 'h28-track-epoch'
        except Exception:
            pass
        return _LIMBUS_H28_PRECISE_UPGRADE_PRE(self, text)

    LyricWindow.upgrade_lyric_timeline_preserve_visual = _h28_precision_upgrade

    def _h28_purge_unsafe_kugou_zero_duration_cache(self, target_key=''):
        removed = 0
        try:
            with self._auto_lyric_cache_lock:
                for key in list(self._auto_lyric_cache.keys()):
                    if not isinstance(key, tuple) or len(key) < 6 or str(key[0]) != '酷狗':
                        continue
                    try: zero_duration = int(key[-1] or 0) <= 0
                    except Exception: zero_duration = False
                    if not zero_duration:
                        continue
                    if target_key and str(key[3] or '') != str(target_key):
                        continue
                    self._auto_lyric_cache.pop(key, None); removed += 1
            if removed:
                try:
                    write_error_log('H28酷狗未知时长缓存已撤权', detail=(
                        f'removed={removed} | track={target_key or "all"} | reason=same-name-version-unsafe'))
                except Exception: pass
        except Exception:
            return 0
        return removed

    def _h28_cache_load(self):
        out = _LIMBUS_H28_CACHE_LOAD_PRE(self)
