    def _h28_kugou_win10_safe(sync):
        try:
            _sys = __import__('sys')
            return bool(_sys.platform.startswith('win') and _h27_windows_build_number() < 22000 and
                        bool(getattr(_sys, 'frozen', False)) and
                        str(sync._process_stem(getattr(sync, '_process_hint', ''))) in ('kgmusic','kugou'))
        except Exception:
            return False

    def _h28_win32_kugou_host_rect():
        """Pure Win32/DWM KuGou host discovery; no Toolhelp/tasklist/UIA/COM."""
        if os.name != 'nt':
            return None
        try:
            from ctypes import wintypes as _wt
            user32 = ctypes.windll.user32
            dwmapi = ctypes.windll.dwmapi
            DWMWA_EXTENDED_FRAME_BOUNDS = 9
            rows = []
            EnumProc = ctypes.WINFUNCTYPE(ctypes.c_bool, _wt.HWND, _wt.LPARAM)
            def cb(hwnd, _lp):
                try:
                    if not user32.IsWindowVisible(hwnd): return True
                    cls = ctypes.create_unicode_buffer(256)
                    user32.GetClassNameW(hwnd, cls, 255)
                    clsname = str(cls.value or '')
                    if clsname.lower() != 'kugou_ui': return True
                    n = user32.GetWindowTextLengthW(hwnd)
                    title = ctypes.create_unicode_buffer(max(2, n+2))
                    user32.GetWindowTextW(hwnd, title, len(title))
                    rr = _wt.RECT()
                    hr = dwmapi.DwmGetWindowAttribute(_wt.HWND(int(hwnd)), DWMWA_EXTENDED_FRAME_BOUNDS,
                                                      ctypes.byref(rr), ctypes.sizeof(rr))
                    if int(hr) != 0:
                        if not user32.GetWindowRect(hwnd, ctypes.byref(rr)): return True
                    rect = (int(rr.left), int(rr.top), int(rr.right), int(rr.bottom))
                    score = _kugou_host_candidate_score(clsname, title.value, rect, True, False)
                    if score > 0: rows.append((score, max(0,rect[2]-rect[0])*max(0,rect[3]-rect[1]), rect))
                except Exception:
                    pass
                return True
            user32.EnumWindows(EnumProc(cb), 0)
            if not rows: return None
            rows.sort(reverse=True)
            return tuple(rows[0][2])
        except Exception:
            return None

    def _h28_publish_kugou_seek_geometry(self, rect, source='win32-host'):
        try:
            l,t,r,b=[float(v) for v in rect]; w=max(1.0,r-l); h=max(1.0,b-t)
            self._kugou_physical_rect_cache=tuple(int(v) for v in rect)
            self._kugou_physical_rect_cache_mono=time.monotonic()*1000.0
            try: self._uia_reader._kugou_last_main_rect=tuple(int(v) for v in rect)
            except Exception: pass
            learned=getattr(self,'_kugou_visual_rail_bounds',None)
            if not (isinstance(learned,(tuple,list)) and len(learned)==2):
                self._kugou_visual_rail_bounds=(l+w*H28_KUGOU_SAFE_RAIL_X0_RATIO, l+w*H28_KUGOU_SAFE_RAIL_X1_RATIO)
                self._kugou_rail_y=t+h*H28_KUGOU_SAFE_RAIL_Y_RATIO
                if time.monotonic()*1000.0-float(getattr(self,'_h28_kugou_geom_log_mono',0.0) or 0.0)>=5000.0:
                    self._h28_kugou_geom_log_mono=time.monotonic()*1000.0
                    try:
                        write_error_log('H28酷狗Win10进度条观察几何就绪',detail=(
                            f'rect={tuple(int(v) for v in rect)} | rail=({int(l+w*H28_KUGOU_SAFE_RAIL_X0_RATIO)},'
                            f'{int(self._kugou_rail_y)})->({int(l+w*H28_KUGOU_SAFE_RAIL_X1_RATIO)},{int(self._kugou_rail_y)}) | '
                            f'source={source} | authority=geometry-only'))
                    except Exception: pass
        except Exception:
            pass

