        _LIMBUS_H41_KUGOU_VISUAL_PRE=MediaSessionSync._kugou_poll_visual_rail_anchor
        def _r2_kugou_visual_holdover(sync):
            try:
                now=time.monotonic()*1000.0
                if sync._process_stem(getattr(sync,'_process_hint',''))!='kgmusic':
                    return False
                if not bool(getattr(sync,'_kugou_rail_master_active',False)):
                    return False
                track=str(getattr(sync,'_track_key','') or '')
                if str(getattr(sync,'_kugou_rail_master_track_key','') or '')!=track:
                    return False
                if int(getattr(sync,'_kugou_rail_master_player_epoch',-1))!=int(getattr(sync,'_media_player_epoch',0) or 0):
                    return False
                if int(getattr(sync,'_kugou_rail_master_identity_epoch',-1))!=int(getattr(sync,'_track_identity_epoch',0) or 0):
                    return False
                gesture=float(getattr(sync,'_kugou_last_gesture_mono',0.0) or 0.0)
                if gesture>0.0 and now-gesture<=2600.0:
                    return False
                generation=int(getattr(sync,'_kugou_transport_generation',0) or 0)
                q_until=float(getattr(sync,'_r2_kugou_visual_quarantine_until_mono',0.0) or 0.0)
                q_gen=int(getattr(sync,'_r2_kugou_visual_quarantine_generation',-1) or -1)
                q_track=str(getattr(sync,'_r2_kugou_visual_quarantine_track_key','') or '')
                if now<q_until and q_gen==generation and (not q_track or q_track==track):
                    return True
                reason=str(getattr(sync,'_kugou_rail_master_reason','') or '')
                authoritative={
                    'host-uia-range-v2','host-uia-same-track-restart','user-rail-gesture','rail-gesture',
                    'h40-authorized-pending-gesture','transport-edge-local','identity-transport-local',
                    'same-title-play-instance-restart'
                }
                if reason not in authoritative:
                    return False
                # After a trusted physical anchor or an explicit transport edge, background
                # playback is a monotonic holdover problem, not a reason to keep screenshot-
                # sampling a stale visual rail. Periodically allow re-observation after 30s.
                host_seen=float(getattr(sync,'_kugou_host_v2_progress_last_success_mono',0.0) or 0.0)
                gen_seen=float(getattr(sync,'_kugou_transport_generation_mono',0.0) or 0.0)
                reference=max(host_seen,gen_seen,float(getattr(sync,'_kugou_rail_master_last_gesture_sync_mono',0.0) or 0.0))
                return bool(reference>0.0 and now-reference<=30000.0)
            except Exception:
                return False

        def _h41_kugou_visual(sync,status_hint=None,local_position_hint=None):
            if _r2_kugou_visual_holdover(sync):
                now=time.monotonic()*1000.0
                last=float(getattr(sync,'_r2_kugou_holdover_log_mono',0.0) or 0.0)
                if now-last>=8000.0:
                    sync._r2_kugou_holdover_log_mono=now
                    try: write_error_log('R2酷狗后台时钟Holdover',detail=(
                        f'position={int(float(local_position_hint or getattr(sync,"_kugou_rail_master_position_ms",0) or 0))}ms | '
                        f'reason={str(getattr(sync,"_kugou_rail_master_reason","") or "unknown")} | '
                        f'transport_generation={int(getattr(sync,"_kugou_transport_generation",0) or 0)} | '
                        'visual-rail=poll-suppressed | authority=local-monotonic'))
                    except Exception: pass
                return False
            out=_LIMBUS_H41_KUGOU_VISUAL_PRE(sync,status_hint=status_hint,local_position_hint=local_position_hint)
            try:
                if _h37_kugou_win10_safe(sync) and (_h38_kugou_owned_duration(sync) if '_h38_kugou_owned_duration' in globals() else 0)<5000 and '_h30_visual_state' in globals():
                    candidate=int(getattr(sync,'_h38_kugou_lyric_duration_candidate_ms',0) or 0)
                    if candidate>=5000 and str(getattr(sync,'_h38_kugou_lyric_duration_candidate_track','') or '')==str(getattr(sync,'_track_key','') or ''):
                        now=time.monotonic()*1000.0; hist=list(getattr(sync,'_h41_kugou_fragment_history',[]) or [])
                        for row in list((_h30_visual_state(sync,'kugou') or {}).get('proofs') or []):
                            try:
                                hits=int(row.get('hits') or 0); span=float(row.get('span') or 0.0); advance=float(row.get('advance') or 0.0); last=float(row.get('last_mono') or 0.0); ratio=float(row.get('ratio') or 0.0)
                            except Exception: continue
                            if hits<2 or span<650.0 or advance<=60.0 or last<=0.0: continue
                            pace=advance/max(1.0,span); est=float(candidate)/pace if pace>0 else 0.0
                            if not (H38_KUGOU_VISUAL_DURATION_MIN_MS<=est<=H38_KUGOU_VISUAL_DURATION_MAX_MS): continue
                            sig=(int(last//150),int(round(est/250.0)))
                            if not any(tuple(x.get('sig') or ())==sig for x in hist):
                                hist.append({'sig':sig,'duration':est,'mono':last,'ratio':max(0.0,min(1.0,ratio))})
                        hist=[x for x in hist[-24:] if now-float(x.get('mono') or 0.0)<=H41_KUGOU_FRAGMENT_HISTORY_TTL_MS]
                        sync._h41_kugou_fragment_history=hist
                        consensus=_h41_kugou_fragment_history_consensus(candidate,hist,now)
                        if consensus is not None:
                            duration=int(round(float(consensus['duration_ms'])/100.0)*100)
                            if _h38_accept_kugou_player_duration(sync,duration,source='host-rail-persistent-fragment-consensus',position_ratio=float(consensus['ratio']),now_ms=now):
                                sync._h41_kugou_fragment_history=[]
                                write_error_log('H41酷狗Win10跨重置碎片Rail时长确认',detail=(
                                    f'duration={duration}ms | samples={int(consensus["samples"])} | span={int(consensus["span_ms"])}ms | authority=player-rail-motion-history'))
            except Exception: pass
            return out
        MediaSessionSync._kugou_poll_visual_rail_anchor=_h41_kugou_visual
        MediaSessionSync._kugou_poll_visual_rail_anchor._limbus_layer='H41'

