                panel.h51_center_slider.setValue(max(0, min(100, int(st.get('h51_center_frequency_pct', H51_CENTER_FREQ_DEFAULT) or H51_CENTER_FREQ_DEFAULT))))
                panel.h51_center_label = QLabel(f'{panel.h51_center_slider.value()}%')
                center_row.addWidget(panel.h51_center_slider, 1); center_row.addWidget(panel.h51_center_label); v.addLayout(center_row)
                panel.h51_center_slider.setToolTip('0% 会尽量避开屏幕中央约 40%×44% 的区域；100% 保持原来的均衡随机布局。碰撞安全优先，因此极端拥挤时仍允许中央作为降级位置。')

                base_size = max(6, min(300, int(st.get('font_size', panel.font_size.value()) or panel.font_size.value())))
                min_size = max(6, min(300, int(st.get('h51_font_min_pt', base_size) or base_size)))
                max_size = max(min_size, min(300, int(st.get('h51_font_max_pt', base_size) or base_size)))
                panel.h51_size_range_check = QCheckBox('启用每行字号范围')
                panel.h51_size_range_check.setChecked(bool(st.get('h51_size_range_enabled', False)))
                panel.h51_size_range_check.setToolTip('默认关闭：完全跟随原来的“字体大小”。开启后才在下面的最小/最大字号之间按歌词行选择。')
                v.addWidget(panel.h51_size_range_check)
                size_row = QHBoxLayout(); size_row.addWidget(QLabel('每行字号范围：'))
                panel.h51_size_min = QSpinBox(); panel.h51_size_min.setRange(6, 300); panel.h51_size_min.setSuffix(' pt'); panel.h51_size_min.setValue(min_size)
                panel.h51_size_max = QSpinBox(); panel.h51_size_max.setRange(6, 300); panel.h51_size_max.setSuffix(' pt'); panel.h51_size_max.setValue(max_size)
                panel.h51_size_min.setEnabled(panel.h51_size_range_check.isChecked()); panel.h51_size_max.setEnabled(panel.h51_size_range_check.isChecked())
