# H58 style/depth material coherence ----------------------------------------------------------
# H57 correctly bakes text + outline + shadow + glow when the Song Atlas style matches.
# Legacy live edge/glow controls, however, mutate current/history style fields immediately
# without rebuilding that Atlas. The signature mismatch forces sprite/vector fallback, which
# reintroduces a hard outline/glow and can even trip the expensive vector emergency renderer.
# H58 makes decorative style an immutable row-birth material. User edits are coalesced and
# prewarmed; they commit only at a lyric boundary once the matching Atlas is actually ready.
H58_STYLE_PREWARM_DEBOUNCE_MS = 180


def _h58_material_snapshot(panel):
    lw = getattr(panel, 'lyric_window', None)
    if lw is None:
        return None
    try:
        _font, _text, resolved_glow = panel._resolved_active_visual_style()
    except Exception:
        resolved_glow = QColor(getattr(lw, 'glow_color', QColor('#ffffff')))
    try:
        return {
            'shadow_enabled': bool(panel.shadow_check.isChecked()),
            'shadow_color': QColor(panel.current_shadow_color),
            'outline_enabled': bool(panel.outline_check.isChecked()),
            'stroke_color': QColor(panel.current_stroke_color),
            'stroke_width': float(panel.stroke_spin.value()),
            'glow_enabled': bool(panel.glow_check.isChecked()),
            'glow_color': QColor(resolved_glow),
            'glow_size': int(panel.glow_size_slider.value()),
            'glow_alpha': int(panel.glow_alpha_slider.value()),
        }
    except Exception:
        return None


def _h58_visual_payload(window, material, visual_style=None):
    if not isinstance(material, dict):
        return None
    try:
        if visual_style is None:
            visual_style = getattr(window, '_pending_visual_style', None)
        if visual_style:
            font, text_color, glow_color = visual_style
        else:
            font, text_color, glow_color = window.font, window.text_color, window.glow_color
        return {
            '_h58_material': True,
            'font': QFont(font),
            'text_color': QColor(text_color),
            'glow_color': QColor(material.get('glow_color', glow_color)),
            **material,
        }
    except Exception:
        return None


def _h58_apply_material(window, material):
    if not isinstance(material, dict):
        return False
    try:
        window.shadow_enabled = bool(material['shadow_enabled'])
        window.shadow_color = QColor(material['shadow_color'])
        window.outline_enabled = bool(material['outline_enabled'])
        window.stroke_color = QColor(material['stroke_color'])
        window.stroke_width = float(material['stroke_width'])
        window.glow = bool(material['glow_enabled'])
        window.glow_color = QColor(material['glow_color'])
        window.glow_size = int(material['glow_size'])
        window.glow_alpha = int(material['glow_alpha'])
        window._h57_depth_composite_cache = None
        return True
    except Exception:
        return False


def _h58_material_key(window, material, visual_style=None):
    payload = _h58_visual_payload(window, material, visual_style)
    if payload is None:
        return None
    try:
        _chars, key = window._song_fragment_chars_and_key(payload)
        return key
    except Exception:
        return None


def _h58_material_ready(window, material, visual_style=None):
    key = _h58_material_key(window, material, visual_style)
    if key is None:
        return False
    try:
        if key == getattr(window, '_song_fragment_atlas_key', None):
            return getattr(window, '_song_fragment_atlas_pixmap', None) is not None
        cache = getattr(window, '_song_fragment_atlas_cache', None)
        return isinstance(cache, OrderedDict) and key in cache
    except Exception:
        return False


def _h58_prewarm_material(panel):
    lw = getattr(panel, 'lyric_window', None)
    material = getattr(lw, '_h58_pending_material', None) if lw is not None else None
    if lw is None or not isinstance(material, dict) or not getattr(lw, 'lyric_timeline', None):
        return None
    payload = _h58_visual_payload(lw, material, getattr(lw, '_pending_visual_style', None))
    if payload is None:
        return None
    try:
        # The old full-song fuse is a precomputation safety barrier, not permission to make a
        # user's explicit style switch permanently lose depth. Give an explicit coalesced edit
        # one below-normal-priority retry. If it hits the budget again, H58 keeps the old row
        # material instead of committing to a sharp vector fallback.
        if bool(getattr(lw, '_song_fragment_atlas_performance_fused', False)):
            lw._song_fragment_atlas_performance_fused = False
            lw._song_fragment_atlas_fuse_reason = 'h58-explicit-style-retry'
        mode = lw._schedule_song_fragment_atlas(visual_style=payload, prewarm_only=True)
        try:
            write_error_log('H58样式景深材质预热', detail=(
                f'mode={mode} | outline={int(bool(material.get("outline_enabled")))} | '
                f'glow={int(bool(material.get("glow_enabled")))} | shadow={int(bool(material.get("shadow_enabled")))} | '
                f'stroke={float(material.get("stroke_width", 0.0)):.1f}px'))
        except Exception:
            pass
        return mode
    except Exception:
        return None


def _h58_queue_material(panel, reason='material-edit'):
    lw = getattr(panel, 'lyric_window', None)
    material = _h58_material_snapshot(panel)
    if lw is None or material is None:
        return False
    active = bool(getattr(lw, 'full_text', '')) and int(getattr(lw, 'displayed_line_index', -1)) >= 0
    if not active:
        if _h58_apply_material(lw, material):
            try:
                if getattr(lw, 'lyric_timeline', None):
                    if bool(getattr(lw, '_song_fragment_atlas_performance_fused', False)):
                        lw._song_fragment_atlas_performance_fused = False
                        lw._song_fragment_atlas_fuse_reason = 'h58-idle-style-retry'
                    lw._schedule_song_fragment_atlas()
            except Exception:
                pass
            try: lw.update()
            except Exception: pass
            return True
        return False
    lw._h58_pending_material = material
    lw._h58_pending_material_reason = str(reason or 'material-edit')
    timer = getattr(panel, '_h58_material_timer', None)
    try:
        if timer is not None:
            timer.start(int(H58_STYLE_PREWARM_DEBOUNCE_MS))
        else:
            _h58_prewarm_material(panel)
    except Exception:
        _h58_prewarm_material(panel)
    try:
        write_error_log('H58样式景深材质排队', detail=(
            f'reason={reason} | commit=next-line-after-atlas | history=immutable | '
            f'outline={int(bool(material.get("outline_enabled")))} | glow={int(bool(material.get("glow_enabled")))}'))
    except Exception:
        pass
    return True


def _h58_activate_runtime():
    if not all(name in globals() for name in ('ControlPanel', 'LyricWindow')):
        return
    try:
        if getattr(ControlPanel.__init__, '_limbus_layer', '') == 'H58':
            return
        sig_pre = LyricWindow._fragment_style_signature_for_visual
        pending_pre = LyricWindow._apply_pending_visual_style
        edge_pre = ControlPanel._apply_edge_style_live
        glow_pre = ControlPanel._apply_glow_live
        pick_color_pre = ControlPanel.pick_color
        init_pre = ControlPanel.__init__

        def h58_fragment_style_signature(window, visual_style=None):
            if isinstance(visual_style, dict) and visual_style.get('_h58_material'):
                try:
                    return _fragment_style_signature(
                        QFont(visual_style['font']), QColor(visual_style['text_color']),
                        QColor(visual_style['stroke_color']), float(visual_style['stroke_width']),
                        bool(visual_style['outline_enabled']), bool(visual_style['shadow_enabled']),
                        QColor(visual_style['shadow_color']), bool(visual_style['glow_enabled']),
                        QColor(visual_style['glow_color']), int(visual_style['glow_size']),
                        int(visual_style['glow_alpha'])
                    )
                except Exception:
                    pass
            return sig_pre(window, visual_style)

        def h58_apply_pending_visual_style(window):
            material = getattr(window, '_h58_pending_material', None)
            visual = getattr(window, '_pending_visual_style', None)
            commit_material = bool(isinstance(material, dict) and _h58_material_ready(window, material, visual))
            if commit_material:
                _h58_apply_material(window, material)
                window._h58_pending_material = None
                window._h58_pending_material_reason = ''
            elif isinstance(material, dict) and bool(getattr(window, '_song_fragment_atlas_performance_fused', False)):
                # A retry that exceeded the worker budget must never strand the next line on a
                # mismatched hard vector style. Keep the already-valid material and drop only
                # this failed live edit; the controls remain persisted for the next clean start.
                window._h58_pending_material = None
                window._h58_pending_material_reason = ''
                try:
                    write_error_log('H58样式景深预热失败保留旧材质', detail='atlas=fused | vector-fallback=forbidden | next-clean-start=uses-saved-style')
                except Exception:
                    pass
            result = pending_pre(window)
            if commit_material and visual is None:
                try: window._schedule_song_fragment_atlas()
                except Exception: pass
            return result or commit_material

        def h58_edge_live(panel):
            if bool(getattr(panel, '_is_started', False)) and getattr(panel, '_loaded_track_key', ''):
                return _h58_queue_material(panel, 'edge')
            result = edge_pre(panel)
            try: _h58_queue_material(panel, 'edge-idle')
            except Exception: pass
            return result

        def h58_glow_live(panel):
            if bool(getattr(panel, '_is_started', False)) and getattr(panel, '_loaded_track_key', ''):
                try: panel._update_diy_live_preview()
                except Exception: pass
                return _h58_queue_material(panel, 'glow')
            result = glow_pre(panel)
            try: _h58_queue_material(panel, 'glow-idle')
            except Exception: pass
            return result

        def h58_pick_color(panel):
            before = QColor(getattr(panel, 'current_color', QColor()))
            result = pick_color_pre(panel)
            after = QColor(getattr(panel, 'current_color', QColor()))
            if (after.isValid() and after != before and bool(getattr(panel, '_is_started', False)) and
                    getattr(panel, '_loaded_track_key', '') and
                    not bool(hasattr(panel, 'random_color_check') and panel.random_color_check.isChecked())):
                try: panel._apply_active_visual_style_live(reason='h58-fixed-color')
                except Exception: pass
            return result

        def h58_control_init(panel, *args, **kwargs):
            init_pre(panel, *args, **kwargs)
            try:
                timer = QTimer(panel)
                timer.setSingleShot(True)
                timer.setInterval(int(H58_STYLE_PREWARM_DEBOUNCE_MS))
                timer.timeout.connect(lambda p=panel: _h58_prewarm_material(p))
                panel._h58_material_timer = timer
                lw = panel.lyric_window
                lw._h58_pending_material = None
                lw._h58_pending_material_reason = ''
                def fixed_font_changed(_font):
                    try:
                        if (bool(getattr(panel, '_is_started', False)) and getattr(panel, '_loaded_track_key', '') and
                                not bool(hasattr(panel, 'random_font_check') and panel.random_font_check.isChecked())):
                            panel._apply_active_visual_style_live(reason='h58-fixed-font')
                    except Exception:
                        pass
                panel.font_combo.currentFontChanged.connect(fixed_font_changed)
            except Exception as exc:
                try: write_error_log('H58样式景深材质初始化失败', exc)
                except Exception: pass

        LyricWindow._fragment_style_signature_for_visual = h58_fragment_style_signature
        LyricWindow._fragment_style_signature_for_visual._limbus_layer = 'H58'
        LyricWindow._fragment_style_signature_for_visual._limbus_policy = 'outline-shadow-glow-are-source-pixels-before-depth-composite'
        LyricWindow._apply_pending_visual_style = h58_apply_pending_visual_style
        LyricWindow._apply_pending_visual_style._limbus_layer = 'H58'
        LyricWindow._apply_pending_visual_style._limbus_policy = 'commit-material-only-after-matching-atlas-ready'
        ControlPanel._apply_edge_style_live = h58_edge_live
        ControlPanel._apply_edge_style_live._limbus_layer = 'H58'
        ControlPanel._apply_glow_live = h58_glow_live
        ControlPanel._apply_glow_live._limbus_layer = 'H58'
        ControlPanel.pick_color = h58_pick_color
        ControlPanel.pick_color._limbus_layer = 'H58'
        ControlPanel.__init__ = h58_control_init
        ControlPanel.__init__._limbus_layer = 'H58'
    except Exception as exc:
        try: write_error_log('H58样式景深材质运行层安装失败', exc)
        except Exception: pass


# H59 exit continuity + center corridor + scoped script previews ----------------------------
# Field H58 logs show normal blank-span releases entering fading=1 with emergency_dropped=0;
# the remaining user-visible risks are presentation continuity, not playback ownership:
# (1) absolute wall-clock exits can skip their first visible frame after a GUI stall;
# (2) H53's frequency was random per-row and protected only the final footprint, so short
#     random clusters and entrance/blur/shake corridors could still cross the center;
# (3) the H54 hover preview shows all scripts even inside a script-specific font selector.
# H59 keeps clocks/transactions/providers untouched and adds one natural hop/drop exit.
H59_EXIT_EFFECT_HOP_DROP = 'hop_drop'
H59_EXIT_FIRST_FRAME_CATCHUP_MS = 120.0
H59_HOP_DURATION_MS = 920.0
H59_CENTER_BASE_CORRIDOR_PX = 20.0
H59_CENTER_PUSH_MARGIN_PX = 16.0
H59_CENTER_MAX_PUSH_PASSES = 3


def _h59_script_preview_text(kind, family):
    family = str(family or '').strip()
    kind = str(kind or '').strip().lower()
    samples = {
        'ja': ('日本語', '春風と星空　かな カナ　夢を見る'),
        'ko': ('한국어', '노래와 별빛　한글　오늘도 꿈을 꿔'),
        'western': ('Latin', 'The quick brown fox　Café déjà vu　AaBb 0123'),
    }
    label, sample = samples.get(kind, ('', ''))
    if not label:
        return _h54_font_preview_text(family) if '_h54_font_preview_text' in globals() else family
    try:
        supported = bool(_h51_font_supports_text(family, sample.replace('　', '').replace(' ', '')))
    except Exception:
        supported = True
    status = '✓ 支持' if supported else '△ 缺字'
    return f'{family}\n{label} {status}\n{sample}'


def _h59_center_quota_allows(window, frequency):
    """Deterministic short-window quota; avoids random clusters that look like no setting."""
    try:
        freq = max(0, min(100, int(frequency)))
    except Exception:
        freq = H51_CENTER_FREQ_DEFAULT
    if freq <= 0:
        window._h59_center_credit = 0
        window._h59_center_frequency_seen = freq
        return False
    if freq >= 100:
        window._h59_center_credit = 0
        window._h59_center_frequency_seen = freq
        return True
    if int(getattr(window, '_h59_center_frequency_seen', -1)) != freq:
        window._h59_center_frequency_seen = freq
        window._h59_center_credit = 0
    credit = int(getattr(window, '_h59_center_credit', 0) or 0) + freq
    allow = credit >= 100
    if allow:
        credit -= 100
    window._h59_center_credit = max(0, min(99, int(credit)))
    return bool(allow)


def _h59_center_corridor_margin(window):
    margin = float(H59_CENTER_BASE_CORRIDOR_PX)
    try:
        text = str(getattr(window, 'full_text', '') or '')
        effects = {str(getattr(window, 'entrance_effect', 'smart') or 'smart').lower()}
        if text and hasattr(window, '_entrance_effect_for_text'):
            effects.add(str(window._entrance_effect_for_text(text) or 'smart').lower())
        if 'slide' in effects:
            margin = max(margin, 24.0)
        if 'rise' in effects or 'bounce' in effects:
            margin = max(margin, 22.0)
    except Exception:
        pass
    try:
        margin = max(margin, min(28.0, float(getattr(window, 'shake_intensity', 0.0) or 0.0) * 2.2))
    except Exception:
        pass
    try:
        if bool(getattr(window, '_h54_depth_enabled', False)) and '_h57_optical_margin' in globals():
            optical = float(_h57_optical_margin(
                int(getattr(window, '_h54_active_depth_level', 1) or 1),
                int(getattr(window, '_h54_depth_layers', H53_DEPTH_DEFAULT_LAYERS) or H53_DEPTH_DEFAULT_LAYERS),
                int(getattr(window, '_h54_depth_strength_pct', H53_DEPTH_DEFAULT_STRENGTH) or 0)))
            margin = max(margin, min(54.0, optical))
    except Exception:
        pass
    return max(12.0, min(64.0, float(margin)))


def _h59_center_guard_box(window, margin=None):
    center = _h53_center_box(window)
    pad = _h59_center_corridor_margin(window) if margin is None else max(0.0, float(margin))
    return (float(center[0]) - pad, float(center[1]) - pad,
            float(center[2]) + pad, float(center[3]) + pad)


def _h59_box_tuple(rect):
    return (float(rect.left()), float(rect.top()), float(rect.right()), float(rect.bottom()))


def _h59_current_corridor_boxes(window, margin=None):
    try:
        base = _h53_current_placement_box(window)
    except Exception:
        return []
    boxes = [tuple(float(x) for x in base)]
    try:
        tr = QTransform(getattr(window, 'persp_transform', QTransform()))
        if bool(getattr(window, 'perspective_enabled', False)) and not tr.isIdentity():
            mapped = tr.mapRect(QRectF(float(base[0]), float(base[1]),
                                      float(base[2] - base[0]), float(base[3] - base[1])))
            boxes.append(_h59_box_tuple(mapped))
    except Exception:
        pass
    pad = _h59_center_corridor_margin(window) if margin is None else max(0.0, float(margin))
    sw = max(1.0, float(window.width()))
    visible = []
    for box in boxes:
        expanded = window._placement_expand_box(box, pad)
        try:
            copies = window._placement_visible_boxes(expanded, sw, bool(getattr(window, 'horizontal_wrap', False)))
        except Exception:
            copies = [expanded]
        visible.extend(copies)
    return visible


def _h59_center_corridor_overlap(window, margin=None):
    guard = _h53_center_box(window)
    worst = 0.0
    for box in _h59_current_corridor_boxes(window, margin):
        try:
            inter = _h53_box_intersection_area(box, guard)
            area = max(1.0, (float(box[2]) - float(box[0])) * (float(box[3]) - float(box[1])))
            worst = max(worst, inter / area)
        except Exception:
            pass
    return max(0.0, min(1.0, float(worst)))


def _h59_push_corridor_outside_center(window, margin=None):
    """Push the lyric anchor so its visual/entrance corridor, not only its resting box, avoids center."""
    try:
        pad = _h59_center_corridor_margin(window) if margin is None else max(0.0, float(margin))
        base = _h53_current_placement_box(window)
        guard = _h59_center_guard_box(window, pad + float(H59_CENTER_PUSH_MARGIN_PX))
        if all(_h53_box_intersection_area(box, _h53_center_box(window)) <= 0.0
               for box in _h59_current_corridor_boxes(window, pad)):
            return False
        candidates = [
            (float(guard[0]) - float(base[2]), 0.0),
            (float(guard[2]) - float(base[0]), 0.0),
            (0.0, float(guard[1]) - float(base[3])),
            (0.0, float(guard[3]) - float(base[1])),
        ]
        sw = max(1.0, float(window.width())); sh = max(1.0, float(window.height()))
        try:
            obstacles = list(window._placement_obstacles() or [])
        except Exception:
            obstacles = []
        best = None
        for dx, dy in candidates:
            shifted = (base[0] + dx, base[1] + dy, base[2] + dx, base[3] + dy)
            corridor = window._placement_expand_box(shifted, pad)
            try:
                copies = window._placement_visible_boxes(corridor, sw, bool(getattr(window, 'horizontal_wrap', False)))
            except Exception:
                copies = [corridor]
            if any(_h53_box_intersection_area(c, _h53_center_box(window)) > 0.0 for c in copies):
                continue
            outside = (max(0.0, -corridor[0]) + max(0.0, corridor[2] - sw) +
                       max(0.0, -corridor[1]) + max(0.0, corridor[3] - sh))
            worst = 0.0
            for ob in obstacles:
                try:
                    obox = ob[0]
                    obs_visible = window._placement_visible_boxes(obox, sw, bool(getattr(window, 'horizontal_wrap', False)))
                    worst = max(worst, float(window._placement_max_overlap(copies, obs_visible)))
                except Exception:
                    pass
            score = worst * 10000.0 + outside * 4.0 + math.hypot(dx, dy) / max(1.0, min(sw, sh))
            if best is None or score < best[0]:
                best = (score, dx, dy)
        if best is None:
            return False
        window.x = int(round(float(window.x) + float(best[1])))
        window.y = int(round(float(window.y) + float(best[2])))
        try: window.compute_perspective()
        except Exception: pass
        try:
            new_box = _h53_current_placement_box(window)
            vx, vy = window._placement_box_center(new_box)
            recent = list(getattr(window, '_placement_recent', []) or [])
            entry = (float(vx), float(vy), float(window.angle))
            window._placement_recent = ((recent[:-1] if recent else []) + [entry])[-18:]
        except Exception:
            pass
        return True
    except Exception:
        return False


def _h59_hop_profile(progress):
    p = max(0.0, min(1.0, float(progress)))
    apex = 0.30
    if p <= apex:
        q = p / apex
        dy = -24.0 * math.sin(q * math.pi * 0.5)
    else:
        q = (p - apex) / max(0.001, 1.0 - apex)
        dy = -24.0 * (1.0 - q) + 48.0 * (q * q)
    fade_p = max(0.0, min(1.0, (p - 0.16) / 0.84))
    alpha = 1.0 - _h51_smoothstep(fade_p)
    return float(dy), max(0.0, min(1.0, float(alpha)))


def _h59_activate_runtime():
    if not all(name in globals() for name in ('ControlPanel', 'LyricWindow', 'FadingLine')):
        return
    try:
        if getattr(ControlPanel.__init__, '_limbus_layer', '') == 'H59':
            return
        init_pre = ControlPanel.__init__
        place_pre = LyricWindow.place_randomly
        fading_init_pre = FadingLine.__init__
        fading_begin_pre = FadingLine.begin_fade
        fading_update_pre = FadingLine.update
        fading_draw_pre = FadingLine.draw
        held_region_pre = LyricWindow._held_visual_region
        font_preview_pre = ControlPanel._show_font_family_preview

        def h59_fading_init(row, *args, **kwargs):
            fading_init_pre(row, *args, **kwargs)
            row._h59_exit_begin_mono = time.monotonic() * 1000.0
            row._h59_exit_draw_count = 0
            row._h59_hop_started_mono = 0.0
            row._h59_first_frame_clamped = False

        def h59_begin_fade(row):
            result = fading_begin_pre(row)
            row._h59_exit_begin_mono = time.monotonic() * 1000.0
            row._h59_exit_draw_count = 0
            row._h59_hop_started_mono = 0.0
            row._h59_first_frame_clamped = False
            return result

        def h59_fading_update(row):
            effect = str(getattr(row, 'exit_effect', 'fade') or 'fade').strip().lower()
            now = time.monotonic() * 1000.0
            if effect == H59_EXIT_EFFECT_HOP_DROP:
                started = float(getattr(row, '_h59_hop_started_mono', 0.0) or 0.0)
                if started <= 0.0:
                    started = now; row._h59_hop_started_mono = now
                    row._h59_exit_begin_mono = now
                    row._h59_exit_draw_count = 0
                elif int(getattr(row, '_h59_exit_draw_count', 0) or 0) <= 0 and now - started > float(H59_EXIT_FIRST_FRAME_CATCHUP_MS):
                    # The hop/drop effect owns its own absolute timer, so it needs the same
                    # first-visible-frame protection as the mature H16/H51 exit clocks.
                    started = now - float(H59_EXIT_FIRST_FRAME_CATCHUP_MS)
                    row._h59_hop_started_mono = started
                    if not bool(getattr(row, '_h59_first_frame_clamped', False)):
                        row._h59_first_frame_clamped = True
                        try: write_error_log('H59退场首帧连续性保护', detail=f'effect={effect} | max_catchup={int(H59_EXIT_FIRST_FRAME_CATCHUP_MS)}ms | timer=hop-drop')
                        except Exception: pass
                p = max(0.0, min(1.0, (now - started) / float(H59_HOP_DURATION_MS)))
                row._h59_hop_progress = p
                _dy, alpha_ratio = _h59_hop_profile(p)
                row._fade_alpha_float = 255.0 * alpha_ratio
                row.alpha = max(0, min(255, int(round(row._fade_alpha_float))))
                if p < 0.82:
                    try: row._update_shake_motion()
                    except Exception: pass
                if p >= 1.0 or row.alpha <= int(FADE_VISUAL_ALPHA_CUTOFF):
                    row.release_render_resources(); return False
                return True
            # First-frame continuity: wall-clock exits must not complete before the user ever
            # sees a real exit frame after a GUI stall. Cap only the pre-first-draw catch-up;
            # after one draw the mature wall-clock lifecycle resumes unchanged.
            if effect != 'instant' and int(getattr(row, '_h59_exit_draw_count', 0) or 0) <= 0:
                clamped = False
                try:
                    started = float(getattr(row, '_h16_exit_started_mono', 0.0) or 0.0)
                    if started > 0.0 and now - started > float(H59_EXIT_FIRST_FRAME_CATCHUP_MS):
                        row._h16_exit_started_mono = now - float(H59_EXIT_FIRST_FRAME_CATCHUP_MS); clamped = True
                except Exception:
                    pass
                try:
                    last = float(getattr(row, '_fade_last_step_mono', 0.0) or 0.0)
                    if last > 0.0 and now - last > float(H59_EXIT_FIRST_FRAME_CATCHUP_MS):
                        row._fade_last_step_mono = now - float(H59_EXIT_FIRST_FRAME_CATCHUP_MS); clamped = True
                except Exception:
                    pass
                if clamped and not bool(getattr(row, '_h59_first_frame_clamped', False)):
                    row._h59_first_frame_clamped = True
                    try: write_error_log('H59退场首帧连续性保护', detail=f'effect={effect} | max_catchup={int(H59_EXIT_FIRST_FRAME_CATCHUP_MS)}ms')
                    except Exception: pass
            alive = fading_update_pre(row)
            if (not alive and effect != 'instant' and
                    int(getattr(row, '_h59_exit_draw_count', 0) or 0) <= 0):
                try:
                    write_error_log('H59退场首帧未呈现诊断', detail=(
                        f'effect={effect} | fade_speed={float(getattr(row,"fade_speed",0.0) or 0.0):.2f} | '
                        f'alpha={int(getattr(row,"alpha",0) or 0)} | action=unexpected-pre-draw-release'))
                except Exception:
                    pass
            return alive

        def h59_fading_draw(row, painter):
            effect = str(getattr(row, 'exit_effect', 'fade') or 'fade').strip().lower()
            if effect == H59_EXIT_EFFECT_HOP_DROP:
                p = max(0.0, min(1.0, float(getattr(row, '_h59_hop_progress', 0.0) or 0.0)))
                dy, _alpha = _h59_hop_profile(p)
                old_y = float(getattr(row, 'y', 0.0) or 0.0)
                old_effect = str(getattr(row, 'exit_effect', 'fade') or 'fade')
                try:
                    # Feed the exact same H57/H58 depth material into the mature fade draw;
                    # only the row anchor follows the hop/drop trajectory.
                    row.y = old_y + float(dy)
                    row.exit_effect = 'fade'
                    result = fading_draw_pre(row, painter)
                finally:
                    row.exit_effect = old_effect
                    row.y = old_y
                row._h59_exit_draw_count = int(getattr(row, '_h59_exit_draw_count', 0) or 0) + 1
                return result
            result = fading_draw_pre(row, painter)
            if effect != 'instant':
                row._h59_exit_draw_count = int(getattr(row, '_h59_exit_draw_count', 0) or 0) + 1
            return result

        def h59_held_visual_region(window, item):
            region = held_region_pre(window, item)
            try:
                if str(getattr(item, 'exit_effect', '') or '').strip().lower() == H59_EXIT_EFFECT_HOP_DROP:
                    # The hop ranges about -24..+48px; reserve both tails so sparse repaint
                    # never clips the motion even though row.y stays immutable outside draw().
                    region = region.united(region.translated(0, -30)).united(region.translated(0, 56))
            except Exception:
                pass
            return region

        def h59_place_randomly(window):
            try:
                freq = max(0, min(100, int(getattr(window, '_h51_center_frequency_pct', H51_CENTER_FREQ_DEFAULT))))
            except Exception:
                freq = H51_CENTER_FREQ_DEFAULT
            allow = _h59_center_quota_allows(window, freq)
            old_freq = getattr(window, '_h51_center_frequency_pct', H51_CENTER_FREQ_DEFAULT)
            try:
                # H53 remains the authoritative collision-safe placer. H59 supplies a
                # deterministic quota instead of another random coin flip.
                window._h51_center_frequency_pct = 100 if allow else 0
                result = place_pre(window)
            finally:
                window._h51_center_frequency_pct = old_freq
            if allow:
                try:
                    write_error_log('H59中央走廊约束', detail=f'frequency={freq}% | quota_allow=1 | corridor=not-required')
                except Exception:
                    pass
                return result
            margin = _h59_center_corridor_margin(window)
            before = _h59_center_corridor_overlap(window, margin)
            pushed = 0
            for _ in range(int(H59_CENTER_MAX_PUSH_PASSES)):
                if _h59_center_corridor_overlap(window, margin) <= 0.0:
                    break
                if not _h59_push_corridor_outside_center(window, margin):
                    break
                pushed += 1
            after = _h59_center_corridor_overlap(window, margin)
            try:
                write_error_log('H59中央走廊约束', detail=(
                    f'frequency={freq}% | quota_allow=0 | margin={margin:.1f}px | '
                    f'overlap={before:.4f}->{after:.4f} | push={pushed} | credit={int(getattr(window,"_h59_center_credit",0) or 0)}'))
            except Exception:
                pass
            return result

        def h59_font_preview(panel, combo, family):
            family = str(family or '').strip()
            if not family:
                try: panel._font_preview_hide()
                except Exception: pass
                return False
            kind = None
            if combo is getattr(panel, 'h51_font_ja_combo', None): kind = 'ja'
            elif combo is getattr(panel, 'h51_font_ko_combo', None): kind = 'ko'
            elif combo is getattr(panel, 'h51_font_western_combo', None): kind = 'western'
            if kind is None:
                return font_preview_pre(panel, combo, family)
            try:
                if panel._font_preview_popup is None:
                    font_preview_pre(panel, combo, family)
                popup = panel._font_preview_popup
                popup.setText(_h59_script_preview_text(kind, family))
                popup.setFont(QFont(family, 17))
                popup.adjustSize()
                pos = QCursor.pos(); popup.move(int(pos.x() + 20), int(pos.y() + 18))
                popup.show(); popup.raise_()
                return True
            except Exception:
                return font_preview_pre(panel, combo, family)

        def h59_control_init(panel, *args, **kwargs):
            # H51 rebuilds the exit combo before H59 exists.  Read the persisted setting
            # directly so a saved H59-only effect cannot be silently rewritten to fade on
            # the next launch merely because the older combo did not know its key yet.
            try:
                _h59_saved_settings = (load_all_config().get('settings') or {})
                _h59_saved_exit = str(_h59_saved_settings.get('h12_exit_effect', '') or '').strip().lower()
            except Exception:
                _h59_saved_exit = ''
            init_pre(panel, *args, **kwargs)
            try:
                if hasattr(panel, 'h12_exit_combo'):
                    selected = (_h59_saved_exit if _h59_saved_exit == H59_EXIT_EFFECT_HOP_DROP
                                else str(getattr(panel.lyric_window, 'exit_effect', 'fade') or 'fade'))
                    if panel.h12_exit_combo.findData(H59_EXIT_EFFECT_HOP_DROP) < 0:
                        insert_at = panel.h12_exit_combo.findData('soft_drift')
                        insert_at = insert_at if insert_at >= 0 else max(0, panel.h12_exit_combo.count() - 1)
                        panel.h12_exit_combo.insertItem(insert_at, '轻跃下坠淡出', H59_EXIT_EFFECT_HOP_DROP)
                    idx = panel.h12_exit_combo.findData(selected)
                    if idx >= 0:
                        panel.h12_exit_combo.blockSignals(True)
                        panel.h12_exit_combo.setCurrentIndex(idx)
                        panel.h12_exit_combo.blockSignals(False)
                        if selected == H59_EXIT_EFFECT_HOP_DROP:
                            panel.lyric_window.exit_effect = H59_EXIT_EFFECT_HOP_DROP
                    panel.h12_exit_combo.setToolTip(
                        '“轻跃下坠淡出”会先轻微上跳，再自然下坠并淡出，并保留该行原有的描边、发光与景深效果。')
                if hasattr(panel, 'h51_center_slider'):
                    panel.h51_center_slider.setToolTip(
                        '控制字幕允许进入屏幕中央区域的频率。0%=严格避开中央；100%=不限制；中间数值按比例放行。')
                    for label in panel.findChildren(QLabel):
                        if str(label.text() or '') == '中央区域出现频率：':
                            label.setText('中央区域允许频率：')
                # Script-specific selectors should preview only the script they control.
                for key, label in (('ja', '日文'), ('ko', '韩文'), ('western', '西文')):
                    combo = getattr(panel, f'h51_font_{key}_combo', None)
                    if combo is not None:
                        combo.setToolTip(f'{label}独立字体：悬停字体时只预览{label}示例和该字体的覆盖情况。')
            except Exception as exc:
                try: write_error_log('H59展示连续性界面初始化失败', exc)
                except Exception: pass

        FadingLine.__init__ = h59_fading_init
        FadingLine.__init__._limbus_layer = 'H59'
        FadingLine.begin_fade = h59_begin_fade
        FadingLine.begin_fade._limbus_layer = 'H59'
        FadingLine.update = h59_fading_update
        FadingLine.update._limbus_layer = 'H59'
        FadingLine.update._limbus_policy = 'non-instant-first-visible-frame-guard-plus-hop-drop'
        FadingLine.draw = h59_fading_draw
        FadingLine.draw._limbus_layer = 'H59'
        FadingLine.draw._limbus_policy = 'hop-drop-reuses-h57-h58-birth-material-no-clipping'
        LyricWindow._held_visual_region = h59_held_visual_region
        LyricWindow._held_visual_region._limbus_layer = 'H59'
        LyricWindow.place_randomly = h59_place_randomly
        LyricWindow.place_randomly._limbus_layer = 'H59'
        LyricWindow.place_randomly._limbus_policy = 'deterministic-center-quota-plus-entry-optical-corridor'
        ControlPanel._show_font_family_preview = h59_font_preview
        ControlPanel._show_font_family_preview._limbus_layer = 'H59'
        ControlPanel._show_font_family_preview._limbus_policy = 'script-selector-previews-only-own-script'
        ControlPanel.__init__ = h59_control_init
        ControlPanel.__init__._limbus_layer = 'H59'
        ControlPanel.__init__._limbus_policy = 'exit-center-preview-presentation-only'
    except Exception as exc:
        try: write_error_log('H59展示连续性运行层安装失败', exc)
        except Exception: pass


# H60 depth fuse fallback + transactional center + preview UI cleanup -------------------------
# Real H59 field logs exposed three presentation defects that share no clock/transaction root:
# (1) the full-song styled Atlas can legitimately hit its 850ms safety fuse; when that happens
#     H57 has no shared source pixels and deep rows silently fall back to sharp sprite/vector;
# (2) H59's post-placement center push can become worse after perspective is recomputed, yet
#     it used to commit that worse anchor and repeat the push; and
# (3) script font selectors already have a rich hover preview, so an ordinary combo tooltip
#     duplicates the same explanation directly over the preview and blocks the samples.
# H60 keeps the full-song fuse, builds only the current deep row after a fuse, makes center
# correction transactional/monotonic, and removes only preview-obscuring redundant tooltips.
H60_LINE_ATLAS_WARN_MS = 24.0
H60_LINE_ATLAS_MAX_GLYPHS = 96
H60_CENTER_IMPROVEMENT_EPS = 0.0005


def _h60_line_shared_key(window, text):
    try:
        return (window._current_fragment_style_signature(), str(text or ''))
    except Exception:
        return (None, str(text or ''))


def _h60_build_line_shared(window, text):
    """Build one styled shared Atlas for only the active row after the song Atlas fuse.

    The 850ms song-level fuse remains authoritative. This fallback rasterizes at most the
    unique glyphs of the one deep lyric row and feeds the ordinary H56/H57 low-pass pipeline.
    It is cached for the row lifetime, so current->history inherits the exact same pixels.
    """
    text = str(text or '')
    if not text:
        return None
    key = _h60_line_shared_key(window, text)
    cached = getattr(window, '_h60_line_shared_cache', None)
    if isinstance(cached, dict) and cached.get('key') == key:
        return cached.get('shared')
    started = time.perf_counter()
    shared = None
    reason = 'unknown'
    try:
        style_sig = key[0]
        if style_sig is None:
            reason = 'style-signature'
        else:
            unique = []
            seen = set()
            for ch in text:
                if not ch or ch.isspace() or ch in seen:
                    continue
                seen.add(ch); unique.append(ch)
            if len(unique) > int(H60_LINE_ATLAS_MAX_GLYPHS):
                reason = f'glyph-limit>{int(H60_LINE_ATLAS_MAX_GLYPHS)}'
            elif not unique:
                reason = 'empty'
            else:
                try:
                    source_ss = max(1.0, float(style_sig[11] or 1.0))
                except Exception:
                    source_ss = 2.0
                entries = []
                for ch in unique:
                    rendered = _render_song_atlas_glyph(style_sig, ch)
                    if rendered is None:
                        entries = []; reason = f'glyph-unavailable:{repr(ch)[:20]}'; break
                    image, left, top, lw, lh = rendered
                    entries.append((str(ch), image, float(left), float(top), float(lw), float(lh), source_ss))
                if entries:
                    shared = _h56_pack_filtered_entries(entries, style_sig)
                    reason = 'none' if shared is not None else 'pack-failed'
    except Exception as exc:
        reason = f'{type(exc).__name__}:{exc}'
        shared = None
    elapsed = (time.perf_counter() - started) * 1000.0
    try:
        window._h60_line_shared_cache = {'key': key, 'shared': shared, 'build_ms': float(elapsed), 'reason': reason}
    except Exception:
        pass
    try:
        if elapsed >= float(H60_LINE_ATLAS_WARN_MS) or shared is None:
            write_error_log('H60行级景深Atlas后备', detail=(
                f'ms={elapsed:.1f} | chars={len(set(text))} | result={"ok" if shared is not None else "sharp"} | '
                f'reason={reason} | song_fuse={int(bool(getattr(window,"_song_fragment_atlas_performance_fused",False)))}'))
    except Exception:
        pass
    return shared


def _h60_push_corridor_outside_center(window, margin=None):
    """Transactional H59 center correction: never commit a position with worse overlap."""
    try:
        pad = _h59_center_corridor_margin(window) if margin is None else max(0.0, float(margin))
        before = float(_h59_center_corridor_overlap(window, pad))
        if before <= 0.0:
            return False
        original = (
            int(getattr(window, 'x', 0) or 0), int(getattr(window, 'y', 0) or 0),
            int(getattr(window, 'angle', 0) or 0), QTransform(getattr(window, 'persp_transform', QTransform())),
            list(getattr(window, '_placement_recent', []) or []),
        )
        base = _h53_current_placement_box(window)
        guard = _h59_center_guard_box(window, pad + float(H59_CENTER_PUSH_MARGIN_PX))
        sw = max(1.0, float(window.width())); sh = max(1.0, float(window.height()))
        raw_moves = [
            (float(guard[0]) - float(base[2]), 0.0),
            (float(guard[2]) - float(base[0]), 0.0),
            (0.0, float(guard[1]) - float(base[3])),
            (0.0, float(guard[3]) - float(base[1])),
        ]
        candidates = []
        for dx, dy in raw_moves:
            for mul in (1.0, 1.20, 1.45, 1.80):
                candidates.append((dx * mul, dy * mul))
        # If perspective makes the analytic push non-linear, also try stable screen-side lanes.
        ox, oy = float(original[0]), float(original[1])
        for tx, ty in (
            (sw * 0.08, oy), (sw * 0.72, oy), (ox, sh * 0.10), (ox, sh * 0.80),
            (sw * 0.10, sh * 0.12), (sw * 0.72, sh * 0.12),
            (sw * 0.10, sh * 0.80), (sw * 0.72, sh * 0.80),
        ):
            candidates.append((float(tx) - ox, float(ty) - oy))
        try:
            obstacles = list(window._placement_obstacles() or [])
        except Exception:
            obstacles = []

        def restore():
            window.x, window.y, window.angle = original[0], original[1], original[2]
            window.persp_transform = QTransform(original[3])
            window._placement_recent = list(original[4])

        best = None
        for dx, dy in candidates:
            restore()
            window.x = int(round(float(original[0]) + float(dx)))
            window.y = int(round(float(original[1]) + float(dy)))
            try: window.compute_perspective()
            except Exception: pass
            after = float(_h59_center_corridor_overlap(window, pad))
            # Literal invariant: a center fix that is not strictly better is not a fix.
            if after + float(H60_CENTER_IMPROVEMENT_EPS) >= before:
                continue
            boxes = list(_h59_current_corridor_boxes(window, pad) or [])
            outside = 0.0
            for b in boxes:
                outside += (max(0.0, -float(b[0])) + max(0.0, float(b[2]) - sw) +
                            max(0.0, -float(b[1])) + max(0.0, float(b[3]) - sh))
            worst = 0.0
            for ob in obstacles:
                try:
                    obox = ob[0]
                    obs_visible = window._placement_visible_boxes(obox, sw, bool(getattr(window, 'horizontal_wrap', False)))
                    worst = max(worst, float(window._placement_max_overlap(boxes, obs_visible)))
                except Exception:
                    pass
            score = after * 1000000.0 + worst * 10000.0 + outside * 4.0 + math.hypot(dx, dy) / max(1.0, min(sw, sh))
            if best is None or score < best[0]:
                best = (score, int(window.x), int(window.y), QTransform(window.persp_transform), after)
        restore()
        if best is None:
            try:
                write_error_log('H60中央走廊事务修正', detail=f'overlap={before:.4f}->{before:.4f} | commit=0 | reason=no-strict-improvement')
            except Exception:
                pass
            return False
        window.x, window.y = int(best[1]), int(best[2])
        window.persp_transform = QTransform(best[3])
        try:
            new_box = _h53_current_placement_box(window)
            vx, vy = window._placement_box_center(new_box)
            recent = list(original[4])
            window._placement_recent = ((recent[:-1] if recent else []) + [(float(vx), float(vy), float(window.angle))])[-18:]
        except Exception:
            pass
        try:
            write_error_log('H60中央走廊事务修正', detail=f'overlap={before:.4f}->{float(best[4]):.4f} | commit=1 | monotonic=1')
        except Exception:
            pass
        return True
    except Exception:
        return False


def _h60_activate_runtime():
    if not all(name in globals() for name in ('ControlPanel', 'LyricWindow', 'FadingLine')):
        return
    try:
        if getattr(ControlPanel.__init__, '_limbus_layer', '') == 'H60':
            return
        init_pre = ControlPanel.__init__
        shared_pre = LyricWindow._shared_song_fragment_atlas
        start_pre = LyricWindow.start_lyric

        def h60_start_lyric(window, *args, **kwargs):
            window._h60_line_shared_cache = None
            window._h60_fuse_fallback_armed = False
            return start_pre(window, *args, **kwargs)

        def h60_shared_song_fragment_atlas(window):
            # Once a row has chosen its local fuse fallback, keep it for that row so a late
            # full-song retry cannot swap pixels/material half-way through the visible line.
            text = str(getattr(window, 'full_text', '') or '')
            current_key = _h60_line_shared_key(window, text) if text else None
            cached = getattr(window, '_h60_line_shared_cache', None)
            if isinstance(cached, dict) and cached.get('key') == current_key and cached.get('shared') is not None:
                return cached.get('shared')
            shared = shared_pre(window)
            if shared is not None:
                window._h60_fuse_fallback_armed = False
                return shared
            if bool(getattr(window, '_song_fragment_atlas_performance_fused', False)):
                window._h60_fuse_fallback_armed = True
            if not bool(getattr(window, '_h60_fuse_fallback_armed', False)):
                return None
            try:
                enabled = bool(getattr(window, '_h54_depth_enabled', False))
                level = int(getattr(window, '_h54_active_depth_level', 1) or 1)
                strength = int(getattr(window, '_h54_depth_strength_pct', H53_DEPTH_DEFAULT_STRENGTH) or 0)
            except Exception:
                enabled = False; level = 1; strength = 0
            if not enabled or level <= 1 or strength <= 0 or not text:
                return None
            return _h60_build_line_shared(window, text)

        def h60_control_init(panel, *args, **kwargs):
            init_pre(panel, *args, **kwargs)
            try:
                # Rich font hover previews already show family, script sample and coverage.
                # Ordinary tooltips on the same controls only cover those samples, so remove
                # them. Keep unrelated/actionable tooltips elsewhere in the application.
                for combo in panel.findChildren(QFontComboBox):
                    try: combo.setToolTip('')
                    except Exception: pass
                for label in panel.findChildren(QLabel):
                    try:
                        if str(label.text() or '').strip() == 'Aa 你好':
                            label.setToolTip('')
                    except Exception:
                        pass
                try:
                    for preview in panel.findChildren(DiyStylePreview):
                        preview.setToolTip('')
                except Exception:
                    pass
            except Exception as exc:
                try: write_error_log('H60预览界面清理失败', exc)
                except Exception: pass

        # H59 resolves this helper by global name on every placement. Replacing only the
        # helper preserves its quota model while making every post-placement correction atomic.
        globals()['_h59_push_corridor_outside_center'] = _h60_push_corridor_outside_center
        LyricWindow._shared_song_fragment_atlas = h60_shared_song_fragment_atlas
        LyricWindow._shared_song_fragment_atlas._limbus_layer = 'H60'
        LyricWindow._shared_song_fragment_atlas._limbus_policy = 'deep-row-local-styled-atlas-after-song-fuse-stable-for-row-lifetime'
        LyricWindow.start_lyric = h60_start_lyric
        LyricWindow.start_lyric._limbus_layer = 'H60'
        ControlPanel.__init__ = h60_control_init
        ControlPanel.__init__._limbus_layer = 'H60'
        ControlPanel.__init__._limbus_policy = 'remove-only-preview-obscuring-redundant-tooltips'
    except Exception as exc:
        try: write_error_log('H60景深熔断/中央稳定/界面清理运行层安装失败', exc)
        except Exception: pass

# H57 bakes one immutable depth material and keeps current/history/exit geometry continuous.

# H61 async depth fallback + stable birth-only center layout -------------------------------
# H60 field evidence exposed one hot-path regression and one design mismatch:
# (1) row-local depth fallback was built synchronously from _shared_song_fragment_atlas(),
#     which is a paint-time query.  A 101ms row build + 29ms H57 composite crossed H11's
#     120ms hard paint budget, permanently entering the plain-glyph emergency lane and
#     therefore hiding glow/outlines/depth and degrading resident history.
# (2) center avoidance still started with an ordinary placement and then post-pushed it.
#     Mature map-label systems instead prioritize deterministic/stable placement: choose a
#     collision-safe anchor once, insert it, and never move already-placed labels.
# H61 keeps the 850ms song fuse, moves row raster work to the existing Qt queued-signal
# worker pattern, bounds transient paint emergency, and uses a birth-only blue-noise/greedy
# candidate selection when the center quota says a row must avoid the protected region.
H61_ROW_CACHE_MAX_ENTRIES = 12
H61_ROW_CACHE_MAX_PIXELS = 18 * 1024 * 1024
H61_ROW_WORKER_BUDGET_MS = 420.0
H61_ROW_EARLY_COMMIT_MS = 320.0
H61_ROW_WARN_BUILD_MS = 36.0
H61_CENTER_POINT_COUNT = 72
H61_CENTER_MIN_DISTANCE_RATIO = 0.145
H61_CENTER_EPS = 0.0008
H61_EMERGENCY_BASE_RECOVERY_MS = 650.0
H61_EMERGENCY_REPEAT_WINDOW_MS = 5000.0
H61_EMERGENCY_MAX_RECOVERY_MS = 1800.0


def _h61_row_key(window, text):
    try:
        return (window._current_fragment_style_signature(), str(text or ''))
    except Exception:
        return (None, str(text or ''))


def _h61_held_row_key(row):
    try:
        sig = _fragment_style_signature(
            row.font, row.color, row.stroke_color, row.stroke_width, row.outline_enabled,
            row.shadow_enabled, row.shadow_color, row.glow, row.glow_color,
            row.glow_size, row.glow_alpha)
        return (sig, str(row.text or ''))
    except Exception:
        return (None, str(getattr(row, 'text', '') or ''))




def _h84_prune_row_queue(window):
    """Retire obsolete row work: visible material first, then current style/timeline lookahead."""
    _h61_row_cache_init(window)
    visible = set()
    text = str(getattr(window, 'full_text', '') or '')
    if text:
        visible.add(_h61_row_key(window, text))
    for row in list(getattr(window, 'history_lines', []) or []) + list(getattr(window, 'fading_lines', []) or []):
        visible.add(_h61_held_row_key(row))
    wanted = set(visible)
    timeline = getattr(window, 'lyric_timeline', []) or []
    raw = getattr(window, 'displayed_line_index', -1)
    start = max(0, int(raw if raw is not None else -1) + 1)
    for entry in timeline[start:start + int(globals().get('H69_FUTURE_ROW_PREWARM', 12))]:
        try:
            future_text = str(entry[1] or '')
        except Exception:
            future_text = ''
        if future_text:
            wanted.add(_h61_row_key(window, future_text))
    window._h61_row_wanted_keys = frozenset(wanted)
    queue = window._h61_row_atlas_queue
    queue[:] = [job for job in queue if job[0] in wanted]
    queue.sort(key=lambda job: job[0] not in visible)
    del queue[36:]


def _h61_row_cache_init(window):
    if not isinstance(getattr(window, '_h61_row_atlas_cache', None), OrderedDict):
        window._h61_row_atlas_cache = OrderedDict()
        window._h61_row_atlas_cache_pixels = 0
    if not isinstance(getattr(window, '_h61_row_atlas_inflight', None), set):
        window._h61_row_atlas_inflight = set()
    if not isinstance(getattr(window, '_h61_row_atlas_queue', None), list):
        window._h61_row_atlas_queue = []
    if not hasattr(window, '_h61_row_worker_active'):
        window._h61_row_worker_active = False
    if not isinstance(getattr(window, '_h61_row_wanted_keys', None), frozenset):
        window._h61_row_wanted_keys = frozenset()


def _h61_cache_row_shared(window, key, shared):
    _h61_row_cache_init(window)
    if key is None or shared is None:
        return
    cache = window._h61_row_atlas_cache
    old = cache.pop(key, None)
    if old is not None:
        try:
            window._h61_row_atlas_cache_pixels = max(
                0, int(window._h61_row_atlas_cache_pixels) - int(old[1] or 0))
        except Exception:
            pass
    pixels = int(shared[3] or 0)
    cache[key] = (shared, pixels)
    window._h61_row_atlas_cache_pixels = int(getattr(window, '_h61_row_atlas_cache_pixels', 0) or 0) + pixels
    cache.move_to_end(key)
    while cache and (
            len(cache) > int(H61_ROW_CACHE_MAX_ENTRIES) or
            int(getattr(window, '_h61_row_atlas_cache_pixels', 0) or 0) > int(H61_ROW_CACHE_MAX_PIXELS)):
        victim, entry = cache.popitem(last=False)
        window._h61_row_atlas_cache_pixels = max(
            0, int(getattr(window, '_h61_row_atlas_cache_pixels', 0) or 0) - int(entry[1] or 0))


def _h61_row_cached_shared(window, text):
    _h61_row_cache_init(window)
    key = _h61_row_key(window, text)
    entry = window._h61_row_atlas_cache.get(key)
    if entry is None:
        return key, None
    try:
        window._h61_row_atlas_cache.move_to_end(key)
    except Exception:
        pass
    return key, entry[0]


def _h61_kick_row_worker(window):
    _h84_prune_row_queue(window)
    if bool(getattr(window, '_h61_row_worker_active', False)):
        return
    queue = window._h61_row_atlas_queue
    if not queue:
        return
    key, text, style_sig = queue.pop(0)
    if key in window._h61_row_atlas_cache:
        QTimer.singleShot(0, lambda w=window: _h61_kick_row_worker(w))
        return
    window._h61_row_worker_active = True
    window._h61_row_atlas_inflight.add(key)

    def worker():
        started = time.perf_counter()
        budget_hit = [False]

        def cancel_check():
            if key not in getattr(window, '_h61_row_wanted_keys', ()):
                return True
            elapsed = (time.perf_counter() - started) * 1000.0
            if elapsed >= float(H61_ROW_WORKER_BUDGET_MS):
                budget_hit[0] = True
                return True
            return False

        payload = {
            'h61_row_fallback': True, 'row_key': key, 'style_sig': style_sig,
            'text': text, 'failed': True,
        }
        try:
            chars = []
            seen = set()
            for ch in str(text or ''):
                if not ch or ch.isspace() or ch in seen:
                    continue
                seen.add(ch); chars.append(ch)
            built = _build_song_fragment_atlas_image(style_sig, chars, cancel_check=cancel_check)
            if isinstance(built, dict) and built.get('cancelled'):
                payload = {
                    'h61_row_fallback': True, 'row_key': key, 'style_sig': style_sig,
                    'text': text, 'cancelled': True, 'budget_hit': bool(budget_hit[0]), **built,
                }
            elif isinstance(built, dict):
                payload = {
                    'h61_row_fallback': True, 'row_key': key, 'style_sig': style_sig,
                    'text': text, **built,
                }
        except Exception as exc:
            payload['error'] = f'{type(exc).__name__}:{exc}'
        try:
            window.song_fragment_atlas_ready.emit(payload)
        except Exception:
            try:
                window._h61_row_worker_active = False
                window._h61_row_atlas_inflight.discard(key)
            except Exception:
                pass

    threading.Thread(target=worker, name='LimbusLyric-H61RowAtlas', daemon=True).start()


def _h61_schedule_row_atlas(window, text):
    text = str(text or '')
    if not text:
        return None
    _h84_prune_row_queue(window)
    key = _h61_row_key(window, text)
    style_sig = key[0]
    if style_sig is None:
        return None
    if key in window._h61_row_atlas_cache:
        return 'cache-hit'
    if key in window._h61_row_atlas_inflight:
        return 'inflight'
    if any(item[0] == key for item in window._h61_row_atlas_queue):
        return 'queued'
    window._h61_row_atlas_queue.append((key, text, style_sig))
    _h84_prune_row_queue(window)
    _h61_kick_row_worker(window)
    return 'scheduled'


def _h61_poisson_points(window):
    """Deterministic Bridson-style candidates, cached per viewport.

    These are only candidate visual centers.  Actual lyric rectangles are still measured with
    the project's mature placement metrics and scored against every resident/fading obstacle.
    """
    sw = max(1, int(window.width())); sh = max(1, int(window.height()))
    key = (sw, sh)
    cached = getattr(window, '_h61_poisson_cache', None)
    if isinstance(cached, dict) and cached.get('key') == key:
        return list(cached.get('points') or [])
    x0 = max(42.0, sw * 0.045); x1 = min(sw - 42.0, sw * 0.955)
    y0 = max(56.0, sh * 0.060); y1 = min(sh - 70.0, sh * 0.925)
    width = max(1.0, x1 - x0); height = max(1.0, y1 - y0)
    min_dist = max(96.0, min(sw, sh) * float(H61_CENTER_MIN_DISTANCE_RATIO))
    cell = min_dist / math.sqrt(2.0)
    gw = max(1, int(math.ceil(width / cell))); gh = max(1, int(math.ceil(height / cell)))
    grid = [[None for _ in range(gh)] for _ in range(gw)]
    seed_bytes = hashlib.sha1(f'H61:{sw}x{sh}'.encode('ascii')).digest()
    rng = random.Random(int.from_bytes(seed_bytes[:8], 'little'))
    first = (x0 + width * 0.23, y0 + height * 0.19)
    points = [first]; active = [first]

    def gpos(p):
        return (min(gw - 1, max(0, int((p[0] - x0) / cell))),
                min(gh - 1, max(0, int((p[1] - y0) / cell))))

    gx, gy = gpos(first); grid[gx][gy] = first
    while active and len(points) < int(H61_CENTER_POINT_COUNT):
        ai = rng.randrange(len(active)); base = active[ai]; found = False
        for _ in range(24):
            ang = rng.random() * math.tau
            rad = min_dist * (1.0 + rng.random())
            p = (base[0] + math.cos(ang) * rad, base[1] + math.sin(ang) * rad)
            if p[0] < x0 or p[0] > x1 or p[1] < y0 or p[1] > y1:
                continue
            pgx, pgy = gpos(p); ok = True
            for ix in range(max(0, pgx - 2), min(gw, pgx + 3)):
                for iy in range(max(0, pgy - 2), min(gh, pgy + 3)):
                    q = grid[ix][iy]
                    if q is not None and math.hypot(p[0] - q[0], p[1] - q[1]) < min_dist:
                        ok = False; break
                if not ok:
                    break
            if not ok:
                continue
            grid[pgx][pgy] = p; points.append(p); active.append(p); found = True; break
        if not found:
            active.pop(ai)
    # A deterministic golden-angle fill covers rare wide-screen holes without clustering.
    idx = 0
    while len(points) < int(H61_CENTER_POINT_COUNT) and idx < int(H61_CENTER_POINT_COUNT) * 5:
        t = (idx + 0.5) / float(int(H61_CENTER_POINT_COUNT) * 5)
        r = math.sqrt(t)
        ang = idx * 2.399963229728653
        p = (x0 + width * (0.5 + 0.49 * r * math.cos(ang)),
             y0 + height * (0.5 + 0.49 * r * math.sin(ang)))
        if x0 <= p[0] <= x1 and y0 <= p[1] <= y1:
            if all(math.hypot(p[0] - q[0], p[1] - q[1]) >= min_dist * 0.62 for q in points):
                points.append(p)
        idx += 1
    window._h61_poisson_cache = {'key': key, 'points': list(points)}
    return list(points)


def _h61_center_quota_allows(window, frequency):
    try:
        freq = max(0, min(100, int(frequency)))
    except Exception:
        freq = int(H51_CENTER_FREQ_DEFAULT)
    if freq <= 0:
        window._h61_center_credit = 0; window._h61_center_frequency_seen = freq
        return False
    if freq >= 100:
        window._h61_center_credit = 0; window._h61_center_frequency_seen = freq
        return True
    if int(getattr(window, '_h61_center_frequency_seen', -1)) != freq:
        window._h61_center_frequency_seen = freq
        window._h61_center_credit = 0
    credit = int(getattr(window, '_h61_center_credit', 0) or 0) + freq
    allow = credit >= 100
    if allow:
        credit -= 100
    window._h61_center_credit = max(0, min(99, int(credit)))
    return bool(allow)


def _h61_candidate_center_score(window, vx, vy, angle, obstacles, recent, margin, disallow_center):
    sw = max(1.0, float(window.width())); sh = max(1.0, float(window.height()))
    cx, cy = window._placement_anchor_for_visual_center(window.full_text, float(vx), float(vy), int(angle))
    box = window._placement_box(window.full_text, cx, cy, int(angle))
    # Never solve center avoidance by making a lyric vertically invisible. Horizontal wrap is
    # a deliberate feature, so only non-wrap layouts require strict horizontal containment.
    vertical_out = max(0.0, -float(box[1])) + max(0.0, float(box[3]) - sh)
    horizontal_out = max(0.0, -float(box[0])) + max(0.0, float(box[2]) - sw)
    if vertical_out > 0.5:
        return None
    if not bool(getattr(window, 'horizontal_wrap', False)) and horizontal_out > 0.5:
        return None

    old = (int(getattr(window, 'x', 0) or 0), int(getattr(window, 'y', 0) or 0),
           int(getattr(window, 'angle', 0) or 0), QTransform(getattr(window, 'persp_transform', QTransform())))
    try:
        window.x = int(round(cx)); window.y = int(round(cy)); window.angle = int(angle)
        try:
            window.compute_perspective()
        except Exception:
            pass
        corridor_overlap = float(_h59_center_corridor_overlap(window, margin)) if disallow_center else 0.0
        cboxes = list(_h59_current_corridor_boxes(window, margin) or [])
    finally:
        window.x, window.y, window.angle = old[0], old[1], old[2]
        window.persp_transform = QTransform(old[3])

    if disallow_center and corridor_overlap > float(H61_CENTER_EPS):
        return None
    worst = 0.0; guard_worst = 0.0
    try:
        guard_pad = max(24.0, min(52.0, float(window._placement_metrics(window.full_text, window.font, window.spacing)[1]) * 0.42))
    except Exception:
        guard_pad = 32.0
    for ob in obstacles:
        try:
            obox, _oa, weight = ob[:3]
            obs = window._placement_visible_boxes(obox, sw, bool(getattr(window, 'horizontal_wrap', False)))
            worst = max(worst, float(window._placement_max_overlap(cboxes, obs)) * float(weight))
            obs_guard = window._placement_visible_boxes(
                window._placement_expand_box(obox, guard_pad), sw, bool(getattr(window, 'horizontal_wrap', False)))
            cg = [window._placement_expand_box(b, guard_pad) for b in cboxes]
            guard_worst = max(guard_worst, float(window._placement_max_overlap(cg, obs_guard)) * float(weight))
        except Exception:
            pass
    recent_penalty = 0.0
    for rx, ry, _ra in recent[-18:]:
        try:
            d = math.hypot(float(vx) - float(rx), float(vy) - float(ry))
            if d < 220.0:
                recent_penalty += (220.0 - d) / 220.0
        except Exception:
            pass
    # Lower is better. Center is already a hard constraint; overlap then recent density decide.
    return (
        worst * 10000.0 + guard_worst * 1800.0 + recent_penalty * 85.0 +
        horizontal_out * (0.015 if bool(getattr(window, 'horizontal_wrap', False)) else 0.2),
        int(round(cx)), int(round(cy)), int(angle), float(corridor_overlap), float(worst),
        float(vx), float(vy),
    )


def _h61_stable_birth_place(window, place_pre):
    """Run mature placement once, then atomically replace only the newborn anchor if needed.

    H59/H60 post-push is bypassed. Existing history/fading rows are read-only obstacles.
    """
    try:
        freq = max(0, min(100, int(getattr(window, '_h51_center_frequency_pct', H51_CENTER_FREQ_DEFAULT))))
    except Exception:
        freq = int(H51_CENTER_FREQ_DEFAULT)
    before_recent = list(getattr(window, '_placement_recent', []) or [])
    # Ask the mature H51/H53 stack for its ordinary whole-screen placement, but bypass H59's
    # center quota/post-push. The result remains a valid fallback candidate.
    quota_pre = globals().get('_h59_center_quota_allows')
    try:
        if callable(quota_pre):
            globals()['_h59_center_quota_allows'] = lambda _w, _f: True
        place_pre(window)
    finally:
        if callable(quota_pre):
            globals()['_h59_center_quota_allows'] = quota_pre

    allow_center = _h61_center_quota_allows(window, freq)
    if allow_center:
        try:
            write_error_log('H61稳定出生布局', detail=(
                f'frequency={freq}% | quota_allow=1 | placement=baseline | existing_rows=immutable'))
        except Exception:
            pass
        return

    margin = _h59_center_corridor_margin(window)
    baseline_overlap = float(_h59_center_corridor_overlap(window, margin))
    if baseline_overlap <= float(H61_CENTER_EPS):
        try:
            write_error_log('H61稳定出生布局', detail=(
                f'frequency={freq}% | quota_allow=0 | baseline_overlap={baseline_overlap:.4f} | '
                'placement=baseline-safe | existing_rows=immutable'))
        except Exception:
            pass
        return

    try:
        obstacles = list(window._placement_obstacles() or [])
    except Exception:
        obstacles = []
    points = _h61_poisson_points(window)
    # Rotate deterministic candidate order per lyric so consecutive lines do not choose the
    # same first safe pocket even when obstacles are sparse.
    seed_text = f'{str(getattr(window,"full_text","") or "")}|{int(getattr(window,"current_line",0) or 0)}'
    seed = int.from_bytes(hashlib.sha1(seed_text.encode('utf-8', errors='ignore')).digest()[:8], 'little')
    rng = random.Random(seed)
    points = list(points)
    rng.shuffle(points)
    angle_min = int(getattr(window, 'angle_min', -10) or -10)
    angle_max = int(getattr(window, 'angle_max', 10) or 10)
    best = None
    for idx, (vx, vy) in enumerate(points):
        angle = rng.randint(min(angle_min, angle_max), max(angle_min, angle_max))
        cand = _h61_candidate_center_score(
            window, vx, vy, angle, obstacles, before_recent, margin, True)
        if cand is not None and (best is None or cand[0] < best[0]):
            best = cand
    if best is None:
        # Preserve the mature baseline rather than moving the lyric off-screen or over another
        # row. This is a visible fallback, never a silent drop.
        try:
            write_error_log('H61稳定出生布局', detail=(
                f'frequency={freq}% | quota_allow=0 | baseline_overlap={baseline_overlap:.4f} | '
                f'placement=baseline-no-safe-candidate | candidates={len(points)} | existing_rows=immutable'))
        except Exception:
            pass
        return

    _score, nx, ny, na, center_overlap, worst_overlap, vx, vy = best
    window.x, window.y, window.angle = int(nx), int(ny), int(na)
    try:
        window.compute_perspective()
    except Exception:
        pass
    window._placement_recent = (before_recent + [(float(vx), float(vy), float(na))])[-18:]
    try:
        write_error_log('H61稳定出生布局', detail=(
            f'frequency={freq}% | quota_allow=0 | baseline_overlap={baseline_overlap:.4f} | '
            f'commit_overlap={center_overlap:.4f} | obstacle_overlap={worst_overlap:.4f} | '
            f'candidate=({int(round(vx))},{int(round(vy))}) | pool={len(points)} | existing_rows=immutable'))
    except Exception:
        pass


def _h61_activate_runtime():
    global _limbus_arm_render_emergency, _limbus_render_emergency_active
    if not all(name in globals() for name in ('LyricWindow', 'ControlPanel')):
        return
    try:
        if getattr(LyricWindow.place_randomly, '_limbus_layer', '') == 'H61':
            return
        start_pre = LyricWindow.start_lyric
        shared_pre = LyricWindow._shared_song_fragment_atlas
        install_pre = LyricWindow._install_song_fragment_atlas
        place_pre = LyricWindow.place_randomly
        arm_pre = globals().get('_limbus_arm_render_emergency')
        active_pre = globals().get('_limbus_render_emergency_active')

        def h61_install_song_fragment_atlas(window, payload):
            if isinstance(payload, dict) and payload.get('h61_row_fallback'):
                _h61_row_cache_init(window)
                key = payload.get('row_key')
                try:
                    window._h61_row_atlas_inflight.discard(key)
                except Exception:
                    pass
                window._h61_row_worker_active = False
                try:
                    if not payload.get('cancelled') and not payload.get('failed'):
                        image = payload.get('image')
                        if image is not None and not image.isNull():
                            pixmap = QPixmap.fromImage(image)
                            if not pixmap.isNull():
                                cmap = dict(payload.get('meta') or {})
                                shared = (pixmap, cmap, payload.get('style_sig'), int(payload.get('pixels', 0) or 0))
                                _h61_cache_row_shared(window, key, shared)
                    build_ms = float(payload.get('build_ms') or 0.0)
                    if build_ms >= float(H61_ROW_WARN_BUILD_MS) or payload.get('cancelled') or payload.get('failed'):
                        write_error_log('H61异步行Atlas后备', detail=(
                            f'build={build_ms:.1f}ms | result={"cancelled" if payload.get("cancelled") else ("failed" if payload.get("failed") else "ok")} | '
                            f'gui_build=0 | budget={int(H61_ROW_WORKER_BUDGET_MS)}ms'))
                except Exception:
                    pass
                try:
                    window.update()
                except Exception:
                    pass
                QTimer.singleShot(0, lambda w=window: _h61_kick_row_worker(w))
                return None
            out = install_pre(window, payload)
            try:
                if bool(getattr(window, '_song_fragment_atlas_performance_fused', False)):
                    _h61_schedule_row_atlas(window, str(getattr(window, 'full_text', '') or ''))
            except Exception:
                pass
            return out

        def h61_start_lyric(window, *args, **kwargs):
            result = start_pre(window, *args, **kwargs)
            try:
                text = str(getattr(window, 'full_text', '') or '')
                key, cached = _h61_row_cached_shared(window, text) if text else (None, None)
                window._h61_current_row_key = key
                window._h61_current_row_started_mono = time.monotonic() * 1000.0
                window._h61_current_row_shared = cached
                window._h61_current_row_sharp_locked = False
                if bool(getattr(window, '_song_fragment_atlas_performance_fused', False)) and text:
                    _h61_schedule_row_atlas(window, text)
            except Exception:
                pass
            return result

        def h61_shared_song_fragment_atlas(window):
            text = str(getattr(window, 'full_text', '') or '')
            # Normal full-song Atlas keeps authority when it exists.
            if not bool(getattr(window, '_song_fragment_atlas_performance_fused', False)):
                return shared_pre(window)
            if not text:
                return None
            key = _h61_row_key(window, text)
            if key != getattr(window, '_h61_current_row_key', None):
                window._h61_current_row_key = key
                window._h61_current_row_started_mono = time.monotonic() * 1000.0
                window._h61_current_row_shared = None
                window._h61_current_row_sharp_locked = False
            selected = getattr(window, '_h61_current_row_shared', None)
            if selected is not None:
                return selected
            _h61_schedule_row_atlas(window, text)
            _key, cached = _h61_row_cached_shared(window, text)
            if cached is not None and not bool(getattr(window, '_h61_current_row_sharp_locked', False)):
                age = max(0.0, time.monotonic() * 1000.0 - float(
                    getattr(window, '_h61_current_row_started_mono', 0.0) or 0.0))
                char_index = int(getattr(window, 'char_index', 0) or 0)
                early_chars = max(3, int(math.ceil(max(1, len(text)) * 0.28)))
                if age <= float(H61_ROW_EARLY_COMMIT_MS) and char_index <= early_chars:
                    window._h61_current_row_shared = cached
                    try:
                        write_error_log('H61异步景深材质早期提交', detail=(
                            f'age={age:.0f}ms | chars={char_index}/{len(text)} | row_material=freeze'))
                    except Exception:
                        pass
                    return cached
                window._h61_current_row_sharp_locked = True
            # Never synchronously call H60's _h60_build_line_shared from paint.
            return None

        def h61_place_randomly(window):
            return _h61_stable_birth_place(window, place_pre)

        if callable(arm_pre):
            def h61_arm_render_emergency(window, reason, elapsed_ms=0.0):
                out = arm_pre(window, reason, elapsed_ms)
                try:
                    if str(reason or '') == 'paint-hard-budget':
                        now = time.monotonic() * 1000.0
                        last = float(getattr(window, '_h61_last_hard_emergency_mono', 0.0) or 0.0)
                        count = int(getattr(window, '_h61_hard_emergency_repeat', 0) or 0)
                        count = count + 1 if last > 0.0 and now - last <= float(H61_EMERGENCY_REPEAT_WINDOW_MS) else 1
                        window._h61_hard_emergency_repeat = min(5, count)
                        window._h61_last_hard_emergency_mono = now
                        hold = min(float(H61_EMERGENCY_MAX_RECOVERY_MS),
                                   float(H61_EMERGENCY_BASE_RECOVERY_MS) + max(0, count - 1) * 260.0)
                        window._h61_hard_emergency_until = now + hold
                        window._h61_hard_emergency_serial = int(
                            getattr(window, '_h61_hard_emergency_serial', 0) or 0) + 1
                except Exception:
                    pass
                return out
            globals()['_limbus_arm_render_emergency'] = h61_arm_render_emergency

        if callable(active_pre):
            def h61_render_emergency_active(window):
                active = bool(active_pre(window))
                if not active:
                    return False
                try:
                    if str(getattr(window, '_limbus_render_emergency_reason', '') or '') == 'paint-hard-budget':
                        now = time.monotonic() * 1000.0
                        until = float(getattr(window, '_h61_hard_emergency_until', 0.0) or 0.0)
                        if until > 0.0 and now >= until:
                            window._limbus_render_emergency_fused = False
                            _limbus_restore_visual_timer_cadence(window)
                            serial = int(getattr(window, '_h61_hard_emergency_serial', 0) or 0)
                            if int(getattr(window, '_h61_hard_emergency_recovered_serial', -1)) != serial:
                                window._h61_hard_emergency_recovered_serial = serial
                                try:
                                    write_error_log('H61硬渲染降级自动恢复', detail=(
                                        f'serial={serial} | renderer=normal | style/depth/history=restored'))
                                except Exception:
                                    pass
                            return False
                except Exception:
                    pass
                return active
            globals()['_limbus_render_emergency_active'] = h61_render_emergency_active

        LyricWindow._install_song_fragment_atlas = h61_install_song_fragment_atlas
        LyricWindow._install_song_fragment_atlas._limbus_layer = 'H61'
        LyricWindow.start_lyric = h61_start_lyric
        LyricWindow.start_lyric._limbus_layer = 'H61'
        LyricWindow._shared_song_fragment_atlas = h61_shared_song_fragment_atlas
        LyricWindow._shared_song_fragment_atlas._limbus_layer = 'H61'
        LyricWindow._shared_song_fragment_atlas._limbus_policy = 'never-build-row-atlas-in-paint'
        LyricWindow.place_randomly = h61_place_randomly
        LyricWindow.place_randomly._limbus_layer = 'H61'
        LyricWindow.place_randomly._limbus_policy = 'birth-only-blue-noise-greedy-center-safe-existing-rows-immutable'
    except Exception as exc:
        try:
            write_error_log('H61稳定出生布局与异步景深安装失败', exc)
        except Exception:
            pass


if '_h57_activate_runtime' in globals():
    _h57_activate_runtime()
# H58 makes font/color/outline/shadow/glow one immutable pre-depth material.
if '_h58_activate_runtime' in globals():
    _h58_activate_runtime()
# H59 closes exit first-frame, center-motion corridor and scoped script preview.
if '_h59_activate_runtime' in globals():
    _h59_activate_runtime()
# H60 keeps depth alive after the song-Atlas fuse, makes center correction transactional, and removes redundant preview blockers.
if '_h60_activate_runtime' in globals():
    _h60_activate_runtime()


# H62 idle-resume continuity + progressive blur-decay exit -----------------------
# Field H61 logs proved that provider-idle suppression itself behaved correctly: the current
# line entered fading and two resident history rows were explicitly held.  The actual pop
# happened when the first lyric after the instrumental gap arrived: because full_text was
# intentionally blank, the generic "first locate/reload" branch cleared both history/fading.
# The base timeline branch above now preserves those rows only for suppressed_line -> next-line
# forward resume; ordinary reload/seek clearing remains unchanged.
#
# H62 also adds an age-driven optical exit.  It never replaces random fixed Z depth.  Instead
# it takes H57's already-composited birth material (text + outline + shadow + glow + depth) as
# the source and asynchronously prepares two *additional* low-pass stages.  Thus the optical
# model is additive: effective appearance = birth-depth material + residence-age defocus.
# No blur raster work is allowed in paintEvent; QImage filtering runs on a worker and QPixmap
# installation is routed back through the existing GUI signal.
H62_EXIT_EFFECT_BLUR_DECAY = 'blur_decay'
H62_BLUR_MID_LEVELS = 2
H62_BLUR_MAX_LEVELS = 5
H62_BLUR_WORKER_BUDGET_MS = 460.0
H62_BLUR_WARN_MS = 40.0
H62_BLUR_MIN_HOLD_MS = 6500.0
H62_BLUR_MAX_HOLD_MS = 18000.0
H62_BLUR_MIN_RELEASE_MS = 1400.0
H62_BLUR_MAX_RELEASE_MS = 4200.0
H62_BLUR_FADE_START = 0.58

import weakref as _h62_weakref


def _h62_smoothstep(value):
    x = max(0.0, min(1.0, float(value)))
    return x * x * (3.0 - 2.0 * x)


def _h62_decay_durations(row):
    try:
        nominal = float(_h16_exit_duration_ms(row))
    except Exception:
        nominal = 3600.0
    hold = max(float(H62_BLUR_MIN_HOLD_MS), min(float(H62_BLUR_MAX_HOLD_MS), nominal * 3.2))
    release = max(float(H62_BLUR_MIN_RELEASE_MS), min(float(H62_BLUR_MAX_RELEASE_MS), nominal * 0.90))
    return float(hold), float(release)


def _h62_decay_progress(row, now_mono=None):
    now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
    hold_ms, release_ms = _h62_decay_durations(row)
    release_start = float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0)
    if release_start > 0.0:
        p0 = max(0.0, min(1.0, float(getattr(row, '_h62_decay_release_progress', 0.0) or 0.0)))
        elapsed = max(0.0, now - release_start)
        # H59's first-visible-frame contract must also cover H62's own age/release clock.
        # A GUI stall right after capacity release may not advance the blur-decay all the way
        # to invisible before one released frame has actually been painted.
        if int(getattr(row, '_h62_decay_release_draw_count', 0) or 0) <= 0:
            catchup = float(globals().get('H59_EXIT_FIRST_FRAME_CATCHUP_MS', 120.0) or 120.0)
            elapsed = min(elapsed, max(16.0, catchup))
        q = max(0.0, min(1.0, elapsed / max(1.0, release_ms)))
        return max(p0, min(1.0, p0 + (1.0 - p0) * _h62_smoothstep(q)))
    started = float(getattr(row, '_h62_decay_hold_mono', 0.0) or 0.0)
    if started <= 0.0:
        started = now
        row._h62_decay_hold_mono = now
    return max(0.0, min(1.0, (now - started) / max(1.0, hold_ms)))


def _h62_decay_mix(progress):
    """Return base/mid/max material weights plus final visibility."""
    p = max(0.0, min(1.0, float(progress)))
    if p <= 0.50:
        t = _h62_smoothstep(p / 0.50)
        base_w, mid_w, max_w = 1.0 - t, t, 0.0
    else:
        t = _h62_smoothstep((p - 0.50) / 0.50)
        base_w, mid_w, max_w = 0.0, 1.0 - t, t
    if p <= float(H62_BLUR_FADE_START):
        visibility = 1.0
    else:
        visibility = 1.0 - _h62_smoothstep(
            (p - float(H62_BLUR_FADE_START)) / max(0.001, 1.0 - float(H62_BLUR_FADE_START)))
    return (float(base_w), float(mid_w), float(max_w), max(0.0, min(1.0, float(visibility))))


def _h62_final_source_shared(row):
    """Return the immutable material H57 would draw before H62 adds residence blur."""
    try:
        enabled = bool(getattr(row, '_h54_depth_enabled', False))
        level = int(getattr(row, '_h54_depth_level', 1) or 1)
        strength = int(getattr(row, '_h54_depth_strength_pct', H53_DEPTH_DEFAULT_STRENGTH) or 0)
        if enabled and level > 1 and strength > 0:
            cached = getattr(row, '_h57_depth_composite_cache', None)
            if isinstance(cached, dict) and cached.get('shared') is not None:
                return cached.get('shared')
            # Do not synchronously build a depth composite here. Let H57 draw once and cache it;
            # H62 will queue its extra blur after that frame.
            return None
        return getattr(row, '_shared_fragment_atlas', None)
    except Exception:
        return None


def _h62_pack_entries_image(entries, style_sig):
    if not entries:
        return None
    total_area = 0.0; max_w = 1; max_h = 1
    for _ch, image, _left, _top, _lw, _lh, _ss in entries:
        iw = max(1, int(image.width())); ih = max(1, int(image.height()))
        total_area += float(iw + 4) * float(ih + 4)
        max_w = max(max_w, iw + 4); max_h = max(max_h, ih + 4)
    target_w = int(max(max_w, min(int(H56_ATLAS_MAX_EDGE), max(256, math.ceil(math.sqrt(max(1.0, total_area)) * 1.35)))))
    positions = {}; x = 2; y = 2; shelf_h = 0; used_w = 2
    for ch, image, _left, _top, _lw, _lh, _ss in sorted(
            entries, key=lambda item: (int(item[1].height()), int(item[1].width()), str(item[0])), reverse=True):
        iw = int(image.width()); ih = int(image.height())
        if x + iw + 2 > target_w and x > 2:
            x = 2; y += shelf_h + 4; shelf_h = 0
        positions[ch] = (x, y, iw, ih)
        x += iw + 4; shelf_h = max(shelf_h, ih); used_w = max(used_w, x)
    used_h = int(y + shelf_h + 2); used_w = int(max(1, min(target_w, used_w)))
    pixels = int(used_w * used_h)
    if (used_w > int(H56_ATLAS_MAX_EDGE) or used_h > int(H56_ATLAS_MAX_EDGE) or
            pixels > int(H56_ATLAS_MAX_PIXELS)):
        return None
    atlas = QImage(int(used_w), int(used_h), QImage.Format_ARGB32_Premultiplied)
    if atlas.isNull():
        return None
    atlas.fill(Qt.transparent)
    qp = QPainter(atlas)
    qp.setRenderHint(QPainter.Antialiasing, True)
    qp.setRenderHint(QPainter.SmoothPixmapTransform, True)
    cmap = {}
    for ch, image, left, top, lw, lh, source_ss in entries:
        px, py, iw, ih = positions[ch]
        qp.drawImage(QPointF(float(px), float(py)), image)
        cmap[str(ch)] = (
            QRectF(float(px), float(py), float(iw), float(ih)),
            float(left), float(top), float(lw), float(lh), float(source_ss),
        )
    qp.end()
    return {'image': atlas, 'meta': cmap, 'style_sig': style_sig, 'pixels': pixels}


def _h62_filter_shared_image(source_image, cmap, style_sig, text, levels, deadline_perf):
    if source_image is None or source_image.isNull() or not cmap or not text or int(levels) <= 0:
        return None
    unique = []; seen = set()
    for ch in str(text):
        if not ch or ch.isspace() or ch in seen:
            continue
        if ch not in cmap:
            return None
        seen.add(ch); unique.append(ch)
    if not unique or len(unique) > int(H56_ATLAS_MAX_GLYPHS):
        return None
    entries = []
    for ch in unique:
        if time.perf_counter() > float(deadline_perf):
            return None
        raw = cmap.get(ch)
        if raw is None:
            return None
        if len(raw) >= 6:
            source, left, top, lw, lh, source_ss = raw[:6]
        else:
            source, left, top, lw, lh = raw[:5]; source_ss = 1.0
        source_ss = max(1.0, float(source_ss or 1.0))
        crop = source_image.copy(QRectF(source).toAlignedRect())
        if crop.isNull():
            return None
        logical_span = max(2.0, min(34.0, (2.0 ** int(levels)) * 1.45))
        pad = max(4, min(128, int(math.ceil(logical_span * source_ss * 1.45))))
        padded = QImage(int(crop.width() + pad * 2), int(crop.height() + pad * 2), QImage.Format_ARGB32_Premultiplied)
        if padded.isNull():
            return None
        padded.fill(Qt.transparent)
        qp = QPainter(padded); qp.setRenderHint(QPainter.SmoothPixmapTransform, True)
        qp.drawImage(QPointF(float(pad), float(pad)), crop); qp.end()
        filtered = _h56_lowpass_image(padded, int(levels))
        if filtered is None or filtered.isNull():
            return None
        entries.append((str(ch), filtered, float(left), float(top), float(lw), float(lh), source_ss))
    return _h62_pack_entries_image(entries, style_sig)


def _h62_find_row(window, token):
    if token is None:
        return None
    for row in list(getattr(window, 'history_lines', []) or []) + list(getattr(window, 'fading_lines', []) or []):
        if getattr(row, '_h62_decay_token', None) == token:
            return row
    return None


def _h62_schedule_decay_atlases(row):
    if row is None or str(getattr(row, 'exit_effect', '') or '').strip().lower() != H62_EXIT_EFFECT_BLUR_DECAY:
        return
    if bool(getattr(row, '_h62_decay_worker_started', False)):
        return
    owner_ref = getattr(row, '_h62_owner_ref', None)
    window = owner_ref() if callable(owner_ref) else None
    if window is None:
        return
    shared = _h62_final_source_shared(row)
    if shared is None:
        return
    try:
        sheet, cmap, style_sig, _pixels = shared
        if sheet is None or sheet.isNull() or not cmap:
            return
        source_image = sheet.toImage()
        if source_image is None or source_image.isNull():
            return
        try: source_image.setDevicePixelRatio(1.0)
        except Exception: pass
        cmap_copy = dict(cmap)
        text = str(getattr(row, 'text', '') or '')
        window._h62_decay_serial = int(getattr(window, '_h62_decay_serial', 0) or 0) + 1
        token = int(window._h62_decay_serial)
        row._h62_decay_token = token
        row._h62_decay_worker_started = True
    except Exception:
        return

    def worker():
        started = time.perf_counter()
        deadline = started + float(H62_BLUR_WORKER_BUDGET_MS) / 1000.0
        mid = max_stage = None
        try:
            mid = _h62_filter_shared_image(
                source_image, cmap_copy, style_sig, text, int(H62_BLUR_MID_LEVELS), deadline)
            if mid is not None and time.perf_counter() <= deadline:
                max_stage = _h62_filter_shared_image(
                    source_image, cmap_copy, style_sig, text, int(H62_BLUR_MAX_LEVELS), deadline)
        except Exception:
            mid = max_stage = None
        elapsed = (time.perf_counter() - started) * 1000.0
        payload = {
            'h62_blur_decay': True, 'token': token, 'build_ms': float(elapsed),
            'mid': mid, 'max': max_stage,
            'failed': bool(mid is None or max_stage is None),
        }
        try:
            window.song_fragment_atlas_ready.emit(payload)
        except Exception:
            pass

    threading.Thread(target=worker, name='LimbusLyric-H62BlurDecay', daemon=True).start()


def _h62_queue_decay_build(row):
    if row is None or bool(getattr(row, '_h62_decay_build_queued', False)) or bool(getattr(row, '_h62_decay_worker_started', False)):
        return
    row._h62_decay_build_queued = True
    def later(r=row):
        try:
            r._h62_decay_build_queued = False
            _h62_schedule_decay_atlases(r)
        except Exception:
            pass
    QTimer.singleShot(0, later)


def _h62_depth_scale_for_row(row):
    try:
        if not bool(getattr(row, '_h54_depth_enabled', False)):
            return 1.0
        level = int(getattr(row, '_h54_depth_level', 1) or 1)
        layers = max(2, min(6, int(getattr(row, '_h54_depth_layers', H53_DEPTH_DEFAULT_LAYERS) or H53_DEPTH_DEFAULT_LAYERS)))
        strength = int(getattr(row, '_h54_depth_strength_pct', H53_DEPTH_DEFAULT_STRENGTH) or 0)
        return float(_h54_depth_scale(level, layers, strength))
    except Exception:
        return 1.0


def _h62_activate_runtime():
    if not all(name in globals() for name in ('ControlPanel', 'LyricWindow', 'FadingLine')):
        return
    try:
        if getattr(FadingLine.draw, '_limbus_layer', '') == 'H62':
            return
        control_init_pre = ControlPanel.__init__
        fading_init_pre = FadingLine.__init__
        begin_pre = FadingLine.begin_fade
        update_pre = FadingLine.update
        hold_pre = FadingLine.update_hold
        draw_pre = FadingLine.draw
        make_history_pre = LyricWindow._make_history_line
        update_shake_pre = LyricWindow.update_shake
        install_pre = LyricWindow._install_song_fragment_atlas

        def h62_fading_init(row, *args, **kwargs):
            fading_init_pre(row, *args, **kwargs)
            now = time.monotonic() * 1000.0
            row._h62_decay_hold_mono = (
                now if str(getattr(row, 'exit_effect', '') or '').strip().lower() == H62_EXIT_EFFECT_BLUR_DECAY else 0.0)
            row._h62_decay_release_mono = 0.0
            row._h62_decay_release_progress = 0.0
            row._h62_decay_release_draw_count = 0
            row._h62_decay_draw_count = 0
            row._h62_decay_progress = 0.0
            row._h62_decay_expired = False
            row._h62_decay_mid_shared = None
            row._h62_decay_max_shared = None
            row._h62_decay_worker_started = False
            row._h62_decay_build_queued = False
            row._h62_decay_build_failed = False
            row._h62_decay_token = None
            row._h62_owner_ref = None

        def h62_make_history(window, text):
            row = make_history_pre(window, text)
            if row is not None:
                try:
                    row._h62_owner_ref = _h62_weakref.ref(window)
                    if str(getattr(row, 'exit_effect', '') or '').strip().lower() == H62_EXIT_EFFECT_BLUR_DECAY:
                        row._h62_decay_hold_mono = time.monotonic() * 1000.0
                        _h62_queue_decay_build(row)
                except Exception:
                    pass
            return row

        def h62_begin_fade(row):
            now = time.monotonic() * 1000.0
            effect = str(getattr(row, 'exit_effect', 'fade') or 'fade').strip().lower()
            p0 = _h62_decay_progress(row, now) if effect == H62_EXIT_EFFECT_BLUR_DECAY else 0.0
            result = begin_pre(row)
            if effect == H62_EXIT_EFFECT_BLUR_DECAY:
                row._h62_decay_release_mono = now
                row._h62_decay_release_progress = p0
                row._h62_decay_release_draw_count = 0
                row._h62_decay_progress = p0
                row.alpha = 255
                _h62_queue_decay_build(row)
            return result

        def h62_update_hold(row):
            changed = bool(hold_pre(row))
            if str(getattr(row, 'exit_effect', '') or '').strip().lower() != H62_EXIT_EFFECT_BLUR_DECAY:
                return changed
            p = _h62_decay_progress(row)
            row._h62_decay_progress = p
            row.alpha = 255
            if p >= 1.0:
                row._h62_decay_expired = True
            _h62_queue_decay_build(row)
            return True

        def h62_update(row):
            if str(getattr(row, 'exit_effect', '') or '').strip().lower() != H62_EXIT_EFFECT_BLUR_DECAY:
                return update_pre(row)
            p = _h62_decay_progress(row)
            row._h62_decay_progress = p
            row.alpha = 255
            _h62_queue_decay_build(row)
            if p < 0.84:
                try: row._update_shake_motion()
                except Exception: pass
            if p >= 1.0:
                row.release_render_resources()
                return False
            return True

        def _draw_pass(row, painter, shared, opacity, scale):
            if shared is None or float(opacity) <= 0.002:
                return None
            old_alpha = int(getattr(row, 'alpha', 255) or 255)
            old_mode = str(getattr(row, 'mode', 'chinese') or 'chinese')
            old_effect = str(getattr(row, 'exit_effect', 'fade') or 'fade')
            try:
                row.alpha = max(1, min(255, int(round(255.0 * float(opacity)))))
                # Force the baked material path even for western text: outline/glow/depth are
                # already pixels in this Atlas and must fade as one optical object.
                row.mode = 'chinese'
                row.exit_effect = 'fade'
                return _h57_draw_row_with_active_order(row, painter, draw_pre, shared, scale)
            finally:
                row.exit_effect = old_effect
                row.mode = old_mode
                row.alpha = old_alpha

        def h62_draw(row, painter):
            if str(getattr(row, 'exit_effect', '') or '').strip().lower() != H62_EXIT_EFFECT_BLUR_DECAY:
                return draw_pre(row, painter)
            p = _h62_decay_progress(row)
            row._h62_decay_progress = p
            base = _h62_final_source_shared(row)
            if base is None:
                # Let H57 establish/cache the authoritative birth-depth material once. Queue
                # the residence blur only after this draw; never build it inside paint.
                result = draw_pre(row, painter)
                _h62_queue_decay_build(row)
                return result
            _h62_queue_decay_build(row)
            mid = getattr(row, '_h62_decay_mid_shared', None)
            max_stage = getattr(row, '_h62_decay_max_shared', None)
            bw, mw, xw, visibility = _h62_decay_mix(p)
            if mid is None:
                bw += mw; mw = 0.0
            if max_stage is None:
                if mid is not None:
                    mw += xw
                else:
                    bw += xw
                xw = 0.0
            scale = _h62_depth_scale_for_row(row)
            result = None
            if bw > 0.002:
                result = _draw_pass(row, painter, base, bw * visibility, scale)
            if mw > 0.002:
                result = _draw_pass(row, painter, mid, mw * visibility, scale)
            if xw > 0.002:
                result = _draw_pass(row, painter, max_stage, xw * visibility, scale)
            row._h62_decay_draw_count = int(getattr(row, '_h62_decay_draw_count', 0) or 0) + 1
            if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
                row._h62_decay_release_draw_count = int(getattr(row, '_h62_decay_release_draw_count', 0) or 0) + 1
            return result

        def h62_update_shake(window):
            result = update_shake_pre(window)
            expired = []
            for row in list(getattr(window, 'history_lines', []) or []):
                if bool(getattr(row, '_h62_decay_expired', False)):
                    expired.append(row)
            if expired:
                window.history_lines = [r for r in window.history_lines if r not in expired]
                for row in expired:
                    try: row.release_render_resources()
                    except Exception: pass
                try:
                    write_error_log('H62渐进失焦历史自然退休', detail=(
                        f'count={len(expired)} | history_left={len(window.history_lines)} | reason=age-blur-invisible'))
                except Exception:
                    pass
                try: window.update()
                except Exception: pass
            return result

        def h62_install(window, payload):
            if isinstance(payload, dict) and payload.get('h62_blur_decay'):
                row = _h62_find_row(window, payload.get('token'))
                if row is None:
                    return None
                try:
                    for key, attr in (('mid', '_h62_decay_mid_shared'), ('max', '_h62_decay_max_shared')):
                        stage = payload.get(key)
                        if not isinstance(stage, dict):
                            continue
                        image = stage.get('image')
                        if image is None or image.isNull():
                            continue
                        pix = QPixmap.fromImage(image)
                        if pix.isNull():
                            continue
                        setattr(row, attr, (
                            pix, dict(stage.get('meta') or {}), stage.get('style_sig'),
                            int(stage.get('pixels', 0) or 0)))
                    row._h62_decay_build_failed = bool(payload.get('failed'))
                    build_ms = float(payload.get('build_ms', 0.0) or 0.0)
                    if build_ms >= float(H62_BLUR_WARN_MS) or bool(payload.get('failed')):
                        write_error_log('H62渐进失焦Atlas后台构建', detail=(
                            f'build={build_ms:.1f}ms | mid={int(getattr(row,"_h62_decay_mid_shared",None) is not None)} | '
                            f'max={int(getattr(row,"_h62_decay_max_shared",None) is not None)} | '
                            f'failed={int(bool(payload.get("failed")))} | gui_filter=0'))
                    window.update()
                except Exception:
                    pass
                return None
            return install_pre(window, payload)

        def h62_control_init(panel, *args, **kwargs):
            try:
                saved = str((load_all_config().get('settings') or {}).get('h12_exit_effect', '') or '').strip().lower()
            except Exception:
                saved = ''
            control_init_pre(panel, *args, **kwargs)
            try:
                combo = getattr(panel, 'h12_exit_combo', None)
                if combo is not None:
                    if combo.findData(H62_EXIT_EFFECT_BLUR_DECAY) < 0:
                        instant_idx = combo.findData('instant')
                        insert_at = instant_idx if instant_idx >= 0 else combo.count()
                        combo.insertItem(insert_at, '渐进失焦 / 模糊退场', H62_EXIT_EFFECT_BLUR_DECAY)
                    selected = saved if saved == H62_EXIT_EFFECT_BLUR_DECAY else str(getattr(panel.lyric_window, 'exit_effect', 'fade') or 'fade')
                    idx = combo.findData(selected)
                    if idx >= 0:
                        combo.blockSignals(True); combo.setCurrentIndex(idx); combo.blockSignals(False)
                        if selected == H62_EXIT_EFFECT_BLUR_DECAY:
                            panel.lyric_window.exit_effect = H62_EXIT_EFFECT_BLUR_DECAY
                    combo.setToolTip(
                        '“渐进失焦 / 模糊退场”会让历史字幕随着停留时间逐渐柔化并消失，同时保留原有描边、发光和景深风格。')

                    def on_exit_changed(_idx):
                        if str(combo.currentData() or '') != H62_EXIT_EFFECT_BLUR_DECAY:
                            return
                        for row in list(getattr(panel.lyric_window, 'history_lines', []) or []) + list(getattr(panel.lyric_window, 'fading_lines', []) or []):
                            try:
                                previous = str(getattr(row, 'exit_effect', '') or '').strip().lower()
                                row.exit_effect = H62_EXIT_EFFECT_BLUR_DECAY
                                if previous != H62_EXIT_EFFECT_BLUR_DECAY:
                                    now = time.monotonic() * 1000.0
                                    row._h62_decay_hold_mono = now
                                    row._h62_decay_release_mono = 0.0
                                    row._h62_decay_release_progress = 0.0
                                    row._h62_decay_release_draw_count = 0
                                    row._h62_decay_draw_count = 0
                                    row._h62_decay_progress = 0.0
                                    row._h62_decay_expired = False
                                row._h62_owner_ref = _h62_weakref.ref(panel.lyric_window)
                                _h62_queue_decay_build(row)
                            except Exception:
                                pass
                    combo.currentIndexChanged.connect(on_exit_changed)
            except Exception as exc:
                try: write_error_log('H62渐进失焦退场界面初始化失败', exc)
                except Exception: pass

        FadingLine.__init__ = h62_fading_init
        FadingLine.__init__._limbus_layer = 'H62'
        FadingLine.begin_fade = h62_begin_fade
        FadingLine.begin_fade._limbus_layer = 'H62'
        FadingLine.update_hold = h62_update_hold
        FadingLine.update_hold._limbus_layer = 'H62'
        FadingLine.update = h62_update
        FadingLine.update._limbus_layer = 'H62'
        FadingLine.update._limbus_policy = 'age-defocus-continuous-through-capacity-release'
        FadingLine.draw = h62_draw
        FadingLine.draw._limbus_layer = 'H62'
        FadingLine.draw._limbus_policy = 'birth-depth-material-plus-async-residence-lowpass-no-paint-raster'
        LyricWindow._make_history_line = h62_make_history
        LyricWindow._make_history_line._limbus_layer = 'H62'
        LyricWindow.update_shake = h62_update_shake
        LyricWindow.update_shake._limbus_layer = 'H62'
        LyricWindow._install_song_fragment_atlas = h62_install
        LyricWindow._install_song_fragment_atlas._limbus_layer = 'H62'
        ControlPanel.__init__ = h62_control_init
        ControlPanel.__init__._limbus_layer = 'H62'
    except Exception as exc:
        try: write_error_log('H62空白段连续性与渐进失焦退场安装失败', exc)
        except Exception: pass

# H63 blur-decay release + KuGou same-track restart display closure -----------------------
# H62 field evidence exposed a first-frame-accounting deadlock: when the authoritative H57
# birth material was temporarily unavailable, h62_draw() used the mature fallback renderer and
# returned early without incrementing _h62_decay_release_draw_count. The row was visibly painted,
# but _h62_decay_progress() believed that no release frame had ever reached the user and therefore
# capped elapsed release time to H59's 120ms first-frame allowance forever. Fading rows accumulated
# until the emergency queue valve removed them. H63 counts *any completed draw*, including fallback,
# as a real visible release frame, and canonicalizes every blur-decay row already resident in
# fading_lines into release phase even when a historical producer appended it without begin_fade().
#
# A separate H51 frozen-KuGou field log showed no cross-song lyric payload takeover. Instead, a
# same-track restart retained a ~198s visual-rail master while HostV2 had already observed a fresh
# ~7s Slider sample. Clicking Start rendered the last lyric line once before HostV2 re-anchored the
# display to ~8s. H63 uses that already-observed, recent HostV2 candidate only on explicit user Start
# and only for a large backwards disagreement on the same bound track. This is display-only: it
# grants neither duration nor seek authority and does not alter normal track-switch ownership.
H63_KUGOU_START_PENDING_MAX_AGE_MS = 1800.0
H63_KUGOU_START_BACKWARD_MIN_MS = 8000.0
H63_KUGOU_START_BACKWARD_DURATION_RATIO = 0.035


def _h63_blur_decay_release_row(row, owner=None, reason='fading-membership'):
    """Ensure a blur-decay row in the fading lane actually owns H62 release time."""
    if row is None or str(getattr(row, 'exit_effect', '') or '').strip().lower() != H62_EXIT_EFFECT_BLUR_DECAY:
        return False
    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        return False
    try:
        if owner is not None and getattr(row, '_h62_owner_ref', None) is None:
            row._h62_owner_ref = _h62_weakref.ref(owner)
    except Exception:
        pass
    try:
        row.begin_fade()
    except Exception:
        return False
    try:
        if not bool(getattr(row, '_h63_release_adopt_logged', False)):
            row._h63_release_adopt_logged = True
            write_error_log('H63渐进失焦退场释放接管', detail=(
                f'reason={reason} | text_chars={len(str(getattr(row,"text","") or ""))} | '
                f'progress={float(getattr(row,"_h62_decay_progress",0.0) or 0.0):.3f}'))
    except Exception:
        pass
    return True


def _h63_kugou_user_start_pending_reanchor(panel):
    """Repair stale same-track display time from an already-observed HostV2 Slider sample."""
    try:
        if str(panel.player_combo.currentText() or '') != '酷狗音乐':
            return False
        sync = panel.media_sync
        if str(sync._process_stem(getattr(sync, '_process_hint', '')) or '') not in ('kgmusic', 'kugou'):
            return False
        loaded = str(getattr(panel, '_loaded_track_key', '') or '')
        track = str(getattr(sync, '_track_key', '') or '')
        if not loaded or not track or loaded != track:
            return False
        if int(getattr(sync, '_track_identity_player_epoch', -1)) != int(getattr(sync, '_media_player_epoch', 0) or 0):
            return False
        pending = getattr(sync, '_kugou_host_v2_progress_pending', None)
        if not isinstance(pending, dict):
            return False
        source_key = str(pending.get('source_key') or '')
        if not ('uia-range:Slider:' in source_key or 'uia-range:ProgressBar:' in source_key):
            return False
        now = time.monotonic() * 1000.0
        age = max(0.0, now - float(pending.get('last_mono') or 0.0))
        if age > float(H63_KUGOU_START_PENDING_MAX_AGE_MS):
            return False
        fresh = max(0.0, float(pending.get('last') or 0.0))
        if fresh <= 0.0:
            return False
        if not bool(getattr(sync, '_kugou_rail_master_active', False)):
            return False
        current = max(0.0, float(getattr(sync, '_kugou_rail_master_position_ms', 0.0) or 0.0))
        try:
            if str(getattr(sync, '_kugou_rail_master_status', '') or '') == 'playing':
                anchor = float(getattr(sync, '_kugou_rail_master_anchor_mono', now) or now)
                current += max(0.0, now - anchor)
        except Exception:
            pass
        duration = max(0.0, float(getattr(sync, '_uia_duration_ms', 0.0) or (getattr(sync, '_state', {}) or {}).get('duration_ms') or 0.0))
        threshold = max(float(H63_KUGOU_START_BACKWARD_MIN_MS), duration * float(H63_KUGOU_START_BACKWARD_DURATION_RATIO))
        delta = current - fresh
        if delta < threshold:
            return False
        if not sync._kugou_seed_rail_local_master(
                fresh, status='playing', reason='h63-user-start-host-pending', absolute=False, now_ms=now):
            return False
        try:
            lw = panel.lyric_window
            lw._last_position_ms = int(round(fresh))
            lw.displayed_line_index = -1
            lw._precision_handoff_pending = None
            lw._precision_handoff_visible_floor = None
        except Exception:
            pass
        try:
            write_error_log('H63酷狗同曲重新开始展示预锚', detail=(
                f'track={track} | stale={int(round(current))}ms | host_pending={int(round(fresh))}ms | '
                f'delta={int(round(delta))}ms | age={int(round(age))}ms | '
                'authority=display-only | duration-authority=unchanged | seek-authority=0'))
        except Exception:
            pass
        return True
    except Exception:
        return False


def _h63_activate_runtime():
    if not all(name in globals() for name in ('ControlPanel', 'LyricWindow', 'FadingLine')):
        return
    try:
        if getattr(FadingLine.draw, '_limbus_layer', '') == 'H63':
            return
        draw_pre = FadingLine.draw
        update_fading_pre = LyricWindow.update_fading
        start_pre = ControlPanel.start

        def h63_fading_draw(row, painter):
            effect = str(getattr(row, 'exit_effect', '') or '').strip().lower()
            before_draw = int(getattr(row, '_h62_decay_draw_count', 0) or 0)
            before_release = int(getattr(row, '_h62_decay_release_draw_count', 0) or 0)
            result = draw_pre(row, painter)
            if effect == H62_EXIT_EFFECT_BLUR_DECAY:
                # H62's normal composite branch already increments both counters. Only fill the
                # accounting hole when its fallback early-return actually rendered the row.
                if int(getattr(row, '_h62_decay_draw_count', 0) or 0) <= before_draw:
                    row._h62_decay_draw_count = before_draw + 1
                if (float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0 and
                        int(getattr(row, '_h62_decay_release_draw_count', 0) or 0) <= before_release):
                    row._h62_decay_release_draw_count = before_release + 1
                    if not bool(getattr(row, '_h63_release_fallback_draw_logged', False)):
                        row._h63_release_fallback_draw_logged = True
                        try:
                            write_error_log('H63渐进失焦退场首帧确认', detail=(
                                'source=completed-draw-fallback-or-composite | first-frame-guard=release'))
                        except Exception:
                            pass
            return result

        def h63_update_fading(window):
            # Every object in fading_lines is semantically in release phase. Historical producers
            # that append snapshots directly must not inherit H62's long history-hold clock.
            for row in list(getattr(window, 'fading_lines', []) or []):
                _h63_blur_decay_release_row(row, window, reason='fading-membership')
            return update_fading_pre(window)

        def h63_start(panel):
            # The field failure happens before _launch_current_lyrics: a fresh HostV2 candidate
            # is already cached while the old same-track visual master still points near song-end.
            # Seed display time before Start renders the timeline. No media operation is issued.
            _h63_kugou_user_start_pending_reanchor(panel)
            return start_pre(panel)

        FadingLine.draw = h63_fading_draw
        FadingLine.draw._limbus_layer = 'H63'
        FadingLine.draw._limbus_policy = 'any-completed-draw-satisfies-h62-release-first-frame'
        LyricWindow.update_fading = h63_update_fading
        LyricWindow.update_fading._limbus_layer = 'H63'
        LyricWindow.update_fading._limbus_policy = 'fading-membership-implies-blur-decay-release-phase'
        ControlPanel.start = h63_start
        ControlPanel.start._limbus_layer = 'H63'
        ControlPanel.start._limbus_policy = 'kugou-same-track-user-start-fresh-host-display-reanchor-only'
    except Exception as exc:
        try: write_error_log('H63渐进失焦释放与酷狗同曲重启展示安装失败', exc)
        except Exception: pass

# H61 removes row-Atlas work from paint, bounds transient emergency, and places center-avoiding rows once at birth.
if '_h61_activate_runtime' in globals():
    _h61_activate_runtime()
# H62 preserves idle-gap residents on resume and adds additive age-defocus exit material.
if '_h62_activate_runtime' in globals():
    _h62_activate_runtime()
# H63 closes blur-decay release accounting and same-track KuGou Start display staleness.
if '_h63_activate_runtime' in globals():
    _h63_activate_runtime()


# H64 capacity-aware blur-decay residency -----------------------------------------
# H63 field logs showed a semantic mismatch: visible_stack/fade_lane correctly changed to 6,
# but H62's history-age clock remained independent of that user capacity. During dense lyrics
# the oldest history row could therefore reach age-blur-invisible at live_count=5, just before
# the sixth row was born, making a requested six-row stack hover around four/five rows.
#
# H64 makes capacity a *soft visual residency target* for blur-decay only. While a current lyric
# is actively present, age defocus still progresses, but its speed follows stack fill and natural
# age retirement is parked below invisibility. Capacity overflow remains the authority that moves
# the oldest resident into fading/release. During provider-idle/instrumental gaps full_text is blank,
# so the original H62 age clock is restored and old rows may still dissolve naturally.
H64_BLUR_FILL_SPEED_MIN = 0.34
H64_BLUR_ACTIVE_PARK_PROGRESS = 0.88

_h64_h62_decay_progress_pre = _h62_decay_progress


def _h64_blur_residency_state(row):
    try:
        ref = getattr(row, '_h62_owner_ref', None)
        window = ref() if callable(ref) else None
        if window is None:
            return None
        capacity = max(1, min(6, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
        history = list(getattr(window, 'history_lines', []) or [])
        current_present = bool(str(getattr(window, 'full_text', '') or '').strip())
        # Fading rows are an exit lane, not live residency. The user slider describes current +
        # resident history; allowing fade overlap keeps mature exit effects intact.
        live_count = (1 if current_present else 0) + len(history)
        return window, capacity, live_count, current_present
    except Exception:
        return None


def _h64_capacity_aware_decay_progress(row, now_mono=None):
    # Release ownership is already correct in H63; never stretch/park a row once capacity or an
    # idle deadline has explicitly moved it to fading.
    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        return _h64_h62_decay_progress_pre(row, now_mono)
    if str(getattr(row, 'exit_effect', '') or '').strip().lower() != H62_EXIT_EFFECT_BLUR_DECAY:
        return _h64_h62_decay_progress_pre(row, now_mono)
    state = _h64_blur_residency_state(row)
    if not state:
        return _h64_h62_decay_progress_pre(row, now_mono)
    window, capacity, live_count, current_present = state
    if capacity <= 1 or not current_present:
        # Empty current text is the important instrumental/provider-idle signal: H62's age-driven
        # natural dissolve is desirable there and must not be held merely to fill the configured cap.
        return _h64_h62_decay_progress_pre(row, now_mono)
    try:
        now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
        hold_ms, _release_ms = _h62_decay_durations(row)
        started = float(getattr(row, '_h62_decay_hold_mono', 0.0) or 0.0)
        if started <= 0.0:
            started = now
            row._h62_decay_hold_mono = now
        fill = max(0.0, min(1.0, float(live_count) / float(max(1, capacity))))
        speed = float(H64_BLUR_FILL_SPEED_MIN) + (1.0 - float(H64_BLUR_FILL_SPEED_MIN)) * fill
        progress = max(0.0, (now - started) / max(1.0, float(hold_ms))) * speed
        # Active lyric flow uses capacity overflow as the retirement authority. The row may become
        # strongly defocused while waiting, but it cannot self-delete one line before the requested
        # stack fills. When the next lyric overflows capacity, begin_fade() snapshots this progress
        # and H62/H63's bounded release clock continues from exactly that optical state.
        progress = min(float(H64_BLUR_ACTIVE_PARK_PROGRESS), progress)
        row._h64_capacity_fill_ratio = fill
        row._h64_capacity_speed = speed
        row._h64_capacity_live = int(live_count)
        row._h64_capacity_target = int(capacity)
        return max(0.0, min(1.0, progress))
    except Exception:
        return _h64_h62_decay_progress_pre(row, now_mono)


def _h64_activate_runtime():
    global _h62_decay_progress
    try:
        if getattr(_h62_decay_progress, '_limbus_layer', '') == 'H64':
            return
        _h62_decay_progress = _h64_capacity_aware_decay_progress
        _h62_decay_progress._limbus_layer = 'H64'
        _h62_decay_progress._limbus_policy = (
            'blur-decay-capacity-soft-target; active-current=fill-speed+no-natural-retire; '
            'idle-current=original-age-retire; release-phase=H63-unchanged')
    except Exception as exc:
        try: write_error_log('H64容量感知渐进失焦安装失败', exc)
        except Exception: pass

# H64 lets the visible subtitle count influence blur-decay residency without changing other exits.
if '_h64_activate_runtime' in globals():
    _h64_activate_runtime()

# H65 continuous blur lifecycle + perceptual exit curve ---------------------------
# H64 solved capacity residency, but field evidence exposed two continuity defects in its
# age*current-speed model. First, changing live fill re-multiplied the row's entire historical
# age by a new speed, so blur progress could jump forward or even move backward. Second, H64
# parked only the returned progress while H62's original hold clock kept aging; the moment
# full_text became blank (provider-idle/instrumental), the raw H62 clock could jump straight to
# 1.0 and retire rows before the user saw the rest of the defocus.
#
# H65 keeps a tiny per-row visual integrator while capacity residency is active. Fill changes
# alter only the *future slope*. Leaving capacity residency rebases H62's hold clock to the exact
# visible progress, so idle/capacity=1 continuation starts from the same frame instead of paying
# back hidden age. Release ownership remains H63/H62.
#
# H65 also separates optical completion from disappearance: the max precomputed H62 blur Atlas
# is reached before opacity decay begins, then held while the row fades. Cross-fade weights get
# a small midpoint compensation to reduce the 75%-alpha dip caused by SourceOver blending two
# partially opaque cached materials. No raster/filter work is added to paintEvent.
H65_BLUR_REACH_MAX_AT = 0.82
H65_BLUR_FADE_START = 0.90
H65_BLUR_CROSSFADE_GAIN = 0.30

_h65_h64_decay_progress_pre = _h62_decay_progress
_h65_raw_h62_decay_progress = globals().get('_h64_h62_decay_progress_pre', _h65_h64_decay_progress_pre)


def _h65_smootherstep(value):
    x = max(0.0, min(1.0, float(value)))
    return x * x * x * (x * (x * 6.0 - 15.0) + 10.0)


def _h65_reset_capacity_integrator(row):
    try:
        row._h65_capacity_active = False
        row._h65_capacity_last_mono = 0.0
    except Exception:
        pass


def _h65_rebase_raw_hold_clock(row, now_mono, progress, reason='idle'):
    """Make raw H62 age continue from the exact visible capacity-managed progress."""
    try:
        now = float(now_mono)
        p = max(0.0, min(1.0, float(progress)))
        hold_ms, _release_ms = _h62_decay_durations(row)
        row._h62_decay_hold_mono = now - p * max(1.0, float(hold_ms))
        row._h65_capacity_active = False
        row._h65_capacity_last_mono = now
        row._h65_capacity_progress = p
        try:
            write_error_log('H65渐进失焦连续退场重基准', detail=(
                f'reason={reason} | progress={p:.3f} | hidden-age-payback=0 | release-authority=unchanged'))
        except Exception:
            pass
        return p
    except Exception:
        _h65_reset_capacity_integrator(row)
        return max(0.0, min(1.0, float(progress or 0.0)))


def _h65_continuous_capacity_decay_progress(row, now_mono=None):
    """Integrate capacity blur speed over time and preserve progress when the policy disengages."""
    now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
    effect = str(getattr(row, 'exit_effect', '') or '').strip().lower()
    if effect != H62_EXIT_EFFECT_BLUR_DECAY:
        _h65_reset_capacity_integrator(row)
        return _h65_h64_decay_progress_pre(row, now)

    # H63/H62 release is authoritative once begin_fade() has captured the optical state.
    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        _h65_reset_capacity_integrator(row)
        return _h65_raw_h62_decay_progress(row, now)

    try:
        state = _h64_blur_residency_state(row)
    except Exception:
        state = None
    if not state:
        _h65_reset_capacity_integrator(row)
        return _h65_h64_decay_progress_pre(row, now)

    _window, capacity, live_count, current_present = state
    managed = bool(int(capacity) > 1 and current_present)
    if not managed:
        if bool(getattr(row, '_h65_capacity_active', False)):
            p = max(0.0, min(float(H64_BLUR_ACTIVE_PARK_PROGRESS),
                             float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
            reason = 'provider-idle' if not current_present else 'capacity-one'
            _h65_rebase_raw_hold_clock(row, now, p, reason=reason)
            return _h65_raw_h62_decay_progress(row, now)
        return _h65_raw_h62_decay_progress(row, now)

    try:
        hold_ms, _release_ms = _h62_decay_durations(row)
        fill = max(0.0, min(1.0, float(live_count) / float(max(1, capacity))))
        speed = float(H64_BLUR_FILL_SPEED_MIN) + (1.0 - float(H64_BLUR_FILL_SPEED_MIN)) * fill
        was_active = bool(getattr(row, '_h65_capacity_active', False))
        if not was_active:
            # Preserve H64's first-frame optical state for compatibility, then integrate from it.
            p = max(0.0, min(float(H64_BLUR_ACTIVE_PARK_PROGRESS),
                             float(_h65_h64_decay_progress_pre(row, now))))
            last = now
        else:
            p = max(0.0, min(float(H64_BLUR_ACTIVE_PARK_PROGRESS),
                             float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
            last = float(getattr(row, '_h65_capacity_last_mono', now) or now)
            elapsed = max(0.0, now - last)
            p += (elapsed / max(1.0, float(hold_ms))) * speed
            p = min(float(H64_BLUR_ACTIVE_PARK_PROGRESS), p)

        row._h65_capacity_active = True
        row._h65_capacity_last_mono = now
        row._h65_capacity_progress = p
        row._h65_capacity_fill_ratio = fill
        row._h65_capacity_speed = speed
        # Keep H64 diagnostics populated so existing field tooling/replays remain useful.
        row._h64_capacity_fill_ratio = fill
        row._h64_capacity_speed = speed
        row._h64_capacity_live = int(live_count)
        row._h64_capacity_target = int(capacity)
        return max(0.0, min(1.0, p))
    except Exception:
        _h65_reset_capacity_integrator(row)
        return _h65_h64_decay_progress_pre(row, now)


def _h65_decay_mix(progress):
    """Complete optical blur before the final opacity tail, with smoother cached-stage blending."""
    p = max(0.0, min(1.0, float(progress)))
    reach = max(0.05, min(0.98, float(H65_BLUR_REACH_MAX_AT)))
    optical = _h65_smootherstep(p / reach)

    if optical <= 0.50:
        t = _h65_smootherstep(optical / 0.50)
        bell = 4.0 * t * (1.0 - t)
        gain = 1.0 + float(H65_BLUR_CROSSFADE_GAIN) * bell
        base_w, mid_w, max_w = min(1.0, (1.0 - t) * gain), min(1.0, t * gain), 0.0
    else:
        t = _h65_smootherstep((optical - 0.50) / 0.50)
        bell = 4.0 * t * (1.0 - t)
        gain = 1.0 + float(H65_BLUR_CROSSFADE_GAIN) * bell
        base_w, mid_w, max_w = 0.0, min(1.0, (1.0 - t) * gain), min(1.0, t * gain)

    fade_start = max(reach, min(0.995, float(H65_BLUR_FADE_START)))
    if p <= fade_start:
        visibility = 1.0
    else:
        visibility = 1.0 - _h65_smootherstep((p - fade_start) / max(0.001, 1.0 - fade_start))
    return (float(base_w), float(mid_w), float(max_w), max(0.0, min(1.0, float(visibility))))


def _h65_activate_runtime():
    global _h62_decay_progress, _h62_decay_mix
    try:
        if getattr(_h62_decay_progress, '_limbus_layer', '') == 'H65':
            return
        _h62_decay_progress = _h65_continuous_capacity_decay_progress
        _h62_decay_progress._limbus_layer = 'H65'
        _h62_decay_progress._limbus_policy = (
            'capacity-speed-integrated; no-progress-reversal; idle-rebase-preserves-visible-progress; '
            'release-phase=H63-H62-unchanged')
        _h62_decay_mix = _h65_decay_mix
        _h62_decay_mix._limbus_layer = 'H65'
        _h62_decay_mix._limbus_policy = (
            'max-defocus-before-opacity-tail; smootherstep-stage-blend; sourceover-midpoint-compensation; '
            'cached-atlas-only-no-paint-raster')
    except Exception as exc:
        try: write_error_log('H65连续渐进失焦生命周期安装失败', exc)
        except Exception: pass


# H65 is a presentation-only closure over H64/H62. It owns neither capacity release nor media time.
if '_h65_activate_runtime' in globals():
    _h65_activate_runtime()


# H66 uninterrupted blur exit ------------------------------------------------------------
# Field evidence from H65 showed two remaining presentation defects:
# 1) capacity-managed history was still capped at H64's 0.88 park point, while H65's optical
#    curve reached its maximum at 0.82. Old rows could therefore sit at one blur level until
#    another lifecycle event released them;
# 2) H62 release always spent a full release_ms on only the *remaining* progress. A row released
#    at p=0.88 could take several seconds to traverse the final 12%, creating a second slow shelf.
# In addition, the mature render-pressure valve may discard blur-decay fading rows outright at
# pressure 1/2, which is visible as an unfinished row disappearing.
#
# H66 makes capacity a maximum residency count rather than a visual progress stop: integrated
# age is allowed to reach 1.0 naturally. Release duration scales with remaining progress so a
# high-progress row does not restart a long tail. Optical blur keeps increasing all the way to
# p=1.0; opacity starts very late and uses a back-loaded cubic tail so the last increase in blur
# remains visible. Under render pressure blur-decay rows are accelerated, never budget-dropped;
# legacy/non-blur exits keep the existing pressure valve semantics.
H66_BLUR_FADE_START = 0.94
H66_BLUR_OPTICAL_POWER = 1.12
H66_BLUR_CROSSFADE_GAIN = 0.24
H66_RELEASE_MIN_TAIL_MS = 520.0
H66_PRESSURE_MIN_TAIL_MS = 360.0
H66_PRESSURE_RELEASE_FACTOR_SOFT = 0.76
H66_PRESSURE_RELEASE_FACTOR_HIGH = 0.56
H66_PRESSURE_RELEASE_FACTOR_SEVERE = 0.40

_h66_h65_progress_pre = _h62_decay_progress
_h66_h65_mix_pre = _h62_decay_mix
_h66_fade_limit_pre = LyricWindow._enforce_fade_exit_limit if 'LyricWindow' in globals() else None


def _h66_is_blur_decay_row(row):
    try:
        return str(getattr(row, 'exit_effect', '') or '').strip().lower() == H62_EXIT_EFFECT_BLUR_DECAY
    except Exception:
        return False


def _h66_release_duration(row, p0, pressure_factor=1.0):
    """Scale release time to remaining optical distance instead of restarting a full tail."""
    try:
        _hold_ms, release_ms = _h62_decay_durations(row)
    except Exception:
        release_ms = 2400.0
    remaining = max(0.0, min(1.0, 1.0 - float(p0)))
    base = max(float(H66_RELEASE_MIN_TAIL_MS), float(release_ms) * remaining)
    factor = max(0.20, min(1.0, float(pressure_factor or 1.0)))
    floor = float(H66_PRESSURE_MIN_TAIL_MS) if factor < 0.999 else float(H66_RELEASE_MIN_TAIL_MS)
    return max(floor, base * factor)


def _h66_release_progress(row, now):
    release_start = float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0)
    p0 = max(0.0, min(1.0, float(getattr(row, '_h62_decay_release_progress', 0.0) or 0.0)))
    if release_start <= 0.0:
        return p0
    elapsed = max(0.0, float(now) - release_start)
    if int(getattr(row, '_h62_decay_release_draw_count', 0) or 0) <= 0:
        catchup = float(globals().get('H59_EXIT_FIRST_FRAME_CATCHUP_MS', 120.0) or 120.0)
        elapsed = min(elapsed, max(16.0, catchup))
    pressure_factor = max(0.20, min(1.0, float(getattr(row, '_h66_pressure_release_factor', 1.0) or 1.0)))
    duration = _h66_release_duration(row, p0, pressure_factor)
    q = max(0.0, min(1.0, elapsed / max(1.0, duration)))
    # Linear remaining-distance travel avoids H62's second ease-in shelf. The optical mix itself
    # remains eased, and the first-visible-frame guard above still prevents unseen completion.
    candidate = max(p0, min(1.0, p0 + (1.0 - p0) * q))
    previous = max(p0, min(1.0, float(getattr(row, '_h66_release_progress_last', p0) or p0)))
    result = max(previous, candidate)
    row._h66_release_progress_last = result
    return result


def _h66_uninterrupted_decay_progress(row, now_mono=None):
    """Continuous capacity age + remaining-distance release; no active 0.88 parking shelf."""
    now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
    if not _h66_is_blur_decay_row(row):
        _h65_reset_capacity_integrator(row)
        return _h66_h65_progress_pre(row, now)

    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        _h65_reset_capacity_integrator(row)
        return _h66_release_progress(row, now)

    try:
        state = _h64_blur_residency_state(row)
    except Exception:
        state = None
    if not state:
        _h65_reset_capacity_integrator(row)
        return _h65_raw_h62_decay_progress(row, now)

    _window, capacity, live_count, current_present = state
    managed = bool(int(capacity) > 1 and current_present)
    if not managed:
        if bool(getattr(row, '_h65_capacity_active', False)):
            p = max(0.0, min(1.0, float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
            reason = 'provider-idle' if not current_present else 'capacity-one'
            _h65_rebase_raw_hold_clock(row, now, p, reason='h66-' + reason)
            return _h65_raw_h62_decay_progress(row, now)
        return _h65_raw_h62_decay_progress(row, now)

    try:
        hold_ms, _release_ms = _h62_decay_durations(row)
        fill = max(0.0, min(1.0, float(live_count) / float(max(1, capacity))))
        speed = float(H64_BLUR_FILL_SPEED_MIN) + (1.0 - float(H64_BLUR_FILL_SPEED_MIN)) * fill
        was_active = bool(getattr(row, '_h65_capacity_active', False))
        if not was_active:
            # Seed from the currently visible H65/H64 state only once; H66 is free to progress
            # beyond the old 0.88 park point on subsequent frames.
            p = max(0.0, min(1.0, float(_h66_h65_progress_pre(row, now))))
            last = now
        else:
            p = max(0.0, min(1.0, float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
            last = float(getattr(row, '_h65_capacity_last_mono', now) or now)
            elapsed = max(0.0, now - last)
            p += (elapsed / max(1.0, float(hold_ms))) * speed
            p = min(1.0, p)
        row._h65_capacity_active = True
        row._h65_capacity_last_mono = now
        row._h65_capacity_progress = p
        row._h65_capacity_fill_ratio = fill
        row._h65_capacity_speed = speed
        row._h64_capacity_fill_ratio = fill
        row._h64_capacity_speed = speed
        row._h64_capacity_live = int(live_count)
        row._h64_capacity_target = int(capacity)
        return p
    except Exception:
        _h65_reset_capacity_integrator(row)
        return _h66_h65_progress_pre(row, now)


def _h66_decay_mix(progress):
    """Keep defocus moving through the last visible frame; fade only in a late back-loaded tail."""
    p = max(0.0, min(1.0, float(progress)))
    optical = max(0.0, min(1.0, p ** float(H66_BLUR_OPTICAL_POWER)))
    if optical <= 0.50:
        t = _h65_smootherstep(optical / 0.50)
        bell = 4.0 * t * (1.0 - t)
        gain = 1.0 + float(H66_BLUR_CROSSFADE_GAIN) * bell
        base_w, mid_w, max_w = min(1.0, (1.0 - t) * gain), min(1.0, t * gain), 0.0
    else:
        t = _h65_smootherstep((optical - 0.50) / 0.50)
        bell = 4.0 * t * (1.0 - t)
        gain = 1.0 + float(H66_BLUR_CROSSFADE_GAIN) * bell
        base_w, mid_w, max_w = 0.0, min(1.0, (1.0 - t) * gain), min(1.0, t * gain)

    start = max(0.80, min(0.985, float(H66_BLUR_FADE_START)))
    if p <= start:
        visibility = 1.0
    else:
        x = max(0.0, min(1.0, (p - start) / max(0.001, 1.0 - start)))
        # Back-loaded fade: at the midpoint of the final tail visibility is still 87.5%, so
        # the user can see the blur continue increasing instead of opacity hiding it early.
        visibility = 1.0 - (x ** 3.0)
    return (float(base_w), float(mid_w), float(max_w), max(0.0, min(1.0, float(visibility))))


def _h66_pressure_factor(level):
    level = int(level or 0)
    if level >= 3:
        return float(H66_PRESSURE_RELEASE_FACTOR_SEVERE)
    if level >= 2:
        return float(H66_PRESSURE_RELEASE_FACTOR_HIGH)
    if level >= 1:
        return float(H66_PRESSURE_RELEASE_FACTOR_SOFT)
    return 1.0


def _h66_enforce_fade_exit_limit(window):
    """Preserve blur-decay exits under pressure; accelerate them instead of deleting mid-effect."""
    try:
        limit = max(1, min(6, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
        pressure = int(window._render_pressure_level())
        soft_budget = int(window._effective_fade_exit_budget())
    except Exception:
        if callable(_h66_fade_limit_pre):
            return _h66_fade_limit_pre(window)
        return 0

    dropped = 0
    rows = list(getattr(window, 'fading_lines', []) or [])
    blur_rows = []
    normal_rows = []
    for item in rows:
        if _h66_is_blur_decay_row(item):
            # H62/H66 visibility is optical, while alpha deliberately stays 255. Never apply
            # the legacy alpha cutoff to this effect.
            blur_rows.append(item)
        elif int(getattr(item, 'alpha', 255) or 0) <= int(FADE_VISUAL_ALPHA_CUTOFF):
            window._discard_fading_item(item); dropped += 1
        else:
            normal_rows.append(item)

    # Keep legacy pressure semantics for non-blur exits only.
    if pressure > 0 and len(normal_rows) > soft_budget:
        drop_n = len(normal_rows) - soft_budget
        for item in normal_rows[:drop_n]:
            window._discard_fading_item(item)
        normal_rows = normal_rows[drop_n:]
        dropped += drop_n
    else:
        overflow = max(0, len(normal_rows) - soft_budget)
        if overflow:
            for item in normal_rows[:overflow]:
                try: item.expedite_fade()
                except Exception: pass

    emergency = max(int(NETEASE_FADE_EXIT_EMERGENCY_MAX), limit + 6)
    if len(normal_rows) > emergency:
        drop_n = len(normal_rows) - emergency
        for item in normal_rows[:drop_n]:
            window._discard_fading_item(item)
        normal_rows = normal_rows[drop_n:]
        dropped += drop_n

    # Blur-decay exits are never popped by the frame-time valve. Pressure shortens their
    # remaining-distance release instead. Older rows get a little more acceleration when several
    # overlap, keeping the lane bounded without a one-frame disappearance.
    factor = _h66_pressure_factor(pressure)
    accelerated = 0
    for idx, item in enumerate(blur_rows):
        item_factor = factor
        if pressure > 0 and len(blur_rows) > 1:
            age_rank = float(len(blur_rows) - idx - 1) / float(max(1, len(blur_rows) - 1))
            item_factor *= (1.0 - 0.22 * age_rank)
        item_factor = max(0.24, min(1.0, item_factor))
        previous = float(getattr(item, '_h66_pressure_release_factor', 1.0) or 1.0)
        item._h66_pressure_release_factor = item_factor
        if item_factor < 0.999 and abs(previous - item_factor) > 0.001:
            accelerated += 1

    # Preserve chronological ordering across the two semantic lanes.
    keep = set(id(x) for x in normal_rows + blur_rows)
    window.fading_lines = [x for x in rows if id(x) in keep]

    now = time.monotonic() * 1000.0
    if dropped:
        if now - float(getattr(window, '_last_fade_budget_log_mono', 0.0) or 0.0) >= 1500.0:
            window._last_fade_budget_log_mono = now
            try:
                write_error_log('渲染压力退场裁剪', detail=(
                    f'pressure={pressure} | dropped={dropped} | fading_left={len(window.fading_lines)} | '
                    f'fade_budget={soft_budget} | blur_protected={len(blur_rows)} | history_preserved={len(window.history_lines)}'))
            except Exception:
                pass
    if accelerated and now - float(getattr(window, '_h66_last_pressure_log_mono', 0.0) or 0.0) >= 1500.0:
        window._h66_last_pressure_log_mono = now
        try:
            write_error_log('H66渲染压力渐进失焦加速', detail=(
                f'pressure={pressure} | blur_rows={len(blur_rows)} | accelerated={accelerated} | '
                f'factor={factor:.2f} | direct_drop=0'))
        except Exception:
            pass
    return dropped


def _h66_activate_runtime():
    global _h62_decay_progress, _h62_decay_mix
    try:
        if getattr(_h62_decay_progress, '_limbus_layer', '') == 'H66':
            return
        _h62_decay_progress = _h66_uninterrupted_decay_progress
        _h62_decay_progress._limbus_layer = 'H66'
        _h62_decay_progress._limbus_policy = (
            'capacity-integrated-to-natural-retirement; no-active-park-shelf; '
            'remaining-distance-release; monotonic-pressure-acceleration')
        _h62_decay_mix = _h66_decay_mix
        _h62_decay_mix._limbus_layer = 'H66'
        _h62_decay_mix._limbus_policy = (
            'defocus-increases-through-last-visible-frame; late-backloaded-opacity-tail; cached-atlas-only')
        if 'LyricWindow' in globals() and callable(_h66_fade_limit_pre):
            LyricWindow._enforce_fade_exit_limit = _h66_enforce_fade_exit_limit
            LyricWindow._enforce_fade_exit_limit._limbus_layer = 'H66'
            LyricWindow._enforce_fade_exit_limit._limbus_policy = (
                'blur-decay-pressure-accelerate-never-budget-drop; legacy-exits-unchanged')
    except Exception as exc:
        try: write_error_log('H66连续渐进失焦退场安装失败', exc)
        except Exception: pass


if '_h66_activate_runtime' in globals():
    _h66_activate_runtime()


# H67 capacity-cadence blur governor ------------------------------------------------------
# H66 made the blur lifecycle continuous, but its capacity speed still used only fill ratio
# (live_count / capacity). That loses the actual user setting at saturation: 3/3 and 6/6 are
# both fill=1.0, so a full three-row stack and a full six-row stack progress at the same speed.
# Field H66 logs also show age retirement while a six-row target is still under-filled, because
# wall-clock hold time can win before capacity overflow on fast lyrics.
#
# H67 predicts *when this specific resident row will be evicted by capacity*. A small robust EMA
# tracks real completed-line cadence. The row's identity position in history tells us how many
# normal line births remain before it becomes the oldest overflow. The controller then adjusts
# only future blur slope so the row approaches a common optical target shortly before that
# predicted eviction. Smaller capacities therefore move faster, larger capacities move slower,
# and fast/slow songs naturally scale without changing media/seek/timeline authority.
#
# Above the eviction target, progress keeps moving asymptotically toward a pre-opacity soft limit
# instead of hard parking or self-deleting. Capacity overflow remains the active-flow retirement
# authority; provider idle rebases to the raw H62 clock exactly as H65/H66 already established.
H67_EVICT_TARGET_PROGRESS = 0.875
H67_ACTIVE_SOFT_LIMIT = 0.938
H67_DEFAULT_CADENCE_MS = 1900.0
H67_CADENCE_MIN_MS = 420.0
H67_CADENCE_MAX_MS = 6200.0
H67_CADENCE_EMA_ALPHA = 0.28
H67_SPEED_RESPONSE_MS = 420.0
H67_SPEED_MIN = 0.10
H67_SPEED_MAX = 3.80
H67_CAPACITY_ONE_TAIL_RATIO = 0.68
H67_CAPACITY_ONE_TAIL_MIN_MS = 520.0
H67_CAPACITY_ONE_TAIL_MAX_MS = 1350.0
H67_EARLY_RELEASE_TAIL_RATIO = 0.78
H67_EARLY_RELEASE_TAIL_MAX_MS = 1650.0

_h67_h66_progress_pre = _h62_decay_progress
_h67_make_history_pre = LyricWindow._make_history_line if 'LyricWindow' in globals() else None


def _h67_reset_capacity_controller(row):
    try:
        _h65_reset_capacity_integrator(row)
    except Exception:
        pass
    try:
        row._h67_capacity_speed_smoothed = 0.0
        row._h67_capacity_speed_desired = 0.0
    except Exception:
        pass


def _h67_local_timeline_cadence(window):
    """Small fallback from nearby source line starts; never changes timeline authority."""
    try:
        timeline = list(getattr(window, 'lyric_timeline', []) or [])
        idx = int(getattr(window, 'displayed_line_index', -1) or -1)
        if idx < 0 or len(timeline) < 2:
            return None
        gaps = []
        lo = max(1, idx - 3)
        hi = min(len(timeline), idx + 3)
        for i in range(lo, hi):
            try:
                gap = float(timeline[i][0]) - float(timeline[i - 1][0])
            except Exception:
                continue
            if float(H67_CADENCE_MIN_MS) <= gap <= float(H67_CADENCE_MAX_MS):
                gaps.append(gap)
        if not gaps:
            return None
        gaps.sort()
        n = len(gaps)
        return float(gaps[n // 2] if n % 2 else (gaps[n // 2 - 1] + gaps[n // 2]) * 0.5)
    except Exception:
        return None


def _h67_window_cadence_ms(window):
    try:
        value = float(getattr(window, '_h67_line_cadence_ema_ms', 0.0) or 0.0)
    except Exception:
        value = 0.0
    if float(H67_CADENCE_MIN_MS) <= value <= float(H67_CADENCE_MAX_MS):
        return value
    fallback = _h67_local_timeline_cadence(window)
    if fallback is not None:
        return float(fallback)
    return float(H67_DEFAULT_CADENCE_MS)


def _h67_note_completed_line(window):
    """Update cadence only for sequential completed rows, excluding seek/provider snapshots."""
    try:
        idx = int(getattr(window, 'displayed_line_index', -1) or -1)
        if idx < 0:
            return
        now = time.monotonic() * 1000.0
        prev_idx = int(getattr(window, '_h67_cadence_line_index', -999999) or -999999)
        prev_mono = float(getattr(window, '_h67_cadence_line_mono', 0.0) or 0.0)
        if prev_idx == idx:
            return
        if prev_mono > 0.0 and idx == prev_idx + 1:
            sample = max(0.0, now - prev_mono)
            if float(H67_CADENCE_MIN_MS) <= sample <= float(H67_CADENCE_MAX_MS):
                old = float(getattr(window, '_h67_line_cadence_ema_ms', 0.0) or 0.0)
                if old > 0.0:
                    # Clip one pathological short/long row before EMA so speed does not jerk.
                    sample = max(old * 0.48, min(old * 2.10, sample))
                    a = max(0.05, min(0.80, float(H67_CADENCE_EMA_ALPHA)))
                    ema = old + (sample - old) * a
                else:
                    ema = sample
                window._h67_line_cadence_ema_ms = max(
                    float(H67_CADENCE_MIN_MS), min(float(H67_CADENCE_MAX_MS), float(ema)))
                window._h67_line_cadence_samples = int(
                    getattr(window, '_h67_line_cadence_samples', 0) or 0) + 1
        window._h67_cadence_line_index = idx
        window._h67_cadence_line_mono = now
    except Exception:
        pass


def _h67_make_history_line(window, text):
    row = _h67_make_history_pre(window, text)
    try:
        # Normal completed-row transition passes the full current text. Visible-prefix seek
        # snapshots do not; duplicate same-index full snapshots are rejected by the index guard.
        if str(text or '') == str(getattr(window, 'full_text', '') or ''):
            _h67_note_completed_line(window)
    except Exception:
        pass
    return row


def _h67_history_slots_to_evict(window, row, capacity):
    """Number of future normal completed-row births before this resident becomes overflow."""
    try:
        history = list(getattr(window, 'history_lines', []) or [])
        keep = max(1, int(capacity) - 1)
        idx = next((i for i, item in enumerate(history) if item is row), -1)
        if idx < 0:
            return 1
        # Oldest-first list. Under-fill contributes the empty slots before overflow begins.
        return max(1, keep - len(history) + idx + 1)
    except Exception:
        return 1


def _h67_desired_capacity_speed(row, progress, hold_ms, cadence_ms, slots_to_evict):
    p = max(0.0, min(1.0, float(progress)))
    hold = max(1.0, float(hold_ms))
    cadence = max(float(H67_CADENCE_MIN_MS), min(float(H67_CADENCE_MAX_MS), float(cadence_ms)))
    slots = max(1, int(slots_to_evict or 1))
    target = max(0.50, min(float(H67_ACTIVE_SOFT_LIMIT) - 0.01, float(H67_EVICT_TARGET_PROGRESS)))
    if p < target:
        remaining_ms = max(float(H67_CADENCE_MIN_MS), cadence * float(slots))
        desired = ((target - p) * hold) / remaining_ms
    else:
        # Never hard-park. Continue toward a pre-opacity limit with an exponential-style slope.
        limit = max(target + 0.01, min(float(H66_BLUR_FADE_START) - 0.001, float(H67_ACTIVE_SOFT_LIMIT)))
        headroom = max(0.0, limit - p)
        tail_tau = max(900.0, cadence * float(slots) * 1.25)
        desired = (headroom * hold) / tail_tau
    return max(float(H67_SPEED_MIN), min(float(H67_SPEED_MAX), float(desired)))


def _h67_capacity_release_duration(row, p0, pressure_factor=1.0):
    """H66 remaining-distance release plus a cadence-aware cap for low-capacity/early eviction."""
    base = float(_h66_release_duration(row, p0, pressure_factor))
    try:
        ref = getattr(row, '_h62_owner_ref', None)
        window = ref() if callable(ref) else None
        if window is None:
            return base
        capacity = max(1, min(6, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
        cadence = _h67_window_cadence_ms(window)
        factor = max(0.20, min(1.0, float(pressure_factor or 1.0)))
        if capacity <= 1:
            cap_tail = max(float(H67_CAPACITY_ONE_TAIL_MIN_MS), min(
                float(H67_CAPACITY_ONE_TAIL_MAX_MS), cadence * float(H67_CAPACITY_ONE_TAIL_RATIO)))
            return max(float(H66_PRESSURE_MIN_TAIL_MS) if factor < 0.999 else float(H66_RELEASE_MIN_TAIL_MS),
                       min(base, cap_tail * factor if factor < 0.999 else cap_tail))
        if float(p0) < float(H67_EVICT_TARGET_PROGRESS) * 0.62:
            # Capacity slider reductions can evict a row before the controller had time to stage it.
            cap_tail = max(float(H66_RELEASE_MIN_TAIL_MS), min(
                float(H67_EARLY_RELEASE_TAIL_MAX_MS), cadence * float(H67_EARLY_RELEASE_TAIL_RATIO)))
            return max(float(H66_PRESSURE_MIN_TAIL_MS) if factor < 0.999 else float(H66_RELEASE_MIN_TAIL_MS),
                       min(base, cap_tail * factor if factor < 0.999 else cap_tail))
    except Exception:
        pass
    return base


def _h67_release_progress(row, now):
    release_start = float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0)
    p0 = max(0.0, min(1.0, float(getattr(row, '_h62_decay_release_progress', 0.0) or 0.0)))
    if release_start <= 0.0:
        return p0
    elapsed = max(0.0, float(now) - release_start)
    if int(getattr(row, '_h62_decay_release_draw_count', 0) or 0) <= 0:
        catchup = float(globals().get('H59_EXIT_FIRST_FRAME_CATCHUP_MS', 120.0) or 120.0)
        elapsed = min(elapsed, max(16.0, catchup))
    pressure_factor = max(0.20, min(1.0, float(getattr(row, '_h66_pressure_release_factor', 1.0) or 1.0)))
    duration = _h67_capacity_release_duration(row, p0, pressure_factor)
    q = max(0.0, min(1.0, elapsed / max(1.0, duration)))
    candidate = max(p0, min(1.0, p0 + (1.0 - p0) * q))
    previous = max(p0, min(1.0, float(getattr(row, '_h67_release_progress_last', p0) or p0)))
    result = max(previous, candidate)
    row._h67_release_progress_last = result
    return result


def _h67_capacity_cadence_decay_progress(row, now_mono=None):
    """Capacity target + real line cadence + resident rank; only future slope is adjusted."""
    now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
    if not _h66_is_blur_decay_row(row):
        _h67_reset_capacity_controller(row)
        return _h67_h66_progress_pre(row, now)

    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        _h65_reset_capacity_integrator(row)
        return _h67_release_progress(row, now)

    try:
        state = _h64_blur_residency_state(row)
    except Exception:
        state = None
    if not state:
        _h67_reset_capacity_controller(row)
        return _h65_raw_h62_decay_progress(row, now)

    window, capacity, _live_count, current_present = state
    managed = bool(int(capacity) > 1 and current_present)
    if not managed:
        if bool(getattr(row, '_h65_capacity_active', False)):
            p = max(0.0, min(1.0, float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
            reason = 'provider-idle' if not current_present else 'capacity-one'
            _h65_rebase_raw_hold_clock(row, now, p, reason='h67-' + reason)
            row._h67_capacity_speed_smoothed = 0.0
            return _h65_raw_h62_decay_progress(row, now)
        return _h65_raw_h62_decay_progress(row, now)

    try:
        hold_ms, _release_ms = _h62_decay_durations(row)
        was_active = bool(getattr(row, '_h65_capacity_active', False))
        if not was_active:
            p = max(0.0, min(1.0, float(_h67_h66_progress_pre(row, now))))
            last = now
            elapsed = 0.0
        else:
            p = max(0.0, min(1.0, float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
            last = float(getattr(row, '_h65_capacity_last_mono', now) or now)
            elapsed = max(0.0, now - last)

        cadence = _h67_window_cadence_ms(window)
        slots = _h67_history_slots_to_evict(window, row, capacity)
        desired = _h67_desired_capacity_speed(row, p, hold_ms, cadence, slots)
        previous_speed = float(getattr(row, '_h67_capacity_speed_smoothed', 0.0) or 0.0)
        if previous_speed <= 0.0 or not was_active:
            speed = desired
        else:
            tau = max(80.0, float(H67_SPEED_RESPONSE_MS))
            alpha = 1.0 - math.exp(-elapsed / tau) if elapsed > 0.0 else 0.0
            speed = previous_speed + (desired - previous_speed) * max(0.0, min(1.0, alpha))
        speed = max(float(H67_SPEED_MIN), min(float(H67_SPEED_MAX), float(speed)))
        if elapsed > 0.0:
            target = max(0.50, min(float(H67_ACTIVE_SOFT_LIMIT) - 0.01, float(H67_EVICT_TARGET_PROGRESS)))
            limit = max(target + 0.01, min(float(H66_BLUR_FADE_START) - 0.001, float(H67_ACTIVE_SOFT_LIMIT)))
            if p < target and speed > 0.0:
                to_target = ((target - p) * max(1.0, float(hold_ms))) / speed
                if elapsed <= to_target:
                    p += (elapsed / max(1.0, float(hold_ms))) * speed
                else:
                    # Split a long/stalled frame at the target, then use an exact exponential
                    # approach. This cannot overshoot into opacity or create a hard clamp shelf.
                    tail_elapsed = max(0.0, elapsed - to_target)
                    p = target
                    tail_tau = max(900.0, cadence * float(max(1, slots)) * 1.25)
                    p = limit - (limit - p) * math.exp(-tail_elapsed / tail_tau)
            else:
                tail_tau = max(900.0, cadence * float(max(1, slots)) * 1.25)
                p = limit - (limit - min(limit, p)) * math.exp(-elapsed / tail_tau)
        # Active flow never self-deletes before capacity overflow. The soft limit is approached
        # asymptotically and therefore remains continuously moving even across long GUI stalls.
        p = max(0.0, min(float(H67_ACTIVE_SOFT_LIMIT) - 1e-7, p))

        row._h65_capacity_active = True
        row._h65_capacity_last_mono = now
        row._h65_capacity_progress = p
        row._h67_capacity_speed_desired = desired
        row._h67_capacity_speed_smoothed = speed
        row._h67_capacity_cadence_ms = cadence
        row._h67_capacity_slots_to_evict = int(slots)
        row._h64_capacity_live = int((1 if current_present else 0) + len(getattr(window, 'history_lines', []) or []))
        row._h64_capacity_target = int(capacity)

        # One oldest-row diagnostic per ~1.6s makes field logs explain *why* speed changed.
        history = list(getattr(window, 'history_lines', []) or [])
        if history and history[0] is row:
            last_log = float(getattr(window, '_h67_last_capacity_blur_log_mono', 0.0) or 0.0)
            if now - last_log >= 1600.0:
                window._h67_last_capacity_blur_log_mono = now
                try:
                    write_error_log('H67容量节奏渐进失焦', detail=(
                        f'capacity={int(capacity)} | history={len(history)} | slots_to_evict={int(slots)} | '
                        f'cadence={cadence:.0f}ms | progress={p:.3f} | target={float(H67_EVICT_TARGET_PROGRESS):.3f} | '
                        f'speed={speed:.2f} | desired={desired:.2f}'))
                except Exception:
                    pass
        return max(0.0, min(1.0, p))
    except Exception:
        _h67_reset_capacity_controller(row)
        return _h67_h66_progress_pre(row, now)


def _h67_activate_runtime():
    global _h62_decay_progress
    try:
        if getattr(_h62_decay_progress, '_limbus_layer', '') == 'H67':
            return
        _h62_decay_progress = _h67_capacity_cadence_decay_progress
        _h62_decay_progress._limbus_layer = 'H67'
        _h62_decay_progress._limbus_policy = (
            'capacity-count+resident-rank+real-line-cadence; future-slope-only; '
            'target-before-overflow; active-soft-limit-before-opacity; capacity-one-tail-scaled')
        if 'LyricWindow' in globals() and callable(_h67_make_history_pre):
            LyricWindow._make_history_line = _h67_make_history_line
            LyricWindow._make_history_line._limbus_layer = 'H67'
            LyricWindow._make_history_line._limbus_policy = (
                'sequential-completed-row-cadence-observer; visual-only; seek-snapshot-neutral')
    except Exception as exc:
        try: write_error_log('H67容量节奏渐进失焦安装失败', exc)
        except Exception: pass


if '_h67_activate_runtime' in globals():
    _h67_activate_runtime()


# H68 deadline blur planner ---------------------------------------------------------------
# H67 learned cadence after completed rows and aimed every resident at one fixed pre-eviction
# progress. Field logs from mixed/ultra-dense songs exposed two consequences: a slow section can
# be followed by a burst before the EMA catches up, producing a late speed jump; and 117-150 ms
# rows cannot physically reach the same 0.875 target before capacity overflow without an extreme
# velocity spike. H68 plans the *whole remaining lifecycle* instead. The known lyric timeline gives
# the exact time until this resident is expected to overflow capacity. A cadence-scaled release tail
# is added to that horizon, and blur progress is paced over horizon+tail. Thus very fast material
# starts moving early but is not required to finish before eviction; the release inherits the same
# velocity and completes the remaining distance. Target/capacity changes only retarget future
# velocity, never progress. Blur exits are also removed from the V28 direct-drop burst clear path;
# their collision weight decays with optical readability instead of deleting the animation.
H68_CADENCE_MIN_MS = 90.0
H68_CADENCE_MAX_MS = 6500.0
H68_TAIL_MIN_MS = 320.0
H68_TAIL_MAX_MS = 1250.0
H68_TAIL_BASE_MS = 220.0
H68_TAIL_CADENCE_RATIO = 0.55
H68_SPEED_RESPONSE_UP_MS = 115.0
H68_SPEED_RESPONSE_DOWN_MS = 280.0
H68_MAX_PROGRESS_PER_MS = 1.0 / 170.0
H68_ACTIVE_LIMIT = 0.939
H68_RELEASE_PRESSURE_FLOOR = 0.78
H68_BLUR_HISTORY_WEIGHT_FLOOR = 0.30
H68_BLUR_EXIT_WEIGHT_FLOOR = 0.08

_h68_h67_progress_pre = _h62_decay_progress
_h68_make_history_pre = LyricWindow._make_history_line if 'LyricWindow' in globals() else None
_h68_obstacles_pre = LyricWindow._placement_obstacles if 'LyricWindow' in globals() else None
_h68_burst_pre = LyricWindow._pre_admit_burst_row if 'LyricWindow' in globals() else None


def _h68_timeline_start(window, index):
    try:
        timeline = list(getattr(window, 'lyric_timeline', []) or [])
        i = int(index)
        if 0 <= i < len(timeline):
            return float(timeline[i][0])
    except Exception:
        pass
    return None


def _h68_future_gap_samples(window, anchor_index, count=4):
    vals = []
    try:
        timeline = list(getattr(window, 'lyric_timeline', []) or [])
        start = max(0, int(anchor_index))
        for i in range(start, min(len(timeline) - 1, start + max(1, int(count)))):
            try:
                gap = float(timeline[i + 1][0]) - float(timeline[i][0])
            except Exception:
                continue
            if float(H68_CADENCE_MIN_MS) <= gap <= float(H68_CADENCE_MAX_MS):
                vals.append(float(gap))
    except Exception:
        pass
    return vals


def _h68_future_cadence_ms(window, anchor_index):
    """Look ahead instead of learning a burst only after it has already happened."""
    vals = _h68_future_gap_samples(window, anchor_index, 4)
    if vals:
        vals.sort()
        # Slightly lower than a median: upcoming dense rows should be budgeted early, while one
        # isolated 100 ms glitch cannot dominate four-row context.
        pos = max(0, min(len(vals) - 1, int(round((len(vals) - 1) * 0.40))))
        return float(vals[pos])
    try:
        fallback = float(_h67_window_cadence_ms(window))
    except Exception:
        fallback = float(H67_DEFAULT_CADENCE_MS)
    return max(float(H68_CADENCE_MIN_MS), min(float(H68_CADENCE_MAX_MS), fallback))


def _h68_tail_budget_ms(window, eviction_index):
    cadence = _h68_future_cadence_ms(window, eviction_index)
    tail = float(H68_TAIL_BASE_MS) + float(H68_TAIL_CADENCE_RATIO) * cadence
    return max(float(H68_TAIL_MIN_MS), min(float(H68_TAIL_MAX_MS), float(tail)))


def _h68_exact_horizon_ms(window, origin_index, capacity):
    """Time from this row entering history (origin+1) to its normal capacity eviction."""
    try:
        origin = int(origin_index)
        cap = max(1, min(6, int(capacity)))
        entry = origin + 1
        evict = origin + cap
        a = _h68_timeline_start(window, entry)
        b = _h68_timeline_start(window, evict)
        if a is not None and b is not None and b >= a:
            return max(0.0, float(b - a)), int(evict)
    except Exception:
        pass
    return None, None


def _h68_plan_for_row(window, row, capacity, now=None):
    now = time.monotonic() * 1000.0 if now is None else float(now)
    origin_raw = getattr(row, '_h68_origin_line_index', -1)
    origin = int(origin_raw if origin_raw is not None else -1)
    horizon, evict = _h68_exact_horizon_ms(window, origin, capacity)
    if horizon is None:
        try:
            slots = max(1, int(_h67_history_slots_to_evict(window, row, capacity)))
            horizon = _h68_future_cadence_ms(window, max(0, int(getattr(window, 'displayed_line_index', 0) or 0))) * slots
            evict = max(0, int(getattr(window, 'displayed_line_index', 0) or 0)) + slots
        except Exception:
            horizon = float(H67_DEFAULT_CADENCE_MS)
            evict = max(0, int(getattr(window, 'displayed_line_index', 0) or 0)) + 1
    tail = _h68_tail_budget_ms(window, int(evict or 0))
    birth = float(getattr(row, '_h68_history_birth_mono', 0.0) or 0.0)
    if birth <= 0.0:
        birth = now
        row._h68_history_birth_mono = now
    age = max(0.0, now - birth)
    remaining_horizon = max(0.0, float(horizon) - age)
    return float(remaining_horizon), float(tail), int(evict or 0), float(horizon)


def _h68_make_history_line(window, text):
    row = _h68_make_history_pre(window, text)
    if row is None:
        return row
    try:
        if str(text or '') == str(getattr(window, 'full_text', '') or ''):
            _origin_raw = getattr(window, 'displayed_line_index', -1)
            row._h68_origin_line_index = int(_origin_raw if _origin_raw is not None else -1)
            row._h68_history_birth_mono = time.monotonic() * 1000.0
            row._h68_progress_velocity = 0.0
            row._h68_release_duration_ms = 0.0
            row._h68_release_initial_velocity = 0.0
    except Exception:
        pass
    return row


def _h68_smooth_velocity(previous, desired, elapsed_ms, urgent=False):
    prev = max(0.0, float(previous or 0.0))
    want = max(0.0, min(float(H68_MAX_PROGRESS_PER_MS), float(desired or 0.0)))
    if prev <= 0.0:
        return want
    tau = float(H68_SPEED_RESPONSE_UP_MS if want > prev else H68_SPEED_RESPONSE_DOWN_MS)
    if urgent and want > prev:
        tau = min(tau, 72.0)
    dt = max(0.0, float(elapsed_ms or 0.0))
    alpha = 1.0 - math.exp(-dt / max(1.0, tau)) if dt > 0.0 else 0.0
    return max(0.0, min(float(H68_MAX_PROGRESS_PER_MS), prev + (want - prev) * alpha))


def _h68_release_duration(row, p0, initial_velocity):
    try:
        ref = getattr(row, '_h62_owner_ref', None)
        window = ref() if callable(ref) else None
    except Exception:
        window = None
    tail = 0.0
    if window is not None:
        try:
            origin_raw = getattr(row, '_h68_origin_line_index', -1)
            origin = int(origin_raw if origin_raw is not None else -1)
            capacity = max(1, min(6, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
            _h, evict = _h68_exact_horizon_ms(window, origin, capacity)
            tail = _h68_tail_budget_ms(window, int(evict if evict is not None else getattr(window, 'displayed_line_index', 0) or 0))
        except Exception:
            tail = 0.0
    if tail <= 0.0:
        try: tail = max(float(H68_TAIL_MIN_MS), min(float(H68_TAIL_MAX_MS), float(_h67_window_cadence_ms(window)) * 0.55 + 220.0))
        except Exception: tail = 720.0
    # Snapshot pressure once. H66's live pressure factor changing halfway through a release was
    # one source of visible late acceleration. Degraded mode may shorten the tail modestly, but
    # never turns it into a completion/drop command.
    try:
        pf = max(0.20, min(1.0, float(getattr(row, '_h66_pressure_release_factor', 1.0) or 1.0)))
    except Exception:
        pf = 1.0
    pressure_scale = max(float(H68_RELEASE_PRESSURE_FLOOR), min(1.0, math.sqrt(pf)))
    tail *= pressure_scale
    # Queue pressure is also continuous. A large burst may shorten newly released rows a little,
    # but keeps a real minimum animation instead of a direct-delete lock.
    if window is not None:
        try:
            blur_count = sum(1 for x in list(getattr(window, 'fading_lines', []) or []) if _h66_is_blur_decay_row(x))
            extra = max(0, blur_count - max(1, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
            tail *= max(0.76, 1.0 / math.sqrt(1.0 + 0.07 * extra))
        except Exception:
            pass
    tail = max(float(H68_TAIL_MIN_MS), min(float(H68_TAIL_MAX_MS), float(tail)))
    remaining = max(1e-6, 1.0 - max(0.0, min(1.0, float(p0))))
    v0 = max(0.0, float(initial_velocity or 0.0))
    if v0 > 1e-9:
        natural = remaining / v0
        # On-plan handoff should already be close. Blend rather than restart a fresh duration.
        tail = 0.72 * tail + 0.28 * max(float(H68_TAIL_MIN_MS), min(float(H68_TAIL_MAX_MS), natural))
    return max(float(H68_TAIL_MIN_MS), min(float(H68_TAIL_MAX_MS), float(tail)))


def _h68_release_progress(row, now):
    release_start = float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0)
    p0 = max(0.0, min(1.0, float(getattr(row, '_h62_decay_release_progress', 0.0) or 0.0)))
    if release_start <= 0.0:
        return p0
    if float(getattr(row, '_h68_release_duration_ms', 0.0) or 0.0) <= 0.0:
        v0 = max(0.0, float(getattr(row, '_h68_progress_velocity', 0.0) or 0.0))
        row._h68_release_initial_velocity = v0
        row._h68_release_duration_ms = _h68_release_duration(row, p0, v0)
        row._h68_release_progress_last = p0
    duration = max(1.0, float(getattr(row, '_h68_release_duration_ms', H68_TAIL_MIN_MS) or H68_TAIL_MIN_MS))
    elapsed = max(0.0, float(now) - release_start)
    if int(getattr(row, '_h62_decay_release_draw_count', 0) or 0) <= 0:
        catchup = float(globals().get('H59_EXIT_FIRST_FRAME_CATCHUP_MS', 120.0) or 120.0)
        elapsed = min(elapsed, max(16.0, catchup))
    s = max(0.0, min(1.0, elapsed / duration))
    delta = max(0.0, 1.0 - p0)
    v0 = max(0.0, float(getattr(row, '_h68_release_initial_velocity', 0.0) or 0.0))
    # Cubic Hermite: same progress and (bounded) velocity at handoff, zero terminal velocity.
    # m0<=3*delta guarantees the monotone segment does not overshoot the endpoint.
    m0 = max(0.0, min(2.70 * delta, v0 * duration))
    h00 = 2.0*s*s*s - 3.0*s*s + 1.0
    h10 = s*s*s - 2.0*s*s + s
    h01 = -2.0*s*s*s + 3.0*s*s
    candidate = h00*p0 + h10*m0 + h01
    previous = max(p0, min(1.0, float(getattr(row, '_h68_release_progress_last', p0) or p0)))
    result = max(previous, min(1.0, candidate))
    row._h68_release_progress_last = result
    # Publish approximate instantaneous velocity for diagnostics/retarget continuity.
    if 0.0 < s < 1.0:
        dh00 = 6.0*s*s - 6.0*s
        dh10 = 3.0*s*s - 4.0*s + 1.0
        dh01 = -6.0*s*s + 6.0*s
        row._h68_progress_velocity = max(0.0, (dh00*p0 + dh10*m0 + dh01) / duration)
    else:
        row._h68_progress_velocity = 0.0 if s >= 1.0 else v0
    return result


def _h68_deadline_decay_progress(row, now_mono=None):
    now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
    if not _h66_is_blur_decay_row(row):
        return _h68_h67_progress_pre(row, now)
    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        return _h68_release_progress(row, now)
    try:
        state = _h64_blur_residency_state(row)
    except Exception:
        state = None
    if not state:
        return _h68_h67_progress_pre(row, now)
    window, capacity, _live_count, current_present = state
    if not (int(capacity) > 1 and current_present):
        return _h68_h67_progress_pre(row, now)
    try:
        p = max(0.0, min(float(H68_ACTIVE_LIMIT), float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
        was_active = bool(getattr(row, '_h68_deadline_active', False))
        last = float(getattr(row, '_h68_last_mono', now) or now)
        elapsed = max(0.0, now - last) if was_active else 0.0
        if not was_active:
            # Seed from the currently visible H67/H66 state, but never inherit its fixed-target speed.
            p = max(p, max(0.0, min(float(H68_ACTIVE_LIMIT), float(_h68_h67_progress_pre(row, now)))))
            if float(getattr(row, '_h68_history_birth_mono', 0.0) or 0.0) <= 0.0:
                row._h68_history_birth_mono = now
        remaining_horizon, tail, evict_idx, full_horizon = _h68_plan_for_row(window, row, capacity, now)
        remaining_total = max(float(H68_TAIL_MIN_MS), remaining_horizon + tail)
        desired_v = max(0.0, min(float(H68_MAX_PROGRESS_PER_MS), (1.0 - p) / remaining_total))
        previous_v = max(0.0, float(getattr(row, '_h68_progress_velocity', 0.0) or 0.0))
        urgent = remaining_horizon < 700.0
        velocity = desired_v if not was_active or previous_v <= 0.0 else _h68_smooth_velocity(previous_v, desired_v, elapsed, urgent)
        if elapsed > 0.0:
            p = min(float(H68_ACTIVE_LIMIT), p + velocity * elapsed)
        row._h68_deadline_active = True
        row._h68_last_mono = now
        row._h68_progress_velocity = velocity
        row._h65_capacity_active = True
        row._h65_capacity_last_mono = now
        row._h65_capacity_progress = p
        row._h67_capacity_speed_smoothed = velocity * max(1.0, float(_h62_decay_durations(row)[0]))
        row._h68_plan_remaining_horizon_ms = remaining_horizon
        row._h68_plan_tail_ms = tail
        row._h68_plan_evict_index = evict_idx
        row._h68_plan_full_horizon_ms = full_horizon
        history = list(getattr(window, 'history_lines', []) or [])
        if history and history[0] is row:
            last_log = float(getattr(window, '_h68_last_plan_log_mono', 0.0) or 0.0)
            if now - last_log >= 1500.0:
                window._h68_last_plan_log_mono = now
                try:
                    write_error_log('H68时间预算渐进失焦', detail=(
                        f'capacity={int(capacity)} | history={len(history)} | evict_line={int(evict_idx)} | '
                        f'horizon={remaining_horizon:.0f}/{full_horizon:.0f}ms | tail={tail:.0f}ms | '
                        f'progress={p:.3f} | velocity={velocity*1000.0:.3f}/s | direct_drop=0'))
                except Exception:
                    pass
        return max(0.0, min(1.0, p))
    except Exception:
        return _h68_h67_progress_pre(row, now)


def _h68_blur_readability(row, fading=False):
    try:
        p = max(0.0, min(1.0, float(_h62_decay_progress(row))))
        visibility = float(_h62_decay_mix(p)[3])
        if fading:
            return max(float(H68_BLUR_EXIT_WEIGHT_FLOOR), min(1.0, visibility * (1.0 - 0.76*p)))
        return max(float(H68_BLUR_HISTORY_WEIGHT_FLOOR), min(1.0, 1.0 - 0.62*p))
    except Exception:
        return 1.0


def _h68_placement_obstacles(window):
    """Same geometry as the mature placer, but blur-decay rows reserve space by readability."""
    obstacles = []
    for f in list(getattr(window, 'history_lines', []) or []):
        try:
            box = window._placement_box(f.text, f.x, f.y, f.angle, f.font, f.spacing)
            scales = list(getattr(f, 'glyph_scales', []) or [])
            max_scale = max([1.0] + [float(x or 1.0) for x in scales])
            fm = QFontMetrics(QFont(f.font))
            growth = min(110.0, max(0.0, float(fm.height()) * (max_scale - 1.0) * 0.62))
            shake = min(24.0, max(0.0, float(getattr(f, 'shake_intensity', 0) or 0) * 2.0))
            box = window._placement_expand_box(box, growth + shake)
            weight = _h68_blur_readability(f, False) if _h66_is_blur_decay_row(f) else 1.0
            obstacles.append((box, float(f.angle), weight, 'history'))
        except Exception:
            pass
    for f in list(getattr(window, 'fading_lines', []) or []):
        try:
            is_blur = _h66_is_blur_decay_row(f)
            if is_blur:
                readability = _h68_blur_readability(f, True)
                if readability <= float(H68_BLUR_EXIT_WEIGHT_FLOOR) + 0.005:
                    continue
                alpha = 255.0 * readability
            else:
                alpha = float(getattr(f, 'alpha', 255) or 0)
                readability = max(0.25, min(1.0, alpha / 255.0))
                if alpha < 55:
                    continue
            box = window._placement_box(f.text, f.x, f.y, f.angle, f.font, f.spacing)
            scales = list(getattr(f, 'glyph_scales', []) or [])
            max_scale = max([1.0] + [float(x or 1.0) for x in scales])
            fm = QFontMetrics(QFont(f.font))
            growth = min(110.0, max(0.0, float(fm.height()) * (max_scale - 1.0) * 0.62))
            shake = min(24.0, max(0.0, float(getattr(f, 'shake_intensity', 0) or 0) * 2.0))
            box = window._placement_expand_box(box, growth + shake)
            box = window._placement_swept_fade_box(box, alpha, getattr(f, 'fade_speed', 0), getattr(f, 'rise_speed', 0))
            obstacles.append((box, float(f.angle), readability, 'fading-sweep'))
        except Exception:
            pass
    return obstacles


def _h68_pre_admit_burst_row(window, target):
    """Never direct-drop blur-decay rows to make admission room; only legacy exits may clear."""
    try:
        rows = list(getattr(window, 'fading_lines', []) or [])
        # Protect rows by their own semantic effect, not by the *current* selector. This also
        # covers a user changing exit presets while older blur rows are still finishing.
        if not any(_h66_is_blur_decay_row(r) for r in rows):
            return _h68_burst_pre(window, target)
        idx = int(target)
        timeline = list(getattr(window, 'lyric_timeline', []) or [])
        if idx < 0 or idx + 1 >= len(timeline):
            return 0
        gap_ms = max(0, int(timeline[idx + 1][0] - timeline[idx][0]))
        chars = len(str(getattr(window, 'full_text', '') or ''))
        burst = bool((gap_ms <= 760 and chars >= 20) or (gap_ms <= 1100 and chars >= 48) or (gap_ms <= 1500 and chars >= 90))
        if not burst:
            return 0
        normal = [r for r in rows if not _h66_is_blur_decay_row(r)]
        if not normal:
            return 0
        # Only pre-existing legacy exits are eligible for V28's old direct clear. Blur rows keep
        # their lifecycle and rely on readability-weighted collision scoring above.
        drop_n = min(len(normal), max(0, len(window._placement_obstacles()) - 2))
        if drop_n <= 0:
            return 0
        doomed_ids = set(id(x) for x in normal[:drop_n])
        survivors = []
        dropped = 0
        for item in rows:
            if id(item) in doomed_ids:
                window._discard_fading_item(item); dropped += 1
            else:
                survivors.append(item)
        window.fading_lines = survivors
        return dropped
    except Exception:
        return 0


def _h68_activate_runtime():
    global _h62_decay_progress
    try:
        if getattr(_h62_decay_progress, '_limbus_layer', '') == 'H68':
            return
        _h62_decay_progress = _h68_deadline_decay_progress
        _h62_decay_progress._limbus_layer = 'H68'
        _h62_decay_progress._limbus_policy = (
            'known-timeline eviction horizon + cadence-scaled tail; velocity-continuous release; '
            'no fixed pre-eviction target; blur exits protected from direct burst drop')
        if 'LyricWindow' in globals():
            if callable(_h68_make_history_pre):
                LyricWindow._make_history_line = _h68_make_history_line
                LyricWindow._make_history_line._limbus_layer = 'H68'
            if callable(_h68_obstacles_pre):
                LyricWindow._placement_obstacles = _h68_placement_obstacles
                LyricWindow._placement_obstacles._limbus_layer = 'H68'
            if callable(_h68_burst_pre):
                LyricWindow._pre_admit_burst_row = _h68_pre_admit_burst_row
                LyricWindow._pre_admit_burst_row._limbus_layer = 'H68'
    except Exception as exc:
        try: write_error_log('H68时间预算渐进失焦安装失败', exc)
        except Exception: pass


if '_h68_activate_runtime' in globals():
    _h68_activate_runtime()


# H69 optical continuity + edge-wrap stability ----------------------------------
# H68 fixed deadline planning, but field testing exposed two lower-level discontinuities:
# (1) logical blur progress could advance before the cached blur material existed.  H62 waited
#     for *both* mid/max stages before emitting either one, and a late H61 row-atlas was only
#     cached for the active row.  Ultra-short lyrics could therefore spend most of their lifetime
#     drawing the clear base, then suddenly acquire blur material (or leave before it arrived).
# (2) horizontal wrap topology used per-frame shake offsets.  Near an edge, a few pixels of shake
#     could flip the wrap cycle between adjacent frames and teleport a glyph by one screen width.
# H69 makes visible defocus monotonic, publishes the cheap mid blur stage immediately, adopts late
# row material into resident rows, prewarms a short future timeline window after the song-atlas
# fuse, and keeps shake out of wrap *decisions* while preserving shake in the final draw position.
H69_FUTURE_ROW_PREWARM = 12
H69_PROGRESS_REGRESSION_EPS = 0.002
H69_REGRESSION_LOG_MS = 1600.0
H69_BLUR_MAX_TOTAL_BUDGET_MS = 620.0

_h69_h68_progress_pre = _h62_decay_progress
_h69_h62_schedule_pre = _h62_schedule_decay_atlases
_h69_install_pre = getattr(LyricWindow, '_install_song_fragment_atlas', None) if 'LyricWindow' in globals() else None
_h69_make_history_pre = getattr(LyricWindow, '_make_history_line', None) if 'LyricWindow' in globals() else None


def _h69_monotonic_decay_progress(row, now_mono=None):
    """Visible blur on one row may advance or hold, never become optically sharper."""
    candidate = max(0.0, min(1.0, float(_h69_h68_progress_pre(row, now_mono))))
    try:
        if not _h66_is_blur_decay_row(row):
            return candidate
        floor = max(0.0, min(1.0, float(getattr(row, '_h69_optical_progress_floor', 0.0) or 0.0)))
        result = max(floor, candidate)
        if candidate + float(H69_PROGRESS_REGRESSION_EPS) < floor:
            owner_ref = getattr(row, '_h62_owner_ref', None)
            window = owner_ref() if callable(owner_ref) else None
            now = time.monotonic() * 1000.0
            if window is not None and now - float(getattr(window, '_h69_last_regression_log_mono', 0.0) or 0.0) >= float(H69_REGRESSION_LOG_MS):
                window._h69_last_regression_log_mono = now
                try:
                    write_error_log('H69可见失焦回退阻断', detail=(
                        f'token={getattr(row,"_h62_decay_token",None)} | candidate={candidate:.3f} | '
                        f'floor={floor:.3f} | release={int(float(getattr(row,"_h62_decay_release_mono",0.0) or 0.0)>0.0)}'))
                except Exception:
                    pass
        row._h69_optical_progress_floor = result
        # Keep upstream capacity state coherent with the visible floor so a later fallback cannot
        # repeatedly request a sharper state.
        try:
            row._h65_capacity_progress = max(
                float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0), result)
        except Exception:
            pass
        return result
    except Exception:
        return candidate


def _h69_schedule_decay_atlases(row):
    """Emit mid blur as soon as it is ready; max blur follows on the same worker."""
    if row is None or not _h66_is_blur_decay_row(row):
        return
    if bool(getattr(row, '_h62_decay_worker_started', False)):
        return
    owner_ref = getattr(row, '_h62_owner_ref', None)
    window = owner_ref() if callable(owner_ref) else None
    if window is None:
        return
    shared = _h62_final_source_shared(row)
    if shared is None:
        return
    try:
        sheet, cmap, style_sig, _pixels = shared
        if sheet is None or sheet.isNull() or not cmap:
            return
        source_image = sheet.toImage()
        if source_image is None or source_image.isNull():
            return
        try: source_image.setDevicePixelRatio(1.0)
        except Exception: pass
        cmap_copy = dict(cmap)
        text = str(getattr(row, 'text', '') or '')
        window._h62_decay_serial = int(getattr(window, '_h62_decay_serial', 0) or 0) + 1
        token = int(window._h62_decay_serial)
        row._h62_decay_token = token
        row._h62_decay_worker_started = True
    except Exception:
        return

    def _emit(stage_name, stage, elapsed, failed=False):
        payload = {
            'h62_blur_decay': True, 'h69_progressive_stage': stage_name,
            'token': token, 'build_ms': float(elapsed),
            'mid': stage if stage_name == 'mid' else None,
            'max': stage if stage_name == 'max' else None,
            'failed': bool(failed),
        }
        try:
            window.song_fragment_atlas_ready.emit(payload)
        except Exception:
            pass

    def worker():
        started = time.perf_counter()
        mid_deadline = started + float(H62_BLUR_WORKER_BUDGET_MS) / 1000.0
        mid = None
        try:
            mid = _h62_filter_shared_image(
                source_image, cmap_copy, style_sig, text, int(H62_BLUR_MID_LEVELS), mid_deadline)
        except Exception:
            mid = None
        elapsed_mid = (time.perf_counter() - started) * 1000.0
        if mid is None:
            _emit('mid', None, elapsed_mid, True)
            return
        # Publish usable blur immediately instead of holding it hostage to the expensive max pass.
        _emit('mid', mid, elapsed_mid, False)

        max_stage = None
        max_deadline = started + float(H69_BLUR_MAX_TOTAL_BUDGET_MS) / 1000.0
        try:
            if time.perf_counter() <= max_deadline:
                max_stage = _h62_filter_shared_image(
                    source_image, cmap_copy, style_sig, text, int(H62_BLUR_MAX_LEVELS), max_deadline)
        except Exception:
            max_stage = None
        elapsed_total = (time.perf_counter() - started) * 1000.0
        _emit('max', max_stage, elapsed_total, max_stage is None)

    threading.Thread(target=worker, name='LimbusLyric-H69BlurStages', daemon=True).start()


def _h69_prewarm_future_rows(window, anchor_index=None):
    """When full-song rasterization fused, stay several lyric births ahead using H61 workers."""
    try:
        if not bool(getattr(window, '_song_fragment_atlas_performance_fused', False)):
            return 0
        timeline = list(getattr(window, 'lyric_timeline', []) or [])
        if not timeline:
            return 0
        if anchor_index is None:
            raw = getattr(window, 'displayed_line_index', -1)
            anchor = int(raw if raw is not None else -1)
        else:
            anchor = int(anchor_index)
        anchor = max(-1, min(len(timeline) - 1, anchor))
        scheduled = 0
        seen = set()
        for idx in range(anchor + 1, min(len(timeline), anchor + 1 + int(H69_FUTURE_ROW_PREWARM))):
            try:
                text = str(timeline[idx][1] or '')
            except Exception:
                text = ''
            if not text or text in seen:
                continue
            seen.add(text)
            state = _h61_schedule_row_atlas(window, text)
            if state == 'scheduled':
                scheduled += 1
        return scheduled
    except Exception:
        return 0


def _h69_install_song_fragment_atlas(window, payload):
    out = _h69_install_pre(window, payload) if callable(_h69_install_pre) else None
    try:
        adopted = 0
        if isinstance(payload, dict) and payload.get('h61_row_fallback') and not payload.get('failed') and not payload.get('cancelled'):
            key = payload.get('row_key')
            entry = getattr(window, '_h61_row_atlas_cache', {}).get(key)
            shared = entry[0] if isinstance(entry, tuple) and len(entry) >= 1 else None
            text = str(payload.get('text') or '')
            if shared is not None and text:
                for row in list(getattr(window, 'history_lines', []) or []) + list(getattr(window, 'fading_lines', []) or []):
                    if str(getattr(row, 'text', '') or '') != text:
                        continue
                    expected_key = _h61_held_row_key(row)
                    if expected_key[0] is None or key != expected_key or shared[2] != expected_key[0]:
                        continue
                    existing = getattr(row, '_shared_fragment_atlas', None)
                    if existing is None or existing[2] != expected_key[0]:
                        row._shared_fragment_atlas = shared
                        if existing is not None:
                            row._h57_depth_composite_cache = None
                            row._h62_decay_token = None
                            row._h62_decay_worker_started = False
                            row._h62_decay_mid_shared = row._h62_decay_max_shared = None
                        adopted += 1
                        try: _h62_queue_decay_build(row)
                        except Exception: pass
                if adopted:
                    try:
                        write_error_log('H69迟到行材质接管', detail=(
                            f'rows={adopted} | text_len={len(text)} | blur_requeue=1 | gui_filter=0'))
                    except Exception:
                        pass
                    try: window.update()
                    except Exception: pass
        # Keep the row-worker queue ahead after either a song-atlas fuse or a row completion.
        _h69_prewarm_future_rows(window)
    except Exception:
        pass
    return out


def _h69_make_history_line(window, text):
    row = _h69_make_history_pre(window, text) if callable(_h69_make_history_pre) else None
    if row is not None:
        try:
            row._h69_optical_progress_floor = max(
                0.0, min(1.0, float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0)))
        except Exception:
            row._h69_optical_progress_floor = 0.0
        try:
            _h69_prewarm_future_rows(window, getattr(row, '_h68_origin_line_index', None))
        except Exception:
            pass
    return row


def _h69_activate_runtime():
    global _h62_decay_progress, _h62_schedule_decay_atlases
    try:
        if getattr(_h62_decay_progress, '_limbus_layer', '') == 'H69':
            return
        _h62_decay_progress = _h69_monotonic_decay_progress
        _h62_decay_progress._limbus_layer = 'H69'
        _h62_decay_progress._limbus_policy = (
            'per-row optical monotonic floor over H68 deadline planner; never sharpen during one lifecycle')
        _h62_schedule_decay_atlases = _h69_schedule_decay_atlases
        _h62_schedule_decay_atlases._limbus_layer = 'H69'
        _h62_schedule_decay_atlases._limbus_policy = 'mid-stage-first progressive worker; max-stage follows off-GUI'
        if 'LyricWindow' in globals():
            if callable(_h69_install_pre):
                LyricWindow._install_song_fragment_atlas = _h69_install_song_fragment_atlas
                LyricWindow._install_song_fragment_atlas._limbus_layer = 'H69'
            if callable(_h69_make_history_pre):
                LyricWindow._make_history_line = _h69_make_history_line
                LyricWindow._make_history_line._limbus_layer = 'H69'
        globals()['H69_EDGE_WRAP_SHAKE_IN_TOPOLOGY'] = False
    except Exception as exc:
        try: write_error_log('H69光学连续与边缘稳定安装失败', exc)
        except Exception: pass


if '_h69_activate_runtime' in globals():
    _h69_activate_runtime()


# H70 per-effect exit profiles + optional flavor layer ------------------------------------------
# User-facing contract:
#   * "退场速度" is one consistent intent control, but each effect keeps its own remembered value.
#   * Every non-instant effect owns one optional flavor dimension. flavor=0 delegates to the exact
#     mature H69/H59/H51 path; flavor never changes timing and the adaptive deadline never changes flavor.
#   * Dense lyrics may softly compress the requested duration at release, but the user's relative
#     speed preference remains visible and no effect is converted into an instant drop.
H70_EXIT_EFFECTS = ('fade', 'per_char', 'wipe_ltr', 'wipe_rtl', 'shrink', 'soft_drift', 'hop_drop', 'blur_decay', 'instant')
H70_SPEED_DEFAULT = 12
H70_SPEED_MIN = 1
H70_SPEED_MAX = 15
H70_FLAVOR_MIN = 0
H70_FLAVOR_MAX = 100
H70_FADE_RISE_MAX_PX = 120.0
H70_SOFT_GRAVITY_EXTRA_PX = 42.0
H70_SHRINK_PRETENSION_MAX = 0.055
H70_HOP_EXTRA_UP_PX = 20.0
H70_HOP_EXTRA_DROP_PX = 34.0
H70_BLUR_DEPTH_EXPAND_MAX = 0.035
H70_ADAPT_BUDGET_MIN_MS = 360.0
H70_ADAPT_BUDGET_MAX_MS = 3600.0
H70_ADAPT_EXCESS_KEEP = 0.24
H70_ADAPT_HARD_MULT = 1.45
H70_ADAPT_HARD_PAD_MS = 180.0
H70_BLUR_TAIL_MIN_MS = 220.0
H70_BLUR_TAIL_MAX_MS = 1800.0
H70_PROFILE_SCHEMA = 1
H70_FLAVOR_LABELS = {
    'fade': '上升距离',
    'per_char': '离散度',
    'wipe_ltr': '拖尾',
    'wipe_rtl': '拖尾',
    'shrink': '蓄力',
    'soft_drift': '重力感',
    'hop_drop': '弹性',
    'blur_decay': '景深扩散',
    'instant': '无',
}

_h70_make_history_pre = getattr(LyricWindow, '_make_history_line', None) if 'LyricWindow' in globals() else None
_h70_fading_begin_pre = getattr(FadingLine, 'begin_fade', None) if 'FadingLine' in globals() else None
_h70_fading_update_pre = getattr(FadingLine, 'update', None) if 'FadingLine' in globals() else None
_h70_fading_draw_pre = getattr(FadingLine, 'draw', None) if 'FadingLine' in globals() else None
_h70_control_init_pre = getattr(ControlPanel, '__init__', None) if 'ControlPanel' in globals() else None
_h70_capture_preset_pre = getattr(ControlPanel, '_capture_style_preset', None) if 'ControlPanel' in globals() else None
_h70_load_preset_pre = getattr(ControlPanel, 'load_preset', None) if 'ControlPanel' in globals() else None
_h70_save_pre = globals().get('save_all_config')
_h70_h16_duration_pre = globals().get('_h16_exit_duration_ms')
_h70_h51_duration_pre = globals().get('_h51_exit_duration_ms')
_h70_fragment_draw_pre = globals().get('_h51_fragment_exit_draw')
_h70_h68_plan_pre = globals().get('_h68_plan_for_row')
_h70_h68_release_duration_pre = globals().get('_h68_release_duration')


def _h70_clamp(value, lo, hi, default=None):
    try:
        value = float(value)
    except Exception:
        value = float(default if default is not None else lo)
    return max(float(lo), min(float(hi), value))


def _h70_normalize_profiles(settings=None):
    settings = dict(settings or {})
    legacy_speed = int(round(_h70_clamp(settings.get('fade_speed', H70_SPEED_DEFAULT), H70_SPEED_MIN, H70_SPEED_MAX, H70_SPEED_DEFAULT)))
    legacy_rise = _h70_clamp(settings.get('rise_speed', 1), 0.0, 5.0, 1.0)
    # Old rise_speed was px per ~30 ms. Around the historical default lifetime, 1 ~= 20 px.
    # Bound the migration: the new control expresses an intentional total distance, not an
    # unbounded frame-rate-dependent velocity.
    migrated_fade_flavor = int(round(_h70_clamp((legacy_rise * 20.0 / H70_FADE_RISE_MAX_PX) * 100.0, 0.0, 100.0, 0.0)))
    raw = settings.get('h70_exit_profiles')
    raw = raw if isinstance(raw, dict) else {}
    out = {}
    for effect in H70_EXIT_EFFECTS:
        item = raw.get(effect)
        item = item if isinstance(item, dict) else {}
        default_flavor = migrated_fade_flavor if effect == 'fade' else 0
        speed = int(round(_h70_clamp(item.get('speed', legacy_speed), H70_SPEED_MIN, H70_SPEED_MAX, legacy_speed)))
        flavor = int(round(_h70_clamp(item.get('flavor', default_flavor), H70_FLAVOR_MIN, H70_FLAVOR_MAX, default_flavor)))
        if effect == 'instant':
            flavor = 0
        out[effect] = {'speed': speed, 'flavor': flavor}
    return out


def _h70_effect_key(value):
    effect = str(value or 'fade').strip().lower()
    return effect if effect in H70_EXIT_EFFECTS else 'fade'


def _h70_profile(window, effect):
    effect = _h70_effect_key(effect)
    profiles = getattr(window, '_h70_exit_profiles', None)
    if isinstance(profiles, dict):
        item = profiles.get(effect)
        if isinstance(item, dict):
            return {
                'speed': int(round(_h70_clamp(item.get('speed', H70_SPEED_DEFAULT), H70_SPEED_MIN, H70_SPEED_MAX, H70_SPEED_DEFAULT))),
                'flavor': int(round(_h70_clamp(item.get('flavor', 0), H70_FLAVOR_MIN, H70_FLAVOR_MAX, 0))),
            }
    return {'speed': H70_SPEED_DEFAULT, 'flavor': 0}


def _h70_row_speed(row):
    return int(round(_h70_clamp(getattr(row, '_h70_exit_speed', getattr(row, 'fade_speed', H70_SPEED_DEFAULT)), H70_SPEED_MIN, H70_SPEED_MAX, H70_SPEED_DEFAULT)))


def _h70_row_flavor(row):
    return _h70_clamp(getattr(row, '_h70_exit_flavor', 0), H70_FLAVOR_MIN, H70_FLAVOR_MAX, 0) / 100.0


def _h70_time_scale_from_speed(speed):
    speed = _h70_clamp(speed, H70_SPEED_MIN, H70_SPEED_MAX, H70_SPEED_DEFAULT)
    # Nonlinear but bounded. Classic fade retains its historical fade_speed formula; this helper
    # is only for effects whose mature implementation had a fixed timer (hop) or its own planner (blur).
    scale = (float(H70_SPEED_DEFAULT) / max(1.0, speed)) ** 0.72
    return max(0.72, min(2.35, float(scale)))


def _h70_apply_profile_to_row(window, row):
    if row is None:
        return row
    effect = _h70_effect_key(getattr(row, 'exit_effect', getattr(window, 'exit_effect', 'fade')))
    profile = _h70_profile(window, effect)
    row._h70_exit_speed = int(profile['speed'])
    row._h70_exit_flavor = int(profile['flavor'])
    row._h70_profile_effect = effect
    row._h70_profile_schema = H70_PROFILE_SCHEMA
    row._h70_deadline_budget_ms = 0.0
    row._h70_adapt_log_key = None
    # Snapshot semantics: changing UI later affects new rows only, so a running exit never retargets.
    row.fade_speed = int(profile['speed'])
    row._h70_legacy_rise_speed = float(getattr(row, 'rise_speed', 0.0) or 0.0)
    # H70 owns all optional secondary motion as a total-distance/progress layer. The old global
    # per-frame rise velocity would otherwise leak into unrelated effects and make flavor=0 false.
    row.rise_speed = 0.0
    return row


def _h70_make_history_line(window, text):
    row = _h70_make_history_pre(window, text) if callable(_h70_make_history_pre) else None
    return _h70_apply_profile_to_row(window, row)


def _h70_release_budget_ms(row):
    try:
        ref = getattr(row, '_h62_owner_ref', None)
        window = ref() if callable(ref) else None
        if window is None:
            return 0.0
        idx = int(getattr(window, 'displayed_line_index', 0) or 0)
        if '_h68_future_cadence_ms' in globals():
            cadence = float(_h68_future_cadence_ms(window, max(0, idx)))
        elif '_h67_window_cadence_ms' in globals():
            cadence = float(_h67_window_cadence_ms(window))
        else:
            cadence = 900.0
        cadence = max(90.0, min(6500.0, cadence))
        capacity = max(1, min(6, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
        # About capacity+0.8 release slots may overlap without making the exit lane dominate.
        # This is deliberately a soft budget; effect-specific visible minima remain authoritative.
        budget = cadence * max(2.4, float(capacity) + 0.8)
        return max(float(H70_ADAPT_BUDGET_MIN_MS), min(float(H70_ADAPT_BUDGET_MAX_MS), budget))
    except Exception:
        return 0.0


def _h70_begin_fade(row):
    out = _h70_fading_begin_pre(row) if callable(_h70_fading_begin_pre) else None
    try:
        row._h70_deadline_budget_ms = _h70_release_budget_ms(row)
        row._h70_adapt_log_key = None
    except Exception:
        pass
    return out


def _h70_effect_min_duration(effect):
    effect = _h70_effect_key(effect)
    return {
        'fade': 380.0,
        'per_char': 620.0,
        'wipe_ltr': 560.0,
        'wipe_rtl': 560.0,
        'shrink': 320.0,
        'soft_drift': 460.0,
        'hop_drop': 420.0,
    }.get(effect, 380.0)


def _h70_soft_adapt_duration(row, effect, preferred_ms):
    effect = _h70_effect_key(effect)
    preferred = max(_h70_effect_min_duration(effect), float(preferred_ms or 0.0))
    if effect in ('blur_decay', 'instant'):
        return preferred
    budget = float(getattr(row, '_h70_deadline_budget_ms', 0.0) or 0.0)
    if budget <= 0.0 or preferred <= budget:
        return preferred
    # Keep some of the user's excess duration so "slow" remains visibly slower than "fast",
    # but bound the tail in burst sections so fixed-speed effects do not pile up into direct clears.
    softened = budget + (preferred - budget) * float(H70_ADAPT_EXCESS_KEEP)
    hard = budget * float(H70_ADAPT_HARD_MULT) + float(H70_ADAPT_HARD_PAD_MS)
    result = max(_h70_effect_min_duration(effect), min(preferred, softened, hard))
    if result < preferred - 12.0:
        key = (effect, int(round(preferred)), int(round(result)), int(round(budget)))
        if getattr(row, '_h70_adapt_log_key', None) != key:
            row._h70_adapt_log_key = key
            try:
                write_error_log('H70退场时间预算适配', detail=(
                    f'effect={effect} | speed={_h70_row_speed(row)} | preferred={preferred:.0f}ms | '
                    f'budget={budget:.0f}ms | effective={result:.0f}ms | flavor={int(round(_h70_row_flavor(row)*100))}% | instant=0'))
            except Exception:
                pass
    return result


def _h70_h16_exit_duration_ms(row):
    if not callable(_h70_h16_duration_pre):
        return 720.0
    preferred = float(_h70_h16_duration_pre(row))
    if bool(getattr(row, '_h70_duration_inner', False)):
        return preferred
    return _h70_soft_adapt_duration(row, getattr(row, 'exit_effect', 'fade'), preferred)


def _h70_h51_exit_duration_ms(row, effect):
    effect = _h70_effect_key(effect)
    if effect == 'shrink':
        # H51 intentionally clamped quick-shrink to >=420 ms, which made the upper half of the
        # old 1..15 speed slider visually identical. H70 keeps 420 ms at the migrated default
        # speed=12 but translates the full profile range around that anchor.
        preferred = 420.0 * _h70_time_scale_from_speed(_h70_row_speed(row))
        preferred = max(320.0, min(1200.0, preferred))
        return _h70_soft_adapt_duration(row, effect, preferred)
    if not callable(_h70_h51_duration_pre):
        return _h70_h16_exit_duration_ms(row)
    row._h70_duration_inner = True
    try:
        preferred = float(_h70_h51_duration_pre(row, effect))
    finally:
        row._h70_duration_inner = False
    return _h70_soft_adapt_duration(row, effect, preferred)


def _h70_h68_plan_for_row(window, row, capacity, now=None):
    if not callable(_h70_h68_plan_pre):
        return (0.0, 720.0, 0, 0.0)
    remaining, tail, evict, full = _h70_h68_plan_pre(window, row, capacity, now)
    if _h70_effect_key(getattr(row, 'exit_effect', '')) == 'blur_decay':
        scale = _h70_time_scale_from_speed(_h70_row_speed(row))
        tail = max(float(H70_BLUR_TAIL_MIN_MS), min(float(H70_BLUR_TAIL_MAX_MS), float(tail) * scale))
    return float(remaining), float(tail), int(evict), float(full)


def _h70_h68_release_duration(row, p0, initial_velocity):
    if not callable(_h70_h68_release_duration_pre):
        return 720.0
    base = float(_h70_h68_release_duration_pre(row, p0, initial_velocity))
    if _h70_effect_key(getattr(row, 'exit_effect', '')) != 'blur_decay':
        return base
    scale = _h70_time_scale_from_speed(_h70_row_speed(row))
    # H68's active planner already saw the scaled tail. Use a square-root release correction
    # so the handoff honors the preference without double-applying the full scale.
    release_scale = math.sqrt(max(0.25, scale))
    return max(float(H70_BLUR_TAIL_MIN_MS), min(float(H70_BLUR_TAIL_MAX_MS), base * release_scale))


def _h70_seed_unit(row, index, salt=0):
    try:
        raw = f'{getattr(row,"text","")}|{int(index)}|{int(salt)}'.encode('utf-8')
        return float(zlib.crc32(raw) & 0xffffffff) / float(0xffffffff)
    except Exception:
        return 0.5


def _h70_fragment_exit_draw(row, painter, effect, progress):
    flavor = _h70_row_flavor(row)
    effect = _h70_effect_key(effect)
    if flavor <= 0.0001 or effect not in ('per_char', 'wipe_ltr', 'wipe_rtl'):
        return _h70_fragment_draw_pre(row, painter, effect, progress) if callable(_h70_fragment_draw_pre) else False
    pack = row._ensure_row_fragment_sheet()
    if pack is None:
        return False
    sheet, meta, _pixels = pack
    if sheet is None or sheet.isNull():
        return True
    try:
        try: sheet_key = int(sheet.cacheKey())
        except Exception: sheet_key = 0
        layout_key = (
            str(getattr(row, '_glyph_cache_key', '') or ''), str(getattr(row, 'text', '') or ''),
            float(getattr(row, 'spacing', 0.0) or 0.0), float(getattr(row, 'angle', 0.0) or 0.0),
            int(getattr(row, 'screen_width', 0) or 0), bool(getattr(row, 'horizontal_wrap', False)), sheet_key,
        )
        cached = getattr(row, '_h51_exit_layout_cache', None)
        if not isinstance(cached, tuple) or len(cached) != 5 or cached[0] != layout_key:
            font = QFont(row.font); fm = QFontMetrics(font)
            th = float(getattr(row, '_glyph_cache_height', 0.0) or fm.height())
            angle_rad = math.radians(float(getattr(row, 'angle', 0.0) or 0.0))
            cos_angle = math.cos(angle_rad); sin_angle = math.sin(angle_rad)
            advances = [
                float(row._glyph_cache_advances[i]) if i < len(row._glyph_cache_advances) else float(fm.horizontalAdvance(ch))
                for i, ch in enumerate(row.text)
            ]
            emphasis_offsets = _audio_emphasis_cursor_offsets(advances, row.glyph_scales, row.spacing)
            raw_centers = [
                (float(emphasis_offsets[i]) if i < len(emphasis_offsets) else 0.0) + float(advances[i]) * 0.5
                for i in range(len(row.text))
            ]
            min_center = min(raw_centers, default=0.0); max_center = max(raw_centers, default=1.0)
            span = max(1.0, max_center - min_center); n = max(1, len(row.text))
            scatter_indices = list(range(n))
            scatter_rng = random.Random(zlib.crc32(str(getattr(row, 'text', '') or '').encode('utf-8')) & 0xffffffff)
            scatter_rng.shuffle(scatter_indices)
            scatter_rank = [0.0] * n
            for scatter_pos, scatter_idx in enumerate(scatter_indices):
                scatter_rank[scatter_idx] = float(scatter_pos) / max(1.0, n - 1.0)
            static = []
            for i, ch in enumerate(row.text):
                item = meta[i] if i < len(meta) else None
                if item is None:
                    static.append(None); continue
                if len(item) >= 6: source, left, top, lw, lh, source_ss = item[:6]
                else: source, left, top, lw, lh = item[:5]; source_ss = 1.0
                br = row._glyph_cache_bounds[i] if i < len(row._glyph_cache_bounds) else QRectF(fm.boundingRect(ch))
                cursor = float(emphasis_offsets[i]) if i < len(emphasis_offsets) else 0.0
                geom_norm = (raw_centers[i] - min_center) / span if i < len(raw_centers) else (float(i) / max(1.0, n - 1.0))
                per_char_order = float(scatter_rank[i]) if i < len(scatter_rank) else 0.0
                base_scale = max(1.0, min(float(AUDIO_EMPHASIS_ABSOLUTE_MAX_SCALE), float(row.glyph_scales[i]) if i < len(row.glyph_scales) else 1.0))
                static.append((QRectF(source), float(left), float(top), float(lw), float(lh), max(1.0, float(source_ss or 1.0)), float(advances[i]), cursor, QRectF(br), float(geom_norm), float(per_char_order), float(base_scale)))
            cached = (layout_key, th, cos_angle, sin_angle, static); row._h51_exit_layout_cache = cached
        _layout_key, th, cos_angle, sin_angle, static = cached
        fragments = []; p = max(0.0, min(1.0, float(progress)))
        wrap_enabled = bool(getattr(row, 'horizontal_wrap', False) and int(getattr(row, 'screen_width', 0) or 0) > 1)
        viewport_h = painter.viewport().height() if wrap_enabled else 0
        for i, item in enumerate(static):
            if item is None: continue
            source, left, top, lw, lh, source_ss, cw, cursor, br, geom_norm, per_char_order, base_scale = item
            if LIVE_HISTORY_DRAW_ENABLED and i < len(row.char_shakes):
                sx = float(row.char_shakes[i].get('x', 0) or 0); sy = float(row.char_shakes[i].get('y', 0) or 0)
            else:
                sx = sy = 0.0
            ox = cursor * cos_angle; oy = cursor * sin_angle
            if wrap_enabled:
                # H69 invariant: random shake and H70 flavor motion are visual only; neither may
                # decide which wrap period a glyph belongs to.
                local_rect = QRectF(ox + float(br.left()), oy + th / 3.0 + float(br.top()), max(cw, float(br.width()), 1.0), max(float(br.height()), 1.0))
                dx, dy, _ = _device_space_staggered_wrap_adjust(painter, local_rect, row.screen_width, viewport_h, th)
                ox += dx; oy += dy
            draw_x = float(ox + sx + left); draw_y = float(oy + sy + top)
            ghost_opacity = 0.0; ghost_shift_x = 0.0; ghost_shift_y = 0.0
            if effect == 'per_char':
                jitter = (_h70_seed_unit(row, i, 17) - 0.5) * 0.18 * flavor
                window = max(0.30, 0.42 - 0.07 * flavor)
                start = max(0.0, min(1.0 - window, per_char_order * 0.58 + jitter))
                lp = max(0.0, min(1.0, (p - start) / window))
                ease = _h51_smoothstep(lp); opacity = 1.0 - ease
                theta = _h70_seed_unit(row, i, 29) * math.pi * 2.0
                drift = (10.0 + 18.0 * flavor) * flavor * (ease ** 1.25)
                shift_x = math.cos(theta) * drift
                shift_y = 3.0 * ease + math.sin(theta) * drift * 0.72
                local_scale = 1.0 - (0.07 + 0.045 * flavor) * ease
            else:
                order = geom_norm if effect == 'wipe_ltr' else 1.0 - geom_norm
                start_span = 0.56 - 0.06 * flavor
                fade_span = 0.44 + 0.06 * flavor
                start = order * start_span
                lp = max(0.0, min(1.0, (p - start) / max(0.08, fade_span)))
                ease = _h51_smoothstep(lp); opacity = 1.0 - ease
                direction = 1.0 if effect == 'wipe_ltr' else -1.0
                shift_x = 7.0 * direction * ease; shift_y = 0.0
                local_scale = 1.0 - 0.035 * ease
                # A bounded secondary fragment follows the wipe frontier. This is a true trail,
                # not another whole-row movement, and disappears at both ends of the local interval.
                ghost_opacity = max(0.0, min(0.18 * flavor, 0.18 * flavor * math.sin(math.pi * lp)))
                ghost_shift_x = -direction * (4.0 + 9.0 * flavor)
            if opacity <= 0.002 and ghost_opacity <= 0.002:
                continue
            scale = base_scale * local_scale
            anchor_x = draw_x + lw * 0.5; anchor_y = draw_y + lh * 0.82
            scaled_left = anchor_x + (draw_x - anchor_x) * scale + shift_x
            scaled_top = anchor_y + (draw_y - anchor_y) * scale + shift_y
            scaled_w = lw * scale; scaled_h = lh * scale
            center = QPointF(scaled_left + scaled_w * 0.5, scaled_top + scaled_h * 0.5)
            fragment_scale = float(scale) / source_ss
            if ghost_opacity > 0.002:
                ghost_center = QPointF(center.x() + ghost_shift_x, center.y() + ghost_shift_y)
                fragments.append(QPainter.PixmapFragment.create(ghost_center, source, fragment_scale * 1.01, fragment_scale * 1.01, 0.0, ghost_opacity))
            if opacity > 0.002:
                fragments.append(QPainter.PixmapFragment.create(center, source, fragment_scale, fragment_scale, 0.0, max(0.0, min(1.0, opacity))))
        if not fragments:
            return True
        painter.setOpacity(1.0); painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        painter.drawPixmapFragments(fragments, sheet)
        return True
    except Exception as exc:
        try: write_error_log('H70专属风味片段绘制回退', exc, detail=f'effect={effect}')
        except Exception: pass
        return _h70_fragment_draw_pre(row, painter, effect, progress) if callable(_h70_fragment_draw_pre) else False


def _h70_fading_update(row):
    effect = _h70_effect_key(getattr(row, 'exit_effect', 'fade'))
    if effect == 'soft_drift':
        now = time.monotonic() * 1000.0
        started = float(getattr(row, '_h16_exit_started_mono', 0.0) or 0.0)
        if started <= 0.0:
            started = now; row._h16_exit_started_mono = now
        # Preserve H20's 620 ms default at speed=12, but unlike its old 620..1050 clamp, make
        # the complete profile range meaningful in both directions.
        preferred = 620.0 * _h70_time_scale_from_speed(_h70_row_speed(row))
        preferred = max(460.0, min(2200.0, preferred))
        duration = _h70_soft_adapt_duration(row, effect, preferred)
        p = max(0.0, min(1.0, (now - started) / max(1.0, duration)))
        row._h16_exit_progress = p
        eased = _h51_smoothstep(p) if '_h51_smoothstep' in globals() else p*p*(3.0-2.0*p)
        row._fade_alpha_float = 255.0 * (1.0 - eased)
        row.alpha = max(0, min(255, int(round(row._fade_alpha_float))))
        if row.alpha > int(FADE_SHAKE_FREEZE_ALPHA):
            try: row._update_shake_motion()
            except Exception: pass
        if p >= 1.0 or row.alpha <= int(FADE_VISUAL_ALPHA_CUTOFF):
            row.release_render_resources(); return False
        return True
    if effect != 'hop_drop':
        return _h70_fading_update_pre(row) if callable(_h70_fading_update_pre) else False
    now = time.monotonic() * 1000.0
    started = float(getattr(row, '_h59_hop_started_mono', 0.0) or 0.0)
    if started <= 0.0:
        started = now; row._h59_hop_started_mono = now; row._h59_exit_begin_mono = now; row._h59_exit_draw_count = 0
    elif int(getattr(row, '_h59_exit_draw_count', 0) or 0) <= 0 and now - started > float(H59_EXIT_FIRST_FRAME_CATCHUP_MS):
        started = now - float(H59_EXIT_FIRST_FRAME_CATCHUP_MS); row._h59_hop_started_mono = started
        if not bool(getattr(row, '_h59_first_frame_clamped', False)):
            row._h59_first_frame_clamped = True
            try: write_error_log('H59退场首帧连续性保护', detail='effect=hop_drop | timer=H70-profile-hop')
            except Exception: pass
    preferred = float(H59_HOP_DURATION_MS) * _h70_time_scale_from_speed(_h70_row_speed(row))
    duration = _h70_soft_adapt_duration(row, effect, preferred)
    p = max(0.0, min(1.0, (now - started) / max(1.0, duration)))
    row._h59_hop_progress = p
    _dy, alpha_ratio = _h59_hop_profile(p)
    row._fade_alpha_float = 255.0 * alpha_ratio; row.alpha = max(0, min(255, int(round(row._fade_alpha_float))))
    if p < 0.82:
        try: row._update_shake_motion()
        except Exception: pass
    if p >= 1.0 or row.alpha <= int(FADE_VISUAL_ALPHA_CUTOFF):
        row.release_render_resources(); return False
    return True


def _h70_fading_draw(row, painter):
    effect = _h70_effect_key(getattr(row, 'exit_effect', 'fade'))
    flavor = _h70_row_flavor(row)
    if flavor <= 0.0001 or effect in ('per_char', 'wipe_ltr', 'wipe_rtl', 'instant'):
        return _h70_fading_draw_pre(row, painter) if callable(_h70_fading_draw_pre) else None
    p = max(0.0, min(1.0, float(getattr(row, '_h16_exit_progress', 0.0) or 0.0)))
    if effect == 'hop_drop':
        p = max(0.0, min(1.0, float(getattr(row, '_h59_hop_progress', p) or p)))
    elif effect == 'blur_decay':
        try: p = max(0.0, min(1.0, float(_h62_decay_progress(row))))
        except Exception: p = max(0.0, min(1.0, float(getattr(row, '_h62_decay_progress', p) or p)))
    painter.save()
    try:
        if effect == 'fade':
            eased = 1.0 - (1.0 - p) * (1.0 - p)
            rise = float(H70_FADE_RISE_MAX_PX) * flavor * eased
            painter.translate(0.0, -rise)
        elif effect == 'shrink':
            q = max(0.0, min(1.0, p / 0.34))
            pretension = float(H70_SHRINK_PRETENSION_MAX) * flavor * math.sin(math.pi * q) if p < 0.34 else 0.0
            if pretension > 0.0001:
                painter.translate(float(row.x), float(row.y)); painter.scale(1.0 + pretension, 1.0 + pretension); painter.translate(-float(row.x), -float(row.y))
        elif effect == 'soft_drift':
            gravity = float(H70_SOFT_GRAVITY_EXTRA_PX) * flavor * (p ** 2.25)
            painter.translate(0.0, gravity)
        elif effect == 'hop_drop':
            apex = 0.30
            if p <= apex:
                q = p / apex; extra_y = -float(H70_HOP_EXTRA_UP_PX) * flavor * math.sin(q * math.pi * 0.5)
            else:
                q = (p - apex) / max(0.001, 1.0 - apex)
                extra_y = -float(H70_HOP_EXTRA_UP_PX) * flavor * (1.0 - q) + float(H70_HOP_EXTRA_DROP_PX) * flavor * (q * q)
            painter.translate(0.0, extra_y)
            rot_strength = max(0.0, (flavor - 0.55) / 0.45)
            if rot_strength > 0.0:
                sign = -1.0 if _h70_seed_unit(row, 0, 71) < 0.5 else 1.0
                rot = sign * 3.0 * rot_strength * math.sin(math.pi * p)
                painter.translate(float(row.x), float(row.y)); painter.rotate(rot); painter.translate(-float(row.x), -float(row.y))
        elif effect == 'blur_decay':
            eased = _h51_smoothstep(p) if '_h51_smoothstep' in globals() else p
            expansion = 1.0 + float(H70_BLUR_DEPTH_EXPAND_MAX) * flavor * eased
            painter.translate(float(row.x), float(row.y)); painter.scale(expansion, expansion); painter.translate(-float(row.x), -float(row.y))
        return _h70_fading_draw_pre(row, painter) if callable(_h70_fading_draw_pre) else None
    finally:
        painter.restore()


def _h70_speed_text(value):
    v = int(round(_h70_clamp(value, H70_SPEED_MIN, H70_SPEED_MAX, H70_SPEED_DEFAULT)))
    if v == H70_SPEED_DEFAULT: return f'{v} · 默认'
    if v <= 5: return f'{v} · 舒缓'
    if v <= 9: return f'{v} · 偏慢'
    if v <= 13: return f'{v} · 稍快' if v > H70_SPEED_DEFAULT else f'{v} · 接近默认'
    return f'{v} · 利落'


def _h70_flavor_text(effect, value):
    effect = _h70_effect_key(effect); v = int(round(_h70_clamp(value, 0, 100, 0)))
    if effect == 'fade':
        return f'{int(round(H70_FADE_RISE_MAX_PX * v / 100.0))} px'
    if effect == 'instant':
        return '无动画'
    return f'{v}%'


def _h70_sync_profile_ui(panel):
    if not hasattr(panel, 'h70_exit_speed_slider'):
        return
    effect = _h70_effect_key(panel.h12_exit_combo.currentData() if hasattr(panel, 'h12_exit_combo') else getattr(panel.lyric_window, 'exit_effect', 'fade'))
    profile = dict(getattr(panel, '_h70_exit_profiles', {}).get(effect, {'speed': H70_SPEED_DEFAULT, 'flavor': 0}))
    panel.lyric_window.exit_effect = effect
    panel.lyric_window._h70_exit_profiles = panel._h70_exit_profiles
    panel.h70_exit_speed_slider.blockSignals(True); panel.h70_exit_flavor_slider.blockSignals(True)
    try:
        panel.h70_exit_speed_slider.setValue(int(profile.get('speed', H70_SPEED_DEFAULT)))
        panel.h70_exit_flavor_slider.setValue(int(profile.get('flavor', 0)))
    finally:
        panel.h70_exit_speed_slider.blockSignals(False); panel.h70_exit_flavor_slider.blockSignals(False)
    label = H70_FLAVOR_LABELS.get(effect, '专属风味')
    panel.h70_exit_flavor_name.setText(label + '：')
    panel.h70_exit_speed_value.setText(_h70_speed_text(panel.h70_exit_speed_slider.value()))
    panel.h70_exit_flavor_value.setText(_h70_flavor_text(effect, panel.h70_exit_flavor_slider.value()))
    enabled = effect != 'instant'
    panel.h70_exit_speed_slider.setEnabled(enabled); panel.h70_exit_flavor_slider.setEnabled(enabled)
    panel.h70_exit_speed_name.setEnabled(enabled); panel.h70_exit_flavor_name.setEnabled(enabled)
    panel.h70_exit_speed_value.setEnabled(enabled); panel.h70_exit_flavor_value.setEnabled(enabled)
    tips = {
        'fade': '上升距离：0=原地整行淡出；提高后在同一淡出时间轴上向上漂移。',
        'per_char': '离散度：0=H69 原逐字退场；提高后每个字增加稳定的时间错落与局部漂移。',
        'wipe_ltr': '拖尾：0=原左→右字形渐隐；提高后波前更柔，并带短暂的字形余辉拖尾。',
        'wipe_rtl': '拖尾：0=原右→左字形渐隐；提高后波前更柔，并带短暂的字形余辉拖尾。',
        'shrink': '蓄力：0=原快速收缩；提高后收缩前加入一次很短、受限的预张力，不循环弹跳。',
        'soft_drift': '重力感：0=原柔和下沉；提高后后半程下沉加速度更明显。',
        'hop_drop': '弹性：0=原轻跃下坠；提高后上抛/落下弧线更有弹性，高强度才加入极轻旋转。',
        'blur_decay': '景深扩散：0=H69 原渐进失焦；提高后失焦过程中增加轻微的空间扩散感，不改变模糊计时。',
        'instant': '直接消失没有动画，因此没有速度或专属风味。',
    }
    panel.h70_exit_flavor_slider.setToolTip(tips.get(effect, ''))
    panel.h70_exit_speed_slider.setToolTip('每个退场特效独立记忆。正常歌曲尽量完全遵守；超高密度歌词只会在必要时软压缩实际时长，绝不会改动专属风味。')


def _h70_profile_slider_changed(panel, field, value):
    effect = _h70_effect_key(panel.h12_exit_combo.currentData() if hasattr(panel, 'h12_exit_combo') else getattr(panel.lyric_window, 'exit_effect', 'fade'))
    if effect == 'instant':
        return
    profiles = getattr(panel, '_h70_exit_profiles', None)
    if not isinstance(profiles, dict):
        profiles = _h70_normalize_profiles({}); panel._h70_exit_profiles = profiles
    item = profiles.setdefault(effect, {'speed': H70_SPEED_DEFAULT, 'flavor': 0})
    if field == 'speed': item['speed'] = int(round(_h70_clamp(value, H70_SPEED_MIN, H70_SPEED_MAX, H70_SPEED_DEFAULT)))
    else: item['flavor'] = int(round(_h70_clamp(value, H70_FLAVOR_MIN, H70_FLAVOR_MAX, 0)))
    panel.lyric_window._h70_exit_profiles = profiles
    panel.h70_exit_speed_value.setText(_h70_speed_text(item['speed']))
    panel.h70_exit_flavor_value.setText(_h70_flavor_text(effect, item['flavor']))
    try: panel._schedule_config_save()
    except Exception: pass


def _h70_control_init(panel, *args, **kwargs):
    try: initial_settings = dict((load_all_config().get('settings') or {}))
    except Exception: initial_settings = {}
    _h70_control_init_pre(panel, *args, **kwargs)
    try:
        panel._h70_exit_profiles = _h70_normalize_profiles(initial_settings)
        panel.lyric_window._h70_exit_profiles = panel._h70_exit_profiles
        # Retain the old widgets for config/preset compatibility, but do not expose two competing
        # sets of timing controls. H70's profile sliders are the user-facing owner from here on.
        for name in ('fade_speed_slider', 'fade_speed_label', 'rise_speed_slider', 'rise_speed_label'):
            w = getattr(panel, name, None)
            if w is not None: w.hide()
        for label in panel.findChildren(QLabel):
            if str(label.text() or '') in ('淡出速度：', '上升速度：', '退场特效：'):
                label.hide()
        area = panel.main_tabs.widget(2) if hasattr(panel, 'main_tabs') and panel.main_tabs.count() > 2 else None
        page = area.widget() if area is not None and hasattr(area, 'widget') else None
        layout = page.layout() if page is not None else None
        if layout is not None and hasattr(panel, 'h12_exit_combo'):
            card = QFrame(page); card.setObjectName('settingsCard')
            v = QVBoxLayout(card); v.setContentsMargins(16, 15, 16, 16); v.setSpacing(10)
            title = QLabel('退场动效'); title.setObjectName('sectionTitle'); v.addWidget(title)
            hint = QLabel('每种退场会记住自己的速度与专属风味；风味设为 0 就回到该效果原本的表现。')
            hint.setWordWrap(True); hint.setObjectName('trackDetail'); v.addWidget(hint)
            row = QHBoxLayout(); row.addWidget(QLabel('退场特效：')); row.addWidget(panel.h12_exit_combo, 1); v.addLayout(row)
            row = QHBoxLayout(); panel.h70_exit_speed_name = QLabel('退场速度：'); row.addWidget(panel.h70_exit_speed_name)
            panel.h70_exit_speed_slider = QSlider(Qt.Horizontal); panel.h70_exit_speed_slider.setRange(H70_SPEED_MIN, H70_SPEED_MAX)
            panel.h70_exit_speed_value = QLabel(''); panel.h70_exit_speed_value.setMinimumWidth(74)
            row.addWidget(panel.h70_exit_speed_slider, 1); row.addWidget(panel.h70_exit_speed_value); v.addLayout(row)
            row = QHBoxLayout(); panel.h70_exit_flavor_name = QLabel('专属风味：'); row.addWidget(panel.h70_exit_flavor_name)
            panel.h70_exit_flavor_slider = QSlider(Qt.Horizontal); panel.h70_exit_flavor_slider.setRange(H70_FLAVOR_MIN, H70_FLAVOR_MAX)
            panel.h70_exit_flavor_value = QLabel(''); panel.h70_exit_flavor_value.setMinimumWidth(74)
            row.addWidget(panel.h70_exit_flavor_slider, 1); row.addWidget(panel.h70_exit_flavor_value); v.addLayout(row)
            layout.insertWidget(max(0, layout.count() - 1), card)
            panel.h12_exit_combo.currentIndexChanged.connect(lambda _i: (_h70_sync_profile_ui(panel), panel._schedule_config_save()))
            panel.h70_exit_speed_slider.valueChanged.connect(lambda x: _h70_profile_slider_changed(panel, 'speed', x))
            panel.h70_exit_flavor_slider.valueChanged.connect(lambda x: _h70_profile_slider_changed(panel, 'flavor', x))
            _h70_sync_profile_ui(panel)
            try:
                panel._filter_settings_cards('')
            except Exception:
                pass
    except Exception as exc:
        try: write_error_log('H70退场配置界面初始化失败', exc)
        except Exception: pass



def _h70_capture_style_preset(panel):
    data = _h70_capture_preset_pre(panel) if callable(_h70_capture_preset_pre) else {}
    if not isinstance(data, dict):
        data = {}
    try:
        data['h70_exit_profiles'] = _h70_normalize_profiles({
            'fade_speed': getattr(panel, 'fade_speed_slider', None).value() if hasattr(panel, 'fade_speed_slider') else H70_SPEED_DEFAULT,
            'rise_speed': getattr(panel, 'rise_speed_slider', None).value() if hasattr(panel, 'rise_speed_slider') else 1,
            'h70_exit_profiles': getattr(panel, '_h70_exit_profiles', {}),
        })
        data['h70_exit_profile_schema'] = int(H70_PROFILE_SCHEMA)
    except Exception:
        pass
    return data


def _h70_load_style_preset(panel, name):
    preset = dict(getattr(panel, 'presets', {}).get(name, {}) or {}) if name in getattr(panel, 'presets', {}) else {}
    out = _h70_load_preset_pre(panel, name) if callable(_h70_load_preset_pre) else None
    try:
        if preset:
            if isinstance(preset.get('h70_exit_profiles'), dict):
                profiles = _h70_normalize_profiles({
                    'fade_speed': preset.get('fade_speed', H70_SPEED_DEFAULT),
                    'rise_speed': preset.get('rise_speed', 1),
                    'h70_exit_profiles': preset.get('h70_exit_profiles'),
                })
            else:
                # A pre-H70 "complete style" preset owned one global fade/rise pair. Migrate it
                # deterministically so loading an old preset still changes exit timing as before.
                profiles = _h70_normalize_profiles({
                    'fade_speed': preset.get('fade_speed', H70_SPEED_DEFAULT),
                    'rise_speed': preset.get('rise_speed', 1),
                })
            panel._h70_exit_profiles = profiles
            panel.lyric_window._h70_exit_profiles = profiles
            _h70_sync_profile_ui(panel)
            try: panel._schedule_config_save()
            except Exception: pass
    except Exception as exc:
        try: write_error_log('H70退场预设恢复失败', exc, detail=str(name))
        except Exception: pass
    return out

def _h70_save_all_config(panel, presets, players):
    if callable(_h70_save_pre):
        _h70_save_pre(panel, presets, players)
    try:
        data = load_all_config(); st = data.setdefault('settings', {})
        st['h70_exit_profile_schema'] = int(H70_PROFILE_SCHEMA)
        st['h70_exit_profiles'] = _h70_normalize_profiles({'fade_speed': st.get('fade_speed', H70_SPEED_DEFAULT), 'rise_speed': st.get('rise_speed', 1), 'h70_exit_profiles': getattr(panel, '_h70_exit_profiles', {})})
        _write_config_dict_atomic(data)
    except Exception as exc:
        try: write_error_log('H70退场配置保存失败', exc)
        except Exception: pass


def _h70_activate_runtime():
    try:
        if callable(_h70_h16_duration_pre):
            globals()['_h16_exit_duration_ms'] = _h70_h16_exit_duration_ms
            _h16_exit_duration_ms._limbus_layer = 'H70'
            _h16_exit_duration_ms._limbus_policy = 'per-effect requested speed plus release-time soft deadline budget'
        if callable(_h70_h51_duration_pre):
            globals()['_h51_exit_duration_ms'] = _h70_h51_exit_duration_ms
            _h51_exit_duration_ms._limbus_layer = 'H70'
        if callable(_h70_fragment_draw_pre):
            globals()['_h51_fragment_exit_draw'] = _h70_fragment_exit_draw
            _h51_fragment_exit_draw._limbus_layer = 'H70'
            _h51_fragment_exit_draw._limbus_policy = 'zero-flavor exact delegate; per-char scatter and wipe trail only above zero'
        if callable(_h70_h68_plan_pre):
            globals()['_h68_plan_for_row'] = _h70_h68_plan_for_row
            _h68_plan_for_row._limbus_layer = 'H70'
        if callable(_h70_h68_release_duration_pre):
            globals()['_h68_release_duration'] = _h70_h68_release_duration
            _h68_release_duration._limbus_layer = 'H70'
        if 'LyricWindow' in globals() and callable(_h70_make_history_pre):
            LyricWindow._make_history_line = _h70_make_history_line
            LyricWindow._make_history_line._limbus_layer = 'H70'
            LyricWindow._make_history_line._limbus_policy = 'snapshot per-effect speed/flavor at row birth; no mid-animation UI retarget'
        if 'FadingLine' in globals():
            if callable(_h70_fading_begin_pre):
                FadingLine.begin_fade = _h70_begin_fade; FadingLine.begin_fade._limbus_layer = 'H70'
            if callable(_h70_fading_update_pre):
                FadingLine.update = _h70_fading_update; FadingLine.update._limbus_layer = 'H70'
            if callable(_h70_fading_draw_pre):
                FadingLine.draw = _h70_fading_draw; FadingLine.draw._limbus_layer = 'H70'
                FadingLine.draw._limbus_policy = 'optional flavor overlay; zero delegates mature H69/H63/H59/H51 renderer'
        if 'ControlPanel' in globals() and callable(_h70_control_init_pre):
            ControlPanel.__init__ = _h70_control_init
            ControlPanel.__init__._limbus_layer = 'H70'
            ControlPanel.__init__._limbus_policy = 'dynamic per-effect remembered speed and named flavor controls'
            if callable(_h70_capture_preset_pre):
                ControlPanel._capture_style_preset = _h70_capture_style_preset
                ControlPanel._capture_style_preset._limbus_layer = 'H70'
            if callable(_h70_load_preset_pre):
                ControlPanel.load_preset = _h70_load_style_preset
                ControlPanel.load_preset._limbus_layer = 'H70'
        globals()['save_all_config'] = _h70_save_all_config
    except Exception as exc:
        try: write_error_log('H70每特效退场配置安装失败', exc)
        except Exception: pass


if '_h70_activate_runtime' in globals():
    _h70_activate_runtime()



# H71 flavor presence + instant UI cleanup ---------------------------------------
# H70 established the right ownership model (per-effect speed + optional flavor), but field
# feedback showed several flavor maxima were intentionally so conservative that 0% and 100%
# could look nearly identical at normal desktop scale. H71 does not touch timing ownership.
# It recalibrates *presentation amplitude* so ~50% is plainly visible and 100% is a distinct
# style while preserving the hard invariant flavor=0 => exact H70/H69 appearance.
#
# Fragment-native effects also request an H61 row-material prewarm when flavor is enabled. If
# the immutable fragment material already exists this is free; otherwise it avoids arriving at
# the fade lane with the optional flavor silently degraded to the whole-row fallback.
H71_PRESENCE_POWER = 0.72
H71_PER_CHAR_DRIFT_BASE_PX = 16.0
H71_PER_CHAR_DRIFT_GAIN_PX = 48.0
H71_PER_CHAR_ROT_MAX_DEG = 7.5
H71_PER_CHAR_VERTICAL_BASE_PX = 5.0
H71_WIPE_GHOST_MAX_ALPHA = 0.32
H71_WIPE_GHOST_SHIFT_BASE_PX = 8.0
H71_WIPE_GHOST_SHIFT_GAIN_PX = 18.0
H71_WIPE_SECOND_GHOST_MAX_ALPHA = 0.12
H71_WIPE_SECOND_GHOST_MULT = 1.72
H71_SHRINK_EXTRA_PRETENSION = 0.070
H71_SOFT_EXTRA_GRAVITY_PX = 58.0
H71_HOP_EXTRA_UP_PX = 26.0
H71_HOP_EXTRA_DROP_PX = 48.0
H71_HOP_EXTRA_ROT_DEG = 3.5
H71_BLUR_EXTRA_EXPAND = 0.060

_h71_fragment_draw_pre = globals().get('_h51_fragment_exit_draw')
_h71_fading_draw_pre = getattr(FadingLine, 'draw', None) if 'FadingLine' in globals() else None
_h71_make_history_pre = getattr(LyricWindow, '_make_history_line', None) if 'LyricWindow' in globals() else None
_h71_sync_profile_ui_pre = globals().get('_h70_sync_profile_ui')


def _h71_presence(value):
    x = max(0.0, min(1.0, float(value or 0.0)))
    if x <= 0.0:
        return 0.0
    return max(0.0, min(1.0, x ** float(H71_PRESENCE_POWER)))


def _h71_fragment_exit_draw(row, painter, effect, progress):
    raw_flavor = _h70_row_flavor(row)
    effect = _h70_effect_key(effect)
    if raw_flavor <= 0.0001 or effect not in ('per_char', 'wipe_ltr', 'wipe_rtl'):
        return _h71_fragment_draw_pre(row, painter, effect, progress) if callable(_h71_fragment_draw_pre) else False
    flavor = _h71_presence(raw_flavor)
    pack = row._ensure_row_fragment_sheet()
    if pack is None:
        # Preserve H70's mature fallback semantics. H71's row-birth prewarm makes this path
        # uncommon without forcing synchronous raster work into paintEvent.
        return _h71_fragment_draw_pre(row, painter, effect, progress) if callable(_h71_fragment_draw_pre) else False
    sheet, meta, _pixels = pack
    if sheet is None or sheet.isNull():
        return True
    try:
        try: sheet_key = int(sheet.cacheKey())
        except Exception: sheet_key = 0
        layout_key = (
            str(getattr(row, '_glyph_cache_key', '') or ''), str(getattr(row, 'text', '') or ''),
            float(getattr(row, 'spacing', 0.0) or 0.0), float(getattr(row, 'angle', 0.0) or 0.0),
            int(getattr(row, 'screen_width', 0) or 0), bool(getattr(row, 'horizontal_wrap', False)), sheet_key,
        )
        cached = getattr(row, '_h51_exit_layout_cache', None)
        if not isinstance(cached, tuple) or len(cached) != 5 or cached[0] != layout_key:
            font = QFont(row.font); fm = QFontMetrics(font)
            th = float(getattr(row, '_glyph_cache_height', 0.0) or fm.height())
            angle_rad = math.radians(float(getattr(row, 'angle', 0.0) or 0.0))
            cos_angle = math.cos(angle_rad); sin_angle = math.sin(angle_rad)
            advances = [
                float(row._glyph_cache_advances[i]) if i < len(row._glyph_cache_advances) else float(fm.horizontalAdvance(ch))
                for i, ch in enumerate(row.text)
            ]
            emphasis_offsets = _audio_emphasis_cursor_offsets(advances, row.glyph_scales, row.spacing)
            raw_centers = [
                (float(emphasis_offsets[i]) if i < len(emphasis_offsets) else 0.0) + float(advances[i]) * 0.5
                for i in range(len(row.text))
            ]
            min_center = min(raw_centers, default=0.0); max_center = max(raw_centers, default=1.0)
            span = max(1.0, max_center - min_center); n = max(1, len(row.text))
            scatter_indices = list(range(n))
            scatter_rng = random.Random(zlib.crc32(str(getattr(row, 'text', '') or '').encode('utf-8')) & 0xffffffff)
            scatter_rng.shuffle(scatter_indices)
            scatter_rank = [0.0] * n
            for scatter_pos, scatter_idx in enumerate(scatter_indices):
                scatter_rank[scatter_idx] = float(scatter_pos) / max(1.0, n - 1.0)
            static = []
            for i, ch in enumerate(row.text):
                item = meta[i] if i < len(meta) else None
                if item is None:
                    static.append(None); continue
                if len(item) >= 6: source, left, top, lw, lh, source_ss = item[:6]
                else: source, left, top, lw, lh = item[:5]; source_ss = 1.0
                br = row._glyph_cache_bounds[i] if i < len(row._glyph_cache_bounds) else QRectF(fm.boundingRect(ch))
                cursor = float(emphasis_offsets[i]) if i < len(emphasis_offsets) else 0.0
                geom_norm = (raw_centers[i] - min_center) / span if i < len(raw_centers) else (float(i) / max(1.0, n - 1.0))
                per_char_order = float(scatter_rank[i]) if i < len(scatter_rank) else 0.0
                base_scale = max(1.0, min(float(AUDIO_EMPHASIS_ABSOLUTE_MAX_SCALE), float(row.glyph_scales[i]) if i < len(row.glyph_scales) else 1.0))
                static.append((QRectF(source), float(left), float(top), float(lw), float(lh), max(1.0, float(source_ss or 1.0)), float(advances[i]), cursor, QRectF(br), float(geom_norm), float(per_char_order), float(base_scale)))
            cached = (layout_key, th, cos_angle, sin_angle, static); row._h51_exit_layout_cache = cached
        _layout_key, th, cos_angle, sin_angle, static = cached
        fragments = []; p = max(0.0, min(1.0, float(progress)))
        wrap_enabled = bool(getattr(row, 'horizontal_wrap', False) and int(getattr(row, 'screen_width', 0) or 0) > 1)
        viewport_h = painter.viewport().height() if wrap_enabled else 0
        for i, item in enumerate(static):
            if item is None: continue
            source, left, top, lw, lh, source_ss, cw, cursor, br, geom_norm, per_char_order, base_scale = item
            if LIVE_HISTORY_DRAW_ENABLED and i < len(row.char_shakes):
                sx = float(row.char_shakes[i].get('x', 0) or 0); sy = float(row.char_shakes[i].get('y', 0) or 0)
            else:
                sx = sy = 0.0
            ox = cursor * cos_angle; oy = cursor * sin_angle
            if wrap_enabled:
                # H69 invariant remains authoritative: shake/flavor motion is visual only and
                # cannot choose the wrap period near a screen edge.
                local_rect = QRectF(ox + float(br.left()), oy + th / 3.0 + float(br.top()), max(cw, float(br.width()), 1.0), max(float(br.height()), 1.0))
                dx, dy, _ = _device_space_staggered_wrap_adjust(painter, local_rect, row.screen_width, viewport_h, th)
                ox += dx; oy += dy
            draw_x = float(ox + sx + left); draw_y = float(oy + sy + top)
            ghost_opacity = 0.0; ghost_shift_x = 0.0; ghost_shift_y = 0.0
            ghost2_opacity = 0.0; ghost2_shift_x = 0.0
            rotation = 0.0
            if effect == 'per_char':
                jitter = (_h70_seed_unit(row, i, 17) - 0.5) * 0.32 * flavor
                window = max(0.27, 0.42 - 0.12 * flavor)
                order_span = 0.58 - 0.08 * flavor
                start = max(0.0, min(1.0 - window, per_char_order * order_span + jitter))
                lp = max(0.0, min(1.0, (p - start) / window))
                ease = _h51_smoothstep(lp); opacity = 1.0 - ease
                theta = _h70_seed_unit(row, i, 29) * math.pi * 2.0
                drift = (float(H71_PER_CHAR_DRIFT_BASE_PX) + float(H71_PER_CHAR_DRIFT_GAIN_PX) * flavor) * flavor * (ease ** 1.12)
                shift_x = math.cos(theta) * drift
                shift_y = float(H71_PER_CHAR_VERTICAL_BASE_PX) * ease + math.sin(theta) * drift * 0.86
                local_scale = 1.0 - (0.07 + 0.10 * flavor) * ease
                rotation = (_h70_seed_unit(row, i, 43) - 0.5) * 2.0 * float(H71_PER_CHAR_ROT_MAX_DEG) * flavor * ease
                # A very faint echo makes the high end visibly "fragmented" without turning
                # the effect into an explosion; it vanishes with the local glyph interval.
                ghost_opacity = max(0.0, 0.10 * flavor * math.sin(math.pi * lp))
                ghost_shift_x = -math.cos(theta) * (7.0 + 13.0 * flavor)
                ghost_shift_y = -math.sin(theta) * (5.0 + 9.0 * flavor)
            else:
                order = geom_norm if effect == 'wipe_ltr' else 1.0 - geom_norm
                start_span = 0.54 - 0.10 * flavor
                fade_span = 0.46 + 0.12 * flavor
                start = order * start_span
                lp = max(0.0, min(1.0, (p - start) / max(0.08, fade_span)))
                ease = _h51_smoothstep(lp); opacity = 1.0 - ease
                direction = 1.0 if effect == 'wipe_ltr' else -1.0
                shift_x = (7.0 + 9.0 * flavor) * direction * ease; shift_y = 0.0
                local_scale = 1.0 - (0.035 + 0.025 * flavor) * ease
                envelope = max(0.0, math.sin(math.pi * lp))
                ghost_opacity = float(H71_WIPE_GHOST_MAX_ALPHA) * flavor * envelope
                ghost_shift_x = -direction * (float(H71_WIPE_GHOST_SHIFT_BASE_PX) + float(H71_WIPE_GHOST_SHIFT_GAIN_PX) * flavor)
                ghost2_opacity = float(H71_WIPE_SECOND_GHOST_MAX_ALPHA) * flavor * envelope
                ghost2_shift_x = ghost_shift_x * float(H71_WIPE_SECOND_GHOST_MULT)
            if opacity <= 0.002 and ghost_opacity <= 0.002 and ghost2_opacity <= 0.002:
                continue
            scale = base_scale * local_scale
            anchor_x = draw_x + lw * 0.5; anchor_y = draw_y + lh * 0.82
            scaled_left = anchor_x + (draw_x - anchor_x) * scale + shift_x
            scaled_top = anchor_y + (draw_y - anchor_y) * scale + shift_y
            scaled_w = lw * scale; scaled_h = lh * scale
            center = QPointF(scaled_left + scaled_w * 0.5, scaled_top + scaled_h * 0.5)
            fragment_scale = float(scale) / source_ss
            if ghost2_opacity > 0.002:
                ghost2_center = QPointF(center.x() + ghost2_shift_x, center.y())
                fragments.append(QPainter.PixmapFragment.create(ghost2_center, source, fragment_scale * 1.025, fragment_scale * 1.025, 0.0, min(0.34, ghost2_opacity)))
            if ghost_opacity > 0.002:
                ghost_center = QPointF(center.x() + ghost_shift_x, center.y() + ghost_shift_y)
                fragments.append(QPainter.PixmapFragment.create(ghost_center, source, fragment_scale * 1.012, fragment_scale * 1.012, rotation * 0.45, min(0.42, ghost_opacity)))
            if opacity > 0.002:
                fragments.append(QPainter.PixmapFragment.create(center, source, fragment_scale, fragment_scale, rotation, max(0.0, min(1.0, opacity))))
        if not fragments:
            return True
        painter.setOpacity(1.0); painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        painter.drawPixmapFragments(fragments, sheet)
        return True
    except Exception as exc:
        try: write_error_log('H71高可感知专属风味片段绘制回退', exc, detail=f'effect={effect}')
        except Exception: pass
        return _h71_fragment_draw_pre(row, painter, effect, progress) if callable(_h71_fragment_draw_pre) else False


def _h71_fading_draw(row, painter):
    effect = _h70_effect_key(getattr(row, 'exit_effect', 'fade'))
    raw_flavor = _h70_row_flavor(row)
    if raw_flavor <= 0.0001 or effect in ('fade', 'per_char', 'wipe_ltr', 'wipe_rtl', 'instant'):
        return _h71_fading_draw_pre(row, painter) if callable(_h71_fading_draw_pre) else None
    presence = _h71_presence(raw_flavor)
    p = max(0.0, min(1.0, float(getattr(row, '_h16_exit_progress', 0.0) or 0.0)))
    if effect == 'hop_drop':
        p = max(0.0, min(1.0, float(getattr(row, '_h59_hop_progress', p) or p)))
    elif effect == 'blur_decay':
        try: p = max(0.0, min(1.0, float(_h62_decay_progress(row))))
        except Exception: p = max(0.0, min(1.0, float(getattr(row, '_h62_decay_progress', p) or p)))
    painter.save()
    try:
        if effect == 'shrink':
            q = max(0.0, min(1.0, p / 0.34))
            extra = float(H71_SHRINK_EXTRA_PRETENSION) * presence * math.sin(math.pi * q) if p < 0.34 else 0.0
            if extra > 0.0001:
                painter.translate(float(row.x), float(row.y)); painter.scale(1.0 + extra, 1.0 + extra); painter.translate(-float(row.x), -float(row.y))
        elif effect == 'soft_drift':
            gravity = float(H71_SOFT_EXTRA_GRAVITY_PX) * presence * (p ** 1.80)
            painter.translate(0.0, gravity)
        elif effect == 'hop_drop':
            apex = 0.30
            if p <= apex:
                q = p / apex; extra_y = -float(H71_HOP_EXTRA_UP_PX) * presence * math.sin(q * math.pi * 0.5)
            else:
                q = (p - apex) / max(0.001, 1.0 - apex)
                extra_y = -float(H71_HOP_EXTRA_UP_PX) * presence * (1.0 - q) + float(H71_HOP_EXTRA_DROP_PX) * presence * (q * q)
            painter.translate(0.0, extra_y)
            sign = -1.0 if _h70_seed_unit(row, 0, 97) < 0.5 else 1.0
            rot = sign * float(H71_HOP_EXTRA_ROT_DEG) * presence * math.sin(math.pi * p)
            if abs(rot) > 0.01:
                painter.translate(float(row.x), float(row.y)); painter.rotate(rot); painter.translate(-float(row.x), -float(row.y))
        elif effect == 'blur_decay':
            eased = _h51_smoothstep(p) if '_h51_smoothstep' in globals() else p
            expansion = 1.0 + float(H71_BLUR_EXTRA_EXPAND) * presence * eased
            painter.translate(float(row.x), float(row.y)); painter.scale(expansion, expansion); painter.translate(-float(row.x), -float(row.y))
        return _h71_fading_draw_pre(row, painter) if callable(_h71_fading_draw_pre) else None
    finally:
        painter.restore()


def _h71_make_history_line(window, text):
    row = _h71_make_history_pre(window, text) if callable(_h71_make_history_pre) else None
    try:
        if row is not None:
            effect = _h70_effect_key(getattr(row, 'exit_effect', 'fade'))
            flavor = _h70_row_flavor(row)
            if flavor > 0.0001 and effect in ('per_char', 'wipe_ltr', 'wipe_rtl') and getattr(row, '_shared_fragment_atlas', None) is None:
                schedule = globals().get('_h61_schedule_row_atlas')
                state = schedule(window, str(getattr(row, 'text', text) or '')) if callable(schedule) else 'unavailable'
                row._h71_fragment_prewarm_state = str(state or '')
                if state == 'scheduled':
                    try: write_error_log('H71专属风味片段材质预热', detail=f'effect={effect} | flavor={int(round(flavor*100))}% | gui_build=0')
                    except Exception: pass
    except Exception:
        pass
    return row


def _h71_sync_profile_ui(panel):
    if callable(_h71_sync_profile_ui_pre):
        _h71_sync_profile_ui_pre(panel)
    try:
        effect = _h70_effect_key(panel.h12_exit_combo.currentData() if hasattr(panel, 'h12_exit_combo') else getattr(panel.lyric_window, 'exit_effect', 'fade'))
        visible = effect != 'instant'
        # Direct disappear owns no animation lifecycle. Hide the two profile rows completely
        # instead of leaving disabled sliders and an "无" pseudo-setting in the card.
        for name in ('h70_exit_speed_name', 'h70_exit_speed_slider', 'h70_exit_speed_value',
                     'h70_exit_flavor_name', 'h70_exit_flavor_slider', 'h70_exit_flavor_value'):
            w = getattr(panel, name, None)
            if w is not None:
                w.setVisible(visible)
        slider = getattr(panel, 'h70_exit_speed_slider', None)
        card = slider.parentWidget() if slider is not None else None
        if card is not None:
            for label in card.findChildren(QLabel):
                text = str(label.text() or '')
                if text.startswith('每种退场会记住自己的速度') or text.startswith('直接消失命中后立即移除'):
                    label.setText(
                        '每种退场会记住自己的速度与专属风味；50% 应明显可见，100% 是清楚的另一种性格。' if visible
                        else '直接消失命中后立即移除，不存在退场速度或专属风味设置。'
                    )
    except Exception:
        pass


def _h71_activate_runtime():
    try:
        if callable(_h71_fragment_draw_pre):
            globals()['_h51_fragment_exit_draw'] = _h71_fragment_exit_draw
            _h51_fragment_exit_draw._limbus_layer = 'H71'
            _h51_fragment_exit_draw._limbus_policy = 'stronger effect-native presence; flavor zero delegates H70/H51; stable edge-wrap topology retained'
        if 'FadingLine' in globals() and callable(_h71_fading_draw_pre):
            FadingLine.draw = _h71_fading_draw
            FadingLine.draw._limbus_layer = 'H71'
            FadingLine.draw._limbus_policy = 'amplitude-only flavor reinforcement; no duration or deadline ownership'
        if 'LyricWindow' in globals() and callable(_h71_make_history_pre):
            LyricWindow._make_history_line = _h71_make_history_line
            LyricWindow._make_history_line._limbus_layer = 'H71'
            LyricWindow._make_history_line._limbus_policy = 'async fragment-material prewarm for enabled per-char/wipe flavors'
        if callable(_h71_sync_profile_ui_pre):
            globals()['_h70_sync_profile_ui'] = _h71_sync_profile_ui
            _h70_sync_profile_ui._limbus_layer = 'H71'
            _h70_sync_profile_ui._limbus_policy = 'instant hides parameter rows; animated effects retain per-effect remembered controls'
    except Exception as exc:
        try: write_error_log('H71专属风味可感知度与直接消失界面收口安装失败', exc)
        except Exception: pass


if '_h71_activate_runtime' in globals():
    _h71_activate_runtime()


# H72 exit lifecycle + dirty-region closure ------------------------------------
# H71 intentionally made effect-native flavor motion large enough to read at desktop scale.
# That exposed two independent lifecycle assumptions which had been safe only while motion stayed
# close to the original glyph box:
#   1) sparse dirty-region accounting knew the mature row/fragment bounds, but not H70/H71's
#      optional secondary translations/ghosts/scales. A row could retire correctly while pixels
#      drawn outside the registered region survived in the translucent backing store as a lone
#      "ghost glyph";
#   2) H68's capacity horizon used monotonic residence age. Playback pauses therefore consumed a
#      future lyric deadline even though the song clock was frozen. If capacity eviction did not
#      arrive when that wall-clock horizon reached zero, active blur progress parked at 0.939 --
#      intentionally short of release -- and could remain faintly visible for a long time. Rows near
#      the end of the timeline may have no future capacity eviction at all.
# H72 closes both contracts without changing H70/H71 artistic amplitudes or user speed semantics.
# Dirty accounting reserves the complete optional-motion envelope and explicitly invalidates that
# envelope on retirement. Exact H68 horizons are measured against the already-sampled playback
# position, so pause/seek behavior follows the media clock. Tail rows which can never be capacity-
# evicted return to H62's natural hold progression, also driven by playback position. Finally, a
# generous hard lifetime watchdog exists only for pathological fading rows which fail to terminate.
H72_EXIT_HARD_MAX_MS = 15000.0
H72_DIRTY_SAFETY_PX = 16.0
H72_PER_CHAR_EXTRA_PAD_PX = 112.0
H72_WIPE_EXTRA_X_PX = 96.0
H72_WIPE_EXTRA_Y_PX = 36.0
H72_FALLBACK_FORCE_FULL_ON_EMPTY = True
H72_ORPHAN_LOG_MS = 1800.0
H72_RELEASE_EPS = 0.002

_h72_held_region_pre = getattr(LyricWindow, '_held_visual_region', None) if 'LyricWindow' in globals() else None
_h72_fading_begin_pre = getattr(FadingLine, 'begin_fade', None) if 'FadingLine' in globals() else None
_h72_fading_update_pre = getattr(FadingLine, 'update', None) if 'FadingLine' in globals() else None
_h72_plan_pre = globals().get('_h68_plan_for_row')
_h72_decay_progress_pre = globals().get('_h62_decay_progress')
_h72_h68_integrator_pre = globals().get('_h69_h68_progress_pre')
_h72_discard_fading_pre = getattr(LyricWindow, '_discard_fading_item', None) if 'LyricWindow' in globals() else None


def _h72_owner_window(row):
    for attr in ('_h62_owner_ref', '_h55_owner_window_ref'):
        try:
            ref = getattr(row, attr, None)
            window = ref() if callable(ref) else None
            if window is not None:
                return window
        except Exception:
            pass
    return None


def _h72_region_rects(region):
    try:
        return list(region.rects())
    except Exception:
        try:
            br = region.boundingRect()
            return [] if br.isEmpty() else [br]
        except Exception:
            return []


def _h72_expand_region(window, region, left, top, right, bottom):
    try:
        if region is None or region.isEmpty():
            return QRegion()
        out = QRegion()
        clip = window.rect()
        li = max(0, int(math.ceil(float(left)))); ti = max(0, int(math.ceil(float(top))))
        ri = max(0, int(math.ceil(float(right)))); bi = max(0, int(math.ceil(float(bottom))))
        for rr in _h72_region_rects(region):
            grown = rr.adjusted(-li, -ti, ri, bi).intersected(clip)
            if not grown.isEmpty():
                out = out.united(QRegion(grown))
        return out
    except Exception:
        return region if region is not None else QRegion()


def _h72_flavor_dirty_padding(item, region):
    """Return device-space padding for the maximum H70/H71 optional-motion envelope."""
    try:
        effect = _h70_effect_key(getattr(item, 'exit_effect', 'fade'))
        raw = max(0.0, min(1.0, float(_h70_row_flavor(item))))
    except Exception:
        return (0.0, 0.0, 0.0, 0.0)
    if raw <= 0.0001 or effect == 'instant':
        return (0.0, 0.0, 0.0, 0.0)
    try:
        presence = float(_h71_presence(raw)) if '_h71_presence' in globals() else raw
    except Exception:
        presence = raw
    safety = float(H72_DIRTY_SAFETY_PX)
    if effect == 'fade':
        rise = float(globals().get('H70_FADE_RISE_MAX_PX', 120.0) or 120.0) * raw
        return (safety, rise + safety, safety, safety)
    if effect == 'per_char':
        return (float(H72_PER_CHAR_EXTRA_PAD_PX), float(H72_PER_CHAR_EXTRA_PAD_PX),
                float(H72_PER_CHAR_EXTRA_PAD_PX), float(H72_PER_CHAR_EXTRA_PAD_PX))
    if effect in ('wipe_ltr', 'wipe_rtl'):
        return (float(H72_WIPE_EXTRA_X_PX), float(H72_WIPE_EXTRA_Y_PX),
                float(H72_WIPE_EXTRA_X_PX), float(H72_WIPE_EXTRA_Y_PX))
    try:
        br = region.boundingRect()
        rw = max(1.0, float(br.width())); rh = max(1.0, float(br.height()))
    except Exception:
        rw = 480.0; rh = 120.0
    if effect == 'shrink':
        extra_scale = (
            float(globals().get('H70_SHRINK_PRETENSION_MAX', 0.055) or 0.055) * raw +
            float(globals().get('H71_SHRINK_EXTRA_PRETENSION', 0.070) or 0.070) * presence
        )
        px = safety + rw * extra_scale * 0.62
        py = safety + rh * extra_scale * 0.75
        return (px, py, px, py)
    if effect == 'soft_drift':
        down = (
            float(globals().get('H70_SOFT_GRAVITY_EXTRA_PX', 42.0) or 42.0) * raw +
            float(globals().get('H71_SOFT_EXTRA_GRAVITY_PX', 58.0) or 58.0) * presence
        )
        return (safety, safety, safety, down + safety)
    if effect == 'hop_drop':
        up = (
            float(globals().get('H70_HOP_EXTRA_UP_PX', 20.0) or 20.0) * raw +
            float(globals().get('H71_HOP_EXTRA_UP_PX', 26.0) or 26.0) * presence
        )
        down = (
            float(globals().get('H70_HOP_EXTRA_DROP_PX', 34.0) or 34.0) * raw +
            float(globals().get('H71_HOP_EXTRA_DROP_PX', 48.0) or 48.0) * presence
        )
        # H59 already reserves its base -24..+48 px path. This is only the optional H70/H71 tail.
        return (safety + 18.0, up + safety, safety + 18.0, down + safety)
    if effect == 'blur_decay':
        expand = (
            float(globals().get('H70_BLUR_DEPTH_EXPAND_MAX', 0.035) or 0.035) * raw +
            float(globals().get('H71_BLUR_EXTRA_EXPAND', 0.060) or 0.060) * presence
        )
        px = safety + rw * expand * 0.58
        py = safety + rh * expand * 0.70
        return (px, py, px, py)
    return (safety, safety, safety, safety)


def _h72_held_visual_region(window, item):
    base = _h72_held_region_pre(window, item) if callable(_h72_held_region_pre) else QRegion()
    try:
        pad = _h72_flavor_dirty_padding(item, base)
        expanded = _h72_expand_region(window, base, *pad) if any(float(x) > 0.0 for x in pad) else base
        previous = getattr(item, '_h72_last_dirty_region', None)
        if expanded is not None and not expanded.isEmpty():
            item._h72_last_dirty_region = QRegion(expanded)
            return expanded
        if previous is not None and not previous.isEmpty():
            # Preserve the previous visible envelope for one terminal clear even if alpha has
            # already crossed the mature held-region cutoff before update_fading removes the row.
            return QRegion(previous)
        return expanded
    except Exception:
        return base


def _h72_h68_playback_integrator(row, now_mono=None):
    """Feed H68 active progress with media-clock elapsed time rather than pause-running wall time."""
    if not callable(_h72_h68_integrator_pre):
        return 0.0
    now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
    try:
        if _h66_is_blur_decay_row(row) and float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) <= 0.0:
            window = _h72_owner_window(row)
            if window is not None:
                pos_raw = getattr(window, '_last_position_ms', None)
                if pos_raw is not None:
                    pos = float(pos_raw)
                    last_pos_raw = getattr(row, '_h72_last_playback_pos_ms', None)
                    last_pos = pos if last_pos_raw is None else float(last_pos_raw)
                    delta = max(0.0, pos - last_pos)
                    # A large media discontinuity is handled by the existing seek/epoch reset paths;
                    # do not turn one stale/seek sample into seconds of blur integration here.
                    delta = min(delta, 1200.0)
                    row._h72_last_playback_pos_ms = pos
                    if bool(getattr(row, '_h68_deadline_active', False)):
                        row._h68_last_mono = now - delta
                    else:
                        row._h68_last_mono = now
                    row._h72_progress_clock = 'playback-position'
    except Exception:
        pass
    return _h72_h68_integrator_pre(row, now)


def _h72_h68_plan_for_row(window, row, capacity, now=None):
    if not callable(_h72_plan_pre):
        return (0.0, 720.0, 0, 0.0)
    remaining, tail, evict, full = _h72_plan_pre(window, row, capacity, now)
    try:
        if not _h66_is_blur_decay_row(row):
            return float(remaining), float(tail), int(evict), float(full)
        origin_raw = getattr(row, '_h68_origin_line_index', -1)
        origin = int(origin_raw if origin_raw is not None else -1)
        exact, exact_evict = _h68_exact_horizon_ms(window, origin, capacity)
        pos = getattr(window, '_last_position_ms', None)
        if exact is not None and exact_evict is not None and pos is not None:
            evict_start = _h68_timeline_start(window, int(exact_evict))
            if evict_start is not None:
                remaining = max(0.0, float(evict_start) - float(pos))
                full = float(exact)
                evict = int(exact_evict)
                row._h72_deadline_clock = 'playback-position'
    except Exception:
        pass
    return float(remaining), float(tail), int(evict), float(full)


def _h72_orphan_blur_progress(row, candidate, now_mono=None):
    """Naturally retire tail history rows which have no possible future capacity eviction."""
    if not _h66_is_blur_decay_row(row):
        return candidate
    if float(getattr(row, '_h62_decay_release_mono', 0.0) or 0.0) > 0.0:
        return candidate
    window = _h72_owner_window(row)
    if window is None:
        return candidate
    try:
        history = list(getattr(window, 'history_lines', []) or [])
        if not any(x is row for x in history):
            return candidate
        capacity = max(1, min(6, int(getattr(window, 'max_visible_subtitles', 1) or 1)))
        origin_raw = getattr(row, '_h68_origin_line_index', -1)
        origin = int(origin_raw if origin_raw is not None else -1)
        exact, _evict = _h68_exact_horizon_ms(window, origin, capacity)
        if exact is not None:
            return candidate
        entry_start = _h68_timeline_start(window, origin + 1)
        pos = getattr(window, '_last_position_ms', None)
        if entry_start is None or pos is None:
            return candidate
        hold_ms, _release_ms = _h62_decay_durations(row)
        natural = max(0.0, min(1.0, (float(pos) - float(entry_start)) / max(1.0, float(hold_ms))))
        result = max(float(candidate), float(natural),
                     max(0.0, min(1.0, float(getattr(row, '_h69_optical_progress_floor', 0.0) or 0.0))))
        row._h69_optical_progress_floor = result
        row._h65_capacity_progress = max(float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0), result)
        if result >= 0.9995:
            row._h62_decay_expired = True
        if natural > float(candidate) + 0.015:
            now = time.monotonic() * 1000.0 if now_mono is None else float(now_mono)
            last = float(getattr(window, '_h72_last_orphan_log_mono', 0.0) or 0.0)
            if now - last >= float(H72_ORPHAN_LOG_MS):
                window._h72_last_orphan_log_mono = now
                try:
                    write_error_log('H72尾段失焦自然退休', detail=(
                        f'origin={origin} | position={int(float(pos))}ms | entry={int(float(entry_start))}ms | '
                        f'hold={float(hold_ms):.0f}ms | progress={result:.3f} | capacity_evict=none | clock=playback'))
                except Exception:
                    pass
        return max(0.0, min(1.0, result))
    except Exception:
        return candidate


def _h72_decay_progress(row, now_mono=None):
    candidate = float(_h72_decay_progress_pre(row, now_mono)) if callable(_h72_decay_progress_pre) else 0.0
    return _h72_orphan_blur_progress(row, max(0.0, min(1.0, candidate)), now_mono)


def _h72_begin_fade(row):
    now = time.monotonic() * 1000.0
    try:
        floor_before = max(
            float(getattr(row, '_h69_optical_progress_floor', 0.0) or 0.0),
            float(getattr(row, '_h65_capacity_progress', 0.0) or 0.0),
            float(getattr(row, '_h62_decay_progress', 0.0) or 0.0),
        ) if _h66_is_blur_decay_row(row) else 0.0
    except Exception:
        floor_before = 0.0
    out = _h72_fading_begin_pre(row) if callable(_h72_fading_begin_pre) else None
    row._h72_exit_begin_mono = now
    row._h72_exit_forced_retire = False
    try:
        if _h66_is_blur_decay_row(row):
            existing = max(0.0, min(1.0, float(getattr(row, '_h62_decay_release_progress', 0.0) or 0.0)))
            corrected = max(existing, max(0.0, min(1.0, floor_before)))
            if corrected > existing + float(H72_RELEASE_EPS):
                row._h62_decay_release_progress = corrected
                row._h62_decay_progress = corrected
                row._h69_optical_progress_floor = max(
                    float(getattr(row, '_h69_optical_progress_floor', 0.0) or 0.0), corrected)
                row._h68_release_progress_last = corrected
                row._h68_release_duration_ms = 0.0
                try:
                    write_error_log('H72失焦退场交接连续性修正', detail=(
                        f'before={existing:.3f} | floor={floor_before:.3f} | release={corrected:.3f}'))
                except Exception:
                    pass
    except Exception:
        pass
    return out


def _h72_fading_update(row):
    now = time.monotonic() * 1000.0
    started = float(getattr(row, '_h72_exit_begin_mono', 0.0) or 0.0)
    if started <= 0.0:
        started = now
        row._h72_exit_begin_mono = now
    window = _h72_owner_window(row)
    retire_region = QRegion()
    if window is not None:
        try:
            retire_region = _h72_held_visual_region(window, row)
        except Exception:
            retire_region = QRegion()
    try:
        alive = bool(_h72_fading_update_pre(row)) if callable(_h72_fading_update_pre) else False
    except Exception as exc:
        alive = False
        try: write_error_log('H72退场更新异常强制回收', exc, detail=f'effect={getattr(row,"exit_effect","")}')
        except Exception: pass
    effect = _h70_effect_key(getattr(row, 'exit_effect', 'fade')) if '_h70_effect_key' in globals() else str(getattr(row, 'exit_effect', 'fade') or 'fade')
    if alive and effect != 'instant' and now - started > float(H72_EXIT_HARD_MAX_MS):
        alive = False
        row._h72_exit_forced_retire = True
        try: row.release_render_resources()
        except Exception: pass
        try:
            write_error_log('H72退场生命周期硬保险', detail=(
                f'effect={effect} | age={now-started:.0f}ms | limit={H72_EXIT_HARD_MAX_MS:.0f}ms | action=retire'))
        except Exception:
            pass
    if not alive and window is not None:
        try:
            prior = getattr(row, '_h72_last_dirty_region', None)
            if prior is not None and not prior.isEmpty():
                retire_region = retire_region.united(QRegion(prior)) if not retire_region.isEmpty() else QRegion(prior)
            pending = getattr(window, '_pending_explicit_region', QRegion())
            if retire_region is not None and not retire_region.isEmpty():
                window._pending_explicit_region = pending.united(retire_region)
            elif bool(H72_FALLBACK_FORCE_FULL_ON_EMPTY) and float(_h70_row_flavor(row) if '_h70_row_flavor' in globals() else 0.0) > 0.0001:
                window._render_force_full = True
        except Exception:
            pass
    return alive


def _h72_discard_fading_item(item):
    """Direct pressure/burst retirement must invalidate the same expanded envelope as natural retirement."""
    window = _h72_owner_window(item)
    retire_region = QRegion()
    if window is not None:
        try:
            retire_region = _h72_held_visual_region(window, item)
            prior = getattr(item, '_h72_last_dirty_region', None)
            if prior is not None and not prior.isEmpty():
                retire_region = retire_region.united(QRegion(prior)) if not retire_region.isEmpty() else QRegion(prior)
        except Exception:
            retire_region = QRegion()
    try:
        if callable(_h72_discard_fading_pre):
            _h72_discard_fading_pre(item)
        else:
            item.release_render_resources()
    finally:
        if window is not None:
            try:
                pending = getattr(window, '_pending_explicit_region', QRegion())
                if retire_region is not None and not retire_region.isEmpty():
                    window._pending_explicit_region = pending.united(retire_region)
                elif bool(H72_FALLBACK_FORCE_FULL_ON_EMPTY) and float(_h70_row_flavor(item) if '_h70_row_flavor' in globals() else 0.0) > 0.0001:
                    window._render_force_full = True
            except Exception:
                pass


def _h72_activate_runtime():
    global _h68_plan_for_row, _h62_decay_progress, _h69_h68_progress_pre
    try:
        if callable(_h72_h68_integrator_pre):
            _h69_h68_progress_pre = _h72_h68_playback_integrator
            _h69_h68_progress_pre._limbus_layer = 'H72'
            _h69_h68_progress_pre._limbus_policy = 'H68 active integration elapsed follows sampled playback delta; pause consumes zero progress'
        if callable(_h72_plan_pre):
            _h68_plan_for_row = _h72_h68_plan_for_row
            _h68_plan_for_row._limbus_layer = 'H72'
            _h68_plan_for_row._limbus_policy = 'exact capacity horizon follows sampled playback position; pause does not consume deadline'
        if callable(_h72_decay_progress_pre):
            _h62_decay_progress = _h72_decay_progress
            _h62_decay_progress._limbus_layer = 'H72'
            _h62_decay_progress._limbus_policy = 'H69 monotonic optical floor plus playback-clock natural retirement when no capacity eviction exists'
        if 'LyricWindow' in globals() and callable(_h72_held_region_pre):
            LyricWindow._held_visual_region = _h72_held_visual_region
            LyricWindow._held_visual_region._limbus_layer = 'H72'
            LyricWindow._held_visual_region._limbus_policy = 'effect-native flavor motion envelope participates in sparse dirty-region cleanup'
        if 'LyricWindow' in globals() and callable(_h72_discard_fading_pre):
            LyricWindow._discard_fading_item = staticmethod(_h72_discard_fading_item)
            LyricWindow._discard_fading_item._limbus_layer = 'H72'
            LyricWindow._discard_fading_item._limbus_policy = 'direct pressure/burst retirement invalidates expanded flavor envelope before releasing resources'
        if 'FadingLine' in globals():
            if callable(_h72_fading_begin_pre):
                FadingLine.begin_fade = _h72_begin_fade
                FadingLine.begin_fade._limbus_layer = 'H72'
                FadingLine.begin_fade._limbus_policy = 'snapshot monotonic blur floor across history-to-fading membership handoff'
            if callable(_h72_fading_update_pre):
                FadingLine.update = _h72_fading_update
                FadingLine.update._limbus_layer = 'H72'
                FadingLine.update._limbus_policy = 'explicit dirty-envelope retirement plus pathological 15s terminal watchdog'
    except Exception as exc:
        try: write_error_log('H72退场生命周期与脏区闭环安装失败', exc)
        except Exception: pass


if '_h72_activate_runtime' in globals():
    _h72_activate_runtime()

# H73 editorial instrument UI --------------------------------------------------
# Presentation-only front-end refinement. H73 deliberately leaves playback, provider,
# seek, lyric timing and overlay renderer ownership untouched. The visual language is
# informed by the MIT-licensed Tabler Icons 24px outline system, but the tiny runtime icons
# below are drawn directly with Qt primitives so frozen builds do not gain an SVG/plugin or
# extra-file dependency. See THIRD_PARTY_UI_ICONS_H73.md for attribution and scope.
H73_UI_ICON_STROKE = 1.55
H73_NAV_ORDER = (0, 1, 2, 4, 3)
H73_PAGE_META = (
    ('播放', '播放器、歌词来源与当前播放状态'),
    ('外观', '字体、颜色、描边、辉光与视觉预设'),
    ('动效', '入场、退场、字符运动与表现参数'),
    ('设置', '应用行为、背景、输出与高级视觉选项'),
    ('单曲', '按歌曲与播放器覆盖全局视觉样式'),
)


def _h73_icon(name, size=18, color='#aaa3a2'):
    """Return a crisp dependency-free outline QIcon on a 24x24 design grid."""
    size = max(12, int(size or 18))
    pm = QPixmap(size, size)
    pm.fill(Qt.transparent)
    p = QPainter(pm)
    try:
        p.setRenderHint(QPainter.Antialiasing, True)
        scale = float(size) / 24.0
        pen = QPen(QColor(color), max(1.0, float(H73_UI_ICON_STROKE) * scale), Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)
        p.setPen(pen)
        p.setBrush(Qt.NoBrush)
        def pt(x, y): return QPointF(float(x) * scale, float(y) * scale)
        def line(x1, y1, x2, y2): p.drawLine(pt(x1, y1), pt(x2, y2))
        def rect(x, y, w, h, r=0.0):
            rr = QRectF(float(x)*scale, float(y)*scale, float(w)*scale, float(h)*scale)
            if r: p.drawRoundedRect(rr, float(r)*scale, float(r)*scale)
            else: p.drawRect(rr)
        def ellipse(x, y, w, h):
            p.drawEllipse(QRectF(float(x)*scale, float(y)*scale, float(w)*scale, float(h)*scale))
        key = str(name or '').strip().lower()
        if key == 'minus':
            line(6, 12, 18, 12)
        elif key == 'square':
            rect(6, 6, 12, 12, 1.1)
        elif key == 'restore':
            rect(5.5, 8, 10.5, 10.5, 1.0); rect(8, 5.5, 10.5, 10.5, 1.0)
        elif key == 'x':
            line(7, 7, 17, 17); line(17, 7, 7, 17)
        elif key == 'search':
            ellipse(5, 5, 10, 10); line(14.5, 14.5, 19, 19)
        elif key == 'music':
            line(9, 6, 9, 16); line(9, 7, 18, 5); line(18, 5, 18, 14)
            ellipse(5.2, 15, 3.8, 2.8); ellipse(14.2, 13, 3.8, 2.8)
        elif key == 'type':
            line(5, 6, 19, 6); line(12, 6, 12, 18); line(8.5, 18, 15.5, 18)
        elif key == 'sparkles':
            line(8, 4.8, 8, 11.2); line(4.8, 8, 11.2, 8)
            line(16.5, 11.5, 16.5, 19.5); line(12.5, 15.5, 20.5, 15.5)
            line(18.5, 4.5, 18.5, 7.5); line(17, 6, 20, 6)
        elif key == 'disc':
            ellipse(4, 4, 16, 16); ellipse(9.5, 9.5, 5, 5); ellipse(11.2, 11.2, 1.6, 1.6)
        elif key == 'sliders':
            line(5, 7, 19, 7); line(5, 12, 19, 12); line(5, 17, 19, 17)
            ellipse(8.2, 5.2, 3.6, 3.6); ellipse(14.2, 10.2, 3.6, 3.6); ellipse(6.2, 15.2, 3.6, 3.6)
        elif key == 'photo-edit':
            rect(3.5, 4.5, 14.5, 13, 1.5); ellipse(6.2, 7.2, 2.6, 2.6)
            line(5.2, 15.1, 9.3, 11.1); line(9.3, 11.1, 12.0, 13.7); line(12.0, 13.7, 14.2, 11.7)
            line(13.7, 18.6, 19.2, 13.1); line(16.9, 12.7, 19.6, 15.4); line(13.2, 19.1, 15.2, 18.6)
        else:
            ellipse(6, 6, 12, 12)
    finally:
        p.end()
    return QIcon(pm)


def _h73_strip_generation_prefix(label):
    try:
        t = str(label.text() or '')
        cleaned = re.sub(r'^H\d+(?:F\d+)?\s*[·•]\s*', '', t).strip()
        if cleaned and cleaned != t:
            label.setText(cleaned)
            return True
    except Exception:
        pass
    return False


def _h73_show_background_popup(panel):
    """Small title-bar utility panel; full Settings-page controls remain discoverable."""
    try:
        old = getattr(panel, '_h73_background_popup', None)
        if old is not None:
            try:
                old.close(); old.deleteLater()
            except Exception:
                pass
        dlg = QDialog(panel)
        dlg.setObjectName('h73BackgroundPopup')
        dlg.setWindowFlags(Qt.Popup | Qt.FramelessWindowHint)
        dlg.setAttribute(Qt.WA_DeleteOnClose, True)
        dlg.setMinimumWidth(320)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(16, 15, 16, 14)
        lay.setSpacing(10)
        title = QLabel('界面背景')
        title.setObjectName('popupTitle')
        lay.addWidget(title)
        hint = QLabel('只改变控制面板外观，不影响桌面歌词。')
        hint.setObjectName('popupHint')
        lay.addWidget(hint)
        enabled = QCheckBox('显示自定义背景')
        enabled.setChecked(bool(panel.background_check.isChecked()))
        enabled.toggled.connect(panel.background_check.setChecked)
        lay.addWidget(enabled)
        file_row = QHBoxLayout(); file_row.setSpacing(8)
        file_label = QLabel(os.path.basename(str(getattr(panel, '_background_path', '') or '')) or '尚未选择图片')
        file_label.setObjectName('popupFile')
        file_label.setToolTip(str(getattr(panel, '_background_path', '') or ''))
        file_row.addWidget(file_label, 1)
        choose = QPushButton('选择 / 更换')
        choose.setObjectName('secondaryAction')
        def choose_bg():
            panel._choose_background_image()
            path = str(getattr(panel, '_background_path', '') or '')
            file_label.setText(os.path.basename(path) or '尚未选择图片')
            file_label.setToolTip(path)
            enabled.setChecked(bool(panel.background_check.isChecked()))
        choose.clicked.connect(choose_bg)
        file_row.addWidget(choose)
        lay.addLayout(file_row)
        strength_row = QHBoxLayout(); strength_row.setSpacing(9)
        strength_row.addWidget(QLabel('背景强度'))
        strength = QSlider(Qt.Horizontal)
        strength.setRange(10, 100)
        strength.setValue(int(panel.background_strength_slider.value()))
        strength_value = QLabel(f'{strength.value()}%')
        strength_value.setObjectName('popupValue')
        strength.valueChanged.connect(lambda v: strength_value.setText(f'{int(v)}%'))
        strength.valueChanged.connect(panel.background_strength_slider.setValue)
        strength_row.addWidget(strength, 1); strength_row.addWidget(strength_value)
        lay.addLayout(strength_row)
        blur_row = QHBoxLayout(); blur_row.setSpacing(9)
        blur_row.addWidget(QLabel('背景磨砂'))
        blur = QSlider(Qt.Horizontal)
        blur.setRange(0, 100)
        blur.setValue(int(panel.background_blur_slider.value()))
        blur_value = QLabel(f'{blur.value()}%')
        blur_value.setObjectName('popupValue')
        blur.valueChanged.connect(lambda v: blur_value.setText(f'{int(v)}%'))
        blur.valueChanged.connect(panel.background_blur_slider.setValue)
        blur_row.addWidget(blur, 1); blur_row.addWidget(blur_value)
        lay.addLayout(blur_row)
        enabled.toggled.connect(strength.setEnabled); enabled.toggled.connect(blur.setEnabled)
        strength.setEnabled(enabled.isChecked()); blur.setEnabled(enabled.isChecked())
        actions = QHBoxLayout(); actions.setSpacing(8)
        clear = QPushButton('清除背景')
        clear.setObjectName('quietAction')
        def clear_bg():
            panel._clear_background_image()
            file_label.setText('尚未选择图片'); file_label.setToolTip(''); enabled.setChecked(False)
        clear.clicked.connect(clear_bg)
        actions.addWidget(clear); actions.addStretch()
        done = QPushButton('完成')
        done.setObjectName('primaryAction')
        done.clicked.connect(dlg.close)
        actions.addWidget(done)
        lay.addLayout(actions)
        panel._h73_background_popup = dlg
        anchor = getattr(getattr(panel, 'window_title_bar', None), 'background_btn', None)
        if anchor is not None:
            gp = anchor.mapToGlobal(QPointF(0, anchor.height()).toPoint())
            dlg.adjustSize()
            x = gp.x() - max(0, dlg.width() - anchor.width())
            y = gp.y() + 5
            screen = QApplication.screenAt(gp) if hasattr(QApplication, 'screenAt') else QApplication.primaryScreen()
            if screen is not None:
                area = screen.availableGeometry()
                x = max(area.left()+6, min(x, area.right()-dlg.width()-6))
                y = max(area.top()+6, min(y, area.bottom()-dlg.height()-6))
            dlg.move(x, y)
        dlg.show(); dlg.raise_()
    except Exception as exc:
        try: write_error_log('H73界面背景快捷面板打开失败', exc)
        except Exception: pass


_h73_title_init_pre = PanelTitleBar.__init__ if 'PanelTitleBar' in globals() else None
_h73_title_sync_pre = PanelTitleBar.sync_window_state if 'PanelTitleBar' in globals() else None
_h73_panel_init_pre = ControlPanel.__init__ if 'ControlPanel' in globals() else None


def _h73_title_init(bar, host):
    _h73_title_init_pre(bar, host)
    try:
        bar.setFixedHeight(40)
        bar.build.setText('LYRIC STUDIO')
        row = bar.layout()
        bar.background_btn = QToolButton(bar)
        bar.background_btn.setObjectName('titleUtilityButton')
        bar.background_btn.setIcon(_h73_icon('photo-edit', 18, '#aaa3a2'))
        bar.background_btn.setIconSize(QSize(18, 18))
        bar.background_btn.setFixedSize(34, 30)
        bar.background_btn.setCursor(Qt.PointingHandCursor)
        bar.background_btn.setToolTip('界面背景 · 选择图片、开关与强度')
        bar.background_btn.clicked.connect(lambda: host._h73_show_background_popup())
        idx = row.indexOf(bar.min_btn)
        row.insertWidget(max(0, idx), bar.background_btn)
        base = ('QPushButton{background:transparent;border:none;border-radius:5px;padding:0;color:#aaa3a2;}'
                ' QPushButton:hover{background:rgba(255,255,255,15);color:#eee8e5;}')
        close = ('QPushButton{background:transparent;border:none;border-radius:5px;padding:0;color:#aaa3a2;}'
                 ' QPushButton:hover{background:#71303b;color:#fff6f4;}')
        for btn, icon_name in ((bar.min_btn, 'minus'), (bar.max_btn, 'square'), (bar.close_btn, 'x')):
            btn.setText(''); btn.setFixedSize(36, 30); btn.setCursor(Qt.PointingHandCursor)
            btn.setIcon(_h73_icon(icon_name, 16, '#aaa3a2')); btn.setIconSize(QSize(16, 16))
            btn.setStyleSheet(close if btn is bar.close_btn else base)
    except Exception:
        pass


def _h73_title_sync(bar):
    if callable(_h73_title_sync_pre):
        _h73_title_sync_pre(bar)
    try:
        bar.max_btn.setText('')
        bar.max_btn.setIcon(_h73_icon('restore' if bar._host.isMaximized() else 'square', 16, '#aaa3a2'))
        bar.max_btn.setIconSize(QSize(16, 16))
    except Exception:
        pass


H73_QSS = r'''
QToolButton#titleUtilityButton {
    background:transparent; border:none; border-radius:5px; padding:0px;
}
QToolButton#titleUtilityButton:hover { background:rgba(255,255,255,15); }
QDialog#h73BackgroundPopup {
    background:#121216; border:1px solid rgba(238,229,226,34); border-radius:7px;
}
QLabel#popupTitle { color:#f0e9e6; font-size:14px; font-weight:700; }
QLabel#popupHint, QLabel#popupFile { color:#817a7d; font-size:11px; }
QLabel#popupFile { padding:4px 0px; }
QLabel#popupValue { color:#cdbec1; min-width:40px; }
QPushButton#quietAction { background:transparent; border:none; color:#91898b; padding:6px 8px; }
QPushButton#quietAction:hover { color:#d6cecb; background:rgba(255,255,255,7); border-radius:5px; }
QPushButton#navButton { padding:9px 11px 10px 10px; }
QPushButton#navButton:checked { border-bottom-width:1px; }
QLabel#workspaceTitle { font-size:18px; font-weight:690; letter-spacing:0.1px; }
QLabel#workspaceDescription { color:#777174; }
QFrame#settingsCard { border-color:rgba(238,229,226,20); }
QLabel#cardTitle { font-size:13px; font-weight:680; }
QLineEdit#settingsFilter { padding-left:7px; }
'''


def _h73_panel_init(panel, *args, **kwargs):
    _h73_panel_init_pre(panel, *args, **kwargs)
    try:
        panel._h73_show_background_popup = lambda: _h73_show_background_popup(panel)
        panel._page_meta = H73_PAGE_META
        for idx, title in enumerate(('播放', '外观', '动效', '设置', '单曲')):
            try: panel.main_tabs.setTabText(idx, title)
            except Exception: pass
        icon_keys = ('music', 'type', 'sparkles', 'sliders', 'disc')
        titles = ('播放', '外观', '动效', '设置', '单曲')
        for idx, btn in enumerate(getattr(panel, '_sidebar_buttons', ())):
            if idx >= len(titles): break
            btn.setText(titles[idx])
            btn.setIcon(_h73_icon(icon_keys[idx], 14, '#91898c'))
            btn.setIconSize(QSize(14, 14))
        # Keep tab indices stable for config compatibility, but visually place creative
        # destinations before application Settings.
        nav = getattr(panel, 'top_nav', None)
        if nav is not None and nav.layout() is not None:
            lay = nav.layout()
            while lay.count():
                item = lay.takeAt(0)
                if item.spacerItem() is not None:
                    continue
            for idx in H73_NAV_ORDER:
                lay.addWidget(panel._sidebar_buttons[idx])
            lay.addStretch()
        panel._update_workspace_header(panel.main_tabs.currentIndex())
        try:
            panel.settings_filter.setPlaceholderText('搜索当前页设置…')
            panel.settings_filter.setToolTip('筛选当前页面中的设置项。')
            panel.settings_filter.addAction(_h73_icon('search', 14, '#777174'), QLineEdit.LeadingPosition)
        except Exception:
            pass
        # This switch is a renderer presentation mode, not a language selector. Preserve
        # the stored data values (chinese/english) for backwards compatibility.
        try:
            panel.mode_combo.setItemText(0, '完整字形')
            panel.mode_combo.setItemText(1, '轮廓余韵')
            panel.mode_combo.setMaximumWidth(110)
            panel.mode_combo.setToolTip('完整字形：主文字完整衰减；轮廓余韵：主字面更早淡去，让描边/辉光稍多停留。与歌词语言无关。')
            style_page = panel.main_tabs.widget(1).widget()
            for label in style_page.findChildren(QLabel):
                if str(label.text() or '').strip() == '模式：':
                    label.setText('退场质感：')
                    label.setToolTip(panel.mode_combo.toolTip())
        except Exception:
            pass
        # Generation tags belong in diagnostics, not product-facing headings.
        stripped = 0
        for label in panel.findChildren(QLabel):
            stripped += int(_h73_strip_generation_prefix(label))
        panel._h73_generation_labels_stripped = stripped
        panel._default_stylesheet = str(getattr(panel, '_default_stylesheet', '') or '') + H73_QSS
        panel._limbus_stylesheet = str(getattr(panel, '_limbus_stylesheet', '') or '') + H73_QSS
        current_theme = panel._current_ui_theme() if hasattr(panel, '_current_ui_theme') else 'default'
        panel.setStyleSheet(panel._limbus_stylesheet if str(current_theme) == 'limbus' else panel._default_stylesheet)
    except Exception as exc:
        try: write_error_log('H73编辑器式前端安装失败', exc)
        except Exception: pass


def _h73_activate_ui():
    try:
        if 'ControlPanel' in globals() and callable(_h73_panel_init_pre):
            ControlPanel.__init__ = _h73_panel_init
            ControlPanel.__init__._limbus_layer = 'H73'
            ControlPanel.__init__._limbus_policy = 'editorial instrument shell; semantic navigation; titlebar background utility; no transport ownership'
        if 'ControlPanel' in globals():
            ControlPanel._h73_show_background_popup = _h73_show_background_popup
        if 'PanelTitleBar' in globals() and callable(_h73_title_init_pre):
            PanelTitleBar.__init__ = _h73_title_init
            PanelTitleBar.__init__._limbus_layer = 'H73'
            PanelTitleBar.__init__._limbus_policy = 'borderless outline controls plus discoverable background utility'
        if 'PanelTitleBar' in globals() and callable(_h73_title_sync_pre):
            PanelTitleBar.sync_window_state = _h73_title_sync
            PanelTitleBar.sync_window_state._limbus_layer = 'H73'
    except Exception as exc:
        try: write_error_log('H73前端激活失败', exc)
        except Exception: pass


if '_h73_activate_ui' in globals():
    _h73_activate_ui()


# H74 preview stage + appearance inspector ---------------------------------------------
# Presentation-only continuation of H73. H74 turns the Appearance/Motion pages into a
# lightweight editor: a persistent lyric preview stage, compact core-style inspector,
# preset overflow menu, and creative-first card ordering. It does not touch MediaSync,
# provider authority, lyric clocks, desktop exit lifecycle, or the packaging dependency set.
H74_PREVIEW_RESET_DELAY_MS = 420
H74_PREVIEW_BASE_DURATION_MS = 1450.0
H74_PREVIEW_SAMPLE = '言葉は、光になる。'


def _h74_icon(name, size=16, color='#aaa3a2'):
    key = str(name or '').strip().lower()
    if key not in ('play', 'dots', 'eye'):
        return _h73_icon(key, size, color) if '_h73_icon' in globals() else QIcon()
    size = max(12, int(size or 16))
    pm = QPixmap(size, size); pm.fill(Qt.transparent)
    p = QPainter(pm)
    try:
        p.setRenderHint(QPainter.Antialiasing, True)
        scale = float(size) / 24.0
        p.setPen(QPen(QColor(color), max(1.0, 1.55 * scale), Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        p.setBrush(Qt.NoBrush)
        if key == 'play':
            path = QPainterPath(); path.moveTo(8*scale, 6*scale); path.lineTo(18*scale, 12*scale); path.lineTo(8*scale, 18*scale); path.closeSubpath(); p.drawPath(path)
        elif key == 'dots':
            p.setBrush(QColor(color)); p.setPen(Qt.NoPen)
            for x in (7.0, 12.0, 17.0): p.drawEllipse(QPointF(x*scale, 12*scale), 1.15*scale, 1.15*scale)
        else:
            p.drawEllipse(QRectF(3.5*scale, 7*scale, 17*scale, 10*scale)); p.drawEllipse(QRectF(9.2*scale, 9.2*scale, 5.6*scale, 5.6*scale))
    finally:
        p.end()
    return QIcon(pm)


def _h74_clamp(v, lo=0.0, hi=1.0):
    try: return max(float(lo), min(float(hi), float(v)))
    except Exception: return float(lo)


def _h74_effect_name(panel):
    try: return str(panel.h12_exit_combo.currentText() or '退场')
    except Exception: return '退场'


def _h74_profile(panel):
    try:
        effect = _h70_effect_key(panel.h12_exit_combo.currentData()) if '_h70_effect_key' in globals() else str(panel.h12_exit_combo.currentData() or 'fade')
        item = dict(getattr(panel, '_h70_exit_profiles', {}).get(effect, {}) or {})
        return effect, int(item.get('speed', 12) or 12), int(item.get('flavor', 0) or 0)
    except Exception:
        return 'fade', 12, 0


def _h74_effect_duration(speed):
    try:
        speed = max(1.0, min(15.0, float(speed or 12)))
        return max(620.0, min(2450.0, float(H74_PREVIEW_BASE_DURATION_MS) * ((12.0 / speed) ** 0.72)))
    except Exception:
        return float(H74_PREVIEW_BASE_DURATION_MS)


class H74PreviewStage(QFrame):
    """Small dependency-free preview surface; never participates in desktop lyric timing."""
    def __init__(self, panel, mode='appearance', parent=None):
        super().__init__(parent)
        self.panel = panel
        self.mode = str(mode or 'appearance')
        self._progress = 0.0
        self._running = False
        self._started_mono = 0.0
        self._replay_serial = 0
        self.setObjectName('h74PreviewStage')
        self.setMinimumHeight(188 if self.mode == 'appearance' else 202)
        self.setToolTip('这里是独立的编辑器预览，不读取或改写播放器时间。桌面歌词仍由原渲染链负责。')
        self._timer = QTimer(self)
        self._timer.setInterval(24)
        self._timer.timeout.connect(self._tick)

    def replay(self):
        self._replay_serial += 1
        self._running = True
        self._progress = 0.0
        self._started_mono = time.monotonic() * 1000.0
        self._timer.start()
        self.update()

    def _reset_static(self, serial=None):
        if serial is not None and int(serial) != int(self._replay_serial): return
        self._running = False
        self._progress = 0.0
        self.update()

    def _tick(self):
        if not self._running:
            self._timer.stop(); return
        _effect, speed, _flavor = _h74_profile(self.panel)
        duration = _h74_effect_duration(speed) if self.mode == 'motion' else 900.0
        self._progress = _h74_clamp((time.monotonic()*1000.0 - self._started_mono) / max(1.0, duration))
        self.update()
        if self._progress >= 1.0:
            self._timer.stop(); self._running = False
            serial = int(self._replay_serial)
            QTimer.singleShot(int(H74_PREVIEW_RESET_DELAY_MS), lambda s=serial: self._reset_static(s))

    def _text(self):
        try:
            text = str(getattr(self.panel, '_h74_preview_text', '') or '').strip()
            return text[:42] if text else H74_PREVIEW_SAMPLE
        except Exception:
            return H74_PREVIEW_SAMPLE

    def _font(self):
        panel = self.panel
        try:
            random_on = bool(getattr(panel, 'random_font_check', None).isChecked()) if hasattr(panel, 'random_font_check') else False
            f = QFont(panel.lyric_window.font if random_on else panel.font_combo.currentFont())
        except Exception:
            f = QFont('Microsoft YaHei')
        try: f.setPointSize(max(18, min(44, int(round(float(panel.font_size.value()) * 0.82)))))
        except Exception: f.setPointSize(28)
        try: f.setItalic(bool(panel.font_italic_check.isChecked()))
        except Exception: pass
        try: f.setWeight(max(1, min(99, int(getattr(panel, '_h12_font_weight', 75) or 75))))
        except Exception:
            try: f.setBold(bool(panel.font_bold_check.isChecked()))
            except Exception: pass
        try: f.setLetterSpacing(QFont.AbsoluteSpacing, float(panel.spacing_spin.value()) * 0.72)
        except Exception: pass
        return f

    def _colors(self):
        panel = self.panel
        try:
            dynamic = bool(getattr(panel, '_h12_cover_follow', False)) or bool(panel.random_color_check.isChecked())
        except Exception:
            dynamic = False
        try: text = QColor(panel.lyric_window.text_color if dynamic else panel.current_color)
        except Exception: text = QColor('#f4c2c2')
        try: stroke = QColor(panel.current_stroke_color)
        except Exception: stroke = QColor('#d8a523')
        try: shadow = QColor(panel.current_shadow_color)
        except Exception: shadow = QColor('#000000')
        try: glow = QColor(panel.lyric_window.glow_color if dynamic else panel.current_glow_color)
        except Exception: glow = QColor('#d8a523')
        return text, stroke, shadow, glow

    def _path_at(self, text, font, cx, cy):
        raw = QPainterPath(); raw.addText(0.0, 0.0, font, str(text))
        br = raw.boundingRect()
        transform = QTransform(); transform.translate(float(cx) - (br.left()+br.width()/2.0), float(cy) - (br.top()+br.height()/2.0))
        return transform.map(raw)

    def _draw_path(self, painter, path, alpha=1.0, ghost=0.0):
        panel = self.panel
        text, stroke, shadow, glow = self._colors()
        opacity = _h74_clamp(alpha)
        try: opacity *= _h74_clamp(float(getattr(panel, '_h12_lyric_opacity_pct', 100))/100.0)
        except Exception: pass
        painter.save(); painter.setOpacity(opacity)
        try:
            if bool(panel.shadow_check.isChecked()):
                sc = QColor(shadow); sc.setAlpha(115 if ghost <= 0.0 else 70)
                transform = QTransform(); transform.translate(2.0, 2.6); painter.fillPath(transform.map(path), sc)
        except Exception: pass
        try:
            if bool(panel.glow_check.isChecked()):
                radius = max(2.0, min(18.0, float(panel.glow_size_slider.value()) * 0.64 + float(ghost)*4.0))
                ga = max(8, min(150, int(panel.glow_alpha_slider.value())))
                _draw_soft_glow_path(painter, path, glow, radius, ga, 0.82 if ghost <= 0 else 0.58)
        except Exception: pass
        try:
            if bool(panel.outline_check.isChecked()):
                width = max(0.0, float(panel.stroke_spin.value())) * 1.55
                if width > 0.0:
                    stroker = QPainterPathStroker(); stroker.setWidth(max(0.7, width*2.0)); painter.fillPath(stroker.createStroke(path), stroke)
        except Exception: pass
        tc = QColor(text)
        if ghost > 0.0: tc.setAlpha(max(20, min(160, int(110 * (1.0-0.45*ghost)))))
        painter.fillPath(path, tc)
        painter.restore()

    def _draw_text(self, painter, text, cx, cy, alpha=1.0, scale=1.0, rotation=0.0, ghost=0.0):
        font = self._font(); path = self._path_at(text, font, cx, cy)
        painter.save(); painter.translate(cx, cy)
        if abs(float(rotation)) > 0.01: painter.rotate(float(rotation))
        if abs(float(scale)-1.0) > 0.001: painter.scale(float(scale), float(scale))
        painter.translate(-cx, -cy); self._draw_path(painter, path, alpha, ghost); painter.restore()

    def _draw_per_char(self, painter, text, cx, cy, progress, flavor, wipe=None):
        font = self._font(); fm = QFontMetrics(font); chars = list(text)
        if not chars: return
        advances = [max(1, fm.horizontalAdvance(ch)) for ch in chars]; total = float(sum(advances)); x = float(cx) - total/2.0
        n = max(1, len(chars)-1)
        for i, (ch, adv) in enumerate(zip(chars, advances)):
            center = x + adv/2.0; x += adv
            if wipe is not None:
                order = i if wipe == 'ltr' else (len(chars)-1-i)
                front = progress * (len(chars)+1.35)
                local = _h74_clamp(front - float(order) + 0.18)
                alpha = 1.0 - local
                offx = (9.0 + 22.0*flavor) * local * (1.0 if wipe == 'ltr' else -1.0)
                offy = 2.0 * math.sin(i*1.73) * local
                self._draw_text(painter, ch, center+offx, cy+offy, alpha=alpha, ghost=0.15*local)
            else:
                phase = float(i)/float(n)
                local = _h74_clamp((progress - phase*0.28) / 0.72)
                alpha = 1.0 - local
                amp = 12.0 + 52.0*flavor
                offx = math.sin((i+1)*2.17) * amp * local
                offy = math.cos((i+1)*1.43) * amp * 0.55 * local
                rot = math.sin((i+2)*1.31) * 6.5 * flavor * local
                self._draw_text(painter, ch, center+offx, cy+offy, alpha=alpha, rotation=rot, ghost=0.18*local)

    def _motion_draw(self, painter, text, cx, cy):
        effect, _speed, flavor_i = _h74_profile(self.panel); flavor = _h74_clamp(flavor_i/100.0)
        progress = self._progress if self._running else 0.0
        if effect == 'instant':
            self._draw_text(painter, text, cx, cy, alpha=0.0 if self._running and progress > 0.08 else 1.0); return
        if effect == 'per_char':
            self._draw_per_char(painter, text, cx, cy, progress, flavor); return
        if effect in ('wipe_ltr', 'wipe_rtl'):
            self._draw_per_char(painter, text, cx, cy, progress, flavor, 'ltr' if effect == 'wipe_ltr' else 'rtl'); return
        eased = progress*progress*(3.0-2.0*progress)
        alpha = 1.0 - progress
        y = 0.0; scale = 1.0; rot = 0.0; ghost = 0.0
        if effect == 'fade': y = -72.0 * flavor * eased
        elif effect == 'shrink':
            pretension = (math.sin(min(1.0, progress/0.20)*math.pi) * 0.11 * flavor) if progress < 0.20 else 0.0
            scale = max(0.34, 1.0 + pretension - 0.64*eased)
        elif effect == 'soft_drift': y = 25.0*eased + 66.0*flavor*(progress**2.25)
        elif effect == 'hop_drop':
            if progress <= 0.32:
                q = progress/0.32; y = -(22.0+34.0*flavor)*math.sin(q*math.pi*0.5)
            else:
                q = (progress-0.32)/0.68; y = -(22.0+34.0*flavor)*(1.0-q) + (48.0+44.0*flavor)*(q*q)
            rot = 4.5*flavor*math.sin(math.pi*progress)
        elif effect == 'blur_decay':
            scale = 1.0 + (0.035 + 0.065*flavor)*eased; alpha = 1.0 - max(0.0, (progress-0.55)/0.45); ghost = 0.85*eased
            if self._running and progress > 0.12:
                for dx, dy, a in ((-2.0,0.0,0.12),(2.0,0.0,0.12),(0.0,-1.5,0.08),(0.0,1.5,0.08)):
                    self._draw_text(painter, text, cx+dx*(1+2*flavor), cy+dy*(1+2*flavor), alpha=max(0.0, alpha*a), scale=scale, ghost=0.9)
        self._draw_text(painter, text, cx, cy+y, alpha=alpha, scale=scale, rotation=rot, ghost=ghost)

    def paintEvent(self, event):
        painter = QPainter(self)
        try:
            painter.setRenderHint(QPainter.Antialiasing, True)
            rect = QRectF(self.rect()).adjusted(0.7, 0.7, -0.7, -0.7)
            _studio_paint_preview(painter, rect)
            painter.setFont(QFont('Segoe UI', 8)); painter.setPen(QColor('#777174'))
            painter.drawText(QRectF(rect.left()+14, rect.top()+10, 170, 18), Qt.AlignLeft|Qt.AlignVCenter, 'LIVE STYLE' if self.mode == 'appearance' else 'MOTION PREVIEW')
            if self.mode == 'motion':
                label = _h74_effect_name(self.panel)
                painter.setPen(QColor('#a99da0')); painter.drawText(QRectF(rect.right()-210, rect.top()+10, 195, 18), Qt.AlignRight|Qt.AlignVCenter, label)
            text = self._text(); cx = rect.center().x(); cy = rect.center().y()+4.0
            if self.mode == 'motion':
                text = text[:18]
                self._motion_draw(painter, text, cx, cy)
            else: self._draw_text(painter, text, cx, cy)
            painter.setFont(QFont('Segoe UI', 8)); painter.setPen(QColor('#696367'))
            try:
                if self.mode == 'appearance':
                    metric = f'{self._font().family()}  ·  {int(self.panel.font_size.value())} pt  ·  {_h12_weight_label(getattr(self.panel, "_h12_font_weight", 75))}  ·  {int(getattr(self.panel, "_h12_lyric_opacity_pct", 100))}%'
                else:
                    effect, speed, flavor = _h74_profile(self.panel); metric = f'速度 {speed}  ·  {H70_FLAVOR_LABELS.get(effect, "风味")} {flavor}%' if effect != 'instant' else '直接消失 · 无额外参数'
            except Exception: metric = ''
            painter.drawText(QRectF(rect.left()+14, rect.bottom()-25, rect.width()-28, 17), Qt.AlignLeft|Qt.AlignVCenter, metric)
        finally:
            painter.end()


def _h74_find_layout_for_widget(layout, widget):
    if layout is None or widget is None: return None
    try:
        for i in range(layout.count()):
            item = layout.itemAt(i)
            if item.widget() is widget: return layout
            child = item.layout()
            found = _h74_find_layout_for_widget(child, widget) if child is not None else None
            if found is not None: return found
    except Exception:
        pass
    return None


def _h74_card_title(card):
    if card is None: return ''
    try:
        for label in card.findChildren(QLabel):
            if label.objectName() in ('cardTitle', 'sectionTitle'):
                text = str(label.text() or '').strip()
                if text: return text
    except Exception: pass
    return ''


def _h74_make_preview_card(panel, mode):
    card = QFrame(); card.setObjectName('h74PreviewCard')
    layout = QVBoxLayout(card); layout.setContentsMargins(0, 0, 0, 8); layout.setSpacing(8)
    header = QHBoxLayout(); header.setContentsMargins(2, 0, 2, 0); header.setSpacing(8)
    title = QLabel('实时预览' if mode == 'appearance' else '退场预览'); title.setObjectName('h74PreviewTitle'); header.addWidget(title)
    hint = QLabel('GLOBAL STYLE' if mode == 'appearance' else 'EXIT PREVIEW'); hint.setObjectName('h74PreviewEyebrow'); header.addWidget(hint); header.addStretch()
    if mode == 'appearance':
        edit = QLineEdit(getattr(panel, '_h74_preview_text', H74_PREVIEW_SAMPLE)); edit.setObjectName('h74PreviewText'); edit.setMaximumWidth(250); edit.setMaxLength(42); edit.setPlaceholderText('预览文字')
        def preview_text_changed(text):
            panel._h74_preview_text = str(text or '')
            if getattr(panel, 'h74_appearance_preview', None) is not None: panel.h74_appearance_preview.update()
            if getattr(panel, 'h74_motion_preview', None) is not None: panel.h74_motion_preview.update()
        edit.textChanged.connect(preview_text_changed)
        panel.h74_preview_text_edit = edit; header.addWidget(edit)
    else:
        replay = QToolButton(); replay.setObjectName('h74ReplayButton'); replay.setIcon(_h74_icon('play', 14, '#b9adaf')); replay.setIconSize(QSize(14,14)); replay.setText('重播'); replay.setToolButtonStyle(Qt.ToolButtonTextBesideIcon); replay.setCursor(Qt.PointingHandCursor); replay.setToolTip('只重播这里的示意预览，不影响桌面歌词或播放器。')
        header.addWidget(replay); panel.h74_motion_replay_btn = replay
    layout.addLayout(header)
    stage = H74PreviewStage(panel, mode, card); layout.addWidget(stage)
    if mode == 'appearance': panel.h74_appearance_preview = stage
    else:
        panel.h74_motion_preview = stage; panel.h74_motion_replay_btn.clicked.connect(stage.replay)
    return card, stage


def _h74_bind_proxy_slider(proxy, source, value_label, formatter):
    def to_source(value):
        try: source.setValue(int(value))
        except Exception: pass
    def from_source(value):
        try:
            proxy.blockSignals(True); proxy.setValue(int(value)); value_label.setText(str(formatter(int(value))))
        finally:
            try: proxy.blockSignals(False)
            except Exception: pass
    proxy.valueChanged.connect(to_source); source.valueChanged.connect(from_source); from_source(source.value())


def _h74_install_appearance_inspector(panel, page_layout):
    card = QFrame(); card.setObjectName('settingsCard')
    layout = QVBoxLayout(card); layout.setContentsMargins(16, 15, 16, 16); layout.setSpacing(11)
    title = QLabel('基础表现'); title.setObjectName('cardTitle'); title.setToolTip('把原来藏在“设置”里的字重和歌词透明度放回外观编辑流程。底层配置键保持不变。'); layout.addWidget(title)
    row = QHBoxLayout(); row.setSpacing(8); label = QLabel('字重：'); label.setObjectName('fieldLabel'); label.setMinimumWidth(94); row.addWidget(label)
    panel.h74_weight_slider = QSlider(Qt.Horizontal); panel.h74_weight_slider.setRange(1,99); panel.h74_weight_value = QLabel(''); panel.h74_weight_value.setObjectName('h74MetricValue'); panel.h74_weight_value.setMinimumWidth(94)
    row.addWidget(panel.h74_weight_slider,1); row.addWidget(panel.h74_weight_value); layout.addLayout(row)
    _h74_bind_proxy_slider(panel.h74_weight_slider, panel.h12_weight, panel.h74_weight_value, lambda value: f'{_h12_weight_label(value)} · {value}')
    row = QHBoxLayout(); row.setSpacing(8); label = QLabel('整体透明度：'); label.setObjectName('fieldLabel'); label.setMinimumWidth(94); row.addWidget(label)
    panel.h74_opacity_slider = QSlider(Qt.Horizontal); panel.h74_opacity_slider.setRange(0,100); panel.h74_opacity_value = QLabel(''); panel.h74_opacity_value.setObjectName('h74MetricValue'); panel.h74_opacity_value.setMinimumWidth(94)
    row.addWidget(panel.h74_opacity_slider,1); row.addWidget(panel.h74_opacity_value); layout.addLayout(row)
    def opacity_text(value): return f'{value}% · '+('隐藏' if value <= 0 else '轻柔' if value < 65 else '平衡' if value < 90 else '清晰')
    _h74_bind_proxy_slider(panel.h74_opacity_slider, panel.h12_opacity, panel.h74_opacity_value, opacity_text)
    row = QHBoxLayout(); row.setSpacing(8)
    panel.h74_cover_follow = QCheckBox('颜色跟随当前封面'); panel.h74_cover_follow.setToolTip('当前歌曲有可用封面时，从封面提取可读色；关闭后回到固定/随机颜色策略。')
    panel.h74_cover_follow.setChecked(bool(panel.h12_cover_check.isChecked())); row.addWidget(panel.h74_cover_follow); row.addStretch(); layout.addLayout(row)
    panel.h74_cover_follow.toggled.connect(panel.h12_cover_check.setChecked)
    def cover_from_source(on):
        panel.h74_cover_follow.blockSignals(True); panel.h74_cover_follow.setChecked(bool(on)); panel.h74_cover_follow.blockSignals(False)
    panel.h12_cover_check.toggled.connect(cover_from_source)
    page_layout.insertWidget(1, card)
    # Old H12 widgets remain the config owners but are no longer duplicated in Settings.
    for widget in (panel.h12_weight, panel.h12_weight_label, panel.h12_opacity, panel.h12_opacity_label, panel.h12_cover_check):
        try: widget.hide()
        except Exception: pass
    try:
        owner = panel.h12_weight.parentWidget()
        for label in owner.findChildren(QLabel):
            if str(label.text() or '').strip() in ('字体粗细：', '歌词透明度：'):
                label.hide()
    except Exception: pass
    return card


def _h74_install_preset_overflow(panel):
    try:
        card = panel.preset_combo.parentWidget(); row = _h74_find_layout_for_widget(card.layout(), panel.preset_combo)
        if row is None: return
        for button in card.findChildren(QPushButton):
            if str(button.text() or '').strip() in ('+', '-', '更新', '重命名'):
                button.hide()
        menu_button = QToolButton(card); menu_button.setObjectName('h74OverflowButton'); menu_button.setIcon(_h74_icon('dots',16,'#9a9193')); menu_button.setIconSize(QSize(16,16)); menu_button.setFixedSize(31,28); menu_button.setCursor(Qt.PointingHandCursor); menu_button.setToolTip('预设操作')
        menu = QMenu(menu_button)
        menu.addAction('新建预设', panel.new_preset); menu.addAction('保存到当前预设', panel.update_preset); menu.addAction('重命名', panel.rename_preset); menu.addSeparator(); menu.addAction('删除当前预设', panel.delete_preset)
        menu_button.setMenu(menu); menu_button.setPopupMode(QToolButton.InstantPopup)
        idx = row.indexOf(panel.preset_combo); row.insertWidget(max(0,idx+1), menu_button); panel.h74_preset_menu_btn = menu_button
    except Exception:
        pass


def _h74_reorder_cards(page_layout, preferred_titles):
    try:
        widgets = []
        for i in range(page_layout.count()):
            widget = page_layout.itemAt(i).widget()
            if isinstance(widget, QFrame) and widget.objectName() == 'settingsCard': widgets.append(widget)
        lookup = {_h74_card_title(widget):widget for widget in widgets}
        anchor = 1
        for title in preferred_titles:
            widget = lookup.get(title)
            if widget is None: continue
            page_layout.removeWidget(widget); page_layout.insertWidget(anchor, widget); anchor += 1
    except Exception:
        pass


def _h74_refresh_previews(panel, replay_motion=False):
    try:
        if getattr(panel, 'h74_appearance_preview', None) is not None: panel.h74_appearance_preview.update()
        if getattr(panel, 'h74_motion_preview', None) is not None:
            panel.h74_motion_preview.update()
            if replay_motion: panel.h74_motion_preview.replay()
    except Exception:
        pass


def _h74_connect_previews(panel):
    appearance = getattr(panel, 'h74_appearance_preview', None); motion = getattr(panel, 'h74_motion_preview', None)
    if appearance is not None:
        bindings = ((panel.font_combo,'currentFontChanged'),(panel.font_size,'valueChanged'),(panel.font_bold_check,'toggled'),(panel.font_italic_check,'toggled'),(panel.spacing_spin,'valueChanged'),(panel.shadow_check,'toggled'),(panel.outline_check,'toggled'),(panel.stroke_spin,'valueChanged'),(panel.glow_check,'toggled'),(panel.glow_size_slider,'valueChanged'),(panel.glow_alpha_slider,'valueChanged'),(panel.h12_weight,'valueChanged'),(panel.h12_opacity,'valueChanged'),(panel.h12_cover_check,'toggled'),(panel.random_font_check,'toggled'),(panel.random_color_check,'toggled'))
        for obj, signal_name in bindings:
            try: getattr(obj, signal_name).connect(lambda *_args, stage=appearance: stage.update())
            except Exception: pass
        for button_name in ('color_btn','shadow_btn','stroke_btn','glow_color_btn'):
            try: getattr(panel, button_name).clicked.connect(lambda _checked=False, stage=appearance: QTimer.singleShot(0, stage.update))
            except Exception: pass
    if motion is not None:
        try: panel.h12_exit_combo.currentIndexChanged.connect(lambda *_args: _h74_refresh_previews(panel, True))
        except Exception: pass
        panel._h74_motion_preview_debounce = QTimer(panel); panel._h74_motion_preview_debounce.setSingleShot(True); panel._h74_motion_preview_debounce.setInterval(180); panel._h74_motion_preview_debounce.timeout.connect(motion.replay)
        for name in ('h70_exit_speed_slider','h70_exit_flavor_slider'):
            obj = getattr(panel, name, None)
            if obj is not None:
                try: obj.valueChanged.connect(lambda *_args, stage=motion, timer=panel._h74_motion_preview_debounce: (stage.update(), timer.start()))
                except Exception: pass


H74_QSS = r'''
QFrame#h74PreviewCard { background:transparent; border:none; }
QLabel#h74PreviewTitle { color:#eee8e6; font-size:13px; font-weight:690; }
QLabel#h74PreviewEyebrow { color:#655f63; font-size:9px; letter-spacing:1.0px; }
QLineEdit#h74PreviewText { min-height:26px; max-height:26px; padding:0 9px; background:rgba(255,255,255,5); border:1px solid rgba(238,229,226,18); border-radius:5px; color:#bdb4b5; }
QLineEdit#h74PreviewText:focus { border-color:rgba(209,164,171,65); background:rgba(255,255,255,7); }
QToolButton#h74ReplayButton { min-height:27px; padding:0 9px 0 7px; border:none; border-radius:5px; color:#a99fa1; background:rgba(255,255,255,5); }
QToolButton#h74ReplayButton:hover { color:#e1d8d6; background:rgba(255,255,255,10); }
QToolButton#h74OverflowButton { background:transparent; border:none; border-radius:5px; padding:0; }
QToolButton#h74OverflowButton:hover { background:rgba(255,255,255,10); }
QLabel#h74MetricValue { color:#a99ea1; min-width:94px; }
'''


_h74_panel_init_pre = ControlPanel.__init__ if 'ControlPanel' in globals() else None


def _h74_panel_init(panel, *args, **kwargs):
    _h74_panel_init_pre(panel, *args, **kwargs)
    try:
        panel._h74_preview_text = H74_PREVIEW_SAMPLE
        style_page = panel.main_tabs.widget(1).widget(); style_layout = style_page.layout()
        motion_page = panel.main_tabs.widget(2).widget(); motion_layout = motion_page.layout()
        appearance_card, _appearance = _h74_make_preview_card(panel, 'appearance'); style_layout.insertWidget(0, appearance_card)
        _h74_install_appearance_inspector(panel, style_layout)
        motion_card, _motion = _h74_make_preview_card(panel, 'motion'); motion_layout.insertWidget(0, motion_card)
        _h74_install_preset_overflow(panel)
        # Rename and reorder only presentation cards. Existing widgets/config owners are reused.
        renames = {'预设':'样式预设','光效':'光与材质','字体与排版':'字体与轮廓','动态':'运动','字符出场':'入场','方向':'空间方向','退场动效':'退场'}
        for label in panel.findChildren(QLabel):
            text = str(label.text() or '').strip()
            if text in renames and label.objectName() in ('cardTitle','sectionTitle'):
                label.setText(renames[text]); label.setObjectName('cardTitle')
        _h74_reorder_cards(style_layout, ('基础表现','样式预设','字体与轮廓','光与材质'))
        _h74_reorder_cards(motion_layout, ('退场','入场','运动','空间方向','同步'))
        panel._page_meta = (
            ('播放', '播放器、歌词来源与当前播放状态'),
            ('外观', '实时预览、字体、色彩、轮廓与光效'),
            ('动效', '实时预览、入场、退场与字符运动'),
            ('设置', '应用行为、背景、输出与高级选项'),
            ('单曲', '按歌曲与播放器覆盖全局视觉样式'),
        )
        panel._update_workspace_header(panel.main_tabs.currentIndex())
        panel._default_stylesheet = str(getattr(panel, '_default_stylesheet', '') or '') + H74_QSS
        panel._limbus_stylesheet = str(getattr(panel, '_limbus_stylesheet', '') or '') + H74_QSS
        theme = panel._current_ui_theme() if hasattr(panel, '_current_ui_theme') else 'default'
        panel.setStyleSheet(panel._limbus_stylesheet if str(theme) == 'limbus' else panel._default_stylesheet)
        _h74_connect_previews(panel)
        try: panel.main_tabs.currentChanged.connect(lambda index: panel.h74_motion_preview.replay() if int(index) == 2 else None)
        except Exception: pass
        _h74_refresh_previews(panel, False)
        if panel.main_tabs.currentIndex() == 2: panel.h74_motion_preview.replay()
        try: panel._filter_settings_cards('')
        except Exception: pass
    except Exception as exc:
        try: write_error_log('H74预览舞台与外观检查器安装失败', exc)
        except Exception: pass


def _h74_activate_ui():
    try:
        if 'ControlPanel' in globals() and callable(_h74_panel_init_pre):
            ControlPanel.__init__ = _h74_panel_init
            ControlPanel.__init__._limbus_layer = 'H74'
            ControlPanel.__init__._limbus_policy = 'presentation-only preview stage + appearance inspector; no transport/provider/lifecycle ownership'
    except Exception as exc:
        try: write_error_log('H74前端激活失败', exc)
        except Exception: pass


if '_h74_activate_ui' in globals():
    _h74_activate_ui()



# H75 information architecture + Spotify parity ---------------------------------------
# H73/H74 established the editorial shell and preview workflow. H75 closes the remaining
# product-language mismatch without taking ownership of playback/seek/provider clocks:
# - Motion becomes visual-only; player offsets + capture/OBS move to Settings / Sync & Output.
# - settings search spans every first-level page and no longer clears on navigation.
# - Spotify gets an independent display offset and first-class per-song DIY scope.
# - the historical H12 Display+Update mixed card is replaced by semantic UI/Application and
#   Update surfaces while its mature controls/config keys remain the compatibility owners.
H75_PLAYER_SCOPES = ('qq', 'netease', 'kugou', 'spotify')
H75_ALL_SCOPES = ('all',) + H75_PLAYER_SCOPES


def _h75_card_for_widget(widget):
    try:
        cur = widget.parentWidget() if widget is not None else None
        while cur is not None:
            if isinstance(cur, QFrame) and cur.objectName() == 'settingsCard':
                return cur
            cur = cur.parentWidget()
    except Exception:
        pass
    return None


def _h75_find_card_by_title(page_layout, title):
    try:
        for i in range(page_layout.count()):
            card = page_layout.itemAt(i).widget()
            if isinstance(card, QFrame) and card.objectName() == 'settingsCard':
                if _h74_card_title(card) == str(title):
                    return card
    except Exception:
        pass
    return None


def _h75_field_row(label_text, widget, parent=None):
    row = QHBoxLayout(); row.setSpacing(8)
    label = QLabel(label_text, parent); label.setObjectName('fieldLabel'); label.setMinimumWidth(94)
    row.addWidget(label); row.addWidget(widget, 1); return row


def _h75_bind_spin_proxy(proxy, source):
    def to_source(value):
        try: source.setValue(int(value))
        except Exception: pass
    def from_source(value):
        try:
            proxy.blockSignals(True); proxy.setValue(int(value))
        finally:
            try: proxy.blockSignals(False)
            except Exception: pass
    proxy.valueChanged.connect(to_source); source.valueChanged.connect(from_source); from_source(source.value())


def _h75_bind_combo_proxy(proxy, source):
    try:
        proxy.blockSignals(True); proxy.clear()
        for i in range(source.count()):
            proxy.addItem(source.itemText(i), source.itemData(i))
        idx = proxy.findData(source.currentData())
        proxy.setCurrentIndex(max(0, idx))
        proxy.blockSignals(False)
    except Exception:
        pass
    def to_source(_index):
        try:
            idx = source.findData(proxy.currentData())
            if idx >= 0: source.setCurrentIndex(idx)
        except Exception: pass
    def from_source(_index):
        try:
            idx = proxy.findData(source.currentData())
            if idx >= 0:
                proxy.blockSignals(True); proxy.setCurrentIndex(idx); proxy.blockSignals(False)
        except Exception: pass
    proxy.currentIndexChanged.connect(to_source); source.currentIndexChanged.connect(from_source)


def _h75_edit_update_source(panel):
    try:
        current = str(panel.h12_update_url_edit.text() or '').strip()
        value, ok = QInputDialog.getText(panel, '自定义更新源', 'HTTPS 更新接口：', QLineEdit.Normal, current)
        if not ok: return
        value = str(value or '').strip()
        if value and not value.lower().startswith('https://'):
            QMessageBox.warning(panel, '更新源无效', '更新接口必须使用 HTTPS。')
            return
        panel.h12_update_url_edit.setText(value)
        panel._h12_update_url = value
        panel._schedule_config_save()
        if hasattr(panel, '_show_action_toast'): panel._show_action_toast('更新源已保存')
    except Exception as exc:
        try: write_error_log('H75自定义更新源编辑失败', exc)
        except Exception: pass


def _h75_make_application_card(panel):
    card = QFrame(); card.setObjectName('settingsCard')
    v = QVBoxLayout(card); v.setContentsMargins(16,15,16,16); v.setSpacing(10)
    title = QLabel('应用界面'); title.setObjectName('cardTitle'); title.setToolTip('只调整控制面板本身；不会改变桌面歌词时间轴。'); v.addWidget(title)
    scale = QComboBox(card); scale.setMaximumWidth(150); _h75_bind_combo_proxy(scale, panel.h12_scale_combo); panel.h75_scale_combo = scale
    v.addLayout(_h75_field_row('界面缩放：', scale, card))
    note = QLabel('背景图片可从右上角图片编辑图标快速进入；完整背景设置仍保留在“界面背景”。', card); note.setObjectName('trackDetail'); note.setWordWrap(True); v.addWidget(note)
    return card



def _h75_apply_live_sync_offset(self, *_args):
    """H75 presentation/config parity: Spotify owns its own display offset; playback authority is unchanged."""
    try:
        player_name = str(self.player_combo.currentText() or '')
        upper_name = player_name.upper()
        if 'SPOTIFY' in upper_name:
            spotify_spin = getattr(self, 'spotify_sync_offset_spin', None)
            self.lyric_window.sync_offset_ms = int(spotify_spin.value()) if spotify_spin is not None else int(getattr(self, '_h75_spotify_sync_offset_ms', 0) or 0)
            if hasattr(self, 'sync_recalibrate_btn'):
                self.sync_recalibrate_btn.setEnabled(False)
            return
    except Exception:
        pass
    if callable(_h75_apply_live_sync_offset_pre):
        return _h75_apply_live_sync_offset_pre(self, *_args)

def _h75_make_sync_output_card(panel, settings):
    card = QFrame(); card.setObjectName('settingsCard')
    v = QVBoxLayout(card); v.setContentsMargins(16,15,16,16); v.setSpacing(10)
    title = QLabel('同步与输出'); title.setObjectName('cardTitle'); title.setToolTip('播放器时间微调只改变字幕显示；输出模式决定普通 Overlay / OBS / 捕获排除。'); v.addWidget(title)
    hint = QLabel('正值让字幕提前，负值让字幕延后。四个播放器互相独立，不修改播放器位置或歌词文件。', card); hint.setObjectName('trackDetail'); hint.setWordWrap(True); v.addWidget(hint)
    panel.h75_offset_proxies = {}
    sources = (('网易云：','netease',panel.netease_sync_offset_spin),('QQ音乐：','qq',panel.qq_sync_offset_spin),('酷狗：','kugou',panel.kugou_sync_offset_spin))
    for label_text, key, source in sources:
        proxy = QSpinBox(card); proxy.setRange(-1500,1500); proxy.setSingleStep(50); proxy.setSuffix(' ms'); proxy.setMaximumWidth(150); proxy.setToolTip(source.toolTip())
        _h75_bind_spin_proxy(proxy, source); panel.h75_offset_proxies[key] = proxy; v.addLayout(_h75_field_row(label_text, proxy, card))
    panel.spotify_sync_offset_spin = QSpinBox(card); panel.spotify_sync_offset_spin.setRange(-1500,1500); panel.spotify_sync_offset_spin.setSingleStep(50); panel.spotify_sync_offset_spin.setSuffix(' ms'); panel.spotify_sync_offset_spin.setMaximumWidth(150)
    panel.spotify_sync_offset_spin.setToolTip('Spotify 独立显示微调。正值=字幕提前，负值=字幕延后；不会控制 Spotify 播放。')
