def _h75_global_filter(panel, text=''):
    query = str(text or '').strip().lower(); page_hits = {}; total_visible = 0; matching_pages = []
    try:
        for index in range(panel.main_tabs.count()):
            area = panel.main_tabs.widget(index); page = area.widget() if isinstance(area,QScrollArea) else area
            cards = page.findChildren(QFrame,'settingsCard') if page is not None else []
            hit = 0
            for card in cards:
                if bool(card.property('h75SearchIgnore')):
                    card.setVisible(False); continue
                matched = (not query) or (query in panel._settings_card_search_text(card))
                card.setVisible(matched)
                if matched: hit += 1; total_visible += 1
            page_hits[index] = hit
            if query and hit: matching_pages.append(index)
        active = int(panel.main_tabs.currentIndex())
        if query and not page_hits.get(active,0) and matching_pages and not bool(getattr(panel,'_h75_filter_switching',False)):
            panel._h75_filter_switching = True
            try: panel.main_tabs.setCurrentIndex(matching_pages[0]); active = matching_pages[0]
            finally: panel._h75_filter_switching = False
        if hasattr(panel,'settings_filter_count'):
            if query:
                panel.settings_filter_count.setText(f'{page_hits.get(active,0)}/{total_visible}组 · {len(matching_pages)}页')
            else: panel.settings_filter_count.setText('')
            panel.settings_filter_count.setProperty('empty', bool(query and total_visible == 0)); panel.settings_filter_count.style().unpolish(panel.settings_filter_count); panel.settings_filter_count.style().polish(panel.settings_filter_count)
        empty = bool(query and total_visible == 0)
        panel.settings_main.setVisible(not empty); panel.settings_empty.setVisible(empty)
        if empty: panel.settings_empty.setText(f'全部设置中没有找到“{str(text).strip()}”')
    except Exception:
        pass


def _h75_filter_settings_cards(self, text=''):
    _h75_global_filter(self, text)


def _h75_on_settings_page_changed(self, index):
    try: self._update_workspace_header(index)
    except Exception: pass
    _h75_global_filter(self, self.settings_filter.text() if hasattr(self,'settings_filter') else '')


