# H76 editorial polish + wipe refinement + blur recovery ---------------------------------
# Field review of H75 found four product-facing rough edges and one runtime safety regression:
#   * the H51 legacy renderer-mode switch had become a user-facing "exit texture" control even
#     though it is an implementation-era compatibility knob with little discoverable value;
#   * the target-display selector occupied space even on single-monitor systems;
#   * H73's icon-only background shortcut remained too ambiguous despite its tooltip;
#   * H71's high-flavor wipe used two separated ghost copies, reading as dirty motion trails rather
#     than a clean directional dissolve;
#   * most importantly, H72's generic "update exception => retire" and 15 s watchdog also wrapped
#     blur-decay. A transient blur progress/material exception could therefore delete a row before a
#     release frame was ever shown. H76 gives blur a fail-soft presentation lane: normal H62-H69
#     behavior stays authoritative, but transient update/progress failures preserve the last optical
#     floor, request a repaint/material retry, and never use H72's generic watchdog. Release also owns
#     a small visible minimum tail so a high history progress cannot look like an instant cut.
H76_BLUR_RELEASE_VISIBLE_MIN_MS = 760.0
H76_BLUR_RELEASE_VISIBLE_MAX_MS = 1800.0
H76_BLUR_NO_DRAW_REPAINT_MS = 520.0
H76_BLUR_ABSOLUTE_EMERGENCY_MS = 30000.0
H76_BLUR_ERROR_LOG_MS = 1600.0
H76_WIPE_GHOST_MAX_ALPHA = 0.085
H76_WIPE_GHOST_SHIFT_BASE_PX = 3.0
H76_WIPE_GHOST_SHIFT_GAIN_PX = 6.0
H76_WIPE_MAIN_SHIFT_MAX_PX = 6.0
H76_WIPE_STRETCH_MAX = 0.028
H76_BLUR_ORPHAN_RELEASE_TRIGGER = 0.92
H76_BLUR_ORPHAN_HOLD_MAX = 0.945
H76_UI_PAGE_SETTLE_MS = 165
H76_UI_POPUP_ENTER_MS = 180
H76_UI_POPUP_RISE_PX = 6

_h76_control_init_pre = ControlPanel.__init__ if 'ControlPanel' in globals() else None
_h76_title_init_pre = PanelTitleBar.__init__ if 'PanelTitleBar' in globals() else None
_h76_fragment_draw_pre = globals().get('_h51_fragment_exit_draw')
_h76_blur_progress_pre = globals().get('_h62_decay_progress')
_h76_fading_update_pre = getattr(FadingLine, 'update', None) if 'FadingLine' in globals() else None
_h76_blur_update_core = globals().get('_h72_fading_update_pre')
_h76_tab_animate_pre = getattr(ControlPanel, '_animate_current_tab', None) if 'ControlPanel' in globals() else None
_h76_background_popup_pre = getattr(ControlPanel, '_h73_show_background_popup', None) if 'ControlPanel' in globals() else None


def _h76_palette_icon(size=16, color='#aaa3a2'):
    size=max(12,int(size or 16)); pm=QPixmap(size,size); pm.fill(Qt.transparent); p=QPainter(pm)
    try:
        p.setRenderHint(QPainter.Antialiasing,True); scale=float(size)/24.0
        p.setPen(QPen(QColor(color),max(1.0,1.55*scale),Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin)); p.setBrush(Qt.NoBrush)
        path=QPainterPath(); path.moveTo(12*scale,3.5*scale)
        path.cubicTo(6.7*scale,3.5*scale,3.5*scale,7.0*scale,3.5*scale,11.5*scale)
        path.cubicTo(3.5*scale,16.4*scale,7.2*scale,20.2*scale,12.0*scale,20.2*scale)
        path.cubicTo(13.5*scale,20.2*scale,14.4*scale,19.4*scale,14.4*scale,18.3*scale)
        path.cubicTo(14.4*scale,17.0*scale,13.3*scale,16.5*scale,13.3*scale,15.2*scale)
        path.cubicTo(13.3*scale,13.9*scale,14.4*scale,13.1*scale,15.7*scale,13.1*scale)
        path.lineTo(17.3*scale,13.1*scale)
        path.cubicTo(19.5*scale,13.1*scale,20.5*scale,11.7*scale,20.5*scale,9.8*scale)
        path.cubicTo(20.5*scale,6.3*scale,16.8*scale,3.5*scale,12*scale,3.5*scale); p.drawPath(path)
        for x,y in ((8,8),(12,6.8),(16,8.4),(7.2,12.2)):
            p.drawEllipse(QPointF(x*scale,y*scale),1.05*scale,1.05*scale)
    finally: p.end()
    return QIcon(pm)


def _h76_find_label(panel, text):
    target=str(text or '').strip()
    try:
        for label in panel.findChildren(QLabel):
            if str(label.text() or '').strip()==target: return label
    except Exception: pass
    return None


def _h76_refresh_multiscreen_visibility(panel):
    try:
        screens=list(QApplication.screens() or []); visible=len(screens)>1
        combo=getattr(panel,'h51_screen_combo',None); label=getattr(panel,'_h76_screen_label',None)
        if combo is not None: combo.setVisible(visible)
        if label is not None: label.setVisible(visible)
        panel._h76_multiscreen_visible=bool(visible)
        return visible
    except Exception: return False


def _h76_sync_background_button(panel):
    try:
        bar=getattr(panel,'window_title_bar',None); btn=getattr(bar,'background_btn',None)
        if btn is None: return
        enabled=bool(getattr(panel,'background_check',None) is not None and panel.background_check.isChecked())
        btn.setText('背景')
        btn.setIcon(_h76_palette_icon(15,'#d1a4ab' if enabled else '#9b9496'))
        btn.setIconSize(QSize(15,15)); btn.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
        btn.setToolTip('界面背景 · 选择图片、开关与强度')
        btn.setFixedSize(66,30)
    except Exception: pass


def _h76_title_init(bar,host):
    _h76_title_init_pre(bar,host)
    try: _h76_sync_background_button(host)
    except Exception: pass


def _h76_animate_current_tab(panel,index):
    """One calm page-settle token: opacity only, no decorative slide/zoom."""
    if not bool(getattr(panel,'_settings_loaded',False)) or not panel.isVisible(): return
    try: page=panel.main_tabs.widget(int(index))
    except Exception: page=None
    if page is None: return
    try: panel._clear_tab_fade()
    except Exception: pass
    try:
        effect=QGraphicsOpacityEffect(page); effect.setOpacity(0.84); page.setGraphicsEffect(effect)
        animation=QPropertyAnimation(effect,b'opacity',panel); animation.setDuration(int(H76_UI_PAGE_SETTLE_MS))
        animation.setStartValue(0.84); animation.setEndValue(1.0); animation.setEasingCurve(QEasingCurve.OutCubic)
        animation.finished.connect(lambda p=page,e=effect: panel._finish_tab_fade(p,e))
        panel._tab_fade_page=page; panel._tab_fade_effect=effect; panel._tab_fade_animation=animation; animation.start()
    except Exception:
        try: panel._clear_tab_fade()
        except Exception: pass


def _h76_finish_popup_motion(dlg,effect):
    try:
        effect.setOpacity(1.0); dlg.setGraphicsEffect(None)
    except Exception: pass
    try:
        dlg._h76_popup_fade_anim=None; dlg._h76_popup_move_anim=None; dlg._h76_popup_effect=None
    except Exception: pass


def _h76_show_background_popup(panel):
    if not callable(_h76_background_popup_pre): return
    _h76_background_popup_pre(panel)
    dlg=getattr(panel,'_h73_background_popup',None)
    if dlg is None or not dlg.isVisible(): return
    try:
        for attr in ('_h76_popup_fade_anim','_h76_popup_move_anim'):
            ani=getattr(dlg,attr,None)
            if ani is not None: ani.stop()
        end=dlg.pos(); dlg.move(end.x(),end.y()+int(H76_UI_POPUP_RISE_PX))
        start=dlg.pos(); effect=QGraphicsOpacityEffect(dlg); effect.setOpacity(0.0); dlg.setGraphicsEffect(effect)
        fade=QPropertyAnimation(effect,b'opacity',dlg); fade.setDuration(int(H76_UI_POPUP_ENTER_MS)); fade.setStartValue(0.0); fade.setEndValue(1.0); fade.setEasingCurve(QEasingCurve.OutCubic)
        move=QPropertyAnimation(dlg,b'pos',dlg); move.setDuration(int(H76_UI_POPUP_ENTER_MS)); move.setStartValue(start); move.setEndValue(end); move.setEasingCurve(QEasingCurve.OutCubic)
        fade.finished.connect(lambda d=dlg,e=effect:_h76_finish_popup_motion(d,e))
        dlg._h76_popup_effect=effect; dlg._h76_popup_fade_anim=fade; dlg._h76_popup_move_anim=move
        move.start(); fade.start()
    except Exception:
        try: dlg.setGraphicsEffect(None)
        except Exception: pass


