QLabel#workspaceTitle { font-size:20px; font-weight:700; letter-spacing:0.15px; }
QLabel#workspaceDescription { color:#716c6f; padding-bottom:3px; }
QFrame#settingsCard { background:transparent; border:none; border-top:1px solid rgba(238,229,226,18); border-radius:0px; }
QFrame#h74PreviewCard { background:rgba(255,255,255,3); border:1px solid rgba(238,229,226,22); border-radius:9px; }
