def _h78_control_init(panel, *args, **kwargs):
    _h78_control_init_pre(panel, *args, **kwargs)
    try:
        _h78_sync_interface_button(panel)
        panel._h73_show_background_popup = lambda: _h77_show_interface_popup(panel)
        _h78_rehome_typography_layout(panel)
        _h78_install_nav_indicator(panel)
        _h78_refine_workspace_header(panel)
        panel._page_meta = (
            ('播放','播放器、歌词来源与当前播放状态'),
            ('外观','实时预览、字体、排版、布局、色彩与光效'),
            ('动效','实时预览、入场、退场、运动与空间方向'),
            ('设置','应用行为、同步输出与更新'),
            ('单曲','按歌曲与 QQ / 网易云 / 酷狗 / Spotify 覆盖全局视觉样式'),
        )
        panel._update_workspace_header(panel.main_tabs.currentIndex())
        panel._default_stylesheet = str(getattr(panel, '_default_stylesheet', '') or '') + H78_QSS
        panel._limbus_stylesheet = str(getattr(panel, '_limbus_stylesheet', '') or '') + H78_QSS
        theme = panel._current_ui_theme() if hasattr(panel, '_current_ui_theme') else 'default'
        panel.setStyleSheet(panel._limbus_stylesheet if str(theme) == 'limbus' else panel._default_stylesheet)
        try: _h75_global_filter(panel, panel.settings_filter.text())
        except Exception: pass
    except Exception as exc:
        try: write_error_log('H78工作室导航与排版归位安装失败', exc)
        except Exception: pass


def _h78_activate_ui():
    global _h76_sync_background_button
    try:
        # H76's background-toggle lambda resolves this global at signal time. Rebinding it is
        # what prevents the title utility from ever reverting from "Interface" to "Background".
        _h76_sync_background_button = _h78_sync_interface_button
        if 'PanelTitleBar' in globals() and callable(_h78_title_init_pre):
            PanelTitleBar.__init__ = _h78_title_init
            PanelTitleBar.__init__._limbus_layer = 'H78'
        if 'ControlPanel' in globals() and callable(_h78_control_init_pre):
            ControlPanel._animate_current_tab = _h78_animate_current_tab
            ControlPanel._animate_current_tab._limbus_layer = 'H78'
            ControlPanel.__init__ = _h78_control_init
            ControlPanel.__init__._limbus_layer = 'H78'
            ControlPanel.__init__._limbus_policy = 'studio navigation + visible page transition + H51 typography/layout re-home; config owners preserved; no runtime authority'
    except Exception as exc:
        try: write_error_log('H78工作室壳层激活失败', exc)
        except Exception: pass


if '_h78_activate_ui' in globals(): _h78_activate_ui()


# H79 live lyric shell + smooth snapshot transition -------------------------------------
# H78 proved that a page-wide QGraphicsOpacityEffect is optically visible but can feel
# low-frame-rate on a dense QScrollArea because every animation tick re-composites the full
# widget tree. H79 keeps the H78 information architecture and changes only presentation:
#   * Appearance is renamed back to the product-specific "字幕" / LYRICS destination;
#   * page changes animate a single captured surface with a short 10 px upward settle rather
#     than applying opacity to hundreds of child widgets; no persistent high-frequency timer;
#   * the H74 motion preview follows the active screen refresh rate instead of a fixed 24 ms;
#   * Now Playing gains a lightweight live lyric sample and ambient tint derived only from
#     already-resolved lyric/cover style state. No new network/provider/transport authority.
H79_PAGE_TRANSITION_MS = 165
H79_PAGE_RISE_PX = 10
H79_UI_MAX_REFRESH_HZ = 120.0
H79_UI_MIN_REFRESH_HZ = 60.0
H79_NAV_INDICATOR_MS = 165

_h79_control_init_pre = ControlPanel.__init__ if 'ControlPanel' in globals() else None
_h79_front_status_pre = ControlPanel._refresh_frontend_status if 'ControlPanel' in globals() else None
_h79_apply_visual_pre = ControlPanel._apply_active_visual_style_live if 'ControlPanel' in globals() else None
_h79_h78_move_nav_pre = globals().get('_h78_move_nav_indicator')


def _h79_ui_refresh_hz(panel):
    try:
        screen = panel.screen() or QApplication.primaryScreen()
        hz = float(screen.refreshRate() or 60.0) if screen is not None else 60.0
    except Exception:
        hz = 60.0
    if not math.isfinite(hz) or hz < 30.0:
        hz = 60.0
    return max(float(H79_UI_MIN_REFRESH_HZ), min(float(H79_UI_MAX_REFRESH_HZ), hz))


def _h79_ui_frame_interval(panel):
    # Active only during micro-animations. On a ~60 Hz display this resolves to ~16 ms;
    # high-refresh displays may use ~8 ms without creating a permanent high-frequency timer.
    return max(8, min(16, int(round(1000.0 / _h79_ui_refresh_hz(panel)))))


class H79PageTransitionOverlay(QWidget):
    """Paint one frozen panel-region snapshot instead of re-rendering a dense widget tree."""
    def __init__(self, panel, pixmap, rect, duration_ms=H79_PAGE_TRANSITION_MS, rise_px=H79_PAGE_RISE_PX):
        super().__init__(panel)
        self._panel = panel
        self._pixmap = QPixmap(pixmap)
        self._duration_ms = max(90, int(duration_ms or H79_PAGE_TRANSITION_MS))
        self._rise_px = max(0, int(rise_px or 0))
        self._started = time.monotonic()
        self._timer = QTimer(self)
        try: self._timer.setTimerType(Qt.PreciseTimer)
        except Exception: pass
        self._timer.setInterval(_h79_ui_frame_interval(panel))
        self._timer.timeout.connect(self._tick)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.setGeometry(QRect(rect))
        self.show(); self.raise_(); self._timer.start(); self.update()

    @staticmethod
    def _ease(t):
        t=max(0.0,min(1.0,float(t))); return 1.0-math.pow(1.0-t,3.0)

    def _tick(self):
        elapsed=(time.monotonic()-self._started)*1000.0
        if elapsed >= float(self._duration_ms):
            self._timer.stop(); self.close(); self.deleteLater(); return
        self.update()

    def paintEvent(self, _event):
        if self._pixmap.isNull(): return
        elapsed=(time.monotonic()-self._started)*1000.0
        t=max(0.0,min(1.0,elapsed/float(self._duration_ms)))
        e=self._ease(t)
        dy=int(round(float(self._rise_px)*(1.0-e)))
        p=QPainter(self)
        try:
            p.setRenderHint(QPainter.SmoothPixmapTransform, True)
            # Fill the small uncovered strip from the snapshot itself so custom panel
            # backgrounds remain coherent while the content settles upward.
            if dy>0 and self._pixmap.height()>0:
                top=self._pixmap.copy(0,0,self._pixmap.width(),min(max(1,dy),self._pixmap.height()))
                p.drawPixmap(QRect(0,0,self.width(),dy), top)
            p.drawPixmap(0,dy,self._pixmap)
            # A tiny settling wash gives depth without a page-wide opacity effect.
            wash_alpha=int(round(16.0*(1.0-e)))
            if wash_alpha>0:
                p.fillRect(self.rect(),QColor(5,5,8,wash_alpha))
        finally:
            p.end()


def _h79_clear_page_overlay(panel):
    old=getattr(panel,'_h79_page_overlay',None)
    if old is not None:
        try:
            old._timer.stop(); old.close(); old.deleteLater()
        except Exception: pass
    panel._h79_page_overlay=None


def _h79_capture_settings_region(panel):
    try:
        host=panel.settings_main
        top_left=host.mapTo(panel,host.rect().topLeft())
        rect=QRect(top_left,host.size())
        if rect.width()<=2 or rect.height()<=2: return QPixmap(),QRect()
        return panel.grab(rect),rect
    except Exception:
        return QPixmap(),QRect()


def _h79_animate_current_tab(panel,index):
    """Short, explicit studio settle rendered from one frozen surface."""
    try:
        if callable(_h79_h78_move_nav_pre):
            _h79_h78_move_nav_pre(panel,int(index),bool(panel.isVisible()))
    except Exception: pass
    if not bool(getattr(panel,'_settings_loaded',False)) or not panel.isVisible():
        return
    _h79_clear_page_overlay(panel)
    try:
        # Defer one event turn so the newly selected QScrollArea has completed layout/paint.
        QTimer.singleShot(0,lambda p=panel: _h79_start_page_overlay(p))
    except Exception: pass


def _h79_start_page_overlay(panel):
    if not panel.isVisible(): return
    try:
        pix,rect=_h79_capture_settings_region(panel)
        if pix.isNull() or rect.isNull(): return
        overlay=H79PageTransitionOverlay(panel,pix,rect,H79_PAGE_TRANSITION_MS,H79_PAGE_RISE_PX)
        panel._h79_page_overlay=overlay
    except Exception:
        _h79_clear_page_overlay(panel)


def _h79_refresh_preview_rate(panel):
    try:
        stage=getattr(panel,'h74_motion_preview',None)
        timer=getattr(stage,'_timer',None)
        if timer is not None:
            timer.setInterval(_h79_ui_frame_interval(panel))
    except Exception: pass


def _h79_ambient_color(panel):
    try:
        key=panel._track_identity(getattr(panel,'_loaded_song',''),getattr(panel,'_loaded_artist',''))
        cached=getattr(panel,'_h12_cover_applied',None)
        if cached and cached[0]==key:
            c=QColor(str(cached[1] or ''))
            if c.isValid(): return c
    except Exception: pass
    try:
        c=QColor(getattr(panel.lyric_window,'text_color',QColor('#d1a4ab')))
        if c.isValid(): return c
    except Exception: pass
    return QColor('#d1a4ab')


class H79HeroAmbient(QFrame):
    def __init__(self,hero,panel):
        super().__init__(hero)
        self._hero=hero; self._panel=panel; self._accent=''
        self.setObjectName('h79HeroAmbient')
        self.setAttribute(Qt.WA_TransparentForMouseEvents,True)
        hero.installEventFilter(self)
        self.setGeometry(hero.rect()); self.lower(); self.show()
        self.refresh()

    def eventFilter(self,obj,event):
        if obj is self._hero and event.type() in (QEvent.Resize,QEvent.Show):
            try: self.setGeometry(self._hero.rect()); self.lower()
            except Exception: pass
        return False

    def refresh(self):
        c=_h79_ambient_color(self._panel)
        h,s,v,a=c.getHsv()
        if h>=0:
            c.setHsv(h,max(45,min(165,s)),max(115,min(220,v)))
        key=c.name()
        if key==self._accent: return
        self._accent=key
        r,g,b=c.red(),c.green(),c.blue()
        self.setStyleSheet(
            'QFrame#h79HeroAmbient {'
            f'background:qlineargradient(x1:0,y1:0,x2:1,y2:1, stop:0 rgba({r},{g},{b},22), '
            f'stop:0.38 rgba({r},{g},{b},7), stop:1 rgba(4,5,8,3));'
            'border:none; border-radius:10px; }'
        )


def _h79_refresh_live_lyric(panel):
    try:
        label=getattr(panel,'h79_live_lyric',None)
        if label is None: return
        raw=str(getattr(panel.lyric_window,'full_text','') or '').strip().replace('\n',' ')
        if len(raw)>54: raw=raw[:53].rstrip()+'…'
        if raw!=str(getattr(panel,'_h79_live_lyric_text','') or ''):
            panel._h79_live_lyric_text=raw
            label.setText(raw)
            label.setVisible(bool(raw))
        if raw:
            f=QFont(getattr(panel.lyric_window,'font',QFont()))
            f.setPointSize(max(10,min(13,int(round(max(10,f.pointSize())*0.34)))))
            label.setFont(f)
            c=_h79_ambient_color(panel)
            label.setStyleSheet(f'color:rgba({c.red()},{c.green()},{c.blue()},205); background:transparent;')
        ambient=getattr(panel,'h79_hero_ambient',None)
        if ambient is not None: ambient.refresh()
    except Exception: pass


def _h79_front_status(panel,*args,**kwargs):
    out=_h79_front_status_pre(panel,*args,**kwargs)
    _h79_refresh_live_lyric(panel)
    return out


def _h79_apply_visual(panel,*args,**kwargs):
    out=_h79_apply_visual_pre(panel,*args,**kwargs)
    try: QTimer.singleShot(0,lambda p=panel:_h79_refresh_live_lyric(p))
    except Exception: pass
    return out


def _h79_install_live_hero(panel):
    try:
        hero=panel.findChild(QFrame,'heroCard')
        if hero is None: return
        ambient=H79HeroAmbient(hero,panel); panel.h79_hero_ambient=ambient
        layout=hero.layout()
        sample=QLabel('',hero); sample.setObjectName('h79LiveLyric'); sample.setWordWrap(False)
        sample.setTextInteractionFlags(Qt.TextSelectableByMouse); sample.setVisible(False)
        if layout is not None: layout.addWidget(sample)
        panel.h79_live_lyric=sample; panel._h79_live_lyric_text=''
        _h79_refresh_live_lyric(panel)
    except Exception: pass


def _h79_relabel_lyrics_workspace(panel):
    try:
        panel.main_tabs.setTabText(1,'字幕')
        buttons=list(getattr(panel,'_sidebar_buttons',()) or ())
        if len(buttons)>1:
            buttons[1].setText('字幕'); buttons[1].setToolTip('字幕字体、排版、颜色、材质与实时预览')
        meta=list(getattr(panel,'_page_meta',()) or ())
        if len(meta)>=5:
            meta[1]=('字幕','实时预览、字体、排版、布局、色彩与光效')
            panel._page_meta=tuple(meta)
        panel._update_workspace_header(panel.main_tabs.currentIndex())
        kicker=getattr(panel,'h77_workspace_kicker',None)
        if kicker is not None and panel.main_tabs.currentIndex()==1:
            kicker.setText('02  /  LYRICS')
        # H78 updates the kicker on each change; replace that presentation-only callback's label map.
        panel.main_tabs.currentChanged.connect(lambda i,p=panel: _h79_sync_kicker(p,i))
    except Exception: pass


def _h79_sync_kicker(panel,index):
    labels=('PLAYBACK','LYRICS','MOTION','SYSTEM','SONG OVERRIDE')
    try:
        kicker=getattr(panel,'h77_workspace_kicker',None)
        if kicker is not None:
            i=int(index); word=labels[i] if 0<=i<len(labels) else 'WORKSPACE'
            kicker.setText(f'{i+1:02d}  /  {word}' if 0<=i<5 else word)
    except Exception: pass


