_studio_control_init_pre = getattr(ControlPanel, '__init__', None) if 'ControlPanel' in globals() else None


def _studio_control_init(panel, *args, **kwargs):
    if callable(_studio_control_init_pre):
        _studio_control_init_pre(panel, *args, **kwargs)
    panel._default_stylesheet += STUDIO_QSS
    panel._limbus_stylesheet += STUDIO_QSS
    panel.setStyleSheet('')
    panel.setStyleSheet(panel._default_stylesheet)
    panel.window_title_bar.build.setText('LYRIC STUDIO')
    panel.manager_tag.setText('MUSIC, IN YOUR WORDS')
    panel.manager_tag.show()
    hero = panel.findChild(QFrame, 'heroCard')
    hero.layout().setContentsMargins(22, 18, 170, 20)
    hero.layout().setSpacing(4)
    panel.front_track_label.setWordWrap(True)
    panel.front_detail_label.setWordWrap(True)
    panel.front_sync_badge.setMinimumWidth(48)
    panel.top_nav.layout().setContentsMargins(5, 5, 5, 5)
    panel.findChild(QWidget, 'panelContent').layout().setSpacing(14)
    for card in panel.findChildren(QFrame, 'settingsCard'):
        card.layout().setContentsMargins(18, 14, 18, 16)
        card.layout().setSpacing(10)
        card.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Maximum)
    for button in panel._sidebar_buttons:
        button.setMinimumHeight(24)
    for button, key in ((panel.start_btn, 'play'),):
        button.setIcon(_h74_icon(key, 16, '#223024' if key == 'play' else '#b9c5a9'))
        button.setIconSize(QSize(16, 16))
    panel.start_btn.setAccessibleName('开始显示桌面歌词')
    panel.stop_btn.setAccessibleName('停止显示桌面歌词')
    panel.settings_filter.setAccessibleName('搜索全部设置')
    panel.h74_appearance_preview.setToolTip('调整下方参数，即时查看字幕效果。')
    panel.h74_motion_preview.setToolTip('点击重播，查看当前退场动效。')
    # Scale from the completed interface, not the early H12 widget/layout snapshot.
    existing_widgets = dict(panel._h12_widget_baseline)
    panel._h12_widget_baseline = [(w, existing_widgets.get(w, (float(w.font().pointSizeF()), w.minimumWidth(), w.minimumHeight(), w.maximumWidth(), w.maximumHeight()))) for w in panel.findChildren(QWidget)]
    existing_layouts = dict(panel._h12_layout_baseline)
    changed_layouts = {hero.layout(), panel.top_nav.layout(), panel.findChild(QWidget, 'panelContent').layout()}
    changed_layouts.update(card.layout() for card in panel.findChildren(QFrame, 'settingsCard'))
    panel._h12_layout_baseline = []
    for layout in panel.findChildren(QVBoxLayout) + panel.findChildren(QHBoxLayout):
        margins = layout.contentsMargins()
        baseline = (margins.left(), margins.top(), margins.right(), margins.bottom(), layout.spacing())
        panel._h12_layout_baseline.append((layout, baseline if layout in changed_layouts else existing_layouts.get(layout, baseline)))
    _h12_apply_scale(panel, panel._h12_ui_scale_pct)
    panel.h79_hero_ambient.update()
    QTimer.singleShot(0, lambda: _studio_finish_style(panel))


def _studio_finish_style(panel):
    _h12_apply_scale(panel, panel._h12_ui_scale_pct)
    _studio_adapt_layout(panel)
    _h78_move_nav_indicator(panel, panel.main_tabs.currentIndex(), False)


_studio_resize_pre = getattr(ControlPanel, 'resizeEvent', None) if 'ControlPanel' in globals() else None


def _studio_resize(panel, event):
    if callable(_studio_resize_pre):
        _studio_resize_pre(panel, event)
    _studio_adapt_layout(panel)


def _studio_adapt_layout(panel):
    if not hasattr(panel, 'h79_hero_ambient'):
        return
    for button in panel._sidebar_buttons:
        button.setMinimumHeight(button.sizeHint().height())
    compact = panel.height() < 850
    panel.manager_tag.setVisible(not compact)
    panel.workspace_description.setVisible(not compact)
    hero = panel.findChild(QFrame, 'heroCard')
    hero.layout().setContentsMargins(22, 12 if compact else 18, 170 if panel.width() >= 800 else 22, 12 if compact else 20)
    panel.h79_hero_ambient.setVisible(panel.width() >= 800)
    for preview in (panel.h74_appearance_preview, panel.h74_motion_preview):
        preview.setMinimumHeight(112 if compact else 172)
    for card in (panel.h80_appearance_stage_card, panel.h80_motion_stage_card):
        card.setMinimumHeight(170 if compact else 205)
    panel.h80_studio_stage_host.setMinimumHeight(200 if compact else 230)


if 'ControlPanel' in globals():
    if callable(_studio_resize_pre):
        ControlPanel.resizeEvent = _studio_resize
    if callable(_studio_control_init_pre):
        ControlPanel.__init__ = _studio_control_init
        ControlPanel.__init__._limbus_layer = 'STUDIO'
if 'H79HeroAmbient' in globals():
    H79HeroAmbient.paintEvent = _studio_ambient_paint


# H86 frameless vertical resize recovery --------------------------------------
# Control-panel presentation only. Preserve playback/seek/provider/lyric authority.
# The frameless shell already exposes WM_NCHITTEST edges, but the custom title bar
# can receive the top-edge mouse press first on some Qt/Windows paths and interpret
# it as a move gesture. When the bottom edge is already off-screen that leaves no
# reachable vertical resize handle. H86 reserves the top border for native resize,
# and bounds the normal window height to the current monitor work area.
H86_TOP_RESIZE_BORDER_PX = 8
H86_VERTICAL_SCREEN_GUARD = True

_h86_title_press_pre = PanelTitleBar.mousePressEvent if 'PanelTitleBar' in globals() else None
_h86_control_init_pre = ControlPanel.__init__ if 'ControlPanel' in globals() else None
_h86_control_move_pre = getattr(ControlPanel, 'moveEvent', None) if 'ControlPanel' in globals() else None


def _h86_screen_for_panel(panel):
    try:
        handle = panel.windowHandle()
        screen = handle.screen() if handle is not None else None
        if screen is not None:
            return screen
    except Exception:
        pass
    try:
        center = panel.frameGeometry().center()
        finder = getattr(QApplication, 'screenAt', None)
        if callable(finder):
            screen = finder(center)
            if screen is not None:
                return screen
    except Exception:
        pass
    try:
        return QApplication.primaryScreen()
    except Exception:
        return None


def _h86_refresh_vertical_limit(panel, rescue=False):
    if panel is None or panel.isMaximized():
        return False
    screen = _h86_screen_for_panel(panel)
    if screen is None:
        return False
    try:
        available = screen.availableGeometry()
        max_h = max(int(panel.minimumHeight()), int(available.height()))
        if int(panel.maximumHeight()) != max_h:
            panel.setMaximumHeight(max_h)
        if rescue and panel.height() > max_h:
            panel.resize(panel.width(), max_h)
        return True
    except Exception:
        return False


def _h86_try_top_system_resize(bar, event):
    if event.button() != Qt.LeftButton:
        return False
    host = getattr(bar, '_host', None)
    if host is None or host.isMaximized():
        return False
    try:
        pos = host.mapFromGlobal(event.globalPos())
        dpr = max(1.0, float(host.devicePixelRatioF()))
        border = max(5, int(round(float(getattr(host, '_frame_resize_border_px', H86_TOP_RESIZE_BORDER_PX)) * dpr)))
        # Only reserve the real top resize band. The rest of the custom title bar
        # remains a move surface exactly as before.
        if pos.y() < 0 or pos.y() >= border:
            return False
        edge = Qt.TopEdge
        hit = 12  # HTTOP
        if pos.x() < border:
            edge = Qt.TopEdge | Qt.LeftEdge
            hit = 13  # HTTOPLEFT
        elif pos.x() >= max(0, host.width() - border):
            edge = Qt.TopEdge | Qt.RightEdge
            hit = 14  # HTTOPRIGHT
        handle = host.windowHandle()
        starter = getattr(handle, 'startSystemResize', None) if handle is not None else None
        if callable(starter):
            try:
                if starter(edge):
                    bar._drag_offset = None
                    return True
            except Exception:
                pass
        if os.name == 'nt':
            try:
                user32 = ctypes.windll.user32
                user32.ReleaseCapture()
                user32.SendMessageW(int(host.winId()), 0x00A1, int(hit), 0)  # WM_NCLBUTTONDOWN
                bar._drag_offset = None
                return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def _h86_title_press(bar, event):
    if _h86_try_top_system_resize(bar, event):
        event.accept()
        return
    if callable(_h86_title_press_pre):
        return _h86_title_press_pre(bar, event)


def _h86_control_init(panel, *args, **kwargs):
    if callable(_h86_control_init_pre):
        _h86_control_init_pre(panel, *args, **kwargs)
    # Run once after Qt has attached the native window/screen. This also rescues
    # an oversized geometry restored from an earlier broken session.
    QTimer.singleShot(0, lambda p=panel: _h86_refresh_vertical_limit(p, rescue=True))


def _h86_control_move(panel, event):
    out = _h86_control_move_pre(panel, event) if callable(_h86_control_move_pre) else None
    # Moving between monitors can change the available work-area height.
    _h86_refresh_vertical_limit(panel, rescue=True)
    return out


try:
    if 'PanelTitleBar' in globals() and callable(_h86_title_press_pre):
        PanelTitleBar.mousePressEvent = _h86_title_press
        PanelTitleBar.mousePressEvent._limbus_layer = 'H86'
        PanelTitleBar.mousePressEvent._limbus_policy = 'top-border-native-resize-before-title-drag'
    if 'ControlPanel' in globals() and callable(_h86_control_init_pre):
        ControlPanel.__init__ = _h86_control_init
        ControlPanel.__init__._limbus_layer = 'H86'
    if 'ControlPanel' in globals() and callable(_h86_control_move_pre):
        ControlPanel.moveEvent = _h86_control_move
        ControlPanel.moveEvent._limbus_layer = 'H86'
except Exception as exc:
    try:
        write_error_log('H86无边框窗口竖向缩放恢复安装失败', exc)
    except Exception:
        pass


