def _h88_song_variants(song):
    text = str(song or '').strip()
    if not text:
        return []
    out = [text]
    base = re.sub(r'\s*[\(（][^()（）]{1,48}[\)）]\s*$', '', text).strip()
    if base and base not in out:
        out.append(base)
    return out


def _h88_artist_variants(artist):
    text = str(artist or '').strip()
    if not text:
        return ['']
    out = [text]
    primary = re.split(r'[/,&，、;；|]+', text, maxsplit=1)[0].strip()
    primary = re.sub(r'\s*[\(（][^()（）]{1,48}[\)）]\s*$', '', primary).strip()
    if primary and primary not in out:
        out.append(primary)
    return out


def _h88_save_art_bytes(raw, out_path):
    if not raw or not out_path:
        return ''
    image = QImage.fromData(raw)
    if image.isNull():
        return ''
    side = min(image.width(), image.height())
    image = image.copy(max(0, (image.width()-side)//2), max(0, (image.height()-side)//2), side, side)
    image = image.scaled(420, 420, Qt.KeepAspectRatioByExpanding, Qt.SmoothTransformation)
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    tmp = out_path + '.tmp.jpg'
    if not image.save(tmp, 'JPG', 91):
        return ''
    os.replace(tmp, out_path)
    return out_path


def _h88_choose_qq_cover_row(rows, song, artist=''):
    rows = [row for row in list(rows or []) if isinstance(row, dict)]
    if not rows:
        return None
    def norm(value):
        return re.sub(r'[^0-9a-z\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]+', '', str(value or '').casefold())
    target = norm(song); wanted_artist = str(artist or '').strip()
    best = None; best_score = -10**9
    for row in rows:
        title = str(row.get('songname') or row.get('name') or '')
        title_norm = norm(title)
        if target and title_norm and not (target == title_norm or target in title_norm or title_norm in target):
            continue
        actual_artist = _artist_text({'singer': row.get('singer', [])}) if '_artist_text' in globals() else ''
        artist_ok = True
        if wanted_artist:
            try: artist_ok = bool(_artist_alias_match(wanted_artist, actual_artist)[0])
            except Exception: artist_ok = norm(wanted_artist) in norm(actual_artist) or norm(actual_artist) in norm(wanted_artist)
        if not artist_ok:
            continue
        score = 100 if target and title_norm == target else 60
        if wanted_artist and actual_artist: score += 35
        if score > best_score:
            best_score = score; best = row
    return best


def _h88_fetch_qq_art(http, song, artist, headers, out_path):
    qq_headers = dict(headers); qq_headers['Referer'] = 'https://y.qq.com/'
    for sname in _h88_song_variants(song):
        for aname in _h88_artist_variants(artist):
            try:
                resp = _r2_qq_search_request(
                    http, 'https://c.y.qq.com/soso/fcgi-bin/client_search_cp',
                    params={'p':1, 'n':12, 'w':f'{sname} {aname}'.strip(), 'format':'json'},
                    headers=qq_headers, timeout=4
                )
                resp.raise_for_status()
                rows = (((resp.json().get('data') or {}).get('song') or {}).get('list') or [])
                hit = _h88_choose_qq_cover_row(rows, sname, aname)
                if not isinstance(hit, dict):
                    continue
                album_mid = str(hit.get('albummid') or hit.get('albumMID') or '').strip()
                song_mid = str(hit.get('songmid') or '').strip()
                if not album_mid and song_mid:
                    try:
                        detail = http.get('https://c.y.qq.com/v8/fcg-bin/fcg_play_single_song.fcg',
                            params={'songmid':song_mid, 'format':'json'}, headers=qq_headers, timeout=4)
                        detail.raise_for_status(); data = detail.json().get('data') or []
                        if data and isinstance(data[0], dict):
                            row = data[0]; album = row.get('album') if isinstance(row.get('album'), dict) else {}
                            album_mid = str(row.get('albummid') or album.get('mid') or '').strip()
                    except Exception:
                        pass
                if not album_mid:
                    continue
                url = f'https://y.gtimg.cn/music/photo_new/T002R500x500M000{album_mid}.jpg'
                img = http.get(url, headers=qq_headers, timeout=4)
                img.raise_for_status()
                path = _h88_save_art_bytes(img.content, out_path)
                if path:
                    return path
            except Exception:
                continue
    return ''


def _h88_fetch_netease_art(http, song, artist, headers, preferred_id, out_path):
    seen = set()
    for sname in _h88_song_variants(song):
        for aname in _h88_artist_variants(artist):
            query = f'{sname} {aname}'.strip()
            if not query or query in seen:
                continue
            seen.add(query)
            try:
                resp = http.post('https://music.163.com/api/search/get/web',
                    data={'s':query, 'type':1, 'limit':10}, headers=headers, timeout=4)
                resp.raise_for_status(); rows = ((resp.json().get('result') or {}).get('songs') or [])
                hit = _h16_choose_cover_row(rows, sname, aname, preferred_id)
                if not hit:
                    continue
                url = _h16_cover_pic_url(hit)
                if not url:
                    continue
                img = http.get(url, headers=headers, timeout=4); img.raise_for_status()
                path = _h88_save_art_bytes(img.content, out_path)
                if path:
                    return path
            except Exception:
                continue
    return ''


def _h88_clear_stale_cover_if_pending(panel, key):
    try:
        current = panel._track_identity(getattr(panel, '_loaded_song', ''), getattr(panel, '_loaded_artist', ''))
        if str(current) != str(key):
            return
        ambient = getattr(panel, 'h79_hero_ambient', None)
        if ambient is None or str(getattr(ambient, '_h87_cover_key', '') or '') == str(key):
            return
        old = QPixmap(getattr(ambient, '_h87_cover', QPixmap()))
        if old.isNull():
            return
        ambient._h87_prev_cover = old
        ambient._h87_cover = QPixmap()
        ambient._h87_cover_key = ''
        ambient._h87_cover_started = time.monotonic()
        timer = getattr(ambient, '_h87_timer', None)
        if timer is not None and not timer.isActive():
            timer.start()
        ambient.update()
    except Exception:
        pass


def _h88_request_art(panel, song, artist=''):
    try:
        song = str(song or '').strip(); artist = str(artist or '').strip()
        if not song:
            return
        key = panel._track_identity(song, artist)
        if not key:
            return
        ambient = getattr(panel, 'h79_hero_ambient', None)
        if ambient is not None and str(getattr(ambient, '_h87_cover_key', '') or '') == str(key) and not getattr(ambient, '_h87_cover', QPixmap()).isNull():
            return
        cached = _h87_cached_art_path(key)
        if cached and _h87_set_panel_art(panel, cached, key):
            neg = dict(getattr(panel, '_h88_art_negative', {}) or {}); neg.pop(key, None); panel._h88_art_negative = neg
            return
        negative = dict(getattr(panel, '_h88_art_negative', {}) or {})
        if time.monotonic() < float(negative.get(key, 0.0) or 0.0):
            return
        active = dict(getattr(panel, '_h87_art_active', {}) or {})
        if key in active:
            return
        QTimer.singleShot(int(H88_COVER_CLEAR_GRACE_MS), lambda p=panel, k=str(key): _h88_clear_stale_cover_if_pending(p, k))
        serial = int(getattr(panel, '_h87_art_serial', 0) or 0) + 1
        panel._h87_art_serial = serial; active[key] = serial; panel._h87_art_active = active
        meta = dict(getattr(panel, '_active_lyric_provider_meta', {}) or {})
        preferred_id = str(meta.get('netease_song_id') or '').strip()
        out_path = _h87_art_file_for_key(key); result_queue = getattr(panel, '_h87_art_results', None)
        process = str(getattr(getattr(panel, 'media_sync', None), '_process_hint', '') or '').lower()
        order = ('qq','netease') if process == 'qqmusic' else ('netease','qq')
        def work():
            path = ''; err = ''
            try:
                http = globals().get('requests')
                if http is None: raise RuntimeError('http-client-unavailable')
                headers = {'User-Agent':'Mozilla/5.0', 'Referer':'https://music.163.com/'}
                for provider in order:
                    if provider == 'qq': path = _h88_fetch_qq_art(http, song, artist, headers, out_path)
                    else: path = _h88_fetch_netease_art(http, song, artist, headers, preferred_id, out_path)
                    if path: break
                if not path: raise RuntimeError('cover-not-found-after-qq+netease')
            except Exception as exc:
                err = f'{type(exc).__name__}: {exc}'
            try:
                if result_queue is not None: result_queue.put((str(key), int(serial), str(path), str(err)))
            except Exception: pass
        threading.Thread(target=work, name='LimbusLyric-H88HeroCover', daemon=True).start()
    except Exception as exc:
        try: write_error_log('H88唱片封面请求失败', exc)
        except Exception: pass


def _h88_poll_art_results(panel):
    q = getattr(panel, '_h87_art_results', None)
    if q is None:
        return
    changed = False
    while True:
        try: key, serial, path, err = q.get_nowait()
        except queue.Empty: break
        except Exception: break
        active = dict(getattr(panel, '_h87_art_active', {}) or {})
        if int(active.get(str(key), 0) or 0) != int(serial or 0):
            continue
        active.pop(str(key), None); panel._h87_art_active = active
        negative = dict(getattr(panel, '_h88_art_negative', {}) or {})
        current = panel._track_identity(getattr(panel, '_loaded_song', ''), getattr(panel, '_loaded_artist', ''))
        if path:
            negative.pop(str(key), None)
            if str(current) == str(key):
                changed = _h87_set_panel_art(panel, path, key) or changed
        else:
            negative[str(key)] = time.monotonic() + float(H88_COVER_NEGATIVE_RETRY_SEC)
        panel._h88_art_negative = negative
        if err:
            try: write_error_log('H88唱片封面获取失败', detail=f'key={key} | retry={int(H88_COVER_NEGATIVE_RETRY_SEC)}s | error={err}')
            except Exception: pass
    if changed:
        _h87_prune_art_cache()


_H88_QWIDGET_BASE = globals().get('QWidget', object)
class H88PageTransitionOverlay(_H88_QWIDGET_BASE):
    """Retire one old-page snapshot and reveal the already-live new page beneath it."""
    def __init__(self, panel, old_pix, _new_pix, rect, direction=1):
        super().__init__(panel)
        self._panel = panel; self._old = QPixmap(old_pix)
        self._direction = -1 if int(direction) < 0 else 1
        self._started = time.monotonic(); self._duration = int(H88_PAGE_TRANSITION_MS)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        try: self.setAttribute(Qt.WA_TranslucentBackground, True)
        except Exception: pass
        self.setGeometry(QRect(rect)); self.show(); self.raise_()
        timer = QTimer(self)
        try: timer.setTimerType(Qt.PreciseTimer)
        except Exception: pass
        timer.setInterval(_h79_ui_frame_interval(panel) if '_h79_ui_frame_interval' in globals() else 16)
        timer.timeout.connect(self._tick); self._timer = timer; timer.start(); self.update()

    @staticmethod
    def _ease(t):
        t = max(0.0, min(1.0, float(t))); return 1.0 - math.pow(1.0-t, 3.4)

    def _tick(self):
        if (time.monotonic()-self._started)*1000.0 >= float(self._duration):
            self._timer.stop(); self.close(); self.deleteLater()
            try: QTimer.singleShot(0, lambda p=self._panel: _h87_refresh_page_snapshot(p))
            except Exception: pass
            return
        self.update()

    def paintEvent(self, _event):
        if self._old.isNull():
            return
        elapsed = (time.monotonic()-self._started)*1000.0
        t = max(0.0, min(1.0, elapsed/float(max(1, self._duration))))
        e = self._ease(t); d = float(self._direction)
        alpha = max(0.0, min(1.0, math.pow(1.0-e, 1.08)))
        p = QPainter(self); p.setRenderHint(QPainter.SmoothPixmapTransform, True)
        p.setOpacity(alpha)
        p.drawPixmap(QPointF(-d*float(H88_PAGE_SHIFT_PX)*e, 0.0), self._old)
        p.end()


def _h88_on_page_changed(panel, index):
    try:
        idx = int(index)
        primed_at = float(getattr(panel, '_h87_transition_primed_at', 0.0) or 0.0)
        primed_fresh = primed_at > 0.0 and time.monotonic() - primed_at <= 1.2
        if primed_fresh:
            old_index = int(getattr(panel, '_h87_transition_old_index', idx) or idx)
            old_pix = QPixmap(getattr(panel, '_h87_transition_old_pix', QPixmap()))
            rect = QRect(getattr(panel, '_h87_transition_old_rect', QRect()))
        else:
            old_index = int(getattr(panel, '_h87_page_index', idx) or idx)
            old_pix = QPixmap(getattr(panel, '_h87_page_snapshot', QPixmap()))
            host = getattr(panel, 'settings_main', None)
            if host is not None:
                top_left = host.mapTo(panel, host.rect().topLeft()); rect = QRect(top_left, host.size())
            else: rect = QRect()
        panel._h87_transition_primed_at = 0.0; panel._h87_transition_old_pix = QPixmap()
        _h87_clear_page_transition(panel)
        panel._h87_page_index = idx
        if not bool(getattr(panel, '_settings_loaded', False)) or not panel.isVisible() or old_pix.isNull() or rect.isNull() or idx == old_index:
            QTimer.singleShot(0, lambda p=panel: _h87_refresh_page_snapshot(p)); return
        overlay = H88PageTransitionOverlay(panel, old_pix, QPixmap(), rect, 1 if idx > old_index else -1)
        panel._h87_page_overlay = overlay
    except Exception:
        QTimer.singleShot(0, lambda p=panel: _h87_refresh_page_snapshot(p))


def _h88_preview_dimensions(expanded):
    if expanded:
        return H88_PREVIEW_EXPANDED_STAGE_H, H88_PREVIEW_EXPANDED_HOST_H
    return H88_PREVIEW_COMPACT_STAGE_H, H88_PREVIEW_COMPACT_HOST_H


def _h88_apply_preview_mode(panel):
    try:
        expanded = bool(getattr(panel, '_h88_preview_expanded', H88_PREVIEW_DEFAULT_EXPANDED))
        stage_h, host_h = _h88_preview_dimensions(expanded)
        for stage in (getattr(panel, 'h74_appearance_preview', None), getattr(panel, 'h74_motion_preview', None)):
            if stage is not None:
                stage.setMinimumHeight(int(stage_h)); stage.setMaximumHeight(int(stage_h))
        for card in (getattr(panel, 'h80_appearance_stage_card', None), getattr(panel, 'h80_motion_stage_card', None)):
            if card is not None:
                card.setMinimumHeight(max(116, int(stage_h)+34)); card.setMaximumHeight(max(116, int(stage_h)+34))
        host = getattr(panel, 'h80_studio_stage_host', None)
        if host is not None:
            host.setMinimumHeight(int(host_h)); host.setMaximumHeight(int(host_h))
        for btn in list(getattr(panel, '_h88_preview_buttons', ()) or ()):
            try:
                btn.setText('收起预览' if expanded else '展开预览')
                btn.setToolTip('把更多高度留给设置项' if expanded else '临时放大效果预览')
            except Exception: pass
    except Exception:
        pass


def _h88_toggle_preview(panel):
    panel._h88_preview_expanded = not bool(getattr(panel, '_h88_preview_expanded', H88_PREVIEW_DEFAULT_EXPANDED))
    _h88_apply_preview_mode(panel)
    if bool(getattr(panel, '_settings_loaded', False)):
        try: panel._schedule_config_save()
        except Exception: pass


def _h88_install_preview_controls(panel):
    buttons = []
    for card in (getattr(panel, 'h80_appearance_stage_card', None), getattr(panel, 'h80_motion_stage_card', None)):
        try:
            layout = card.layout() if card is not None else None
            header = layout.itemAt(0).layout() if layout is not None and layout.count() else None
            if header is None: continue
            btn = QToolButton(card); btn.setObjectName('h88PreviewSizeButton'); btn.setCursor(Qt.PointingHandCursor)
            btn.clicked.connect(lambda _checked=False, p=panel: _h88_toggle_preview(p))
            header.insertWidget(0, btn); buttons.append(btn)
        except Exception:
            pass
    panel._h88_preview_buttons = buttons
    _h88_apply_preview_mode(panel)


def _h88_cards_for_page(panel, index):
    try:
        area = panel.main_tabs.widget(int(index)); page = area.widget() if hasattr(area, 'widget') else None
        layout = page.layout() if page is not None else None
        out = []
        if layout is not None:
            for i in range(layout.count()):
                w = layout.itemAt(i).widget()
                if isinstance(w, QFrame) and w.objectName() == 'settingsCard':
                    out.append(w)
        return out
    except Exception:
        return []


def _h88_scroll_to_card(panel, index, card):
    try:
        area = panel.main_tabs.widget(int(index)); page = area.widget(); bar = area.verticalScrollBar()
        pos = card.mapTo(page, QPoint(0, 0)).y()
        target = max(bar.minimum(), min(bar.maximum(), int(pos)-8))
        old = getattr(panel, '_h88_section_scroll_anim', None)
        if old is not None: old.stop()
        ani = QPropertyAnimation(bar, b'value', panel); ani.setDuration(int(H88_SECTION_SCROLL_MS))
        ani.setStartValue(bar.value()); ani.setEndValue(target); ani.setEasingCurve(QEasingCurve.OutCubic)
        panel._h88_section_scroll_anim = ani; ani.start()
    except Exception:
        pass


def _h88_update_section_rail(panel, index):
    rail = getattr(panel, 'h88_section_rail', None); layout = rail.layout() if rail is not None else None
    if rail is None or layout is None:
        return
    idx = int(index)
    visible = idx in (1, 2)
    rail.setVisible(visible)
    if not visible:
        return
    while layout.count():
        item = layout.takeAt(0); w = item.widget()
        if w is not None: w.deleteLater()
    cards = _h88_cards_for_page(panel, idx)
    for card in cards:
        title = _h74_card_title(card) if '_h74_card_title' in globals() else ''
        if not title: continue
        btn = QPushButton(title, rail); btn.setObjectName('h88SectionChip'); btn.setCheckable(False); btn.setCursor(Qt.PointingHandCursor)
        btn.clicked.connect(lambda _checked=False, p=panel, i=idx, c=card: _h88_scroll_to_card(p, i, c))
        layout.addWidget(btn)
    layout.addStretch()


def _h88_install_section_rail(panel):
    try:
        rail = QFrame(panel.settings_shell); rail.setObjectName('h88SectionRail')
        layout = QHBoxLayout(rail); layout.setContentsMargins(0, 0, 0, 8); layout.setSpacing(6)
        shell_layout = panel.settings_shell.layout()
        stage = getattr(panel, 'h80_studio_stage_host', None)
        at = shell_layout.indexOf(stage) if stage is not None else shell_layout.indexOf(panel.settings_main)
        shell_layout.insertWidget(max(0, at), rail)
        panel.h88_section_rail = rail
        panel.main_tabs.currentChanged.connect(lambda i, p=panel: _h88_update_section_rail(p, i))
        _h88_update_section_rail(panel, panel.main_tabs.currentIndex())
    except Exception as exc:
        try: write_error_log('H88设置分区导航安装失败', exc)
        except Exception: pass


def _h88_append_qss(panel):
    try:
        theme = _h87_frontend_theme(panel) if '_h87_frontend_theme' in globals() else 'studio'
        extra = H88_CLASSIC_QSS if theme == 'classic' else H88_STUDIO_QSS
        style = str(panel.styleSheet() or '')
        if 'QFrame#h88SectionRail' not in style:
            panel.setStyleSheet(style + extra)
    except Exception:
        pass


_h88_frontend_theme_pre = globals().get('_h87_apply_frontend_theme')
def _h88_apply_frontend_theme(panel, theme=None, save=False):
    out = _h88_frontend_theme_pre(panel, theme, save) if callable(_h88_frontend_theme_pre) else None
    _h88_append_qss(panel)
