# --- Screenshot-free page continuity -------------------------------------------------
_H89_QWIDGET_BASE = globals().get('QWidget', object)
class H89PageVeil(_H89_QWIDGET_BASE):
    """A tiny paint-only focus sweep; never snapshots or re-renders the settings page."""
    def __init__(self, panel, rect, direction=1):
        super().__init__(panel)
        self._panel = panel
        self._direction = -1 if int(direction) < 0 else 1
        self._started = time.monotonic()
        self._duration = int(H89_PAGE_VEIL_MS)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        try: self.setAttribute(Qt.WA_TranslucentBackground, True)
        except Exception: pass
        self.setGeometry(QRect(rect)); self.show(); self.raise_()
        timer = QTimer(self)
        try: timer.setTimerType(Qt.PreciseTimer)
        except Exception: pass
        timer.setInterval(_h79_ui_frame_interval(panel) if '_h79_ui_frame_interval' in globals() else 16)
        timer.timeout.connect(self._tick); self._timer = timer; timer.start(); self.update()

    @staticmethod
    def _ease(t):
        t = max(0.0, min(1.0, float(t)))
        return 1.0 - math.pow(1.0-t, 3.1)

    def _tick(self):
        if (time.monotonic()-self._started)*1000.0 >= float(self._duration):
            self._timer.stop(); self.close(); self.deleteLater(); return
        self.update()

    def paintEvent(self, _event):
        elapsed = (time.monotonic()-self._started)*1000.0
        t = max(0.0, min(1.0, elapsed/float(max(1, self._duration))))
        e = self._ease(t)
        rect = QRectF(self.rect())
        if rect.width() <= 1.0 or rect.height() <= 1.0: return
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing, True)
        classic = _h87_frontend_theme(self._panel) == 'classic' if '_h87_frontend_theme' in globals() else False
        accent = QColor('#c88f9a' if classic else '#d3b66f')
        # One narrow moving veil plus a very light whole-surface settle. This is deliberately
        # cheaper than compositing a captured 700x500+ page every frame.
        p.fillRect(rect, QColor(accent.red(), accent.green(), accent.blue(), int(round(12.0*(1.0-e)))))
        span = max(34.0, min(96.0, rect.width()*0.12))
        start = -span if self._direction > 0 else rect.width()
        end = rect.width() if self._direction > 0 else -span
        x = start + (end-start)*e
        grad = QLinearGradient(QPointF(x,0.0), QPointF(x+span*self._direction,0.0))
        if self._direction > 0:
            grad.setColorAt(0.0, QColor(accent.red(),accent.green(),accent.blue(),0))
            grad.setColorAt(0.55, QColor(accent.red(),accent.green(),accent.blue(),22))
            grad.setColorAt(1.0, QColor(accent.red(),accent.green(),accent.blue(),0))
        else:
            grad.setColorAt(0.0, QColor(accent.red(),accent.green(),accent.blue(),0))
            grad.setColorAt(0.45, QColor(accent.red(),accent.green(),accent.blue(),22))
            grad.setColorAt(1.0, QColor(accent.red(),accent.green(),accent.blue(),0))
        p.fillRect(rect, grad); p.end()


def _h89_clear_page_veil(panel):
    old = getattr(panel, '_h89_page_veil', None)
    if old is not None:
        try: old._timer.stop(); old.close(); old.deleteLater()
        except Exception: pass
    panel._h89_page_veil = None


def _h89_prime_page_transition(panel):
    # Keep only semantic direction ownership; do not grab any workspace pixels.
    try:
        panel._h89_transition_old_index = int(panel.main_tabs.currentIndex())
        panel._h89_transition_primed_at = time.monotonic()
    except Exception:
        pass


def _h89_refresh_page_snapshot(_panel):
    # H87/H88 callers may still invoke this name. H89 intentionally owns no page snapshots.
    return None


def _h89_on_page_changed(panel, index):
    try:
        idx = int(index)
        old_idx = int(getattr(panel, '_h89_transition_old_index', getattr(panel, '_h87_page_index', idx)) or idx)
        panel._h89_transition_old_index = idx
        panel._h87_page_index = idx
        _h89_clear_page_veil(panel)
        if not bool(getattr(panel, '_settings_loaded', False)) or not panel.isVisible() or idx == old_idx:
            return
        host = getattr(panel, 'settings_main', None)
        if host is None: return
        tl = host.mapTo(panel, host.rect().topLeft()); rect = QRect(tl, host.size())
        if rect.width() < 8 or rect.height() < 8: return
        veil = H89PageVeil(panel, rect, 1 if idx > old_idx else -1)
        panel._h89_page_veil = veil
        try:
            if '_h80_run_micro_reveal' in globals(): _h80_run_micro_reveal(panel, idx)
        except Exception: pass
    except Exception:
        pass


# --- Preview becomes a true disclosure rail -----------------------------------------
def _h89_preview_current_card(panel):
    idx = int(panel.main_tabs.currentIndex()) if hasattr(panel, 'main_tabs') else -1
    return getattr(panel, 'h80_appearance_stage_card', None) if idx == 1 else getattr(panel, 'h80_motion_stage_card', None) if idx == 2 else None


def _h89_preview_header_widgets(panel, card):
    cache = getattr(panel, '_h89_preview_header_widgets', None)
    if not isinstance(cache, dict):
        cache = {}; panel._h89_preview_header_widgets = cache
    key = id(card)
    if key in cache: return cache[key]
    widgets = []
    try:
        layout = card.layout(); header = layout.itemAt(0).layout() if layout is not None and layout.count() else None
        if header is not None:
            for i in range(header.count()):
                w = header.itemAt(i).widget()
                if w is not None and w.objectName() not in ('h89PreviewRailButton','h88PreviewSizeButton'):
                    widgets.append(w)
    except Exception: pass
    cache[key] = widgets
    return widgets


def _h89_preview_target_heights(opened):
    return (H89_PREVIEW_OPEN_HOST_H, H89_PREVIEW_OPEN_CARD_H) if opened else (H89_PREVIEW_CLOSED_HOST_H, H89_PREVIEW_CLOSED_CARD_H)


def _h89_finish_preview_height(panel, opened, host, card, host_h, card_h):
    try:
        host.setMaximumHeight(int(host_h)); card.setMaximumHeight(int(card_h))
        if not opened:
            stage = getattr(panel, 'h74_appearance_preview', None) if card is getattr(panel,'h80_appearance_stage_card',None) else getattr(panel,'h74_motion_preview',None)
            if stage is not None: stage.hide()
            for w in _h89_preview_header_widgets(panel, card): w.hide()
        panel._h89_preview_animations = []
    except Exception: pass


def _h89_apply_preview_state(panel, animate=False):
    try:
        host = getattr(panel, 'h80_studio_stage_host', None)
        card = _h89_preview_current_card(panel)
        if host is None or card is None: return
        opened = bool(getattr(panel, '_h89_preview_open', False))
        host_h, card_h = _h89_preview_target_heights(opened)
        stage = getattr(panel, 'h74_appearance_preview', None) if card is getattr(panel,'h80_appearance_stage_card',None) else getattr(panel,'h74_motion_preview',None)
        # H80 owns which page/card is visible; H89 owns how much of that card is disclosed.
        card.setMinimumHeight(0); host.setMinimumHeight(0)
        try:
            host.layout().setContentsMargins(8, 5 if not opened else 10, 8, 5 if not opened else 10)
            card.layout().setContentsMargins(0, 0, 0, 0 if not opened else 8)
        except Exception: pass
        if opened:
            for w in _h89_preview_header_widgets(panel, card): w.show()
            if stage is not None:
                stage.setMinimumHeight(int(H89_PREVIEW_STAGE_H)); stage.setMaximumHeight(int(H89_PREVIEW_STAGE_H)); stage.show()
        buttons = list(getattr(panel, '_h89_preview_buttons', ()) or ())
        for btn in buttons:
            btn.setText('预览')
            btn.setToolTip('收起预览' if opened else '展开预览')
            btn.setProperty('h89Open', bool(opened))
            try: btn.style().unpolish(btn); btn.style().polish(btn)
            except Exception: pass
        old_anims = list(getattr(panel, '_h89_preview_animations', ()) or ())
        for ani in old_anims:
            try: ani.stop(); ani.deleteLater()
            except Exception: pass
        panel._h89_preview_animations = []
        if not animate or not panel.isVisible():
            host.setMaximumHeight(int(host_h)); card.setMaximumHeight(int(card_h))
            _h89_finish_preview_height(panel, opened, host, card, host_h, card_h)
            return
        start_host = max(1, int(host.height())); start_card = max(1, int(card.height()))
        ah = QPropertyAnimation(host, b'maximumHeight', panel); ah.setDuration(int(H89_PREVIEW_ANIM_MS)); ah.setStartValue(start_host); ah.setEndValue(int(host_h)); ah.setEasingCurve(QEasingCurve.OutCubic)
        ac = QPropertyAnimation(card, b'maximumHeight', panel); ac.setDuration(int(H89_PREVIEW_ANIM_MS)); ac.setStartValue(start_card); ac.setEndValue(int(card_h)); ac.setEasingCurve(QEasingCurve.OutCubic)
        panel._h89_preview_animations = [ah, ac]
        ah.finished.connect(lambda p=panel,o=opened,h=host,c=card,hh=host_h,ch=card_h: _h89_finish_preview_height(p,o,h,c,hh,ch))
        ac.start(); ah.start()
    except Exception:
        pass


def _h89_toggle_preview(panel):
    panel._h89_preview_open = not bool(getattr(panel, '_h89_preview_open', False))
    _h89_apply_preview_state(panel, True)
    if bool(getattr(panel, '_settings_loaded', False)):
        try: panel._schedule_config_save()
        except Exception: pass


def _h89_install_preview_rail(panel):
    buttons = []
    # Retire H88's separate size buttons and replace them with one semantic disclosure affordance.
    for old in list(getattr(panel, '_h88_preview_buttons', ()) or ()):
        try: old.hide(); old.deleteLater()
        except Exception: pass
    for card in (getattr(panel, 'h80_appearance_stage_card', None), getattr(panel, 'h80_motion_stage_card', None)):
        try:
            layout = card.layout() if card is not None else None
            header = layout.itemAt(0).layout() if layout is not None and layout.count() else None
            if header is None: continue
            btn = QToolButton(card); btn.setObjectName('h89PreviewRailButton'); btn.setCursor(Qt.PointingHandCursor); btn.setText('预览')
            btn.clicked.connect(lambda _checked=False, p=panel: _h89_toggle_preview(p))
            header.addWidget(btn); buttons.append(btn)
        except Exception: pass
    panel._h89_preview_buttons = buttons
    _h89_apply_preview_state(panel, False)


# --- Section navigation becomes visible state, not decorative chips ------------------
def _h89_focus_card(panel, card):
    try:
        old = getattr(panel, '_h89_focused_card', None)
        if old is not None and old is not card:
            old.setProperty('h89Focus', False); old.style().unpolish(old); old.style().polish(old)
        card.setProperty('h89Focus', True); card.style().unpolish(card); card.style().polish(card)
        panel._h89_focused_card = card
        QTimer.singleShot(620, lambda c=card: _h89_clear_card_focus(c))
    except Exception: pass


def _h89_clear_card_focus(card):
    try:
        card.setProperty('h89Focus', False); card.style().unpolish(card); card.style().polish(card)
    except Exception: pass


def _h89_scroll_to_card(panel, index, card):
    try:
        area = panel.main_tabs.widget(int(index)); page = area.widget(); bar = area.verticalScrollBar()
        pos = card.mapTo(page, QPoint(0,0)).y(); target = max(bar.minimum(), min(bar.maximum(), int(pos)-10))
        old = getattr(panel, '_h89_section_scroll_anim', None)
        if old is not None: old.stop()
        ani = QPropertyAnimation(bar, b'value', panel); ani.setDuration(int(H89_SECTION_SCROLL_MS)); ani.setStartValue(bar.value()); ani.setEndValue(target); ani.setEasingCurve(QEasingCurve.OutCubic)
        panel._h89_section_scroll_anim = ani; ani.start(); _h89_focus_card(panel, card)
    except Exception: pass


def _h89_sync_section_active(panel, index=None):
    try:
        idx = int(panel.main_tabs.currentIndex() if index is None else index)
        if idx not in (1,2): return
        area = panel.main_tabs.widget(idx); page = area.widget(); bar = area.verticalScrollBar(); y = int(bar.value()) + 28
        mapping = list(getattr(panel, '_h89_section_mapping', ()) or ())
        active = None
        for i, card, btn in mapping:
            if i != idx: continue
            pos = int(card.mapTo(page, QPoint(0,0)).y())
            if pos <= y: active = btn
            elif active is None: active = btn; break
        for i, _card, btn in mapping:
            if i == idx: btn.setChecked(btn is active)
    except Exception: pass


def _h89_rebuild_section_rail(panel, index):
    rail = getattr(panel, 'h88_section_rail', None); layout = rail.layout() if rail is not None else None
    if rail is None or layout is None: return
    idx = int(index); rail.setVisible(idx in (1,2))
    if idx not in (1,2): return
    while layout.count():
        item = layout.takeAt(0); w = item.widget()
        if w is not None: w.deleteLater()
    mapping = []
    cards = _h88_cards_for_page(panel, idx) if '_h88_cards_for_page' in globals() else []
    for card in cards:
        title = _h74_card_title(card) if '_h74_card_title' in globals() else ''
        if not title: continue
        btn = QPushButton(title, rail); btn.setObjectName('h89SectionTab'); btn.setCheckable(True); btn.setAutoExclusive(True); btn.setCursor(Qt.PointingHandCursor)
        btn.clicked.connect(lambda _checked=False,p=panel,i=idx,c=card: _h89_scroll_to_card(p,i,c))
        layout.addWidget(btn); mapping.append((idx,card,btn))
    layout.addStretch(); panel._h89_section_mapping = mapping
    QTimer.singleShot(0, lambda p=panel,i=idx: _h89_sync_section_active(p,i))


def _h89_install_section_rail(panel):
    try:
        rail = getattr(panel, 'h88_section_rail', None)
        if rail is None: return
        shell_layout = panel.settings_shell.layout(); shell_layout.removeWidget(rail)
        header = getattr(panel, 'workspace_header', None); at = shell_layout.indexOf(header) + 1 if header is not None else 1
        shell_layout.insertWidget(max(0,at), rail)
        panel.main_tabs.currentChanged.connect(lambda i,p=panel: _h89_rebuild_section_rail(p,i))
        for idx in (1,2):
            area = panel.main_tabs.widget(idx)
            try: area.verticalScrollBar().valueChanged.connect(lambda _v,p=panel,i=idx: _h89_sync_section_active(p,i))
            except Exception: pass
        _h89_rebuild_section_rail(panel, panel.main_tabs.currentIndex())
    except Exception:
        pass


# --- Manual lyric editor disclosure --------------------------------------------------
def _h89_finish_lrc_disclosure(panel, opening, effect):
    try:
        editor = panel.text_input
        if opening:
            editor.setMaximumHeight(int(H89_LRC_EDITOR_H)); editor.setMinimumHeight(int(H89_LRC_EDITOR_H)); effect.setOpacity(1.0); editor.setFocus(Qt.OtherFocusReason)
        else:
            editor.hide(); editor.setMinimumHeight(0); editor.setMaximumHeight(int(H89_LRC_EDITOR_H)); effect.setOpacity(1.0)
        panel._h89_lrc_animations = []
    except Exception: pass


def _h89_toggle_lrc_editor(panel):
    try:
        opening = not bool(getattr(panel, '_lrc_editor_expanded', False)); panel._lrc_editor_expanded = opening
        editor = panel.text_input; panel.lrc_toggle_btn.setText('收起歌词文本' if opening else '展开歌词文本')
        old = list(getattr(panel, '_h89_lrc_animations', ()) or ())
        for ani in old:
            try: ani.stop(); ani.deleteLater()
            except Exception: pass
        effect = editor.graphicsEffect()
        if not isinstance(effect, QGraphicsOpacityEffect):
            effect = QGraphicsOpacityEffect(editor); editor.setGraphicsEffect(effect)
        editor.setMinimumHeight(0)
        if opening:
            editor.show(); editor.setMaximumHeight(0); effect.setOpacity(0.0); start_h=0; end_h=int(H89_LRC_EDITOR_H); a0=0.0; a1=1.0
        else:
            start_h=max(1,int(editor.height())); end_h=0; a0=float(effect.opacity()); a1=0.0
        ah=QPropertyAnimation(editor,b'maximumHeight',panel); ah.setDuration(int(H89_LRC_DISCLOSURE_MS)); ah.setStartValue(start_h); ah.setEndValue(end_h); ah.setEasingCurve(QEasingCurve.OutCubic)
        ao=QPropertyAnimation(effect,b'opacity',panel); ao.setDuration(int(H89_LRC_DISCLOSURE_MS)); ao.setStartValue(a0); ao.setEndValue(a1); ao.setEasingCurve(QEasingCurve.OutCubic)
        panel._h89_lrc_animations=[ah,ao]; ah.finished.connect(lambda p=panel,o=opening,e=effect:_h89_finish_lrc_disclosure(p,o,e)); ao.start(); ah.start()
    except Exception:
        # Preserve the old semantic even if a graphics backend rejects the cosmetic animation.
        try:
            panel._lrc_editor_expanded = not bool(getattr(panel,'_lrc_editor_expanded',False)); panel.text_input.setVisible(panel._lrc_editor_expanded)
        except Exception: pass


# --- Stable frameless vertical geometry ---------------------------------------------
def _h89_screen_for_panel(panel):
    try:
        handle=panel.windowHandle(); screen=handle.screen() if handle is not None else None
        if screen is not None: return screen
    except Exception: pass
    try:
        center=panel.frameGeometry().center(); finder=getattr(QApplication,'screenAt',None); screen=finder(center) if callable(finder) else None
        if screen is not None: return screen
    except Exception: pass
    try: return QApplication.primaryScreen()
    except Exception: return None


def _h89_rescue_vertical_geometry(panel):
    try:
        if panel is None or panel.isMaximized(): return False
        # Never fight the OS while the user still owns a native resize/move gesture.
        try:
            if QApplication.mouseButtons() & Qt.LeftButton:
                _h89_schedule_geometry_guard(panel, 180); return False
        except Exception: pass
        screen=_h89_screen_for_panel(panel)
        if screen is None: return False
        area=screen.availableGeometry(); g=panel.geometry()
        min_h=min(max(1,int(panel.minimumHeight())),int(area.height()))
        h=max(min_h,min(int(g.height()),int(area.height())))
        y=max(int(area.top()),min(int(g.y()),int(area.bottom())-h+1))
        changed=False
        if int(g.height())!=h:
            panel.resize(panel.width(),h); changed=True
        if int(panel.y())!=y:
            panel.move(panel.x(),y); changed=True
        return changed
    except Exception:
        return False


def _h89_schedule_geometry_guard(panel, delay=None):
    try:
        timer=getattr(panel,'_h89_geometry_timer',None)
        if timer is None:
            timer=QTimer(panel); timer.setSingleShot(True); timer.timeout.connect(lambda p=panel:_h89_rescue_vertical_geometry(p)); panel._h89_geometry_timer=timer
        timer.setInterval(int(H89_GEOMETRY_SETTLE_MS if delay is None else delay)); timer.start()
    except Exception: pass


def _h89_h86_limit_bridge(panel, rescue=False):
    # H86 used setMaximumHeight()/resize() inside moveEvent. During top-edge native resize that
    # competes with Windows' own geometry transaction and can jump the frameless window. H89
    # waits until the gesture settles, then clamps only vertical geometry once.
    try:
        panel.setMaximumHeight(int(H89_QWIDGET_MAX))
        if rescue: _h89_schedule_geometry_guard(panel)
        return True
    except Exception:
        return False


def _h89_try_top_system_resize(bar, event):
    if event.button()!=Qt.LeftButton: return False
    host=getattr(bar,'_host',None)
    if host is None or host.isMaximized(): return False
    try:
        pos=host.mapFromGlobal(event.globalPos()); dpr=max(1.0,float(host.devicePixelRatioF())); border=max(5,int(round(float(getattr(host,'_frame_resize_border_px',8))*dpr)))
        if pos.y()<0 or pos.y()>=border: return False
        hit=12; edge=Qt.TopEdge
        if pos.x()<border: hit=13; edge=Qt.TopEdge|Qt.LeftEdge
        elif pos.x()>=max(0,host.width()-border): hit=14; edge=Qt.TopEdge|Qt.RightEdge
        bar._drag_offset=None
        if os.name=='nt':
            user32=ctypes.windll.user32; user32.ReleaseCapture()
            # Exactly one native ownership path. Post rather than nest SendMessage inside Qt's
            # child mousePressEvent; Windows then owns the complete resize transaction.
            user32.PostMessageW(int(host.winId()),0x00A1,int(hit),0)
            _h89_schedule_geometry_guard(host); return True
        handle=host.windowHandle(); starter=getattr(handle,'startSystemResize',None) if handle is not None else None
        if callable(starter):
            try: return bool(starter(edge))
            except Exception: return False
    except Exception: pass
    return False


_h89_control_init_pre = globals().get('ControlPanel').__init__ if 'ControlPanel' in globals() else None
_h89_resize_pre = getattr(globals().get('ControlPanel'),'resizeEvent',None) if 'ControlPanel' in globals() else None
_h89_frontend_theme_pre = globals().get('_h87_apply_frontend_theme')
_h89_save_pre = globals().get('save_all_config')


def _h89_apply_frontend_theme(panel, theme=None, save=False):
    out=_h89_frontend_theme_pre(panel,theme,save) if callable(_h89_frontend_theme_pre) else None
    _h89_append_qss(panel); return out


def _h89_resize(panel,event):
    out=_h89_resize_pre(panel,event) if callable(_h89_resize_pre) else None
    _h89_clear_page_veil(panel); _h89_schedule_geometry_guard(panel)
    return out


def _h89_sync_stage(panel,index,animate=True):
    old=globals().get('_h89_h80_stage_pre')
    out=old(panel,index,animate) if callable(old) else None
    QTimer.singleShot(0,lambda p=panel:_h89_apply_preview_state(p,False)); return out


def _h89_save_all_config(panel,presets,players):
    if callable(_h89_save_pre): _h89_save_pre(panel,presets,players)
    try:
        data=load_all_config(); settings=data.setdefault('settings',{}); settings['h89_preview_open']=bool(getattr(panel,'_h89_preview_open',False)); _write_config_dict_atomic(data)
    except Exception: pass


def _h89_control_init(panel,*args,**kwargs):
    _h89_control_init_pre(panel,*args,**kwargs)
    try:
        settings=(load_all_config().get('settings') or {}) if 'load_all_config' in globals() else {}
        panel._h89_preview_open=bool(settings.get('h89_preview_open',False))
        # The inspector is scroll-based; 540 px was unnecessarily restrictive after the studio
        # stage became fixed chrome. Let small displays reclaim vertical space.
        panel.setMinimumHeight(int(H89_MIN_PANEL_HEIGHT)); panel.setMaximumHeight(int(H89_QWIDGET_MAX))
        _h89_install_preview_rail(panel); _h89_install_section_rail(panel); _h89_append_qss(panel)
        QTimer.singleShot(0,lambda p=panel:_h89_apply_preview_state(p,False))
        QTimer.singleShot(0,lambda p=panel:_h89_schedule_geometry_guard(p,20))
    except Exception as exc:
        try: write_error_log('H89交互工作区安装失败',exc)
        except Exception: pass


def _h89_activate_ui():
    try:
        # Existing signal lambdas resolve these globals at call time, so this retires expensive
        # H87/H88 capture work without reconnecting the navigation graph.
        globals()['_h87_prime_page_transition']=_h89_prime_page_transition
        globals()['_h87_refresh_page_snapshot']=_h89_refresh_page_snapshot
        globals()['_h87_on_page_changed']=_h89_on_page_changed
        globals()['H87PageTransitionOverlay']=H89PageVeil
        # H86 wrappers also resolve their helpers dynamically. Replace only the runtime helper,
        # keeping the H86 historical function body/source lock untouched.
        globals()['_h86_refresh_vertical_limit']=_h89_h86_limit_bridge
        globals()['_h86_try_top_system_resize']=_h89_try_top_system_resize
        if '_h80_sync_studio_stage' in globals():
            globals()['_h89_h80_stage_pre']=globals()['_h80_sync_studio_stage']; globals()['_h80_sync_studio_stage']=_h89_sync_stage
        globals()['_h88_apply_preview_mode']=lambda p:_h89_apply_preview_state(p,False)
        globals()['_h88_toggle_preview']=_h89_toggle_preview
        globals()['_h88_update_section_rail']=_h89_rebuild_section_rail
        globals()['_h87_apply_frontend_theme']=_h89_apply_frontend_theme
        globals()['save_all_config']=_h89_save_all_config
        if 'ControlPanel' in globals():
            ControlPanel.__init__=_h89_control_init; ControlPanel.__init__._limbus_layer='H89'
            ControlPanel.__init__._limbus_policy='collapsible preview + section feedback + screenshot-free nav + settled frameless resize; presentation-only'
            if callable(_h89_resize_pre): ControlPanel.resizeEvent=_h89_resize; ControlPanel.resizeEvent._limbus_layer='H89'
            ControlPanel._toggle_lrc_editor=_h89_toggle_lrc_editor; ControlPanel._toggle_lrc_editor._limbus_layer='H89'
    except Exception as exc:
        try: write_error_log('H89高级交互层激活失败',exc)
        except Exception: pass


if '_h89_activate_ui' in globals(): _h89_activate_ui()


# H90 responsive shell + record restore + density fix ---------------------------------
# Field-feedback closure. Presentation/shell only: keep player/seek/provider/lyric
# authority unchanged. H90 removes the redundant section-chip rail, restores the record
# at compact widths, prevents UI scale from forcing a near-full-screen minimum geometry,
# and retires the extra title-bar resize transaction in favour of the existing native
# WM_NCHITTEST edge/corner path.
H90_MIN_PANEL_WIDTH = 520
H90_MIN_PANEL_HEIGHT = 360
H90_RECORD_VISIBLE_MIN_WIDTH = 500
H90_TITLEBAR_HEIGHT = 38
H90_TOP_PASSIVE_BORDER_PX = 5
H90_GEOMETRY_SETTLE_MS = 360
H90_QWIDGET_MAX = 16777215

_h90_control_init_pre = globals().get('ControlPanel').__init__ if 'ControlPanel' in globals() else None
_h90_resize_pre = getattr(globals().get('ControlPanel'), 'resizeEvent', None) if 'ControlPanel' in globals() else None
_h90_apply_scale_pre = globals().get('_h12_apply_scale')
_h90_studio_adapt_pre = globals().get('_studio_adapt_layout')
_h90_title_press_base = globals().get('_h86_title_press_pre') or (getattr(globals().get('PanelTitleBar'), 'mousePressEvent', None) if 'PanelTitleBar' in globals() else None)
_h90_save_pre = globals().get('save_all_config')


def _h90_remove_section_rail(panel):
    """Retire H88/H89 section chips completely; page cards remain normal scroll content."""
    try:
        rail = getattr(panel, 'h88_section_rail', None)
        if rail is not None:
            try:
                lay = getattr(panel, 'settings_shell', None).layout() if getattr(panel, 'settings_shell', None) is not None else None
                if lay is not None: lay.removeWidget(rail)
            except Exception: pass
            try: rail.hide(); rail.setParent(None); rail.deleteLater()
            except Exception: pass
        panel.h88_section_rail = None
        panel._h89_section_mapping = []
    except Exception:
        pass


def _h90_relax_shell(panel):
    """Keep larger UI text usable without making the top-level window itself enormous."""
    try:
        panel.setMinimumSize(int(H90_MIN_PANEL_WIDTH), int(H90_MIN_PANEL_HEIGHT))
        panel.setMaximumHeight(int(H90_QWIDGET_MAX))
    except Exception: pass
    try:
        bar = getattr(panel, 'window_title_bar', None)
        if bar is not None:
            bar.setMinimumHeight(int(H90_TITLEBAR_HEIGHT)); bar.setMaximumHeight(int(H90_TITLEBAR_HEIGHT))
            for name in ('min_btn', 'max_btn', 'close_btn'):
                btn = getattr(bar, name, None)
                if btn is not None:
                    btn.setMinimumSize(34, 28); btn.setMaximumSize(42, 32)
    except Exception: pass
    # The long settings body is already inside QScrollArea. Tell Qt that these shell containers
    # may shrink vertically instead of propagating every scaled child's sizeHint to the window.
    for obj in (
        getattr(panel, 'settings_shell', None),
        getattr(panel, 'main_tabs', None),
        panel.findChild(QWidget, 'panelContent') if 'QWidget' in globals() else None,
    ):
        try:
            if obj is not None:
                obj.setMinimumHeight(0)
                obj.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Ignored)
        except Exception: pass
    try:
        tabs = getattr(panel, 'main_tabs', None)
        if tabs is not None: tabs.setMinimumHeight(82)
    except Exception: pass
    try:
        header = getattr(panel, 'workspace_header', None)
        if header is not None: header.setMinimumHeight(0)
    except Exception: pass
    try:
        hero = panel.findChild(QFrame, 'heroCard')
        if hero is not None:
            hero.setMinimumHeight(0); hero.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)
    except Exception: pass
    try:
        # Navigation should stay comfortable at 125/150% text scale without becoming a tall bar.
        for button in list(getattr(panel, '_sidebar_buttons', ()) or ()):
            button.setMinimumHeight(28); button.setMaximumHeight(42)
    except Exception: pass


def _h90_apply_scale(panel, pct):
    out = _h90_apply_scale_pre(panel, pct) if callable(_h90_apply_scale_pre) else None
    _h90_relax_shell(panel)
    try: _h90_adapt_layout(panel)
    except Exception: pass
    return out


def _h90_adapt_layout(panel):
    """Preserve Listening Room at compact widths instead of deleting the whole record."""
    if callable(_h90_studio_adapt_pre):
        try: _h90_studio_adapt_pre(panel)
        except Exception: pass
    try:
        width = int(panel.width())
        ambient = getattr(panel, 'h79_hero_ambient', None)
        if ambient is not None:
            ambient.setVisible(width >= int(H90_RECORD_VISIBLE_MIN_WIDTH))
            if width >= int(H90_RECORD_VISIBLE_MIN_WIDTH):
                ambient.show(); ambient.raise_(); ambient.lower(); ambient.update()
        hero = panel.findChild(QFrame, 'heroCard')
        if hero is not None and hero.layout() is not None:
            compact = int(panel.height()) < 850
            right = 150 if width >= int(H90_RECORD_VISIBLE_MIN_WIDTH) else 22
            hero.layout().setContentsMargins(22, 12 if compact else 18, right, 12 if compact else 20)
        # H80's historical responsive pass restores old preview minimum heights. Re-apply the
        # H89 disclosure state so UI scaling/resizing cannot silently reopen a collapsed preview.
        preview_sync = globals().get('_h89_apply_preview_state')
        if callable(preview_sync): preview_sync(panel, False)
    except Exception:
        pass


def _h90_title_press(bar, event):
    """Do not start a second resize transaction from the child title bar.

    ControlPanel.nativeEvent already returns HTTOP/HTTOPLEFT/HTTOPRIGHT. If a rare Qt path still
    delivers a client mouse press inside the physical top strip, ignore it rather than moving the
    window or posting another WM_NCLBUTTONDOWN. This removes the click->jump->rescue cycle.
    """
    try:
        if event.button() == Qt.LeftButton:
            host = getattr(bar, '_host', None)
            if host is not None and not host.isMaximized():
                pos = host.mapFromGlobal(event.globalPos())
                if 0 <= int(pos.y()) < int(H90_TOP_PASSIVE_BORDER_PX):
                    bar._drag_offset = None
                    event.ignore()
                    return
    except Exception:
        pass
    if callable(_h90_title_press_base):
        return _h90_title_press_base(bar, event)


def _h90_rescue_geometry(panel):
    """Only rescue a genuinely off-screen normal window after interaction has settled."""
    try:
        if panel is None or panel.isMaximized(): return False
        try:
            if QApplication.mouseButtons() & Qt.LeftButton:
                _h90_schedule_geometry_guard(panel, 220); return False
        except Exception: pass
        screen = _h89_screen_for_panel(panel) if '_h89_screen_for_panel' in globals() else QApplication.primaryScreen()
        if screen is None: return False
        area = screen.availableGeometry(); g = panel.geometry()
        h = min(max(int(H90_MIN_PANEL_HEIGHT), int(g.height())), int(area.height()))
        y = int(g.y())
        # Do not "snap" a normal top-edge click. Move only when the title bar is genuinely
        # outside the work area or the resized window cannot fit below its current y.
        if y < int(area.top()): y = int(area.top())
        if y + h > int(area.bottom()) + 1: y = max(int(area.top()), int(area.bottom()) - h + 1)
        changed = False
        if int(g.height()) != h:
            panel.resize(panel.width(), h); changed = True
        if int(panel.y()) != y:
            panel.move(panel.x(), y); changed = True
        return changed
    except Exception:
        return False


def _h90_schedule_geometry_guard(panel, delay=None):
    try:
        timer = getattr(panel, '_h90_geometry_timer', None)
        if timer is None:
            timer = QTimer(panel); timer.setSingleShot(True)
            timer.timeout.connect(lambda p=panel: _h90_rescue_geometry(p))
            panel._h90_geometry_timer = timer
        timer.setInterval(int(H90_GEOMETRY_SETTLE_MS if delay is None else delay)); timer.start()
    except Exception: pass


def _h90_resize(panel, event):
    out = _h90_resize_pre(panel, event) if callable(_h90_resize_pre) else None
    _h90_relax_shell(panel); _h90_adapt_layout(panel); _h90_schedule_geometry_guard(panel)
    return out


def _h90_save_all_config(panel, presets, players):
    if callable(_h90_save_pre): _h90_save_pre(panel, presets, players)


def _h90_control_init(panel, *args, **kwargs):
    _h90_control_init_pre(panel, *args, **kwargs)
    try:
        _h90_remove_section_rail(panel)
        _h90_relax_shell(panel)
        _h90_adapt_layout(panel)
        QTimer.singleShot(0, lambda p=panel: (_h90_relax_shell(p), _h90_adapt_layout(p), _h90_schedule_geometry_guard(p, 40)))
    except Exception as exc:
        try: write_error_log('H90响应式外壳安装失败', exc)
        except Exception: pass


def _h90_no_section_rail(*_args, **_kwargs):
    return None


def _h90_activate_ui():
    try:
        # Retire the H88/H89 chip rail rather than maintaining a decorative navigation layer.
        globals()['_h89_rebuild_section_rail'] = _h90_no_section_rail
        globals()['_h89_sync_section_active'] = _h90_no_section_rail
        globals()['_h88_update_section_rail'] = _h90_no_section_rail
        # Existing H86 title wrapper resolves this helper dynamically. Never initiate a second
        # native resize from it; H90 installs a passive title press and relies on nativeEvent.
        globals()['_h86_try_top_system_resize'] = lambda *_a, **_k: False
        globals()['_h89_try_top_system_resize'] = lambda *_a, **_k: False
        globals()['_h12_apply_scale'] = _h90_apply_scale
        globals()['_studio_adapt_layout'] = _h90_adapt_layout
        globals()['save_all_config'] = _h90_save_all_config
        if 'PanelTitleBar' in globals():
            PanelTitleBar.mousePressEvent = _h90_title_press
            PanelTitleBar.mousePressEvent._limbus_layer = 'H90'
            PanelTitleBar.mousePressEvent._limbus_policy = 'native-hit-test-only top resize; client top strip never drags window'
        if 'ControlPanel' in globals():
            ControlPanel.__init__ = _h90_control_init
            ControlPanel.__init__._limbus_layer = 'H90'
            ControlPanel.__init__._limbus_policy = 'responsive compact shell + record restore + no section chips + native-hit-test resize; presentation-only'
            if callable(_h90_resize_pre):
                ControlPanel.resizeEvent = _h90_resize
                ControlPanel.resizeEvent._limbus_layer = 'H90'
    except Exception as exc:
        try: write_error_log('H90响应式界面层激活失败', exc)
        except Exception: pass


if '_h90_activate_ui' in globals(): _h90_activate_ui()

# H91 draggable workspace + media-first hero + shared cover pipeline -----------------
# Presentation / artwork acquisition only. media clock core, seek authority, lyric search
# transactions and provider identity remain untouched. Field logs showed that process-affine
# media identity often arrives 15-109ms after a QQ switch while lyric first-screen binding can
# take ~1.4-1.9s. H91 lets the front shell follow that media identity immediately, makes the
# top navigation strip a vertical workspace splitter, and unifies record artwork with cover-
# follow colour acquisition so the two presentation features no longer search independently.
H91_HERO_MIN_H = 96
H91_HERO_MAX_H = 252
H91_HERO_DEFAULT_H = 204
H91_HERO_COMPACT_H = 132
H91_ART_NEGATIVE_RETRY_SEC = 28.0
H91_ART_CLEAR_GRACE_MS = 360
H91_QQ_DURATION_TOL_MIN = 3500

_h91_control_init_pre = globals().get('ControlPanel').__init__ if 'ControlPanel' in globals() else None
_h91_front_status_pre = getattr(globals().get('ControlPanel'), '_refresh_frontend_status', None) if 'ControlPanel' in globals() else None
_h91_resize_pre = getattr(globals().get('ControlPanel'), 'resizeEvent', None) if 'ControlPanel' in globals() else None
_h91_save_pre = globals().get('save_all_config')
_h91_cover_tick_pre = globals().get('_h16_cover_tick')
_h91_ambient_paint_pre = getattr(globals().get('H79HeroAmbient'), 'paintEvent', None) if 'H79HeroAmbient' in globals() else None


def _h91_clamp_hero_height(value):
    try: value = int(round(float(value)))
    except Exception: value = H91_HERO_DEFAULT_H
    return max(int(H91_HERO_MIN_H), min(int(H91_HERO_MAX_H), value))


def _h91_apply_hero_height(panel, height=None, persist=False):
    try:
        hero = panel.findChild(QFrame, 'heroCard') if 'QFrame' in globals() else None
        if hero is None: return False
        if height is None: height = getattr(panel, '_h91_hero_height', H91_HERO_DEFAULT_H)
        height = _h91_clamp_hero_height(height); panel._h91_hero_height = height
        hero.setMinimumHeight(height); hero.setMaximumHeight(height)
        hero.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        compact = height <= int(H91_HERO_COMPACT_H)
        tiny = height <= 108
        # Keep the song title + sync state + record. Retire secondary copy as space tightens.
        for name in ('manager_tag', 'front_detail_label', 'h79_live_lyric'):
            obj = getattr(panel, name, None)
            if obj is not None:
                obj.setVisible(not compact and (bool(str(obj.text() or '').strip()) if name == 'h79_live_lyric' else True))
        for name in ('app_title',):
            obj = getattr(panel, name, None)
            if obj is not None: obj.setVisible(not tiny)
        layout = hero.layout()
        if layout is not None:
            width = int(panel.width())
            right = 106 if compact and width >= 500 else (150 if width >= 500 else 18)
            layout.setContentsMargins(18 if compact else 22, 8 if compact else 14, right, 8 if compact else 14)
            layout.setSpacing(1 if compact else 4)
        ambient = getattr(panel, 'h79_hero_ambient', None)
        if ambient is not None:
            ambient.setVisible(int(panel.width()) >= 500); ambient.update()
        if persist and bool(getattr(panel, '_settings_loaded', False)):
            try: panel._schedule_config_save()
            except Exception: pass
        return True
    except Exception:
        return False


_H91_QOBJECT_BASE = globals().get('QObject', object)
class H91WorkspaceSplitter(_H91_QOBJECT_BASE):
    """Use only the empty background of topNav as a vertical splitter.

    Child nav buttons keep their ordinary click semantics. Dragging the strip upward shrinks the
    Hero and gives that height directly to the settings shell; dragging downward restores it.
    """
    def __init__(self, panel, nav):
        super().__init__(nav)
        self.panel = panel; self.nav = nav; self.dragging = False; self.start_y = 0; self.start_h = H91_HERO_DEFAULT_H
        nav.installEventFilter(self)
        nav.setToolTip('空白处上下拖动：压缩 / 展开歌曲与唱片区域；双击恢复默认高度')
        try: nav.setCursor(Qt.SizeVerCursor)
        except Exception: pass

    def _global_y(self, event):
        try: return int(event.globalPos().y())
        except Exception:
            try: return int(event.globalPosition().y())
            except Exception: return 0

    def eventFilter(self, obj, event):
        if obj is not self.nav: return False
        t = event.type()
        try:
            if t == QEvent.MouseButtonDblClick and event.button() == Qt.LeftButton:
                _h91_apply_hero_height(self.panel, H91_HERO_DEFAULT_H, True); event.accept(); return True
            if t == QEvent.MouseButtonPress and event.button() == Qt.LeftButton:
                self.dragging = True; self.start_y = self._global_y(event)
                self.start_h = int(getattr(self.panel, '_h91_hero_height', H91_HERO_DEFAULT_H) or H91_HERO_DEFAULT_H)
                try: self.nav.setCursor(Qt.SplitVCursor)
                except Exception: pass
                event.accept(); return True
            if t == QEvent.MouseMove and self.dragging and (event.buttons() & Qt.LeftButton):
                target = self.start_h + (self._global_y(event) - self.start_y)
                _h91_apply_hero_height(self.panel, target, False); event.accept(); return True
            if t == QEvent.MouseButtonRelease and self.dragging:
                self.dragging = False
                try: self.nav.setCursor(Qt.SizeVerCursor)
                except Exception: pass
                _h91_apply_hero_height(self.panel, getattr(self.panel, '_h91_hero_height', self.start_h), True)
                event.accept(); return True
        except Exception:
            self.dragging = False
        return False


def _h91_source_affine_media(panel, state=None):
    try:
        state = dict(state or (panel.media_sync.snapshot() or {}))
        song = str(state.get('media_title') or '').strip(); artist = str(state.get('media_artist') or '').strip()
        generic = {'qq音乐','qqmusic','网易云音乐','酷狗音乐','spotify'}
        if not song or song.casefold() in generic or len(song) >= 180: return ('','',state)
        player_name = str(panel.player_combo.currentText() or '') if hasattr(panel, 'player_combo') else ''
        cfg = (getattr(panel, 'players', {}) or {}).get(player_name, {}) or {}
        process = str(cfg.get('process') or '').strip()
        source = str(state.get('media_source') or '')
        matcher = getattr(getattr(panel, 'media_sync', None), '_source_matches_process_hint', None)
        if source and process and callable(matcher) and not bool(matcher(source, process)):
            return ('','',state)
        return (song, artist, state)
    except Exception:
        return ('','',dict(state or {}))


def _h91_current_visual_identity(panel):
    song, artist, state = _h91_source_affine_media(panel)
    if song:
        return song, artist, panel._track_identity(song, artist), state
    song = str(getattr(panel, '_loaded_song', '') or '').strip(); artist = str(getattr(panel, '_loaded_artist', '') or '').strip()
    return song, artist, panel._track_identity(song, artist) if song else '', state


def _h91_song_variants(song):
    text = str(song or '').strip()
    if not text: return []
    out=[]
    def add(v):
        v=re.sub(r'\s+',' ',str(v or '')).strip(' -–—·・')
        if v and v not in out: out.append(v)
    add(text)
    add(re.sub(r'\s*[\(（][^()（）]{1,64}[\)）]\s*$', '', text))
    # Japanese/Chinese decorative title brackets often carry vocalist/producer metadata rather
    # than the canonical song title: 【鏡音リン】少女A【椎名もた】 -> 少女A.
    add(re.sub(r'【[^】]{1,80}】|\[[^\]]{1,80}\]|［[^］]{1,80}］', ' ', text))
    add(re.sub(r'(?i)\s+(?:feat\.?|ft\.?)\s+.+$', '', text))
    return out[:5]


def _h91_bracket_aliases(song):
    values=[]
    for group in re.findall(r'【([^】]{1,80})】|\[([^\]]{1,80})\]|［([^］]{1,80})］', str(song or '')):
        value=next((str(x).strip() for x in group if str(x).strip()), '')
        if value and value not in values: values.append(value)
    return values


def _h91_artist_variants(song, artist):
    text=str(artist or '').strip(); out=[]
    def add(v):
        v=re.sub(r'\s+',' ',str(v or '')).strip()
        if v and v not in out: out.append(v)
    add(text)
    for item in re.split(r'[/,&，、;；|]+', text): add(re.sub(r'\s*[\(（][^()（）]{1,64}[\)）]\s*$', '', item))
    for item in _h91_bracket_aliases(song): add(item)
    # Empty artist is the last resort only; duration/title scoring still protects identity.
    return (out[:6] + ['']) if '' not in out else out[:7]


def _h91_norm(value):
    return re.sub(r'[^0-9a-z\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]+','',str(value or '').casefold())


def _h91_duration_score(candidate_ms, expected_ms):
    try: c=int(candidate_ms or 0); e=int(expected_ms or 0)
    except Exception: return 0
    if c <= 0 or e <= 0: return 0
    d=abs(c-e); tol=max(int(H91_QQ_DURATION_TOL_MIN), int(e*0.025))
    if d <= tol: return 70
    if d <= max(8000, int(e*0.05)): return 30
    if d > max(12000, int(e*0.08)): return -70
    return -15


def _h91_artist_match(wanted, actual):
    if not str(wanted or '').strip(): return True
    try: return bool(_artist_alias_match(str(wanted), str(actual))[0])
    except Exception:
        a=_h91_norm(wanted); b=_h91_norm(actual); return bool(a and b and (a in b or b in a))


def _h91_choose_qq_row(rows, song, artist='', expected_duration_ms=0):
    target=_h91_norm(song); best=None; best_score=-10**9
    for row in [x for x in list(rows or []) if isinstance(x,dict)]:
        title=str(row.get('songname') or row.get('name') or ''); tn=_h91_norm(title)
        if not target or not tn: continue
        if target==tn: score=150
        elif target in tn or tn in target: score=85
        else: continue
        actual=_artist_text({'singer':row.get('singer',[])}) if '_artist_text' in globals() else ''
        if artist:
            score += 55 if _h91_artist_match(artist,actual) else -35
        score += _h91_duration_score(int(row.get('interval') or 0)*1000, expected_duration_ms)
        if str(row.get('albummid') or row.get('albumMID') or '').strip(): score += 8
        if score>best_score: best_score=score; best=row
    return best if best_score>=90 else None


def _h91_choose_netease_row(rows, song, artist='', expected_duration_ms=0, preferred_id=''):
    pid=str(preferred_id or '').strip(); target=_h91_norm(song); best=None; best_score=-10**9
    for row in [x for x in list(rows or []) if isinstance(x,dict)]:
        title=str(row.get('name') or ''); tn=_h91_norm(title)
        if not target or not tn: continue
        if target==tn: score=150
        elif target in tn or tn in target: score=85
        else: continue
        rid=str(row.get('id') or '').strip()
        if pid and rid==pid: score += 120
        arts=row.get('artists') if isinstance(row.get('artists'),list) else row.get('ar')
        actual=', '.join(str(x.get('name') or '') for x in list(arts or []) if isinstance(x,dict))
        if artist: score += 55 if _h91_artist_match(artist,actual) else -35
        duration=row.get('duration') or row.get('dt') or 0
        score += _h91_duration_score(duration, expected_duration_ms)
        if _h16_cover_pic_url(row): score += 8
        if score>best_score: best_score=score; best=row
    return best if best_score>=90 else None


def _h91_fetch_qq_art(http, song, artist, expected_duration_ms, headers, out_path):
    qq_headers=dict(headers); qq_headers['Referer']='https://y.qq.com/'
    best=None; best_query=('', '')
    for sname in _h91_song_variants(song):
        for aname in _h91_artist_variants(song,artist):
            try:
                resp=_r2_qq_search_request(http,'https://c.y.qq.com/soso/fcgi-bin/client_search_cp',params={'p':1,'n':18,'w':f'{sname} {aname}'.strip(),'format':'json'},headers=qq_headers,timeout=4)
                resp.raise_for_status(); rows=(((resp.json().get('data') or {}).get('song') or {}).get('list') or [])
                hit=_h91_choose_qq_row(rows,sname,aname,expected_duration_ms)
                if hit is not None: best=hit; best_query=(sname,aname); break
            except Exception: pass
        if best is not None: break
    if not isinstance(best,dict): return '',''
    album_mid=str(best.get('albummid') or best.get('albumMID') or '').strip(); song_mid=str(best.get('songmid') or '').strip()
    if not album_mid and song_mid:
        try:
            detail=http.get('https://c.y.qq.com/v8/fcg-bin/fcg_play_single_song.fcg',params={'songmid':song_mid,'format':'json'},headers=qq_headers,timeout=4)
            detail.raise_for_status(); data=detail.json().get('data') or []
            if data and isinstance(data[0],dict):
                album=data[0].get('album') if isinstance(data[0].get('album'),dict) else {}; album_mid=str(data[0].get('albummid') or album.get('mid') or '').strip()
        except Exception: pass
    if not album_mid: return '',''
    try:
        img=http.get(f'https://y.gtimg.cn/music/photo_new/T002R500x500M000{album_mid}.jpg',headers=qq_headers,timeout=4); img.raise_for_status()
        path=_h88_save_art_bytes(img.content,out_path) if '_h88_save_art_bytes' in globals() else ''
        if path: return path, f'qq:{song_mid or album_mid}:{best_query[0]}'
        return '',''
    except Exception: return '',''


def _h91_fetch_netease_art(http, song, artist, expected_duration_ms, headers, preferred_id, out_path):
    seen=set()
    for sname in _h91_song_variants(song):
        for aname in _h91_artist_variants(song,artist):
            query=f'{sname} {aname}'.strip()
            if not query or query in seen: continue
            seen.add(query)
            try:
                resp=http.post('https://music.163.com/api/search/get/web',data={'s':query,'type':1,'limit':14},headers=headers,timeout=4)
                resp.raise_for_status(); rows=((resp.json().get('result') or {}).get('songs') or [])
                hit=_h91_choose_netease_row(rows,sname,aname,expected_duration_ms,preferred_id)
                if not hit: continue
                url=_h16_cover_pic_url(hit)
                if not url: continue
                img=http.get(url,headers=headers,timeout=4); img.raise_for_status()
                path=_h88_save_art_bytes(img.content,out_path) if '_h88_save_art_bytes' in globals() else ''
                if path: return path, f'netease:{hit.get("id") or ""}:{sname}'
            except Exception: pass
    return '',''


def _h91_share_art_color(panel, key, path):
    if not path or not os.path.isfile(path): return ''
    try:
        pix=QPixmap(path); image=pix.toImage() if not pix.isNull() else None; color=_h16_cover_color_from_image(image) if image is not None and '_h16_cover_color_from_image' in globals() else ''
        color=str(color or '').strip().lower()
        if not color: return ''
        memory=dict(getattr(panel,'_h16_cover_cache',{}) or {}); changed=str(memory.get(str(key)) or '').lower()!=color
        memory[str(key)]=color; panel._h16_cover_cache=memory
        if '_h85_persist_new_cover_colors' in globals(): _h85_persist_new_cover_colors(panel)
        loaded=panel._track_identity(getattr(panel,'_loaded_song',''),getattr(panel,'_loaded_artist',''))
        if bool(getattr(panel,'_h12_cover_follow',False)) and str(loaded)==str(key):
            applied=getattr(panel,'_h12_cover_applied',None)
            panel._h12_cover_result=(str(key),color); panel._h12_cover_applied=(str(key),color)
            if changed or not applied or str(applied[0])!=str(key) or str(applied[1]).lower()!=color:
                try: panel._apply_active_visual_style_live(reason='h91-shared-cover')
                except Exception: pass
        return color
    except Exception:
        return ''


def _h91_clear_stale_record(panel, key):
    try:
        _s,_a,current,_state=_h91_current_visual_identity(panel)
        if str(current)!=str(key): return
        ambient=getattr(panel,'h79_hero_ambient',None)
        if ambient is None or str(getattr(ambient,'_h87_cover_key','') or '')==str(key): return
        old=QPixmap(getattr(ambient,'_h87_cover',QPixmap()))
        if old.isNull(): return
        ambient._h87_prev_cover=old; ambient._h87_cover=QPixmap(); ambient._h87_cover_key=''; ambient._h87_cover_started=time.monotonic()
        timer=getattr(ambient,'_h87_timer',None)
        if timer is not None and not timer.isActive(): timer.start()
        ambient.update()
    except Exception: pass


def _h91_request_art(panel, song, artist='', expected_duration_ms=0):
    try:
        song=str(song or '').strip(); artist=str(artist or '').strip()
        if not song: return
        key=panel._track_identity(song,artist)
        if not key: return
        ambient=getattr(panel,'h79_hero_ambient',None)
        if ambient is not None and str(getattr(ambient,'_h87_cover_key','') or '')==str(key) and not getattr(ambient,'_h87_cover',QPixmap()).isNull():
            cached=_h87_cached_art_path(key) if '_h87_cached_art_path' in globals() else ''
            if cached: _h91_share_art_color(panel,key,cached)
            return
        cached=_h87_cached_art_path(key) if '_h87_cached_art_path' in globals() else ''
        if cached:
            _h91_share_art_color(panel,key,cached)
            _s,_a,current,_state=_h91_current_visual_identity(panel)
            if str(current)==str(key): _h87_set_panel_art(panel,cached,key)
            neg=dict(getattr(panel,'_h88_art_negative',{}) or {}); neg.pop(str(key),None); panel._h88_art_negative=neg
            return
        negative=dict(getattr(panel,'_h88_art_negative',{}) or {})
        if time.monotonic()<float(negative.get(str(key),0.0) or 0.0): return
        active=dict(getattr(panel,'_h87_art_active',{}) or {})
        if str(key) in active: return
        QTimer.singleShot(int(H91_ART_CLEAR_GRACE_MS),lambda p=panel,k=str(key):_h91_clear_stale_record(p,k))
        serial=int(getattr(panel,'_h87_art_serial',0) or 0)+1; panel._h87_art_serial=serial; active[str(key)]=serial; panel._h87_art_active=active
        out_path=_h87_art_file_for_key(key); q=getattr(panel,'_h87_art_results',None)
        meta=dict(getattr(panel,'_active_lyric_provider_meta',{}) or {}); preferred_id=str(meta.get('netease_song_id') or '').strip()
        state=panel.media_sync.snapshot() or {}; duration=int(expected_duration_ms or state.get('duration_ms') or 0)
        player=str(panel.player_combo.currentText() or '') if hasattr(panel,'player_combo') else ''
        order=('qq','netease') if player=='QQ音乐' else (('netease','qq') if player=='网易云音乐' else ('qq','netease'))
        def work():
            path=''; provenance=''; err=''
            try:
                http=globals().get('requests')
                if http is None: raise RuntimeError('http-client-unavailable')
                headers={'User-Agent':'Mozilla/5.0','Referer':'https://music.163.com/'}
                for provider in order:
                    if provider=='qq': path,provenance=_h91_fetch_qq_art(http,song,artist,duration,headers,out_path)
                    else: path,provenance=_h91_fetch_netease_art(http,song,artist,duration,headers,preferred_id,out_path)
                    if path: break
                if not path: raise RuntimeError('cover-not-found-after-shared-qq+netease')
            except Exception as exc: err=f'{type(exc).__name__}: {exc}'
            try:
                if q is not None: q.put((str(key),int(serial),str(path),str(err),str(provenance)))
            except Exception: pass
        threading.Thread(target=work,name='LimbusLyric-H91SharedCover',daemon=True).start()
    except Exception as exc:
        try: write_error_log('H91共享封面请求失败',exc)
        except Exception: pass


def _h91_poll_art_results(panel):
    q=getattr(panel,'_h87_art_results',None)
    if q is None: return
    changed=False
    while True:
        try: item=q.get_nowait()
        except queue.Empty: break
        except Exception: break
        try:
            key,serial,path,err,provenance=item if len(item)>=5 else (*item[:4],'legacy')
        except Exception: continue
        active=dict(getattr(panel,'_h87_art_active',{}) or {})
        if int(active.get(str(key),0) or 0)!=int(serial or 0): continue
        active.pop(str(key),None); panel._h87_art_active=active
        if str(err or '')=='stale-cancelled':
            continue
        negative=dict(getattr(panel,'_h88_art_negative',{}) or {})
        _s,_a,current,_state=_h91_current_visual_identity(panel)
        loaded=panel._track_identity(getattr(panel,'_loaded_song',''),getattr(panel,'_loaded_artist',''))
        if path:
            negative.pop(str(key),None); color=_h91_share_art_color(panel,key,path)
            if str(current)==str(key) or str(loaded)==str(key): changed=_h87_set_panel_art(panel,path,key) or changed
            try: write_error_log('H91共享封面就绪',detail=f'key={key} | source={provenance} | color={color or "none"} | record=1 | cover-follow=shared')
            except Exception: pass
        else:
            negative[str(key)]=time.monotonic()+float(H91_ART_NEGATIVE_RETRY_SEC)
            if err:
                try: write_error_log('H91共享封面获取失败',detail=f'key={key} | retry={int(H91_ART_NEGATIVE_RETRY_SEC)}s | error={err}')
                except Exception: pass
        panel._h88_art_negative=negative
    if changed and '_h87_prune_art_cache' in globals(): _h87_prune_art_cache()


def _h91_cover_tick(panel):
    """Cover-follow and record artwork share one image acquisition/cache path."""
    try:
        if not bool(getattr(panel,'_h12_cover_follow',False)): return
        song=str(getattr(panel,'_loaded_song','') or '').strip(); artist=str(getattr(panel,'_loaded_artist','') or '').strip()
        key=panel._track_identity(song,artist) if song else ''
        if not key: return
        cached=_h87_cached_art_path(key) if '_h87_cached_art_path' in globals() else ''
        if cached:
            _h91_share_art_color(panel,key,cached); return
        # A persisted colour can still apply instantly, but RGB alone cannot reconstruct album art;
        # keep one shared artwork request running so the record can be populated as well.
        color=str((getattr(panel,'_h16_cover_cache',{}) or {}).get(str(key)) or '')
        if not color:
            item=(getattr(panel,'_h85_cover_persistent',{}) or {}).get(str(key)) or {}; color=str(item.get('color') or '')
            if color:
                memory=dict(getattr(panel,'_h16_cover_cache',{}) or {}); memory[str(key)]=color; panel._h16_cover_cache=memory
        if color:
            applied=getattr(panel,'_h12_cover_applied',None)
            if not applied or str(applied[0])!=str(key) or str(applied[1]).lower()!=color.lower(): panel._h12_cover_result=(str(key),color)
        state=panel.media_sync.snapshot() or {}; _h91_request_art(panel,song,artist,state.get('duration_ms') or 0)
    except Exception:
        if callable(_h91_cover_tick_pre):
            try: return _h91_cover_tick_pre(panel)
            except Exception: pass


def _h91_refresh_frontend_status(panel,*args,**kwargs):
    out=_h91_front_status_pre(panel,*args,**kwargs) if callable(_h91_front_status_pre) else None
    try:
        song,artist,state=_h91_source_affine_media(panel)
        if not song: return out
        key=panel._track_identity(song,artist)
        # Media identity owns only the shell presentation. Lyrics remain owned by the existing
        # auto-search transaction and are allowed to bind later without being rewritten here.
        panel.front_track_label.setText(song+(f'  ·  {artist}' if artist else ''))
        panel._h91_presented_media_key=str(key)
        if str(key)!=str(getattr(panel,'_h91_last_art_probe_key','') or ''):
            panel._h91_last_art_probe_key=str(key)
            _h91_request_art(panel,song,artist,state.get('duration_ms') or 0)
    except Exception: pass
    return out


def _h91_ambient_paint(self,_event):
    """Scale the record with Hero height so splitter compression stays intentional, not clipped."""
    panel=getattr(self,'_panel',None)
    if panel is None or 'QPainter' not in globals():
        if callable(_h91_ambient_paint_pre): return _h91_ambient_paint_pre(self,_event)
        return
    _h87_prepare_ambient(self)
    p=QPainter(self); p.setRenderHint(QPainter.Antialiasing,True); p.setRenderHint(QPainter.SmoothPixmapTransform,True)
    rect=QRectF(self.rect()); classic=_h87_frontend_theme(panel)=='classic' if '_h87_frontend_theme' in globals() else False
    clip=QPainterPath(); clip.addRoundedRect(rect,18,18); p.setClipPath(clip)
    grad=QLinearGradient(rect.topLeft(),rect.bottomRight())
    if classic: grad.setColorAt(0,QColor('#211b1e')); grad.setColorAt(.58,QColor('#17171b')); grad.setColorAt(1,QColor('#302227'))
    else: grad.setColorAt(0,QColor('#20322e')); grad.setColorAt(.58,QColor('#17241f')); grad.setColorAt(1,QColor('#332f24'))
    p.fillRect(rect,grad)
    accent=_h79_ambient_color(panel) if '_h79_ambient_color' in globals() else QColor('#c9ac77')
    r=max(32.0,min(66.0,(rect.height()-18.0)*0.46)); center=QPointF(rect.right()-max(r+18.0,58.0),rect.center().y()+2.0)
    glow=QRadialGradient(center,r*2.25); glow.setColorAt(0,QColor(accent.red(),accent.green(),accent.blue(),48)); glow.setColorAt(1,QColor(accent.red(),accent.green(),accent.blue(),0)); p.fillRect(rect,glow)
    p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,78)); p.drawEllipse(QPointF(center.x()+2,center.y()+3),r+2,r+2)
    p.setBrush(QColor('#0f1514' if not classic else '#121114')); p.setPen(QPen(QColor(202,190,151,42),1)); p.drawEllipse(center,r,r)
    current=getattr(self,'_h87_cover',QPixmap()); previous=getattr(self,'_h87_prev_cover',QPixmap()); angle=float(getattr(self,'_h87_angle',0.0) or 0.0)
    fade=1.0; started=float(getattr(self,'_h87_cover_started',0.0) or 0.0)
    if started>0:
        t=max(0.0,min(1.0,((time.monotonic()-started)*1000.0)/float(H87_COVER_FADE_MS))); fade=1.0-math.pow(1.0-t,3.0)
        if t>=1.0: self._h87_cover_started=0.0; self._h87_prev_cover=QPixmap()
    cr=r*.88; drew=False
    if previous is not None and not previous.isNull() and fade<1.0: drew=_h87_draw_record_cover(p,previous,center,cr,angle,1.0-fade) or drew
    if current is not None and not current.isNull(): drew=_h87_draw_record_cover(p,current,center,cr,angle,fade) or drew
    if not drew: p.setPen(Qt.NoPen); p.setBrush(QColor('#18211e' if not classic else '#1a171a')); p.drawEllipse(center,cr,cr)
    p.setBrush(Qt.NoBrush)
    for frac in (.48,.58,.68,.78,.88): p.setPen(QPen(QColor(228,218,188,20),1)); p.drawEllipse(center,r*frac,r*frac)
    p.setPen(Qt.NoPen); p.setBrush(QColor('#d0b278' if not classic else '#c88b96')); p.drawEllipse(center,max(6.0,r*.17),max(6.0,r*.17)); p.setBrush(QColor('#1c2924')); p.drawEllipse(center,max(2.5,r*.055),max(2.5,r*.055))
    if rect.height()>=132:
        p.setPen(QColor('#c9b68d' if not classic else '#c79da5')); p.setFont(QFont('Segoe UI',8)); p.drawText(QRectF(rect.right()-154,10,138,18),Qt.AlignCenter,'L I S T E N I N G  R O O M')
    p.end()


