# H92 navigation-button drag gesture arbitration ---------------------------------------------
# H91 intentionally listened only to the topNav background so child buttons kept ordinary click
# semantics. In Qt, however, mouse events delivered to child QPushButtons do not flow through the
# parent's eventFilter. H92 installs a second, presentation-only arbiter on the nav children:
# a short press/release remains a normal page click, while dominant vertical movement >=7 px
# promotes the gesture to Hero/workspace resizing and suppresses the pending button click.
H92_NAV_DRAG_THRESHOLD_PX = 7

_H92_QOBJECT_BASE = globals().get('QObject', object)
class H92NavButtonDragGesture(_H92_QOBJECT_BASE):
    """Allow the whole page navigation strip, including buttons, to resize the Hero."""
    def __init__(self, panel, nav):
        super().__init__(nav)
        self.panel = panel
        self.nav = nav
        self.pending = False
        self.dragging = False
        self.press_obj = None
        self.start_x = 0
        self.start_y = 0
        self.start_h = H91_HERO_DEFAULT_H
        self._watched = []
        self._watch(nav)
        try:
            for child in nav.findChildren(QWidget):
                self._watch(child)
        except Exception:
            pass
        try:
            nav.setToolTip('整条页面栏都可上下拖动：拖动压缩 / 展开歌曲与唱片区域；轻点按钮仍正常切页')
        except Exception:
            pass

    def _watch(self, obj):
        if obj is None or obj in self._watched:
            return
        try:
            obj.installEventFilter(self)
            self._watched.append(obj)
        except Exception:
            pass

    def _global_xy(self, event):
        try:
            pt = event.globalPos()
            return int(pt.x()), int(pt.y())
        except Exception:
            try:
                pt = event.globalPosition()
                return int(pt.x()), int(pt.y())
            except Exception:
                return 0, 0

    def _cancel_pressed_control(self):
        obj = self.press_obj
        try:
            fn = getattr(obj, 'setDown', None)
            if callable(fn):
                fn(False)
        except Exception:
            pass

    def _finish_drag(self):
        self._cancel_pressed_control()
        self.pending = False
        self.dragging = False
        self.press_obj = None
        try:
            self.nav.setCursor(Qt.SizeVerCursor)
        except Exception:
            pass
        try:
            _h91_apply_hero_height(
                self.panel,
                getattr(self.panel, '_h91_hero_height', self.start_h),
                True,
            )
        except Exception:
            pass

    def eventFilter(self, obj, event):
        if obj not in self._watched:
            return False
        try:
            kind = event.type()
            if kind == QEvent.MouseButtonPress and event.button() == Qt.LeftButton:
                self.start_x, self.start_y = self._global_xy(event)
                self.start_h = int(
                    getattr(self.panel, '_h91_hero_height', H91_HERO_DEFAULT_H)
                    or H91_HERO_DEFAULT_H
                )
                self.press_obj = obj
                self.dragging = False
                # Preserve H91 background behaviour. For child buttons, wait until movement proves
                # drag intent before consuming anything so an ordinary click remains untouched.
                if obj is self.nav:
                    return False
                self.pending = True
                return False

            if kind == QEvent.MouseMove and (event.buttons() & Qt.LeftButton) and (self.pending or self.dragging):
                gx, gy = self._global_xy(event)
                dx = gx - self.start_x
                dy = gy - self.start_y
                if self.pending:
                    if abs(dy) < int(H92_NAV_DRAG_THRESHOLD_PX) or abs(dy) < abs(dx):
                        return False
                    self.pending = False
                    self.dragging = True
                    self._cancel_pressed_control()
                    try:
                        self.nav.setCursor(Qt.SplitVCursor)
                    except Exception:
                        pass
                if self.dragging:
                    _h91_apply_hero_height(self.panel, self.start_h + dy, False)
                    event.accept()
                    return True

            if kind == QEvent.MouseButtonRelease and event.button() == Qt.LeftButton:
                if self.dragging:
                    self._finish_drag()
                    event.accept()
                    return True
                # Threshold was never crossed: do not consume release; QPushButton may emit clicked.
                self.pending = False
                self.press_obj = None
                return False
        except Exception:
            self.pending = False
            self.dragging = False
            self.press_obj = None
        return False


def _h92_install_nav_drag(panel):
    nav = getattr(panel, 'top_nav', None)
    if nav is None:
        return
    # H91's background splitter remains installed and owns empty-space dragging. H92 only adds
    # arbitration on child controls; both routes write the same presentation-only Hero height.
    panel._h92_nav_button_drag = H92NavButtonDragGesture(panel, nav)


_h92_control_init_pre = globals().get('ControlPanel').__init__ if 'ControlPanel' in globals() else None

def _h92_control_init(panel, *args, **kwargs):
    if callable(_h92_control_init_pre):
        _h92_control_init_pre(panel, *args, **kwargs)
    try:
        _h92_install_nav_drag(panel)
    except Exception as exc:
        try:
            write_error_log('H92页面栏按钮拖拽安装失败', exc)
        except Exception:
            pass


if 'ControlPanel' in globals() and callable(_h92_control_init_pre):
    try:
        ControlPanel.__init__ = _h92_control_init
        ControlPanel.__init__._limbus_layer = 'H92'
        ControlPanel.__init__._limbus_policy = 'nav buttons click-or-vertical-drag gesture; presentation-only'
    except Exception as exc:
        try:
            write_error_log('H92页面栏按钮拖拽层激活失败', exc)
        except Exception:
            pass

# H93 explicit workspace grip ---------------------------------------------------------------
# H91/H92 tried to infer a vertical-resize gesture from the page navigation background/buttons.
# Real Qt style/platform delivery can keep those gestures inside child controls. H93 retires the
# inferred gesture routes and installs one explicit grip directly under topNav. The visible mark is
# intentionally tiny, while the transparent hit target is much taller. During a drag an application-
# level event filter is temporarily installed as a second capture path, so a Windows/Qt mouse-grab
# quirk cannot strand the gesture when the pointer leaves the visual mark.
# Presentation geometry only; player/lyric/transport authority is untouched.
H93_GRIP_HEIGHT = 20
H93_GRIP_HIT_WIDTH = 72
H93_GRIP_HIT_HEIGHT = 14
H93_GRIP_LINE_WIDTH = 52
H93_GRIP_LINE_HEIGHT = 3
H93_HERO_MIN_H = 28
# Keep a non-zero collapsed height: several historical persistence/start-drag paths intentionally
# use truthy fallback semantics. 28 px is visually near-collapsed without turning 0 into "default".
H91_HERO_MIN_H = H93_HERO_MIN_H

_H93_QOBJECT_BASE = globals().get('QObject', object)
class H93WorkspaceGrip(_H93_QOBJECT_BASE):
    def __init__(self, panel, grip):
        super().__init__(grip)
        self.panel = panel
        self.grip = grip
        self.dragging = False
        self.start_y = 0
        self.start_h = H91_HERO_DEFAULT_H
        self._app_filter_installed = False
        grip.installEventFilter(self)
        try:
            grip.setMouseTracking(True)
            grip.setCursor(Qt.SplitVCursor)
            grip.setToolTip('上下拖动：压缩 / 展开歌曲与唱片区域；双击恢复默认高度')
        except Exception:
            pass

    def _global_y(self, event):
        try:
            return int(event.globalPos().y())
        except Exception:
            try:
                return int(event.globalPosition().y())
            except Exception:
                try:
                    return int(QCursor.pos().y())
                except Exception:
                    return 0

    def _install_app_capture(self):
        if self._app_filter_installed:
            return
        try:
            app = QApplication.instance()
            if app is not None:
                app.installEventFilter(self)
                self._app_filter_installed = True
        except Exception:
            pass

    def _remove_app_capture(self):
        if not self._app_filter_installed:
            return
        try:
            app = QApplication.instance()
            if app is not None:
                app.removeEventFilter(self)
        except Exception:
            pass
        self._app_filter_installed = False

    def _finish_drag(self, persist=True):
        if not self.dragging:
            self._remove_app_capture()
            return
        self.dragging = False
        try:
            self.grip.releaseMouse()
        except Exception:
            pass
        self._remove_app_capture()
        if persist:
            _h91_apply_hero_height(
                self.panel,
                getattr(self.panel, '_h91_hero_height', self.start_h),
                True,
            )

    def eventFilter(self, obj, event):
        is_grip = obj is self.grip
        if not is_grip and not self.dragging:
            return False
        try:
            kind = event.type()
            if is_grip and kind == QEvent.MouseButtonDblClick and event.button() == Qt.LeftButton:
                _h91_apply_hero_height(self.panel, H91_HERO_DEFAULT_H, True)
                event.accept()
                return True
            if is_grip and kind == QEvent.MouseButtonPress and event.button() == Qt.LeftButton:
                self.dragging = True
                self.start_y = self._global_y(event)
                current = getattr(self.panel, '_h91_hero_height', H91_HERO_DEFAULT_H)
                self.start_h = int(H91_HERO_DEFAULT_H if current is None else current)
                self._install_app_capture()
                try:
                    self.grip.grabMouse()
                except Exception:
                    pass
                event.accept()
                return True
            if self.dragging and kind == QEvent.MouseMove:
                # Do not rely solely on event.buttons(): on some Windows/Qt paths the move can be
                # rerouted while QWidget::grabMouse is active. The active drag state is authoritative.
                dy = self._global_y(event) - self.start_y
                _h91_apply_hero_height(self.panel, self.start_h + dy, False)
                event.accept()
                return True
            if self.dragging and kind == QEvent.MouseButtonRelease:
                self._finish_drag(True)
                event.accept()
                return True
            if self.dragging and kind in (
                getattr(QEvent, 'WindowDeactivate', -10001),
                getattr(QEvent, 'ApplicationDeactivate', -10002),
            ):
                self._finish_drag(True)
                return False
        except Exception:
            self._finish_drag(False)
        return False


def _h93_retire_inferred_nav_drag(panel):
    """Remove H91/H92 nav event filters so the nav returns to click-only behaviour."""
    nav = getattr(panel, 'top_nav', None)
    if nav is None:
        return
    old = getattr(panel, '_h91_workspace_splitter', None)
    if old is not None:
        try:
            nav.removeEventFilter(old)
        except Exception:
            pass
    old2 = getattr(panel, '_h92_nav_button_drag', None)
    if old2 is not None:
        for obj in list(getattr(old2, '_watched', ()) or ()):
            try:
                obj.removeEventFilter(old2)
            except Exception:
                pass
    try:
        nav.setCursor(Qt.ArrowCursor)
        nav.setToolTip('切换设置页面')
    except Exception:
        pass
    for btn in list(getattr(panel, '_sidebar_buttons', ()) or ()):
        try:
            btn.setCursor(Qt.PointingHandCursor)
        except Exception:
            pass


def _h93_install_workspace_grip(panel):
    nav = getattr(panel, 'top_nav', None)
    shell = getattr(panel, 'settings_shell', None)
    if nav is None or shell is None:
        return False
    layout = shell.layout()
    if layout is None:
        return False
    _h93_retire_inferred_nav_drag(panel)
    old_filter = getattr(panel, '_h93_workspace_grip_filter', None)
    if old_filter is not None:
        try:
            old_filter._finish_drag(False)
        except Exception:
            pass
    old_grip = getattr(panel, 'h93_workspace_grip', None)
    if old_grip is not None:
        try:
            old_grip.deleteLater()
        except Exception:
            pass
    old_row = getattr(panel, 'h93_workspace_grip_row', None)
    if old_row is not None:
        try:
            old_row.deleteLater()
        except Exception:
            pass
    # The row reserves a little vertical breathing room, but it is deliberately passive. Only the
    # compact centered hit target below owns the drag filter, so blank space across the row no longer
    # starts a workspace resize.
    row = QFrame(shell)
    row.setObjectName('h93WorkspaceGripRow')
    row.setFixedHeight(int(H93_GRIP_HEIGHT))
    row.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    row.setStyleSheet('QFrame#h93WorkspaceGripRow { background: transparent; border: none; }')
    row_layout = QHBoxLayout(row)
    row_layout.setContentsMargins(0, 0, 0, 0)
    row_layout.setSpacing(0)

    grip = QFrame(row)
    grip.setObjectName('h93WorkspaceGrip')
    grip.setFixedSize(int(H93_GRIP_HIT_WIDTH), int(H93_GRIP_HIT_HEIGHT))
    grip.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
    grip.setStyleSheet(
        'QFrame#h93WorkspaceGrip {'
        'background: transparent; border: none; border-radius: 7px;'
        '}'
        'QFrame#h93WorkspaceGrip:hover {'
        'background: rgba(214,187,119,10);'
        '}'
        'QFrame#h93WorkspaceGripMark {'
        'background: rgba(214,187,119,92); border: none; border-radius: 1px;'
        '}'
        'QFrame#h93WorkspaceGrip:hover QFrame#h93WorkspaceGripMark {'
        'background: rgba(214,187,119,178);'
        '}'
    )
    grip_layout = QHBoxLayout(grip)
    grip_layout.setContentsMargins(0, 0, 0, 0)
    grip_layout.setSpacing(0)
    mark = QFrame(grip)
    mark.setObjectName('h93WorkspaceGripMark')
    mark.setFixedSize(int(H93_GRIP_LINE_WIDTH), int(H93_GRIP_LINE_HEIGHT))
    try:
        mark.setAttribute(Qt.WA_TransparentForMouseEvents, True)
    except Exception:
        pass
    grip_layout.addStretch(1)
    grip_layout.addWidget(mark, 0, Qt.AlignCenter)
    grip_layout.addStretch(1)
    row_layout.addStretch(1)
    row_layout.addWidget(grip, 0, Qt.AlignCenter)
    row_layout.addStretch(1)

    # Keep the passive row directly below topNav. Hero remains bounded above, so neither drag
    # extreme can remove the compact recovery handle.
    nav_index = layout.indexOf(nav)
    layout.insertWidget(max(0, nav_index + 1), row)
    panel.h93_workspace_grip_row = row
    panel.h93_workspace_grip = grip
    panel._h93_workspace_grip_filter = H93WorkspaceGrip(panel, grip)
    return True

def _h93_restore_persisted_frontend_theme(panel):
    """Commit the persisted frontend palette after every older UI layer has initialized.

    H87 owns the palette setting, while H88-H93 wrap ControlPanel.__init__ afterwards. A final
    reconciliation here guarantees that a late Studio stylesheet write cannot win only on the
    first frame. Manual palette switching already calls the same runtime apply function.
    """
    try:
        settings = (load_all_config().get('settings') or {}) if 'load_all_config' in globals() else {}
        saved = str(settings.get('h87_frontend_theme', getattr(panel, '_h87_frontend_theme', H87_FRONTEND_DEFAULT)) or H87_FRONTEND_DEFAULT).lower()
        theme = 'classic' if saved == 'classic' else 'studio'
        panel._h87_frontend_theme = theme
        apply_theme = globals().get('_h87_apply_frontend_theme')
        if callable(apply_theme):
            apply_theme(panel, theme, False)
        return True
    except Exception as exc:
        try: write_error_log('H93启动前端风格恢复失败', exc)
        except Exception: pass
        return False


_h93_control_init_pre = globals().get('ControlPanel').__init__ if 'ControlPanel' in globals() else None

def _h93_control_init(panel, *args, **kwargs):
    if callable(_h93_control_init_pre):
        _h93_control_init_pre(panel, *args, **kwargs)
    try:
        _h93_install_workspace_grip(panel)
    except Exception as exc:
        try:
            write_error_log('H93工作区显式拖把手安装失败', exc)
        except Exception:
            pass
    # This wrapper is the final control-panel init layer in this build, so it owns the last
    # palette commit. Run once now and once at the end of the queued 0-ms startup work.
    _h93_restore_persisted_frontend_theme(panel)
    try:
        QTimer.singleShot(0, lambda p=panel: _h93_restore_persisted_frontend_theme(p))
    except Exception:
        pass


if 'ControlPanel' in globals() and callable(_h93_control_init_pre):
    try:
        ControlPanel.__init__ = _h93_control_init
        ControlPanel.__init__._limbus_layer = 'H93'
        ControlPanel.__init__._limbus_policy = 'explicit workspace grip; inferred nav drag retired; presentation-only'
    except Exception as exc:
        try:
            write_error_log('H93工作区显式拖把手层激活失败', exc)
        except Exception:
            pass

# H94 Spotify lyric fallback -------------------------------------------------------------
# Playback remains H13's strict Windows-local GSMTC lane. H94 only extends the lyric-content
# fallback chain after NetEase/QQ/KuGou have all failed. It never owns seek, playback state,
# player identity, or duration. The documented Musixmatch API is preferred when the user has
# supplied an API key. Spotify's Web Player color-lyrics endpoint is best-effort only: it is
# an internal endpoint, may change without notice, and is bounded so failure cannot stall the
# existing three-provider pipeline. No browser-cookie scraping or implicit credential capture.
H94_SPOTIFY_LYRIC_FALLBACK_ENABLED = str(os.environ.get('LIMBUSLYRIC_SPOTIFY_LYRIC_FALLBACK', '1')).strip().lower() not in {
    '0', 'false', 'off', 'no'
}
H94_SPOTIFY_INTERNAL_LYRICS_ENABLED = str(os.environ.get('LIMBUSLYRIC_SPOTIFY_INTERNAL_LYRICS', '1')).strip().lower() not in {
    '0', 'false', 'off', 'no'
}
H94_SPOTIFY_CONNECT_TIMEOUT = 2.2
H94_SPOTIFY_READ_TIMEOUT = 4.2
_H94_SPOTIFY_TOKEN_LOCK = threading.Lock()
_H94_SPOTIFY_TOKEN_CACHE = {'token': '', 'expires_ms': 0, 'authenticated': False}
_H94_ACTIVE_FALLBACK_LOCK = threading.Lock()
_H94_ACTIVE_FALLBACKS = set()


def _h94_ms_to_lrc_tag(value):
    try:
        ms = max(0, int(float(value or 0)))
    except Exception:
        ms = 0
    minutes, remain = divmod(ms, 60000)
    seconds, millis = divmod(remain, 1000)
    return f'[{minutes:02d}:{seconds:02d}.{millis:03d}]'


def _h94_lrc_has_timed_rows(text):
    return bool(re.search(r'\[\d{1,3}:\d{1,2}(?:[.:]\d{1,3})?\]', str(text or '')))


def _h94_spotify_token(force=False):
    """Return a short-lived Web Player token without reading local browser credential stores.

    Optional credentials are explicit environment variables only. ``sp_dc`` is account-secret
    material, so it is never logged, persisted by H94, or copied from a browser automatically.
    """
    if not H94_SPOTIFY_INTERNAL_LYRICS_ENABLED or LyricSearchEngine._is_cancelled():
        return '', False
    now_ms = int(time.time() * 1000.0)
    with _H94_SPOTIFY_TOKEN_LOCK:
        cached = dict(_H94_SPOTIFY_TOKEN_CACHE)
        if not force and cached.get('token') and int(cached.get('expires_ms') or 0) - now_ms > 60000:
            return str(cached.get('token') or ''), bool(cached.get('authenticated'))

    explicit = str(os.environ.get('LIMBUSLYRIC_SPOTIFY_BEARER_TOKEN', '') or '').strip()
    if explicit:
        with _H94_SPOTIFY_TOKEN_LOCK:
            _H94_SPOTIFY_TOKEN_CACHE.update(token=explicit, expires_ms=now_ms + 20 * 60 * 1000, authenticated=True)
        return explicit, True

    sp_dc = str(os.environ.get('LIMBUSLYRIC_SPOTIFY_SP_DC', '') or '').strip()
    cookies = {'sp_dc': sp_dc} if sp_dc else None
    try:
        response = requests.get(
            'https://open.spotify.com/get_access_token',
            params={'reason': 'transport', 'productType': 'web_player'},
            headers={**LyricSearchEngine.HEADERS, 'Accept': 'application/json'},
            cookies=cookies,
            timeout=(H94_SPOTIFY_CONNECT_TIMEOUT, H94_SPOTIFY_READ_TIMEOUT),
        )
        response.raise_for_status()
        obj = response.json() if response.content else {}
        token = str((obj or {}).get('accessToken') or '').strip()
        if not token:
            return '', False
        expires_ms = int((obj or {}).get('accessTokenExpirationTimestampMs') or (now_ms + 45 * 60 * 1000))
        authenticated = bool(sp_dc and not bool((obj or {}).get('isAnonymous', False)))
        with _H94_SPOTIFY_TOKEN_LOCK:
            _H94_SPOTIFY_TOKEN_CACHE.update(token=token, expires_ms=expires_ms, authenticated=authenticated)
        return token, authenticated
    except Exception as exc:
        try:
            write_error_log('H94 Spotify Web令牌不可用', detail=f'{type(exc).__name__} | credential_capture=0 | soft_fail=1')
        except Exception:
            pass
        return '', False


def _h94_spotify_candidate_score(song_name, artist, expected_duration_ms, row):
    if not isinstance(row, dict):
        return None
    candidate_song = str(row.get('name') or '').strip()
    artists = row.get('artists') if isinstance(row.get('artists'), list) else []
    candidate_artist = ', '.join(str(x.get('name') or '').strip() for x in artists if isinstance(x, dict) and x.get('name')).strip()
    q_song = _clean_name(song_name)
    c_song = _clean_name(candidate_song)
    if not q_song or not c_song:
        return None
    title_exact = q_song == c_song
    title_safe = title_exact or (len(q_song) >= 4 and (q_song in c_song or c_song in q_song))
    if not title_safe:
        return None
    artist_ok = True
    if str(artist or '').strip():
        artist_ok, _alias = _artist_alias_match(artist, candidate_artist)
        if not artist_ok:
            return None
    expected = int(expected_duration_ms or 0)
    candidate_duration = int(row.get('duration_ms') or 0)
    duration_delta = None
    if expected > 0:
        if candidate_duration <= 0:
            return None
        duration_delta = abs(expected - candidate_duration)
        if duration_delta > max(3500, int(max(expected, candidate_duration) * 0.025)):
            return None
    elif not str(artist or '').strip():
        # No artist and no duration is not enough evidence for a fourth-provider borrow.
        return None
    score = (120 if title_exact else 75) + (75 if str(artist or '').strip() and artist_ok else 15)
    if duration_delta is not None:
        score += max(0, 45 - int(duration_delta / 100))
    return score, candidate_duration, candidate_song, candidate_artist


def _h94_spotify_search_track(song_name, artist='', expected_duration_ms=0):
    token, authenticated = _h94_spotify_token()
    if not token or LyricSearchEngine._is_cancelled():
        return None, authenticated
    query = f'track:{song_name}' + (f' artist:{artist}' if str(artist or '').strip() else '')
    headers = {
        **LyricSearchEngine.HEADERS,
        'Authorization': f'Bearer {token}',
        'Accept': 'application/json',
    }
    try:
        response = requests.get(
            'https://api.spotify.com/v1/search',
            params={'q': query, 'type': 'track', 'limit': 8},
            headers=headers,
            timeout=(H94_SPOTIFY_CONNECT_TIMEOUT, H94_SPOTIFY_READ_TIMEOUT),
        )
        if response.status_code in (401, 403):
            with _H94_SPOTIFY_TOKEN_LOCK:
                _H94_SPOTIFY_TOKEN_CACHE.update(token='', expires_ms=0, authenticated=False)
            return None, authenticated
        response.raise_for_status()
        rows = (((response.json() or {}).get('tracks') or {}).get('items') or [])
        best = None
        for row in rows if isinstance(rows, list) else []:
            scored = _h94_spotify_candidate_score(song_name, artist, expected_duration_ms, row)
            if not scored:
                continue
            score, candidate_duration, candidate_song, candidate_artist = scored
            item = (score, row, candidate_duration, candidate_song, candidate_artist)
            if best is None or item[0] > best[0]:
                best = item
        if best is None:
            return None, authenticated
        row = dict(best[1])
        row['_h94_duration_ms'] = int(best[2] or 0)
        row['_h94_song'] = best[3]
        row['_h94_artist'] = best[4]
        return row, authenticated
    except Exception as exc:
        try:
            write_error_log('H94 Spotify曲目检索失败', detail=f'{type(exc).__name__} | soft_fail=1')
        except Exception:
            pass
        return None, authenticated


def _h94_spotify_color_lyrics(song_name, artist='', expected_duration_ms=0):
    if not H94_SPOTIFY_INTERNAL_LYRICS_ENABLED or LyricSearchEngine._is_cancelled():
        return '', 0, {}
    track, authenticated = _h94_spotify_search_track(song_name, artist, expected_duration_ms)
    if not isinstance(track, dict):
        return '', 0, {}
    track_id = str(track.get('id') or '').strip()
    if not track_id:
        return '', 0, {}
    token, authenticated_now = _h94_spotify_token()
    authenticated = bool(authenticated or authenticated_now)
    if not token:
        return '', 0, {}
    headers = {
        **LyricSearchEngine.HEADERS,
        'Authorization': f'Bearer {token}',
        'App-Platform': 'WebPlayer',
        'Accept': 'application/json',
    }
    try:
        response = requests.get(
            f'https://spclient.wg.spotify.com/color-lyrics/v2/track/{urllib.parse.quote(track_id, safe="")}',
            params={'format': 'json', 'market': 'from_token'},
            headers=headers,
            timeout=(H94_SPOTIFY_CONNECT_TIMEOUT, H94_SPOTIFY_READ_TIMEOUT),
        )
        if response.status_code in (401, 403):
            try:
                write_error_log('H94 Spotify歌词鉴权不可用', detail=f'authenticated={int(authenticated)} | status={response.status_code} | soft_fail=1')
            except Exception:
                pass
            return '', 0, {}
        if response.status_code == 404:
            return '', 0, {}
        response.raise_for_status()
        payload = response.json() or {}
        lyric_obj = payload.get('lyrics') if isinstance(payload.get('lyrics'), dict) else {}
        sync_type = str(lyric_obj.get('syncType') or '').upper()
        rows = lyric_obj.get('lines') if isinstance(lyric_obj.get('lines'), list) else []
        if sync_type != 'LINE_SYNCED' or not rows:
            return '', 0, {}
        out = []
        last_start = -1
        for row in rows:
            if not isinstance(row, dict):
                continue
            words = str(row.get('words') or '').strip()
            if not words:
                continue
            try:
                start = int(float(row.get('startTimeMs') or 0))
            except Exception:
                continue
            if start < 0 or start < last_start:
                continue
            last_start = start
            out.append(_h94_ms_to_lrc_tag(start) + words)
        lrc = '\n'.join(out).strip()
        if not lrc or not _h94_lrc_has_timed_rows(lrc):
            return '', 0, {}
        duration = int(track.get('_h94_duration_ms') or track.get('duration_ms') or expected_duration_ms or 0)
        meta = {
            'source': 'Spotify',
            'lyric_payload_source': 'Spotify',
            'spotify_track_id': track_id,
            'spotify_lyrics_internal': True,
            'spotify_lyrics_authenticated': bool(authenticated),
            'spotify_lyrics_provider': str(lyric_obj.get('providerDisplayName') or lyric_obj.get('provider') or 'Musixmatch'),
            'spotify_sync_type': sync_type,
            'h94_fallback': True,
        }
        return lrc, duration, meta
    except Exception as exc:
        try:
            write_error_log('H94 Spotify内部歌词失败', detail=f'{type(exc).__name__} | soft_fail=1')
        except Exception:
            pass
        return '', 0, {}


def _h94_musixmatch_lyrics(song_name, artist='', expected_duration_ms=0):
    """Documented licensed fallback. The API key must be supplied explicitly by the user."""
    key = str(os.environ.get('LIMBUSLYRIC_MUSIXMATCH_API_KEY', '') or '').strip()
    if not key or LyricSearchEngine._is_cancelled():
        return '', 0, {}
    expected = int(expected_duration_ms or 0)
    params = {
        'q_track': str(song_name or '').strip(),
        'q_artist': str(artist or '').strip(),
        'subtitle_format': 'lrc',
        'apikey': key,
    }
    if expected > 0:
        params['f_subtitle_length'] = max(1, int(round(expected / 1000.0)))
        params['f_subtitle_length_max_deviation'] = max(2, int(round(max(2500, expected * 0.02) / 1000.0)))
    try:
        response = requests.get(
            'https://api.musixmatch.com/ws/1.1/matcher.subtitle.get',
            params=params,
            headers=LyricSearchEngine.HEADERS,
            timeout=(H94_SPOTIFY_CONNECT_TIMEOUT, H94_SPOTIFY_READ_TIMEOUT),
        )
        response.raise_for_status()
        obj = response.json() or {}
        message = obj.get('message') if isinstance(obj.get('message'), dict) else {}
        header = message.get('header') if isinstance(message.get('header'), dict) else {}
        if int(header.get('status_code') or 0) != 200:
            return '', 0, {}
        body = message.get('body') if isinstance(message.get('body'), dict) else {}
        subtitle = body.get('subtitle') if isinstance(body.get('subtitle'), dict) else {}
        lrc = str(subtitle.get('subtitle_body') or '').strip()
        if not lrc or not _h94_lrc_has_timed_rows(lrc):
            return '', 0, {}
        meta = {
            'source': 'Spotify/Musixmatch',
            'lyric_payload_source': 'Spotify/Musixmatch',
            'spotify_lyrics_provider': 'Musixmatch',
            'musixmatch_subtitle_id': str(subtitle.get('subtitle_id') or ''),
            'h94_fallback': True,
        }
        return lrc, expected, meta
    except Exception as exc:
        try:
            write_error_log('H94 Musixmatch歌词失败', detail=f'{type(exc).__name__} | api_key_logged=0 | soft_fail=1')
        except Exception:
            pass
        return '', 0, {}


def _h94_fetch_spotify_lyric_fallback(song_name, artist='', expected_duration_ms=0):
    if not H94_SPOTIFY_LYRIC_FALLBACK_ENABLED or LyricSearchEngine._is_cancelled():
        return '', 0, {}
    # Prefer Musixmatch's documented/credentialed API because Spotify states that Musixmatch
    # supplies its licensed synced lyrics. The internal Web Player endpoint is a second, best-
    # effort lane only; neither lane is allowed to become playback authority.
    lrc, duration, meta = _h94_musixmatch_lyrics(song_name, artist, expected_duration_ms)
    if lrc:
        return lrc, duration, meta
    return _h94_spotify_color_lyrics(song_name, artist, expected_duration_ms)


def _h94_result_needs_spotify_fallback(row, *, path='auto'):
    row = dict(row or {})
    if not H94_SPOTIFY_LYRIC_FALLBACK_ENABLED:
        return False
    if row.get('h94_spotify_fallback_attempted'):
        return False
    if bool(row.get('trans_only')) or bool(row.get('cancelled')):
        return False
    if str(row.get('source') or '') not in LYRIC_SOURCE_ORDER:
        return False
    if not str(row.get('song') or '').strip() or row.get('lyric'):
        return False
    if path == 'auto':
        # The fast/precise pipeline may emit an intermediate no-op while a better result is still
        # pending. Only the terminal empty result may open the fourth-provider lane.
        if bool(row.get('precision_upgrade_pending')) or bool(row.get('progressive_keep_fast')):
            return False
    elif path == 'manual':
        if str(row.get('event') or '') != 'search-result' or not bool(row.get('final')) or bool(row.get('keep_fast')):
            return False
    return True


def _h94_selected_player_duration_for_fallback(panel, row):
    song = str((row or {}).get('song') or '')
    artist = str((row or {}).get('artist') or '')
    # H81 is the authority boundary. If it is present, ask it for player-owned duration evidence
    # rather than trusting a lyric provider's candidate duration. This value is search evidence,
    # not permission for Spotify/Musixmatch to bind transport.
    if '_h81_selected_player_duration' in globals():
        try:
            value = int(_h81_selected_player_duration(panel, song, artist) or 0)
            if value > 0:
                return value
        except Exception:
            pass
    try:
        return max(0, int((row or {}).get('provider_duration_ms') or 0))
    except Exception:
        return 0


def _h94_prepare_result_payload(row, lrc, lyric_duration, meta, *, expected_duration_ms=0, path='auto'):
    # Pure payload work only.  H94 workers must never read QWidget state: the selected-player
    # duration witness is frozen on the GUI thread before the network worker starts.
    out = dict(row or {})
    out['h94_spotify_fallback_attempted'] = True
    out['h94_spotify_fallback_path'] = str(path or '')
    raw = str(lrc or '').strip()
    if raw:
        try:
            clean = LyricSearchEngine._clean_lrc(raw, out.get('song',''), out.get('artist',''))
        except Exception:
            clean = raw
    else:
        clean = ''
    if clean and not _h94_lrc_has_timed_rows(clean):
        clean = ''

    try:
        expected = max(0, int(expected_duration_ms or 0))
    except Exception:
        expected = 0
    provider_meta = dict(meta or {})
    if int(lyric_duration or 0) > 0:
        provider_meta['lyric_candidate_duration_ms'] = int(lyric_duration or 0)
    provider_meta['h94_transport_authority'] = False
    provider_meta['h94_original_selected_source'] = str(out.get('source') or '')

    if clean:
        try:
            provider_meta = _build_lyric_payload_meta(
                provider_meta,
                str(provider_meta.get('lyric_payload_source') or 'Spotify'),
                clean,
                int(expected or lyric_duration or 0),
                provider_meta,
            )
            provider_meta.update(dict(meta or {}))
            provider_meta['h94_transport_authority'] = False
            provider_meta['h94_original_selected_source'] = str(out.get('source') or '')
            if int(lyric_duration or 0) > 0:
                provider_meta['lyric_candidate_duration_ms'] = int(lyric_duration or 0)
        except Exception:
            pass
        out['lyric'] = clean
        out['provider_meta'] = provider_meta
        # When a live player owns this request, only selected-player evidence may become row
        # duration. For offline manual lookup no transport is bound, so the lyric candidate may
        # size the presentation timeline safely.
        offline_manual = bool(path == 'manual' and not bool(out.get('player_presence_ok')))
        out['duration'] = int((lyric_duration if offline_manual else expected) or 0)
        out['error'] = ''
        if path == 'manual':
            out['stage'] = 'spotify-fallback'
            out['final'] = True
            out['keep_fast'] = False
        elif path == 'auto':
            out['progressive_stage'] = 'spotify-fallback'
            out['precision_upgrade_pending'] = False
            out['progressive_keep_fast'] = False
            out['precision_upgrade'] = False
        try:
            write_error_log('H94 Spotify歌词最终兜底命中', detail=(
                f'path={path} | song={out.get("song","")} | artist={out.get("artist","")} | '
                f'selected_source={out.get("source","")} | '
                f'provider={str(provider_meta.get("spotify_lyrics_provider") or provider_meta.get("lyric_payload_source") or "Spotify")} | '
                f'player_duration={int(expected or 0)} | lyric_candidate_duration={int(lyric_duration or 0)} | '
                f'internal={int(bool(provider_meta.get("spotify_lyrics_internal")))} | transport_authority=0'
            ))
        except Exception:
            pass
    else:
        old_error = str(out.get('error') or '').strip()
        out['error'] = old_error or '网易云 / QQ音乐 / 酷狗 / Spotify 均未找到可用同步歌词'
    return out


def _h94_start_fallback_worker(panel, row, *, path, emit):
    request = dict(row or {})
    request['h94_spotify_fallback_pending'] = True
    # Freeze all GUI/player evidence before leaving the Qt thread.  This keeps the network
    # worker portable across PyQt/Windows builds and prevents QWidget access from worker threads.
    expected = _h94_selected_player_duration_for_fallback(panel, request)
    song = str(request.get('song') or '')
    artist = str(request.get('artist') or '')
    generation = int(request.get('generation', -1) or -1)
    key = str(request.get('key') or '')
    token = (id(panel), str(path or ''), generation, key, str(request.get('source') or ''), bool(request.get('trans_only')))
    with _H94_ACTIVE_FALLBACK_LOCK:
        if token in _H94_ACTIVE_FALLBACKS:
            return True
        _H94_ACTIVE_FALLBACKS.add(token)

    def cancelled():
        try:
            if path == 'auto':
                if generation != int(getattr(panel, '_auto_generation', -2)):
                    return True
                current_key = str(getattr(panel, '_auto_target_key', '') or '')
                # An empty owner key means the transaction has already been released.  Treat it
                # as stale instead of allowing a late Spotify fallback to resurrect old lyrics.
                return bool(key and current_key != key)
            if path == 'manual':
                return generation != int(getattr(panel, '_manual_fetch_generation', -2))
            if path == 'mode':
                return generation != int(getattr(panel, '_mode_refetch_generation', -2))
        except Exception:
            return True
        return False

    try:
        status = getattr(panel, 'status', None)
        if status is not None:
            status.setText(f'状态：三大歌词源未命中，正在尝试 Spotify「{song}」…')
    except Exception:
        pass

    def worker():
        try:
            LyricSearchEngine._set_cancel_check(cancelled)
            if cancelled():
                return
            lrc = ''; duration = 0; meta = {}
            try:
                lrc, duration, meta = _h94_fetch_spotify_lyric_fallback(song, artist, expected)
            except Exception as exc:
                try:
                    write_error_log('H94 Spotify歌词兜底线程失败', detail=f'path={path} | {type(exc).__name__} | soft_fail=1')
                except Exception:
                    pass
            if cancelled():
                return
            payload = _h94_prepare_result_payload(
                request, lrc, duration, meta, expected_duration_ms=expected, path=path
            )
            try:
                emit(payload)
            except Exception as exc:
                try:
                    write_error_log('H94 Spotify歌词兜底结果投递失败', detail=f'path={path} | {type(exc).__name__} | soft_fail=1')
                except Exception:
                    pass
        finally:
            LyricSearchEngine._set_cancel_check(None)
            with _H94_ACTIVE_FALLBACK_LOCK:
                _H94_ACTIVE_FALLBACKS.discard(token)

    try:
        threading.Thread(
            target=worker,
            name=f'LimbusLyric-H94SpotifyLyrics-{path}',
            daemon=True,
        ).start()
    except Exception:
        with _H94_ACTIVE_FALLBACK_LOCK:
            _H94_ACTIVE_FALLBACKS.discard(token)
        raise
    return True


# Result-layer integration deliberately sits *after* H81. We do not replace
# LyricSearchEngine.search: H81's identity firewall remains intact and receives every successful
# Spotify fallback payload before it can bind any player/timeline state.
_LIMBUS_H94_AUTO_RESULT_PRE = ControlPanel._on_auto_lyric_result
_LIMBUS_H94_MANUAL_RESULT_PRE = ControlPanel._on_manual_lyric_result
_LIMBUS_H94_MODE_RESULT_PRE = ControlPanel._on_mode_lyric_result


def _h94_auto_result(panel, result):
    row = dict(result or {})
    key = str(row.get('key') or '')
    if not _h94_result_needs_spotify_fallback(row, path='auto'):
        out = _LIMBUS_H94_AUTO_RESULT_PRE(panel, row)
        # The re-emitted terminal fallback result is now owned by the historical result chain.
        # Clear the marker only after that handler runs; the separately connected QQ cleanup
        # slot will then see either a loaded lyric or an already-closed failure transaction.
        if bool(row.get('h94_spotify_fallback_attempted')) and key == str(getattr(panel, '_h94_auto_fallback_pending_key', '') or ''):
            panel._h94_auto_fallback_pending_key = ''
        return out
    panel._h94_auto_fallback_pending_key = key
    try:
        return _h94_start_fallback_worker(
            panel, row, path='auto', emit=lambda payload: panel.auto_lyric_result.emit(dict(payload))
        )
    except Exception:
        if key == str(getattr(panel, '_h94_auto_fallback_pending_key', '') or ''):
            panel._h94_auto_fallback_pending_key = ''
        raise


def _h94_manual_result(panel, result):
    row = dict(result or {})
    if not _h94_result_needs_spotify_fallback(row, path='manual'):
        return _LIMBUS_H94_MANUAL_RESULT_PRE(panel, row)
    return _h94_start_fallback_worker(
        panel, row, path='manual', emit=lambda payload: panel._manual_fetch_emit(dict(payload))
    )


def _h94_mode_result(panel, result):
    row = dict(result or {})
    if not _h94_result_needs_spotify_fallback(row, path='mode'):
        return _LIMBUS_H94_MODE_RESULT_PRE(panel, row)
    return _h94_start_fallback_worker(
        panel, row, path='mode', emit=lambda payload: panel.mode_lyric_result.emit(dict(payload))
    )


ControlPanel._on_auto_lyric_result = _h94_auto_result
ControlPanel._on_manual_lyric_result = _h94_manual_result
ControlPanel._on_mode_lyric_result = _h94_mode_result
ControlPanel._on_auto_lyric_result._limbus_layer = 'H94'
ControlPanel._on_manual_lyric_result._limbus_layer = 'H94'
ControlPanel._on_mode_lyric_result._limbus_layer = 'H94'
ControlPanel._on_auto_lyric_result._limbus_policy = 'three-provider-final-empty -> spotify-lyrics-only; H81 transport authority preserved'


# H95 unified lyric foundation + Sync Doctor V1 --------------------------------------
# H95 is deliberately display-only and sidecar-only:
# - Unified Lyric Track mirrors the already accepted lyric payload; it does NOT replace
#   parse_lrc(), renderer ownership, provider search, MediaSessionSync or seek authority.
# - Sync Doctor transforms only LyricWindow's final display clock. Source timestamps and
#   player position are never rewritten. Per-song corrections are stored separately.
H95_SYNC_DOCTOR_ENABLED = True
H95_SYNC_MAX_ABS_CORRECTION_MS = 5000
H95_SYNC_MAX_ANCHORS = 8
H95_SYNC_LINEAR_MIN_SPAN_MS = 15000
H95_SYNC_LINEAR_MIN_SCALE = 0.98
H95_SYNC_LINEAR_MAX_SCALE = 1.02
H95_UNIFIED_MODEL_VERSION = 1


def _h95_clamp_int(value, low, high, default=0):
    try:
        return max(int(low), min(int(high), int(round(float(value)))))
    except Exception:
        return int(default)


def _h95_normalize_correction_row(row, song='', artist=''):
    src = row if isinstance(row, dict) else {}
    out = {
        'song': str(src.get('song') or song or '').strip(),
        'artist': str(src.get('artist') or artist or '').strip(),
        'manual_adjust_ms': _h95_clamp_int(src.get('manual_adjust_ms', 0), -H95_SYNC_MAX_ABS_CORRECTION_MS, H95_SYNC_MAX_ABS_CORRECTION_MS),
        'anchors': [],
    }
    raw_anchors = src.get('anchors') if isinstance(src.get('anchors'), list) else []
    cleaned = []
    for item in raw_anchors[-H95_SYNC_MAX_ANCHORS:]:
        if not isinstance(item, dict):
            continue
        try:
            playback = max(0, int(round(float(item.get('playback_ms')))))
            source = max(0, int(round(float(item.get('source_ms')))))
        except Exception:
            continue
        cleaned.append({'playback_ms': playback, 'source_ms': source})
    # Keep deterministic source-time order; replace near-duplicates so repeated anchoring of
    # the same visible line does not overweight one moment in the least-squares fit.
    merged = []
    for item in sorted(cleaned, key=lambda x: (x['source_ms'], x['playback_ms'])):
        if merged and abs(int(item['source_ms']) - int(merged[-1]['source_ms'])) <= 500:
            merged[-1] = item
        else:
            merged.append(item)
    out['anchors'] = merged[-H95_SYNC_MAX_ANCHORS:]
    return out


def _h95_normalize_correction_store(store):
    if not isinstance(store, dict):
        return {}
    out = {}
    for identity, row in list(store.items())[-1200:]:
        key = str(identity or '').strip()
        if not key or not isinstance(row, dict):
            continue
        normalized = _h95_normalize_correction_row(row)
        if normalized.get('song') and normalized.get('artist'):
            out[key] = normalized
    return out


def _h95_model_from_row(row):
    row = _h95_normalize_correction_row(row)
    anchors = list(row.get('anchors') or [])
    manual = float(row.get('manual_adjust_ms') or 0)
    offsets = [float(a['source_ms']) - float(a['playback_ms']) for a in anchors]
    # With zero/one anchor, or anchors too close together, the safest correction is a
    # translation only. This avoids inventing drift from one mistimed button press.
    if len(anchors) < 2:
        base_offset = offsets[-1] if offsets else 0.0
        intercept = max(-H95_SYNC_MAX_ABS_CORRECTION_MS, min(H95_SYNC_MAX_ABS_CORRECTION_MS, base_offset + manual))
        return {'mode': 'offset', 'scale': 1.0, 'intercept_ms': float(intercept), 'anchor_count': len(anchors), 'span_ms': 0}
    xs = [float(a['playback_ms']) for a in anchors]
    ys = [float(a['source_ms']) for a in anchors]
    span = max(xs) - min(xs)
    if span < float(H95_SYNC_LINEAR_MIN_SPAN_MS):
        ordered = sorted(offsets)
        mid = len(ordered) // 2
        base_offset = ordered[mid] if len(ordered) % 2 else (ordered[mid - 1] + ordered[mid]) / 2.0
        intercept = max(-H95_SYNC_MAX_ABS_CORRECTION_MS, min(H95_SYNC_MAX_ABS_CORRECTION_MS, base_offset + manual))
        return {'mode': 'offset', 'scale': 1.0, 'intercept_ms': float(intercept), 'anchor_count': len(anchors), 'span_ms': int(span)}
    mx = sum(xs) / len(xs); my = sum(ys) / len(ys)
    denom = sum((x - mx) ** 2 for x in xs)
    scale = (sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / denom) if denom > 1.0 else 1.0
    if not (H95_SYNC_LINEAR_MIN_SCALE <= scale <= H95_SYNC_LINEAR_MAX_SCALE):
        ordered = sorted(offsets)
        mid = len(ordered) // 2
        base_offset = ordered[mid] if len(ordered) % 2 else (ordered[mid - 1] + ordered[mid]) / 2.0
        intercept = max(-H95_SYNC_MAX_ABS_CORRECTION_MS, min(H95_SYNC_MAX_ABS_CORRECTION_MS, base_offset + manual))
        return {'mode': 'offset', 'scale': 1.0, 'intercept_ms': float(intercept), 'anchor_count': len(anchors), 'span_ms': int(span)}
    intercept = (my - scale * mx) + manual
    return {'mode': 'linear', 'scale': float(scale), 'intercept_ms': float(intercept), 'anchor_count': len(anchors), 'span_ms': int(span)}


def _h95_correct_display_position(position_ms, row):
    try:
        base = max(0.0, float(position_ms))
    except Exception:
        return 0, 0, {'mode': 'offset', 'scale': 1.0, 'intercept_ms': 0.0, 'anchor_count': 0, 'span_ms': 0}
    model = _h95_model_from_row(row)
    transformed = base * float(model.get('scale') or 1.0) + float(model.get('intercept_ms') or 0.0)
    delta = transformed - base
    delta = max(-float(H95_SYNC_MAX_ABS_CORRECTION_MS), min(float(H95_SYNC_MAX_ABS_CORRECTION_MS), delta))
    final = max(0, int(round(base + delta)))
    return final, int(round(delta)), model


def _h95_unified_track_from_timeline(timeline, song='', artist='', source='', identity=''):
    # S1/S2: data normalization is owned by a dependency-free module when available.
    # Resolve it lazily so historical replay gates (which execute this function in isolation)
    # retain the exact legacy fallback instead of failing on a missing module global.
    core_builder = globals().get('_core_build_unified_track_from_timeline')
    if callable(core_builder):
        try:
            return core_builder(
                timeline, song=song, artist=artist, source=source, identity=identity,
                model_version=globals().get('H95_UNIFIED_MODEL_VERSION', 1),
            )
        except Exception as exc:
            try: globals().get('write_error_log', lambda *a, **k: None)('S1统一歌词核心回退', exc, detail='owner=limbus_core.lyric_model -> legacy-H95')
            except Exception: pass
    lines = []
    seq = list(timeline or [])
    for index, item in enumerate(seq):
        try:
            start_ms = max(0, int(item[0])); text = str(item[1] or '')
        except Exception:
            continue
        precise = item[2] if len(item) >= 3 else None
        words = []
        if isinstance(precise, (list, tuple)):
            for ev in precise:
                try:
                    ev_start, visible_end = int(ev[0]), int(ev[1])
                    ev_end = int(ev[2]) if len(ev) >= 3 else ev_start
                    visible_start = int(ev[3]) if len(ev) >= 4 else 0
                except Exception:
                    continue
                visible_start = max(0, min(len(text), visible_start))
                visible_end = max(visible_start, min(len(text), visible_end))
                token = text[visible_start:visible_end]
                if token:
                    words.append({
                        'text': token,
                        'start_ms': max(0, ev_start),
                        'end_ms': max(max(0, ev_start), ev_end),
                        'char_start': visible_start,
                        'char_end': visible_end,
                    })
        next_start = None
        if index + 1 < len(seq):
            try: next_start = max(start_ms, int(seq[index + 1][0]))
            except Exception: next_start = None
        precise_end = max([int(w['end_ms']) for w in words], default=start_ms)
        end_ms = max(start_ms, precise_end, next_start if next_start is not None else start_ms + 4000)
        lines.append({
            'index': len(lines), 'start_ms': start_ms, 'end_ms': end_ms,
            'text': text, 'translation': '', 'romanization': '', 'role': 'MAIN',
            'words': words,
        })
    return {
        'model_version': H95_UNIFIED_MODEL_VERSION,
        'identity': str(identity or ''), 'song': str(song or ''), 'artist': str(artist or ''),
        'source': str(source or ''), 'lines': lines,
        'precise_line_count': sum(1 for line in lines if line.get('words')),
        'word_event_count': sum(len(line.get('words') or []) for line in lines),
    }


def _h95_build_unified_lyric_track(text, song='', artist='', source='', identity=''):
    # Important: H95 consumes the existing parser contract instead of replacing it.
    timeline = parse_lrc(text, diagnostics=False)
    return _h95_unified_track_from_timeline(timeline, song=song, artist=artist, source=source, identity=identity)


def _h95_panel_identity(panel):
    try:
        song = str(getattr(panel, '_loaded_song', '') or '').strip()
        artist = str(getattr(panel, '_loaded_artist', '') or '').strip()
        if not song or not artist:
            return '', song, artist
        return str(panel._track_identity(song, artist)), song, artist
    except Exception:
        return '', '', ''


def _h95_activate_song_correction(panel):
    identity, song, artist = _h95_panel_identity(panel)
    store = getattr(panel, '_h95_sync_doctor_store', {})
    row = store.get(identity) if identity and isinstance(store, dict) else None
    normalized = _h95_normalize_correction_row(row, song=song, artist=artist) if isinstance(row, dict) else None
    try:
        panel.lyric_window._h95_song_correction = normalized
        panel.lyric_window._h95_song_correction_identity = identity if normalized else ''
    except Exception:
        pass
    return normalized


def _h95_refresh_shadow_model(panel, text=None):
    try:
        identity, song, artist = _h95_panel_identity(panel)
        payload = str(text if text is not None else panel.text_input.toPlainText() or '').strip()
        if not payload:
            panel._h95_unified_track = None
            return None
        source = str(getattr(panel, '_loaded_source', '') or panel.source_combo.currentText() or '')
        track = _h95_build_unified_lyric_track(payload, song=song, artist=artist, source=source, identity=identity)
        panel._h95_unified_track = track
        try: panel.lyric_window._h95_unified_track = track
        except Exception: pass
        try:
            write_error_log('H95统一歌词影子模型', detail=(
                f'identity={identity or "<unbound>"} | source={source} | lines={len(track.get("lines") or [])} | '
                f'precise_lines={int(track.get("precise_line_count") or 0)} | words={int(track.get("word_event_count") or 0)} | authority=0'))
        except Exception:
            pass
        return track
    except Exception as exc:
        try: write_error_log('H95统一歌词影子模型构建失败', exc)
        except Exception: pass
        return None


_H95_LYRIC_PLAYBACK_POSITION_PRE = LyricWindow._playback_position if 'LyricWindow' in globals() else None
_H95_PRECISION_UPGRADE_PRE = getattr(LyricWindow, 'upgrade_lyric_timeline_preserve_visual', None) if 'LyricWindow' in globals() else None


def _h95_lyric_playback_position(window):
    result = _H95_LYRIC_PLAYBACK_POSITION_PRE(window)
    try:
        if not (isinstance(result, tuple) and result and result[0] is not None):
            return result
        row = getattr(window, '_h95_song_correction', None)
        if not isinstance(row, dict):
            return result
        base = int(result[0])
        final, delta, model = _h95_correct_display_position(base, row)
        window._h95_last_base_position_ms = base
        window._h95_last_final_position_ms = final
        window._h95_last_correction_ms = delta
        window._h95_last_model = model
        window._h95_last_position_mono = time.monotonic() * 1000.0
        return (final,) + tuple(result[1:])
    except Exception:
        return result


def _h95_precision_upgrade_shadow(window, text):
    result = _H95_PRECISION_UPGRADE_PRE(window, text)
    if result:
        try:
            prior = getattr(window, '_h95_unified_track', None)
            prior = prior if isinstance(prior, dict) else {}
            track = _h95_build_unified_lyric_track(
                text,
                song=str(prior.get('song') or ''), artist=str(prior.get('artist') or ''),
                source=str(prior.get('source') or ''), identity=str(prior.get('identity') or ''),
            )
            window._h95_unified_track = track
        except Exception as exc:
            try: write_error_log('H95精准升级影子模型刷新失败', exc)
            except Exception: pass
    return result


def _h95_schedule_save(panel):
    try: panel._schedule_config_save()
    except Exception: pass


def _h95_store_current_row(panel, row):
    identity, song, artist = _h95_panel_identity(panel)
    if not identity:
        return False
    store = getattr(panel, '_h95_sync_doctor_store', None)
    if not isinstance(store, dict):
        store = {}; panel._h95_sync_doctor_store = store
    normalized = _h95_normalize_correction_row(row, song=song, artist=artist)
    normalized['song'] = song; normalized['artist'] = artist
    store[identity] = normalized
    _h95_activate_song_correction(panel)
    _h95_schedule_save(panel)
    try:
        if getattr(panel, '_is_started', False): panel.lyric_window.check_lyric_time()
    except Exception: pass
    return True


def _h95_adjust_current_song(panel, delta_ms):
    identity, song, artist = _h95_panel_identity(panel)
    if not identity:
        try: panel.status.setText('状态：同步医生需要先识别到当前歌曲和歌手')
        except Exception: pass
        return False
    row = dict((getattr(panel, '_h95_sync_doctor_store', {}) or {}).get(identity) or {})
    row = _h95_normalize_correction_row(row, song=song, artist=artist)
    row['manual_adjust_ms'] = _h95_clamp_int(
        int(row.get('manual_adjust_ms') or 0) + int(delta_ms),
        -H95_SYNC_MAX_ABS_CORRECTION_MS, H95_SYNC_MAX_ABS_CORRECTION_MS,
    )
    ok = _h95_store_current_row(panel, row)
    if ok:
        try: panel.status.setText(f'状态：本曲显示修正 {int(delta_ms):+d} ms（非破坏式）')
        except Exception: pass
        _h95_refresh_sync_doctor_ui(panel)
    return ok


def _h95_current_anchor_target(panel):
    window = getattr(panel, 'lyric_window', None)
    if window is None or not getattr(window, 'lyric_timeline', None):
        return None
    try:
        base_result = _H95_LYRIC_PLAYBACK_POSITION_PRE(window)
        if not (isinstance(base_result, tuple) and base_result and base_result[0] is not None):
            return None
        base_ms = int(base_result[0])
    except Exception:
        return None
    timeline = list(window.lyric_timeline or [])
    try: index = int(getattr(window, 'displayed_line_index', -1))
    except Exception: index = -1
    if not (0 <= index < len(timeline)):
        try:
            corrected = window._playback_position()[0]
            starts = [int(item[0]) for item in timeline]
            index = max(0, min(len(timeline) - 1, bisect.bisect_right(starts, int(corrected)) - 1))
        except Exception:
            return None
    try:
        source_ms = int(timeline[index][0]); text = str(timeline[index][1] or '')
    except Exception:
        return None
    return {'index': index, 'source_ms': source_ms, 'playback_ms': base_ms, 'text': text}


def _h95_anchor_current_line(panel):
    identity, song, artist = _h95_panel_identity(panel)
    if not identity:
        try: panel.status.setText('状态：同步医生需要完整的歌曲 + 歌手身份，避免同名歌曲误绑定')
        except Exception: pass
        return False
    target = _h95_current_anchor_target(panel)
    if not target:
        try: panel.status.setText('状态：当前没有可锚定的歌词行或可信显示时钟')
        except Exception: pass
        return False
    row = _h95_normalize_correction_row((getattr(panel, '_h95_sync_doctor_store', {}) or {}).get(identity), song=song, artist=artist)
    anchors = list(row.get('anchors') or [])
    fresh = {'playback_ms': int(target['playback_ms']), 'source_ms': int(target['source_ms'])}
    replaced = False
    for i, anchor in enumerate(anchors):
        if abs(int(anchor.get('source_ms') or 0) - fresh['source_ms']) <= 500:
            anchors[i] = fresh; replaced = True; break
    if not replaced:
        anchors.append(fresh)
    row['anchors'] = anchors[-H95_SYNC_MAX_ANCHORS:]
    # The selected visible line already reflects any current H95 manual nudge. The new
    # anchor therefore captures that whole correction; keeping manual_adjust_ms would
    # double-apply it immediately after anchoring. Consolidate the nudge into evidence.
    row['manual_adjust_ms'] = 0
    if not _h95_store_current_row(panel, row):
        return False
    model = _h95_model_from_row(row)
    try:
        panel.status.setText(
            f'状态：已锚定第 {int(target["index"]) + 1} 行 · {int(target["source_ms"])}ms '
            f'← 当前 {int(target["playback_ms"])}ms · 模型={model.get("mode")}')
    except Exception:
        pass
    _h95_refresh_sync_doctor_ui(panel)
    return True


def _h95_remove_last_anchor(panel):
    identity, song, artist = _h95_panel_identity(panel)
    if not identity:
        return False
    row = _h95_normalize_correction_row((getattr(panel, '_h95_sync_doctor_store', {}) or {}).get(identity), song=song, artist=artist)
    anchors = list(row.get('anchors') or [])
    if not anchors:
        return False
    anchors.pop(); row['anchors'] = anchors
    ok = _h95_store_current_row(panel, row)
    if ok:
        try: panel.status.setText('状态：已撤销本曲最后一个同步锚点')
        except Exception: pass
        _h95_refresh_sync_doctor_ui(panel)
    return ok


def _h95_reset_current_song(panel):
    identity, _song, _artist = _h95_panel_identity(panel)
    if not identity:
        return False
    store = getattr(panel, '_h95_sync_doctor_store', {})
    if isinstance(store, dict): store.pop(identity, None)
    _h95_activate_song_correction(panel)
    _h95_schedule_save(panel)
    try:
        if getattr(panel, '_is_started', False): panel.lyric_window.check_lyric_time()
        panel.status.setText('状态：已清除本曲同步医生修正；原歌词时间轴未被修改')
    except Exception: pass
    _h95_refresh_sync_doctor_ui(panel)
    return True


def _h95_format_clock(ms):
    try:
        value = max(0, int(ms)); minutes, rest = divmod(value, 60000); seconds, milli = divmod(rest, 1000)
        return f'{minutes:02d}:{seconds:02d}.{milli:03d}'
    except Exception:
        return '--:--.---'


def _h95_refresh_sync_doctor_ui(panel):
    label = getattr(panel, 'h95_sync_doctor_status', None)
    if label is None:
        return
    identity, song, artist = _h95_panel_identity(panel)
    if not identity:
        label.setText('当前歌曲尚未形成“歌名 + 歌手”安全身份；同步医生不会保存修正。')
        return
    row = (getattr(panel, '_h95_sync_doctor_store', {}) or {}).get(identity)
    model = _h95_model_from_row(row)
    anchors = int(model.get('anchor_count') or 0)
    mode = str(model.get('mode') or 'offset')
    if not isinstance(row, dict):
        model_text = '未修正'
    elif mode == 'linear':
        drift = (float(model.get('scale') or 1.0) - 1.0) * 1000000.0
        model_text = f'线性漂移 · {drift:+.0f} ppm · 锚点 {anchors}'
    else:
        model_text = f'固定偏移 · {float(model.get("intercept_ms") or 0):+.0f} ms · 锚点 {anchors}'
    window = getattr(panel, 'lyric_window', None)
    base = getattr(window, '_h95_last_base_position_ms', None) if window is not None else None
    final = getattr(window, '_h95_last_final_position_ms', None) if window is not None else None
    delta = getattr(window, '_h95_last_correction_ms', None) if window is not None else None
    clock_text = ''
    if base is not None and final is not None and isinstance(row, dict):
        clock_text = f'\n显示时钟：{_h95_format_clock(base)} → {_h95_format_clock(final)}（本曲 {int(delta or 0):+d} ms）'
    label.setText(f'{song} · {artist}\n{model_text}{clock_text}')


def _h95_install_sync_doctor_ui(panel):
    card = getattr(panel, 'h75_sync_output_card', None)
    if card is None or card.layout() is None:
        return
    layout = card.layout()
    divider = QFrame(card); divider.setFrameShape(QFrame.HLine); divider.setFrameShadow(QFrame.Sunken)
    layout.addWidget(divider)
    title = QLabel('歌词同步医生', card); title.setObjectName('sectionTitle'); layout.addWidget(title)
    hint = QLabel('只修正当前歌曲的最终显示时钟，不修改播放器位置，也不改 QRC / LRC / 后续 TTML。先用 ±50/100 ms 对齐；需要校正逐渐漂移时，在歌曲前后各点一次“这句现在才该出现”。', card)
    hint.setObjectName('trackDetail'); hint.setWordWrap(True); layout.addWidget(hint)
    status = QLabel('', card); status.setObjectName('trackDetail'); status.setWordWrap(True); status.setTextInteractionFlags(Qt.TextSelectableByMouse)
    panel.h95_sync_doctor_status = status; layout.addWidget(status)
    row = QHBoxLayout(); row.setSpacing(6)
    for text, delta in (('−100', -100), ('−50', -50), ('+50', 50), ('+100', 100)):
        button = QPushButton(text + ' ms', card); button.setObjectName('compactButton'); button.clicked.connect(lambda _checked=False, d=delta: _h95_adjust_current_song(panel, d)); row.addWidget(button)
    anchor = QPushButton('这句现在才该出现', card); anchor.setObjectName('compactButton'); anchor.setToolTip('把当前显示歌词行的原始时间与当前最终播放器显示时钟建立一个非破坏式锚点。两个相隔足够远的锚点可自动识别线性漂移。'); anchor.clicked.connect(lambda: _h95_anchor_current_line(panel)); row.addWidget(anchor)
    undo = QPushButton('撤销锚点', card); undo.setObjectName('compactButton'); undo.clicked.connect(lambda: _h95_remove_last_anchor(panel)); row.addWidget(undo)
    reset = QPushButton('清除本曲修正', card); reset.setObjectName('compactButton'); reset.clicked.connect(lambda: _h95_reset_current_song(panel)); row.addWidget(reset)
    row.addStretch(); layout.addLayout(row)
    panel.h95_sync_doctor_anchor_btn = anchor
    panel.h95_sync_doctor_reset_btn = reset
    timer = QTimer(panel); timer.setInterval(500); timer.timeout.connect(lambda: _h95_refresh_sync_doctor_ui(panel)); timer.start(); panel._h95_sync_doctor_timer = timer
    _h95_refresh_sync_doctor_ui(panel)


_H95_CONTROL_INIT_PRE = ControlPanel.__init__ if 'ControlPanel' in globals() else None
_H95_RECORD_LOADED_PRE = getattr(ControlPanel, '_record_loaded_track', None) if 'ControlPanel' in globals() else None
_H95_LAUNCH_PRE = getattr(ControlPanel, '_launch_current_lyrics', None) if 'ControlPanel' in globals() else None


def _h95_control_init(panel, *args, **kwargs):
    try:
        cfg = load_all_config(); settings = cfg.get('settings') if isinstance(cfg, dict) else {}
        initial_store = _h95_normalize_correction_store((settings or {}).get('sync_doctor_corrections', {}))
    except Exception:
        initial_store = {}
    panel._h95_sync_doctor_store = initial_store
    panel._h95_unified_track = None
    _H95_CONTROL_INIT_PRE(panel, *args, **kwargs)
    try:
        _h95_activate_song_correction(panel)
        _h95_install_sync_doctor_ui(panel)
    except Exception as exc:
        try: write_error_log('H95同步医生界面安装失败', exc)
        except Exception: pass


def _h95_record_loaded_track(panel, song, artist='', source=None):
    result = _H95_RECORD_LOADED_PRE(panel, song, artist, source)
    _h95_activate_song_correction(panel)
    try: _h95_refresh_shadow_model(panel)
    except Exception: pass
    try: _h95_refresh_sync_doctor_ui(panel)
    except Exception: pass
    return result


def _h95_launch_current_lyrics(panel, start_delay=0):
    _h95_activate_song_correction(panel)
    result = _H95_LAUNCH_PRE(panel, start_delay=start_delay)
    if result:
        try: _h95_refresh_shadow_model(panel)
        except Exception: pass
        try: _h95_refresh_sync_doctor_ui(panel)
        except Exception: pass
    return result


def _h95_activate():
    try:
        if 'LyricWindow' in globals() and callable(_H95_LYRIC_PLAYBACK_POSITION_PRE):
            LyricWindow._playback_position = _h95_lyric_playback_position
            LyricWindow._playback_position._limbus_layer = 'H95'
            LyricWindow._playback_position._limbus_policy = 'final-display-clock-only; no transport/source timestamp authority'
            if callable(_H95_PRECISION_UPGRADE_PRE):
                LyricWindow.upgrade_lyric_timeline_preserve_visual = _h95_precision_upgrade_shadow
                LyricWindow.upgrade_lyric_timeline_preserve_visual._limbus_layer = 'H95'
                LyricWindow.upgrade_lyric_timeline_preserve_visual._limbus_policy = 'legacy-seamless-upgrade-owner + unified-sidecar-refresh-only'
        if 'ControlPanel' in globals() and callable(_H95_CONTROL_INIT_PRE):
            ControlPanel.__init__ = _h95_control_init
            ControlPanel.__init__._limbus_layer = 'H95'
            if callable(_H95_RECORD_LOADED_PRE):
                ControlPanel._record_loaded_track = _h95_record_loaded_track
                ControlPanel._record_loaded_track._limbus_layer = 'H95'
            if callable(_H95_LAUNCH_PRE):
                ControlPanel._launch_current_lyrics = _h95_launch_current_lyrics
                ControlPanel._launch_current_lyrics._limbus_layer = 'H95'
                ControlPanel._launch_current_lyrics._limbus_policy = 'legacy-renderer-owner + H95 sidecar model refresh'
    except Exception as exc:
        try: write_error_log('H95统一歌词与同步医生激活失败', exc)
        except Exception: pass


if '_h95_activate' in globals():
    _h95_activate()



# H95F1 adaptive header + grip micro interaction + background frost -------------------------
# Presentation-only closure on top of H95. The existing media clocks, seek ownership, lyric
# search/provider identity, Sync Doctor timing model and unified lyric sidecar remain untouched.
# H95F1 makes the media Hero respond progressively to the explicit H93 grip, removes duplicated
# vertical whitespace, gives the compact grip hover/press feedback without instructional copy,
# and adds a persistent user-controlled frost amount for custom control-panel backgrounds.
H95F1_HERO_DEFAULT_H = 176
H95F1_GRIP_ROW_H = 16
H95F1_GRIP_HOVER_W = 56
H95F1_GRIP_HOVER_H = 4
H95F1_GRIP_ACTIVE_W = 60
H95F1_GRIP_ACTIVE_H = 4
H95F1_WORKSPACE_TOP_MARGIN = 7
H95F1_WORKSPACE_BOTTOM_MARGIN = 6
H95F1_FROST_MAX_SOURCE_EDGE = 1920


def _h95f1_header_profile(height, width=900, scale_pct=100):
    """Pure responsive profile: shrink whitespace/widgets first, hide primary text last."""
    try: h = max(int(H93_HERO_MIN_H), min(int(H91_HERO_MAX_H), int(round(float(height)))))
    except Exception: h = int(H95F1_HERO_DEFAULT_H)
    try: width = max(320, int(width))
    except Exception: width = 900
    # Hero height is a physical splitter dimension, so cap text/padding scale to avoid a 150%
    # UI preference immediately re-introducing clipping inside the same fixed Hero height.
    try: scale = max(0.85, min(1.20, float(scale_pct) / 100.0))
    except Exception: scale = 1.0
    if h >= 164:
        level='roomy'; margins=(20,11,150 if width>=500 else 18,11); spacing=3; title=24; detail=11; brand=10; badge=10; progress=9
    elif h >= 124:
        level='compact'; margins=(18,7,116 if width>=500 else 18,7); spacing=2; title=21; detail=10; brand=9; badge=9; progress=8
    elif h >= 88:
        level='tight'; margins=(16,4,88 if width>=500 else 16,4); spacing=1; title=18; detail=9; brand=8; badge=8; progress=6
    elif h >= 54:
        level='mini'; margins=(14,2,70 if width>=500 else 14,2); spacing=0; title=15; detail=8; brand=8; badge=8; progress=5
    else:
        level='collapsed'; margins=(12,1,12,1); spacing=0; title=13; detail=8; brand=8; badge=8; progress=4
    def px(v): return max(7, int(round(float(v)*scale)))
    return {
        'level': level, 'height': h, 'margins': tuple(int(round(x*scale)) for x in margins),
        'spacing': max(0,int(round(spacing*scale))), 'title_px': px(title), 'detail_px': px(detail),
        'brand_px': px(brand), 'badge_px': px(badge), 'progress_h': max(3,int(round(progress*scale))),
        'show_manager': h >= 112, 'show_detail': h >= 96, 'show_live': h >= 122,
        'show_brand': h >= 66, 'show_badge': h >= 70, 'show_title': h >= 44,
        'show_record': width >= 500 and h >= 76,
    }


def _h95f1_frost_downsample_size(width, height, blur):
    """Pure sizing policy for the cached image-space frost pass."""
    try: w=max(1,int(width)); h=max(1,int(height)); amount=max(0,min(100,int(blur)))
    except Exception: return (1,1)
    if amount <= 0: return (w,h)
    factor = 1.0 + (float(amount) / 8.0)
    return (max(24,int(round(w/factor))), max(24,int(round(h/factor))))


def _h95f1_frost_pixmap(raw, blur):
    """Fast cached defocus: smooth downsample/upscale, presentation-only and dependency-free."""
    try:
        if raw is None or raw.isNull(): return QPixmap()
        amount=max(0,min(100,int(blur or 0)))
        if amount <= 0: return QPixmap(raw)
        base=QPixmap(raw)
        edge=max(int(base.width()),int(base.height()))
        if edge > int(H95F1_FROST_MAX_SOURCE_EDGE):
            ratio=float(H95F1_FROST_MAX_SOURCE_EDGE)/float(edge)
            base=base.scaled(max(1,int(base.width()*ratio)),max(1,int(base.height()*ratio)),Qt.KeepAspectRatio,Qt.SmoothTransformation)
        sw,sh=_h95f1_frost_downsample_size(base.width(),base.height(),amount)
        small=base.scaled(sw,sh,Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
        out=small.scaled(base.size(),Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
        if amount >= 64:
            # A second low-cost pass makes high frost values visibly softer without a frame-loop effect.
            sw2,sh2=_h95f1_frost_downsample_size(out.width(),out.height(),min(100,amount+18))
            out=out.scaled(sw2,sh2,Qt.IgnoreAspectRatio,Qt.SmoothTransformation).scaled(out.size(),Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
        return out
    except Exception:
        try: return QPixmap(raw)
        except Exception: return QPixmap()


_H95F1_PANEL_BG_SET_PRE = getattr(PanelBackground, 'set_background', None) if 'PanelBackground' in globals() else None

def _h95f1_panel_set_background(self, path='', enabled=False, strength=42, blur=0):
    path=str(path or ''); amount=max(0,min(100,int(blur or 0)))
    path_changed = path != str(getattr(self,'_background_path','') or '')
    blur_changed = amount != int(getattr(self,'_background_blur',0) or 0)
    if callable(_H95F1_PANEL_BG_SET_PRE):
        _H95F1_PANEL_BG_SET_PRE(self,path,enabled,strength)
    self._background_blur=amount
    try:
        if path_changed or not hasattr(self,'_h95f1_background_raw'):
            self._h95f1_background_raw = QPixmap(path) if path and os.path.isfile(path) else QPixmap()
        raw=getattr(self,'_h95f1_background_raw',QPixmap())
        if path_changed or blur_changed or not hasattr(self,'_h95f1_background_frost_key'):
            self._background_pixmap=_h95f1_frost_pixmap(raw,amount)
            self._h95f1_background_frost_key=(path,amount)
        elif raw is not None and not raw.isNull() and getattr(self,'_background_pixmap',QPixmap()).isNull():
            self._background_pixmap=_h95f1_frost_pixmap(raw,amount)
        self.update()
    except Exception:
        pass


def _h95f1_set_label_metric(widget, *, font_px=None, padding_top=None, padding=''):
    if widget is None: return
    chunks=[]
    if font_px is not None: chunks.append(f'font-size:{int(font_px)}px')
    if padding: chunks.append(str(padding))
    elif padding_top is not None: chunks.append(f'padding-top:{int(padding_top)}px')
    try: widget.setStyleSheet(';'.join(chunks) + (';' if chunks else ''))
    except Exception: pass


_H95F1_HERO_APPLY_PRE = globals().get('_h91_apply_hero_height')

def _h95f1_apply_hero_height(panel, height=None, persist=False):
    out=_H95F1_HERO_APPLY_PRE(panel,height,persist) if callable(_H95F1_HERO_APPLY_PRE) else False
    try:
        h=int(getattr(panel,'_h91_hero_height',H95F1_HERO_DEFAULT_H) if height is None else _h91_clamp_hero_height(height))
        profile=_h95f1_header_profile(h,int(panel.width()),int(getattr(panel,'_h12_ui_scale_pct',100) or 100))
        hero=panel.findChild(QFrame,'heroCard')
        if hero is None or hero.layout() is None: return out
        hero.layout().setContentsMargins(*profile['margins']); hero.layout().setSpacing(profile['spacing'])
        app=getattr(panel,'app_title',None); manager=getattr(panel,'manager_tag',None); detail=getattr(panel,'front_detail_label',None)
        live=getattr(panel,'h79_live_lyric',None); badge=getattr(panel,'front_sync_badge',None); title=getattr(panel,'front_track_label',None)
        if app is not None: app.setVisible(bool(profile['show_brand']))
        if manager is not None: manager.setVisible(bool(profile['show_manager']))
        if detail is not None: detail.setVisible(bool(profile['show_detail']))
        if live is not None: live.setVisible(bool(profile['show_live']) and bool(str(live.text() or '').strip()))
        if badge is not None: badge.setVisible(bool(profile['show_badge']))
        if title is not None: title.setVisible(bool(profile['show_title']))
        _h95f1_set_label_metric(app,font_px=profile['brand_px'])
        _h95f1_set_label_metric(manager,font_px=max(7,profile['brand_px']-1))
        _h95f1_set_label_metric(title,font_px=profile['title_px'],padding_top=0 if h<164 else 2)
        _h95f1_set_label_metric(detail,font_px=profile['detail_px'],padding_top=0)
        _h95f1_set_label_metric(badge,font_px=profile['badge_px'],padding='padding:2px 7px' if h<124 else 'padding:3px 8px')
        if live is not None: _h95f1_set_label_metric(live,font_px=profile['detail_px'])
        progress=getattr(panel,'h87_hero_progress',None)
        if progress is not None:
            progress.setVisible(h >= 38); progress.setFixedHeight(int(profile['progress_h'])); progress.update()
        icon=getattr(panel,'brand_icon',None)
        if icon is not None:
            side=max(20,min(30,int(round((20 if h<124 else 26 if h<164 else 30)*(float(getattr(panel,'_h12_ui_scale_pct',100) or 100)/100.0)))))
            icon.setVisible(h>=76); icon.setFixedSize(side,side)
        ambient=getattr(panel,'h79_hero_ambient',None)
        if ambient is not None:
            ambient.setVisible(bool(profile['show_record'])); ambient.update()
        panel._h95f1_header_profile=profile
    except Exception:
        pass
    return out


def _h95f1_apply_shell_density(panel):
    try:
        scale=max(.75,min(1.75,float(getattr(panel,'_h12_ui_scale_pct',100) or 100)/100.0))
        content=panel.findChild(QWidget,'panelContent')
        if content is not None and content.layout() is not None:
            content.layout().setContentsMargins(int(round(22*scale)),int(round(10*scale)),int(round(22*scale)),int(round(12*scale)))
            content.layout().setSpacing(max(6,int(round(9*scale))))
        header=getattr(panel,'workspace_header',None)
        if header is not None and header.layout() is not None:
            header.layout().setContentsMargins(0,int(round(H95F1_WORKSPACE_TOP_MARGIN*scale)),0,int(round(H95F1_WORKSPACE_BOTTOM_MARGIN*scale)))
            header.layout().setSpacing(max(8,int(round(12*scale))))
        mark=getattr(panel,'h78_workspace_mark',None)
        if mark is not None: mark.setFixedHeight(max(26,int(round(28*scale))))
        row=getattr(panel,'h93_workspace_grip_row',None)
        if row is not None: row.setFixedHeight(max(int(H93_GRIP_HIT_HEIGHT),int(round(H95F1_GRIP_ROW_H*scale))))
    except Exception:
        pass


_H95F1_QOBJECT_BASE=globals().get('QObject',object)
class H95F1GripMicroInteraction(_H95F1_QOBJECT_BASE):
    def __init__(self,panel,grip,mark):
        super().__init__(grip); self.panel=panel; self.grip=grip; self.mark=mark; self.pressed=False
        grip.installEventFilter(self)
        try: grip.setToolTip('')
        except Exception: pass
        self._apply('idle')
    def _apply(self,state):
        classic = bool('_h87_frontend_theme' in globals() and _h87_frontend_theme(self.panel)=='classic')
        if state=='active': size=(H95F1_GRIP_ACTIVE_W,H95F1_GRIP_ACTIVE_H); alpha=238
        elif state=='hover': size=(H95F1_GRIP_HOVER_W,H95F1_GRIP_HOVER_H); alpha=198
        else: size=(H93_GRIP_LINE_WIDTH,H93_GRIP_LINE_HEIGHT); alpha=112
        rgb=(197,139,150) if classic else (214,187,119)
        try:
            self.mark.setFixedSize(int(size[0]),int(size[1]))
            self.mark.setStyleSheet(f'background:rgba({rgb[0]},{rgb[1]},{rgb[2]},{alpha});border:none;border-radius:{2 if int(size[1])>=4 else 1}px;')
        except Exception: pass
    def refresh_palette(self): self._apply('active' if self.pressed else ('hover' if self.grip.underMouse() else 'idle'))
    def eventFilter(self,obj,event):
        if obj is not self.grip: return False
        try:
            kind=event.type()
            if kind==QEvent.Enter and not self.pressed: self._apply('hover')
            elif kind==QEvent.Leave and not self.pressed: self._apply('idle')
            elif kind==QEvent.MouseButtonPress and event.button()==Qt.LeftButton: self.pressed=True; self._apply('active')
            elif kind==QEvent.MouseButtonRelease and event.button()==Qt.LeftButton: self.pressed=False; self._apply('hover' if self.grip.underMouse() else 'idle')
            elif kind in (getattr(QEvent,'WindowDeactivate',-10001),getattr(QEvent,'ApplicationDeactivate',-10002)):
                self.pressed=False; self._apply('idle')
        except Exception:
            self.pressed=False
        return False


