# H95F2 frost material + cover identity + Hero collision closure ---------------------------
# Presentation/identity hardening on top of H95F1.  Player clocks, seek ownership and lyric
# timing are unchanged.  H95F2 turns the custom-background control into a restrained frosted
# material (soft diffusion + preserved structure + micro-grain), makes shared artwork matching
# honor the player's full artist credit rather than whichever search alias happened to return a
# row, and keeps the decorative LISTENING ROOM legend from colliding with the live sync badge.
H95F2_ART_CACHE_SCHEMA = 'h95f2-art-identity-v1'
H95F2_GRAIN_TILE = 56
H95F2_LISTENING_GAP = 12


def _h95f2_artist_tokens(value):
    raw=html.unescape(str(value or '')).strip()
    if not raw: return []
    out=[]
    # Keep order: the first explicit credit is the primary identity witness.  Bracketed aliases
    # in the *song title* are deliberately not injected here; they may improve query recall but
    # may not authorize a different release/credit.
    for part in re.split(r'[/／、,&＆，;；|+＋×]', raw):
        key=_clean_name(re.sub(r'^(?:cv|vocal|vocals|歌手|演唱)\s*[:：]?\s*','',part.strip(),flags=re.I))
        if len(key)>=2 and key not in out: out.append(key)
    whole=_clean_name(raw)
    if whole and whole not in out: out.append(whole)
    return out


def _h95f2_strict_credit_match(wanted, actual):
    """Release-art identity guard: one shared collaborator cannot authorize a multi-credit row."""
    q=_h95f2_artist_tokens(wanted); c=_h95f2_artist_tokens(actual)
    if not q: return True
    if not c: return False
    q_atomic=[x for x in q if x != _clean_name(wanted)] or q[:1]
    c_atomic=[x for x in c if x != _clean_name(actual)] or c[:1]
    overlaps=[]
    for qa in q_atomic:
        for ca in c_atomic:
            if qa==ca or (min(len(qa),len(ca))>=3 and (qa in ca or ca in qa)):
                overlaps.append((qa,ca)); break
    if not overlaps: return False
    # A single-credit query remains compatible with the historical conservative alias match.
    if len(q_atomic)<=1: return True
    primary=q_atomic[0]
    primary_ok=any(primary==ca or (min(len(primary),len(ca))>=3 and (primary in ca or ca in primary)) for ca in c_atomic)
    # For multiple explicit query credits either retain the primary credit or independently
    # corroborate two credits. This rejects ぽわぽわP/鏡音リン -> 椎名もた/鏡音リン merely because
    # 鏡音リン overlaps, while still accepting ぽわぽわP alone or both matching credits.
    return bool(primary_ok or len(overlaps)>=2)


def _h95f2_title_score(canonical_song, candidate_title):
    tn=_h91_norm(candidate_title) if '_h91_norm' in globals() else _clean_name(candidate_title)
    if not tn: return -10**6
    best=-10**6
    variants=_h91_song_variants(canonical_song) if '_h91_song_variants' in globals() else [canonical_song]
    for variant in variants:
        target=_h91_norm(variant) if '_h91_norm' in globals() else _clean_name(variant)
        if not target: continue
        if target==tn: best=max(best,170)
        elif target in tn or tn in target: best=max(best,92)
    return best


def _h95f2_cover_duration_ok(candidate_ms, expected_ms):
    try: c=int(candidate_ms or 0); e=int(expected_ms or 0)
    except Exception: return True
    if e<=0 or c<=0: return True
    return abs(c-e) <= max(4200,int(max(c,e)*0.032))


def _h95f2_choose_qq_cover_row(rows, canonical_song, canonical_artist='', expected_duration_ms=0):
    best=None; best_score=-10**9
    for row in [x for x in list(rows or []) if isinstance(x,dict)]:
        title=str(row.get('songname') or row.get('name') or '')
        score=_h95f2_title_score(canonical_song,title)
        if score<0: continue
        actual=_artist_text({'singer':row.get('singer',[])}) if '_artist_text' in globals() else ''
        if canonical_artist and not _h95f2_strict_credit_match(canonical_artist,actual): continue
        candidate_ms=int(row.get('interval') or 0)*1000
        if not _h95f2_cover_duration_ok(candidate_ms,expected_duration_ms): continue
        if canonical_artist and actual: score+=82
        score+=_h91_duration_score(candidate_ms,expected_duration_ms) if '_h91_duration_score' in globals() else 0
        if str(row.get('albummid') or row.get('albumMID') or '').strip(): score+=8
        if score>best_score: best_score=score; best=row
    return best if best_score>=120 else None


def _h95f2_choose_netease_cover_row(rows, canonical_song, canonical_artist='', expected_duration_ms=0, preferred_id=''):
    pid=str(preferred_id or '').strip(); best=None; best_score=-10**9
    for row in [x for x in list(rows or []) if isinstance(x,dict)]:
        score=_h95f2_title_score(canonical_song,str(row.get('name') or ''))
        if score<0: continue
        arts=row.get('artists') if isinstance(row.get('artists'),list) else row.get('ar')
        actual=', '.join(str(x.get('name') or '') for x in list(arts or []) if isinstance(x,dict))
        if canonical_artist and not _h95f2_strict_credit_match(canonical_artist,actual): continue
        duration=int(row.get('duration') or row.get('dt') or 0)
        if not _h95f2_cover_duration_ok(duration,expected_duration_ms): continue
        rid=str(row.get('id') or '').strip()
        if pid and rid==pid: score+=120
        if canonical_artist and actual: score+=82
        score+=_h91_duration_score(duration,expected_duration_ms) if '_h91_duration_score' in globals() else 0
        if '_h16_cover_pic_url' in globals() and _h16_cover_pic_url(row): score+=8
        if score>best_score: best_score=score; best=row
    return best if best_score>=120 else None


def _h95f2_fetch_qq_art(http, song, artist, expected_duration_ms, headers, out_path):
    qq_headers=dict(headers); qq_headers['Referer']='https://y.qq.com/'
    seen=set(); best=None; provenance=''
    song_queries=_h91_song_variants(song) if '_h91_song_variants' in globals() else [song]
    artist_queries=_h91_artist_variants(song,artist) if '_h91_artist_variants' in globals() else [artist,'']
    for sname in song_queries:
        for aname in artist_queries:
            query=f'{sname} {aname}'.strip()
            if not query or query in seen: continue
            seen.add(query)
            try:
                resp=_r2_qq_search_request(http,'https://c.y.qq.com/soso/fcgi-bin/client_search_cp',params={'p':1,'n':24,'w':query,'format':'json'},headers=qq_headers,timeout=4)
                resp.raise_for_status(); rows=(((resp.json().get('data') or {}).get('song') or {}).get('list') or [])
                hit=_h95f2_choose_qq_cover_row(rows,song,artist,expected_duration_ms)
                if hit is not None:
                    best=hit; provenance=f'qq:{str(hit.get("songmid") or "")}:{sname}'; break
            except Exception: pass
        if best is not None: break
    if not isinstance(best,dict): return '',''
    album_mid=str(best.get('albummid') or best.get('albumMID') or '').strip(); song_mid=str(best.get('songmid') or '').strip()
    if not album_mid and song_mid:
        try:
            detail=http.get('https://c.y.qq.com/v8/fcg-bin/fcg_play_single_song.fcg',params={'songmid':song_mid,'format':'json'},headers=qq_headers,timeout=4)
            detail.raise_for_status(); data=detail.json().get('data') or []
            if data and isinstance(data[0],dict):
                album=data[0].get('album') if isinstance(data[0].get('album'),dict) else {}; album_mid=str(data[0].get('albummid') or album.get('mid') or '').strip()
        except Exception: pass
    if not album_mid: return '',''
    try:
        img=http.get(f'https://y.gtimg.cn/music/photo_new/T002R500x500M000{album_mid}.jpg',headers=qq_headers,timeout=4); img.raise_for_status()
        path=_h88_save_art_bytes(img.content,out_path) if '_h88_save_art_bytes' in globals() else ''
        if path:
            try:
                actual=_artist_text({'singer':best.get('singer',[])}) if '_artist_text' in globals() else ''
                write_error_log('H95F2封面身份严格命中',detail=f'provider=QQ | song={song} | wanted_artist={artist} | matched_artist={actual} | duration={int(best.get("interval") or 0)*1000} | source={provenance}')
            except Exception: pass
            return path,provenance
    except Exception: pass
    return '',''


def _h95f2_fetch_netease_art(http, song, artist, expected_duration_ms, headers, preferred_id, out_path):
    seen=set(); song_queries=_h91_song_variants(song) if '_h91_song_variants' in globals() else [song]; artist_queries=_h91_artist_variants(song,artist) if '_h91_artist_variants' in globals() else [artist,'']
    for sname in song_queries:
        for aname in artist_queries:
            query=f'{sname} {aname}'.strip()
            if not query or query in seen: continue
            seen.add(query)
            try:
                resp=http.post('https://music.163.com/api/search/get/web',data={'s':query,'type':1,'limit':18},headers=headers,timeout=4)
                resp.raise_for_status(); rows=((resp.json().get('result') or {}).get('songs') or [])
                hit=_h95f2_choose_netease_cover_row(rows,song,artist,expected_duration_ms,preferred_id)
                if not hit: continue
                url=_h16_cover_pic_url(hit) if '_h16_cover_pic_url' in globals() else ''
                if not url: continue
                img=http.get(url,headers=headers,timeout=4); img.raise_for_status(); path=_h88_save_art_bytes(img.content,out_path) if '_h88_save_art_bytes' in globals() else ''
                if path:
                    try:
                        arts=hit.get('artists') if isinstance(hit.get('artists'),list) else hit.get('ar'); actual=', '.join(str(x.get('name') or '') for x in list(arts or []) if isinstance(x,dict))
                        write_error_log('H95F2封面身份严格命中',detail=f'provider=网易云 | song={song} | wanted_artist={artist} | matched_artist={actual} | duration={int(hit.get("duration") or hit.get("dt") or 0)} | source=netease:{hit.get("id") or ""}')
                    except Exception: pass
                    return path,f'netease:{hit.get("id") or ""}:{sname}'
            except Exception: pass
    return '',''


def _h95f2_art_file_for_key(key):
    root=_h87_art_dir() if '_h87_art_dir' in globals() else ''
    if not root or not key: return ''
    digest=hashlib.sha1((H95F2_ART_CACHE_SCHEMA+'|'+str(key)).encode('utf-8','ignore')).hexdigest()
    return os.path.join(root,digest+'.jpg')


def _h95f2_cached_art_path(key):
    path=_h95f2_art_file_for_key(key)
    if not path or not os.path.isfile(path): return ''
    try:
        if time.time()-float(os.path.getmtime(path))>float(H87_ART_TTL_SEC): os.remove(path); return ''
    except Exception: return ''
    return path


def _h95f2_frost_pixmap(raw, amount):
    """Frost material base: restrained diffusion plus a little source structure, not pure blur."""
    try:
        if raw is None or raw.isNull(): return QPixmap()
        amount=max(0,min(100,int(amount or 0)))
        if amount<=0: return QPixmap(raw)
        base=QPixmap(raw); edge=max(int(base.width()),int(base.height()))
        if edge>int(H95F1_FROST_MAX_SOURCE_EDGE):
            ratio=float(H95F1_FROST_MAX_SOURCE_EDGE)/float(edge); base=base.scaled(max(1,int(base.width()*ratio)),max(1,int(base.height()*ratio)),Qt.KeepAspectRatio,Qt.SmoothTransformation)
        factor=1.0+float(amount)/22.0
        sw=max(40,int(round(base.width()/factor))); sh=max(40,int(round(base.height()/factor)))
        soft=base.scaled(sw,sh,Qt.IgnoreAspectRatio,Qt.SmoothTransformation).scaled(base.size(),Qt.IgnoreAspectRatio,Qt.SmoothTransformation)
        out=QPixmap(base.size()); out.fill(Qt.transparent)
        p=QPainter(out); p.setRenderHint(QPainter.SmoothPixmapTransform,True); p.drawPixmap(0,0,soft)
        # Keep a controlled amount of original structure. Strong frost remains diffused but avoids
        # the "Gaussian blur slider" look where every edge dissolves into a uniform smear.
        p.setOpacity(max(0.12,0.34-0.0018*amount)); p.drawPixmap(0,0,base); p.setOpacity(1.0)
        haze_alpha=int(round(4+amount*0.10)); p.fillRect(out.rect(),QColor(220,220,218,haze_alpha)); p.end()
        return out
    except Exception:
        try: return QPixmap(raw)
        except Exception: return QPixmap()


_H95F2_BG_PAINT_PRE=getattr(PanelBackground,'paintEvent',None) if 'PanelBackground' in globals() else None
_H95F2_GRAIN_CACHE={}
def _h95f2_grain_tile(amount,limbus=False):
    bucket=max(1,min(10,int(round(max(0,min(100,int(amount or 0)))/10.0))))
    key=(bucket,bool(limbus)); cached=_H95F2_GRAIN_CACHE.get(key)
    if cached is not None and not cached.isNull(): return cached
    try:
        side=int(H95F2_GRAIN_TILE); image=QImage(side,side,QImage.Format_ARGB32); image.fill(QColor(0,0,0,0))
        seed=0x95F2 + bucket*977 + (211 if limbus else 0); strength=1+bucket//2
        for y in range(side):
            for x in range(side):
                seed=(1664525*seed+1013904223)&0xffffffff; n=(seed>>24)&0xff
                if n<78:
                    tone=236 if (n&1) else 92; alpha=max(1,min(8,strength+(n%3)-1))
                    image.setPixelColor(x,y,QColor(tone,tone,tone,alpha))
        pix=QPixmap.fromImage(image); _H95F2_GRAIN_CACHE[key]=pix; return pix
    except Exception: return QPixmap()


def _h95f2_panel_paint(self,event):
    if callable(_H95F2_BG_PAINT_PRE): _H95F2_BG_PAINT_PRE(self,event)
    try:
        amount=max(0,min(100,int(getattr(self,'_background_blur',0) or 0)))
        if amount<=0 or not bool(getattr(self,'_background_enabled',False)): return
        limbus=str(getattr(self,'_theme_mode',''))=='limbus_manager'; p=QPainter(self); p.setRenderHint(QPainter.Antialiasing,False)
        # A faint milky material wash + deterministic micro-grain is what makes this read as
        # frosted material rather than merely an out-of-focus photograph.
        alpha=int(round(2+amount*0.10)); tint=QColor(219,225,216,alpha) if limbus else QColor(235,220,224,alpha)
        p.fillRect(self.rect(),tint)
        tile=_h95f2_grain_tile(amount,limbus)
        if tile is not None and not tile.isNull():
            p.setOpacity(0.34+0.0028*amount); p.drawTiledPixmap(self.rect(),tile); p.setOpacity(1.0)
        p.end()
    except Exception: pass


def _h95f2_compact_badge_text(text,hero_height):
    raw=str(text or '').strip()
    try: h=int(hero_height or H95F1_HERO_DEFAULT_H)
    except Exception: h=H95F1_HERO_DEFAULT_H
    paused='暂停' in raw
    if h<88: return '暂停' if paused else ('同步' if '同步' in raw else raw)
    if h<124:
        if paused: return '同步 · 暂停' if '同步' in raw else '暂停'
        return '同步' if '同步' in raw else raw
    return raw


_H95F2_FRONT_STATUS_PRE=getattr(ControlPanel,'_refresh_frontend_status',None) if 'ControlPanel' in globals() else None
def _h95f2_refresh_frontend_status(panel,*args,**kwargs):
    out=_H95F2_FRONT_STATUS_PRE(panel,*args,**kwargs) if callable(_H95F2_FRONT_STATUS_PRE) else None
    try:
        badge=getattr(panel,'front_sync_badge',None)
        if badge is not None:
            h=int(getattr(panel,'_h91_hero_height',H95F1_HERO_DEFAULT_H) or H95F1_HERO_DEFAULT_H)
            text=_h95f2_compact_badge_text(badge.text(),h); badge.setText(text); badge.adjustSize()
            badge.setMaximumWidth(max(54,110 if h>=124 else 82 if h>=88 else 64))
        ambient=getattr(panel,'h79_hero_ambient',None)
        if ambient is not None: ambient.update()
    except Exception: pass
    return out


_H95F2_AMBIENT_PAINT_PRE=getattr(globals().get('H79HeroAmbient'),'paintEvent',None) if 'H79HeroAmbient' in globals() else None
def _h95f2_ambient_paint(self,event):
    # Reuse H91's complete record rendering but temporarily suppress its fixed-position legend;
    # then redraw the legend only when real widget geometry leaves a safe lane.
    panel=getattr(self,'_panel',None)
    if panel is None or 'QPainter' not in globals():
        if callable(_H95F2_AMBIENT_PAINT_PRE): return _H95F2_AMBIENT_PAINT_PRE(self,event)
        return
    # H91 draws the legend only when height>=132. Temporarily report a short rect through a tiny
    # flag consumed by the copied draw path would be invasive, so redraw the full H91 scene here
    # by calling it with the actual height and cover the legend lane only if it would collide.
    if callable(_H95F2_AMBIENT_PAINT_PRE): _H95F2_AMBIENT_PAINT_PRE(self,event)
    try:
        if self.height()<132: return
        hero=getattr(self,'_hero',None); badge=getattr(panel,'front_sync_badge',None)
        if hero is None or badge is None: return
        target=QRect(max(0,self.width()-154),10,138,18)
        top=badge.mapTo(hero,QPoint(0,0)); badge_rect=QRect(top,badge.size()).adjusted(-int(H95F2_LISTENING_GAP),-4,int(H95F2_LISTENING_GAP),4)
        if not target.intersects(badge_rect): return
        # The old legend has already been painted by H91. Restore the local background by asking
        # the ambient to repaint on the next event with the legend disabled marker handled below.
        # We cannot erase a gradient/record scene losslessly here, so collision state is stored and
        # H95F2's final paint path below uses a legend-free copy on subsequent frames.
        self._h95f2_hide_listening=True
    except Exception: pass


# A compact clone of H91's ambient paint with one intentional delta: collision-aware decorative
# legend. Keeping it in the final presentation layer avoids changing legacy H91 behavior/hashes.
def _h95f2_ambient_paint_final(self,_event):
    panel=getattr(self,'_panel',None)
    if panel is None or 'QPainter' not in globals():
        if callable(_H95F2_AMBIENT_PAINT_PRE): return _H95F2_AMBIENT_PAINT_PRE(self,_event)
        return
    _h87_prepare_ambient(self)
    p=QPainter(self); p.setRenderHint(QPainter.Antialiasing,True); p.setRenderHint(QPainter.SmoothPixmapTransform,True)
    rect=QRectF(self.rect()); classic=_h87_frontend_theme(panel)=='classic' if '_h87_frontend_theme' in globals() else False
    clip=QPainterPath(); clip.addRoundedRect(rect,18,18); p.setClipPath(clip)
    grad=QLinearGradient(rect.topLeft(),rect.bottomRight())
    if classic: grad.setColorAt(0,QColor('#211b1e')); grad.setColorAt(.58,QColor('#17171b')); grad.setColorAt(1,QColor('#302227'))
    else: grad.setColorAt(0,QColor('#20322e')); grad.setColorAt(.58,QColor('#17241f')); grad.setColorAt(1,QColor('#332f24'))
    p.fillRect(rect,grad); accent=_h79_ambient_color(panel) if '_h79_ambient_color' in globals() else QColor('#c9ac77')
    r=max(32.0,min(66.0,(rect.height()-18.0)*0.46)); center=QPointF(rect.right()-max(r+18.0,58.0),rect.center().y()+2.0)
    glow=QRadialGradient(center,r*2.25); glow.setColorAt(0,QColor(accent.red(),accent.green(),accent.blue(),48)); glow.setColorAt(1,QColor(accent.red(),accent.green(),accent.blue(),0)); p.fillRect(rect,glow)
    p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,78)); p.drawEllipse(QPointF(center.x()+2,center.y()+3),r+2,r+2)
    p.setBrush(QColor('#0f1514' if not classic else '#121114')); p.setPen(QPen(QColor(202,190,151,42),1)); p.drawEllipse(center,r,r)
    current=getattr(self,'_h87_cover',QPixmap()); previous=getattr(self,'_h87_prev_cover',QPixmap()); angle=float(getattr(self,'_h87_angle',0.0) or 0.0); fade=1.0; started=float(getattr(self,'_h87_cover_started',0.0) or 0.0)
    if started>0:
        t=max(0.0,min(1.0,((time.monotonic()-started)*1000.0)/float(H87_COVER_FADE_MS))); fade=1.0-math.pow(1.0-t,3.0)
        if t>=1.0: self._h87_cover_started=0.0; self._h87_prev_cover=QPixmap()
    cr=r*.88; drew=False
    if previous is not None and not previous.isNull() and fade<1.0: drew=_h87_draw_record_cover(p,previous,center,cr,angle,1.0-fade) or drew
    if current is not None and not current.isNull(): drew=_h87_draw_record_cover(p,current,center,cr,angle,fade) or drew
    if not drew: p.setPen(Qt.NoPen); p.setBrush(QColor('#18211e' if not classic else '#1a171a')); p.drawEllipse(center,cr,cr)
    p.setBrush(Qt.NoBrush)
    for frac in (.48,.58,.68,.78,.88): p.setPen(QPen(QColor(228,218,188,20),1)); p.drawEllipse(center,r*frac,r*frac)
    p.setPen(Qt.NoPen); p.setBrush(QColor('#d0b278' if not classic else '#c88b96')); p.drawEllipse(center,max(6.0,r*.17),max(6.0,r*.17)); p.setBrush(QColor('#1c2924')); p.drawEllipse(center,max(2.5,r*.055),max(2.5,r*.055))
    if rect.height()>=132 and rect.width()>=360:
        legend=QRect(int(rect.right()-154),10,138,18); safe=True
        try:
            badge=getattr(panel,'front_sync_badge',None); hero=getattr(self,'_hero',None)
            if badge is not None and hero is not None and badge.isVisible():
                top=badge.mapTo(hero,QPoint(0,0)); brect=QRect(top,badge.size()).adjusted(-int(H95F2_LISTENING_GAP),-4,int(H95F2_LISTENING_GAP),4); safe=not legend.intersects(brect)
        except Exception: safe=False
        if safe:
            p.setPen(QColor('#c9b68d' if not classic else '#c79da5')); p.setFont(QFont('Segoe UI',8)); p.drawText(QRectF(legend),Qt.AlignCenter,'L I S T E N I N G  R O O M')
    p.end()


_H95F2_CONTROL_INIT_PRE=ControlPanel.__init__ if 'ControlPanel' in globals() else None
def _h95f2_control_init(panel,*args,**kwargs):
    _H95F2_CONTROL_INIT_PRE(panel,*args,**kwargs)
    try:
        # Matching rules changed, so old artwork/color evidence is not silently trusted under the
        # new schema. Cached JPEG paths are version-salted; clear old in-memory colours once.
        data=load_all_config(); settings=data.setdefault('settings',{})
        if not bool(settings.get('h95f2_cover_identity_migrated',False)):
            panel._h16_cover_cache={}; panel._h85_cover_persistent={}
            try: _h85_write_cover_cache(panel)
            except Exception: pass
            settings['h95f2_cover_identity_migrated']=True; _write_config_dict_atomic(data)
        # H95F10F4 changes the identity again from track-only to release-aware. Preserve the
        # H95F2 migration contract above and run a separate one-time purge for artwork/colors
        # that may have been accepted under the old title/artist/duration-only selector.
        if not bool(settings.get('h95f10f4_cover_release_migrated',False)):
            panel._h16_cover_cache={}; panel._h85_cover_persistent={}
            try: _h85_write_cover_cache(panel)
            except Exception: pass
            settings['h95f10f4_cover_release_migrated']=True; _write_config_dict_atomic(data)
        if hasattr(panel,'background_blur_name'): panel.background_blur_name.setText('背景磨砂：')
        if hasattr(panel,'background_blur_slider'): panel.background_blur_slider.setToolTip('柔化背景细节并加入轻微雾化与微颗粒材质；0% 保留原图。')
        QTimer.singleShot(0,lambda p=panel:_h95f2_refresh_frontend_status(p))
    except Exception as exc:
        try: write_error_log('H95F2材质/封面/头部闭环安装失败',exc)
        except Exception: pass


def _h95f2_activate():
    try:
        globals()['_h95f1_frost_pixmap']=_h95f2_frost_pixmap
        globals()['_h87_art_file_for_key']=_h95f2_art_file_for_key
        globals()['_h87_cached_art_path']=_h95f2_cached_art_path
        globals()['_h91_fetch_qq_art']=_h95f2_fetch_qq_art
        globals()['_h91_fetch_netease_art']=_h95f2_fetch_netease_art
        if 'PanelBackground' in globals() and callable(_H95F2_BG_PAINT_PRE): PanelBackground.paintEvent=_h95f2_panel_paint; PanelBackground.paintEvent._limbus_layer='H95F2'
        if 'H79HeroAmbient' in globals(): H79HeroAmbient.paintEvent=_h95f2_ambient_paint_final; H79HeroAmbient.paintEvent._limbus_layer='H95F2'
        if 'ControlPanel' in globals() and callable(_H95F2_CONTROL_INIT_PRE):
            ControlPanel._refresh_frontend_status=_h95f2_refresh_frontend_status; ControlPanel._refresh_frontend_status._limbus_layer='H95F2'
            ControlPanel.__init__=_h95f2_control_init; ControlPanel.__init__._limbus_layer='H95F2'; ControlPanel.__init__._limbus_policy='frosted material + full-credit artwork identity + collision-aware hero legend; presentation/cover-only'
    except Exception as exc:
        try: write_error_log('H95F2闭环激活失败',exc)
        except Exception: pass


if '_h95f2_activate' in globals(): _h95f2_activate()

# H95F3 preview fit + classic compact frontend ---------------------------------------
# H95F3 is presentation-only. It closes the compact preview clipping reported on
# Appearance/Motion and offers a new implementation inspired by the early frontend.
# The legacy source is NOT reinstated: current widgets, search, Sync Doctor, Spotify,
# artwork guards and all current runtime owners remain authoritative.
H95F3_PREVIEW_STAGE_H = 108
H95F3_PREVIEW_OPEN_CARD_H = 154
H95F3_PREVIEW_OPEN_HOST_H = 176
H95F3_LAYOUT_DEFAULT = 'studio'
H95F3_LEGACY_HERO_DEFAULT = 126
H95F3_STUDIO_TOP_NAV_H = 43
H95F3_LEGACY_TOP_NAV_H = 36

H95F3_LAYOUT_QSS = r'''
QWidget[h95f3Layout="legacy"] QFrame#topNav {
    border-radius:6px; background:rgba(14,14,17,224); border:1px solid rgba(238,229,226,22);
}
QWidget[h95f3Layout="legacy"] QFrame#h78NavIndicator {
    border-radius:4px; border:1px solid rgba(209,164,171,48); background:rgba(209,164,171,15);
}
QWidget[h95f3Layout="legacy"] QPushButton#navButton {
    padding:5px 11px; border-radius:3px; font-size:11px;
}
QWidget[h95f3Layout="legacy"] QFrame#workspaceHeader { min-height:32px; max-height:38px; }
QWidget[h95f3Layout="legacy"] QLineEdit#settingsFilter { min-height:25px; max-height:27px; border-radius:6px; }
QWidget[h95f3Layout="legacy"] QFrame#settingsCard { border-radius:7px; }
QWidget[h95f3Layout="legacy"] QFrame#settingsCard QLabel#cardTitle { font-size:13px; padding-top:0px; padding-bottom:1px; }
QWidget[h95f3Layout="legacy"] QFrame#h80StudioStageHost { border-radius:7px; margin-bottom:6px; }
QWidget[h95f3Layout="legacy"] QLabel#heroTrackTitle { letter-spacing:0px; }
QWidget[h95f3Layout="legacy"] QLabel#heroTrackDetail { font-size:10px; }
QWidget[h95f3Layout="legacy"] QFrame#heroCard { border-radius:9px; }
'''


def _h95f3_preview_geometry(opened=True):
    if not opened:
        return {'stage': 0, 'card': int(globals().get('H89_PREVIEW_CLOSED_CARD_H', 38)), 'host': int(globals().get('H89_PREVIEW_CLOSED_HOST_H', 48))}
    return {'stage': H95F3_PREVIEW_STAGE_H, 'card': H95F3_PREVIEW_OPEN_CARD_H, 'host': H95F3_PREVIEW_OPEN_HOST_H}


def _h95f3_layout_profile(mode):
    legacy = str(mode or '').lower() == 'legacy'
    return {
        'mode': 'legacy' if legacy else 'studio',
        'top_nav_h': H95F3_LEGACY_TOP_NAV_H if legacy else H95F3_STUDIO_TOP_NAV_H,
        'workspace_copy': not legacy,
        'workspace_margins': (0, 3, 0, 4) if legacy else None,
        'card_margins': (10, 9, 10, 10) if legacy else None,
        'card_spacing': 7 if legacy else None,
    }


def _h95f3_layout_value(panel):
    value = str(getattr(panel, '_h95f3_frontend_layout', H95F3_LAYOUT_DEFAULT) or H95F3_LAYOUT_DEFAULT).lower()
    return 'legacy' if value == 'legacy' else 'studio'


def _h95f3_repolish(widget):
    try:
        widget.style().unpolish(widget); widget.style().polish(widget); widget.update()
    except Exception:
        pass


def _h95f3_cache_card_metrics(panel):
    cache = getattr(panel, '_h95f3_card_metrics', None)
    if not isinstance(cache, dict): cache = {}; panel._h95f3_card_metrics = cache
    try:
        for card in panel.findChildren(QFrame, 'settingsCard'):
            lay = card.layout()
            if lay is None or id(card) in cache: continue
            m = lay.contentsMargins()
            cache[id(card)] = (card, (m.left(),m.top(),m.right(),m.bottom()), int(lay.spacing()))
    except Exception:
        pass
    return cache


def _h95f3_apply_card_density(panel, legacy):
    cache = _h95f3_cache_card_metrics(panel)
    for _key, row in list(cache.items()):
        try:
            card, margins, spacing = row; lay = card.layout()
            if lay is None: continue
            if legacy:
                lay.setContentsMargins(10,9,10,10); lay.setSpacing(7)
            else:
                lay.setContentsMargins(*margins); lay.setSpacing(int(spacing))
        except Exception:
            pass


def _h95f3_apply_layout(panel, mode=None, save=False):
    mode = 'legacy' if str(mode or _h95f3_layout_value(panel)).lower() == 'legacy' else 'studio'
    previous = _h95f3_layout_value(panel)
    panel._h95f3_frontend_layout = mode
    profile = _h95f3_layout_profile(mode); legacy = mode == 'legacy'
    try:
        style=str(panel.styleSheet() or '')
        if H95F3_LAYOUT_QSS not in style: panel.setStyleSheet(style+H95F3_LAYOUT_QSS)
        panel.setProperty('h95f3Layout', mode); _h95f3_repolish(panel)
        # Dynamic ancestor selectors need descendants repolished after the layout property flips.
        for child in panel.findChildren(QWidget):
            try: child.setProperty('h95f3Layout',mode); _h95f3_repolish(child)
            except Exception: pass
        nav = getattr(panel, 'top_nav', None)
        if nav is not None:
            nav.setMinimumHeight(int(profile['top_nav_h'])); nav.setMaximumHeight(int(profile['top_nav_h']))
        header = getattr(panel, 'workspace_header', None)
        if header is not None and header.layout() is not None:
            if legacy:
                header.layout().setContentsMargins(*profile['workspace_margins']); header.layout().setSpacing(8)
                header.setMinimumHeight(32); header.setMaximumHeight(38)
            else:
                header.setMinimumHeight(0); header.setMaximumHeight(16777215)
                if '_h95f1_apply_shell_density' in globals():
                    try: _h95f1_apply_shell_density(panel)
                    except Exception: pass
        for name in ('workspace_title','workspace_description','h77_workspace_kicker','h78_workspace_mark'):
            w = getattr(panel, name, None)
            if w is not None: w.setVisible(bool(profile['workspace_copy']))
        filt = getattr(panel, 'settings_filter', None)
        if filt is not None:
            filt.setMaximumWidth(290 if legacy else 320); filt.setMinimumWidth(190 if legacy else 210)
        _h95f3_apply_card_density(panel, legacy)
        # Keep every modern feature, but let the classic layout start from a denser media header.
        current_h = int(getattr(panel, '_h91_hero_height', H95F1_HERO_DEFAULT_H if 'H95F1_HERO_DEFAULT_H' in globals() else 176) or 176)
        if previous != mode:
            if previous == 'legacy': panel._h95f3_legacy_hero_height = current_h
            else: panel._h95f3_studio_hero_height = current_h
        target = int(getattr(panel, '_h95f3_legacy_hero_height', H95F3_LEGACY_HERO_DEFAULT) if legacy else getattr(panel, '_h95f3_studio_hero_height', current_h))
        if previous != mode and '_h91_apply_hero_height' in globals():
            _h91_apply_hero_height(panel, target, False)
        if getattr(panel, 'h87_frontend_combo', None) is not None:
            # H87 controls palette only. H95F3 is an independent layout choice.
            panel.h87_frontend_combo.setToolTip('配色主题；“前端布局”请在外观页切换。')
        combo = getattr(panel, 'h95f3_layout_combo', None)
        if combo is not None and combo.currentData() != mode:
            combo.blockSignals(True); idx = combo.findData(mode); combo.setCurrentIndex(max(0,idx)); combo.blockSignals(False)
        if '_h89_apply_preview_state' in globals():
            QTimer.singleShot(0, lambda p=panel: _h89_apply_preview_state(p, False))
        if '_h78_move_nav_indicator' in globals():
            QTimer.singleShot(0, lambda p=panel: _h78_move_nav_indicator(p, p.main_tabs.currentIndex(), False))
    except Exception:
        pass
    if save and bool(getattr(panel, '_settings_loaded', False)):
        try:
            data=load_all_config(); settings=data.setdefault('settings',{})
            settings['h95f3_frontend_layout']=mode
            settings['h95f3_studio_hero_height']=int(getattr(panel,'_h95f3_studio_hero_height',getattr(panel,'_h91_hero_height',176)) or 176)
            settings['h95f3_legacy_hero_height']=int(getattr(panel,'_h95f3_legacy_hero_height',H95F3_LEGACY_HERO_DEFAULT) or H95F3_LEGACY_HERO_DEFAULT)
            _write_config_dict_atomic(data)
        except Exception as exc:
            try: write_error_log('H95F3前端布局即时保存失败', exc)
            except Exception: pass
        try: panel._schedule_config_save()
        except Exception: pass
    return mode


def _h95f3_install_layout_card(panel):
    try:
        if getattr(panel,'h95f3_layout_card',None) is not None: return panel.h95f3_layout_card
        page=panel.main_tabs.widget(1).widget(); layout=page.layout()
        card=QFrame(page); card.setObjectName('settingsCard')
        v=QVBoxLayout(card); v.setContentsMargins(14,12,14,13); v.setSpacing(8)
        title=QLabel('前端布局',card); title.setObjectName('cardTitle'); v.addWidget(title)
        row=QHBoxLayout(); row.setSpacing(9)
        name=QLabel('界面结构：',card); name.setObjectName('fieldLabel'); name.setMinimumWidth(94); row.addWidget(name)
        combo=QComboBox(card); combo.addItem('新版','studio'); combo.addItem('旧版','legacy'); combo.setToolTip('经典紧凑保留早期前端更直接的密度与标签感，但继续使用当前全部功能和修复。'); row.addWidget(combo,1); v.addLayout(row)
        hint=QLabel('布局与玫瑰 / 森林配色相互独立。经典紧凑不是旧代码回滚：同步、封面、Spotify、同步医生与新设置全部保留。',card); hint.setObjectName('trackDetail'); hint.setWordWrap(True); v.addWidget(hint)
        layout.insertWidget(0,card)
        panel.h95f3_layout_card=card; panel.h95f3_layout_combo=combo
        idx=combo.findData(_h95f3_layout_value(panel)); combo.setCurrentIndex(max(0,idx))
        combo.currentIndexChanged.connect(lambda _i,p=panel,c=combo:_h95f3_apply_layout(p,c.currentData(),True))
        return card
    except Exception as exc:
        try: write_error_log('H95F3前端布局卡安装失败',exc)
        except Exception: pass
        return None


_H95F3_SAVE_PRE=globals().get('save_all_config')
def _h95f3_save_all_config(panel,presets,players):
    if callable(_H95F3_SAVE_PRE): _H95F3_SAVE_PRE(panel,presets,players)
    try:
        data=load_all_config(); settings=data.setdefault('settings',{})
        settings['h95f3_frontend_layout']=_h95f3_layout_value(panel)
        settings['h95f3_studio_hero_height']=int(getattr(panel,'_h95f3_studio_hero_height',getattr(panel,'_h91_hero_height',176)) or 176)
        settings['h95f3_legacy_hero_height']=int(getattr(panel,'_h95f3_legacy_hero_height',H95F3_LEGACY_HERO_DEFAULT) or H95F3_LEGACY_HERO_DEFAULT)
        _write_config_dict_atomic(data)
    except Exception: pass


_H95F3_DENSITY_PRE=globals().get('_h95f1_apply_shell_density')
def _h95f3_apply_shell_density(panel):
    out=_H95F3_DENSITY_PRE(panel) if callable(_H95F3_DENSITY_PRE) else None
    if _h95f3_layout_value(panel)=='legacy':
        QTimer.singleShot(0,lambda p=panel:_h95f3_apply_layout(p,'legacy',False))
    return out


_H95F3_THEME_PRE=globals().get('_h87_apply_frontend_theme')
def _h95f3_apply_frontend_theme(panel,theme=None,save=False):
    out=_H95F3_THEME_PRE(panel,theme,save) if callable(_H95F3_THEME_PRE) else None
    try:
        style=str(panel.styleSheet() or '')
        if H95F3_LAYOUT_QSS not in style: panel.setStyleSheet(style+H95F3_LAYOUT_QSS)
    except Exception: pass
    _h95f3_apply_layout(panel,_h95f3_layout_value(panel),False)
    return out


def _h95f3_show_interface_popup(panel):
    # H87's historical “frontend style” is a palette selector, not the new layout selector.
    # Rename the visible copy so users do not confuse Rose/Forest colours with old/new layout.
    try:
        if '_h87_show_interface_popup' in globals(): _h87_show_interface_popup(panel)
        dlg=getattr(panel,'_h73_background_popup',None)
        if dlg is not None:
            for label in dlg.findChildren(QLabel):
                text=str(label.text() or '').strip()
                if text=='前端风格': label.setText('配色主题')
                elif text=='控制面板外观': label.setText('配色方案')
                elif text.startswith('只改变控制面板配色与交互呈现') or text.startswith('只改变控制面板配色'):
                    label.setText('只改变控制面板配色；前端布局请在“外观 → 前端布局”切换。')
            combo=getattr(panel,'h87_frontend_combo',None)
            if combo is not None: combo.setToolTip('玫瑰 / 森林配色；不改变前端布局。')
    except Exception as exc:
        try: write_error_log('H95F3界面弹窗文案区分失败',exc)
        except Exception: pass


_H95F3_CONTROL_INIT_PRE=ControlPanel.__init__ if 'ControlPanel' in globals() else None
def _h95f3_control_init(panel,*args,**kwargs):
    _H95F3_CONTROL_INIT_PRE(panel,*args,**kwargs)
    try:
        data=load_all_config(); settings=data.setdefault('settings',{})
        panel._h95f3_frontend_layout='legacy' if str(settings.get('h95f3_frontend_layout',H95F3_LAYOUT_DEFAULT)).lower()=='legacy' else 'studio'
        panel._h95f3_studio_hero_height=int(settings.get('h95f3_studio_hero_height',getattr(panel,'_h91_hero_height',176)) or 176)
        panel._h95f3_legacy_hero_height=int(settings.get('h95f3_legacy_hero_height',H95F3_LEGACY_HERO_DEFAULT) or H95F3_LEGACY_HERO_DEFAULT)
        # Add the selector using current controls; no old frontend code is imported or reactivated.
        panel._default_stylesheet=str(getattr(panel,'_default_stylesheet','') or '')+H95F3_LAYOUT_QSS
        panel._limbus_stylesheet=str(getattr(panel,'_limbus_stylesheet','') or '')+H95F3_LAYOUT_QSS
        try: panel.setStyleSheet(str(panel.styleSheet() or '')+H95F3_LAYOUT_QSS)
        except Exception: pass
        _h95f3_install_layout_card(panel)
        panel._h73_show_background_popup=lambda p=panel:_h95f3_show_interface_popup(p)
        try:
            btn=getattr(getattr(panel,'window_title_bar',None),'background_btn',None)
            if btn is not None: btn.setToolTip('界面 · 配色、缩放、背景与显示')
        except Exception: pass
        if panel._h95f3_frontend_layout=='legacy' and '_h91_apply_hero_height' in globals():
            _h91_apply_hero_height(panel,panel._h95f3_legacy_hero_height,False)
        elif panel._h95f3_frontend_layout=='studio' and '_h91_apply_hero_height' in globals():
            _h91_apply_hero_height(panel,panel._h95f3_studio_hero_height,False)
        _h95f3_apply_layout(panel,panel._h95f3_frontend_layout,False)
        QTimer.singleShot(0,lambda p=panel:_h95f3_apply_layout(p,_h95f3_layout_value(p),False))
        QTimer.singleShot(80,lambda p=panel:_h95f3_apply_layout(p,_h95f3_layout_value(p),False))
    except Exception as exc:
        try: write_error_log('H95F3预览/经典紧凑前端安装失败',exc)
        except Exception: pass


def _h95f3_activate():
    try:
        # H89 reads these globals at runtime. Provide enough vertical budget for header +
        # preview canvas + metric footer so high-DPI/font environments cannot crop the footer.
        globals()['H89_PREVIEW_STAGE_H']=int(H95F3_PREVIEW_STAGE_H)
        globals()['H89_PREVIEW_OPEN_CARD_H']=int(H95F3_PREVIEW_OPEN_CARD_H)
        globals()['H89_PREVIEW_OPEN_HOST_H']=int(H95F3_PREVIEW_OPEN_HOST_H)
        globals()['save_all_config']=_h95f3_save_all_config
        if callable(_H95F3_DENSITY_PRE): globals()['_h95f1_apply_shell_density']=_h95f3_apply_shell_density
        if callable(_H95F3_THEME_PRE): globals()['_h87_apply_frontend_theme']=_h95f3_apply_frontend_theme
        if 'ControlPanel' in globals() and callable(_H95F3_CONTROL_INIT_PRE):
            ControlPanel.__init__=_h95f3_control_init; ControlPanel.__init__._limbus_layer='H95F3'; ControlPanel.__init__._limbus_policy='preview fit + classic compact layout option using current widgets; presentation-only'
    except Exception as exc:
        try: write_error_log('H95F3前端闭环激活失败',exc)
        except Exception: pass


if '_h95f3_activate' in globals(): _h95f3_activate()

# H95F4 true legacy frontend -----------------------------------------------------------
# H95F3 interpreted "legacy" as a compact skin for the modern Studio shell. H95F4
# corrects that product mistake: Legacy is a distinct shell that mirrors the final V29
# structure (simple media header + native QTabWidget tabs + settings pages) while all
# current controls/runtime owners remain the same objects. No legacy player/lyric code is
# reactivated, and Modern Studio remains byte-for-byte owned by the existing H73-H95F3 layers.
H95F4_FRONTEND_DEFAULT = 'studio'
H95F4_LEGACY_TAB_LABELS = ('播放', '字幕', '动效', '高级', '单曲DIY')
H95F4_STUDIO_TAB_LABELS = ('播放', '外观', '动效', '设置', '单曲')

H95F4_QSS = r'''
QFrame#h95f4LegacyHeader {
    background: rgba(13,14,17,120);
    border: none;
    border-bottom: 1px solid rgba(238,229,226,24);
    border-radius: 0px;
}
QLabel#h95f4LegacyIcon {
    background: rgba(255,255,255,4); border: 1px solid rgba(238,229,226,20);
    border-radius: 4px; padding: 1px;
}
QLabel#h95f4LegacyBrand {
    color:#ebe4e1; font-size:20px; font-weight:760; letter-spacing:0.15px;
}
QLabel#h95f4LegacyTrack {
    color:#f1ebe7; font-size:16px; font-weight:650; padding-top:1px;
}
QLabel#h95f4LegacyDetail { color:#7f787b; font-size:11px; }
QLabel#h95f4LegacyBadge {
    background:transparent; color:#d2b2b8; border:1px solid #4b3e42;
    border-radius:3px; padding:3px 9px; min-width:66px; font-size:10px;
}
QWidget[h95f4Frontend="legacy"] QTabWidget#mainTabs::pane {
    border:none; background:rgba(9,10,13,150); top:-1px;
}
QWidget[h95f4Frontend="legacy"] QTabBar::tab {
    background:transparent; color:#777174; padding:8px 13px 9px 13px;
    margin-right:4px; border:none; border-bottom:1px solid transparent;
}
QWidget[h95f4Frontend="legacy"] QTabBar::tab:hover { color:#c9c1be; }
QWidget[h95f4Frontend="legacy"] QTabBar::tab:selected {
    color:#efd8dd; border-bottom:1px solid #bf8490;
}
QWidget[h95f4Frontend="legacy"] QFrame#settingsCard {
    background:rgba(13,14,17,118); border:none; border-top:1px solid #2b282a;
    border-radius:0px;
}
QWidget[h95f4Frontend="legacy"] QFrame#settingsCard:hover { border-top-color:#423a3d; }
QWidget[h95f4Frontend="legacy"] QFrame#contextStrip {
    background:rgba(13,14,17,108); border:none; border-top:1px solid #2b282a;
    border-radius:0px;
}
QWidget[h95f4Frontend="legacy"] QFrame#h80StudioStageHost {
    background:transparent; border:none; border-radius:0px; margin-bottom:4px;
}
QWidget[h95f4Frontend="legacy"] QLabel#cardTitle { font-size:13px; font-weight:650; }
QWidget[h95f4Frontend="legacy"] QLabel#fieldLabel { min-width:88px; }
QWidget[h95f4Frontend="legacy"] QPushButton { border-radius:3px; }
QWidget[h95f4Frontend="legacy"] QComboBox,
QWidget[h95f4Frontend="legacy"] QSpinBox,
QWidget[h95f4Frontend="legacy"] QDoubleSpinBox,
QWidget[h95f4Frontend="legacy"] QFontComboBox,
QWidget[h95f4Frontend="legacy"] QTextEdit,
QWidget[h95f4Frontend="legacy"] QLineEdit,
QWidget[h95f4Frontend="legacy"] QListWidget { border-radius:3px; }
QWidget[h95f4Frontend="legacy"][h95f4Palette="classic"] QFrame#h95f4LegacyHeader {
    background:rgba(22,15,17,188); border-bottom-color:rgba(191,132,144,45);
}
QWidget[h95f4Frontend="legacy"][h95f4Palette="classic"] QTabBar::tab:selected {
    color:#efd8dd; border-bottom-color:#bf8490;
}
QWidget[h95f4Frontend="legacy"][h95f4Palette="studio"] QFrame#h95f4LegacyHeader {
    background:rgba(15,22,19,188); border-bottom-color:rgba(201,172,119,42);
}
QWidget[h95f4Frontend="legacy"][h95f4Palette="studio"] QTabBar::tab:selected {
    color:#e6ddc8; border-bottom-color:#c9ac77;
}
'''


def _h95f4_frontend_profile(mode):
    legacy = str(mode or '').lower() == 'legacy'
    return {
        'mode': 'legacy' if legacy else 'studio',
        'modern_hero': not legacy,
        'legacy_header': legacy,
        'top_nav': not legacy,
        'workspace_header': not legacy,
        'workspace_grip': not legacy,
        'section_rail': not legacy,
        'native_tabbar': legacy,
        'legacy_labels': legacy,
    }


def _h95f4_frontend_value(panel):
    value = str(getattr(panel, '_h95f4_frontend_version', H95F4_FRONTEND_DEFAULT) or H95F4_FRONTEND_DEFAULT).lower()
    return 'legacy' if value == 'legacy' else 'studio'


def _h95f4_repolish(widget):
    if widget is None: return
    try:
        widget.style().unpolish(widget); widget.style().polish(widget); widget.update()
    except Exception:
        pass


def _h95f4_install_legacy_header(panel):
    existing = getattr(panel, 'h95f4_legacy_header', None)
    if existing is not None:
        return existing
    hero = panel.findChild(QFrame, 'heroCard')
    if hero is None or hero.parentWidget() is None or hero.parentWidget().layout() is None:
        return None
    parent = hero.parentWidget(); layout = parent.layout(); index = layout.indexOf(hero)
    frame = QFrame(parent); frame.setObjectName('h95f4LegacyHeader')
    v = QVBoxLayout(frame); v.setContentsMargins(2, 5, 2, 11); v.setSpacing(3)
    top = QHBoxLayout(); top.setSpacing(9)
    icon = QLabel(frame); icon.setObjectName('h95f4LegacyIcon'); icon.setFixedSize(36,36)
    try:
        pix = QPixmap(_bundled_resource_path(APP_ICON_FILENAME))
        if not pix.isNull(): icon.setPixmap(pix.scaled(32,32,Qt.KeepAspectRatio,Qt.SmoothTransformation))
    except Exception:
        pass
    brand = QLabel('LimbusLyric', frame); brand.setObjectName('h95f4LegacyBrand')
    badge = QLabel('就绪', frame); badge.setObjectName('h95f4LegacyBadge'); badge.setAlignment(Qt.AlignCenter)
    top.addWidget(icon); top.addWidget(brand); top.addStretch(1); top.addWidget(badge)
    track = QLabel('尚未载入歌曲', frame); track.setObjectName('h95f4LegacyTrack'); track.setTextInteractionFlags(Qt.TextSelectableByMouse)
    detail = QLabel('开启自动读词后，切歌会自动刷新歌词；也可以手动读取。', frame); detail.setObjectName('h95f4LegacyDetail'); detail.setWordWrap(True)
    v.addLayout(top); v.addWidget(track); v.addWidget(detail)
    frame.setMinimumHeight(96); frame.setMaximumHeight(116); frame.hide()
    layout.insertWidget(max(0,index+1), frame)
    panel.h95f4_legacy_header = frame; panel.h95f4_legacy_badge = badge
    panel.h95f4_legacy_track = track; panel.h95f4_legacy_detail = detail
    return frame


def _h95f4_sync_legacy_header(panel):
    try:
        badge = getattr(panel,'h95f4_legacy_badge',None); src_badge=getattr(panel,'front_sync_badge',None)
        track = getattr(panel,'h95f4_legacy_track',None); src_track=getattr(panel,'front_track_label',None)
        detail = getattr(panel,'h95f4_legacy_detail',None); src_detail=getattr(panel,'front_detail_label',None)
        if badge is not None and src_badge is not None: badge.setText(str(src_badge.text() or '就绪'))
        if track is not None and src_track is not None: track.setText(str(src_track.text() or '尚未载入歌曲'))
        if detail is not None and src_detail is not None: detail.setText(str(src_detail.text() or ''))
    except Exception:
        pass


def _h95f4_cache_metrics(panel):
    if isinstance(getattr(panel,'_h95f4_card_metrics',None),dict): return
    panel._h95f4_card_metrics={}; panel._h95f4_page_metrics={}
    try:
        for card in panel.findChildren(QFrame,'settingsCard'):
            lay=card.layout()
            if lay is None: continue
            m=lay.contentsMargins(); panel._h95f4_card_metrics[id(card)]=(card,(m.left(),m.top(),m.right(),m.bottom()),int(lay.spacing()))
        for i in range(panel.main_tabs.count()):
            area=panel.main_tabs.widget(i); page=area.widget() if hasattr(area,'widget') else None; lay=page.layout() if page is not None else None
            if lay is None: continue
            m=lay.contentsMargins(); panel._h95f4_page_metrics[i]=(lay,(m.left(),m.top(),m.right(),m.bottom()),int(lay.spacing()))
    except Exception:
        pass


def _h95f4_apply_density(panel, legacy):
    _h95f4_cache_metrics(panel)
    try:
        for card, margins, spacing in list(getattr(panel,'_h95f4_card_metrics',{}).values()):
            lay=card.layout()
            if lay is None: continue
            if legacy: lay.setContentsMargins(10,10,10,12); lay.setSpacing(8)
            else: lay.setContentsMargins(*margins); lay.setSpacing(int(spacing))
        for _idx,(lay,margins,spacing) in list(getattr(panel,'_h95f4_page_metrics',{}).items()):
            if legacy: lay.setContentsMargins(10,9,10,14); lay.setSpacing(7)
            else: lay.setContentsMargins(*margins); lay.setSpacing(int(spacing))
    except Exception:
        pass


def _h95f4_apply_frontend(panel, mode=None, save=False):
    mode = 'legacy' if str(mode or _h95f4_frontend_value(panel)).lower()=='legacy' else 'studio'
    profile = _h95f4_frontend_profile(mode); legacy = mode=='legacy'
    panel._h95f4_frontend_version = mode
    # H95F3's "legacy" compact skin is retired as a user-facing frontend. Keep its preview
    # geometry fix, but force its shell mode to Studio so H95F4 owns the real second shell.
    panel._h95f3_frontend_layout='studio'
    try:
        if '_h95f3_apply_layout' in globals(): _h95f3_apply_layout(panel,'studio',False)
    except Exception: pass
    try:
        card=getattr(panel,'h95f3_layout_card',None)
        if card is not None:
            card.setProperty('h75SearchIgnore',True); card.hide()
    except Exception: pass
    legacy_header=_h95f4_install_legacy_header(panel)
    hero=panel.findChild(QFrame,'heroCard'); nav=getattr(panel,'top_nav',None); header=getattr(panel,'workspace_header',None)
    grip=getattr(panel,'h93_workspace_grip_row',None); rail=getattr(panel,'h88_section_rail',None)
    try:
        if hero is not None: hero.setVisible(bool(profile['modern_hero']))
        if legacy_header is not None: legacy_header.setVisible(bool(profile['legacy_header']))
        if nav is not None: nav.setVisible(bool(profile['top_nav']))
        if header is not None: header.setVisible(bool(profile['workspace_header']))
        if grip is not None: grip.setVisible(bool(profile['workspace_grip']))
        if rail is not None:
            if legacy: rail.hide()
            elif '_h89_rebuild_section_rail' in globals(): _h89_rebuild_section_rail(panel,panel.main_tabs.currentIndex())
        panel.main_tabs.tabBar().setVisible(bool(profile['native_tabbar']))
        labels=H95F4_LEGACY_TAB_LABELS if legacy else H95F4_STUDIO_TAB_LABELS
        for i,text in enumerate(labels):
            if i<panel.main_tabs.count(): panel.main_tabs.setTabText(i,text)
        _h95f4_apply_density(panel,legacy)
        panel.setProperty('h95f4Frontend',mode)
        panel.setProperty('h95f4Palette','classic' if str(getattr(panel,'_h87_frontend_theme','studio'))=='classic' else 'studio')
        for w in (panel,hero,legacy_header,panel.main_tabs,panel.main_tabs.tabBar()): _h95f4_repolish(w)
        _h95f4_sync_legacy_header(panel)
        # Studio-only page/header animations should not try to animate hidden landmarks.
        if legacy and '_h87_clear_page_transition' in globals():
            try: _h87_clear_page_transition(panel)
            except Exception: pass
        combo=getattr(panel,'h95f4_frontend_combo',None)
        if combo is not None and combo.currentData()!=mode:
            combo.blockSignals(True); idx=combo.findData(mode); combo.setCurrentIndex(max(0,idx)); combo.blockSignals(False)
    except Exception as exc:
        try: write_error_log('H95F4前端版本应用失败',exc,detail=f'mode={mode}')
        except Exception: pass
    if save and bool(getattr(panel,'_settings_loaded',False)):
        try:
            data=load_all_config(); settings=data.setdefault('settings',{}); settings['h95f4_frontend_version']=mode; settings['h95f3_frontend_layout']='studio'; _write_config_dict_atomic(data)
        except Exception as exc:
            try: write_error_log('H95F4前端版本即时保存失败',exc)
            except Exception: pass
        try: panel._schedule_config_save()
        except Exception: pass
    return mode


def _h95f4_popup_divider(parent):
    line=QFrame(parent); line.setObjectName('h77PopupDivider'); line.setFixedHeight(1); return line


_H95F4_POPUP_PRE=globals().get('_h95f3_show_interface_popup') or globals().get('_h87_show_interface_popup') or globals().get('_h77_show_interface_popup')
def _h95f4_show_interface_popup(panel):
    if callable(_H95F4_POPUP_PRE): _H95F4_POPUP_PRE(panel)
    try:
        dlg=getattr(panel,'_h73_background_popup',None); lay=dlg.layout() if dlg is not None else None
        if dlg is None or lay is None or bool(dlg.property('h95f4FrontendInjected')): return
        # H95F3 advertised its compact experiment as an Appearance-page layout selector. That
        # surface is retired; keep the palette copy accurate now that frontend version lives here.
        for label in dlg.findChildren(QLabel):
            text=str(label.text() or '').strip()
            if text.startswith('只改变控制面板配色；前端布局请在'):
                label.setText('只改变控制面板配色；新版 / 旧版前端在本面板的“前端版本”中切换。')
        dlg.setProperty('h95f4FrontendInjected',True)
        section=QLabel('前端版本',dlg); section.setObjectName('h77PopupSection')
        row=QHBoxLayout(); row.setSpacing(10)
        name=QLabel('界面结构',dlg); name.setObjectName('h77PopupLabel'); row.addWidget(name); row.addStretch()
        combo=QComboBox(dlg); combo.setObjectName('h77PopupCombo'); combo.setMinimumWidth(178)
        combo.addItem('新版','studio'); combo.addItem('旧版','legacy')
        idx=combo.findData(_h95f4_frontend_value(panel)); combo.setCurrentIndex(max(0,idx)); row.addWidget(combo)
        hint=QLabel('旧版会恢复早期的简洁歌曲状态头与标签页结构；播放器、歌词源和现有设置保持不变。',dlg); hint.setObjectName('popupHint'); hint.setWordWrap(True)
        lay.insertWidget(2,section); lay.insertLayout(3,row); lay.insertWidget(4,hint); lay.insertWidget(5,_h95f4_popup_divider(dlg))
        combo.currentIndexChanged.connect(lambda _i,p=panel,c=combo:_h95f4_apply_frontend(p,c.currentData(),True))
        panel.h95f4_frontend_combo=combo
        dlg.adjustSize()
        anchor=getattr(getattr(panel,'window_title_bar',None),'background_btn',None)
        if anchor is not None:
            gp=anchor.mapToGlobal(QPoint(0,anchor.height()))
            x=gp.x()-max(0,dlg.width()-anchor.width()); y=gp.y()+5
            screen=QApplication.screenAt(gp) if hasattr(QApplication,'screenAt') else QApplication.primaryScreen()
            if screen is not None:
                area=screen.availableGeometry(); x=max(area.left()+6,min(x,area.right()-dlg.width()-6)); y=max(area.top()+6,min(y,area.bottom()-dlg.height()-6))
            dlg.move(x,y)
    except Exception as exc:
        try: write_error_log('H95F4界面弹窗前端版本注入失败',exc)
        except Exception: pass


_H95F4_STATUS_PRE=getattr(ControlPanel,'_refresh_frontend_status',None) if 'ControlPanel' in globals() else None
def _h95f4_refresh_frontend_status(panel,*args,**kwargs):
    out=_H95F4_STATUS_PRE(panel,*args,**kwargs) if callable(_H95F4_STATUS_PRE) else None
    _h95f4_sync_legacy_header(panel)
    return out


_H95F4_SAVE_PRE=globals().get('save_all_config')
def _h95f4_save_all_config(panel,presets,players):
    if callable(_H95F4_SAVE_PRE): _H95F4_SAVE_PRE(panel,presets,players)
    try:
        data=load_all_config(); settings=data.setdefault('settings',{}); settings['h95f4_frontend_version']=_h95f4_frontend_value(panel); settings['h95f3_frontend_layout']='studio'; _write_config_dict_atomic(data)
    except Exception: pass


_H95F4_DENSITY_PRE=globals().get('_h95f1_apply_shell_density')
def _h95f4_apply_shell_density(panel):
    out=_H95F4_DENSITY_PRE(panel) if callable(_H95F4_DENSITY_PRE) else None
    try: _h95f4_apply_frontend(panel,_h95f4_frontend_value(panel),False)
    except Exception: pass
    return out


def _h95f4_reconcile_page_shell(panel):
    if _h95f4_frontend_value(panel)!='legacy': return
    try:
        hero=panel.findChild(QFrame,'heroCard'); legacy_header=getattr(panel,'h95f4_legacy_header',None)
        nav=getattr(panel,'top_nav',None); header=getattr(panel,'workspace_header',None); grip=getattr(panel,'h93_workspace_grip_row',None); rail=getattr(panel,'h88_section_rail',None)
        if hero is not None: hero.hide()
        if legacy_header is not None: legacy_header.show()
        if nav is not None: nav.hide()
        if header is not None: header.hide()
        if grip is not None: grip.hide()
        if rail is not None: rail.hide()
        panel.main_tabs.tabBar().show()
        _h95f4_sync_legacy_header(panel)
    except Exception: pass


_H95F4_THEME_PRE=globals().get('_h87_apply_frontend_theme')
def _h95f4_apply_frontend_theme(panel,theme=None,save=False):
    out=_H95F4_THEME_PRE(panel,theme,save) if callable(_H95F4_THEME_PRE) else None
    try:
        style=str(panel.styleSheet() or '')
        if H95F4_QSS not in style: panel.setStyleSheet(style+H95F4_QSS)
        panel.setProperty('h95f4Palette','classic' if str(getattr(panel,'_h87_frontend_theme','studio'))=='classic' else 'studio')
        _h95f4_apply_frontend(panel,_h95f4_frontend_value(panel),False)
    except Exception: pass
    return out


_H95F4_CONTROL_INIT_PRE=ControlPanel.__init__ if 'ControlPanel' in globals() else None
def _h95f4_control_init(panel,*args,**kwargs):
    _H95F4_CONTROL_INIT_PRE(panel,*args,**kwargs)
    try:
        settings=(load_all_config().get('settings') or {}) if 'load_all_config' in globals() else {}
        saved=settings.get('h95f4_frontend_version',None)
        if saved is None:
            # One-time migration for users who tried H95F3's misleading compact option.
            saved='legacy' if str(settings.get('h95f3_frontend_layout','studio')).lower()=='legacy' else H95F4_FRONTEND_DEFAULT
        panel._h95f4_frontend_version='legacy' if str(saved).lower()=='legacy' else 'studio'
        panel._h95f3_frontend_layout='studio'
        panel._default_stylesheet=str(getattr(panel,'_default_stylesheet','') or '')+H95F4_QSS
        panel._limbus_stylesheet=str(getattr(panel,'_limbus_stylesheet','') or '')+H95F4_QSS
        try: panel.setStyleSheet(str(panel.styleSheet() or '')+H95F4_QSS)
        except Exception: pass
        _h95f4_install_legacy_header(panel); _h95f4_cache_metrics(panel)
        card=getattr(panel,'h95f3_layout_card',None)
        if card is not None: card.setProperty('h75SearchIgnore',True); card.hide()
        panel._h73_show_background_popup=lambda p=panel:_h95f4_show_interface_popup(p)
        try:
            btn=getattr(getattr(panel,'window_title_bar',None),'background_btn',None)
            if btn is not None: btn.setToolTip('界面 · 前端版本、配色、缩放与背景')
        except Exception: pass
        _h95f4_apply_frontend(panel,panel._h95f4_frontend_version,False)
        panel.main_tabs.currentChanged.connect(lambda _i,p=panel: QTimer.singleShot(0,lambda: _h95f4_reconcile_page_shell(p)))
        QTimer.singleShot(0,lambda p=panel:_h95f4_apply_frontend(p,_h95f4_frontend_value(p),False))
        QTimer.singleShot(80,lambda p=panel:_h95f4_apply_frontend(p,_h95f4_frontend_value(p),False))
    except Exception as exc:
        try: write_error_log('H95F4真实旧版前端安装失败',exc)
        except Exception: pass


def _h95f4_activate():
    try:
        globals()['save_all_config']=_h95f4_save_all_config
        if callable(_H95F4_DENSITY_PRE): globals()['_h95f1_apply_shell_density']=_h95f4_apply_shell_density
        if callable(_H95F4_THEME_PRE): globals()['_h87_apply_frontend_theme']=_h95f4_apply_frontend_theme
        if 'ControlPanel' in globals() and callable(_H95F4_CONTROL_INIT_PRE):
            if callable(_H95F4_STATUS_PRE): ControlPanel._refresh_frontend_status=_h95f4_refresh_frontend_status; ControlPanel._refresh_frontend_status._limbus_layer='H95F4'
            ControlPanel.__init__=_h95f4_control_init; ControlPanel.__init__._limbus_layer='H95F4'; ControlPanel.__init__._limbus_policy='true V29-inspired legacy shell + modern Studio shell; current runtime owners only'
    except Exception as exc:
        try: write_error_log('H95F4真实旧版前端闭环激活失败',exc)
        except Exception: pass


if '_h95f4_activate' in globals(): _h95f4_activate()


# H95F4F1 startup re-entry closure ----------------------------------------------------
# H95F4 owns a second shell, but its first implementation reused H95F3's Studio
# restoration helper while also wrapping the global H95F1 density hook.  During
# ControlPanel construction this formed a synchronous cycle:
#   H95F4 apply -> H95F3 Studio apply -> global density -> H95F4 density -> H95F4 apply.
# It ran on the GUI thread before the splash could finish, so startup appeared frozen.
# Keep H95F4's shell contract unchanged and add a narrow re-entry guard around the
# already-reviewed H95F4 applicator. Nested density/theme reconciliation requests are
# intentionally coalesced into the outer application transaction.
_H95F4F1_APPLY_FRONTEND_PRE = globals().get('_h95f4_apply_frontend')


def _h95f4f1_apply_frontend(panel, mode=None, save=False):
    requested = 'legacy' if str(mode or _h95f4_frontend_value(panel)).lower() == 'legacy' else 'studio'
    if bool(getattr(panel, '_h95f4_frontend_apply_guard', False)):
        # The outer transaction already owns visibility, labels, density and persistence.
        # Returning the requested normalized mode prevents H95F3/H95F1 reconciliation from
        # recursively re-entering the shell applicator during startup or resize.
        return requested
    panel._h95f4_frontend_apply_guard = True
    try:
        if callable(_H95F4F1_APPLY_FRONTEND_PRE):
            return _H95F4F1_APPLY_FRONTEND_PRE(panel, requested, save)
        return requested
    finally:
        panel._h95f4_frontend_apply_guard = False


def _h95f4f1_activate():
    try:
        if callable(_H95F4F1_APPLY_FRONTEND_PRE):
            globals()['_h95f4_apply_frontend'] = _h95f4f1_apply_frontend
            _h95f4f1_apply_frontend._limbus_layer = 'H95F4F1'
            _h95f4f1_apply_frontend._limbus_policy = 'coalesce nested legacy/studio shell reconciliation; startup GUI thread must not recurse'
    except Exception as exc:
        try: write_error_log('H95F4F1启动重入闭环激活失败', exc)
        except Exception: pass


if '_h95f4f1_activate' in globals(): _h95f4f1_activate()


