def _h95f5_result_wrap(panel,result,pre):
    row=dict(result or {}); out=pre(panel,result)
    try:
        if row.get('lyric') and str(row.get('event') or 'search-result') not in ('needs-input','identity-ready','fatal'):
            QTimer.singleShot(0,lambda p=panel:_h95f5_schedule_translation_fetch(p))
    except Exception: pass
    return out


