# H95F6 dual-lane bilingual + player inspector + modern glass
# H95F5 proved bilingual/placement behavior but rendered translation as a post-paint
# sidecar. H95F6 integrates translation into the mature visual state: the primary lane
# keeps precise provider timing while the translation lane mirrors the resolved preset
# (font/color/outline/glow/shadow/depth/entrance/exit/shake) and only applies bilingual
# layout deltas (relative size/gap). It also scopes Sync Doctor by player, collapses the
# growing four-player sync card into a current-player inspector, and restores a translucent
# modern title-bar glass without touching Legacy chrome.
H95F6_TRANSLATION_SCALE_DEFAULT = 82
H95F6_MODERN_CLASSIC_ALPHA = 176
H95F6_MODERN_STUDIO_ALPHA = 170
H95F6_SYNC_SCOPE_SEPARATOR = '::'


def _h95f6_player_key(value):
    text = str(value or '').strip(); upper = text.upper()
    if 'SPOTIFY' in upper: return 'spotify'
    if 'QQ' in upper: return 'qq'
    if '酷狗' in text or 'KUGOU' in upper or 'KU GOU' in upper: return 'kugou'
    if '网易' in text or 'NETEASE' in upper or 'CLOUDMUSIC' in upper: return 'netease'
    safe = re.sub(r'[^a-z0-9]+', '-', upper.lower()).strip('-')
    return safe or 'unknown'


def _h95f6_player_label(key):
    return {'netease':'网易云','qq':'QQ音乐','kugou':'酷狗','spotify':'Spotify'}.get(str(key or ''), str(key or '当前播放器'))


def _h95f6_lane_font(base_font, scale_pct=H95F6_TRANSLATION_SCALE_DEFAULT):
    """Preserve the resolved user preset exactly; scale only the bilingual secondary lane."""
    font = QFont(base_font)
    try: scale = max(0.50, min(1.00, float(scale_pct) / 100.0))
    except Exception: scale = float(H95F6_TRANSLATION_SCALE_DEFAULT) / 100.0
    size = float(font.pointSizeF())
    if size > 0: font.setPointSizeF(max(6.0, size * scale))
    else: font.setPixelSize(max(9, int(round(max(12, font.pixelSize()) * scale))))
    return font


def _h95f6_lane_spacing(base_spacing, scale_pct=H95F6_TRANSLATION_SCALE_DEFAULT):
    try: return max(0.5, float(base_spacing) * max(0.50, min(1.00, float(scale_pct) / 100.0)))
    except Exception: return max(0.5, float(base_spacing or 5.0) * 0.82)


def _h95f6_translation_origin(main_text, trans_text, main_font, trans_font, spacing, scale_pct, gap_px, angle):
    mfm = QFontMetrics(QFont(main_font)); tfm = QFontMetrics(QFont(trans_font))
    msp = float(spacing); tsp = _h95f6_lane_spacing(spacing, scale_pct)
    main_len = sum(float(mfm.horizontalAdvance(ch)) for ch in str(main_text or '')) + max(0, len(str(main_text or ''))-1) * msp
    trans_len = sum(float(tfm.horizontalAdvance(ch)) for ch in str(trans_text or '')) + max(0, len(str(trans_text or ''))-1) * tsp
    rad = math.radians(float(angle)); ax = math.cos(rad); ay = math.sin(rad); px = -ay; py = ax
    shift = (main_len - trans_len) * 0.5
    offset = float(mfm.height()) + max(2.0, float(gap_px)) + float(tfm.height()) * 0.10
    return (ax * shift + px * offset, ay * shift + py * offset, ax, ay, tsp, tfm)


def _h95f6_main_index_for_secondary(index, secondary_len, primary_len):
    if primary_len <= 0: return 0
    if secondary_len <= 1: return max(0, primary_len - 1)
    return max(0, min(primary_len - 1, int(round(float(index) * float(primary_len - 1) / float(secondary_len - 1)))))


def _h95f6_primary_flow_state(owner, main_index, base_alpha=1.0):
    alpha = max(0.0, min(1.0, float(base_alpha))); dx = dy = 0.0
    try:
        for fs, fe, fa in getattr(owner, '_flow_fade_ranges', []) or []:
            if int(fs) <= int(main_index) < int(fe): alpha *= max(0.0, min(1.0, float(fa))); break
        else:
            if int(getattr(owner, '_flow_fade_start', -1)) <= int(main_index) < int(getattr(owner, '_flow_fade_end', -1)):
                alpha *= max(0.0, min(1.0, float(getattr(owner, '_flow_fade_alpha', 1.0) or 1.0)))
    except Exception: pass
    try:
        for ms, me, mdx, mdy in getattr(owner, '_flow_motion_ranges', []) or []:
            if int(ms) <= int(main_index) < int(me): dx = float(mdx); dy = float(mdy); break
    except Exception: pass
    return alpha, dx, dy


def _h95f6_draw_glyph_path(painter, path, *, fill, stroke, stroke_width, outline, shadow, shadow_color, glow, glow_color, glow_size, glow_alpha, opacity=1.0):
    if path is None or path.isEmpty() or float(opacity) <= 0.0: return
    painter.save(); painter.setOpacity(max(0.0, min(1.0, float(opacity))))
    try:
        if bool(glow): _draw_soft_glow_path(painter, path, QColor(glow_color), float(glow_size), float(glow_alpha))
        if bool(shadow):
            painter.save(); painter.translate(3.0, 3.0); painter.setPen(Qt.NoPen); painter.setBrush(QColor(shadow_color)); painter.drawPath(path); painter.restore()
        if bool(outline) and float(stroke_width or 0.0) > 0.0:
            painter.setPen(QPen(QColor(stroke), float(stroke_width) * 2.0, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        else: painter.setPen(Qt.NoPen)
        painter.setBrush(QColor(fill)); painter.drawPath(path)
    finally: painter.restore()


def _h95f6_draw_active_translation(window, painter, text):
    text = str(text or '').strip(); main = str(getattr(window, 'full_text', '') or '')
    if not text or not main or int(getattr(window, 'char_index', 0) or 0) <= 0: return False
    scale_pct = int(getattr(window, '_h95f5_translation_scale_pct', H95F6_TRANSLATION_SCALE_DEFAULT) or H95F6_TRANSLATION_SCALE_DEFAULT)
    gap_px = int(getattr(window, '_h95f5_translation_gap_px', H95F5_TRANSLATION_GAP_DEFAULT) or H95F5_TRANSLATION_GAP_DEFAULT)
    font = _h95f6_lane_font(window.font, scale_pct)
    ox, oy, ax, ay, tsp, fm = _h95f6_translation_origin(main, text, window.font, font, float(getattr(window,'spacing',5.0) or 5.0), scale_pct, gap_px, float(getattr(window,'angle',0.0) or 0.0))
    primary_len = max(1, len(main)); secondary_len = max(1, len(text)); revealed = max(0, min(primary_len, int(getattr(window,'char_index',0) or 0)))
    base_alpha = max(0.0, min(1.0, float(getattr(window,'line_alpha',1.0) or 0.0))) if getattr(window,'lyric_timeline',None) else 1.0
    advances = [float(fm.horizontalAdvance(ch)) for ch in text]
    cursor = 0.0; shakes = getattr(window,'char_shakes',[]) or []; emph = getattr(window,'_audio_emphasis_latched_scales',[]) or []
    painter.save()
    try:
        if bool(getattr(window,'perspective_enabled',False)): painter.setTransform(window.persp_transform, True)
        painter.translate(float(window.x), float(window.y))
        if '_h54_apply_active_depth_transform' in globals():
            try: _h54_apply_active_depth_transform(painter, window)
            except Exception: pass
        for i, ch in enumerate(text):
            mi = _h95f6_main_index_for_secondary(i, secondary_len, primary_len)
            if mi >= revealed: cursor += advances[i] + tsp; continue
            alpha, mdx, mdy = _h95f6_primary_flow_state(window, mi, base_alpha)
            sx = sy = 0.0
            try:
                if mi < len(shakes) and getattr(window,'_flow_mode','') != 'intro-credit-soft': sx=float(shakes[mi].get('x',0) or 0); sy=float(shakes[mi].get('y',0) or 0)
            except Exception: pass
            gx = ox + ax * cursor + sx + mdx; gy = oy + ay * cursor + sy + mdy
            path = QPainterPath(); path.addText(0.0, float(fm.height())/3.0, font, ch)
            glyph_scale = 1.0
            try:
                if mi < len(emph): glyph_scale=max(1.0,min(float(AUDIO_EMPHASIS_ABSOLUTE_MAX_SCALE),float(emph[mi] or 1.0)))
            except Exception: glyph_scale=1.0
            if glyph_scale > 1.001:
                br=path.boundingRect(); c=br.center(); anchor_y=br.bottom(); tr=QTransform(); tr.translate(gx+c.x(),gy+anchor_y); tr.scale(glyph_scale,glyph_scale); tr.translate(-c.x(),-anchor_y); face=tr.map(path)
            else:
                tr=QTransform(); tr.translate(gx,gy); face=tr.map(path)
            _h95f6_draw_glyph_path(painter, face, fill=window.text_color, stroke=window.stroke_color, stroke_width=window.stroke_width, outline=window.outline_enabled, shadow=window.shadow_enabled, shadow_color=window.shadow_color, glow=window.glow, glow_color=window.glow_color, glow_size=window.glow_size, glow_alpha=window.glow_alpha, opacity=alpha)
            cursor += advances[i] + tsp
    finally: painter.restore()
    return True


def _h95f6_exit_progress(row):
    effect = _h70_effect_key(getattr(row,'exit_effect','fade')) if '_h70_effect_key' in globals() else str(getattr(row,'exit_effect','fade') or 'fade')
    if effect == 'hop_drop':
        try: return max(0.0,min(1.0,float(getattr(row,'_h59_hop_progress',0.0) or 0.0)))
        except Exception: pass
    if effect == 'blur_decay' and '_h62_decay_progress' in globals():
        try: return max(0.0,min(1.0,float(_h62_decay_progress(row))))
        except Exception: pass
    try: return max(0.0,min(1.0,float(getattr(row,'_h16_exit_progress',1.0-float(row.alpha)/255.0) or 0.0)))
    except Exception: return max(0.0,min(1.0,1.0-float(getattr(row,'alpha',255) or 0)/255.0))


def _h95f6_exit_glyph_state(row, index, count):
    effect = _h70_effect_key(getattr(row,'exit_effect','fade')) if '_h70_effect_key' in globals() else str(getattr(row,'exit_effect','fade') or 'fade')
    p = _h95f6_exit_progress(row); alpha=max(0.0,min(1.0,float(getattr(row,'alpha',255) or 0)/255.0)); dx=dy=0.0
    if effect == 'instant': return 0.0,0.0,0.0
    if effect == 'per_char' and count>0:
        order=float(index)/max(1.0,float(count-1)); start=order*0.58; q=max(0.0,min(1.0,(p-start)/max(0.08,1.0-start))); alpha *= (1.0-q); dy += 5.0*q
    elif effect in ('wipe_ltr','wipe_rtl') and count>0:
        order=float(index)/max(1.0,float(count-1)); order=order if effect=='wipe_ltr' else 1.0-order; start=order*0.72; q=max(0.0,min(1.0,(p-start)/0.28)); alpha *= (1.0-q); dx += (5.0 if effect=='wipe_ltr' else -5.0)*q
    return alpha,dx,dy


def _h95f6_draw_history_translation(row, painter, text):
    text=str(text or '').strip(); main=str(getattr(row,'text','') or '')
    if not text or not main or int(getattr(row,'alpha',0) or 0)<=0: return False
    scale_pct=int(getattr(row,'_h95f5_translation_scale_pct',H95F6_TRANSLATION_SCALE_DEFAULT) or H95F6_TRANSLATION_SCALE_DEFAULT); gap_px=int(getattr(row,'_h95f5_translation_gap_px',H95F5_TRANSLATION_GAP_DEFAULT) or H95F5_TRANSLATION_GAP_DEFAULT)
    font=_h95f6_lane_font(row.font,scale_pct); ox,oy,ax,ay,tsp,fm=_h95f6_translation_origin(main,text,row.font,font,float(getattr(row,'spacing',5.0) or 5.0),scale_pct,gap_px,float(getattr(row,'angle',0.0) or 0.0))
    advances=[float(fm.horizontalAdvance(ch)) for ch in text]; cursor=0.0; shakes=getattr(row,'char_shakes',[]) or []
    painter.save()
    try:
        _h95f5_apply_history_group_transform(row,painter)
        painter.translate(float(row.x),float(row.y))
        for i,ch in enumerate(text):
            mi=_h95f6_main_index_for_secondary(i,len(text),max(1,len(main))); alpha,mdx,mdy=_h95f6_exit_glyph_state(row,i,len(text)); sx=sy=0.0
            try:
                if mi < len(shakes): sx=float(shakes[mi].get('x',0) or 0); sy=float(shakes[mi].get('y',0) or 0)
            except Exception: pass
            path=QPainterPath(); path.addText(0.0,float(fm.height())/3.0,font,ch); tr=QTransform(); tr.translate(ox+ax*cursor+sx+mdx,oy+ay*cursor+sy+mdy); face=tr.map(path)
            _h95f6_draw_glyph_path(painter,face,fill=row.color,stroke=row.stroke_color,stroke_width=row.stroke_width,outline=row.outline_enabled,shadow=row.shadow_enabled,shadow_color=row.shadow_color,glow=row.glow,glow_color=row.glow_color,glow_size=row.glow_size,glow_alpha=row.glow_alpha,opacity=alpha)
            cursor += advances[i]+tsp
    finally: painter.restore()
    return True


def _h95f6_group_box(window, x, y, angle, translation=None):
    main=str(getattr(window,'full_text','') or ''); box=window._placement_box(main,x,y,angle); trans=str(translation if translation is not None else _h95f5_translation_for_line(window) or '')
    if not trans: return box
    scale=int(getattr(window,'_h95f5_translation_scale_pct',H95F6_TRANSLATION_SCALE_DEFAULT) or H95F6_TRANSLATION_SCALE_DEFAULT); tfont=_h95f6_lane_font(window.font,scale); tsp=_h95f6_lane_spacing(float(window.spacing),scale)
    main_len,main_h,_=window._placement_metrics(main,window.font,window.spacing); trans_len,trans_h,_=window._placement_metrics(trans,tfont,tsp); rad=math.radians(float(angle)); ax=math.cos(rad); ay=math.sin(rad); px=-ay; py=ax; gap=max(2.0,float(getattr(window,'_h95f5_translation_gap_px',H95F5_TRANSLATION_GAP_DEFAULT) or H95F5_TRANSLATION_GAP_DEFAULT)); shift=(float(main_len)-float(trans_len))*0.5; offset=float(main_h)+gap+float(trans_h)*0.10; tx=float(x)+ax*shift+px*offset; ty=float(y)+ay*shift+py*offset; tbox=window._placement_box(trans,tx,ty,angle,tfont,tsp)
    return (min(box[0],tbox[0]),min(box[1],tbox[1]),max(box[2],tbox[2]),max(box[3],tbox[3]))


def _h95f6_row_group_box(row):
    try:
        text=str(getattr(row,'text','') or ''); trans=str(getattr(row,'_h95f5_translation','') or ''); font=QFont(row.font); fm=QFontMetrics(font); spacing=float(getattr(row,'spacing',5.0) or 5.0); main_len=sum(float(fm.horizontalAdvance(ch)) for ch in text)+max(0,len(text)-1)*spacing; main_h=float(fm.height()); pad=max(20.0,main_h*0.72); angle=float(getattr(row,'angle',0.0) or 0.0); rad=math.radians(angle); ax=math.cos(rad); ay=math.sin(rad); px=-ay; py=ax; x=float(row.x); y=float(row.y); x2=x+main_len*ax; y2=y+main_len*ay; box=(min(x,x2)-pad,min(y,y2)-pad,max(x,x2)+pad,max(y,y2)+pad)
        if not trans: return box
        scale=int(getattr(row,'_h95f5_translation_scale_pct',H95F6_TRANSLATION_SCALE_DEFAULT) or H95F6_TRANSLATION_SCALE_DEFAULT); tf=_h95f6_lane_font(font,scale); tfm=QFontMetrics(tf); tsp=_h95f6_lane_spacing(spacing,scale); tlen=sum(float(tfm.horizontalAdvance(ch)) for ch in trans)+max(0,len(trans)-1)*tsp; th=float(tfm.height()); shift=(main_len-tlen)*0.5; off=main_h+float(getattr(row,'_h95f5_translation_gap_px',H95F5_TRANSLATION_GAP_DEFAULT) or H95F5_TRANSLATION_GAP_DEFAULT)+th*0.10; tx=x+ax*shift+px*off; ty=y+ay*shift+py*off; tx2=tx+tlen*ax; ty2=ty+tlen*ay; tpad=max(16.0,th*0.72); tbox=(min(tx,tx2)-tpad,min(ty,ty2)-tpad,max(tx,tx2)+tpad,max(ty,ty2)+tpad); return (min(box[0],tbox[0]),min(box[1],tbox[1]),max(box[2],tbox[2]),max(box[3],tbox[3]))
    except Exception: return (0.0,0.0,0.0,0.0)


_H95F6_PAINT_PRE = LyricWindow.paintEvent if 'LyricWindow' in globals() else None
_H95F6_FADE_PRE = FadingLine.draw if 'FadingLine' in globals() else None


def _h95f6_paint_event(window,event):
    # Keep H95F5 bilingual geometry/dirty-region ownership active, but suppress only its
    # old post-paint glyph helper. This avoids the old flat sidecar without hiding the
    # translation from active-region repaint accounting.
    saved_draw=globals().get('_h95f5_draw_secondary_text')
    try:
        globals()['_h95f5_draw_secondary_text']=lambda *a,**k: False
        out=_H95F6_PAINT_PRE(window,event)
    finally:
        if saved_draw is not None: globals()['_h95f5_draw_secondary_text']=saved_draw
    try:
        text=_h95f5_translation_for_line(window)
        if text:
            p=QPainter(window); p.setRenderHint(QPainter.Antialiasing,True); _h95f6_draw_active_translation(window,p,text); p.end()
    except Exception: pass
    return out


def _h95f6_fading_draw(row,painter):
    saved=str(getattr(row,'_h95f5_translation','') or '')
    saved_draw=globals().get('_h95f5_draw_secondary_text')
    try:
        globals()['_h95f5_draw_secondary_text']=lambda *a,**k: False
        out=_H95F6_FADE_PRE(row,painter)
    finally:
        if saved_draw is not None: globals()['_h95f5_draw_secondary_text']=saved_draw
    try:
        if saved: _h95f6_draw_history_translation(row,painter,saved)
    except Exception: pass
    return out


def _h95f6_find_top_layout_row(root_layout, widget):
    if root_layout is None or widget is None: return None
    for i in range(root_layout.count()):
        item=root_layout.itemAt(i)
        if item.widget() is widget: return (root_layout,i)
        child=item.layout()
        if child is not None:
            for j in range(child.count()):
                ci=child.itemAt(j)
                if ci.widget() is widget: return (root_layout,i)
    return None


def _h95f6_set_bilingual(panel, enabled, save=True):
    enabled=bool(enabled); combo=getattr(panel,'h95f5_bilingual_combo',None)
    if combo is not None:
        idx=combo.findData('bilingual' if enabled else 'original')
        if idx>=0 and combo.currentIndex()!=idx: combo.setCurrentIndex(idx)
    else:
        panel._h95f5_bilingual_mode='bilingual' if enabled else 'original'; _h95f5_apply_panel_settings(panel,save,enabled)
    if enabled and hasattr(panel,'trans_check') and panel.trans_check.isChecked(): panel.trans_check.setChecked(False)
    try:
        panel.h95f6_bilingual_check.blockSignals(True); panel.h95f6_bilingual_check.setChecked(enabled); panel.h95f6_bilingual_check.blockSignals(False)
    except Exception: pass
    _h95f6_sync_language_controls(panel)


def _h95f6_sync_language_controls(panel):
    bilingual=_h95f5_norm_mode(getattr(panel,'_h95f5_bilingual_mode','original'))=='bilingual'
    trans_only=bool(getattr(panel,'trans_check',None) is not None and panel.trans_check.isChecked())
    try:
        panel.h95f6_bilingual_check.blockSignals(True); panel.h95f6_bilingual_check.setChecked(bilingual and not trans_only); panel.h95f6_bilingual_check.blockSignals(False)
        panel.h95f6_bilingual_check.setEnabled(not trans_only)
    except Exception: pass
    for name in ('h95f6_translation_scale','h95f6_translation_gap','h95f6_translation_scale_label'):
        w=getattr(panel,name,None)
        if w is not None: w.setEnabled(bilingual and not trans_only)
    try:
        if trans_only and bilingual: _h95f6_set_bilingual(panel,False,True)
    except Exception: pass


