        # Replace only Sync Doctor helpers; unified lyric identity and translation identity stay song+artist.
        globals()['_h95_activate_song_correction']=_h95f6_activate_song_correction; globals()['_h95_store_current_row']=_h95f6_store_current_row; globals()['_h95_adjust_current_song']=_h95f6_adjust_current_song; globals()['_h95_anchor_current_line']=_h95f6_anchor_current_line; globals()['_h95_remove_last_anchor']=_h95f6_remove_last_anchor; globals()['_h95_reset_current_song']=_h95f6_reset_current_song; globals()['_h95_refresh_sync_doctor_ui']=_h95f6_refresh_sync_doctor_ui
