_H95F7_CONTROL_INIT_PRE = ControlPanel.__init__ if 'ControlPanel' in globals() else None

def _h95f7_control_init(panel,*args,**kwargs):
    _H95F7_CONTROL_INIT_PRE(panel,*args,**kwargs)
