# H95F9 translation alignment + exit continuity ---------------------------------------
# Field H95F8 logs exposed two independent presentation gaps. Translation retrieval was
# successful but a strict nearest-timestamp join aligned only a subset of provider rows;
# meanwhile blur-decay history planning reused its material-progress value as the release
# visibility progress, so a row entering the real exit lane at p0~=0.8 looked almost gone.
# H95F9 keeps provider text authoritative (never machine-translates missing rows), upgrades
# the join to monotonic offset-aware sequence alignment, and separates residence material
# blur from the real release visibility envelope. Playback/seek/source timing is untouched.
H95F9_TRANSLATION_MAX_TOLERANCE_MS = 2600
H95F9_TRANSLATION_SKIP_COST_MS = 1450
H95F9_TRANSLATION_OFFSET_PROBE_MS = 3200
H95F9_EXIT_VISIBILITY_MIN_MS = 900.0

_H95F9_ALIGN_PRE = globals().get('_h95f5_align_translation_lines')
_H95F9_TRANSLATION_RESULT_PRE = globals().get('_h95f5_translation_result')
_H95F9_TRANSLATION_CACHE_PRE = globals().get('_h95f5_apply_cached_translation')
_H95F9_BLUR_PROGRESS_PRE = globals().get('_h62_decay_progress')
_H95F9_BLUR_MIX_PRE = globals().get('_h62_decay_mix')
_H95F9_EXIT_PROGRESS_PRE = globals().get('_h95f6_exit_progress')
_h95f9_mix_tls = threading.local()


def _h95f9_translation_rows(translation_timeline):
    rows=[]
    for item in list(translation_timeline or []):
        try:
            at=int(item[0]); text=str(item[1] or '').strip()
        except Exception:
            continue
        if text:
            rows.append((at,text))
    rows.sort(key=lambda x:x[0])
    return rows


def _h95f9_translation_offset(main_times, trans_times):
    if not main_times or not trans_times:
        return 0
    diffs=[]
    for t in trans_times:
        pos=bisect.bisect_left(main_times,t)
        cand=[]
        for i in (pos-1,pos,pos+1):
            if 0<=i<len(main_times): cand.append(int(t)-int(main_times[i]))
        if not cand: continue
        d=min(cand,key=lambda x:abs(x))
        if abs(d)<=int(H95F9_TRANSLATION_OFFSET_PROBE_MS): diffs.append(int(d))
    if not diffs:
        return 0
    diffs.sort()
    mid=len(diffs)//2
    return int(diffs[mid] if len(diffs)%2 else round((diffs[mid-1]+diffs[mid])*0.5))


def _h95f9_local_translation_tolerance(main_times,index,base):
    gaps=[]
    if index>0: gaps.append(max(0,int(main_times[index])-int(main_times[index-1])))
    if index+1<len(main_times): gaps.append(max(0,int(main_times[index+1])-int(main_times[index])))
    gap=min([g for g in gaps if g>0],default=0)
    adaptive=float(base)
    if gap>0:
        adaptive=max(adaptive,min(float(H95F9_TRANSLATION_MAX_TOLERANCE_MS),350.0+gap*0.42))
    return int(max(int(base),min(int(H95F9_TRANSLATION_MAX_TOLERANCE_MS),round(adaptive))))


def _h95f9_align_translation_lines(main_lines, translation_timeline, tolerance_ms=H95F5_TRANSLATION_ALIGN_TOLERANCE_MS):
    mains=[]
    for line in list(main_lines or []):
        try: mains.append((int(line.get('start_ms') or 0),str(line.get('text') or '').strip()))
        except Exception: mains.append((0,''))
    trans=_h95f9_translation_rows(translation_timeline)
    if not mains: return []
    if not trans: return ['']*len(mains)
    mt=[x[0] for x in mains]; tt=[x[0] for x in trans]
    offset=_h95f9_translation_offset(mt,tt)
    n=len(mains); m=len(trans); inf=10**18
    # Monotonic sequence DP. Skipping a row is cheaper than accepting a wildly wrong time,
    # but a coherent provider-wide offset or sparse-line drift can exceed the old 900 ms.
    dp=[[inf]*(m+1) for _ in range(n+1)]; prev=[[None]*(m+1) for _ in range(n+1)]
    dp[0][0]=0
    skip=float(H95F9_TRANSLATION_SKIP_COST_MS)
    for i in range(n+1):
        for j in range(m+1):
            cur=dp[i][j]
            if cur>=inf: continue
            if i<n and cur+skip<dp[i+1][j]:
                dp[i+1][j]=cur+skip; prev[i+1][j]=(i,j,'m')
            if j<m and cur+skip<dp[i][j+1]:
                dp[i][j+1]=cur+skip; prev[i][j+1]=(i,j,'t')
            if i<n and j<m:
                adjusted=int(trans[j][0])-int(offset); diff=abs(adjusted-int(mains[i][0]))
                tol=_h95f9_local_translation_tolerance(mt,i,int(tolerance_ms))
                same=bool(trans[j][1] and re.sub(r'\s+','',trans[j][1]).casefold()==re.sub(r'\s+','',mains[i][1]).casefold())
                if diff<=tol and not same:
                    # Slightly favor matches so stable sequence evidence can rescue rows at
                    # 1.0-2.0 s provider drift without swallowing a genuinely omitted row.
                    cost=float(diff)*0.72
                    if cur+cost<dp[i+1][j+1]:
                        dp[i+1][j+1]=cur+cost; prev[i+1][j+1]=(i,j,'x')
    out=['']*n; i=n; j=m
    while i>0 or j>0:
        step=prev[i][j]
        if step is None: break
        pi,pj,kind=step
        if kind=='x' and i>0 and j>0:
            out[i-1]=str(trans[j-1][1] or '')
        i,j=pi,pj
    # Never regress a row that the old conservative matcher could prove safely. This is
    # especially useful for duplicate/refrain timestamps where several DP paths tie.
    if callable(_H95F9_ALIGN_PRE):
        try:
            old=list(_H95F9_ALIGN_PRE(main_lines,translation_timeline,tolerance_ms))
            if len(old)==len(out):
                for k,text in enumerate(old):
                    candidate=str(text or '').strip()
                    original=str(mains[k][1] or '').strip() if 0<=k<len(mains) else ''
                    same=bool(candidate and re.sub(r'\s+','',candidate).casefold()==re.sub(r'\s+','',original).casefold())
                    if candidate and not same and not out[k]: out[k]=candidate
        except Exception: pass
    return out


def _h95f9_translation_coverage(owner, lyric=''):
    track=getattr(owner,'_h95_unified_track',None)
    lines=(track.get('lines') or []) if isinstance(track,dict) else []
    total=len(lines); aligned=sum(1 for line in lines if str(line.get('translation') or '').strip())
    source_rows=0
    try: source_rows=len(_h95f9_translation_rows(parse_lrc(str(lyric or ''),diagnostics=False)))
    except Exception: source_rows=0
    return int(total),int(aligned),int(source_rows)


def _h95f9_update_translation_status(panel, lyric=''):
    try:
        total,aligned,source_rows=_h95f9_translation_coverage(panel.lyric_window,lyric)
        if aligned>0:
            suffix=''
            if source_rows and source_rows<total:
                suffix=f' · 翻译源提供 {source_rows} 行'
            elif total and aligned<total:
                suffix=f' · {total-aligned} 行无安全对齐'
            panel.h95f5_translation_status.setText(f'双语翻译已就绪 · {aligned}/{total or aligned} 行{suffix}')
        return total,aligned,source_rows
    except Exception:
        return 0,0,0


def _h95f9_translation_result(panel,payload):
    out=_H95F9_TRANSLATION_RESULT_PRE(panel,payload) if callable(_H95F9_TRANSLATION_RESULT_PRE) else False
    try:
        lyric=str((payload or {}).get('lyric') or '') if isinstance(payload,dict) else ''
        total,aligned,source_rows=_h95f9_update_translation_status(panel,lyric)
        write_error_log('H95F9双语翻译覆盖',detail=(
            f'main={total} | source_rows={source_rows} | aligned={aligned} | missing={max(0,total-aligned)} | '
            f'policy=provider-only-no-fabrication'))
    except Exception: pass
    return out


def _h95f9_apply_cached_translation(panel):
    out=_H95F9_TRANSLATION_CACHE_PRE(panel) if callable(_H95F9_TRANSLATION_CACHE_PRE) else None
    try:
        identity,_,_=_h95f5_panel_identity_key(panel); row=getattr(panel,'_h95f5_translation_cache',{}).get(identity,{})
        _h95f9_update_translation_status(panel,str(row.get('lyric') or '') if isinstance(row,dict) else '')
    except Exception: pass
    return out


def _h95f9_release_envelope(row, now_ms=None):
    release=float(getattr(row,'_h62_decay_release_mono',0.0) or 0.0)
    if release<=0.0: return None
    now=float(time.monotonic()*1000.0 if now_ms is None else now_ms)
    duration=float(getattr(row,'_h76_blur_release_duration_ms',0.0) or 0.0)
    if duration<=0.0:
        duration=float(H95F9_EXIT_VISIBILITY_MIN_MS)
    duration=max(float(H95F9_EXIT_VISIBILITY_MIN_MS),duration)
    elapsed=max(0.0,now-release)
    if int(getattr(row,'_h62_decay_release_draw_count',0) or 0)<=0:
        elapsed=min(elapsed,max(16.0,float(globals().get('H59_EXIT_FIRST_FRAME_CATCHUP_MS',120.0) or 120.0)))
    q=max(0.0,min(1.0,elapsed/max(1.0,duration)))
    return q*q*(3.0-2.0*q)


def _h95f9_blur_progress(row,now_mono=None):
    p=float(_H95F9_BLUR_PROGRESS_PRE(row,now_mono)) if callable(_H95F9_BLUR_PROGRESS_PRE) else 0.0
    try:
        release=float(getattr(row,'_h62_decay_release_mono',0.0) or 0.0)
        env=_h95f9_release_envelope(row,now_mono) if release>0.0 else None
        _h95f9_mix_tls.exit_envelope=env
        _h95f9_mix_tls.row_id=id(row) if env is not None else None
        if env is not None:
            row._h95f9_exit_effect_progress=float(env)
            row._h95f9_material_progress=max(0.0,min(1.0,p))
            if not bool(getattr(row,'_h95f9_exit_decouple_logged',False)):
                row._h95f9_exit_decouple_logged=True
                write_error_log('H95F9退场效果进度解耦',detail=(
                    f'material_p0={float(getattr(row,"_h62_decay_release_progress",p) or p):.3f} | '
                    f'effect_p0=0.000 | direct_drop=0 | first-frame-guard=preserved'))
        return max(0.0,min(1.0,p))
    except Exception:
        try: _h95f9_mix_tls.exit_envelope=None; _h95f9_mix_tls.row_id=None
        except Exception: pass
        return max(0.0,min(1.0,p))


def _h95f9_blur_mix(progress):
    base=_H95F9_BLUR_MIX_PRE(progress) if callable(_H95F9_BLUR_MIX_PRE) else (1.0,0.0,0.0,1.0)
    try:
        bw,mw,xw,visibility=base
        env=getattr(_h95f9_mix_tls,'exit_envelope',None)
        if env is not None:
            # Residence depth/defocus remains continuous at its mature material progress,
            # while the actual exit visibility always owns a fresh 0->1 envelope.
            visibility=max(0.0,min(1.0,1.0-float(env)))
        return float(bw),float(mw),float(xw),float(visibility)
    except Exception:
        return base


def _h95f9_exit_progress(row):
    effect=_h70_effect_key(getattr(row,'exit_effect','fade')) if '_h70_effect_key' in globals() else str(getattr(row,'exit_effect','fade') or 'fade')
    if effect=='blur_decay':
        env=_h95f9_release_envelope(row)
        if env is not None: return max(0.0,min(1.0,float(env)))
    return _H95F9_EXIT_PROGRESS_PRE(row) if callable(_H95F9_EXIT_PROGRESS_PRE) else 0.0


def _h95f9_activate():
    try:
        if callable(_H95F9_ALIGN_PRE):
            globals()['_h95f5_align_translation_lines']=_h95f9_align_translation_lines
            _h95f9_align_translation_lines._limbus_layer='H95F9'
            _h95f9_align_translation_lines._limbus_policy='monotonic provider-row alignment; offset/drift rescue only; missing translations never fabricated'
        if callable(_H95F9_TRANSLATION_RESULT_PRE):
            globals()['_h95f5_translation_result']=_h95f9_translation_result
            _h95f9_translation_result._limbus_layer='H95F9'
        if callable(_H95F9_TRANSLATION_CACHE_PRE):
            globals()['_h95f5_apply_cached_translation']=_h95f9_apply_cached_translation
            _h95f9_apply_cached_translation._limbus_layer='H95F9'
        if callable(_H95F9_BLUR_PROGRESS_PRE):
            globals()['_h62_decay_progress']=_h95f9_blur_progress
            _h95f9_blur_progress._limbus_layer='H95F9'
            _h95f9_blur_progress._limbus_policy='material blur continuity + independent release envelope; no direct-drop semantics'
        if callable(_H95F9_BLUR_MIX_PRE):
            globals()['_h62_decay_mix']=_h95f9_blur_mix
            _h95f9_blur_mix._limbus_layer='H95F9'
        if callable(_H95F9_EXIT_PROGRESS_PRE):
            globals()['_h95f6_exit_progress']=_h95f9_exit_progress
            _h95f9_exit_progress._limbus_layer='H95F9'
    except Exception as exc:
        try: write_error_log('H95F9翻译对齐与退场连续性激活失败',exc)
        except Exception: pass


if '_h95f9_activate' in globals(): _h95f9_activate()

# H95F10 bilingual source lock + exit dirty closure + shell stability ----------------
# H95F9 improved translation alignment, but field behavior still exposed three ownership gaps:
# translation retrieval could borrow a different provider than the main payload; H72 terminal
# dirty cleanup predates the bilingual lane and therefore did not clear its final pixels; and the
# modern sync badge could churn through transient clock-source labels before the first lyric row.
# This layer closes those boundaries without changing player clock/seek authority.
H95F10_SYNC_BADGE_WIDTH = 86

_H95F10_H72_REGION_PRE = globals().get('_h72_held_visual_region')
_H95F10_FRONT_STATUS_PRE = getattr(ControlPanel, '_refresh_frontend_status', None) if 'ControlPanel' in globals() else None


def _h95f10_translation_retire_region(window, item):
    base = _H95F10_H72_REGION_PRE(window, item) if callable(_H95F10_H72_REGION_PRE) else QRegion()
    try:
        text = str(getattr(item, '_h95f5_translation', '') or '').strip()
        if not text:
            return base
        local = _h95f7_translation_local_rect(item, text, True) if '_h95f7_translation_local_rect' in globals() else QRectF()
        if local is None or local.isEmpty():
            return base
        lh = max(24.0, float(QFontMetrics(_h95f6_lane_font(
            item.font, getattr(item, '_h95f5_translation_scale_pct', H95F6_TRANSLATION_SCALE_DEFAULT)
        )).height()))
        region = window._map_visual_local_rect(
            local, getattr(item, 'persp_transform', QTransform()),
            float(getattr(item, 'x', 0.0) or 0.0), float(getattr(item, 'y', 0.0) or 0.0),
            bool(getattr(item, 'horizontal_wrap', False)), lh
        )
        if region is not None and not region.isEmpty():
            # Preserve this bilingual envelope for H72's terminal one-frame clear path.
            item._h95f10_translation_last_dirty_region = QRegion(region)
            item._h72_last_dirty_region = base.united(region) if base is not None and not base.isEmpty() else QRegion(region)
            return item._h72_last_dirty_region
        previous = getattr(item, '_h95f10_translation_last_dirty_region', None)
        if previous is not None and not previous.isEmpty():
            return base.united(previous) if base is not None and not base.isEmpty() else QRegion(previous)
    except Exception:
        pass
    return base


def _h95f10_frontend_status(panel, *args, **kwargs):
    out = _H95F10_FRONT_STATUS_PRE(panel, *args, **kwargs) if callable(_H95F10_FRONT_STATUS_PRE) else None
    try:
        badge = getattr(panel, 'front_sync_badge', None)
        if badge is None:
            return out
        state = panel.media_sync.snapshot() or {}
        status = str(state.get('status') or 'unknown')
        window = getattr(panel, 'lyric_window', None)
        visible_text = bool(str(getattr(window, 'full_text', '') or '').strip()) if window is not None else False
        visible_chars = int(getattr(window, 'char_index', 0) or 0) if window is not None else 0
        payload_ready = bool(str(panel.text_input.toPlainText() if hasattr(panel, 'text_input') else '').strip())
        # Before the first real lyric row, source arbitration can legitimately change several
        # times.  Do not expose that internal churn as a jumping badge; show one semantic state.
        if status in ('playing', 'paused') and not (visible_text and visible_chars > 0):
            if payload_ready:
                text = '等待歌词'
            else:
                text = '读取中'
            if status == 'paused':
                text += ' · 暂停'
            badge.setText(text)
        badge.setMinimumWidth(int(H95F10_SYNC_BADGE_WIDTH))
        badge.setMaximumWidth(max(int(H95F10_SYNC_BADGE_WIDTH), 96))
        badge.setAlignment(Qt.AlignCenter)
    except Exception:
        pass
    return out


def _h95f10_activate():
    try:
        if callable(_H95F10_H72_REGION_PRE):
            globals()['_h72_held_visual_region'] = _h95f10_translation_retire_region
            _h95f10_translation_retire_region._limbus_layer = 'H95F10'
            _h95f10_translation_retire_region._limbus_policy = 'terminal dirty cleanup unions bilingual lane; no translation ghost pixels'
        if 'ControlPanel' in globals() and callable(_H95F10_FRONT_STATUS_PRE):
            ControlPanel._refresh_frontend_status = _h95f10_frontend_status
            ControlPanel._refresh_frontend_status._limbus_layer = 'H95F10'
            ControlPanel._refresh_frontend_status._limbus_policy = 'pre-first-row semantic badge stability; player clock authority unchanged'
    except Exception as exc:
        try: write_error_log('H95F10双语同源与界面稳定层激活失败', exc)
        except Exception: pass


if '_h95f10_activate' in globals(): _h95f10_activate()


# H95F10F2 startup anchor + bilingual exit ownership + frame pacing -----------------
# Field logs from H95F10F1 exposed three presentation regressions that static release gates
# could not model: (1) the cold-start QQ rail escape hatch could accept one transient validated
# Text sample and jump the overlay far away before the Text stream settled; (2) the bilingual
# translation lane left the mature H70/H71/H76 exit renderer, then approximated its own per-char
# motion from the translation's character count; and (3) the secondary lane could synchronously
# rasterize high-DPI sprites in paintEvent while also scheduling a second full-song atlas.  This
# layer keeps player/provider authority unchanged, requires a coherent post-release sample cluster
# before a startup rail anchor, maps each translated glyph to the resolved PRIMARY glyph exit state,
# and uses cached vector batches until/without a translation atlas so paint never creates sprites.
H95F10F2_STARTUP_RAIL_CONFIRM_SAMPLES = 3
H95F10F2_STARTUP_RAIL_CONFIRM_SPAN_MS = 260.0
H95F10F2_STARTUP_RAIL_MAX_CLUSTER_MS = 2600.0
H95F10F2_STARTUP_RAIL_MAX_BACKSTEP_MS = 900.0
H95F10F2_TRANSLATION_ALPHA_BUCKETS = 32
H95F10F2_TRANSLATION_EXIT_PAD_PX = 96
H95F10F2_TRANSLATION_PATH_CACHE_MAX = 768
_H95F10F2_TRANSLATION_PATH_CACHE = OrderedDict()

_H95F10F2_QQ_PRELOCK_PRE = getattr(MediaSessionSync, '_qq_try_prelock_rail_validated_anchor', None) if 'MediaSessionSync' in globals() else None
_H95F10F2_TRANSLATION_ATLAS_PRE = globals().get('_h95f7_translation_atlas_shared')
_H95F10F2_ACTIVE_TRANSLATION_PRE = globals().get('_h95f7_draw_active_translation')
_H95F10F2_HISTORY_TRANSLATION_PRE = globals().get('_h95f7_draw_history_translation')
_H95F10F2_GROUP_TRANSFORM_PRE = globals().get('_h95f5_apply_history_group_transform')
_H95F10F2_HELD_REGION_PRE = getattr(LyricWindow, '_held_visual_region', None) if 'LyricWindow' in globals() else None
_H95F10F2_H72_REGION_PRE = globals().get('_h72_held_visual_region')


def _h95f10f2_qq_prelock_rail_anchor(self, ui, status):
    """Require a coherent post-release QQ Text cluster before cold-start rail takeover.

    A real rail seek settles into several duration-matched samples.  A hover/transition echo can
    momentarily agree with the cursor geometry once, which is exactly what the field log showed
    (125 s hint -> 123 s sample -> immediate return to 5/6/7 s).  Geometry remains intent only;
    this wrapper merely withholds the legacy commit until the validated Text stream is coherent.
    """
    if not callable(_H95F10F2_QQ_PRELOCK_PRE):
        return None
    try:
        source=str((ui or {}).get('source') or '')
        confidence=int((ui or {}).get('confidence') or 0)
        raw=(ui or {}).get('position_ms')
        duration=int((ui or {}).get('duration_ms') or 0)
        known=int(getattr(self,'_uia_duration_ms',0) or 0)
        now=time.monotonic()*1000.0
        release=float(getattr(self,'_qq_gesture_release_mono',0.0) or 0.0)
        gid=int(getattr(self,'_qq_gesture_id',0) or 0)
        expected_id=int(getattr(self,'_qq_gesture_expected_id',0) or 0)
        expected=getattr(self,'_qq_gesture_expected_ms',None)
        release_age=now-release if release>0.0 else 999999.0
        basic=bool(
            source=='qq-time-pair-validated' and confidence>=160 and raw is not None and
            duration>0 and known>0 and gid>0 and gid==expected_id and expected is not None and
            0.0<=release_age<=float(QQ_STARTUP_PRELOCK_RAIL_RELEASE_WINDOW_MS) and
            not bool((ui or {}).get('_qq_mouse_down'))
        )
        if not basic:
            if gid != int(getattr(self,'_h95f10f2_prelock_gid',0) or 0):
                self._h95f10f2_prelock_pending=None
            return None
        duration_tol=max(1800.0,float(known)*0.012)
        if abs(float(duration)-float(known))>duration_tol:
            self._h95f10f2_prelock_pending=None; return None
        observed=max(0.0,min(float(known),float(raw)+(420.0 if str(status or '')=='playing' else 0.0)))
        tol=max(float(QQ_STARTUP_PRELOCK_RAIL_MATCH_MIN_TOL_MS),min(float(QQ_STARTUP_PRELOCK_RAIL_MATCH_MAX_TOL_MS),float(known)*float(QQ_STARTUP_PRELOCK_RAIL_MATCH_RATIO)))
        if abs(observed-float(expected))>tol:
            self._h95f10f2_prelock_pending=None; return None
        pending=getattr(self,'_h95f10f2_prelock_pending',None)
        if not isinstance(pending,dict) or int(pending.get('gid',-1))!=gid:
            pending={'gid':gid,'samples':[],'started':now}; self._h95f10f2_prelock_pending=pending; self._h95f10f2_prelock_gid=gid
        samples=list(pending.get('samples') or [])
        if samples and observed < float(samples[-1][1])-float(H95F10F2_STARTUP_RAIL_MAX_BACKSTEP_MS):
            # A several-second backwards jump is not a settled post-seek stream. Restart the
            # cluster instead of letting the first matching hover/transition value become time.
            samples=[]; pending['started']=now
        samples.append((now,observed))
        samples=samples[-int(H95F10F2_STARTUP_RAIL_CONFIRM_SAMPLES):]
        pending['samples']=samples; self._h95f10f2_prelock_pending=pending
        if len(samples)<int(H95F10F2_STARTUP_RAIL_CONFIRM_SAMPLES):
            return None
        span=float(samples[-1][0])-float(samples[0][0]); values=[float(v) for _t,v in samples]
        cluster=max(values)-min(values)
        coherent=bool(span>=float(H95F10F2_STARTUP_RAIL_CONFIRM_SPAN_MS) and cluster<=float(H95F10F2_STARTUP_RAIL_MAX_CLUSTER_MS))
        if str(status or '')=='playing':
            coherent=bool(coherent and values[-1]>=values[0]-250.0)
        if not coherent:
            return None
        try:
            write_error_log('H95F10F2首锚Rail多样本确认',detail=(
                f'gesture={gid} | samples={len(samples)} | span={span:.0f}ms | '
                f'range={int(min(values))}-{int(max(values))}ms | hint={int(float(expected))}ms | commit=legacy-validated'))
        except Exception: pass
        out=_H95F10F2_QQ_PRELOCK_PRE(self,ui,status)
        if out is not None:
            self._h95f10f2_prelock_pending=None
        return out
    except Exception:
        return None


def _h95f10f2_translation_atlas_shared(window, schedule=True):
    """Translation never owns a second full-song atlas build.

    Reuse a cache hit if an earlier version/session already installed one, but do not schedule a
    new translated charset atlas.  The F2 vector batch path is bounded to visible rows and avoids
    poisoning the PRIMARY song-atlas performance fuse when a large CJK translation charset is slow.
    """
    try:
        if not callable(_H95F10F2_TRANSLATION_ATLAS_PRE): return None
        return _H95F10F2_TRANSLATION_ATLAS_PRE(window, False)
    except Exception:
        return None


def _h95f10f2_glyph_path(owner,font,fm,ch):
    # One process-wide immutable vector cache is cheaper than rebuilding the same glyph on every
    # history-row birth. QPainterPath is implicitly shared; callers only transform copies/maps.
    try:
        key=(QFont(font).toString(),str(ch))
        cache=_H95F10F2_TRANSLATION_PATH_CACHE
        hit=cache.get(key)
        if hit is not None:
            cache.move_to_end(key); return hit
        path=QPainterPath(); path.addText(0.0,float(fm.height())/3.0,QFont(font),str(ch))
        cache[key]=path; cache.move_to_end(key)
        while len(cache)>int(H95F10F2_TRANSLATION_PATH_CACHE_MAX): cache.popitem(last=False)
        return path
    except Exception:
        path=QPainterPath()
        try: path.addText(0.0,float(fm.height())/3.0,QFont(font),str(ch))
        except Exception: pass
        return path


def _h95f10f2_draw_path_groups(painter, owner, groups, *, font_owner=None):
    if not groups: return False
    target=font_owner if font_owner is not None else owner
    drawn=False
    for alpha_key,path in sorted(groups.items(),key=lambda kv:kv[0]):
        if path is None or path.isEmpty() or int(alpha_key)<=0: continue
        opacity=max(0.0,min(1.0,float(alpha_key)/255.0))
        _h95f6_draw_glyph_path(
            painter,path,
            fill=getattr(target,'text_color',getattr(target,'color',QColor('#ffffff'))),
            stroke=getattr(target,'stroke_color',QColor('#000000')),
            stroke_width=float(getattr(target,'stroke_width',0.45) or 0.45),
            outline=bool(getattr(target,'outline_enabled',True)),
            shadow=bool(getattr(target,'shadow_enabled',True)),
            shadow_color=getattr(target,'shadow_color',QColor('#000000')),
            glow=bool(getattr(target,'glow',False)),
            glow_color=getattr(target,'glow_color',QColor('#ffffff')),
            glow_size=float(getattr(target,'glow_size',0.0) or 0.0),
            glow_alpha=int(getattr(target,'glow_alpha',0) or 0),opacity=opacity)
        drawn=True
    return drawn


def _h95f10f2_alpha_bucket(alpha,buckets=H95F10F2_TRANSLATION_ALPHA_BUCKETS):
    a=max(0.0,min(1.0,float(alpha)))
    n=max(2,int(buckets)); return max(0,min(255,int(round(round(a*(n-1))/(n-1)*255.0))))


def _h95f10f2_primary_exit_order(row):
    text=str(getattr(row,'text','') or ''); n=max(1,len(text))
    key=(text,QFont(getattr(row,'font',QFont())).toString(),round(float(getattr(row,'spacing',5.0) or 5.0),3),tuple(round(float(x),3) for x in (getattr(row,'_glyph_cache_advances',[]) or [])[:len(text)]))
    cached=getattr(row,'_h95f10f2_primary_exit_order_cache',None)
    if isinstance(cached,tuple) and len(cached)==3 and cached[0]==key: return cached[1],cached[2]
    try:
        fm=QFontMetrics(QFont(row.font)); advances=[float(row._glyph_cache_advances[i]) if i<len(getattr(row,'_glyph_cache_advances',[]) or []) else float(fm.horizontalAdvance(ch)) for i,ch in enumerate(text)]
        scales=list(getattr(row,'glyph_scales',[]) or [1.0]*len(text))
        if '_audio_emphasis_cursor_offsets' in globals(): offsets=_audio_emphasis_cursor_offsets(advances,scales,float(getattr(row,'spacing',5.0) or 5.0))
        else:
            offsets=[]; c=0.0
            for a in advances: offsets.append(c); c+=a+float(getattr(row,'spacing',5.0) or 5.0)
        centers=[(float(offsets[i]) if i<len(offsets) else 0.0)+float(advances[i])*0.5 for i in range(len(text))]
        lo=min(centers,default=0.0); hi=max(centers,default=1.0); span=max(1.0,hi-lo)
        geom=[(centers[i]-lo)/span if i<len(centers) else float(i)/max(1.0,n-1.0) for i in range(len(text))]
    except Exception:
        geom=[float(i)/max(1.0,n-1.0) for i in range(len(text))]
    idx=list(range(n)); rng=random.Random(zlib.crc32(text.encode('utf-8')) & 0xffffffff); rng.shuffle(idx); scatter=[0.0]*n
    for pos,j in enumerate(idx): scatter[j]=float(pos)/max(1.0,n-1.0)
    row._h95f10f2_primary_exit_order_cache=(key,geom,scatter)
    return geom,scatter


def _h95f10f2_primary_glyph_exit_state(row, main_index):
    effect=_h70_effect_key(getattr(row,'exit_effect','fade')) if '_h70_effect_key' in globals() else str(getattr(row,'exit_effect','fade') or 'fade')
    p=max(0.0,min(1.0,float(_h95f6_exit_progress(row)))) if '_h95f6_exit_progress' in globals() else 0.0
