def _h95f10f2_apply_history_group_transform(row,painter):
    """Mirror the primary whole-row exit transforms; fragment effects are handled per glyph."""
    try:
        effect=_h70_effect_key(getattr(row,'exit_effect','fade')) if '_h70_effect_key' in globals() else str(getattr(row,'exit_effect','fade') or 'fade')
        if effect in ('per_char','wipe_ltr','wipe_rtl','instant'):
            transform=getattr(row,'persp_transform',None)
            if transform is not None and hasattr(transform,'isIdentity') and not transform.isIdentity(): painter.setTransform(transform,True)
            return
        p=max(0.0,min(1.0,float(_h95f6_exit_progress(row)))) if '_h95f6_exit_progress' in globals() else max(0.0,min(1.0,float(getattr(row,'_h16_exit_progress',0.0) or 0.0)))
        raw=float(_h70_row_flavor(row)) if '_h70_row_flavor' in globals() else 0.0
        # H71 is the outer flavor layer in the primary renderer.
        if raw>0.0001 and effect not in ('fade',):
            presence=float(_h71_presence(raw)) if '_h71_presence' in globals() else raw
            if effect=='shrink':
                q=max(0.0,min(1.0,p/0.34)); extra=float(H71_SHRINK_EXTRA_PRETENSION)*presence*math.sin(math.pi*q) if p<0.34 else 0.0
                if extra>0.0001: painter.translate(float(row.x),float(row.y)); painter.scale(1.0+extra,1.0+extra); painter.translate(-float(row.x),-float(row.y))
            elif effect=='soft_drift': painter.translate(0.0,float(H71_SOFT_EXTRA_GRAVITY_PX)*presence*(p**1.80))
            elif effect=='hop_drop':
                apex=0.30
                if p<=apex: q=p/apex; ey=-float(H71_HOP_EXTRA_UP_PX)*presence*math.sin(q*math.pi*0.5)
                else: q=(p-apex)/max(0.001,1.0-apex); ey=-float(H71_HOP_EXTRA_UP_PX)*presence*(1.0-q)+float(H71_HOP_EXTRA_DROP_PX)*presence*(q*q)
                painter.translate(0.0,ey); sign=-1.0 if _h70_seed_unit(row,0,97)<0.5 else 1.0; rot=sign*float(H71_HOP_EXTRA_ROT_DEG)*presence*math.sin(math.pi*p)
                if abs(rot)>0.01: painter.translate(float(row.x),float(row.y)); painter.rotate(rot); painter.translate(-float(row.x),-float(row.y))
            elif effect=='blur_decay':
                eased=_h51_smoothstep(p); exp=1.0+float(H71_BLUR_EXTRA_EXPAND)*presence*eased; painter.translate(float(row.x),float(row.y)); painter.scale(exp,exp); painter.translate(-float(row.x),-float(row.y))
        # H70 is the inner flavor layer.
        if raw>0.0001:
            if effect=='fade': painter.translate(0.0,-float(H70_FADE_RISE_MAX_PX)*raw*(1.0-(1.0-p)*(1.0-p)))
            elif effect=='shrink':
                q=max(0.0,min(1.0,p/0.34)); pre=float(H70_SHRINK_PRETENSION_MAX)*raw*math.sin(math.pi*q) if p<0.34 else 0.0
                if pre>0.0001: painter.translate(float(row.x),float(row.y)); painter.scale(1.0+pre,1.0+pre); painter.translate(-float(row.x),-float(row.y))
            elif effect=='soft_drift': painter.translate(0.0,float(H70_SOFT_GRAVITY_EXTRA_PX)*raw*(p**2.25))
            elif effect=='hop_drop':
                apex=0.30
                if p<=apex: q=p/apex; ey=-float(H70_HOP_EXTRA_UP_PX)*raw*math.sin(q*math.pi*0.5)
                else: q=(p-apex)/max(0.001,1.0-apex); ey=-float(H70_HOP_EXTRA_UP_PX)*raw*(1.0-q)+float(H70_HOP_EXTRA_DROP_PX)*raw*(q*q)
                painter.translate(0.0,ey); rs=max(0.0,(raw-0.55)/0.45)
                if rs>0.0:
                    sign=-1.0 if _h70_seed_unit(row,0,71)<0.5 else 1.0; rot=sign*3.0*rs*math.sin(math.pi*p); painter.translate(float(row.x),float(row.y)); painter.rotate(rot); painter.translate(-float(row.x),-float(row.y))
            elif effect=='blur_decay':
                eased=_h51_smoothstep(p); exp=1.0+float(H70_BLUR_DEPTH_EXPAND_MAX)*raw*eased; painter.translate(float(row.x),float(row.y)); painter.scale(exp,exp); painter.translate(-float(row.x),-float(row.y))
        # Mature baseline group motion.
        if effect=='shrink':
            eased=_h51_smoothstep(p); painter.translate(float(row.x),float(row.y)+5.0*eased); sc=1.0-0.16*eased; painter.scale(sc,sc); painter.translate(-float(row.x),-float(row.y))
        elif effect=='soft_drift':
            eased=_h51_smoothstep(p); painter.translate(0.0,7.0*eased); sc=1.0-0.018*eased; painter.translate(float(row.x),float(row.y)); painter.scale(sc,sc); painter.translate(-float(row.x),-float(row.y))
        elif effect=='hop_drop' and '_h59_hop_profile' in globals():
            try: dy,_=_h59_hop_profile(p); painter.translate(0.0,float(dy))
            except Exception: pass
        transform=getattr(row,'persp_transform',None)
        if transform is not None and hasattr(transform,'isIdentity') and not transform.isIdentity(): painter.setTransform(transform,True)
    except Exception:
        try:
            if callable(_H95F10F2_GROUP_TRANSFORM_PRE): _H95F10F2_GROUP_TRANSFORM_PRE(row,painter)
        except Exception: pass


def _h95f10f2_draw_active_translation(window,painter,text):
    text=str(text or '').strip(); main=str(getattr(window,'full_text','') or '')
    if not text or not main or int(getattr(window,'char_index',0) or 0)<=0: return False
    layout=_h95f7_translation_layout(window,text,False) if '_h95f7_translation_layout' in globals() else None
    if not layout: return False
    font,ox,oy,ax,ay,tsp,fm,advances=layout; plen=max(1,len(main)); slen=max(1,len(text)); revealed=max(0,min(plen,int(getattr(window,'char_index',0) or 0)))
    base_alpha=max(0.0,min(1.0,float(getattr(window,'line_alpha',1.0) or 0.0))) if getattr(window,'lyric_timeline',None) else 1.0
    shakes=getattr(window,'char_shakes',[]) or []; emph=getattr(window,'_audio_emphasis_latched_scales',[]) or []; groups={}; cursor=0.0
    for i,ch in enumerate(text):
        mi=_h95f6_main_index_for_secondary(i,slen,plen)
        if mi>=revealed: cursor+=advances[i]+tsp; continue
        alpha,mdx,mdy=_h95f6_primary_flow_state(window,mi,base_alpha); sx=sy=0.0
        try:
            if mi<len(shakes) and getattr(window,'_flow_mode','')!='intro-credit-soft': sx=float(shakes[mi].get('x',0) or 0); sy=float(shakes[mi].get('y',0) or 0)
        except Exception: pass
        scale=1.0
        try:
            if mi<len(emph): scale=max(1.0,min(float(AUDIO_EMPHASIS_ABSOLUTE_MAX_SCALE),float(emph[mi] or 1.0)))
        except Exception: pass
        base=_h95f10f2_glyph_path(window,font,fm,ch)
        if base is not None and not base.isEmpty() and not ch.isspace():
            gx=ox+ax*cursor+sx+mdx; gy=oy+ay*cursor+sy+mdy; tr=QTransform()
            if scale>1.001:
                br=base.boundingRect(); c=br.center(); by=br.bottom(); tr.translate(gx+c.x(),gy+by); tr.scale(scale,scale); tr.translate(-c.x(),-by)
            else: tr.translate(gx,gy)
            k=_h95f10f2_alpha_bucket(alpha); groups.setdefault(k,QPainterPath()).addPath(tr.map(base))
        cursor+=advances[i]+tsp
    painter.save()
    try:
        if bool(getattr(window,'perspective_enabled',False)): painter.setTransform(window.persp_transform,True)
        painter.translate(float(window.x),float(window.y))
        if '_h54_apply_active_depth_transform' in globals():
            try: _h54_apply_active_depth_transform(painter,window)
            except Exception: pass
        return _h95f10f2_draw_path_groups(painter,window,groups)
    finally: painter.restore()


def _h95f10f2_draw_history_translation(row,painter,text):
    text=str(text or '').strip(); main=str(getattr(row,'text','') or '')
    if not text or not main: return False
    effect=_h70_effect_key(getattr(row,'exit_effect','fade')) if '_h70_effect_key' in globals() else str(getattr(row,'exit_effect','fade') or 'fade')
    if effect!='blur_decay' and int(getattr(row,'alpha',0) or 0)<=0: return False
    layout=_h95f7_translation_layout(row,text,True) if '_h95f7_translation_layout' in globals() else None
    if not layout: return False
    font,ox,oy,ax,ay,tsp,fm,advances=layout; shakes=getattr(row,'char_shakes',[]) or []; groups={}; ghosts={}; cursor=0.0; plen=max(1,len(main)); slen=max(1,len(text))
    fragment=effect in ('per_char','wipe_ltr','wipe_rtl')
    whole_alpha=max(0.0,min(1.0,float(getattr(row,'alpha',255) or 0)/255.0))
    if effect=='blur_decay' and '_h62_decay_mix' in globals():
        try:
            p=max(0.0,min(1.0,float(_h95f6_exit_progress(row)))); _bw,_mw,_xw,whole_alpha=_h62_decay_mix(p)
        except Exception: whole_alpha=1.0
    for i,ch in enumerate(text):
        mi=_h95f6_main_index_for_secondary(i,slen,plen); sx=sy=0.0
        try:
            if mi<len(shakes): sx=float(shakes[mi].get('x',0) or 0); sy=float(shakes[mi].get('y',0) or 0)
        except Exception: pass
        if fragment: alpha,dx,dy,scale,rotation,ghost=_h95f10f2_primary_glyph_exit_state(row,mi)
        else: alpha,dx,dy,scale,rotation,ghost=whole_alpha,0.0,0.0,1.0,0.0,[]
        base=_h95f10f2_glyph_path(row,font,fm,ch)
        if base is not None and not base.isEmpty() and not ch.isspace():
            gx=ox+ax*cursor+sx+dx; gy=oy+ay*cursor+sy+dy; br=base.boundingRect(); c=br.center(); by=br.bottom(); tr=QTransform(); tr.translate(gx+c.x(),gy+by); tr.rotate(float(rotation)); tr.scale(float(scale),float(scale)); tr.translate(-c.x(),-by); face=tr.map(base)
            k=_h95f10f2_alpha_bucket(alpha); groups.setdefault(k,QPainterPath()).addPath(face)
            for ga,gdx,gdy,gscale,grot in ghost:
                gt=QTransform(); gt.translate(float(gdx),float(gdy)); gt.translate(gx+c.x(),gy+by); gt.rotate(float(grot)); gt.scale(float(gscale),float(gscale)); gt.translate(-c.x(),-by); gk=_h95f10f2_alpha_bucket(ga,8); ghosts.setdefault(gk,QPainterPath()).addPath(gt.map(base))
        cursor+=advances[i]+tsp
    painter.save()
    try:
        _h95f10f2_apply_history_group_transform(row,painter); painter.translate(float(row.x),float(row.y))
        drawn=_h95f10f2_draw_path_groups(painter,row,ghosts,font_owner=row)
        return bool(_h95f10f2_draw_path_groups(painter,row,groups,font_owner=row) or drawn)
    finally: painter.restore()


def _h95f10f2_expand_translation_region(window,item,base):
    try:
        text=str(getattr(item,'_h95f5_translation','') or '').strip()
        if not text: return base
        local=_h95f7_translation_local_rect(item,text,True)
        if local is None or local.isEmpty(): return base
        pad=int(H95F10F2_TRANSLATION_EXIT_PAD_PX)
        local=local.adjusted(-pad,-pad,pad,pad)
        lh=max(24.0,float(QFontMetrics(_h95f6_lane_font(item.font,getattr(item,'_h95f5_translation_scale_pct',H95F6_TRANSLATION_SCALE_DEFAULT))).height()))
        reg=window._map_visual_local_rect(local,getattr(item,'persp_transform',QTransform()),float(getattr(item,'x',0.0) or 0.0),float(getattr(item,'y',0.0) or 0.0),bool(getattr(item,'horizontal_wrap',False)),lh)
        return base.united(reg) if base is not None and not base.isEmpty() else QRegion(reg)
    except Exception: return base


def _h95f10f2_held_visual_region(window,item):
    base=_H95F10F2_HELD_REGION_PRE(window,item) if callable(_H95F10F2_HELD_REGION_PRE) else QRegion()
