# Release UI closure: palette + UI-scale composition ---------------------------------
# Field report: changing H12 UI scale while Classic/rose was active reapplied the
# historical base stylesheet, visually switching the shell back to Studio/forest.
# Switching the palette again then reapplied an unscaled stylesheet, undoing the chosen
# scale. Keep the existing H12/H87/H95 owners intact; compose their final stylesheet in
# one last presentation-only adapter. No player/provider/lyric/render ownership changes.
_R3_THEME_SCALE_SCALE_PRE = globals().get('_h12_apply_scale')
_R3_THEME_SCALE_THEME_PRE = globals().get('_h87_apply_frontend_theme')


def _r3_scale_stylesheet(css, factor):
    text = str(css or '')
    factor = max(0.5, min(2.0, float(factor or 1.0)))
    if not text or abs(factor - 1.0) < 0.0001:
        return text
    props = r'(font-size|padding(?:-(?:left|right|top|bottom))?|margin(?:-(?:left|right|top|bottom))?|min-width|max-width|min-height|max-height|border-radius)'
    def repl(match):
        return f'{match.group(1)}: {max(1, round(float(match.group(2)) * factor))}px'
    return re.sub(props + r'\s*:\s*([0-9]+(?:\.[0-9]+)?)px', repl, text)


def _r3_apply_scaled_active_theme(panel):
    if not hasattr(panel, '_h87_frontend_theme'):
        return
    theme = 'classic' if str(getattr(panel, '_h87_frontend_theme', 'studio')).lower() == 'classic' else 'studio'
    if callable(_R3_THEME_SCALE_THEME_PRE):
        _R3_THEME_SCALE_THEME_PRE(panel, theme, False)
    unscaled = str(panel.styleSheet() or '')
    panel._r3_unscaled_theme_stylesheet = unscaled
    pct = max(50, min(200, int(getattr(panel, '_h12_ui_scale_pct', 100) or 100)))
    panel.setStyleSheet(_r3_scale_stylesheet(unscaled, pct / 100.0))


def _r3_apply_scale_preserve_theme(panel, pct):
    if bool(getattr(panel, '_r3_theme_scale_guard', False)):
        return _R3_THEME_SCALE_SCALE_PRE(panel, pct) if callable(_R3_THEME_SCALE_SCALE_PRE) else None
    panel._r3_theme_scale_guard = True
    try:
        out = _R3_THEME_SCALE_SCALE_PRE(panel, pct) if callable(_R3_THEME_SCALE_SCALE_PRE) else None
        _r3_apply_scaled_active_theme(panel)
        return out
    finally:
        panel._r3_theme_scale_guard = False


def _r3_apply_theme_preserve_scale(panel, theme=None, save=False):
    if bool(getattr(panel, '_r3_theme_scale_guard', False)):
        return _R3_THEME_SCALE_THEME_PRE(panel, theme, save) if callable(_R3_THEME_SCALE_THEME_PRE) else None
    panel._r3_theme_scale_guard = True
    try:
        out = _R3_THEME_SCALE_THEME_PRE(panel, theme, save) if callable(_R3_THEME_SCALE_THEME_PRE) else None
        unscaled = str(panel.styleSheet() or '')
        panel._r3_unscaled_theme_stylesheet = unscaled
        pct = max(50, min(200, int(getattr(panel, '_h12_ui_scale_pct', 100) or 100)))
        panel.setStyleSheet(_r3_scale_stylesheet(unscaled, pct / 100.0))
        return out
    finally:
        panel._r3_theme_scale_guard = False


def _r3_activate_theme_scale_composition():
    try:
        if callable(_R3_THEME_SCALE_SCALE_PRE):
            globals()['_h12_apply_scale'] = _r3_apply_scale_preserve_theme
            _r3_apply_scale_preserve_theme._limbus_layer = 'R3-THEME-SCALE'
        if callable(_R3_THEME_SCALE_THEME_PRE):
            globals()['_h87_apply_frontend_theme'] = _r3_apply_theme_preserve_scale
            _r3_apply_theme_preserve_scale._limbus_layer = 'R3-THEME-SCALE'
    except Exception as exc:
        try: write_error_log('界面缩放与配色组合层激活失败', exc)
        except Exception: pass


