# Release last-mile R6: recording-friendly render admission + QQ precise-duration proof ----
# Field evidence from a long recording session showed two independent issues:
#   * the GUI event loop can occasionally miss a 40-200ms tick while background render work is
#     available, even though paint/provider calls themselves remain fast;
#   * QQ can prove the *new* track duration by an advancing mm:ss pair, yet the lyric worker may
#     still reject the same numeric duration because it equals a pre-bind witness. That leaves
#     provider_duration_ms=0 and can discard an otherwise exact-duration KuGou KRC candidate.
# Keep all mature clock/search/render formulas byte-identical. This final adapter only (1) turns a
# measured late GUI tick into the scheduler's existing bounded speculative-work quiet latch, and
# (2) admits QQ's explicit post-bind duration_self_proved evidence for lyric-version selection.
R6_GUI_LATE_MIN_MS = 40.0
R6_GUI_LATE_IGNORE_AFTER_MS = 750.0
R6_GUI_QUIET_BASE_MS = 520.0
R6_GUI_QUIET_MAX_MS = 1200.0
R6_QQ_SELF_PROOF_WAIT_MS = 420.0
R6_QQ_SELF_PROOF_POLL_MS = 55.0

_R6_CHECK_LYRIC_PRE = LyricWindow.check_lyric_time if 'LyricWindow' in globals() else None
_R6_QQ_DURATION_PRE = ControlPanel._resolve_qq_auto_track_duration_after_bind if 'ControlPanel' in globals() else None
_R6_OBS_TICK_PRE = H13ObsLyricMirror._tick if 'H13ObsLyricMirror' in globals() else None


def _r6_job_track_key(panel, job):
    try:
        key = str((job or {}).get('key') or '')
        if key:
            return key
        return str(panel._track_identity((job or {}).get('song', ''), (job or {}).get('artist', '')) or '')
    except Exception:
        return ''


def _r6_qq_postbind_self_proved_duration(panel, job, cancel_check=None):
    """Return QQ duration only after the UIA adapter explicitly proves new-track advance.

    ``duration_self_proved`` is emitted by QQMusicUiAdapter only after the per-track adapter has
    been reset and its mm:ss pair advances with the player's wall clock. Requiring the currently
    bound MediaSessionSync track key and metadata identity as well prevents an old control value
    from becoming a cross-track lyric-version witness merely because two songs share a duration.
    """
    try:
        if str((job or {}).get('source') or '') != 'QQ音乐':
            return 0
        sync = getattr(panel, 'media_sync', None)
        reader = getattr(sync, '_uia_reader', None) if sync is not None else None
        if sync is None or reader is None or not hasattr(reader, 'poll'):
            return 0
        wanted_key = _r6_job_track_key(panel, job)
        bound_key = str(getattr(sync, '_track_key', '') or '')
        if wanted_key and bound_key and wanted_key != bound_key:
            return 0
        snap = sync.snapshot() or {}
        media_title = str(snap.get('media_title') or '').strip()
        media_artist = str(snap.get('media_artist') or '').strip()
        media_source = str(snap.get('media_source') or '')
        if media_title and sync._source_matches_process_hint(media_source, 'qqmusic.exe'):
            if not panel._same_track((job or {}).get('song', ''), (job or {}).get('artist', ''), media_title, media_artist):
                return 0
        deadline = time.monotonic() + float(R6_QQ_SELF_PROOF_WAIT_MS) / 1000.0
        while time.monotonic() <= deadline:
            if callable(cancel_check) and bool(cancel_check()):
                return 0
            # Track ownership can change while the bounded worker wait is in flight.
            current_key = str(getattr(sync, '_track_key', '') or '')
            if wanted_key and current_key and wanted_key != current_key:
                return 0
            row = reader.poll('qqmusic.exe') or {}
            duration = int(row.get('duration_ms') or 0)
            position = row.get('position_ms')
            source = str(row.get('source') or '')
            if (
                duration > 0 and source == 'qq-time-pair-validated' and
                bool(row.get('duration_self_proved')) and position is not None
            ):
                try:
                    position = int(position)
                except Exception:
                    position = -1
                if position >= 0:
                    try:
                        write_error_log('R6 QQ新曲推进自证时长接管', detail=(
                            f'song={(job or {}).get("song","")} | artist={(job or {}).get("artist","")} | '
                            f'duration={duration}ms | position={position}ms | track={wanted_key or current_key or "<none>"} | '
                            'role=lyric-version-witness | seek/clock=unchanged'))
                    except Exception:
                        pass
                    return duration
            time.sleep(float(R6_QQ_SELF_PROOF_POLL_MS) / 1000.0)
    except Exception:
        pass
    return 0


def _r6_resolve_qq_duration(panel, job, cancel_check=None):
    out = int(_R6_QQ_DURATION_PRE(panel, job, cancel_check=cancel_check) or 0) if callable(_R6_QQ_DURATION_PRE) else 0
    if out > 0 or str((job or {}).get('source') or '') != 'QQ音乐':
        return out
    proved = int(_r6_qq_postbind_self_proved_duration(panel, job, cancel_check=cancel_check) or 0)
    return proved if proved > 0 else out


def _r6_check_lyric_time(window, *args, **kwargs):
    # Set the existing H95F10F14 speculative-work latch *before* the mature tick runs, so any
    # N+1/N+2 work considered later in this same tick yields immediately. Current/visible work is
    # priority <=1 in that scheduler and therefore remains admitted.
    try:
        now = time.monotonic() * 1000.0
        prev = getattr(window, '_last_check_mono', None)
        if prev is not None and bool(getattr(window, 'lyric_timeline', None)):
            gap = max(0.0, now - float(prev))
            if float(R6_GUI_LATE_MIN_MS) <= gap <= float(R6_GUI_LATE_IGNORE_AFTER_MS):
                quiet_ms = min(float(R6_GUI_QUIET_MAX_MS), max(float(R6_GUI_QUIET_BASE_MS), gap * 3.0))
                quiet_until = now + quiet_ms
                window._speculative_render_quiet_until_mono = max(
                    float(getattr(window, '_speculative_render_quiet_until_mono', 0.0) or 0.0), quiet_until)
                window._r6_gui_late_quiet_count = int(getattr(window, '_r6_gui_late_quiet_count', 0) or 0) + 1
                last_log = float(getattr(window, '_r6_gui_late_quiet_log_mono', 0.0) or 0.0)
                if gap >= 80.0 and now - last_log >= 2500.0:
                    window._r6_gui_late_quiet_log_mono = now
                    try:
                        write_error_log('R6 GUI晚帧推测预热静默', detail=(
                            f'gap={gap:.1f}ms | quiet={int(quiet_ms)}ms | current-visible=unchanged | '
                            'neighbor/future=yield'))
                    except Exception:
                        pass
    except Exception:
        pass
    return _R6_CHECK_LYRIC_PRE(window, *args, **kwargs) if callable(_R6_CHECK_LYRIC_PRE) else None



def _r6_obs_mirror_tick(mirror):
    # The OBS mirror is itself a GUI-thread QWidget grab. If the main lyric event loop has just
    # missed a frame, copying another frame immediately only deepens the backlog. Drop mirror
    # refreshes during the same bounded quiet window; OBS keeps the previous valid frame while the
    # real lyric window catches up, then normal 20 Hz mirroring resumes automatically.
    try:
        source = getattr(mirror, 'source_window', None)
        quiet_until = float(getattr(source, '_speculative_render_quiet_until_mono', 0.0) or 0.0) if source is not None else 0.0
        if time.monotonic() * 1000.0 < quiet_until:
            mirror._r6_skipped_capture_frames = int(getattr(mirror, '_r6_skipped_capture_frames', 0) or 0) + 1
            return None
    except Exception:
        pass
    return _R6_OBS_TICK_PRE(mirror) if callable(_R6_OBS_TICK_PRE) else None

def _r6_activate_release_last_mile():
    try:
        if callable(_R6_QQ_DURATION_PRE):
            old_layer = str(getattr(_R6_QQ_DURATION_PRE, '_limbus_layer', '') or 'H95F10F6')
            ControlPanel._resolve_qq_auto_track_duration_after_bind = _r6_resolve_qq_duration
            _r6_resolve_qq_duration._limbus_layer = old_layer
            _r6_resolve_qq_duration._r6_postbind_self_proof = True
        if callable(_R6_CHECK_LYRIC_PRE):
            old_layer = str(getattr(_R6_CHECK_LYRIC_PRE, '_limbus_layer', '') or 'H33')
            old_residency = getattr(_R6_CHECK_LYRIC_PRE, '_limbus_qq_residency', None)
            LyricWindow.check_lyric_time = _r6_check_lyric_time
            _r6_check_lyric_time._limbus_layer = old_layer
            if old_residency is not None:
                _r6_check_lyric_time._limbus_qq_residency = old_residency
            _r6_check_lyric_time._r6_recording_quiet = True
        if callable(_R6_OBS_TICK_PRE):
            H13ObsLyricMirror._tick = _r6_obs_mirror_tick
            _r6_obs_mirror_tick._r6_late_frame_drop = True
        try:
            write_error_log('R6发布末端稳定层激活', detail=(
                'gui-late=speculative-quiet-only+obs-mirror-drop | current-visible=unchanged | '
                'qq-duration=postbind-duration-self-proved | provider/search/clock/seek/formulas=unchanged'))
        except Exception:
            pass
    except Exception as exc:
        try: write_error_log('R6发布末端稳定层激活失败', exc)
        except Exception: pass


_r6_activate_release_last_mile()


