# Switch latency + recording stability R7 ------------------------------------------
# Field logs show that first-screen ordinary lyrics are still delayed by serial foreign
# provider probing after QQ search failures, while song-atlas construction often spends
# 200-400ms immediately around a track handoff.  R7 changes scheduling only:
#   * the QQ auto fast stage races at most two mature ordinary-provider searches and returns
#     the first usable payload; the existing duration/version validator still decides whether
#     that payload may be shown, and precise search remains on the mature path;
#   * a new lyric session briefly defers whole-song Atlas construction and speculative
#     neighbour work so the current visible row owns the CPU/GIL during the handoff.
# Provider parsers, precision verification, player clock/seek authority, and render formulas
# remain unchanged.
R7_FAST_RACE_ENABLED = True
R7_FAST_RACE_PROVIDERS_OPEN = ('网易云', '酷狗')
R7_FAST_RACE_PROVIDERS_CLOSED = ('QQ音乐', '网易云')
R7_SWITCH_ATLAS_QUIET_MS = 920.0
R7_SWITCH_SPECULATIVE_QUIET_MS = 240.0

_R7_ATLAS_SCHEDULE_PRE = LyricWindow._schedule_song_fragment_atlas if 'LyricWindow' in globals() else None
_R7_ACTUALLY_START_PRE = LyricWindow._actually_start if 'LyricWindow' in globals() else None


def _r7_qq_search_breaker_open():
    try:
        breaker = globals().get('_R2_QQ_SEARCH_BREAKER')
        if breaker is None:
            return False
        snap = breaker.snapshot('qq-search') or {}
        return int(snap.get('retry_after_ms') or 0) > 0
    except Exception:
        return False


def _r7_fast_provider_probe(song_name, artist, provider, cancel_check=None,
                            provider_track_id=None, provider_duration_ms=0,
                            original_source='QQ音乐'):
    """Run one mature ordinary provider path without cross-provider fallback."""
    try:
        if callable(cancel_check) and bool(cancel_check()):
            return None
        LyricSearchEngine._set_cancel_check(cancel_check)
        # The original player's provider identity is forwarded only to that same provider.
        # Foreign racers stay title/artist based and cannot inherit a QQ/NetEase native ID.
        use_native_id = provider_track_id if str(provider) == str(original_source) else None
        use_duration = int(provider_duration_ms or 0) if str(provider) == str(original_source) else 0
        lyric, duration = _H95F10F8_SEARCH_PRE(
            song_name, artist, provider, False,
            provider_track_id=use_native_id, provider_duration_ms=use_duration,
            prefer_precise=False, provider_locked=True,
            require_translation_pair=False,
        ) if callable(_H95F10F8_SEARCH_PRE) else (None, 0)
        meta = LyricSearchEngine.last_provider_meta() or {}
        err = str(LyricSearchEngine.last_error or '')
        if callable(cancel_check) and bool(cancel_check()):
            return None
        if not lyric:
            return {'provider': provider, 'lyric': None, 'duration': int(duration or 0), 'meta': dict(meta), 'error': err}
        meta = dict(meta or {})
        meta['lyric_payload_source'] = str(meta.get('lyric_payload_source') or provider)
        meta['r7_fast_payload_provider'] = provider
        meta['r7_fast_presentation_only'] = True
        return {
            'provider': provider, 'lyric': lyric, 'duration': int(duration or 0),
            'meta': meta, 'error': '', 'quality': int(_lyric_clock_quality(lyric)),
        }
    except Exception as exc:
        return {'provider': provider, 'lyric': None, 'duration': 0, 'meta': {}, 'error': f'{type(exc).__name__}: {exc}'}
    finally:
        try: LyricSearchEngine._set_cancel_check(None)
        except Exception: pass


def _r7_fast_auto_search_impl(song_name, artist='', source='网易云', trans_only=False,
                              provider_track_id=None, provider_duration_ms=0, prefer_precise=True,
                              provider_locked=False, require_translation_pair=False):
    """Return (lyric, duration) only for the bounded QQ auto ordinary race, else None.

    This helper is called from the already-existing H95F10F8 search layer, so R7 does not add
    another search monkeypatch.  The caller's mature fast-stage duration/version validator stays
    authoritative; foreign results here are presentation candidates only.
    """
    auto_thread = str(threading.current_thread().name or '').startswith('LimbusLyric-AutoLyrics-g')
    eligible = bool(
        R7_FAST_RACE_ENABLED and auto_thread and str(source or '') == 'QQ音乐' and
        not bool(trans_only) and not bool(prefer_precise) and not bool(provider_locked) and
        not bool(require_translation_pair)
    )
    if not eligible or not callable(_H95F10F8_SEARCH_PRE):
        return None

    parent_cancel = getattr(getattr(LyricSearchEngine, '_cancel_local', None), 'fn', None)
    providers = tuple(R7_FAST_RACE_PROVIDERS_OPEN if _r7_qq_search_breaker_open() else R7_FAST_RACE_PROVIDERS_CLOSED)
    started = time.monotonic()
    race_stop = threading.Event()

    def race_cancelled():
        return bool(race_stop.is_set() or (callable(parent_cancel) and bool(parent_cancel())))

    executor = concurrent.futures.ThreadPoolExecutor(max_workers=len(providers), thread_name_prefix='LimbusLyric-R7Fast')
    futures = {
        executor.submit(
            _r7_fast_provider_probe, song_name, artist, provider, race_cancelled,
            provider_track_id, provider_duration_ms, source): provider
        for provider in providers
    }
    errors = []
    winner = None
    winner_future = None
    try:
        for future in concurrent.futures.as_completed(futures):
            if callable(parent_cancel) and bool(parent_cancel()):
                break
            try:
                row = future.result()
            except Exception as exc:
                row = {'provider': futures.get(future, ''), 'lyric': None, 'error': f'{type(exc).__name__}: {exc}'}
            if isinstance(row, dict) and row.get('lyric'):
                winner = row
                winner_future = future
                race_stop.set()
                break
            if isinstance(row, dict) and row.get('error'):
                errors.append(f'{row.get("provider","?")}:{row.get("error","")}')
    finally:
        race_stop.set()
        for fut in futures:
            if fut is not winner_future:
                try: fut.cancel()
                except Exception: pass
        try: executor.shutdown(wait=False, cancel_futures=True)
        except Exception: pass

    if winner is not None:
        try:
            LyricSearchEngine._set_provider_meta(**dict(winner.get('meta') or {}))
            LyricSearchEngine.last_error = ''
            write_error_log('R7切歌普通歌词竞速命中', detail=(
                f'song={song_name} | payload={winner.get("provider","")} | '
                f'duration={int(winner.get("duration") or 0)} | quality={int(winner.get("quality") or 0)} | '
                f'elapsed={int((time.monotonic()-started)*1000.0)}ms | '
                f'qq-breaker-open={int(_r7_qq_search_breaker_open())} | version-validator=unchanged'))
        except Exception:
            pass
        return winner.get('lyric'), int(winner.get('duration') or 0)

    # All racers missed or failed. Preserve the mature full search semantics. Because this helper
    # calls the predecessor of F8 and the request is ordinary (prefer_precise=False), this is the
    # same mature result F8 would have returned after its no-op ordinary branch.
    try:
        if errors:
            write_error_log('R7切歌普通歌词竞速未命中', detail=(
                f'song={song_name} | providers={providers} | errors={errors[:2]} | fallback=mature-search'))
    except Exception:
        pass
    return _H95F10F8_SEARCH_PRE(
        song_name, artist, source, trans_only,
        provider_track_id=provider_track_id, provider_duration_ms=provider_duration_ms,
        prefer_precise=prefer_precise, provider_locked=provider_locked,
        require_translation_pair=require_translation_pair,
    )

def _r7_resume_song_atlas(window):
    try:
        window._r7_atlas_resume_armed = False
        if not bool(getattr(window, 'lyric_timeline', None)):
            return
        now = time.monotonic() * 1000.0
        quiet_until = max(
            float(getattr(window, '_r7_switch_atlas_quiet_until_mono', 0.0) or 0.0),
            float(getattr(window, '_speculative_render_quiet_until_mono', 0.0) or 0.0),
        )
        if now < quiet_until:
            delay = max(25, int(quiet_until - now) + 12)
            window._r7_atlas_resume_armed = True
            QTimer.singleShot(delay, lambda w=window: _r7_resume_song_atlas(w))
            return
        if callable(_R7_ATLAS_SCHEDULE_PRE):
            _R7_ATLAS_SCHEDULE_PRE(window)
    except Exception:
        try: window._r7_atlas_resume_armed = False
        except Exception: pass


def _r7_schedule_song_fragment_atlas(window, visual_style=None, prewarm_only=False):
    try:
        now = time.monotonic() * 1000.0
        quiet_until = max(
            float(getattr(window, '_r7_switch_atlas_quiet_until_mono', 0.0) or 0.0),
            float(getattr(window, '_speculative_render_quiet_until_mono', 0.0) or 0.0),
        )
        if now < quiet_until:
            window._song_fragment_atlas_deferred = True
            if not bool(getattr(window, '_r7_atlas_resume_armed', False)):
                window._r7_atlas_resume_armed = True
                delay = max(25, int(quiet_until - now) + 12)
                QTimer.singleShot(delay, lambda w=window: _r7_resume_song_atlas(w))
            return 'r7-switch-deferred'
    except Exception:
        pass
    return _R7_ATLAS_SCHEDULE_PRE(window, visual_style=visual_style, prewarm_only=prewarm_only) if callable(_R7_ATLAS_SCHEDULE_PRE) else None


def _r7_actually_start(window, *args, **kwargs):
    try:
        now = time.monotonic() * 1000.0
        window._r7_switch_atlas_quiet_until_mono = now + float(R7_SWITCH_ATLAS_QUIET_MS)
        # Only speculative neighbour/future work yields here. Current/visible rows remain
        # priority <=1 and keep the same sprite/vector fallback and effect formulas.
        window._speculative_render_quiet_until_mono = max(
            float(getattr(window, '_speculative_render_quiet_until_mono', 0.0) or 0.0),
            now + float(R7_SWITCH_SPECULATIVE_QUIET_MS),
        )
    except Exception:
        pass
    return _R7_ACTUALLY_START_PRE(window, *args, **kwargs) if callable(_R7_ACTUALLY_START_PRE) else None


def _r7_activate_switch_latency_recording_stability():
    try:
        # Search routing is consolidated inside _h95f10f8_search to stay within the
        # reviewed patch-debt budget; do not add another LyricSearchEngine.search layer here.
        _r7_fast_auto_search_impl._limbus_layer = 'R7-fast-first-screen-consolidated'
        if callable(_R7_ATLAS_SCHEDULE_PRE):
            setattr(LyricWindow, '_schedule_song_fragment_atlas', _r7_schedule_song_fragment_atlas)
            _r7_schedule_song_fragment_atlas._limbus_layer = 'R7-switch-atlas-admission'
        if callable(_R7_ACTUALLY_START_PRE):
            setattr(LyricWindow, '_actually_start', _r7_actually_start)
            _r7_actually_start._limbus_layer = 'R7-switch-visible-first'
        try:
            write_error_log('R7切歌首屏与录屏稳定层激活', detail=(
                'fast=bounded-provider-race+existing-duration-validator | '
                'switch=atlas-defer920ms+speculative-quiet240ms | current-visible=unchanged | '
                'precise/provider-parser/clock/seek/effects=unchanged'))
        except Exception:
            pass
    except Exception as exc:
        try: write_error_log('R7切歌首屏与录屏稳定层激活失败', exc)
        except Exception: pass



_r7_activate_switch_latency_recording_stability()


# Variable-font stability + shared frame pacing R8 -----------------------------------------
# Field logs with H51 per-line size ranges show two distinct costs:
#   1) a whole-song Atlas can take hundreds of milliseconds even though its single font size
#      cannot be reused by rows that deliberately choose different point sizes;
#   2) held rows keep advancing per-glyph shake on every visual tick, so adding a newborn row
#      can make already-read text visibly wander and also creates avoidable Python work.
# R8 keeps current-row effects and all player/provider clocks untouched.  Variable-size mode
# uses row-scoped material only; held rows freeze their birth geometry.  In ordinary fixed-size
# mode, held-row motion remains mature behavior but yields during a recent GUI-late window and
# is capped to a secondary cadence when several resident rows are present.  This is renderer
# policy shared by QQ/NetEase/KuGou/Spotify/custom-player paths.
R8_HISTORY_SECONDARY_INTERVAL_MS = 30.0
R8_VARIABLE_SIZE_ROW_ONLY = True
R8_VARIABLE_SIZE_FREEZE_HELD = True

_R8_ATLAS_SCHEDULE_PRE = getattr(LyricWindow, '_schedule_song_fragment_atlas', None) if 'LyricWindow' in globals() else None
_R8_SHARED_ATLAS_PRE = getattr(LyricWindow, '_shared_song_fragment_atlas', None) if 'LyricWindow' in globals() else None
_R8_HOLD_PRE = getattr(FadingLine, 'update_hold', None) if 'FadingLine' in globals() else None


def _r8_variable_size_mode(window):
    try:
        if not bool(getattr(window, '_h51_size_range_enabled', False)):
            return False
        lo = int(getattr(window, '_h51_font_min_pt', 0) or 0)
        hi = int(getattr(window, '_h51_font_max_pt', lo) or lo)
        return bool(lo > 0 and hi > 0 and lo != hi)
    except Exception:
        return False


def _r8_force_row_material_mode(window):
    """Cancel wasteful song-wide material work; H61 then supplies row-scoped Atlas material."""
    try:
        window._song_fragment_atlas_desired_key = None
        window._song_fragment_atlas_pending_key = None
        window._song_fragment_atlas_deferred = False
        window._song_fragment_atlas_performance_fused = True
        window._song_fragment_atlas_fuse_reason = 'r8-variable-size-row-only'
        window._song_fragment_atlas_fused_style_sig = None
        window._song_fragment_atlas_fuse_until_mono = time.monotonic() * 1000.0 + 86400000.0
        return True
    except Exception:
        return False


def _r8_schedule_song_fragment_atlas(window, visual_style=None, prewarm_only=False):
    if bool(R8_VARIABLE_SIZE_ROW_ONLY) and _r8_variable_size_mode(window):
        _r8_force_row_material_mode(window)
        return 'r8-variable-size-row-only'
    try:
        if str(getattr(window, '_song_fragment_atlas_fuse_reason', '') or '') == 'r8-variable-size-row-only':
            window._song_fragment_atlas_performance_fused = False
            window._song_fragment_atlas_fuse_reason = ''
            window._song_fragment_atlas_fused_style_sig = None
            window._song_fragment_atlas_fuse_until_mono = 0.0
    except Exception:
        pass
    return _R8_ATLAS_SCHEDULE_PRE(window, visual_style=visual_style, prewarm_only=prewarm_only) if callable(_R8_ATLAS_SCHEDULE_PRE) else None


def _r8_shared_song_fragment_atlas(window):
    if bool(R8_VARIABLE_SIZE_ROW_ONLY) and _r8_variable_size_mode(window):
        _r8_force_row_material_mode(window)
    return _R8_SHARED_ATLAS_PRE(window) if callable(_R8_SHARED_ATLAS_PRE) else None


def _r8_freeze_history_row(window, row):
    if row is None:
        return row
    try:
        freeze = bool(R8_VARIABLE_SIZE_FREEZE_HELD and _r8_variable_size_mode(window))
        row._r8_hold_geometry_frozen = freeze
        row._r8_hold_last_motion_mono = time.monotonic() * 1000.0
        if freeze:
            # Preserve exactly what the reader saw at transition time. Do not snap glyphs back
            # to zero; pin each current shake offset as its target and stop future target rolls.
            for st in list(getattr(row, 'char_shakes', []) or []):
                if isinstance(st, dict):
                    st['target_x'] = float(st.get('x', 0.0) or 0.0)
                    st['target_y'] = float(st.get('y', 0.0) or 0.0)
    except Exception:
        pass
    return row


def _r8_update_hold(row):
    if bool(getattr(row, '_r8_hold_geometry_frozen', False)):
        return False
    now = time.monotonic() * 1000.0
    try:
        owner_ref = getattr(row, '_h62_owner_ref', None)
        owner = owner_ref() if callable(owner_ref) else None
    except Exception:
        owner = None
    if owner is not None:
        # A late GUI frame already caused R6/S1 to quiet speculative work.  Held-row shake is
        # secondary visual motion too, so it should not immediately refill that event-loop budget.
        try:
            if now < float(getattr(owner, '_speculative_render_quiet_until_mono', 0.0) or 0.0):
                return False
        except Exception:
            pass
        try:
            resident = len(list(getattr(owner, 'history_lines', []) or [])) + len(list(getattr(owner, 'fading_lines', []) or []))
        except Exception:
            resident = 0
        if resident >= 2:
            last = float(getattr(row, '_r8_hold_last_motion_mono', 0.0) or 0.0)
            if last > 0.0 and now - last < float(R8_HISTORY_SECONDARY_INTERVAL_MS):
                return False
    row._r8_hold_last_motion_mono = now
    return bool(_R8_HOLD_PRE(row)) if callable(_R8_HOLD_PRE) else False


def _r8_activate_variable_font_stability():
    try:
        if callable(_R8_ATLAS_SCHEDULE_PRE):
            LyricWindow._schedule_song_fragment_atlas = _r8_schedule_song_fragment_atlas
            _r8_schedule_song_fragment_atlas._limbus_layer = getattr(_R8_ATLAS_SCHEDULE_PRE, '_limbus_layer', 'R7-switch-atlas-admission')
            _r8_schedule_song_fragment_atlas._r8_variable_size_row_material = True
        if callable(_R8_SHARED_ATLAS_PRE):
            LyricWindow._shared_song_fragment_atlas = _r8_shared_song_fragment_atlas
            _r8_shared_song_fragment_atlas._limbus_layer = getattr(_R8_SHARED_ATLAS_PRE, '_limbus_layer', 'H61-row-fallback')
            _r8_shared_song_fragment_atlas._r8_variable_size_row_material = True
        if callable(_R8_HOLD_PRE):
            FadingLine.update_hold = _r8_update_hold
            _r8_update_hold._limbus_layer = getattr(_R8_HOLD_PRE, '_limbus_layer', 'H62')
            _r8_update_hold._r8_shared_history_frame_pacing = True
        try:
            write_error_log('R8字号范围稳定与共享帧节流激活', detail=(
                'variable-size=song-atlas-off+row-material | held=birth-geometry-freeze | '
                'fixed-size-history=late-frame-yield+30ms-secondary-cadence | '
                'scope=all-players | current-row/provider/clock/seek/effects=unchanged'))
        except Exception:
            pass
    except Exception as exc:
        try: write_error_log('R8字号范围稳定与共享帧节流激活失败', exc)
        except Exception: pass


_r8_activate_variable_font_stability()


# Visual continuity + frame-budget R9 -----------------------------------------------
# R8 correctly identified wasteful whole-song work in per-line size-range mode, but two
# control choices were unsafe: it reused the song-Atlas *performance fuse* as a disable flag
# (which intentionally routes H11/H35 to plain glyphs and drops glow/vector material), and it
# froze held-row update_hold() completely (which also freezes legitimate mature motion).
# R9 supersedes those controls. Per-line sizes remain stable across same-track precise hot
# upgrades; mature entrance/hold/exit/material effects stay authoritative; variable-size mode
# simply declines speculative whole-song Atlas work and limits glyph prewarm to small visible
# batches. This is renderer policy shared by every player/provider.
R9_VISIBLE_GLYPH_BATCH = 6

_R9_SCHEDULE_PRE = _R8_ATLAS_SCHEDULE_PRE
_R9_SHARED_PRE = _R8_SHARED_ATLAS_PRE
_R9_HOLD_PRE = _R8_HOLD_PRE
_R9_F9_SCHEDULE_PRE = globals().get('_h95f10f9_schedule_plan')


def _r9_clear_r8_false_fuse(window):
    try:
        if str(getattr(window, '_song_fragment_atlas_fuse_reason', '') or '') == 'r8-variable-size-row-only':
            window._song_fragment_atlas_performance_fused = False
            window._song_fragment_atlas_fuse_reason = ''
            window._song_fragment_atlas_fused_style_sig = None
            window._song_fragment_atlas_fuse_until_mono = 0.0
            window._limbus_render_emergency_fused = False
            if str(getattr(window, '_limbus_render_emergency_reason', '') or '') == 'r8-variable-size-row-only':
                window._limbus_render_emergency_reason = ''
            try:
                _limbus_restore_visual_timer_cadence(window)
            except Exception:
                pass
    except Exception:
        pass


def _r9_schedule_song_fragment_atlas(window, visual_style=None, prewarm_only=False):
    if _r8_variable_size_mode(window):
        # This is an admission decision, not a performance failure. Never arm the emergency
        # renderer just because rows intentionally use different point sizes.
        _r9_clear_r8_false_fuse(window)
        try:
            window._song_fragment_atlas_desired_key = None
            window._song_fragment_atlas_pending_key = None
            window._song_fragment_atlas_deferred = False
        except Exception:
            pass
        return 'r9-variable-size-no-song-prewarm'
    _r9_clear_r8_false_fuse(window)
    return _R9_SCHEDULE_PRE(window, visual_style=visual_style, prewarm_only=prewarm_only) if callable(_R9_SCHEDULE_PRE) else None


def _r9_shared_song_fragment_atlas(window):
    _r9_clear_r8_false_fuse(window)
    return _R9_SHARED_PRE(window) if callable(_R9_SHARED_PRE) else None


def _r9_freeze_history_row(window, row):
    # Geometry (x/y/angle/font) is already copied immutably into FadingLine at birth. Do not
    # freeze update_hold: mature shake and the later exit lifecycle must remain alive.
    try:
        if row is not None:
            row._r8_hold_geometry_frozen = False
    except Exception:
        pass
    return row


def _r9_update_hold(row):
    return bool(_R9_HOLD_PRE(row)) if callable(_R9_HOLD_PRE) else False


def _r9_uncached_visible_batch(style_sig, chars, limit=R9_VISIBLE_GLYPH_BATCH):
    out = []
    try:
        with _H95F10F9_PREWARM_LOCK:
            for ch in tuple(chars or ()):
                if not ch or str(ch).isspace():
                    continue
                key = _h95f10f8_sprite_key(style_sig, ch)
                if key is None or key in _HIRES_GLYPH_SPRITE_CACHE or key in _H95F10F9_GLYPH_PENDING:
                    continue
                out.append(ch)
                if len(out) >= int(limit):
                    break
    except Exception:
        out = list(tuple(chars or ())[:max(1, int(limit))])
    return tuple(out)


def _r9_h95f10f9_schedule_plan(window, plan):
    if not _r8_variable_size_mode(window):
        return _R9_F9_SCHEDULE_PRE(window, plan) if callable(_R9_F9_SCHEDULE_PRE) else False
    now = float(plan.get('now', time.monotonic() * 1000.0) or 0.0)
    token = plan.get('token')
    # Variable-size rows are cheap in the normal sprite/vector renderer; prewarm only the
    # glyphs that are actually visible now, in small batches. Do not queue full-row or
    # neighbour/N+1/N+2 jobs that can monopolize the Python worker/GIL for 40-70ms bursts.
    pstyle = plan.get('primary_style'); tstyle = plan.get('translation_style')
    pchars = _r9_uncached_visible_batch(pstyle, plan.get('primary_visible_missing_chars'))
    tchars = _r9_uncached_visible_batch(tstyle, plan.get('translation_visible_missing_chars'))
    _h95f10f9_enqueue_missing(window, pstyle, pchars, 'primary-visible', -2)
    _h95f10f9_enqueue_missing(window, tstyle, tchars, 'translation-visible', -1)
    window._h95f10f9_plan_token = token
    window._h95f10f9_plan_schedule_mono = now
    window._h95f10f9_neighbor_token = token
    return bool(pchars or tchars)


def _r9_activate_visual_continuity_frame_budget():
    try:
        # Supersede R8 wrappers with the mature predecessors plus safe admission policy.
        globals()['_r8_freeze_history_row'] = _r9_freeze_history_row
        if callable(_R9_SCHEDULE_PRE):
            LyricWindow._schedule_song_fragment_atlas = _r9_schedule_song_fragment_atlas
            _r9_schedule_song_fragment_atlas._limbus_layer = 'R9-variable-size-admission'
        if callable(_R9_SHARED_PRE):
            LyricWindow._shared_song_fragment_atlas = _r9_shared_song_fragment_atlas
            _r9_shared_song_fragment_atlas._limbus_layer = getattr(_R9_SHARED_PRE, '_limbus_layer', 'H61')
        if callable(_R9_HOLD_PRE):
            FadingLine.update_hold = _r9_update_hold
            _r9_update_hold._limbus_layer = getattr(_R9_HOLD_PRE, '_limbus_layer', 'H62')
        if callable(_R9_F9_SCHEDULE_PRE):
            globals()['_h95f10f9_schedule_plan'] = _r9_h95f10f9_schedule_plan
        try:
            write_error_log('R9视觉连续性与共享帧预算激活', detail=(
                'variable-size=no-false-performance-fuse+no-song-prewarm | '
                'history=mature-motion+birth-position/font-preserved | '
                f'visible-prewarm=batch<={int(R9_VISIBLE_GLYPH_BATCH)}+no-neighbor | '
                'outline/glow/entrance/exit=restored | scope=all-players'))
        except Exception:
            pass
    except Exception as exc:
        try: write_error_log('R9视觉连续性与共享帧预算激活失败', exc)
        except Exception: pass



_r9_activate_visual_continuity_frame_budget()


# QQ modern search + trusted cover direct-ID R9.2 ----------------------------------
# Field logs show the legacy c.y.qq.com/soso/client_search_cp endpoint returning repeated
# HTTP 500 while the rest of QQ playback/UIA remains healthy.  Keep every mature identity,
# duration and lyric decoder contract, but transparently translate the current desktop
# musicu.fcg search response into the legacy row shape expected by existing callers.  The
# old endpoint remains a transport fallback only when the modern request itself is unavailable.
# Separately, once the lyric pipeline has already supplied a trusted NetEase song ID, cover
# lookup can verify that exact ID instead of re-searching the title and re-entering ambiguity
# backoff.  Both changes are network/metadata routing only; player clock/seek/render are untouched.
_R92_QQ_SEARCH_PRE = globals().get('_r2_qq_search_request')
_R92_NETEASE_ART_PRE = globals().get('_h95f10f4_fetch_netease_art')
_R92_QQ_SEARCH_LOG_MONO = 0.0


class _R92QQSearchCompatResponse:
    def __init__(self, payload):
        self.status_code = 200
        self._payload = payload if isinstance(payload, dict) else {}

    def json(self):
        return self._payload

    def raise_for_status(self):
        return None


def _r9_2_qq_legacy_search_args(url, params=None):
    try:
        if 'client_search_cp' not in str(url or ''):
            return None
        parsed = urllib.parse.urlparse(str(url or ''))
        query = dict(urllib.parse.parse_qsl(parsed.query, keep_blank_values=True))
        if isinstance(params, dict):
            query.update({str(k): v for k, v in params.items()})
        keyword = str(query.get('w') or '').strip()
        if not keyword:
            return None
        try: limit = max(1, min(50, int(query.get('n') or 8)))
        except Exception: limit = 8
        try: page = max(1, int(query.get('p') or 1))
        except Exception: page = 1
        return keyword, limit, page
    except Exception:
        return None


def _r9_2_qq_modern_row(raw):
    if not isinstance(raw, dict):
        return None
    info = raw.get('songInfo') if isinstance(raw.get('songInfo'), dict) else raw
    if not isinstance(info, dict):
        return None
    row = dict(info)
    album = info.get('album') if isinstance(info.get('album'), dict) else {}
    title = str(info.get('title') or info.get('name') or info.get('songname') or '')
    mid = str(info.get('mid') or info.get('songmid') or '')
    song_id = info.get('id') or info.get('songid')
    album_mid = str(album.get('mid') or info.get('albummid') or info.get('albumMID') or '')
    album_name = str(album.get('name') or album.get('title') or info.get('albumname') or '')
    interval = info.get('interval') or 0
    try:
        interval = int(float(interval or 0))
        if interval > 10000:  # tolerate APIs that expose milliseconds instead of seconds
            interval = int(round(interval / 1000.0))
    except Exception:
        interval = 0
    row['songname'] = title
    row['name'] = str(info.get('name') or title)
    row['title'] = title
    row['songmid'] = mid
    row['mid'] = mid
    row['songid'] = song_id
    row['id'] = song_id
    row['interval'] = interval
    row['singer'] = info.get('singer') or info.get('artists') or info.get('ar') or []
    row['album'] = album
    row['albummid'] = album_mid
    row['albumMID'] = album_mid
    row['albumname'] = album_name
    return row


def _r9_2_qq_modern_search(http, keyword, limit, page, headers=None, timeout=8):
    if http is None or not callable(getattr(http, 'post', None)):
        return None
    payload = {
        'music.search.SearchCgiService': {
            'method': 'DoSearchForQQMusicDesktop',
            'module': 'music.search.SearchCgiService',
            'param': {
                'remoteplace': 'txt.yqq.center',
                'search_type': 0,
                'query': str(keyword),
                'page_num': int(page),
                'num_per_page': int(limit),
            },
        },
    }
    req_headers = dict(headers or {})
    req_headers['Referer'] = 'https://y.qq.com/'
    req_headers.setdefault('User-Agent', 'Mozilla/5.0')
    req_headers.setdefault('Content-Type', 'application/json')
    response = http.post(
        'https://u.y.qq.com/cgi-bin/musicu.fcg',
        json=payload, headers=req_headers, timeout=timeout,
    )
    response.raise_for_status()
    obj = response.json() if hasattr(response, 'json') else {}
    block = (obj or {}).get('music.search.SearchCgiService') or (obj or {}).get('req_1') or {}
    if not isinstance(block, dict) or int(block.get('code') or 0) != 0:
        raise RuntimeError('qq-modern-search-code')
    body = ((block.get('data') or {}).get('body') or {}) if isinstance(block.get('data'), dict) else {}
    song_box = body.get('song') if isinstance(body.get('song'), dict) else {}
    raw_rows = song_box.get('list') or []
    rows = []
    for raw in raw_rows:
        row = _r9_2_qq_modern_row(raw)
        if isinstance(row, dict) and (row.get('songmid') or row.get('songid')):
            rows.append(row)
    compat = {'code': 0, 'data': {'song': {'list': rows, 'curnum': len(rows), 'curpage': int(page)}}}
    return _R92QQSearchCompatResponse(compat)


def _r9_2_qq_search_request(http, url, *, params=None, headers=None, timeout=8):
    global _R92_QQ_SEARCH_LOG_MONO
    args = _r9_2_qq_legacy_search_args(url, params)
    if args is None or not callable(_R92_QQ_SEARCH_PRE):
        return _R92_QQ_SEARCH_PRE(http, url, params=params, headers=headers, timeout=timeout) if callable(_R92_QQ_SEARCH_PRE) else http.get(url, params=params, headers=headers, timeout=timeout)
    keyword, limit, page = args
    try:
        modern = _r9_2_qq_modern_search(http, keyword, limit, page, headers=headers, timeout=timeout)
        if modern is not None:
            breaker = globals().get('_R2_QQ_SEARCH_BREAKER')
            try:
                if breaker is not None: breaker.success('qq-search')
            except Exception: pass
            now = time.monotonic()
            if now - float(_R92_QQ_SEARCH_LOG_MONO or 0.0) >= 8.0:
                _R92_QQ_SEARCH_LOG_MONO = now
                try:
                    rows = (((modern.json().get('data') or {}).get('song') or {}).get('list') or [])
                    write_error_log('R9.2 QQ现代搜索接管', detail=f'query={keyword} | rows={len(rows)} | endpoint=musicu.fcg | legacy=standby')
                except Exception: pass
            return modern
    except Exception as exc:
        try:
            now = time.monotonic()
            if now - float(_R92_QQ_SEARCH_LOG_MONO or 0.0) >= 8.0:
                _R92_QQ_SEARCH_LOG_MONO = now
                write_error_log('R9.2 QQ现代搜索暂不可用', exc, detail='fallback=legacy-search-or-provider-breaker')
        except Exception: pass
    return _R92_QQ_SEARCH_PRE(http, url, params=params, headers=headers, timeout=timeout)


def _r9_2_fetch_netease_art(http, song, artist, duration_ms, headers, preferred_id, out_path, album=''):
    sid = str(preferred_id or '').strip()
    if sid and http is not None:
        try:
            detail_headers = dict(headers or {})
            detail_headers.setdefault('User-Agent', 'Mozilla/5.0')
            detail_headers['Referer'] = 'https://music.163.com/'
            response = http.get(
                'https://music.163.com/api/song/detail/',
                params={'id': sid, 'ids': f'[{sid}]'}, headers=detail_headers, timeout=4,
            )
            response.raise_for_status()
            payload = response.json() if hasattr(response, 'json') else {}
            rows = (payload or {}).get('songs') or ((payload or {}).get('result') or {}).get('songs') or []
            row = rows[0] if rows and isinstance(rows[0], dict) else None
            if isinstance(row, dict):
                title = str(row.get('name') or row.get('title') or '')
                actual_artist = _artist_text(row) if '_artist_text' in globals() else ''
                title_ok = bool('_h95f2_title_score' not in globals() or _h95f2_title_score(song, title) >= 0)
                artist_ok = bool(not artist or not actual_artist or '_h95f2_strict_credit_match' not in globals() or _h95f2_strict_credit_match(artist, actual_artist))
                candidate_duration = int(row.get('duration') or row.get('dt') or 0)
                duration_ok = bool('_h95f2_cover_duration_ok' not in globals() or _h95f2_cover_duration_ok(candidate_duration, duration_ms))
                actual_album = _h95f10f4_netease_album(row) if '_h95f10f4_netease_album' in globals() else ''
                album_ok = bool(not album or '_h95f10f4_release_match' not in globals() or _h95f10f4_release_match(album, actual_album))
                if title_ok and artist_ok and duration_ok and album_ok:
                    url = _h16_cover_pic_url(row) if '_h16_cover_pic_url' in globals() else ''
                    if url:
                        img = http.get(url, headers=detail_headers, timeout=4)
                        img.raise_for_status()
                        path = _h88_save_art_bytes(img.content, out_path) if '_h88_save_art_bytes' in globals() else ''
                        if path:
                            try:
                                write_error_log('R9.2封面可信网易云ID直取', detail=(
                                    f'song={song} | song_id={sid} | album={actual_album or "<unknown>"} | '
                                    f'duration={candidate_duration} | search=skip'))
                            except Exception: pass
                            return path, f'netease-id:{sid}'
                else:
                    try:
                        write_error_log('R9.2封面可信ID校验拒绝', detail=(
                            f'song={song} | song_id={sid} | title_ok={int(title_ok)} | artist_ok={int(artist_ok)} | '
                            f'duration_ok={int(duration_ok)} | album_ok={int(album_ok)}'))
                    except Exception: pass
        except Exception as exc:
            try: write_error_log('R9.2封面可信ID直取失败', exc, detail=f'song={song} | song_id={sid} | fallback=release-search')
            except Exception: pass
    return _R92_NETEASE_ART_PRE(http, song, artist, duration_ms, headers, preferred_id, out_path, album) if callable(_R92_NETEASE_ART_PRE) else ('', '')


def _r9_2_activate_network_metadata_routing():
    try:
        if callable(_R92_QQ_SEARCH_PRE):
            globals()['_r2_qq_search_request'] = _r9_2_qq_search_request
        if callable(_R92_NETEASE_ART_PRE):
            globals()['_h95f10f4_fetch_netease_art'] = _r9_2_fetch_netease_art
        try:
            write_error_log('R9.2网络元数据路由激活', detail=(
                'qq-search=musicu-desktop-primary+legacy-standby | '
                'cover=trusted-netease-id-direct+release-search-fallback | '
                'identity/duration/clock/seek/render=unchanged'))
        except Exception: pass
    except Exception as exc:
        try: write_error_log('R9.2网络元数据路由激活失败', exc)
        except Exception: pass


_r9_2_activate_network_metadata_routing()

if __name__ == "__main__":
    if '--packaging-smoke-test' in sys.argv:
        sys.exit(_packaging_smoke_test())
    sys.excepthook = _global_exception_hook
    _s2_install_exception_observers()
    try:
        if not _acquire_single_instance():
            try:
                ctypes.windll.user32.MessageBoxW(
                    None,
                    f"LimbusLyric 已经在运行。\n\n你正在启动：{LIMBUSLYRIC_BUILD_TAG}\n\n请先在系统托盘把旧实例完全退出，再启动当前版本。",
                    f"LimbusLyric · {LIMBUSLYRIC_BUILD_TAG}",
                    0x40
                )
            except Exception:
                pass
            sys.exit(0)
        app = QApplication(sys.argv)
        try:
            write_error_log(
                '日志会话启动',
                detail=(f'path={_ensure_log_session()} | retention=count-only | '
                        f'keep_recent={_LOG_KEEP_RECENT} | max_sessions={_LOG_MAX_SESSIONS} | '
                        f'max_total={int(_LOG_MAX_TOTAL_BYTES/(1024*1024))}MB | '
                        f'max_session={int(_LOG_MAX_SESSION_BYTES/(1024*1024))}MB'),
                force_sync=True,
            )
            _h22_fault_ok = _h22_enable_native_fault_trace()
            write_error_log('H22原生崩溃追踪', detail=f'faulthandler={int(bool(_h22_fault_ok))} | all_threads=1 | sink=session-log', force_sync=True)
            write_error_log('运行环境', detail=_runtime_environment_detail(app), force_sync=True)
            app.aboutToQuit.connect(lambda: _flush_async_log(2.0))
        except Exception:
            pass
        app_icon = _application_icon()
        if not app_icon.isNull():
            app.setWindowIcon(app_icon)

        # Interactive startup is staged so the fade-in really happens before QWidget-heavy
        # panel construction. Autostart is always silent; users can also opt out in Advanced.
        startup_motion = None
        skip_startup_animation = False
        if '--autostart' not in sys.argv:
            try:
                _startup_settings = (load_all_config().get('settings') or {})
                skip_startup_animation = bool(_startup_settings.get('skip_startup_animation', False))
            except Exception:
                skip_startup_animation = False
        # H43: affected packaged Windows builds repeatedly raise 0x8001010d from the
        # transparent StartupMotion QWidget.show() itself. The animation is cosmetic; skip
        # that native-window stage in frozen Windows while leaving normal panel startup intact.
        try:
            if '_h42_windows_frozen' in globals() and _h42_windows_frozen():
                skip_startup_animation = True
                write_error_log('H43 Windows frozen启动动画安全跳过', detail='reason=StartupMotion.show-0x8001010d | panel-startup=direct')
        except Exception:
            pass
        if '--autostart' not in sys.argv and not skip_startup_animation:
            startup_motion = StartupMotion(app_icon)
            startup_motion.show_centered(app.primaryScreen())

        app.setQuitOnLastWindowClosed(False)
        startup_state = {'panel': None}

        def _build_panel_and_continue():
            try:
                panel = ControlPanel(defer_startup_tasks=(startup_motion is not None))
                startup_state['panel'] = panel  # keep the hidden panel alive after this callback
                if not app_icon.isNull():
                    panel.setWindowIcon(app_icon)
                screen = app.primaryScreen().availableGeometry()
                if not getattr(panel, '_geometry_restored', False):
                    x = screen.left() + max(0, (screen.width() - panel.width()) // 2)
                    y = screen.top() + max(0, (screen.height() - panel.height()) // 2)
                    panel.move(x, y)
                autostart_hidden = ('--autostart' in sys.argv and panel.startup_minimized_check.isChecked())

                def _reveal_panel():
                    if autostart_hidden:
                        return
                    panel.setWindowOpacity(1.0)
                    panel.show()
                    if getattr(panel, '_restore_maximized', False):
                        panel.showMaximized()
                    panel.raise_(); panel.activateWindow()
                    try:
                        panel._release_deferred_startup_tasks()
                    except Exception:
                        pass

                if startup_motion is not None and not autostart_hidden:
                    target_geometry = QRect(screen) if getattr(panel, '_restore_maximized', False) else QRect(panel.geometry())
                    startup_motion.finish(panel=panel, target_geometry=target_geometry, callback=_reveal_panel)
                else:
                    _reveal_panel()
            except Exception as exc:
                write_error_log("程序启动失败", exc)
                print("FATAL STARTUP ERROR:", file=sys.stderr)
                traceback.print_exc()
                app.exit(1)

        # Let the paint-only 0->1 card fade fully finish before QWidget-heavy panel construction.
        # Any construction/show/layout cost therefore lands on a stationary solid card, never on
        # the fade or the small->large morph itself.
        QTimer.singleShot(720 if startup_motion is not None else 0, _build_panel_and_continue)
        sys.exit(app.exec_())
    except Exception as exc:
        write_error_log("程序启动失败", exc)
        print("FATAL STARTUP ERROR:", file=sys.stderr)
        traceback.print_exc()
        sys.exit(1)



